pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold a
    // typical future item (1..100 unknown distribution) are toxic.
    let dead_zone = 40.0;
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < dead_zone {
            // unusable sliver: quadratic blow-up as it shrinks
            score += (dead_zone - pr) * (dead_zone - pr) * 0.35;
        } else {
            // larger residuals are genuinely reusable: reward them
            score -= (pr - dead_zone) * 0.25;
        }
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as f64) >= nx * 0.8 {
            score += 8.0; // next item likely strands this residual
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(25.0);
    } else {
        // New-bin candidate: only attractive when existing bins fit badly.
        // Base cost of opening a bin, discounted by mean residual waste.
        score += 20.0 + mean_residual * 0.3 - 10.0 * progress;
    }

    // Mild preference for bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer minimal post-residual, with non-linear tightening late in stream.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for awkward residuals (near half-capacity dead space).
    let awkward = (pr - 0.5).abs();
    score += 20.0 * awkward * awkward * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual small relative to item).
    score -= 15.0 * fit * fit * (1.0 - pr);

    // Lookahead coupling: reward if next item can use the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = (post - nx) / cap;
            score -= 12.0 * (1.0 - waste) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr);
    } else if fitting_bins_count > 1 {
        // Mild reward for spreading load when many bins fit.
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize unless open bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            ((cap - mean_residual) / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = cap * (1.1 - 0.35 * pressure) + 10.0 * (1.0 - progress);
        // If only this new bin can take the item, make it attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual matches the fleet mean.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify with ratio.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot plausibly fit future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 14.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins with smaller residual (best-fit flavor).
        score += 0.35 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, consolidate tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let spread = mean_residual - post_residual as f64;
    score += 0.25 * spread * (open_bins_count as f64).ln().max(0.0);

    // Brand-new bin candidate: only attractive when it enables a near-perfect
    // split with the lookahead item, or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && (bin_capacity as f64 - pair).abs() <= 5.0 {
            score -= 45.0;
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (exact fit).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to be useful later
    // (typical items are >= 10, so anything below ~10 is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 6.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gap: partially penalize
        score += (25.0 - post) * 1.5;
    }

    // Reward tight fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post gap,
    // strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= (post - nxt).min(10.0) * 2.0;
        } else {
            // Next item cannot use this residual: mild penalty for blocking
            score += (nxt - post).min(20.0) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; prefer
    // filling existing bins when the fit is decent.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual alignment: prefer bins whose residual is below average
    // (closer to full), leaving larger residuals in emptier bins.
    score += (mean_residual - post).max(-30.0).min(30.0) * 0.5;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (post residual here is large).
    if bin_residual == bin_capacity {
        // Slightly worse than a perfect fit, better than a bad fit.
        score = cap * 0.45 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover = lower score = favored)
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on small post-residual (dead space),
    // weighted by stream progress.
    let dead_penalty = (1.0 - norm_pr).powi(2) * (20.0 + 60.0 * progress);
    score += dead_penalty;

    // Smooth reward for post_residual close to next item size (lookahead fit),
    // gaussian-like coupling.
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let sigma = 15.0 + 25.0 * (1.0 - progress);
        let fit_bonus = -30.0 * (-(diff * diff) / (2.0 * sigma * sigma)).exp();
        score += fit_bonus;
    }

    // Last-chance bin: strongly favor using it when it's the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Slight preference for placing into bins with lower-than-mean residual
    // (consolidate large gaps), scaled by number of open bins.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * mean_gap * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild early-stream preference for opening fresh bins (keeps large residuals
    // available later); decays smoothly with progress.
    if bin_residual == bin_capacity {
        score -= (1.0 - progress).powi(2) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1..100 unknown, assume >=10 typical) are "dead".
    // Penalize heavily when post_residual falls into unusable gap band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver: nearly useless
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger residuals are reusable: reward proportionally
        score -= (post_residual as f64 - 35.0) * 0.4;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (favor bins with small residuals to close them out); when few bins,
    // opening new bins is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 1.5;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a big usable residual, or no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mid-range so good fits in open bins win.
        score = 45.0 + (100 - item_size.min(100)) as f64 * 0.3;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // packing next item here too is attractive
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits elsewhere: new bin is fine
        }
    }

    // Stream progression: early on, slightly favor keeping residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward (small dead space relative to capacity)
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tight * tight;
    }

    // 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // the smaller the leftover after a hypothetical next placement, the better
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 40.0 * (miss / bin_capacity as f64);
        }
    }

    // Relative-to-mean residual shaping: prefer bins with residual below mean (denser bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 30.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Early in the stream, be more willing to open/spread bins; later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 + 50.0 * (1.0 - poor_fit) + progress * 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // room for the next item in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits (small post_residual), strongest when leftover is in a "usable" class.
    let tight_fit = (post_residual <= eighth) as f64;
    score -= 25.0 * tight_fit;

    // Penalize dead space: leftovers that no typical item (>= next_item_size) can use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        }
        // Reward leftovers that exactly or nearly fit the next item (harmonic pairing).
        if post_residual >= next_item_size {
            let pair_gap = post_residual - next_item_size;
            if pair_gap <= eighth {
                score -= 14.0;
            }
        }
        // Modulo class: leftover divisible into halves/quarters is reusable.
        if post_residual % quarter == 0 && post_residual > 0 {
            score -= 6.0;
        } else if post_residual % (eighth.max(1)) == 0 && post_residual > 0 {
            score -= 3.0;
        }
    } else {
        // Last item: just minimize waste aggressively.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 22.0 + 10.0 * progress;
        // If no open bin fits well, allow new bin: reduce penalty when mean residual is low.
        new_bin_penalty -= 15.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        let _ = crowd;
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins (small bin_residual).
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * -0.0;

    // Spread-awareness: prefer bins below mean residual (relatively full).
    score += 0.08 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap that can still host typical small items: mild reward.
        score -= 5.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage proliferation,
    // but only when the fit is not tight.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    score += pressure * (1.0 - fill_ratio);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate handling: an empty bin is only attractive when
    // open bins have poor fits (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let mean_tightness = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Prefer new bin when existing bins are crowded and many are open.
        score = 55.0 + 20.0 * (1.0 - mean_tightness) - 1.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 25.0; // don't open new bin if this item has few alternatives... wait, fitting counts exclude new bin; keep neutral
            score -= 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space, more so when it cannot fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * post_residual as f64;
        }
    }

    // Lookahead matching: reward when post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness;

    // Penalize wasting a large residual on a small item.
    let waste_ratio = item_size as f64 / bin_residual as f64;
    score += 40.0 * (1.0 - waste_ratio);

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = mean_residual < item_size as f64 * 1.2;
        score += if big_item > 0.7 || poor_fit { -150.0 } else { 250.0 };
    } else {
        // Prefer bins whose residual deviates favorably from the mean.
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: encourage keeping bins compact for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item * 10.0 {
        score += 60.0; // unusable sliver
    } else if pr > 0.0 && pr < min_item * 25.0 {
        score += 25.0; // hard-to-fill gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n && pr - n < 10.0 {
            score -= 30.0; // next item fits snugly
        } else if pr >= n {
            score -= 10.0;
        } else if pr > 0.0 {
            score += 15.0; // blocks the lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure from number of open bins: encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 - 25.0 * progress; // new bin less attractive later on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify by capacity fraction.
    // Small residuals (< 20% of capacity) are near-dead space; penalize.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score += 30.0 * (0.2 - frac);
    }

    // Harmonic classes via integer division thresholds on post_residual.
    // Residuals that are multiples of common item-size classes are reusable.
    let class = post_residual / 10; // harmonic class index (item sizes 1..100)
    if class >= 1 && post_residual % 10 == 0 {
        score -= 8.0; // round residual = reusable for round items
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if lookahead would then fit almost exactly.
            let pr2 = post_residual - next_item_size;
            if pr2 <= 5 {
                score -= 15.0;
            }
        } else {
            // Lookahead won't fit here; slight penalty unless post_residual tiny.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (better-packed bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early in stream, be slightly more exploratory toward new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score = 40.0 - 60.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // item can't fit anywhere else anyway handled elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward
        if match_gap == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the residual: reward proportional to tightness
            score -= 20.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted potential
            score += 5.0 + 0.1 * match_gap;
        }
    }

    // Penalize residuals too small to hold any plausible item (dead space)
    if post_residual < 10 {
        score += 15.0;
    }

    // Prefer tighter fits relative to mean residual of open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 {
            ((post_residual as i64 - next_item_size as i64).abs() as f64) / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted if open bins are scarce or fit is bad
        score += 30.0 - 10.0 * poor_fit_penalty - 2.0 * open_bins_count as f64;
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1..=3)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0 * (4.0 - post_residual as f64);
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits relative to item size.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Penalize leaving a gap just below the next item's need (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        let miss = (next_item_size as u32 - post_residual) as f64;
        score += 8.0 * miss;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones.
    score += 0.35 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 3.0 * fitting_bins_count as f64 };
        score += pressure;
        // A new bin is fine if the item is large and would leave little waste anywhere.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

