    if bin_residual == bin_capacity {
        score = 55.0 + progress * 10.0;
        if post_residual >= 90 {
            score -= 20.0; // tiny item into fresh bin is fine
        }
    }

    // Penalize very large post_residual mildly (wasted capacity) unless new bin
    if bin_residual < bin_capacity && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the smallest item size (1)
    // are pure waste; residuals too small for typical items are near-waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty scales with how large the unusable gap is relative to item.
    if post_residual < item_size as u32 {
        score += 0.5 * (item_size - post_residual as u32) as f64;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate implicitly via residual, but add pressure).
    score += 0.15 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the remaining space, slight penalty for stranding.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Progress-based mild tightening: later in stream, be greedier about fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty, harsher the smaller the dead gap relative to capacity.
        let gap = post_residual as f64;
        score += (1.0 + 40.0 / (gap + 5.0)) * (next_item_size as f64 - gap);
    } else if next_item_size > 0 {
        // Reward keeping the bin usable for the lookahead item.
        score -= 8.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bonus: avoid forcing a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins already tighter than average (fill fuller bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight early-stream conservatism: keep flexibility while many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

