    // the item grid and are easier to fill exactly later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (perfect pair completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
            // Integer-division threshold: post_residual / next_item_size >= 2
            // means room for two more items later; mildly favorable.
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to
            // how much dead space would be stranded.
            score += 6.0 * (1.0 - cap_frac);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or all open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = item_size as f64 * 0.5 - 25.0 * crowding - 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0; // large items deserve fresh bins
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score -= 0.5 * (open_bins_count.min(50) as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
