    // Early: waste is cheap-ish, keep flexibility; Late: waste is costly.
    let progress_coupling = 2.0 * progress * (1.0 - progress); // peaks mid-stream
    score += rn * rn * (1.0 + 3.0 * progress) - progress_coupling * rn * (mean_residual / cap);

