pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: modulo classes on capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
    let pr_class = pr % quarter;
    let pr_div = pr / quarter;

    // Reward residuals that land in "usable" harmonic classes (multiples of 1/8 capacity).
    if pr % eighth == 0 && pr > 0 {
        score -= 12.0;
    }
    // Penalize dead space in the awkward 1..quarter band (too small for typical items).
    if pr > 0 && pr < eighth {
        score += 18.0;
    }
    if pr > eighth && pr < quarter {
        score += 7.0;
    }

    // Coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how snugly the next item nests.
            let snug = (pr - next_item_size) as f64;
            score -= 10.0 + 20.0 * (1.0 - snug / bin_capacity as f64);
            // Extra reward if next item also lands on a harmonic class boundary.
            if (pr - next_item_size) % eighth == 0 {
