    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: prefer the tightest, add mild pressure scaled by count.
    if fitting_bins_count > 1 {
        score += 0.8 * (fitting_bins_count as f64 - 1.0);
    }

