    }
    // Reward residuals in harmonic sweet spots (exact multiples of quarter capacity)
    if class == 0 && post > 0 {
        score -= 12.0;
    }
    // Small residues that can pair with tiny items are fine
    if post >= 1 && post <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post {
        score -= 10.0 + 0.3 * (post - next_item_size) as f64;
    } else if next_item_size > post {
        // next item won't fit here; penalize wasted near-fit space
        score += 0.1 * (next_item_size - post) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64);
        // If there are few fitting bins and mean residual is large, prefer reusing
        if fitting_bins_count >= 1 && mean_residual > item_size as f64 + 15.0 {
            score += 40.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference for fuller bins as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * (post as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=min item) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item (k=2) if it would otherwise fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open,
    // but allow it when few bins are open (early stream) or this is the last fitting bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, increasingly penalized as stream progresses.
        score += 25.0 + 45.0 * progress + open_bins_count as f64 * 3.0;
        // But if no open bin fits well, new bin becomes viable: handled via relative comparison.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Favor filling already-open bins, more so with many open bins.
        score -= open_bins_count.min(10) as f64 * 1.5;
        // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins with residuals close to the item (tight fit) relative to mean residual.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 20.0;
        // Mild preference for bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // heavily reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a new residual: penalize leftover drift.
            let next_left = post_residual - next_item_size;
            score += next_left as f64 * 0.3;
            if next_left <= 5 {
                score -= 8.0; // near-chain bonus
            }
        } else {
            // Next item won't fit here; residual becomes dead space for step 2.
            // Penalize more when the residual is small-but-unusable.
            if post_residual < 10 {
                score += 12.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    }

    // Compare residual against mean residual across open bins:
    // leaving less than average is good (tight packing), more is wasteful.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred, scaled by how many bins fit.
        let fit_pressure = if fitting_bins_count == 0 {
            -100.0
        } else if fitting_bins_count == 1 {
            30.0
        } else {
            15.0 * fitting_bins_count as f64
        };
        score += fit_pressure;
        // Early in stream, allow new bins more freely; later, discourage.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize small dead space that nothing can use (items >= 1).
    if post_residual < 1 {
        score -= 60.0; // perfect fit bonus
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit
    } else {
        // Dead space penalty grows if residual is too small for typical items.
        score += (10.0 - post_residual as f64).max(0.0) * 0.5;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by how badly.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // More competing bins: slight penalty to prefer concentrating load.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling.
    let fill_pressure = mean_residual / bin_capacity as f64;
    let openness = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= fill_pressure * openness * 15.0;

    // Time horizon: early in stream, be more exploratory (favor tight fits less,
    // keep bins flexible); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * fill_pressure;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (waste minimization).
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= waste_ratio * 8.0;

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if fitting_bins_count == 1 { 0.35 }
            else { 0.0 };
        score = score * 0.5 + (1.0 - desperation) * 120.0 - desperation * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit = post_residual <= bin_residual && item_size <= bin_residual;

    // Base: quadratic in post_residual (dead space penalty grows superlinearly)
    let mut score = pr * pr / (bin_capacity as f64);

    // Smooth stream-progress coupling: late in the stream, tolerate larger residuals less
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth bump peaked when post_residual is small
    let tightness = 1.0 - pr / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Lookahead: reward leaving space for the next item (smooth interaction)
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = (pr - ni).abs();
        score += 0.5 * gap * gap / (bin_capacity as f64);
        score -= 10.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
    }

    // Last-chance bin: strongly favor using it (smooth, count-based)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean residual context: bins far below mean residual are less attractive late
    score += 0.05 * (mean_residual - pr).abs();

    // Slight preference for consolidating into fewer bins
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: dead-space classes modulo 10.
    // Residuals that are "useless" (below typical small item size) get penalized hard.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr < 10 {
        score += 25.0; // unusable dead space (< min item size)
    } else if pr < 20 {
        score += 8.0;  // only fits tiny items
    } else {
        // modular harmonic classes: residuals divisible by 10 pair well with
        // items in the 10..80 decade structure
        let class = pr % 10;
        score += class as f64 * 0.7; // prefer round residuals (10,20,30...)
        if pr % 20 == 0 {
            score -= 5.0; // extra bonus: pairs with medium items
        }
        if pr % 50 == 0 {
            score -= 4.0; // half-capacity class is versatile
        }
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact or near-exact pairing with next item
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 35.0;
            } else if slack < 10 {
                score -= 15.0;
            } else {
                score -= (slack as f64).min(30.0) * 0.3;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 + (next_item_size as f64 - post_residual as f64).min(40.0) * 0.4;
        }
    }

    // Integer-division threshold on item_size relative to capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size > half {
        // big items: better in a fresh-ish bin, penalize stuffing into nearly full bins
        if post_residual < quarter {
            score += 10.0;
        }
    } else if item_size <= quarter {
        // small items: fine anywhere, mild bonus for filling gaps
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only
    // when open bins look bad; make it attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = 55.0
            - (mean_residual / bin_capacity as f64) * 15.0
            + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // fresh bin guarantees room for lookahead
        }
    }

    // Stream progression: early on, be more willing to open bins (reserve flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    } else {
        score += progress * 2.0; // later: consolidate into existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    // Anything below ~12 is nearly unusable; penalize super-linearly.
    if post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Moderately risky gap: mild penalty.
        score += 0.35 * (25.0 - post_residual as f64);
    }

    // Reward tight fits: post_residual close to zero relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer consolidating into existing bins when the pool is large.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current fit is poor. Make the empty-bin candidate moderately attractive
    // but not dominant.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * open_bins_count as f64;
        // If stream is early, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is huge, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            // Next item fits but leaves dead space again: dampen reward.
            score -= 10.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for consuming
            // a bin that could have stayed flexible.
            score += 3.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below average,
    // it's already fragmented; prefer bins with more room for tight packing.
    let res = bin_residual as f64;
    if res < mean_residual - 15.0 {
        score += 5.0;
    } else if res > mean_residual + 15.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match — next item exactly fills this bin afterward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Reward: next item fits comfortably but not exactly (soft lookahead bonus).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * post_residual as f64;
    }
    // Penalize dead space that the next item cannot use.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64 - next_item_size as f64;
        score += waste.clamp(0.0, 100.0) * 0.8;
    }

    // Reward exact closure of the bin now (zero post-residual is ideal).
    if post_residual == 0 {
        score -= 300.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the item is large and a fresh bin gives a clean fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let clean_fit = (bin_capacity - item_size) as f64;
        score += 40.0 + open_bins_count as f64 * 5.0
            - (clean_fit / 4.0)
            - progress * 20.0;
        // If next item also fits the fresh bin's residual, soften the penalty.
        if next_item_size > 0 && next_item_size <= clean_fit as u32 {
            score -= 30.0;
        }
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large leftover space.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: penalize if post-residual can't hold the next item
    // (dead space relative to lookahead), reward if it can exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // leftover below next item size: waste unless tiny
            score += 0.35 * (next_item_size - post_residual) as f64;
            if post_residual > 0 && post_residual < 15 {
                score -= 10.0; // small dead space is acceptable
            }
        }
    }

    // New-bin candidate handling: only open a new bin when all fits are poor
    // (large post_residual in every fitting bin) or when bin pressure is low.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        let best_possible = post_residual as f64; // = 0 for empty bin
        let _ = best_possible;
        // Cost of a fresh bin decreases over the stream (amortization)
        let horizon = (total_items.saturating_sub(step_index)) as f64;
        score += 30.0 + 55.0 * pressure - 12.0 * (1.0 - horizon / (total_items.max(1) as f64 + 1.0));
        // If next item is large and this bin is fresh, mild discount
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    // Prefer filling bins with small mean residual (consolidate).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Mild preference for bins with moderate residual when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Progress-coupled tightening: later in the stream, demand tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: post_residual value decays with stream progress
    let decay = 1.0 - progress * progress;
    score -= 30.0 * norm_pr * decay;

    // Penalize dead space quadratically, stronger late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic term
    score -= 25.0 * (1.0 - norm_pr).powi(3) * norm_item;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = norm_next * (1.0 - (norm_pr - norm_next));
        score -= 35.0 * chain;
    } else if next_item_size > 0 {
        score += 10.0 * norm_next * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild pressure toward consolidating into few bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_item * decay;

    // Mean residual context: prefer bins below mean residual (tighter bins)
    let mr = mean_residual / cap;
    score += 15.0 * (mr - norm_pr) * (0.5 + progress);

    // New-bin candidate: penalize slightly unless residual is very small (poor fit)
    if bin_residual == bin_capacity {
        let poor_fit_bonus = (norm_item - 0.5).abs();
        score += 8.0 - 20.0 * poor_fit_bonus * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual small (<= 10) -> strong reward.
    // Class 2: post_residual in a "dead zone" (unusable for typical items) -> penalty.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0 - (post_residual as f64) * 2.0;
    }

    // Integer-division thresholds: leftover divisible by common small item sizes
    // is more likely reusable later.
    let reusable = post_residual >= 10
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0);
    if reusable {
        score -= 8.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Dead space: unusable for minimum item size.
        score += 12.0;
    }

    // Fractional fill ratio coupling: prefer bins that end up "harmonically full"
    // (fill ratio near multiples of 1/4 of capacity).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    let quarter = (fill * 4.0).round() / 4.0;
    score -= (1.0 - (fill - quarter).abs() * 8.0) * 4.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = next_item_size - post_residual;
            score += (over % 10) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin would
    // be left with dead space and the new bin is genuinely useful.
    if bin_residual == bin_capacity {
        // Opening a new bin starts with full residual 100 -> base score 100.
        // Reward slightly if open bins are crowded, penalize if plenty of slack.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 + 20.0 * progress;
        if mean_residual > (item_size as f64) * 1.5 {
            score += 25.0; // existing bins already have plenty of room
        }
    }

    // Mild consolidation pressure: fewer open bins is better; tie-break toward
    // bins whose residual is below the mean (filling the emptier-feeling bins).
    score += (open_bins_count as f64) * 0.05;
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste. Penalize them super-linearly.
    let min_item = 1.0f64;
    let dead = if post_residual > 0 && (post_residual as f64) < min_item * 10.0 {
        // unusable sliver
        (11.0 - post_residual as f64).powi(2) * 6.0
    } else {
        0.0
    };
    score += dead;

    // Reward near-perfect fits (small but usable residual is fine).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins early on,
    // but relax pressure as the stream progresses (packing tail needs slack).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - 1.0 * progress);

    // Mean-residual coupling: if open bins are already slack-heavy, prefer
    // consolidating into tight bins (low residual) rather than adding slack.
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item would be blocked by a bad choice, penalize.
    if next_item_size > post_residual && next_item_size <= bin_residual - item_size.min(bin_residual) {
        // no extra penalty; residual already reflects it
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = bin_residual as f64 - item_size as f64; // = post_residual for new bin
        let decent_fit_exists = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual) >= item_size as f64 * 0.95;
        if decent_fit_exists {
            score += 30.0; // keep using existing bins when fits exist
        } else if item_size >= 60 {
            score -= 10.0; // large items deserve a fresh bin
        } else {
            score += fit_quality * 0.3; // mild preference to consolidate
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.9 + open_bins_count as f64;
    }

    // Core: reward tight fits (small post_residual).
    score = post_residual as f64;

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 40.0 - leftover * 0.8; // chainable, penalize leftover after chain
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Reward when post_residual is small relative to mean residual (tighter than average).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize large dead space that likely becomes unusable (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 {
        score += post_residual as f64 * 0.1;
    }

    // Early in the stream, be slightly more willing to open bins (spread items);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Mild penalty when many bins are already open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically; tiny residuals are wasted capacity.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 12.0 / pr.sqrt();
    } else {
        score -= 40.0; // perfect fit is ideal
    }

    // Tightness ratio: reward filling the bin well.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * fill * fill;

    // Lookahead: if the next item fits in the post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
            // extra bonus if next item would nearly fill leftover
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward leftover
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we
    // prefer good existing fits, but reward opening a new bin when existing
    // bins are fragmented (high mean residual spread / many open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0
            - 0.05 * open_bins_count as f64
            - 0.04 * mean_residual
            - 10.0 * progress;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0; // open fresh bin when existing residuals can't host the future
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // placing into a smaller-than-average residual conserves large holes.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 15.0 * dev;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fraction of bin filled after placement
    let tight = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.6 * fill * fill);

    // Stream-progress coupling: as stream advances, weight tight fits more strongly
    score -= (pr * fill) * (0.35 * progress * (1.0 - progress) * 4.0 + 0.15 * progress);

    // Polynomial interaction between fill and tightness
    score -= 8.0 * fill * fill * fill * (tight + 0.5);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let gap = pr - mean_residual;
    score += 0.05 * gap * gap / cap;

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        score -= 6.0 * (-((diff / cap).powi(2) * 8.0)).exp() * (0.5 + progress);
    } else {
        // last item: strongly prefer tightest fit
        score -= 12.0 * fill;
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 5.0 * fill * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * (open_bins_count as f64) * (1.0 - fill) * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when no open bin offers a genuinely tight fit
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction bands.
    // Leftovers that are "harmonic" (clean fractions of capacity: 0, 25, 50, 75) are
    // more reusable for typical items, so reward them; odd/prime-like leftovers penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill, ideal
    } else {
        // fractional position of the leftover
        let frac = pr as f64 / cap;
        // reward leftovers that align with quarter-capacity grid
        let quarter = (pr % (bin_capacity / 4)) as f64;
        let grid_bonus = if quarter == 0.0 { 18.0 } else { -quarter * 0.35 };
        score += grid_bonus;

        // mid-size leftovers (25..60) are the most useful for future items (items 10..80
        // or 1..100): reward keeping residuals in the sweet spot
        if pr >= 25 && pr <= 60 {
            score -= 14.0;
        } else if pr < 25 {
            // tiny dead space, mildly penalized beyond its raw size
            score += (25 - pr) as f64 * 0.4;
        } else {
            // large leftover: good, but only if it can host a whole future item class
            score -= 6.0;
        }

        // integer-division harmonic class: leftover divisible by common item sizes (10,20,25,50)
        if pr % 10 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does next_item_size fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // exact future fill
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic match quality: reward small slack, penalize awkward remainder
            score -= (30.0 - slack * 0.5).max(2.0);
            if (pr % next_item_size.max(1)) == 0 { score -= 8.0; }
        } else {
            // next item cannot fit here regardless; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    // (large post_residual waste) or when open bins are already fragmented.
    if bin_residual == bin_capacity {
        // baseline new-bin score: emulate a mediocre placement
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // many open bins with high mean residual -> fragmentation, prefer new bin less
        if mean_residual > cap * 0.4 && open_bins_count > 2 {
            score += 10.0;
        }
        // if many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < next_item_size) are "dead". Penalize them super-linearly.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < dead_threshold.max(1) {
        score += 40.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac * fill_frac;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64).sqrt() * (2.5 - 4.0 * fill_frac).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin would give a large usable residual while open bins
    // would leave small dead gaps). Penalize opening bins mildly to avoid proliferation.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 12.0 + 0.15 * open_bins_count as f64 - 0.2 * spread;
        // Late in the stream, opening new bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // unless it creates dead space.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 18.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly placement: reward, scaled by tightness of the chain fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize unusable dead space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 40.0; // tiny useless sliver
            } else {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.0;
    }

    // Compare against mean residual of open bins: bins below mean residual
    // (tighter bins) are more valuable — penalize wasting them.
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score += 0.5 * (res_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res_f);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        let mut penalty = 120.0;
        if fitting_bins_count == 1 {
            // only one open bin fits; keep some chance to open new bin if fit is terrible
            let fit_quality = (bin_residual - item_size) as f64;
            if fit_quality > 0.0 && fit_quality < 10.0 && next_item_size > post_residual {
                penalty -= 80.0; // allow opening a fresh bin to preserve next item
            }
        }
        if open_bins_count == 0 {
            penalty = 0.0; // nothing else available
        }
        score += penalty;
    }

    // Late-stream consolidation: favor filling existing bins more as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - res_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but weight tightness non-linearly.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits into post_residual (chained fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (next_item_size as f64) * 0.3;
        } else {
            // Slight penalty if the next item can't follow into this bin.
            score += 8.0;
        }
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor and there is meaningful remaining stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: base score is its full residual; discourage early opening
        // when decent fits exist, encourage when bins are crowded/poor fits.
        score += 25.0 * (1.0 - progress);
        score += (open_bins_count as f64) * 2.0;
        // If the item fits well in some open bin (fitting_bins_count > 0 and
        // tightness would be high), the new-bin call should lose.
        if fitting_bins_count > 0 && post_residual as f64 <= bin_capacity as f64 * 0.5 {
            score += 40.0;
        }
        // Late in the stream, opening fresh bins wastes capacity.
        if progress > 0.85 {
            score += 30.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce dispersion (bring residual toward mean) less aggressively;
    // when mean residual is low, pack tightly into existing bins.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.15;
        // Crowded bins: reward using bins when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Early stream: keep bins balanced (avoid extreme fragmentation).
    if progress < 0.3 {
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial base: reward small post_residual, with cubic shaping
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr - 0.5 * norm_pr * norm_pr) * 100.0;

    // Non-linear coupling with stream progress: early on tolerate slack, late be strict
    score *= 1.0 + 0.8 * (1.0 - progress) * norm_pr - 0.4 * progress * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: penalize if post_residual cannot fit next item but residual could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && bin_residual as f64 >= nxt {
            score += 25.0 * (1.0 - pr / nxt);
        }
        // Reward smooth continuation: post_residual close to next item size
        let fit_closeness = 1.0 - ((pr - nxt).abs() / cap);
        score -= 10.0 * fit_closeness * fit_closeness;
    }

    // Mean residual coupling: penalize bins far above mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Slight preference to fill existing bins when many are open
    score += (open_bins_count as f64).sqrt() * norm_pr * 5.0;

    // New-bin candidate: penalize mildly so it's chosen only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable classes" via integer division on the item size range.
    // Leftovers that can host another item (>= 10) are far more valuable
    // than dead space below 10.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space penalty: this leftover can never host any item.
            score += 40.0;
        } else {
            // Usable leftover: reward proportionally to how many size
            // classes (10..80) can still fit into it.
            let classes = ((post_residual - 10) / 10 + 1).min(8) as f64;
            score -= 3.0 * classes;
        }
    } else {
        // Perfect (zero-residual) closure is ideal.
        score -= 60.0;
    }

    // Harmonic match with lookahead: if next item fits exactly into the
    // post residual, strongly favor this bin (pairing trick).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            // Next item closes this bin almost perfectly.
            score -= 45.0;
        } else {
            // Next item fits with some slack; scale by class match.
            let class_gap = gap / 10;
            score -= 12.0 - class_gap as f64;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: slight penalty,
        // worse when leftover is large (wasted capacity ahead).
        if post_residual >= 10 {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins: prefer tighter packing
    // when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Slight preference for bins already below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Early in the stream, allow new bins more freely; late in the stream,
    // squeeze into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity and no good pairing exists. An empty new bin
    // gets post_residual == bin_capacity, so its base score is high;
    // adjust it into a competitive range based on item size class.
    if bin_residual == bin_capacity {
        let size_class = item_size / 10;
        // Large items (class 6..8) justify fresh bins; small items should
        // stuff into existing leftovers.
        if size_class >= 6 {
            score -= 30.0 + (size_class as f64 - 5.0) * 8.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // steep penalty for unusable slivers
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward fits that leave room for typical next items (coupling with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item cannot follow here -> dead space likely
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave big awkward gap
    // or no open bin fits well; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual < 20 {
            score -= 20.0; // opening fresh bin fine if item is large
        }
    }

    // Prefer bins with residual close to item (tight packing) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Late in stream, tighten packing further.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    // -> this bin will be exactly filled by the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead: next item leaves very small dead space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    }
    // Next item does NOT fit after this placement: penalize small leftovers
    // (dead space) more strongly as post_residual shrinks.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize large post_residual relative to mean residual across open bins
    // (waste of capacity vs. the fleet average).
    score += 2.0 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Discourage opening new bins when existing bins give an acceptable fit:
    // new-bin candidate (bin_residual == bin_capacity) gets a penalty unless
    // the item is huge relative to residual elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Mild early-stream bias to consolidate items while bins are few.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    score *= 1.0 + 2.0 * (-post_residual as f64 / (bin_capacity as f64 * 0.25)).exp();

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only bin that fits the item -> strong preference.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Early in the stream: keep bins balanced to preserve flexibility.
    // Late in the stream: consolidate aggressively.
    let consolidation = t * t;
    score += consolidation * (bin_residual as f64 * 0.4);
    score -= (1.0 - consolidation) * (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Penalize opening new bins when open bins exist that fit, more so late.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0 + 60.0 * consolidation + open_bins_count as f64 * 2.0;
        // But allow new bin if the item is huge relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 45.0;
    }

    // Mild penalty per open bin to discourage fragmentation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight packing (low post_residual), normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly -> stronger squeeze.
    let coupling = 0.35 * (post / cap).powi(2) * (0.5 + progress);
    score += coupling;

    // Smooth penalty for awkward residuals that few future items can use.
    let awkward = (1.0 - (post / cap * 2.0 - 1.0).powi(2)).max(0.0); // peaks mid-range
    score += 0.15 * awkward * (1.0 - progress);

    // Reward near-exact fits with a smooth quadratic bonus.
    let exact = 1.0 - (post / cap).powi(2);
    score -= 0.30 * exact;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 0.25 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 0.10 * progress;
    }

    // New-bin candidate: neutral-ish baseline; encourage it only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score = 0.55 + 0.4 * frag + 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall in?
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0.0 .. 1.0

    // Integer-division thresholds: dead-space classes
    // post_residual in [0,10): excellent fill (near-perfect packing)
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 20.0;
    } else if post_residual < 30 {
        score -= 8.0;
    } else if post_residual > 80 {
        // bin left mostly empty -> bad, new bin would be better
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by small
    // harmonics (5, 10, 20) are reusable by typical item sizes.
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Non-reusable odd residuals get penalized
    if post_residual % 2 == 1 && post_residual < 10 {
        score += 5.0;
    }

    // Next-item lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here -> strong reward, scaled by tightness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.1;
        } else {
            // residual too small for next item: penalize proportionally to waste
            let waste_frac = frac;
            score += waste_frac * 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins when they fit well
        score = cap_f - 25.0;
        // open bins are nearly full on average -> new bin is fine
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        // many bins open but little average space -> new bin justified
        if open_bins_count > 4 && mean_residual < 15.0 {
            score -= 15.0;
        }
        // early in stream, keep bin count low
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference for tight fits overall
    score += (item_size as f64 / cap_f) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver -> strong penalty
    }
    // Mid-size dead space that few future items can fill (11..=20)
    if post_residual >= 11 && post_residual <= 20 {
        score += 18.0;
    }
    // Perfect or near-perfect fill: heavily reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to bin fill ratio
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // and prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        score += 35.0 + 10.0 * pressure;
        // But if this bin is the only option, new bin is still acceptable
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: small reward for consolidating
        score -= 3.0 * pressure;
    }

    // Lookahead: if the next item fits into post_residual, reward leaving room for it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Bonus if post_residual after next item would also be small/zero
        let after_next = post_residual - next_item_size;
        if after_next <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mildly penalize leaving awkward residue
        score += 5.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item can fit tightly into post residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Next item cannot fit here: mild penalty scaled by wasted lookahead space
    else if next_item_size > 0 {
        let overshoot = (next_item_size - post_residual) as f64;
        score += overshoot * 0.5;
    }

    // Penalize post residual relative to mean residual (avoid dead space outliers)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Slight preference for filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: make empty bins moderately unattractive unless lookahead is hopeless
    if bin_residual == bin_capacity {
        let hopeless = next_item_size > 0 && next_item_size > item_size
            && fitting_bins_count <= 1;
        if !hopeless {
            score += 25.0;
        } else {
            score -= 50.0;
        }
    }

    // Tiny tie-break: prefer tighter current fit
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: best-fit signal (small post_residual is good).
    // Non-linear: reward tight fits more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post-residual, this placement
    // chains nicely -> reward. If next item is stranded by leftover space,
    // penalize dead space that blocks it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // bonus proportional to how well next item uses the leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * use_ratio;
        } else {
            // leftover too small for next item: dead-space penalty scaled
            // by how close it is to being useless
            let waste = post_residual as f64 / (next_item_size as f64);
            score += 5.0 * (1.0 - waste).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // current bins are nearly full (poor fits). Penalize the empty-bin call
    // by the amount of capacity it would waste relative to mean residual.
    if bin_residual == bin_capacity {
        // discourage new bins when open bins still have room
        score += 10.0 + mean_residual * 0.5;
        // late in the stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if many bins fit the item, definitely don't open a new one
        score += 3.0 * (fitting_bins_count as f64);
    } else {
        // mild reward for preferring already-open bins (keeps bin count low)
        score -= 2.0;
    }

    // Global state: with many open bins, favor bins below mean residual
    // (spread load evenly, keep flexible bins alive).
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core waste term, non-linearly scaled by stream progress:
    // later in the stream => dead space is punished more strongly.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Quadratic penalty on residual (dead space grows super-linearly in badness).
    score += 0.004 * post * post;

    // Reward tight fits: small post_residual relative to capacity.
    score -= 12.0 * (1.0 - post / cap).powi(3);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 10.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            // Next item cannot use the leftover space: mild penalty scaled by gap.
            score += 0.03 * (nxt - post).min(cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * progress;
        score += 8.0 * (1.0 - size_ratio) + 6.0 * pressure;
    }

    // Coupling with mean residual across open bins: placing into a bin far from
    // the mean residual is slightly penalized (keeps bin states homogeneous).
    let dev = (post - mean_residual).abs();
    score += 0.02 * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "perfect" residuals (0 or small)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted
    score += (pr / cap) * 60.0;

    // Integer division thresholds: post_residual classes
    if post_residual == 0 {
        score -= 100.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 40.0; // nearly perfect
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual > 50 {
        score += 25.0; // large dead space
    }

    // Modulo arithmetic on post_residual vs capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 15.0; // divisible residual is reusable
    }
    if post_residual > half {
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // harmonic match: next item exactly divides post residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins are few or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0) * 2.0;
    }

    // Prefer filling fuller bins when many bins are open
    score += mean_residual * 0.1 - (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: residual below the minimum item size (1..100 interface, use 10 as safe floor)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strongly penalize dead space in the "awkward" band that few items can fill
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open bins pressure: when many bins are open, discourage new-bin candidates / hoarding space
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if next item fits in the post residual, reward saving that space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the mean (balanced usage)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Early stream: slightly more willing to open bins; late stream: conserve
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin filled by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize dead space, especially small dead space that is hard to reuse
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 2.0 * (pr / 10.0).powi(2);
    }

    // Lookahead: strongly reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // bonus if both fit nearly exactly
            let double_left = post_residual - next_item_size;
            if double_left < 10 {
                score -= 20.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally to wasted potential
            score += 10.0 * (next_item_size as f64 - pr) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global state coupling: many open bins with low mean residual -> consolidate
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.01);
    score += 0.05 * pressure;

    // Time horizon: early in the stream, be more willing to open new bins (exploration);
    // late in the stream, pack tightly into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, expensive later
        score += 20.0 * (1.0 - progress);
        score -= 15.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (keep spread of residuals balanced)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for fuller bins overall
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let rn = r / cap;
    let base = r;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (penalize large residual); late, tolerate larger residuals.
    let progress_weight = 0.4 + 1.2 * t * t;
    let mut score = base * (1.0 + progress_weight * rn);

    // Smooth penalty for near-full bins wasted when many bins are open
    let open_f = open_bins_count as f64;
    let crowd = (open_f / (1.0 + open_f)) * (1.0 - rn);
    score -= 8.0 * crowd * (1.0 - t);

    // Reward perfect fit smoothly (post residual near zero)
    score -= 15.0 * (-rn * rn * 20.0).exp();

    // Lookahead coupling: reward if next item fits remaining space, smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits = (r - ns).max(0.0) / cap;
        let match_term = 1.0 - ((r - ns) / cap).abs();
        score -= 6.0 * match_term * (1.0 - t * 0.5) * (if r >= ns { 1.0 } else { -0.5 });
        let _ = fits;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.3);
    }

    // Mean residual alignment: prefer bins close to the mean residual (smooth)
    let dev = (r - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + t);

    // Mild preference to fill existing bins vs opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "usable" residue classes based on the known size range (1..=100).
    // A residual that is itself a plausible item size (>= some threshold)
    // is valuable; tiny slivers are dead space.
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: residuals below 10 (or the smallest plausible
    // upcoming item) are nearly unusable -> strong penalty.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Harmonic class reward: post_residual that is divisible into useful
    // chunks (i.e., can host next_item_size exactly or nearly) is favored.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= prf {
            // Next item fits here: big reward, scaled by tightness of the
            // follow-up fit (harmonic pairing of pr and next size).
            let follow_fit = 1.0 - ((prf - n) / bin_capacity as f64);
            score -= 30.0 + 20.0 * follow_fit;
            // Exact modulo match: pr is a harmonic multiple of next size.
            if pr % next_item_size.max(1) == 0 && pr > 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally
            // to how much of the bin's remaining value is stranded.
            score += 10.0 * (1.0 - prf / (prf + n));
        }
    }

    // Integer-division threshold: reward residuals in "half-bin" and
    // "third-bin" harmonic classes, which pack well for arbitrary sizes.
    let c = bin_capacity as f64;
    let frac = prf / c;
    if (frac - 0.5).abs() < 0.05 || (frac - 1.0 / 3.0).abs() < 0.05 || (frac - 0.25).abs() < 0.05 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // fit into existing bins is bad. Give the empty bin a mild baseline
    // bonus (tight packing of a fresh bin) but a penalty that grows with
    // how many bins are already open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    } else {
        // Reward placing into existing bins generally.
        score -= 5.0;
        // Prefer fuller bins (best-fit flavor) modulated by stream progress.
        let fullness = 1.0 - bin_residual as f64 / c;
        score -= 10.0 * fullness;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-average-residual bin consolidates space.
    score += 0.3 * (prf - mean_residual);

    // Late-stream tightening: as the stream ends, squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it can't hold even the smallest plausible item.
    let dead_threshold = 1.0f64.min((bin_capacity as f64) * 0.1);
    if (post_residual as f64) <= dead_threshold && post_residual > 0 {
        score += 25.0; // tiny but nonzero gap: worst kind of dead space
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill: strongly favored
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Penalize large leftover gaps that are only slightly too small for
    // the next item (near-miss creates tempting-but-useless space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, tolerate opening new bins less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If mean residual is large, prefer reusing a bin with big residual
    // (this bin's residual deviating high from mean is fine; low is wasteful).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New empty bin candidate: only attractive when the item is huge
    // relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        if big_item > 0.6 {
            score -= 20.0 * (big_item - 0.6) / 0.4;
        } else {
            score += 15.0 * (1.0 - big_item);
        }
        // extra penalty for opening a new bin when other bins fit
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- 2-step lookahead: reward a perfect match for the next item ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Ideal: this bin becomes exactly sized for the next item
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterwards: mildly good, tighter is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - (slack * 0.35).min(22.0);
        } else {
            // Next item will NOT fit here: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // ---- Dead-space shaping relative to mean residual of open bins ----
    let pr = post_residual as f64;
    if pr < 10.0 {
        // Nearly full bin: excellent, it is effectively closed
        score -= 20.0;
    } else if pr > mean_residual + 15.0 {
        // Leaves much more slack than the fleet average: hoarding risk
        score += (pr - mean_residual) * 0.25;
    }

    // ---- Last-chance bin: strongly prefer using it over opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is huge relative
        // to capacity or no open bin offers a decent fit.
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.8;
        if tight_fit || (fitting_bins_count == 0) {
            score -= 10.0;
        } else {
            // Discourage wasting a fresh bin when existing bins fit fine
            score += 12.0 + mean_residual * 0.1;
        }
    }

    // ---- Late-stream tightening: waste matters more as stream ends ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight) * (1.0 - tight);

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post residual too small to fit any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a large useless gap
            score += 10.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Crowding: if many bins open, prefer consolidation onto existing bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 8.0 * (open_bins_count as f64).ln() * (0.5 + t);
    }

    // Global mean residual coupling: prefer bins with residual near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // early phase or many items left: opening fresh bins is fine
        score = 60.0 + 40.0 * (1.0 - t) - 5.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 50.0; // fresh bin supports lookahead pair
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    // Waste ratio: reward placements that use a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: waste left behind, with smooth non-linear penalty growth.
    let mut score = norm_pr * (1.0 + 2.5 * norm_pr * norm_pr);

    // Tight-fit reward: smooth polynomial dip as post_residual -> 0.
    let tight = (1.0 - norm_pr).powi(6);
    score -= 3.0 * tight;

    // Coupling: tight fits matter more late in the stream.
    score -= 1.5 * tight * (progress * progress);

    // Dead-space penalty: residuals too small for typical items.
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 2.0 * dead * dead;

    // Lookahead: reward if next item fits smoothly into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (norm_pr - nx).abs();
        score += 0.8 * gap * gap;
        score -= 0.5 * (1.0 - gap.abs().min(1.0)) * (1.0 - progress);
    }

    // Prefer bins with residual close to item size (smooth coupling).
    let fit_gap = (br - it) / cap;
    score += 0.6 * fit_gap * fit_gap;

    // Mean-residual coupling: avoid scattering waste across many bins.
    score += 0.3 * ((mean_residual - pr).abs() / cap);

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 + progress);
    }

    // New-bin candidate penalty: opening a bin wastes the remaining capacity
    // of all open bins; penalize proportionally, softened early in stream.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64 / cap;
        score += 1.5 + 0.8 * waste + 1.0 * progress;
        // Allow new bin if item is huge (poor fit anywhere) via smooth term.
        score -= 2.0 * norm_it * norm_it;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, scaled by capacity fraction.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Harmonic class of post_residual modulo capacity quarter-bands.
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter;
    score += match band {
        0 => -6.0,                       // tiny leftover: near-perfect fit
        1 => 0.0,
        2 => 3.0,                        // half-ish leftover: mediocre
        _ => 1.5,
    };

    // Fine harmonic class: post_residual mod 10 (dead-space granularity).
    let dead = post_residual % 10;
    if dead > 0 && dead < 10 {
        // small unusable slivers are penalized; multiples of 10 are reusable
        score += (10 - dead) as f64 * 0.35;
    }

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= (bin_capacity - slack) as f64 * 0.08;
            if slack == 0 {
                score -= 8.0; // perfect chain
            }
            // harmonic class of slack modulo quarter
            if slack / quarter.max(1) == 0 {
                score -= 2.0;
            }
        } else {
            // next item cannot fit here regardless: mild penalty for wasting potential
            score += 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Many open bins: discourage spreading; prefer tight packing into fewer bins.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far below mean residual, it's a good "filler" target.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.12;

    // Early stream: be more conservative (keep big residuals for large future items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size >= bin_capacity / 2 {
            score -= 20.0; // large items justify a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to hold even the minimum item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // If the leftover can't fit the lookahead item, it is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (avoid extreme fragmentation).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened if item is large or many bins open.
        score = bin_capacity as f64 - 10.0 * (item_size as f64 / 100.0) + 0.5 * open_bins_count as f64;
        // If this is the last chance anyway, opening new is natural.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Penalize opening new bins when a reasonably tight existing fit exists.
        if post_residual == bin_capacity - item_size && item_size <= 50 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but avoid tiny useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty: slivers are almost unusable
    }

    // 2-step lookahead: reward exact/near match of next_item_size into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let leftover = pr - nxt;
            score -= 60.0 - (leftover / bin_capacity as f64) * 40.0;
        } else {
            // next item won't fit here: post_residual likely wasted
            score += (nxt - pr).min(50.0) * 0.8;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are valuable, keep them tight.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 1.0 {
            score -= (1.0 - ratio) * 20.0;
        } else {
            score += (ratio - 1.0) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = bin_capacity as f64 + 30.0 - pressure * 40.0;
        // opening a new bin is good if the next item is large and would leave poor fits
        if next_item_size > item_size && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: pack tighter as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 * progress);

    // Mild preference to spread load when many bins are open with slack.
    if open_bins_count > 4 && pr > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits the post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: any residual is pure waste; prefer largest packing.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (mean residual low relative to item) or many bins open.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // Default cost of a fresh bin; discount when open bins are scarce or stream early.
        let mut new_bin_cost = 70.0 + 40.0 * horizon;
        if open_bins_count <= 2 {
            new_bin_cost -= 25.0;
        }
        if pressure > 1.0 {
            new_bin_cost -= 30.0 * (pressure - 1.0).min(1.5);
        }
        score += new_bin_cost;
    } else {
        // Mild reward for consolidating into existing bins when many are open.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins with residual close to but above item (best-fit flavor).
        let diff = (bin_residual - item_size) as f64;
        score += 0.1 * diff;
    }

    // Time-varying exploration: early stream favors experimentation with
    // balanced residual profiles; late stream favors greedy tight fits.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - horizon) * 10.0 * ((mean_residual - post_residual as f64).abs() < 15.0) as i32 as f64;
    score += horizon * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual, non-linearly warped by stream progress.
    // Early on (progress->0): prefer tight fits strongly (post_residual^2).
    // Late (progress->1): flat preference on residual, focus shifts to dead space.
    let warp = 1.0 + 1.5 * (1.0 - progress) * (1.0 - progress);
    let mut score = pr * warp + 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Smooth coupling: penalize large residuals more as stream progresses
    // (less future opportunity to fill big gaps).
    score += 30.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward filling bins nearly exactly (dead-space avoidance, smooth bump).
    let dead = norm_pr;
    score += 25.0 * dead * (1.0 - dead) * (1.0 - dead) * 0.5;

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by wasted space.
        score += 6.0 * (1.0 - (next_item_size as f64 / cap)) * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 - progress) - 5.0 * dev * progress;

    // New-bin candidate: penalize lightly early (prefer packing), more
    // strongly late only if the fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 10.0 * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // size classes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, strongly favored
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // integer-division thresholds: small unusable dead space is bad
        if pr < 10 { score += 25.0; } // dead space below min item size
        else if pr < 20 { score += 8.0; }
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // chain fit: perfect next placement
        } else if next_item_size < pr {
            let nxt_class = next_item_size % 10;
            let pr_class = pr % 10;
            if nxt_class == pr_class { score -= 5.0; } // harmonic alignment
            // penalize leaving residual that only barely fits next item
            let gap = pr - next_item_size;
            if gap > 0 && gap < 10 { score += 6.0; }
        } else {
            // next item cannot fit here: slight penalty for tight bins
            score += 3.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive early or when open bins
    // are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // opening a new bin is cheap early, expensive late
        score += 15.0 * progress;
        // if existing bins are fragmented, opening fresh is better
        if fragmentation < item_size as f64 / bin_capacity as f64 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
        // discourage hoarding many open bins
        score += 2.0 * open_bins_count as f64;
    } else {
        // mild reward for filling already-open bins (bin consolidation)
        score -= 1.0 * open_bins_count as f64;
        // prefer bins whose residual is close to item (tight fits)
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Pressure from number of open bins: prefer filling existing bins
    // when many are already open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; if post residual nearly fits but not quite, penalize.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        } else if post_residual > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) - post_residual <= 5 {
            score += 5.0;
        }
    }

    // Mean residual context: when open bins are generally full (low mean residual),
    // opening a new bin is more acceptable; penalize new-bin usage less then.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by stream position and pressure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - progress * 10.0 - mean_residual * 0.05;
    } else {
        // Existing bin bonus: prefer bins with residual close to item size.
        score -= 5.0;
    }

    // Penalize leaving residual just below the smallest possible item (dead space).
    if post_residual >= 1 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fit (item then next item).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // exact two-item chain: near-perfect packing
        } else if next_item_size < post_residual {
            let slack = pr - ns;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            // bonus if chain leaves very little dead space
            if slack <= 10 { score -= 10.0; }
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += 6.0 + 0.15 * (ns - pr);
        }
    } else {
        // last item: minimize final residual aggressively
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual of open bins.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= 2.0 * (mr - post_residual as f64).min(30.0);
    } else {
        score += 1.5 * ((post_residual as f64) - mr).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize leaving residuals too small to be useful (dead space) for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // default neutral-ish score based on post_residual (= capacity - item)
        score += 8.0;
        // but if it would be a tight start (large item), opening fresh is fine
        if item_size >= 60 { score -= 10.0; }
        if fitting_bins_count > 0 { score += 10.0; } // discourage opening when alternatives exist
        if open_bins_count == 0 { score -= 20.0; }
    }

    // Early stream: be slightly more open to new bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: strongly reward bins that can also host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.5 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Bin becomes useless for the lookahead item.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer perfect closure.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Compare against global state: penalize bins far from mean residual
    // (prefer bins that are either much fuller or aligned with the average).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (new-bin candidate gets lower score early); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 4.0 + 12.0 * progress + 0.05 * open_bins_count as f64;
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 3.0 * progress;
    }

    // Mild penalty for large open-bin counts to discourage bin sprawl.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + 40.0 * post_norm * post_norm + 60.0 * post_norm * post_norm * post_norm;

    // Stream progress coupling: waste becomes more costly later in the stream
    score += 30.0 * progress * post_norm * (1.0 - post_norm);

    // Reward tight fits (small post residual) more strongly
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins with residual close to item + next item (two-item packing)
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - slack * 2.0).max(0.0);
    } else if next_item_size > 0 && post < next_item_size && post > 0.0 {
        // dead space relative to lookahead item
        score += 10.0 * (next_item_size as f64 - post) / cap;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev - 10.0 * dev;

    // New-bin candidate: mild penalty so it's chosen only when it truly wins
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" of the capacity we land in.
    // Classes of 10 units (item granularity floor): 0-9 dead space, 10-19 tight slot, etc.
    let class = post_residual / 10;
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space classes: residual < 10 is nearly unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is king
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual < 20 {
        score -= 20.0; // tight slot, very good
    } else if post_residual < 40 {
        score -= 5.0;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are reusable by future items — reward them.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 { score -= 18.0; } else { score -= slack as f64 * 0.15; }
        } else {
            // next item won't fit here; mildly prefer larger residual anyway
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual < 50 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has max residual; make it attractive
    // only when the item is large relative to capacity or fits are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Base new-bin score: prefer it for large items / when few bins fit.
        score = 55.0
            - (item_size as f64) * 0.5
            - (fitting_bins_count as f64) * 4.0
            + progress * 10.0;
        // If the item nearly fills a fresh bin, opening new is great.
        if item_size >= 70 { score -= 30.0; }
        // If an open bin would end with dead space but new bin gives clean fit, favor new.
        if next_item_size > 0 && post_residual >= next_item_size { score -= 8.0; }
    }

    // Mild global pressure: many open bins with high mean residual -> prefer consolidation.
    score += (mean_residual - frac * bin_capacity as f64) * 0.05;
    if open_bins_count > 4 { score -= 1.5; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse later in the stream (less time to recover it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 40.0 * progress;

    // Pressure from many open bins: prefer reusing bins, avoid spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        // Next item cannot use the gap: penalize creating it.
        score += (post_residual as f64) * 0.8;
    }

    // New empty bin: make it attractive only when the item is large relative
    // to capacity or no good fits exist; otherwise keep it mildly expensive.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Slight preference toward bins tighter than the mean residual (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the leftover -> moderate reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + tight / 10.0);
    }

    // Penalize dead space: leftover too small for the smallest plausible item (1..100 range).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Last-chance bin: only one bin can fit this item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Reward bins tighter than the mean residual (good fits), penalize loose bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight pressure toward consolidation when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Progress-aware: early in stream, tolerate opening new bins; later, prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 35.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host a clean 2-chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that can't fit typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress); // dead space early is worse
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if it fits perfectly after the next item too.
        let r2 = post_residual - next_item_size;
        if r2 < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap that blocks the known next item: penalize.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    if open_bins_count > 3 && mean_residual > 25.0 {
        score -= 5.0 * (mean_residual / 100.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (poor fit elsewhere likely) or no other bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins by default.
        score += 18.0;
        // Large items justify a new bin (avoids leaving tiny unusable gaps).
        if item_size > 60 {
            score -= 30.0;
        } else if item_size > 40 {
            score -= 12.0;
        }
        // If many bins are open and mean residual is low, opening fresh is fine.
        if open_bins_count > 2 && mean_residual < 15.0 {
            score -= 10.0;
        }
        // Late in stream, prefer reusing existing bins even if imperfect.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Mild penalty for wasting a very large bin residual on a small item.
    if bin_residual > 70 && item_size < 30 && !is_new_bin {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual value decays with stream progress
    // (later in the stream, waste matters more, so small post_residual is favored).
    let pr_norm = pr / cap;
    score += (pr_norm * pr_norm) * cap * (0.5 + 0.5 * progress);

    // Penalize leaving dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr).min(cap) * (0.3 + 0.7 * progress);
        } else {
            // reward exact-ish fit for the lookahead item
            score -= (1.0 - (nxt - pr).abs() / cap) * 2.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty when many bins are open and this bin is far from mean residual
    let dev = (pr - mean_residual).abs();
    score += dev * 0.1 * (open_bins_count as f64).ln().max(1.0);

    // Smooth new-bin handling: empty bin gets a progressive penalty so that
    // early on we prefer filling existing bins, later a fresh bin is acceptable
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + pr_norm * cap * 0.2;
    }

    // Tight-fit reward (non-linear in fill fraction)
    let fill = 1.0 - pr_norm;
    score -= fill * fill * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo buckets.
    // Residuals divisible by 10 pair well with typical item sizes (10..80 grid).
    let pr = post_residual as i64;
    let class10 = pr % 10;
    let class20 = pr % 20;
    let class25 = pr % 25;

    // Penalize "awkward" residual classes that few item sizes can fill.
    // class10 == 0 is best (any multiple-of-10 item fills it).
    match class10 {
        0 => { score -= 12.0; }
        5 => { score -= 3.0; }          // half-class: items ending in 5 fit
        2 | 4 | 6 | 8 => { score -= 6.0; } // even but not 0/5-ish
        _ => { score += 4.0; }          // odd residuals are worst dead space
    }

    // Modulo-20 harmonic: residuals in {0,20,40,...} accept two half-slots.
    if class20 == 0 { score -= 5.0; }

    // Modulo-25 harmonic: quarter-class alignment.
    if class25 == 0 { score -= 4.0; }
    else if class25 == 12 || class25 == 13 { score += 3.0; }

    // Integer-division thresholds: how many "typical" small items (size 10)
    // still fit after placement.
    let slots10 = pr / 10;
    let slots20 = pr / 20;
    score -= 2.0 * slots10 as f64;
    score -= 3.0 * slots20 as f64;

    // Perfect fit reward: post_residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is unusable forever.
        score += 25.0;
    }

    // Lookahead coupling: does the next item's harmonic class match post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // next item fills this bin exactly
        } else if post_residual > next_item_size {
            let nxt = next_item_size as i64;
            let rem = pr - nxt;
            // Reward if remainder after next item is again a "good" class.
            if rem % 10 == 0 { score -= 8.0; }
            else if rem < 10 { score += 10.0; }
        } else {
            // Next item cannot fit here; mildly favor other bins.
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current item is large and would leave bad classes.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Large items (>60% of capacity) leave little room -> opening fresh
        // bin for them is fine; small items should use existing bins.
        if frac > 0.6 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Progress-aware tightening: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean-residual anchor: prefer bins tighter than the fleet average.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // future item (1..100 range, but small gaps < ~20 are nearly unusable)
    // are heavily penalized, scaled super-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * (20.0 - post_residual as f64) * 0.8;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 150.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: an empty bin should only win when fits elsewhere
    // are bad. Penalize the empty bin moderately so it's used as fallback,
    // but relax the penalty when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        let mean_res = mean_residual;
        let fallback_relief = (mean_res / bin_capacity as f64).min(1.0) * 60.0;
        score += 70.0 - fallback_relief;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Penalize leaving a gap slightly larger than next item that wastes space.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // Early in the stream, allow more freedom to open bins; late in the
    // stream, be conservative and fill existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Discourage leaving residuals much larger than mean (wasteful outlier).
    if post_residual as f64 > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small dead space).
    let dead = post_residual as f64;
    score -= 6.0 * (1.0 - dead / bin_capacity as f64).max(0.0) * (bin_capacity as f64 - dead);

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            // Next item won't fit here: penalize proportionally to leftover size.
            20.0 + (next_item_size - post_residual) as f64
        };
        score += 0.8 * gap;

        // Perfect two-item chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post residual can absorb next item with minimal slack.
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 10.0;
        }
    } else {
        // Last item: only the immediate fit matters.
        score += 0.5 * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize new-bin candidate mildly so we only open new bins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * item_size as f64;
        // Opening a new bin is attractive when few bins fit and item is large.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_capacity as f64 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 12.0 * fit_ratio;
    }

    // Penalize dead space that no future item (>= 10 or >= 1) can use.
    let min_item = if total_items > 0 && step_index + 1 < total_items { 1u32 } else { 1 };
    if post_residual < min_item {
        score -= 40.0; // perfect fill
    }

    // Lookahead coupling: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 0.15 * next_item_size as f64;
        }
    } else {
        // Last item: maximize fill of residual.
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin proportionally
    // to how much usable space already exists across open bins.
    if bin_residual == bin_capacity {
        let usable_space = mean_residual * open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 0.3 * usable_space * (1.0 - 0.5 * progress);
        // Late in the stream, consolidation matters more; ease penalty slightly.
        if fitting_bins_count <= 1 {
            score -= 25.0; // no real alternative
        }
        if item_size > 70 {
            score -= 10.0; // huge items pair poorly; fresh bin ok
        }
    }

    // Prefer filling bins with larger residuals relative to mean (balance avoidance).
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate moderate slack; late, strongly penalize slack.
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * norm_post * norm_post * (1.0 + progress);
    score += 40.0 * poly;

    // Reward filling bins deeply as the stream progresses (smooth interaction).
    let fill = (item_size as f64) / cap;
    score -= 25.0 * fill * (0.3 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic term).
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bin: strongly favor using it (smooth exponential-like via polynomial).
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post) * (0.5 + 0.5 * progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 20.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Smooth penalty for leaving space unusable by next item.
        let gap = (next_item_size as f64 - post) / cap;
        score += 10.0 * gap * gap * (1.0 - progress);
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score += 30.0 + 50.0 * (1.0 - crowded) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size divisors (e.g. 10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit, ideal closure
    } else {
        // Harmonic bonus: how well r decomposes into small units
        let mut harmonic = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if r % d == 0 {
                harmonic += 8.0;
            }
        }
        score -= harmonic;

        // Penalize dead space in awkward ranges (just above typical small items)
        if r < 10 {
            score += 30.0; // unusable sliver
        } else if r >= 10 && r <= 20 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual % next_item_size == 0 {
            score -= 25.0; // harmonic chaining: next item tiles the remainder
        } else {
            score -= 15.0 * (nxt / (post_residual as f64));
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted lookahead
        score += 10.0 + 0.1 * (next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fraction-of-capacity harmonic classes of item_size
    let frac = item_size as f64 / bin_capacity as f64;
    if (frac * 4.0).fract() < 1e-9 {
        score -= 5.0; // quarter-multiple items pack harmonically
    }

    // Late in the stream, tighten bins: prefer tight fills over opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate: only attractive when current bin leaves bad remainder
    // or when many bins are open and this is an empty fresh bin.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 15.0 - 8.0 * bad_fit;
        if open_bins_count as f64 > mean_residual.max(1.0) {
            score -= 3.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier space)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize awkward mid-range dead space that few items can use.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= 8.0 * (item_size as f64 / bin_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count.
        score += 20.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: placing in a bin above mean residual is good (reduces spread).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the post-residual can exactly
    // (or nearly) host the next item — a perfect 2-item chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Exact match is gold; penalize leftover slack quadratically.
            score -= 30.0 - 0.25 * slack;
            score += 0.01 * slack * slack;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall,
            // meaning this bin likely becomes dead space after this placement.
            let shortfall = nxt - post;
            score += 0.30 * shortfall;
        }
    } else {
        // Last item: prefer minimal post residual (best fit).
        score += 0.10 * post_residual as f64;
    }

    // Compare post_residual against mean residual: creating an outlier
    // small residual (below mean) wastes capacity potential.
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);
    // Reward bins whose residual was already tight (low bin_residual waste).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when post_residual of open bins would be tiny/dead.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer filling existing bins reasonably.
        score += 15.0;
        // But if the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for many open bins: consolidation pressure.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += poly * (40.0 + 60.0 * progress);

    // Reward tight fits, more strongly as stream progresses
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 15.0;

    // Penalize dead space relative to mean residual
    if pr > mean_residual {
        score += (pr - mean_residual) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 0.1 * next_item_size as f64;
    }

    // Slight penalty for proliferating open bins late in stream
    score += (open_bins_count as f64).sqrt() * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    let post = post_residual;
    let class = post / 10; // coarse harmonic class
    match class {
        0 => score -= 8.0,          // near-perfect fit (0..9)
        1 => score += 2.0,          // awkward small dead space (10..19)
        2 => score -= 1.0,
        3 => score -= 2.0,
        4 => score -= 3.0,
        5 => score -= 1.0,
        _ => {}
    }

    // Fine modulo structure: residuals divisible by 10 pair well with typical items
    if post % 10 == 0 && post > 0 {
        score -= 3.0;
    }
    if post % 5 == 0 && post % 10 != 0 {
        score -= 1.0;
    }

    // Lookahead: penalize if next item does NOT fit in post_residual (dead space risk)
    if next_item_size > 0 {
        if next_item_size > post {
            score += (next_item_size - post) as f64 * 0.6;
        } else {
            score -= 4.0;
            // extra reward if next item exactly consumes post residual
            if next_item_size == post {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless current bins are very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap;
        // prefer new bin only if existing bins are packed tight late in stream
        score += 15.0 - 12.0 * avg_fill - 5.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Slight preference for filling large items into large residuals
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual is "dead" if it is smaller than the smallest plausible item (<= ~10)
        // or smaller than the lookahead item that might otherwise use it.
        if post_residual < 10 {
            score += 40.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // gap cannot host the next item
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward exact-ish fits: post_residual proportional penalty already covers it,
    // but amplify tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new bin has bin_residual == bin_capacity, so subtracting tightness reward
    // would help it; counteract by penalizing emptiness under pressure).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_fit / bin_capacity as f64);
    }

    // Mild preference for bins with low residual relative to mean (fill fuller bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to capacity (waste).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Aggressive 2-step lookahead: reward if the next item fits exactly or well
    // into the post-residual space (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the chain is
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: post-residual likely becomes dead space;
            // penalize more if it's a small unusable remnant
            if post_residual < next_item_size && post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins whose remaining
    // space stays near/below the mean (avoid leaving abnormally large holes).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early in the stream, be more willing to spread items (keep residual
    // flexibility); later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - dead_frac);

    // Slight penalty for using a nearly-empty existing bin vs. tight fits,
    // unless it's the new-bin candidate itself (which keeps base post_residual = capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral baseline, slightly discouraged unless
        // lookahead chain is perfect (handled above by subtraction).
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = (bin_capacity as f64 - (item_size as f64 / bin_residual.max(1) as f64) * bin_capacity as f64).abs();
    score += tightness * 0.5;

    // Penalize large dead space relative to the smallest future item size scale.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    } else if post_residual > 0 && post_residual < item_size {
        score += 4.0; // dead space smaller than next item is useless
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high (many loose bins).
    let mr = mean_residual / bin_capacity as f64;
    score += mr * 8.0;

    // Progress horizon: early in the stream, keep bins flexible (penalize very low post_residual);
    // late in the stream, prefer aggressive packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.4 {
        score += post_residual as f64 * 0.05; // flexibility early
    } else {
        score -= post_residual as f64 * 0.10 * progress; // compact late
    }

    // Discourage spreading across too many open bins when few fit.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Slight preference for existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: penalize residual, with non-linear polynomial shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling: residual penalty steepens with stream progress
    let progress_coupling = 1.0 + 0.6 * progress + 0.8 * progress * progress;
    score *= progress_coupling;

    // Non-linear reward for tight fits (post_residual near zero), smooth via exp-free polynomial
    let tightness = 1.0 - norm_pr; // 1 = perfectly full
    let tight_reward = tightness * tightness * tightness * (item * 30.0);
    score -= tight_reward;

    // Penalize residual that cannot fit the next item (dead space), smoothly
    if nxt > 0.0 {
        let gap = (nxt - norm_pr).max(0.0);
        score += 25.0 * gap * gap * (1.0 - 0.3 * progress);
        // Reward residual that exactly accommodates next item
        let match_f = 1.0 - ((nxt - norm_pr).abs());
        if match_f > 0.0 {
            score -= 12.0 * match_f * match_f * match_f;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and fit is loose (encourage consolidation)
    let many = open_bins_count as f64;
    score += 0.5 * (many.sqrt()) * norm_pr * (1.0 - tightness);

    // Deviation from mean residual: prefer bins near the mean (balanced packing), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual of best fit would be large
    if bin_residual == bin_capacity {
        score += 55.0 - 15.0 * item * item - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr;

    // Strongly prefer reusing an existing bin over opening a new one.
    if !is_new_bin {
        score -= 0.65 * cap;
    } else {
        // New-bin candidate: mild penalty growing with number of open bins (encourage consolidation).
        score += 0.4 * open_bins_count as f64;
    }

    // Tightness bonus: strongly reward near-perfect fills (harmonic class ~0).
    let tight = 1.0 - pr / cap;
    score -= 35.0 * tight.powi(6);

    // Harmonic class of post_residual via quarter-capacity integer division.
    // Class 1 (residual in (0, C/4]) is a "dead zone": too small for most items.
    // Class 2 ((C/4, C/2]) is awkward; class 3 (> C/2) is still flexible.
    let class = (post_residual * 4) / bin_capacity;
    score += match class {
        0 => -10.0,
        1 => 12.0,
        2 => 5.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward if the next item can also fit the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0;
            // extra harmony: next item leaves a class-0 or class-3 residual too
            let nq = ((post_residual - next_item_size) * 4) / bin_capacity;
            if nq == 0 { score -= 4.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // Late in the stream, slightly favor tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - pr / cap);

    // Mild pull toward bins with below-average residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual) as f64;
    }

    // Non-linear penalty on small-but-not-dead gaps (hard to fill later).
    if post_residual > 0 && post_residual <= 30 {
        score += 1.5 * (30 - post_residual) as f64;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is excellent -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // next item still fits, mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize if post residual is a
            // tempting-but-useless gap for the lookahead item
            score += 0.5 * (post_residual as f64 - (post_residual - next_item_size) as f64).min(post_residual as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are already plentiful; encourage consolidation.
    let mean_r = mean_residual.max(0.0);
    if bin_residual as f64 > mean_r {
        score -= 8.0; // prefer bins with above-average free space
    } else {
        score += 4.0;
    }

    // Pressure grows with number of open bins: favor filling existing bins
    // rather than opening new ones.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin offers a decent fit (post_residual
    // large means poor fit here). Empty-bin call has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, moderated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post residual (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit: post residual becomes dead space.
        score += 0.35 * post_residual as f64;
    }

    // Reward tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize bins far from mean residual (prefer homogeneous fill).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing fits are bad.
        score += 15.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead: penalize leaving a residual too small for the next item
    // (dead space), but reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Dead space relative to lookahead; worse the closer it is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        } else if next_item_size == post_residual {
            score -= 30.0;
        } else {
            // Next item fits: residual remains partially usable.
            score -= 5.0;
        }
    } else {
        // Last item: pure waste minimization.
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual vs. a fresh 100 residual)
    // or when there are few alternatives.
    if bin_residual == bin_capacity && item_size < bin_capacity {
        let avg_waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, keep bins open and consolidated; later, fresh bins are cheaper.
        let new_bin_penalty = 45.0 * (1.0 - 0.5 * progress);
        score = new_bin_penalty + 0.25 * avg_waste_elsewhere;
        if fitting_bins_count <= 1 {
            score -= 20.0; // poor alternatives elsewhere -> new bin is fine
        }
        if item_size >= 70 {
            score -= 15.0; // big items start clean bins happily
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Slight consolidation pressure: prefer bins with below-average residual
    // (i.e., more filled bins) to keep many half-empty bins from lingering.
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Mild crowding penalty: spreading across many open bins is fine, but
    // discourage adding to an already crowded pool when the fit is loose.
    if open_bins_count > 8 && post_residual > 40 {
        score += 0.5 * ((open_bins_count - 8) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: post_residual == 0 -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic fractions of capacity: residual equal to capacity/k is reusable.
    let harmonics: [f64; 6] = [cap, cap / 2.0, cap / 3.0, cap / 4.0, cap / 5.0, cap / 10.0];
    for h in harmonics.iter() {
        if (pr - h).abs() < 1.0 {
            score -= 60.0;
        }
    }

    // Dead-space class: tiny nonzero residual (1..=9) is wasted space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Modulo-10 classes: residual divisible by 10 pairs well with integer item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division threshold: post_residual bucketed by 20s; deeper buckets worse.
    score += (post_residual / 20) as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * frac;
        } else {
            // next item cannot fit here: mild penalty scaled by wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else works.
    if bin_residual == bin_capacity {
        score += 80.0;
        // But if mean residual across open bins is too small to be useful,
        // opening fresh is less bad.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 90.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    score += (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable leftover for typical small items: mild reward scaled by usefulness.
        score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 20.0;
        // Pressure from many open bins: discourage yet another bin.
        score += 3.0 * open_bins_count as f64;
        // But if the item leaves a dead gap in any existing bin, new bin gains appeal:
        if post_residual > 0 && post_residual <= 9 {
            score -= 45.0;
        }
        // Lookahead: if next item is small, a fresh bin with large residual is good.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead coupling: prefer bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0; // leftover too small for next item: penalize
        }
    }

    // Mean-residual coupling: bins far below mean residual are "fresh"; using them
    // for large items is fine, but avoid dumping items into nearly-full bins when
    // alternatives exist.
    if (bin_residual as f64) < mean_residual - 20.0 && fitting_bins_count > 1 {
        score += 8.0;
    }

    // Open-bin pressure: mild reward for consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Stream progression: late in the stream, tighten up (prefer tighter fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * lookahead_gap;
        // Perfect two-item packing bonus
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0; // near-perfect chain
        }
        // Penalize leaving residual that no small item can fill later
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.2 * post_residual as f64;
    }

    // Compare post_residual against mean residual across open bins:
    // a placement far below mean residual creates an outlier dead bin.
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    if dev > 0.0 {
        score += 0.25 * dev; // above-mean leftover: wasteful
    } else {
        score += 0.1 * dev; // slight reward for below-mean usage
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is acceptable if the item is huge relative to capacity
        // and no open bin is tight enough
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Keep new-bin penalty mild late in stream if many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild tightness reward for very small post residual
    if post_residual <= 5 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual (good packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize wasting residual that the next item could have used.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Keep residual usable for the next item: mild reward.
            score -= 4.0;
        } else {
            // Destroying residual that fits next item is costly, scaled by how close it was.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 6.0 + 0.35 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Fragmentation guard: penalize bins whose residual is far below the current mean
    // (isolated small pockets) — but only mildly, since tight fits also lower residual.
    if bin_residual < bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score += 0.12 * gap;
        }
    }

    // Early-stream exploration: with few open bins, be slightly greedy about filling
    // existing bins to consolidate; later, allow more bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= (1.0 - progress) * 5.0;
    }

    // New-bin candidate: neutral-ish score anchored to mean residual so it wins only
    // when all existing fits are poor (post_residual large or dead-space heavy).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + mean_residual * 0.3;
        // Late in the stream, opening a new bin is less attractive (end-game consolidation).
        score += progress * 15.0;
        // Never open a new bin when this is the only fitting bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm);

    // Smooth quadratic coupling: penalize large residuals more as stream progresses
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) non-linearly
    score -= 8.0 * (1.0 - pr_norm).powi(3);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Dead-space penalty: residual too small for typical future items
    let small_item = 1.0 / cap;
    let dead = (small_item - pr_norm).max(0.0);
    score += 20.0 * dead * dead * cap * (1.0 + progress);

    // Lookahead: reward if next item fits in post residual (smooth ramp)
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fit_margin = pr_norm - next_norm;
        if fit_margin >= 0.0 {
            score -= 6.0 * fit_margin * (1.0 + 2.0 * (1.0 - progress));
        } else {
            score += 4.0 * (-fit_margin);
        }
    }

    // Mean residual coupling: prefer bins deviating from mean in smooth fashion
    let mean_norm = mean_residual / cap;
    score += 5.0 * (pr_norm - mean_norm) * (pr_norm - mean_norm) * 4.0 * progress;

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * pr_norm;

    // New-bin candidate: penalize opening a fresh bin unless current residual is very tight
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - item_norm) * (1.0 - progress);
        // allow new bin for big items late in stream
        score -= 18.0 * item_norm * item_norm * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small divisors) are preferred,
    // since future small items are more likely to fit exactly.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is ideal
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        3.0 // odd residuals are harder to fill
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: very small leftovers are
    // dead space unless they are exact (handled above).
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Coupling with lookahead item: reward residuals that can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 6.0 + 4.0 * (slack / bin_capacity as f64);
        // Harmonic match: next item exactly divides leftover
        if next_item_size > 0 && pr % next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by how close we are
        score += 4.0 * (next_item_size - pr) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0
            + 10.0 * (post_residual as f64 / bin_capacity as f64)
            - 5.0 * (open_bins_count as f64).sqrt();
    }

    // Tight fit reward: residual close to item size means dense packing.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Progress-aware dead-space penalty: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Deviation from mean residual: prefer bins below mean (denser bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    if post_residual > 0 {
        // A gap is "dead" if it's too small to fit even the smallest plausible item (1..100 range).
        if post_residual < 10 {
            score += 500.0; // unusable sliver -> strong penalty
        } else if post_residual <= 20 {
            // Gap barely fits small items; penalty grows as gap shrinks.
            score += (20 - post_residual) as f64 * 12.0;
        }
        // Non-linear coupling: quadratic penalty on small residuals.
        if post_residual <= 30 {
            let r = post_residual as f64;
            score += (30.0 - r) * (30.0 - r) * 0.4;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 300.0;
    }

    // Favor bins whose residual tightly matches the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 80.0;

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 2 {
        // This bin is scarce capacity; reward using it rather than opening a new bin.
        score -= 60.0;
    }
    if open_bins_count > 0 {
        score -= open_bins_count as f64 * 2.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (already relatively full bins) to consolidate packing.
    score -= (mean_residual - bin_residual as f64) * 1.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial reward proportional to how well next item uses the gap.
        score -= (next_item_size as f64 / post_residual.max(1) as f64) * 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in this gap: penalize leaving medium gaps.
        score += 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only preferable when no open bin
    // offers a decent fit. Penalize opening new bins mildly, scaled by progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + progress * 60.0;
        // But if item is large and would leave huge dead space in any open bin,
        // new bin becomes attractive: reduce penalty.
        if item_size >= 60 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin anyway
        }
    }

    // Last-chance bonus: if only this bin fits, strongly favor it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Aggressive 2-step lookahead: perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chain fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(40.0);
        }
    }

    // Relative to mean residual: prefer bins with residual near mean (balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when item fits well in an existing bin
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * item_size as f64;
        // allow new bin only if no good fit exists (post_residual very small in others is handled above)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual is good, but extremely large
    // post_residual means the bin stays too empty (wasted unless reusable).
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 6.0; // creating tiny unusable slivers is bad
    }

    // Reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty for leaving large gaps
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many bins compete, to prefer best fit discrimination
        score += fitting_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // base reluctance to open new bins
        score += 40.0;
        // reduce reluctance late in the stream or when open bins are crowded
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        let mean_fit = mean_residual / (bin_capacity as f64);
        if mean_fit < 0.25 {
            score -= 20.0 * (0.25 - mean_fit) / 0.25;
        }
        // if item is large relative to capacity, prefer a fresh bin more
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        // reward bins whose residual is close to mean (keep balanced portfolio)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Dynamic time horizon: early on, be conservative with open bins;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post / (bin_capacity as f64));

    // Slight penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64;
    score += 20.0 * x * (1.0 - x) * (1.0 - 2.0 * x); // cubic tilt: penalize mid-range waste

    // Stream-progress coupling: later in the stream, tighten more (quadratic in progress)
    let tighten = progress * progress;
    score *= 1.0 + 0.5 * tighten * x;

    // Dead-space penalty: post residual too small to fit typical future items
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - x) * (0.5 + progress);
    } else if next_item_size > 0 {
        score -= 3.0 * (1.0 - x) * x;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mean-residual coupling: penalize bins deviating from mean residual (polynomial)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // New-bin candidate: mildly discouraged unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - tighten) + 8.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps divisible by 10 are reusable
    let gap_class = post_residual % 10;
    score += if gap_class == 0 {
        -6.0
    } else if gap_class <= 3 {
        4.0
    } else {
        gap_class as f64 * 0.5
    };

    // Integer-division thresholds on post_residual: tiny gaps are dead space
    if post_residual <= 10 {
        score += 12.0;
    } else if post_residual <= 20 {
        score += 3.0;
    } else if post_residual >= 40 {
        score -= 2.0;
    }

    // Lookahead: does next item fit the post residual? (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // exact modulo pairing: next item fills gap to a multiple of 10
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else if next_item_size > post_residual && post_residual < next_item_size.min(10) {
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        score = 30.0 + 40.0 * crowded - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Slight preference for tighter existing bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are heavily penalized since nothing can ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward zone" gaps: residuals that few item sizes can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Tight fit: reward small relative leftover.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins and avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure.
        score += 25.0 + pressure * 8.0;
    } else {
        score -= pressure * 0.8;
    }

    // Lookahead: if next item fits exactly in the post residual, reward;
    // if next item cannot fit in post residual but could fit elsewhere, neutral.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // placing here kills space needed by next item -> mild penalty
            score += 10.0;
        }
    }

    // Slightly prefer bins whose residual is above the mean (keep flexible bins alive).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect chain: next item exactly consumes leftover space.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how close next item gets to filling post_residual.
                let fill_ratio = nxt / pr;
                score -= 40.0 * fill_ratio;
                // Penalize leftover after the lookahead item too.
                score += 0.3 * gap;
            }
        } else {
            // Next item cannot fit in this bin's leftover: leftover is dead space
            // unless another bin takes it. Penalize dead space more when few bins fit.
            score += 0.5 * (nxt - pr);
        }
    } else {
        // Last item: just prefer tightest fit.
        score = post_residual as f64;
    }

    // Compare post_residual against mean residual: leaving above-average residual
    // is wasteful; below-average residual preserves capacity elsewhere.
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only if it beats
    // genuinely bad fits. Slightly favor new bin late in the stream when the
    // next item is large (keeps a big empty space available for it).
    if bin_residual == bin_capacity {
        score = 55.0;
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress; // later in stream: prefer consolidating into open bins
    }

    // Small penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item exactly fills post_residual, penalty if it barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into bins below the mean.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * (0.3 + 0.4 * t);

    // Late in the stream, avoid opening new bins; prefer existing bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * t + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual is a "nice" multiple region.
    let r = post_residual as f64;
    if r >= 10.0 && r <= 30.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Tight fits rewarded more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (1.0 + 3.0 * progress) * 20.0;

    // Dead-space penalty: cubic in normalized residual, growing with progress
    score += norm_pr * norm_pr * norm_pr * (10.0 + 40.0 * progress) * cap;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 + 12.0 * progress;
        } else {
            let gap = (next_item_size as f64 - pr) / cap;
            score += gap * gap * 30.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (keeps residuals balanced)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Mild pressure to consolidate into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (norm_pr * 5.0 - tight * 2.0);

    // Small smooth progress tilt: earlier stream favors filling large-residual bins less eagerly
    score += progress * norm_pr * 10.0 - (1.0 - progress) * norm_pr * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 1.5;
    }

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable.
    let dead_class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if dead_class > 0 && dead_class < 5 {
        score += dead_class as f64 * 1.5;
    }

    // Integer-division thresholds: coarse class of leftover space.
    let class = post_residual / 10; // 0..=10
    score += class as f64 * 2.0; // larger leftover mildly penalized (waste)
    if class == 0 && post_residual > 0 {
        score += 15.0; // tiny leftover class is bad
    }

    // Lookahead coupling: does next item fit in the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= bin_capacity as f64; // chain perfect fit
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= fit_ratio * 20.0; // reward reusing leftover
        } else {
            // next item won't fit here; leftover becomes dead unless class is useful
            let harm = (post_residual as f64) / bin_capacity as f64;
            score += harm * 10.0;
        }
    }

    // Tight fit reward relative to current residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: neutral baseline, only chosen when open bins score worse.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        // discourage opening new bin when a decent fit exists
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 25.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (more filled).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use
    // (tiny gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    }

    // Reward placements that leave a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Tight-fit reward: item consuming most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but relax if this bin is the last chance elsewhere.
        score += 30.0 + pressure * 2.0;
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 30.0;
    }

    // Slight preference for bins below the mean residual (keep residuals even,
    // avoid leaving one bin as a dead-space trap while others stay usable).
    score += 0.15 * ((bin_residual as f64 - mean_residual)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Exact match (post_residual == next_item_size) is ideal: subtract big bonus
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // If next item leaves a further perfect residual, extra reward
        if post_residual >= 2 * next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to the mismatch
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 * (miss / bin_capacity as f64);
    }

    // Penalize dead space below smallest plausible item
    if post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins that are relatively fuller than average (tight packing)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-attractive only when
    // no open bin offers a good fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        // If this item would leave a large residual in an open bin anyway,
        // opening fresh is fine; otherwise discourage
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - waste_ratio);
        // Late in the stream, opening new bins is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild preference for compacting into few bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: strong bonus when post residual is small.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    // Items are 1..=100; residual < next_item_size is likely wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += 0.6 * (nxt - post);
        }
        // Perfect lookahead pairing: residual after placement fits next item exactly.
        if nxt > 0.0 && post >= nxt {
            let pair_waste = post - nxt;
            score -= 4.0 * (1.0 - pair_waste / cap);
        }
    } else {
        // Last item: exhaust bins aggressively.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or this bin's residual is far below the mean (fragmented bin).
    if bin_residual == bin_capacity {
        let poor_fit = post / cap; // = 1.0 for empty bin with no item subtracted... post = cap - item
        let mean_gap = mean_residual - (bin_residual as f64 - item_size as f64);
        // Prefer new bin when existing bins are fragmented (low mean residual)
        // and the alternative would leave big waste.
        score = 0.55 * cap
            + 0.4 * (mean_residual)
            - 30.0 * (1.0 - poor_fit)
            - (if mean_residual < 25.0 { 15.0 } else { 0.0 })
            - mean_gap.max(0.0) * 0.3;
        // Early stream: keep new bins cheap to allow spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins: discourage opening more.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Existing bin: mild preference for bins below mean residual
        // (consolidate emptier bins, keep fuller ones for big items).
        let gap = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * gap;
        // Slight penalty for very full bins unless fit is near-perfect.
        if post > 0.0 && post < 10.0 {
            score -= 5.0; // near-perfect fill, reward strongly
        }
    }

    // Progress-aware waste weighting: later in stream, waste matters more
    // since fewer chances to recover.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, scaled by stream progress (later => tighter packing desired)
    let mut score = post * (0.5 + 1.5 * progress);

    // Smooth non-linear penalty on tiny residuals (dead space) via quadratic coupling
    let dead = (1.0 - norm_post) * (norm_post * norm_post);
    score += 30.0 * dead;

    // Interaction: post_residual with mean residual — prefer bins near the mean residual to keep balance
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Cubic coupling of normalized post residual with progress: early on tolerate spread, late avoid extremes
    score += 20.0 * progress * norm_post * norm_post * norm_post * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward if next item fits in post residual (smooth reward)
    if next_item_size > 0 {
        let fits = (post_residual as f64 >= next_item_size as f64) as f64;
        let tight = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 12.0 * fits * (0.5 + tight);
    }

    // Slight preference to fill existing bins when many are open
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make empty bin moderately attractive only when residual of others is hopeless
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let post = post_residual;
    if post == 0 {
        score -= 25.0; // perfect fill, excellent
    } else {
        // Reward residuals that are exact multiples of small harmonic units
        let units: [u32; 6] = [10, 20, 25, 50, 5, 40];
        for (i, &u) in units.iter().enumerate() {
            if post % u == 0 {
                score -= (12.0 - i as f64 * 1.5).min(post as f64 * 0.08);
                break;
            }
        }
        // Penalize dead space: small unusable leftovers
        if post < 10 {
            score += 18.0;
        } else if post < 20 {
            score += 6.0;
        }
        // Integer-division thresholds: post/25 class
        let class = post / 25; // 0..4
        score += match class {
            0 => 8.0,
            1 => 0.0,
            2 => -3.0,
            _ => -5.0,
        };
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            let slack = post - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0) * 0.5;
            // harmonic: next item divides post residual evenly
            if post % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; mildly penalize tight fits
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins are crowded or this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // penalize new bin by average slack + count pressure
        score = 55.0 + open_bins_count as f64 * 2.0 - crowding * 30.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items start fresh bins more readily
        }
    }

    // Slight preference to fill bins with larger residual less when many bins open
    score += (post as f64) * (open_bins_count as f64).ln().max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (<= 10)
    // or smaller than the lookahead item when it cannot fit.
    if post_residual < 10 {
        score += 40.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap blocks the next item: soft penalty proportional to the blockage
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer filling
    // existing bins when open_bins_count is large.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (they are "fresher"); prefer bins closer to the mean to consolidate.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive if no open bin fits well,
    // i.e., make it lose against any reasonable existing placement.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Slightly cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear penalty
    // on very small leftovers (dead space that few future items can use).
    if post_residual > 0 {
        score += 8.0 / (post_residual as f64).powf(0.35);
    } else {
        score -= 12.0; // perfect fit is excellent
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly into the
    // post residual; penalize if the next item cannot use the leftover at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain fit: this bin absorbs two items perfectly
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * slack; // next item fits, mild reward decaying with slack
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.20 * miss; // leftover is dead space w.r.t. the lookahead item
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are scarce
    // resources; using them for a loose fit is costly.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev; // slight reward for below-mean residual usage
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (pristine empty bin): keep it competitive only when the
    // item is large relative to capacity or when open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Large items and heavy fragmentation favor opening a fresh bin.
        score -= 15.0 * fill_ratio + 10.0 * (fragmentation - 0.5).max(0.0);
        // Late in the stream, avoid spawning bins that will end mostly empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild pressure against hoarding many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty for leftover space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: only one open bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space smaller than the next item
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Prefer filling bins with more residual (consolidate waste) when waste is small
    if post_residual <= 10 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // existing fits are poor (large post_residual) or many bins are open
    if bin_residual == bin_capacity {
        let poor_fit_penalty = post_residual as f64; // == item_size for new bin
        let escape_bonus = if fitting_bins_count > 0 {
            (poor_fit_penalty / bin_capacity as f64) * 30.0 + (open_bins_count as f64 / 20.0).min(1.5) * 10.0
        } else {
            0.0
        };
        score += 70.0 - escape_bonus;
    }

    // Time horizon: as stream progresses, favor closing bins tightly (less waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with high mean residual -> prefer bins below mean residual
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Mild penalty for using very full bins early (save them for small items)
    if progress < 0.5 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Early: prefer tight fits less aggressively; late: strongly minimize waste.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: residuals that are too small to be useful
    // are penalized quadratically (wasted capacity).
    let dead = (1.0 - norm_pr).powi(2) * (norm_pr.powi(3)) * cap;
    score += 40.0 * dead;

    // Reward filling bins tightly: smooth interaction of item size and post residual.
    score -= 30.0 * norm_it * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (closing out emptier-than-average bins), smoothly weighted.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into the resulting post_residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit; mild penalty scaled by leftover size.
            score += 5.0 * norm_pr * (1.0 - progress);
        }
    }

    // Slight preference for consolidating into fewer bins as stream advances.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate (bin_residual == bin_capacity): post_residual is large,
    // so base term already penalizes it; add extra smooth penalty unless the
    // item is huge relative to capacity (then opening a bin is natural).
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - norm_it) * (1.0 - norm_it) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward exact-fit classes (0, small divisors of capacity)
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 12.0; // class aligned to tenths of capacity
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Penalize dead-space classes: residuals in awkward ranges
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr >= 10 && pr < 20 {
        score += 10.0;
    }

    // Integer-division threshold: small residual is fine only if next item can use it
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead pair fit: strong reward, scaled by how snugly
            score -= 18.0 + 10.0 * (next_item_size as f64 / cap);
            if pr == next_item_size {
                score -= 20.0; // exact lookahead match
            }
        } else {
            // residual cannot host next item: penalize proportionally to waste
            score += 8.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins below mean residual (tight bins first)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate, discourage spreading into many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline waste of a fresh bin
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        } else if fitting_bins_count == 1 {
            score += 50.0; // keep last-chance bin alive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Zero residual (perfect fit) gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // Penalize if post residual is just barely too small for the next item (near-miss dead space).
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) <= 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Mild progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    // Slight preference toward bins with below-average residual (fill emptier bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly -> excellent
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                score -= 200.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // dead space that cannot host the next item: penalize small leftovers
            score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins whose residual is above mean (larger holes)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
        // early stream: opening bins is cheap and useful
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 50.0;
        }
    }

    // Prefer tighter fits generally
    score += 0.3 * (post_residual as f64 - (bin_capacity as f64 - item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Penalize dead space that is too small for any plausible future item (1..100).
    if post_residual > 0 {
        let dead = if post_residual < 1 { 1.0 } else { 0.0 };
        // usable residual: post_residual can host next item?
        let hosts_next = if (post_residual as u32) >= next_item_size && next_item_size > 0 { 1.0 } else { 0.0 };
        score += 6.0 * dead * (1.0 - hosts_next);
        score += 0.35 * (post_residual as f64) * (1.0 - hosts_next);
    }

    // Lookahead coupling: reward if next item fits in post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else if next_item_size >= bin_residual {
            // next item won't fit this bin anyway; less pressure to save space
            score -= 1.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Many open bins: prefer consolidation, penalize spreading.
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness);

    // Global state: if this bin's residual is far from mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Time horizon: early in stream, be choosier (penalize mediocre fits);
    // late in stream, accept decent fits more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.04 * post_residual as f64;
    score -= progress * 1.5 * tightness;

    // New-bin candidate: make it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        let bad_existing = if post_residual == 0 { 0.0 } else { 1.0 };
        score += 5.0 * bad_existing + 0.5 * open_bins_count as f64;
        // Opening a fresh bin early is cheap; later prefer filling existing bins.
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tight fits mildly), late, pack tightly (reward).
    let tightness = 1.0 - (pr / cap).powf(2.0); // 0 = roomy, 1 = very tight
    score -= tightness * (pr * (0.5 + progress)) * 0.8;

    // Smooth quadratic penalty on large dead space that grows with progress
    let dead = (pr / cap).powi(2);
    score += dead * cap * (0.15 + 0.35 * progress * progress);

    // Lookahead: reward residual that can host next item (smoothly)
    if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        let closeness = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= fits * closeness * (8.0 + 12.0 * (1.0 - progress));
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    let spread = (mean_residual - pr) / cap;
    score += spread * spread * 4.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current residuals are poorly usable
    if bin_residual == bin_capacity {
        let avg_usability = 1.0 - ((mean_residual / cap).powf(1.5));
        score += 10.0 + 20.0 * avg_usability * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual belongs to a
    // "composable" class (multiples of 25, or small residuals) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Exact-fill reward: perfect packing.
    if pr == 0 {
        score -= 200.0;
    }

    // Harmonic classes on post_residual: 0, quarter, half, three-quarter.
    if pr % quarter == 0 {
        score -= 30.0; // residual aligns with harmonic grid -> likely reusable
    } else {
        // Penalize residuals that are just above a harmonic class (dead space)
        let class = (pr / quarter) * quarter;
        let offset = pr - class;
        score += offset as f64 * 0.6;
    }

    // Tiny residuals are dead space unless item exactly filled.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // Harmonic check: does post_residual - next land on a class?
            if (pr - next_item_size) % quarter == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by gap
            let gap = (next_item_size - pr) as f64;
            score += (gap * 0.15).min(20.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.5 * mean_residual;
        score += base;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Prefer fuller bins among many open bins (consolidation pressure).
    let fullness = (bin_capacity - bin_residual) as f64 / cap;
    score -= fullness * 10.0 + open_bins_count as f64 * 0.3;

    // Mean-residual drift: if this bin's residual is far below the mean,
    // it's an outlier worth closing out.
    let res_f = post_residual as f64;
    if res_f < mean_residual - 15.0 {
        score -= 10.0;
    } else if res_f > mean_residual + 15.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < next plausible small item) are heavily penalized.
    let dead_threshold: u32 = 12;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Mid-range unusable gaps (can't host even a small item comfortably)
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Reward near-perfect fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness * tightness);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap: penalize small gaps more
        if post_residual < next_item_size.min(dead_threshold) {
            score += 20.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a bad gap or mean residual is already low.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < dead_threshold;
        if bad_fit {
            score -= 50.0; // opening fresh bin beats creating dead space
        } else {
            score += 10.0 + 0.3 * mean_residual; // prefer reusing open bins
        }
    }

    // Slight progress adaptation: later in stream, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual.min(30) as f64 / 30.0);

    // Mild alignment with mean residual: prefer bins whose residual is below mean
    // (i.e., already well-filled bins).
    score -= 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward
        if match_gap == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the residual: reward proportional to tightness
            score -= 20.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted potential
            score += 5.0 + 0.1 * match_gap;
        }
    }

    // Penalize residuals too small to hold any plausible item (dead space)
    if post_residual < 10 {
        score += 15.0;
    }

    // Prefer tighter fits relative to mean residual of open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 {
            ((post_residual as i64 - next_item_size as i64).abs() as f64) / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted if open bins are scarce or fit is bad
        score += 30.0 - 10.0 * poor_fit_penalty - 2.0 * open_bins_count as f64;
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual close to 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 12.0; // small-but-fillable residual
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't use the leftover: mild penalty scaled by waste
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Crowding: many open bins -> favor consolidation (low mean residual bins get boost).
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.05 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Early phase: prefer keeping residuals large/flexible; late phase: pack tight.
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 0.10 * post_residual as f64;

    // New-bin candidate handling: opening a bin is costly unless it enables a
    // perfect-ish future sequence or current fits are all bad.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 {
            if item_size + next_item_size <= bin_capacity {
                new_bin_score -= 40.0; // fresh bin can host a perfect pair
            }
            if next_item_size > post_residual && post_residual > 0 {
                new_bin_score -= 20.0; // existing bins leave next item stranded
            }
        }
        if post_residual > 0 && (post_residual < 10 || post_residual > 90) {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, punish dead space more strongly
    let progress_weight = 1.0 + 2.0 * progress * progress * (3.0 - 2.0 * progress);
    score *= progress_weight;

    // Reward tight fits: quadratic bonus when post_residual is small relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize creating residual that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let usable = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        // smooth blend: reward exact next-item fit, penalize near-miss waste
        let fit_quality = (next_item_size as f64 / cap) * (1.0 - gap / cap);
        score -= 6.0 * fit_quality * usable;
        score += 3.0 * (gap / cap) * (gap / cap) * (1.0 - usable * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    }

    // Crowding effect: many open bins -> prefer filling existing ones
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate (empty bin): penalize so it is chosen only when nothing fits well
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 20.0 * progress;
        // less penalty if mean residual across open bins is tiny (all bins nearly full)
        let relief = (mean_residual / cap).min(1.0);
        score += base_penalty * (1.0 - 0.6 * relief);
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: capacity quantized into harmonic classes.
    // Class 0: perfect fit (post_residual == 0) -> strong reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect / near-perfit fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // Harmonic classes of post_residual modulo 10: small residues in
    // classes {1,2,3} leave "almost unusable" slivers -> penalize harder.
    let m = post_residual % 10;
    if m > 0 && m <= 3 {
        score += 8.0; // dead-space sliver penalty
    } else if m >= 8 {
        score -= 4.0; // still fairly usable residue class
    }

    // Integer-division thresholds: post_residual in quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual > 3 * quarter {
        score += 12.0; // bin still mostly empty after placement: wasteful
    } else if post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= 5 {
            score -= 15.0;
        } else {
            score -= (10.0 * (1.0 - slack / cap)).max(0.0);
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's residue: mild penalty on slivers
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Give it a moderate baseline so tight
    // fits in open bins beat it, but a wasteful fit does not.
    if bin_residual == bin_capacity {
        // baseline: comparable to a mediocre fit
        score = 0.35 * cap + 5.0;
        // early stream: opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is huge, fresh bin is attractive
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    score += 0.02 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Perfect fit for the next item too: chain bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // when few bins are open, tolerate opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.5) * (0.6 + 0.4 * progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when the item actually fits well.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * diff * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 == next {
            // Perfect 2-step chain: fill this bin completely over two items.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after placement: mild reward scaled by closeness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize proportionally to wasted potential.
            score += 8.0 * (1.0 - post_residual as f64 / next);
        }
    } else {
        // Last item in stream: prefer minimizing residual as tightly as possible.
        score -= 20.0;
    }

    // Perfect fill now is always excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: tiny unusable remnants (below min item size 1 handled
    // generically: residuals smaller than a plausible next item are risky).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins that are already relatively full (low residual vs mean).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if many bins are open with scattered residuals, a fresh bin can
        // consolidate future items; soften the penalty late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Slight preference for keeping open-bins count low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0; // dead space relative to lookahead
    } else if next_item_size > 0 {
        score -= 10.0; // lookahead fits into the remainder
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual - (bin_capacity - item_size) as f64;
        score = (bin_capacity - item_size) as f64
            + 15.0
            - 20.0 * avg_waste.max(0.0) / bin_capacity as f64
            - 10.0 * progress
            - (open_bins_count as f64).min(10.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / bin_capacity as f64) * 5.0;

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills less aggressively; late, strongly prefer small residuals.
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Smooth cubic term penalizing mid-range dead space (awkward residuals ~ 20-50)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 30.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward residuals that can fit the next item (smooth, not piecewise)
    let fit_next = (next - pr).abs();
    score -= 8.0 * (-fit_next / 15.0) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty when many bins are open and residual is large (fragmentation risk)
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // Mild pull toward mean residual for smoother packing
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a moderate default score so it wins
    // only when all open bins have poor (large) residuals.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals that are small or perfectly reusable get strong bonuses.
    let pr = post_residual;
    let class = match pr {
        0 => -8.0,                       // perfect fit: best possible
        x if x < 10 => -4.0,             // tiny dead space, nearly perfect
        x if x % 10 == 0 => -2.5,        // decadal residual: highly reusable
        x if x % 5 == 0 => -1.2,         // half-decadal: decent
        _ => 0.0,                        // awkward residual
    };
    score += class;

    // Integer-division threshold on post_residual vs next_item_size:
    // reward residuals that can host the lookahead item exactly or with small waste.
    if next_item_size > 0 && next_item_size <= pr {
        let fits_next = (pr / next_item_size.max(1)) as f64;
        let waste = (pr % next_item_size.max(1)) as f64;
        score -= 3.0 * fits_next.min(2.0) + 2.0 - waste / cap;
        if pr == next_item_size {
            score -= 4.0; // lookahead consumes residual exactly
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // residual cannot host the next item: penalize proportionally to how close it was
        let miss = (next_item_size - pr) as f64;
        score += 1.5 * (1.0 - miss / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate handling: opening a fresh bin is expensive unless
    // current fit is bad or many bins already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = post_residual as f64 / cap; // large = bad fit in a fresh bin
        let mut penalty = 6.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count <= 1 {
            penalty -= 8.0; // no real alternative: new bin is fine
        }
        if fit_quality < 0.15 {
            penalty -= 2.0; // large item fills fresh bin well
        }
        // Harmonic class of the fresh-bin residual after placement
        if pr % 10 == 0 && pr > 0 {
            penalty -= 1.0;
        }
        score += penalty.max(-6.0);
    } else {
        // Prefer filling bins whose residual is closest to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 1.5 * tightness;
        // Prefer bins deviating from the mean residual (reduce variance of leftovers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev / cap;
    }

    // Modulo coupling: reward when item_size and residual share harmonic structure.
    if item_size % 10 == bin_residual % 10 && bin_residual != bin_capacity {
        score -= 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

