        score += 40.0 * (1.0 - (post_residual as f64) / usable_threshold);
    }

    // Reward near-perfect fits (small but nonzero residual is great).
    let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Reward exact fills.
    if post_residual == 0 {
