        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && (post_residual as f64) < usable_threshold {
            // Dead space blocks the lookahead too: extra penalty.
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; a new empty bin gets penalized.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight reward for filling fuller bins relative to the mean residual.
        score -= 5.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
