pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr);
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let leftover = pr - nx;
            score -= 12.0 * (1.0 - leftover / bin_capacity as f64);
            if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                score -= 8.0; // near-perfect two-item packing
            }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.15 * (nx - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: prefer the ones with least residual anyway (mild penalty)
    if fitting_bins_count > 2 {
        score += 0.05 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: if mean residual is high, prefer filling existing bins
    if mean_residual > item_size as f64 {
        score -= 0.10 * mean_residual;
    }

    // Time horizon: early in stream, keep bins flexible (penalize very low residual);
    // late in stream, allow aggressive compaction
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let flexibility_weight = 6.0 * (1.0 - progress);
    score += flexibility_weight * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item fits poorly anywhere (large item, high mean residual)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        // base cost of a fresh bin, discounted when streams are long and bins few
        let mut nb = 30.0 - 0.02 * total_items as f64;
        if open_bins_count > 0 {
            nb += 0.05 * open_bins_count as f64;
        }
        // a new bin is good if it would leave a big residual (roomy) vs poor fits
        nb -= 0.10 * waste_elsewhere;
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 10.0;
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let cap = bin_capacity as f64;

    // Base: penalize leftover space, with non-linear polynomial coupling to progress.
    let mut score = r * (1.0 + 2.0 * progress * r + 1.5 * progress * (1.0 - r) * (1.0 - r));

    // Perfect fit reward (smooth): strongly subtract near-zero post residual.
    score -= (1.0 - r) * (1.0 - r) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - r);
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            score -= 0.5 * (1.0 - r);
        } else {
            let gap = (nx - post_residual as f64) / cap;
            score += 2.0 * gap * gap * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.05 * (open_bins_count as f64 / (1.0 + mean_residual / cap).max(0.1)) * r;

    // New-bin candidate: make it slightly less attractive unless residual is large.
    if bin_residual == bin_capacity {
        score += 0.5 + 1.5 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (harmonic class: dead space <= 5)
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic class of post_residual via integer division thresholds
    let class = post_residual / 10; // 0..=10
    score -= (10 - class) as f64 * 2.0; // smaller classes (tighter bins) favored

    // Penalize dead space that cannot accommodate the next item (waste lookahead)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space: next item can't use it
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // next item fits exactly-ish in residual: reward chained packing
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 25.0;
            }
        }
    } else {
        // last item: minimize leftover aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits for the item
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // more attractive if open bins are fragmented (high mean residual spread)
        score -= (mean_residual / 4.0).min(30.0);
        // attractive late in stream when consolidation has less value
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
        // very attractive if no other bin leaves a good post-fit
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving residual in awkward zones (11..=19, 31..=39):
    // these rarely match common item sizes
    let pr = post_residual;
    if (11..=19).contains(&pr) || (31..=39).contains(&pr) {
        score += 8.0;
    }

    // Prefer bins whose residual is already below mean (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight preference for fewer open bins being consumed efficiently
    score -= 1.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals too small for the smallest item (1..=10)
    // are effectively unusable; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward using nearly-full bins (tight fits) to consolidate.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    if bin_residual != bin_capacity {
        score -= 3.0 + open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: it becomes dead space if next item is large.
        score += 4.0;
    }

    // Early in the stream, be more willing to open bins; later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (compact bins first).
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect chaining of two items into one bin).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            // Perfect 2-item fit: strong reward.
            score -= 60.0;
        } else {
            // Proximity bonus decaying with distance.
            score -= 30.0 * (-diff / 20.0).exp();
        }
        // Penalize post_residuals that are unusable for the next item
        // (dead space smaller than the smallest plausible item).
        if pr < nxt && pr > 0.0 {
            score += (nxt - pr) * 1.5;
        }
        // If next item fits too but not exactly, mild penalty for leaving
        // slack relative to mean residual.
        if pr >= nxt {
            score += (pr - nxt) * 0.3;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious,
    // keep large residuals in low-residual bins penalized.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (huge dead space or no open bin fits well). Penalize opening new
    // bins by default, scaled by how many open bins exist.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0 + 5.0 * open_bins_count as f64;
        let waste = post_residual as f64; // = capacity - item_size
        // Opening a new bin is good only if it wastes less than the
        // alternative would; approximate by comparing waste to mean residual.
        let waste_advantage = (mean_residual - waste).max(0.0);
        score += base_penalty - 2.0 * waste_advantage;
    }

    // Mild stream-phase adaptation: early on, be slightly more conservative
    // about tight fits (distribution unknown); later, trust lookahead more.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Penalize small unusable dead space (< next item size) but reward
    // post_residual that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or open bins are very full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 - 18.0 * fill_ratio - 10.0 * mean_fill;
        if post_residual < 15 {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already well utilized.
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 5.0;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Slight preference for bins below mean residual (spread large items).
    score += (bin_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = r * (1.0 + 0.35 * progress * progress) - 12.0 * rn * (1.0 - rn) * (1.0 - progress);

    // Penalize large dead space more than proportionally (quadratic in normalized residual)
    score += 18.0 * rn * rn;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - rn) * (1.0 - rn) * (10.0 + 15.0 * progress);

    // Lookahead coupling: bonus if next item fits in post_residual, penalty otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 4.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Mild dispersion penalty: prefer bins close to mean residual (balance)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * rn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction classes.
    let item_class = item_size / 10;                       // 1..=10
    let post_class = post_residual / 10;                   // dead-space granularity

    // Reward exact harmonic fits: post_residual divisible into useful classes.
    // A post_residual that is itself a "nice" size (multiple of 10) or small is good.
    let nice_fit = (post_residual % 10 == 0) as f64;
    score -= 12.0 * nice_fit;

    // Penalize dead space that no item class can use: post_residual < 10 is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Small-but-usable residual (10..=20) is good — many small items fit.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Perfect fit: zero waste gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the residual left behind accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic chain: post_residual % next_item_size small => likely another fit.
            let chain = (post_residual % next_item_size) as f64;
            score -= 10.0 - 0.3 * chain;
            if post_residual == next_item_size {
                score -= 15.0; // chains to an exact future fit
            }
        } else if next_item_size > post_residual {
            // Residual too small for the next item: penalize proportionally.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current
    // fit is terrible and the item is large (harmonic class 7+).
    if bin_residual == bin_capacity {
        let waste_here = (bin_capacity - item_size) as f64;
        let bad_local_fit = post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size && post_residual < 15);
        if bad_local_fit && item_class >= 7 {
            score -= 20.0; // prefer fresh bin for huge items that leave waste
        } else {
            score += 35.0 + 0.2 * waste_here; // keep filling open bins by default
        }
    }

    // Progress-based tightening: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Mean-residual coupling: when open bins are generally empty, discourage
    // leaving a scattered residual; when bins are tight, reward compacting.
    if mean_residual > 50.0 {
        score += 0.1 * (post_residual as f64);
    } else {
        score -= 0.1 * (post_residual as f64);
    }

    // Integer-division threshold on post class: mid-class residuals (30-60)
    // are the most reusable, mild reward.
    if post_class >= 3 && post_class <= 6 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (smallest item is 1, but useful threshold ~10)
    // are pure waste. Penalize unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Medium dead space (10..20) is risky: penalize mildly.
    else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fills relative to the item size (high fill ratio is good).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 30.0 + pressure * 10.0;
        // If the next item could combine better, slight discount for a fresh bin.
        if next_item_size > 0 && next_item_size <= post_residual.max(item_size) {
            score -= 5.0;
        }
    } else {
        // Reusing an existing bin relieves open-bin pressure.
        score -= pressure * 3.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only mildly, so tight fits dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: penalize proportional to waste.
        score += (post_residual as f64) * 0.3;
    }

    // Early in the stream, be more willing to open bins (score dampening
    // for new bins late in the stream is already handled via pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward when post_residual can still accommodate the next item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (next_item_size as f64);
        // Extra reward if after the next item the residual is small (tight chain).
        let chain_left = post_residual - next_item_size;
        if chain_left <= 10 {
            score -= 40.0;
        }
    }

    // Penalize dead space: post_residual too small for any plausible next item (min size 1, typical >= 10).
    if next_item_size > 0 && post_residual < next_item_size {
        // Waste penalty grows the smaller the leftover relative to next item need.
        score += 30.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Very small unusable residual: penalize strongly (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: capacity minus item, plus a mild opening cost.
        score = (bin_capacity - item_size) as f64 + 25.0;
        // If current bin would be a perfect or chained fit, new bin should lose (handled by big negative above).
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 200.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as stream progresses, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving large dead space relative to typical item scale.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        // Dead space is only truly wasted if the next item cannot use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 15.0 * dead;
        } else {
            // Reward leaving a gap that exactly (or nearly) hosts the next item.
            let gap_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * gap_fit * gap_fit;
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity and open bins are already numerous/crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 22.0;
        // But discount the penalty when bins are crowded and item is big.
        score -= 25.0 * crowded * big_item;
        // Late in the stream, slightly prefer consolidating into open bins.
        score += 10.0 * progress;
        // If the next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones
    // to reduce fragmentation; when few are open, spreading is cheaper.
    let open_pressure = (open_bins_count as f64).ln() / 10.0;
    if bin_residual != bin_capacity {
        score -= open_pressure * (bin_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // breaking ties toward slightly below-mean residuals for future flexibility.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small lookahead shaping: if the next item fits in the post-residual with
    // room to spare, slight bonus; if it barely fits, extra bonus (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core: quadratic waste penalty, mildly amplified as the stream progresses
    // (late in the stream, dead space matters more since fewer chances to fill it).
    let mut score = (pr * pr) / cap * (1.0 + 0.9 * progress);

    // Smooth cubic coupling: mid-sized leftovers are the worst (too big to ignore,
    // too small to be useful). Penalize via distance from a "useful" residual band.
    let useful = (next_item_size as f64 - pr).abs() / cap;
    score += 12.0 * useful * useful * (0.5 + progress);

    // Tight fits are excellent: reward small post_residual non-linearly.
    score -= 20.0 * (-pr / (0.25 * cap)).exp();

    // Last-chance bin: strongly favor using it (avoid opening a bin for one item).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive if the item is large (small post_residual)
    // or all existing fits are terrible. Penalize otherwise, softly increasing
    // with the number of open bins (bin proliferation).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 * open_pressure * (1.0 - fill) * (1.0 - fill);
        // If no open bin fits, opening is necessary: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Lookahead: if the next item could fill this bin's post_residual, opening is good.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1.0));
        }
    } else {
        // Existing bin: slight reward when its residual is below the mean
        // (prefer packing into already-tight bins, keep loose bins flexible).
        score += 3.0 * ((mean_residual - bin_residual as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted residual, scaled by fraction of capacity.
    let mut score = post;

    // Harmonic class of post_residual: residues mod 10 act as "waste classes".
    // Small residues (< 10) are nearly perfect fits -> strong reward.
    let residue = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if residue == 0 {
        score -= 12.0; // clean harmonic class, reusable by multiples of 10
    } else if residue <= 3 {
        score -= 4.0;  // near-perfect class
    } else if residue >= 7 {
        score += 8.0;  // awkward dead space class
    }

    // Integer-division thresholds: post_residual in (0,10) is nearly dead space
    // unless a small item arrives; discourage mid-range dead zones.
    let dead_zone = post_residual / 10; // 0..=10 class
    score += (dead_zone as f64) * 2.5;

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward when next item lands on a harmonic boundary.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        score += 6.0; // this bin likely becomes a dead bin
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score -= (mean_residual - post) * 0.5;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if post == cap && next_item_size > 0 {
            // empty-bin call: score is just capacity + bonuses; nudge so it
            // only wins when open bins have poor fits.
            score += (fitting_bins_count as f64) * 3.0;
        }
    }

    // Early stream: encourage keeping residuals harmonic (multiples of 10)
    // for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste -> heavy penalty.
    let dead_zone: f64 = 10.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Non-linear penalty for leaving a gap that cannot fit the lookahead item
    // while a slightly larger gap could have (poor lookahead fit).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    } else if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        // Reward preserving room for the next item.
        score -= 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size as f64).max(1.0);
    score -= (1.0 / (1.0 + fit_ratio)) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate (empty bin): make it attractive only when the fit is
    // poor or dead space would be created elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when current item is large.
        let mut new_bin_cost = 25.0;
        if item_size >= 50 {
            new_bin_cost -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // Large item followed by large item: fresh bin is fine.
            new_bin_cost -= 12.0;
        }
        score += new_bin_cost;
        // Empty bin has no dead space; slight structural bonus.
        score -= 3.0;
    }

    // Slight progression-awareness: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += post_residual as f64 * 0.3 * progress;

    // Tie-break toward bins with residuals close to the mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavy reward for minimal post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (this bin becomes perfectly filled next step).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: mild reward,
            // scaled by how tight the double-fill is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the remaining space: penalize dead space,
            // especially when it exceeds typical sizes.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
            if post_residual < 10 {
                score += 50.0; // unusable sliver
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced only if current bins are poor fits.
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 20.0;
        }
    }

    // Early in the stream, be more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (bin_capacity as f64) * 0.55;

    // Penalize large unusable gaps: if post_residual can't hold a typical item (>=10),
    // the space is dead — punish proportionally.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward when the next item fits exactly into post_residual,
    // penalize when post_residual nearly fits the next item (near-miss waste).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // (low mean residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / (bin_capacity as f64));
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 45.0 - 40.0 * crowding - 25.0 * scarcity;
    } else {
        // Prefer bins whose residual deviates favorably from the mean (below-mean
        // residual = well-utilized bin; reward selecting it).
        let dev = mean_residual - (bin_residual as f64);
        score += dev * 0.20;
    }

    // Time horizon: early in the stream, be conservative with new bins (spread items);
    // late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);
    score -= progress * 6.0;

    // Mild penalty for opening bins when many are already open (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 2.5 * (open_bins_count as f64);
    }

    // Small deterministic tie-breaker favoring lower residual bins.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: wasted space after placement (lower = tighter fit)
    let mut score = pr;

    // Non-linear quadratic penalty on wasted space, growing with stream progress
    score += 30.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Dead-space penalty: if the lookahead item cannot fit in the residual,
    // the remaining space is likely unusable — penalize, more so late in stream.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * (1.0 + 2.0 * progress);
        } else {
            // Reward bins whose residual accommodates the next item
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin so that
    // decent existing fits win, but the quadratic waste term can override it
    // when all open bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
        // If no open bin fits at all, opening is necessary — soften penalty
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins that bring residual closer to the mean
    // (balance load across open bins), scaled non-linearly.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + 0.5 * progress);

    // Slight preference for filling already-open bins as open-bin count grows
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residuals are dead space.
    let dead_threshold = bin_capacity / 10; // 10 units
    if post_residual < dead_threshold {
        score -= 25.0; // near-perfect fill, reward strongly
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0; // decent fill
    } else {
        score += (post_residual as f64) * 0.05; // penalize large leftover
    }

    // Modulo-class coupling: post_residual that pairs with next_item_size is golden.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < dead_threshold {
            score -= 12.0;
        } else if next_item_size > post_residual {
            // next item cannot go here; this residual is stranded
            score += 6.0;
        }
        // harmonic complement: post_residual + next_item_size close to capacity multiples
        let sum = post_residual + next_item_size;
        if sum == bin_capacity {
            score -= 15.0;
        }
    }

    // Integer-division thresholds on residual class
    let class = post_residual / (bin_capacity / 20); // 5-unit buckets
    score += (class as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin mildly, unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * (open_bins_count as f64);
        // but if item is huge relative to typical residual, new bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 12.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.02;

    // Prefer bins below mean residual (tighter bins fill faster)
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item + 9.0 {
        // gap too small for any realistic item: heavy penalty
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins
        score += 15.0 + 8.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // but if the next item fits perfectly in a fresh bin, mild discount
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 20.0;
        }
    } else {
        // placing into an open bin reduces open-bin pressure slightly
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would be blocked by post_residual, penalize a little.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            score -= 80.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot fit here; penalize proportional to wasted lookahead.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: prefer leaving residuals close to
    // the mean (balanced bins), penalize outliers.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere (handled above) — make empty-bin less attractive generally.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if item is large and next item also large, a fresh bin is fine.
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 2 {
            score -= 120.0;
        }
    }

    // Mild pressure to keep the number of open bins low early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    // Later in the stream, residual waste matters more, so weight grows.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear quadratic coupling: penalize mid-range residuals super-linearly
    // (dead space that's neither reusable nor tight).
    let mid = norm_pr - 0.5;
    score += 12.0 * mid * mid * (1.0 + progress);

    // Cubic term: strongly reward near-zero post_residual (tight fit).
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if pr >= nx {
            // Next item fits: reward, scaled by how snugly.
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit: slight penalty proportional to shortfall.
            score += 2.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but more acceptable late in stream
    // when open bins are fragmented (mean residual low).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 6.0 - 4.0 * progress - 2.0 * fragmentation;
    }

    // Tie-break: prefer bins with residual close to item (smooth coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * tightness * tightness;

    // Small normalization against open-bin count pressure.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "usable slots"
    let harmonic_class = post_residual % 10;
    if harmonic_class == 0 {
        score -= 6.0; // aligned residual is highly reusable
    } else if harmonic_class <= 3 {
        score -= 2.0;
    } else if harmonic_class >= 7 {
        score += 5.0; // awkward leftover
    }

    // Integer division thresholds: post_residual buckets by quarter capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 8.0; // nearly full bin, great placement
    } else if post_residual >= 3 * quarter {
        score += 10.0; // item barely dented the bin: wasteful
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let base = 0.5 * cap;
        score = cap as f64 - 10.0
            + (open_bins_count as f64).sqrt() * 2.0
            + if fitting_bins_count == 0 { -30.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size > bin_capacity - item_size { -8.0 } else { 0.0 }
            - base * 0.0;
    }

    // Progress modulation: later in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Mean residual coupling: if this bin is far from mean residual, slight penalty
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical items are wasted.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver
    }
    // Gap that cannot fit the lookahead item is also semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (best-fit coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // and penalize opening yet another bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if residuals are fragmented.
        score += 30.0 + mean_residual * 0.15;
    }

    // Mild preference to place into bins whose residual is near mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact-ish match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: next item exactly fills the bin after this one.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that neither fits next item nor is useful.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 50.0;
    }

    // Reward bins tighter than the mean (well-packed bins get priority).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // But allow new bin early in stream or if open bins are all loose.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 35.0;
        }
    }

    // Slight preference for filling larger fraction of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Penalize exact-fit slightly less than waste; reward perfect closure strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else {
        // Dead space penalty grows if residual becomes unusable for typical items.
        let dead = (post_residual as f64 - 10.0).max(0.0);
        score += 0.15 * dead;
    }

    // Lookahead: if next item fits into post_residual, this placement is doubly good.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
    }
    // If next item would NOT fit here but this bin is the only fit, prefer using it now.
    if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor the sole fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // late in stream, allow more aggressive filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> favor bins below mean
    // (balance residuals) to leave larger bins for future large items.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
        // Opening a new bin is costly when many bins are already open.
        if bin_residual == bin_capacity {
            score += 2.0 + 0.5 * open_bins_count as f64;
        }
    } else if bin_residual == bin_capacity {
        // Only one bin open: new bin fine if current one is crowded.
        score += 1.0;
    }

    // Slight preference for bins whose residual is close to item (min fragmentation).
    score += 0.1 * (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling: penalize large residuals more as stream progresses
    let coupling = norm_pr * norm_pr * (0.5 + progress);
    score += 40.0 * coupling;
    // reward tight fits (small post_residual) with a smooth bonus
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);
    // lookahead: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 10.0 * (gap / cap) * (0.5 + progress);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // discourage opening new bins late in the stream
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (20.0 + 30.0 * progress);
    // mean residual alignment
    score += 0.2 * (pr - mean_residual) * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins left in "good" residue classes
    // (multiples of 10, small residues) are more reusable for typical items.
    let pr = post_residual;
    let class = if pr == 0 { 0.0 }
        else if pr % 10 == 0 { 1.0 }
        else if pr % 5 == 0 { 2.0 }
        else if pr <= 9 { 4.0 }   // unusable sliver
        else { 3.0 };
    score += class * 3.0;

    // Penalize dead space: residuals below 10 can never be filled.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 4.0;
    }

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 12.0 - (waste as f64).min(12.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - pr).min(20)) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate: prefer keeping items in existing bins when mean residual
    // suggests space is plentiful; open new bins when open bins are nearly full.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score += 6.0 - 20.0 * tight;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is required
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    } else {
        // reward tightening a bin relative to mean residual
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Fractional capacity alignment: item sizes near half or full capacity pair well.
    let frac = item_size as f64 / cap;
    if (frac - 0.5).abs() < 0.05 || frac > 0.9 {
        score -= 2.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 200.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        // Semi-dead space: only items <= post_residual can use it; penalize
        // proportionally to how unlikely a future item fits.
        score += 8.0 * (20.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 150.0;
    } else {
        // Usable gap: mild reward for tight fit (low post_residual).
        score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for next item: penalize if it's also below min-size dead zone.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new one.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += 4.0 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; prefer filling bins below mean residual.
    let this_residual = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (this_residual - mean_residual);
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin offers a good fit (this bin is empty, so post_residual is large).
    if bin_residual == bin_capacity {
        // Base handicap so we only open new bins when open bins score badly.
        score += 90.0 + 5.0 * open_bins_count as f64;
        // But if many bins are open and residuals are fragmented, opening a
        // fresh large bin is fine.
        if open_bins_count > 6 && mean_residual < 30.0 {
            score -= 100.0;
        }
        // If the item is large relative to capacity, fresh bin is natural.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Early-stream smoothing: be slightly more permissive early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (tiny post_residual).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the next item: penalize proportionally.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Compare against mean residual: bins with unusually low residual are
    // nearly full -> prefer filling them (keep big holes in other bins).
    if (post_residual as f64) < mean_residual {
        score -= 0.6 * (mean_residual - post_residual as f64);
    } else {
        score += 0.4 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit
    // the item; the empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            score -= 10.0;
        }
    }

    // Slight preference for using already-open bins as bins accumulate.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: polynomial coupling of post_residual with stream progress.
    // Later in the stream, tight fits (small post_residual) matter more.
    let mut score = pr * (1.0 + 1.5 * progress * pr_norm);

    // Reward near-perfect fits with a smooth quadratic bonus.
    score -= 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful for typical items,
    // expressed smoothly: penalty peaks when residual is small but nonzero.
    let dead = (pr_norm * (1.0 - pr_norm)).min(0.25);
    score += 10.0 * (0.25 - dead);

    // Last-chance bin: strongly favor using it (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = (pr - nxt).abs() / cap;
        score += fits_next * (-15.0 * gap) - (1.0 - fits_next) * 5.0 * (1.0 - gap);
    }

    // Slight preference to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    // New-bin candidate: neutral-ish score anchored to mean residual so that
    // opening a new bin only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.3 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes rewarded
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post <= 5 {
        score -= 25.0;
    } else if post <= 10 {
        score -= 10.0;
    }

    // Modulo classes: residuals that form "harmonic" slots (divisible into common small sizes)
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut harm_bonus = 0.0;
    for h in harmonics.iter() {
        if post >= *h && post % h == 0 {
            harm_bonus += 8.0;
        }
        // residual that can still host next_item_size exactly
        if next_item_size > 0 && post == *h && (*h % next_item_size == 0 || next_item_size % h == 0) {
            harm_bonus += 12.0;
        }
    }
    score -= harm_bonus;

    // Penalize dead space: post_residual too small for likely next items
    if next_item_size > 0 && post > 0 && post < next_item_size.min(80) {
        score += 6.0;
    }
    // Reward when this bin exactly hosts the next item too
    if next_item_size > 0 && post == next_item_size {
        score -= 18.0;
    }
    if next_item_size > 0 && post >= next_item_size && post - next_item_size <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size.min(bin_capacity)) as f64;
            let _ = best_possible;
            score += 10.0 * (open_bins_count as f64).sqrt();
        }
        // open new bin early when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Prefer tighter bins generally (small residual before placement)
    score += 0.15 * (bin_residual as f64 / cap);

    // Encourage balancing residual mass across bins
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual closely matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    // Pressure from open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize if post_residual is a dead gap that next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }

    // Mild preference to fill bins below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins have large residuals that would waste space.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 1.5;
        // If no other bin fits well, allow new bin more readily.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 0.55 * bin_capacity as f64
            + 0.30 * mean_residual
            - 6.0 * (fitting_bins_count == 0) as i32 as f64
            + 2.0 * (open_bins_count as f64).sqrt();
        return base;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: item + next item exactly fill the bin.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item still fits after this placement: reward tight couplings.
            let slack = (post_residual - next_item_size) as f64;
            score -= 28.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit in the post residual: penalize dead space,
            // more strongly when the leftover is small-but-unusable.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(60.0);
        }
    }

    // Prefer bins whose residual is already below the mean (tight bins get packed first).
    score += 0.25 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Early stream: be slightly greedy toward tight fits; later: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit
    let tightness = item_size as f64 / bin_capacity as f64;
    let residual_frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - residual_frac * 10.0).max(0.0);
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - progress * 0.5);
            // extra reward if next item exactly fills the remainder
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // leftover too small for the next item -> mild penalty scaled by dead space
            score += 4.0 + residual_frac * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // Penalize spreading across many open bins when few fit options exist
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Coupling with global mean residual: prefer bins whose residual is below mean
    // (i.e., fuller bins) to consolidate waste
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: early on, be more willing to open new bins (penalize tight fits less),
    // later, consolidate aggressively
    score *= 1.0 - 0.15 * progress;

    // Mild penalty for opening a new bin when decent fits exist,
    // but relax that penalty early in the stream
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 + 0.5 * open_bins_count as f64;
        score += open_penalty * (0.4 + 0.6 * progress);
        // but if the item is large and would leave a clean residual, new bin is fine
        if item_size >= 60 && next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Favor bins that keep residual in "usable" bands (>= next typical sizes)
    if residual_frac > 0.0 && residual_frac < 0.1 {
        score += 6.0 * (1.0 - progress);
    }

    // Small jitter-free deterministic tie-breaker based on fill level
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items as f64);
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Reward tight fits: post_residual^2 normalized, stronger late in stream
    score -= (pr_norm * pr_norm) * (8.0 + 24.0 * progress);

    // Reward filling a bin completely
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small to be useful for typical items:
    // smooth trough around residual ~ small values
    let small_dead = if pr < 10.0 { 0.0 } else { ((pr - 10.0) / cap).powi(2) };
    score += small_dead * 5.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 15.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            // penalize leaving residual that blocks the next item
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild competition bonus scaled by scarcity
        score -= 5.0 / fitting_bins_count as f64;
    }

    // Prefer bins below mean residual (keep balanced residuals) - smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Penalize opening a new bin, more so early and when few bins open
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but if no existing bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: multiples of 10 are "harmonic" residuals
    // that future items (sizes 1..100) are more likely to fit well.
    let harm = post_residual % 10;
    score += match harm {
        0 => -18.0,          // perfectly harmonic residual: strongly reward
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        5 => -4.0,           // half-harmonic: mildly attractive
        _ => 1.5,
    };

    // Integer-division class: post_residual / 10 buckets
    let bucket = post_residual / 10;
    score += if bucket <= 1 {
        12.0 // tiny dead space (<20) is nearly unusable
    } else if bucket <= 3 {
        -6.0 // sweet spot 20..40
    } else {
        0.0
    };

    // Coupling with lookahead: if next item fits harmonically into post_residual,
    // reward heavily (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = post_residual - next_item_size;
            let chain_harm = chain % 10;
            score -= match chain_harm {
                0 => 22.0,
                5 => 10.0,
                _ => 4.0,
            } as f64;
            // exact fill of remaining space by next item is ideal
            if chain == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot follow in this bin: penalize if we also waste space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Next-item size class thresholds (modulo arithmetic on lookahead)
    if next_item_size >= 50 {
        // big lookahead: prefer bins with large residual harmony
        score -= (post_residual / 25) as f64 * 5.0;
    } else if next_item_size >= 20 && next_item_size < 50 {
        score += if post_residual % 20 == 0 { -5.0 } else { 2.0 };
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has neutral-ish score so it wins
    // only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64 + 8.0;
        // late in the stream, opening new bins is fine; early on, prefer reuse
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Tight fits are excellent: small post_residual relative to item
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Spread pressure: many open bins with high mean residual -> prefer filling
    // existing bins harder.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-full bins are excellent: reward very tight fits strongly.
    if post_residual <= 5 {
        score -= 45.0;
    }

    // Non-linear waste curve: penalize gaps that no typical item can use,
    // scaled by how "orphaned" the gap is relative to capacity.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 25.0 {
        score += (25.0 - gap) * 1.8;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win when the fit
    // elsewhere would be poor. Penalize the fresh bin moderately, more so
    // when existing bins are still roomy.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.4;
    } else {
        // Reward bins whose residual is close to what the item consumes
        // (tight packing), i.e. low bin_residual relative to item.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= (1.0 - tightness) * 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (perfect pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item cannot fit in post residual but would fit elsewhere,
    // slight penalty for fragmenting space.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Stream progression: late in the stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - gap / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after pairing
            let pair_left = post_residual - next_item_size;
            score -= 30.0 - (pair_left as f64) * 0.4;
        } else {
            // next item cannot follow into this bin: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: strongly prefer tight fits
        score += (post_residual as f64) * 0.5;
    }

    // Compare residual against mean residual across open bins
    score -= (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 55.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base score.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    // (items are 1..100, so residuals < 1 are zero; residual in (0, ~10) is hard to fill).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: opening a bin is costly when many bins are open
    // and residuals elsewhere are large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 4.0 * openness * (1.0 - progress);
        // If mean residual is large, prefer using existing bins.
        score += 0.15 * mean_residual;
    } else {
        // Mild bonus for using bins whose residual is above average (balance residuals).
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.05 * diff;
    }

    // Time-horizon term: early in the stream, be more conservative (penalize fragmentation);
    // late in the stream, prioritize just fitting the item.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Small tie-breaker favoring fuller bins.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize large dead space more than linearly (quadratic in normalized residual)
    score += 12.0 * fit * fit * (1.0 - progress);

    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 15.0 * (-pr / (0.25 * cap)).exp();

    // Penalize bins far below mean residual (fragmented outliers)
    score += 0.5 * (mean_residual - pr).abs();

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - nxt / cap);
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mildly discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit), scaled.
    let mut score = post;

    // Harmonic class of post_residual: dead-space classes modulo 10.
    // Small residues (<10) are "perfect" classes; large residues in awkward
    // classes (e.g. 11..19, 31..40) are hard to fill later -> penalize.
    let cls = post_residual % 10;
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 6.0; // near-perfect fit class
        } else if cls == 0 {
            score -= 3.0; // round residual, easy to pair
        } else if cls <= 2 {
            score -= 1.0;
        } else if cls >= 6 && cls <= 8 {
            score += 4.0; // awkward mid-class dead space
        }
    }

    // Lookahead coupling: reward if next item fits into post_residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt = next_item_size as f64;
        let nxt_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.5 * (cap - nxt) / cap * 10.0;
        score += 0.3 * nxt_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for next item -> dead space likely
        score += 0.5 * post;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    // or the item is large and would waste little.
    if bin_residual == bin_capacity {
        // New bin baseline: fresh bin has full capacity.
        let mut nb = 0.35 * cap; // moderate penalty to prefer reusing bins
        // Large items (harmonic top class) pack cleanly in fresh bins.
        if item as u32 > bin_capacity / 2 {
            nb -= 0.15 * cap;
        }
        // If many bins open and mean residual is high, prefer reuse -> raise nb.
        nb += 0.25 * mean_residual;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            nb += 10.0;
        }
        // Late in stream, consolidate.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            nb += 12.0;
        }
        return nb;
    }

    // Slight bonus for filling bins proportionally deep.
    score -= 0.1 * (cap - bin_residual as f64) / cap * 10.0;

    // Mild penalty when many bins compete: prefer tightest, already handled,
    // but break ties with residual closeness to item size.
    score += 0.05 * (bin_residual as f64 - item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit is perfect; avoid overflow of penalty meaning
    } else if post_residual < 10 {
        // gap below the smallest typical item is dead space -> strong penalty
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // small but potentially usable gap: mild penalty scaled by tightness
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual as f64 <= mean_residual * 0.25 {
        score -= 20.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // penalize leaving a gap just barely too small for the next item
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        if miss <= 10.0 {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strong reward to use the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current fit is poor.
    if bin_residual == bin_capacity {
        // neutral baseline; slightly high so only genuinely bad fits trigger opening
        score += 10.0 + 0.3 * mean_residual;
    } else {
        // reward tightness relative to capacity
        score -= 0.2 * (bin_residual - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that nothing small could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual stays close to the mean (balanced packing).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter existing bins (smaller residual before placement).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave a near-perfect second fit, extra reward.
    if next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) <= 5 {
        score -= 10.0;
    }
    // Penalize if next item is large and this placement wastes too much space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline penalty for opening a new bin, decaying with stream progress.
        score = 0.0;
        score += 15.0 * (1.0 - progress);
        // If several bins fit, opening a new bin is rarely good.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        }
        // If the mean residual is large, open bins have slack; penalize new bin.
        score += mean_residual * 0.3;
        // Small items don't justify new bins.
        if item_size <= 30 {
            score += 25.0;
        }
        // Very large items with poor fit prospects elsewhere: allow new bin.
        if item_size > 70 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer placing into bins with residual close to item (minimize fragmentation).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so tight fits are favored
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling with stream progress: early on, tolerate loose fits;
    // later, penalize residual more aggressively (quadratic ramp).
    let prog_term = 0.5 + 2.0 * progress * progress;
    score *= prog_term;

    // Smooth reward when post residual aligns with next item size (lookahead fit)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-diff / 25.0) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Penalize creating dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * ((open_bins_count as f64).ln() + 1.0) * (1.0 - norm_pr);

    // New-bin candidate: make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 10.0 * progress - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual too small to ever be useful for typical items.
    let min_item = 1u32;
    let dead = post_residual < min_item.max(next_item_size.min(100));
    if dead && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: bucket post_residual by integer division (capacity fractions).
    // Residuals in the class [51..100] are "half-full reusable"; [1..50] are risky scraps.
    let class = post_residual / (bin_capacity / 4).max(1); // 0..=4 harmonic class
    score -= 8.0 * class as f64;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // chain fit
        } else if next_item_size < post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 10.0; // next item won't fit here; keep this bin's residual coherent
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer bins already below mean residual (consolidation).
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well (poor fits everywhere)
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0 || fit_ratio < 0.5;
        if poor_fit_elsewhere {
            score -= 30.0;
        } else {
            score += 45.0;
        }
        // Early stream: opening bins cheap is fine.
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Modulo arithmetic tie-breaker on post_residual: favor residuals in friendly classes
    // (multiples of common item sizes leave combinable space).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(100)) {
        // gap too small even for the smallest possible item or the next item
        score += 60.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap can't hold the lookahead item
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward leaving room for the next item
        score -= 15.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    let pressure = open_bins_count as f64 * (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else if (bin_residual as f64 - item_size as f64) > mean_residual + 20.0 {
        // wasteful placement relative to average residual
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - lookahead_gap / bin_capacity as f64);
    }

    // Penalize dead space that no plausible item (1..100) can fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin fine if item is large
        }
    }

    // Late-stream pressure: consolidate as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Small residual that still fits the next item is great.
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to waste.
            let waste = (post_residual as f64) / (next_item_size as f64).max(1.0);
            score += 8.0 * waste.min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when existing fits are poor
    // (large post_residual) or many bins are already open with slack.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        score += 30.0 * (1.0 - poor_fit);
        score += 3.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin is attractive for chaining large items
        }
    }

    // Global slack pressure: many open bins with high mean residual -> discourage
    // spreading; instead favor filling existing bins harder.
    let slack = mean_residual / bin_capacity as f64;
    score += 10.0 * slack * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: early in stream, be conservative (keep bins balanced);
    // late in stream, pack greedily (reward high fill).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - tightness);

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, quadratically coupled with stream progress
    let mut score = pr as f64 * (1.0 + 0.8 * progress) + 60.0 * x * x * (0.5 + progress);

    // Smooth non-linear interaction: post residual vs progress polynomial
    let coupling = x * progress * (1.0 - progress) * 40.0;
    score += coupling;

    // Reward tight fits (small post residual) more strongly later in the stream
    let tight = (1.0 - x).powi(3);
    score -= tight * 30.0 * (0.4 + 0.6 * progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here: penalize moderately, more early on
            score += 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // slight penalty to break ties among many fitting bins toward tighter ones
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual close to item size (best-fit flavor), smooth
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * diff * diff;

    // New-bin candidate: penalize opening fresh bins unless current residuals are large
    if bin_residual == bin_capacity {
        let mean_x = mean_residual / cap;
        score += 45.0 * (1.0 - mean_x) * (1.0 - 0.5 * progress);
    } else {
        // mild preference to fill already-open bins relative to mean residual
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev * dev;
    }

    // Encourage consolidation: fewer open bins favored slightly
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo-10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "usable" sizes (>=10) get rewarded; tiny slivers penalized
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr < 10 {
        score += 25.0; // dead space sliver
    } else {
        // reward residuals in friendly harmonic classes (multiples of 10)
        if class == 0 {
            score -= 12.0;
        } else {
            score += (10 - class) as f64 * 0.8; // distance to next multiple of 10
        }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // harmonic match: next item leaves again a multiple-of-10 residual
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 8.0;
            }
            if pr2 < 10 && pr2 > 0 {
                score += 10.0;
            }
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but avoid opening new bins
    // when open bins fit well (post_residual small relative to capacity).
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64);
        // late in stream, prefer reusing open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // if many open bins already, discourage new bin
        score += open_bins_count as f64 * 1.5;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.8 {
        score -= 10.0;
    }

    // Prefer bins below mean residual (concentrate waste in few bins)
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range awkward gaps (10..=20) get a mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }
    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual tightly matches the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward the mean residual: avoid leaving bins far below average fill.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item could use the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit the leftover, penalize leaving a small gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 25 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64;
        // But allow opening a new bin if the item would leave a large usable
        // residual and existing fits are all poor (post_residual tiny).
        if post_residual >= 20 && item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 80.0 + 60.0 * tightness; // tighter follow-up fit => better
        } else {
            // Penalize leaving a residual that the next item cannot use
            // unless the residual is small enough to be "dead space" anyway.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * waste;
            if post_residual < 10 {
                score -= 20.0; // tiny dead space is acceptable
            }
        }
    }

    // Compare post_residual against mean residual: leaving less than the mean
    // indicates this bin was used efficiently relative to others.
    score += 0.5 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of the current bin; make it
        // attractive only if the item leaves a large residual in any existing bin.
        score = 60.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0; // a fresh bin still supports the next item well
        }
        if item_size >= 90 {
            score -= 30.0; // huge items are fine anywhere
        }
    }

    // Penalize very poor fits: item barely fits leaving awkward mid-size residual.
    if post_residual > 10 && post_residual < 30 && next_item_size > post_residual {
        score += 25.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize small dead space that nothing (min size 1..~10) can reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys a bin that could have held the next item
            score += 10.0 * (1.0 - fill);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let pull = 40.0 * large_item * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln();
        score += 55.0 - pull;
    }

    // Global state: many open bins with slack -> prefer consolidating into them.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Late stream: squeeze harder, avoid leftover gaps.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.4 * t * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits, quadratically penalized residual.
    let mut score = 1.0 - (1.0 - rn) * (1.0 - rn);

    // Non-linear coupling: residual value depends on stream progress.
    // Early: waste is cheap-ish, keep flexibility; Late: waste is costly.
    let progress_coupling = 2.0 * progress * (1.0 - progress); // peaks mid-stream
    score += rn * rn * (1.0 + 3.0 * progress) - progress_coupling * rn * (mean_residual / cap);

    // Perfect fit reward (smooth bump around zero residual).
    score -= 8.0 * (-r / 6.0) * (-r / 6.0).exp();

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        score += 0.02 * gap;
        score -= 2.0 * (-gap / 4.0) * (-gap / 4.0).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize spreading too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Mild bonus for using a partially filled bin vs fresh bin.
    if bin_residual < bin_capacity {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), tiny slivers (1..=5),
    // and modular classes mod 10 get tiered treatment.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 25.0; // near-perfect: sliver is effectively dead but fit was tight
    } else if pr % 10 == 0 {
        score -= 15.0; // round residual: likely reusable by common item sizes
    } else if pr % 5 == 0 {
        score -= 8.0;
    } else {
        score += 6.0; // non-harmonic residual: less reusable
    }

    // Integer-division thresholds: residual bands
    let band = pr / 20; // 0..=5
    score += band as f64 * 3.0; // larger leftover costs more, but sub-linearly

    // Lookahead coupling: does the next item land exactly in this residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // chain completion
        } else if next_item_size < pr {
            let nxt_res = pr - next_item_size;
            if nxt_res % 10 == 0 {
                score -= 12.0;
            } else if nxt_res <= 5 {
                score -= 10.0;
            } else {
                score += 2.0;
            }
        } else {
            score += 10.0; // next item won't fit here: residual likely stranded
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Penalize wasting a mostly-empty bin when many bins are open.
    if bin_residual as f64 > 0.8 * cap {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good consolidator.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Early stream: be greedy with best fits; late stream: close bins aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (pr == 0) as i32 as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin has room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
