pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-residual relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if (post - next).abs() < 0.5 {
            // Perfect chain: this bin will be exactly completed by the next item.
            score -= 60.0;
        } else if next <= post {
            // Next item fits here: partial reward proportional to how much it fills.
            let fill = next / post;
            score -= 25.0 * fill;
            // Extra reward if after next item residual is small (near-perfect chain).
            let chain_res = post - next;
            score -= 15.0 * (1.0 - chain_res / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space, scaled by gap.
            score += 0.4 * (next - post).min(60.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent existing fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        // New bins are more acceptable early in the stream or when bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 30.0; // existing bins are all tight, new bin is good
        }
    }

    // Mild waste penalty: large item into large residual wastes packing potential.
    if item_size as f64 > bin_residual as f64 * 0.9 && bin_residual < bin_capacity {
        score -= 5.0; // near-full utilization of the bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
