pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = rn * rn * (1.0 + 2.0 * progress) + 0.35 * rn;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more
    let coupling = rn * progress * (1.0 - progress) * 4.0;
    score += 1.5 * coupling;

    // Penalize post residuals that are too small to be useful later,
    // but only mildly; reward mid-range residuals that stay usable
    let next_n = next_item_size as f64 / cap;
    if next_item_size > 0 {
        if next_n <= rn {
            score -= 0.8 * (1.0 - (rn - next_n)) * (1.0 - progress); // lookahead fits: reward
        } else {
            score += 0.6 * (next_n - rn) * (0.5 + progress); // lookahead won't fit: penalize
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 * (1.0 - rn) + 0.5;
    }

    // Compare against mean residual: bins with residual far above mean waste space
    let mean_n = mean_residual / cap;
    score += 0.4 * (rn - mean_n).abs() * (0.5 + 0.5 * progress);

    // Slight preference to keep number of open bins bounded early on
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral-ish score so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = 0.9 + 0.5 * progress + 0.3 * (1.0 - rn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // determine how reusable the leftover space is for typical item sizes.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: leftover too small for any plausible item (1..=100).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 60.0; // nearly dead space
    }

    // Modulo / integer-division harmonic classes on post_residual.
    let cls = post_residual / 10; // decade class 0..10
    score += match cls {
        0 => 40.0,            // 1..9 : nearly useless
        1 => 25.0,            // 10..19
        2 => 12.0,            // 20..29
        3 => 5.0,             // 30..39
        4 => 0.0,             // 40..49 : sweet spot for medium items
        5 => -3.0,            // 50..59
        6 => -2.0,            // 60..69
        7 => 2.0,             // 70..79
        8 => 8.0,             // 80..89
        _ => 15.0,            // 90..99 : only tiny items fit
    };

    // Lookahead coupling: reward residuals that can host next_item_size exactly
    // or within a tight harmonic window.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 80.0; // sets up a perfect next fit
            } else if slack < 10 {
                score -= 30.0;
            } else if slack < 30 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else (large item, tight fit).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Prefer open bins generally; new bin competes only for big items.
        score += 55.0 - 40.0 * fit_quality;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild preference to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (10.0 - 20.0 * frac).max(0.0) * 0.2;

    // Small phase-dependent tightening: late in stream, waste hurts more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += frac * progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are nearly unusable
    // given item sizes >= 1 but typically larger; penalize them heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 19 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 20.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: prefer reusing existing bins when several are open,
    // but allow new bins early in the stream when fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if post_residual <= 19 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 9 {
            score += 15.0; // would create another dead gap
        }
    }

    // New-bin candidate handling: empty bin gets a mild default cost that
    // scales with how many bins are already open and stream progress,
    // so it wins only when all open-bin fits are bad (high dead space).
    if bin_residual == bin_capacity {
        score = 40.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // If no open bin fits at all, new bin is the only choice anyway.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild mean-residual coupling: bins deviating far above mean residual
    // are less attractive (keep bin residuals balanced).
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Two-step lookahead matching ---
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect match: post_residual == next_item_size -> strongly reward.
        let gap = (post - nxt).abs();
        score -= 25.0 * (-gap / 20.0).exp();

        // Penalize dead space: post_residual too small for next item (wasted space).
        if post < nxt {
            score += (nxt - post) * 0.8;
        } else {
            // Slight reward for leaving enough room for the next item.
            score -= 3.0;
        }

        // If next item fits tightly too (two consecutive tight fits), extra reward.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score -= (mean_residual - post_residual as f64) * 0.15;

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New empty bin candidate: penalize unless it enables a clean two-item sequence ---
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            // Opening a fresh bin that can host the next item too can be OK early on.
            score -= (1.0 - progress) * 25.0;
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space that is too small for the next item but nonzero.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        // Reward leaving room exactly usable by the lookahead item.
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    } else {
        // Last item: reward filling the bin as much as possible.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of bins can fit the item.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item is large and current residuals are small.
            let lookahead_pressure = next_item_size as f64 / bin_capacity as f64;
            let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
            score -= 20.0 * lookahead_pressure * mean_tightness;
        }
    }

    // Dynamic time horizon: later in the stream, prefer consolidating into few bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (filling emptier bins keeps tight bins free).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize dead space more strongly as stream progresses
    let dead_penalty = pr * pr * (1.0 + 3.0 * progress) + pr * pr * pr * (2.0 + 4.0 * progress);
    score += dead_penalty * bin_capacity as f64;

    // Reward tight fits (small post_residual) with a smooth quadratic discount
    let tight_fit = (1.0 - pr) * (1.0 - pr);
    score -= 2.5 * tight_fit * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty when bin is far below mean residual (fragmentation risk), smooth cubic
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 1.5 * dev * dev * dev;

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let gap_norm = gap / bin_capacity as f64;
        // Smooth reward when post_residual is close to next item size (perfect reuse)
        let reuse = 1.0 - (gap_norm.abs()).min(1.0);
        score -= 4.0 * reuse * reuse;
    } else {
        // End of stream: pure waste minimization, extra weight on small residuals
        score += 1.0 * pr * pr * bin_capacity as f64;
    }

    // Slight preference for consolidating into fewer bins as bins accumulate
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small moduli: reward residuals
    // that sit in "reusable" classes (large enough chunks for typical items).
    let pr = post_residual as i64;
    let cls4 = pr % 4;
    let cls10 = pr % 10;

    // Reward residuals aligned to common item-size fractions (items 1..100,
    // often multiples of 5 or 10): a residual that is itself a plausible
    // future item size is valuable.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Dead-space penalty via integer division thresholds: residuals in
    // (0, 10] can hold almost nothing -> strong penalty.
    if pr > 0 && pr <= 10 {
        score += 25.0;
    } else if pr > 10 && pr <= 20 {
        score += 8.0;
    }

    // Lookahead harmony: if the next item fits exactly or well into the
    // post residual, reward heavily.
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 30.0; // perfect harmonic pairing
        } else if ni < pr {
            let slack = pr - ni;
            if slack <= 5 {
                score -= 18.0;
            } else if slack <= 15 {
                score -= 9.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; mildly penalize tight residuals
            // that will strand the bin.
            if pr < ni && pr <= 25 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // are genuinely poor. Its post_residual == capacity (large), so add a
    // fixed opening cost that tight fits in open bins can overcome.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheap; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Prefer bins with residuals far below mean (consolidate big gaps).
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Mild pressure against proliferating open bins.
    score += 0.4 * open_bins_count as f64;

    // Modulo-4 harmonic micro-adjustment: residuals ≡ 0 mod 4 align with
    // even-sized items and pack more cleanly.
    if cls4 == 0 && pr > 0 {
        score -= 1.5;
    }
    // Penalize awkward cls10 residues 1..2 (nearly unusable slivers).
    if pr > 0 && (cls10 == 1 || cls10 == 2) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for typical future items
    // (assumed >= 1, but small gaps < 20 are hard to reuse).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0; // strong penalty for tiny gaps
    }

    // Reward near-perfect fits heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.1;

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open bins pressure.
        score += 60.0 + pressure;
        // If this is the last chance bin, opening new is attractive.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
    } else {
        // Existing bin that is the last chance: strong bonus to use it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Reward using bins with lower residual (tighter packing).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 25.0;
    }
    // Penalize leaving a gap that cannot fit the next item (dead space w.r.t. lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
