pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 18.0;

    // Penalize dead space: post-residual below typical small-item threshold is wasted.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // post-residual too small for next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        }
        // Perfect pairing: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, tighter packing matters less, mild bonus for new bins with big items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins (penalize opening new ones).
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline plus penalty scaled by open bins & mean residual.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // Allow new bin when it's late and item is large (few future packing options).
        if progress > 0.7 && item_size > 60 {
            score -= 60.0;
        }
        // If only one fitting bin exists, discourage the new bin.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    } else {
        // Prefer bins with residual closest above item (best-fit flavor) via fit_ratio,
        // plus small penalty when this bin's residual far exceeds mean residual
        // (keeping "flexible" bins open for other items).
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear shaping (favor small dead space)
    let mut score = post + 40.0 * (x * x) - 30.0 * (x * x * x);

    // Polynomial coupling of post residual with stream progress:
    // early on, tolerate larger residuals; late, punish them more.
    let coupling = 25.0 * (1.0 - progress) * x - 60.0 * progress * x * x;
    score += coupling;

    // Fit quality: reward near-perfect fills smoothly.
    let tightness = 1.0 - x;
    score -= 45.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 55.0 * (0.5 + 0.5 * progress);
    }

    // Dead-space penalty relative to mean residual: bins far below mean residual
    // leave awkward gaps; smooth quadratic deviation.
    let dev = (mean_residual - post) / cap;
    score += 20.0 * dev * dev;

    // Lookahead: if next item fits into post residual, reward; else smooth penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 18.0 * (1.0 - nx / cap);
        } else {
            score += 10.0 * ((nx - post) / cap) * ((nx - post) / cap);
        }
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.8 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space classes modulo capacity quarters
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score -= 30.0,            // very tight fill, excellent
        1 => score -= 10.0,            // decent
        2 => score += 5.0,             // mediocre
        _ => score += 15.0,            // large dead space
    }

    // Exact-fit bonus via modulo arithmetic
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0; // residual divisible into small items
    } else if post_residual < 10 {
        score -= 25.0; // unusable sliver = effectively perfect
    }

    // Penalize residuals that no typical next item can use (harmonic class of next item)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0; // cannot host next item anyway
        } else if post_residual == next_item_size {
            score -= 40.0; // perfect lookahead chain
        } else if post_residual % next_item_size == 0 {
            score -= 20.0; // next item tiles the residual harmonically
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing else fits well
        let desperation = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score = (bin_capacity - item_size) as f64 + 50.0 - desperation;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    // Mild global pressure: as stream progresses, discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score -= 0.10 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 range) are pure waste. Penalize hard when the
    // gap falls below a "usable" threshold, scaled by stream position.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * (8.0 + 6.0 * progress);
    }

    // Reward perfect or near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins that are tighter than average
    // (below-mean residual => bin already well filled).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.15;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow more freedom.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.2;

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead (k=2): if the next item would fit exactly in the post
    // residual, reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 2 {
                score -= 20.0;
            } else {
                score -= 5.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover gap: mild penalty for
            // creating a stranded gap.
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when existing bins would be badly fragmented
    // (post_residual tiny but nonzero) or when the item fits poorly
    // everywhere. Otherwise keep new bins slightly unattractive to force
    // packing into open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && (post_residual as f64) < dead_threshold;
        let many_open = open_bins_count as f64 > 8.0;
        if poor_fit {
            score -= 12.0; // better to start fresh than strand a gap
        } else if many_open && post_residual as f64 > bin_capacity as f64 * 0.5 {
            score -= 3.0; // spread out when bins are plentiful and fit is loose
        } else {
            score += 10.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // slack after also fitting the next item
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    }

    // Penalize unusable dead space (< 10) unless it is zero
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits -> strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins below mean residual (tighter bins) slightly
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Early stream: prefer filling existing bins; late stream: allow new bins for tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual perfectly matches next item
        let base = 40.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score += 5.0;
        } else {
            score += base;
        }
    }

    // Mild preference for opening new bins when many bins are open and mean residual is low
    if bin_residual == bin_capacity && open_bins_count > 4 && mean_residual < 20.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin: fine, but waste is absolute
    }
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // awkward leftover zone
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit this bin anyway, mild bonus for using this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is penalized normally, but less when existing residuals
        // are large (poor fits likely) or when this bin is the only fit.
        let mut new_bin_score = 20.0 - 25.0 * fragmentation;
        if fitting_bins_count == 1 {
            new_bin_score += 55.0; // don't open a new bin when an existing one barely fits
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 5.0; // big items coming: fresh capacity has value
        }
        score = new_bin_score;
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight preference for bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling: penalize mid-range dead space more as stream progresses
    let dead_penalty = (norm_post * (1.0 - norm_post)).powi(2) * (1.0 + 3.0 * progress);
    score += 12.0 * dead_penalty;

    // Reward tight fits more strongly later in the stream
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).clamp(0.0, 1.0);
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_post);
    }

    // Penalize bins deviating from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * cap);

    // Lookahead coupling: reward residual that can fit next item smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 5.0 * fit_frac * (1.0 - fit_frac) * 4.0;
    }

    // Mild preference for consolidating into fewer bins early
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands
    let pr = post_residual as u32;
    let class = pr / (bin_capacity / 10); // 0..=10 harmonic class
    // Reward low classes (tight fits) super-linearly
    score -= (10 - class as f64) * (10 - class as f64) * 1.5;

    // Perfect fit dominates
    if pr == 0 { score -= 1000.0; }
    // Small dead space classes (1..=5) are nearly useless
    else if pr <= 5 { score += 40.0; }

    // Modulo coupling: does post_residual align with next item size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits here too: strong reward, scaled by leftover after that
            let after2 = pr - next_item_size;
            score -= 60.0 + (after2 as f64).sqrt() * 5.0;
            // harmonic alignment: pr mod next_item_size small => reusable space
            let m = pr % next_item_size;
            score -= (next_item_size as f64 - m as f64).min(m as f64) * 2.0;
        } else {
            // next item cannot use this residual: penalize proportional to gap
            score += (next_item_size - pr) as f64 * 0.8;
        }
        // lookahead size class (integer division by 10)
        let nclass = next_item_size / 10;
        if nclass >= 5 && pr < next_item_size { score += 10.0; }
    }

    // New-bin candidate: only prefer when residual is fully fresh AND current bin would leave bad class
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 120.0;
        // worth it if item is large and would otherwise fragment a bin
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 { score -= 90.0; }
        if fitting_bins_count == 0 { score -= 200.0; }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    } else {
        // penalize using bins that are already tight when other options exist
        if fitting_bins_count == 1 {
            // last chance: reward strongly to avoid opening a bin
            score -= 80.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    // many open bins: encourage filling existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual in (0, 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize leaving gaps that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward gaps that can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bins pressure: prefer bins that reduce fragmentation when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild bonus for filling a large fraction of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
