pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size
    let tightness = if item_size > 0 { item_size as f64 / bin_residual.max(1) as f64 } else { 0.0 };
    score -= 12.0 * tightness;

    // Penalize dead space that can't fit typical small items (min size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += 2.0;
        }
    }

    // Time horizon: late in stream, consolidate; early, allow spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: make it slightly unattractive unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 6.0;
        // Exception: big items early are fine in a fresh bin
        if item_size > 60 {
            score -= 10.0;
        }
        // If this item leaves a huge gap in any bin anyway, fresh bin is fine
        if post_residual > 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for placing into a nearly-full bin when a better spread exists? No — prefer fullness:
    score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base preference for tight fits: reward small post_residual non-linearly
    let tight = 1.0 - (post / cap);
    score -= 8.0 * tight * tight;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep residual flexible; late, prefer filling bins hard.
    let flex = post / cap;
    score += (1.0 - progress) * 6.0 * flex * flex;
    score -= progress * 4.0 * (1.0 - flex) * (1.0 - flex);

    // Penalize dead space below the smallest plausible item (smooth trough)
    let dead = ((post - 10.0) / cap).max(0.0);
    score += 5.0 * dead * dead;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Mild penalty when bin residual is far from mean residual (imbalance)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        // but allow new bin late in stream when open bins are fragmented
        if open_bins_count > 3 && progress > 0.7 {
            score -= 8.0;
        }
    }

    // Slight penalty for proliferation of open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall into?
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50

    // Penalize dead space in "wasted" harmonic classes (tiny unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward leaving residuals in highly reusable classes (multiples of ~10/25)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: post_residual in [10, 25) is good for small items
    let pr_class = post_residual / 25; // 0..4 harmonic band
    match pr_class {
        0 => score -= 5.0,          // 0..25: tight fill, good
        1 => score -= 2.0,          // 25..50: decent
        2 => score += 0.0,          // 50..75: mediocre
        _ => score += 6.0,          // 75..100: wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward when next item can still fit (keeps chain going), scaled by closeness
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize if we waste a nearly-empty bin's potential
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * mean_residual;
        // But if item is large and fits snugly in a fresh bin, opening is fine
        if item_size >= half {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals less when many bins are open (consolidation)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight progression-aware tightening: as stream advances, favor tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (dead space = post_residual < 10)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (post_residual close to 0 but >= threshold handled above)
    if post_residual > 0 && post_residual < 15 {
        score -= 10.0;
    }

    // Open bins pressure: discourage spreading across many bins when alternatives exist
    score += 0.35 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if current item is large and would leave big gap elsewhere, new bin is fine
        if item_size >= 50 {
            score -= 20.0;
        }
        // If mean residual across open bins is small (they're all tight), new bin reasonable
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit in the gap: penalize leaving that gap
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins get filled first)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late in stream: be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 50.0;

    // --- 2-step lookahead: exact match between post_residual and next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: keep chain alive
            score -= 8.0;
            // Reward leaving enough room for a possible second follow-up item
            let twice_next = 2 * next_item_size;
            if post_residual >= twice_next {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit: post_residual becomes dead space
            // Penalize proportionally to wasted capacity
            let dead = post_residual as f64;
            score += dead * 0.35;
            // Extra penalty for tiny unusable slivers
            if dead < 10.0 {
                score += 25.0;
            }
        }
    } else {
        // Last item: just fill as tightly as possible
        score -= 20.0;
    }

    // --- Relative to mean residual: prefer bins that are already fuller ---
    let mean = mean_residual;
    if (bin_residual as f64) < mean {
        score -= 6.0; // fuller-than-average bin -> consolidate
    } else {
        score += 3.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // make it costly, but cheaper if current item is large and lookahead is large
        let large_item = item_size >= 60;
        let big_next = next_item_size >= 60;
        let mut new_bin_cost = 30.0;
        if large_item {
            new_bin_cost -= 8.0;
        }
        if big_next {
            new_bin_cost -= 5.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += progress * 10.0;
        // Many open bins with high mean residual -> discourage new bin
        if open_bins_count > 3 && mean > 40.0 {
            new_bin_cost += 10.0;
        }
        score += new_bin_cost;
    }

    // Mild pressure against leaving medium dead space even when lookahead fits
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness: reward small post-residual relative to item
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 / (1.0 + tightness);

    // Penalize dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post-residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Prefer fuller bins when many bins are open
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * (open_bins_count as f64).sqrt();

    // Global mean residual coupling: if this bin is much fuller than average, favor it
    score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time horizon: early in stream, be more willing to open new bins (keep options open)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    // New-bin candidate (empty bin): accept early or when fit is poor elsewhere
    if bin_residual == bin_capacity {
        let open_penalty = 18.0 * (1.0 - progress); // cheaper to open early
        score = open_penalty + 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // room for the next item too
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the only fitting bin lightly
        }
    } else {
        // late in stream, avoid opening bins: push open-bin scores down
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress and post-residual fraction
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64 / bin_capacity as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling: quadratic + cubic shaping of post residual,
    // weighted by stream progress (tight packing matters more later in the stream).
    let poly = pr * pr * (1.0 - pr) + 0.5 * pr * pr * pr;
    score += progress * poly * cap * 2.0;

    // Smooth interaction between post_residual and mean residual: penalize bins whose
    // post-residual deviates upward from the fleet mean (wasted space relative to others).
    let dev = (pr - mean_residual / cap).abs();
    score += dev * dev * cap * 1.5;

    // Lookahead coupling: smooth reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_q = 1.0 - (gap / cap).min(1.0);
        score -= fit_q * fit_q * next_item_size as f64 * 0.8;
    }

    // Last-chance bonus: smooth sigmoid-like reward when this bin is the only fitting one.
    if fitting_bins_count == 1 {
        let tight = 1.0 - (post_residual as f64 / cap);
        score -= 10.0 + 8.0 * tight;
    }

    // Mild penalty for proliferating bins late in stream (encourages consolidation).
    score += (open_bins_count as f64).ln1p() * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: capacity split into
    // C / gcd classes. Residuals in "nice" classes (multiples of 10 or 5)
    // are more reusable, so reward them (subtract).
    let nice = |r: u32| -> f64 {
        if r == 0 { 0.0 }
        else if r % 10 == 0 { 18.0 }
        else if r % 5 == 0 { 9.0 }
        else if r % 2 == 0 { 4.0 }
        else { 0.0 }
    };
    score -= nice(post_residual);

    // Penalize tiny dead space that nothing (min size ~1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // fraction of post_residual consumed by next item
            let f = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * f;
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin leaves
    // very bad post_residual or bin is already tight.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual < 15 && post_residual > 0 {
            score -= 35.0; // opening fresh is fine when fill is near-perfect
        }
    }

    // Prefer filling bins that are already relatively full
    // (low residual relative to mean residual across open bins).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Coupling with mean residual: if this bin is much emptier than average,
    // deprioritize it (keep emptier bins for future items).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.15 * dev; // dev negative -> subtract, favor fuller bins
    }

    // Modulo-4 harmonic class on item_size: items in classes matching
    // residual class combine to round residuals, slight reward.
    if post_residual % 4 == 0 && item_size % 4 == 0 {
        score -= 3.0;
    }

    // Early in stream: be slightly conservative, keep bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals in the "unusable gap" band
    // (small, likely to never be filled) get a heavy nonlinear penalty.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny sliver: pure dead space
        } else if post_residual <= 25 {
            score += 40.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
        } else if post_residual < 10 && post_residual > 0 {
            score += 60.0;
        }
        // Gap exactly matching the lookahead item is excellent.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
        // Gap too small for any plausible item (min size 1..10 band unknown,
        // but penalize gaps below a conservative threshold).
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: best possible outcome.
        score -= 50.0;
    }

    // Reward tight fills relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spawning new ones.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax it when no existing bin fits well (last-chance logic).
        let mut new_bin_penalty = 45.0 + 12.0 * open_pressure;
        if fitting_bins_count == 0 {
            new_bin_penalty -= 70.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: avoid wasting the last-chance bin only
            // if this item would leave a bad gap there.
            new_bin_penalty += 10.0 * (1.0 - fill_ratio);
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild bonus when it's below mean residual (tighter than average).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Last-chance bin: strong bonus to use it rather than strand it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item can fit the post-residual, reward;
    // if the post-residual is smaller than next item but nonzero, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is superlinearly good).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + 5.0 * (5 - post_residual) as f64;
    } else {
        score += (post_residual as f64).powf(1.3) * 0.15;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly,
    // penalize when next item can't fit the leftover (dead space likely).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - next).abs();
        if next <= pr {
            if gap == 0.0 {
                score -= 300.0;
            } else {
                score -= 60.0 / (1.0 + gap / 10.0);
            }
        } else {
            // next item cannot fit: leftover likely wasted
            score += (next - pr) * 0.4;
        }
        // Bonus if post_residual can hold next item and still leave usable space
        if pr >= next && pr - next <= 20.0 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average when mean is high.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mild preference for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Early in stream: be pickier about dead space (long horizon to regret it).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 + 0.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items: post_residual
    // below the minimum item size (1) is impossible, but small post_residual
    // relative to the known next item is wasted.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            // Next item cannot use this leftover space -> penalize proportionally.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Next item fits perfectly in the leftover -> big reward.
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the item
    // is large relative to residual or no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // Large items fit better in a fresh bin; reward slightly.
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill_fraction;
        // Early in the stream, opening bins is cheaper (more future use of them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open already, discourage adding more.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below average (denser bins) when the fit
    // is not perfect, to consolidate fragmented space.
    if post_residual > 0 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 4.0 * dev;
    }

    // Global time horizon: as the stream nears its end, prefer using existing
    // residual capacity since leftover space is wasted anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score -= 5.0 * (progress - 0.8) / 0.2 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild preference for filling bins with more accumulated content.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual, modulated by progress
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with cubic term
    score -= 30.0 * (1.0 - prn).powi(3) * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * (1.0 - progress);

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap) * (0.3 + 0.7 * progress);
        } else {
            score += 8.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many bins early
    score += 2.0 * open_bins_count as f64 * progress / (total_items.max(1) as f64) * 10.0;

    // New-bin candidate handling: penalize opening a new bin unless the fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) - 10.0 * prn * prn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into dead-space classes via modular arithmetic.
    // Residuals < 10 are pure dead space (item sizes >= 1, but small residuals rarely reusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Class by post_residual / 10: low classes (0..=2) are more likely dead space.
    let pr_class = post_residual / 10;
    score += match pr_class {
        0 => 20.0,
        1 => 8.0,
        2 => 3.0,
        _ => 0.0,
    };

    // Reward tight fits (small post_residual) but only if not creating dead space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Harmonic residue of post_residual mod 10: multiples of 10 leave cleaner space.
    let harm = (post_residual % 10) as f64;
    score += 0.6 * harm;

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward when next item is large (hard to place later).
            if next_item_size >= 50 {
                score -= 8.0;
            }
        } else {
            score += 10.0;
            // Penalize more if next item is small and would be stranded.
            if next_item_size <= 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if item is huge and no good fit exists, new bin becomes attractive:
        // (the comparison against real bins' dead-space penalties decides this).
        if item_size >= 70 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Perfect pairing potential in fresh bin.
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual deviates from mean toward tighter side.
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmenting further;
    // prefer placing into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave another dead gap, discourage.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // reward small gap: next item fits snugly
            score -= 200.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here: penalize proportionally to wasted residual
            score += 50.0 * (post_residual as f64 / cap);
        }
    }

    // Penalize large dead space relative to mean residual of open bins
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit_exists = next_item_size > 0 && post_residual as f64 >= next_item_size as f64
            && (post_residual as f64 - next_item_size as f64) < 10.0;
        let mut new_bin_penalty = 250.0 + 200.0 * progress;
        if tight_fit_exists { new_bin_penalty += 400.0; }
        // allow new bin if item is large and residual would leave tiny useless sliver
        let sliver = pr < 10.0 && pr > 0.0;
        if sliver { new_bin_penalty -= 500.0; }
        score += new_bin_penalty;
    }

    // Mild preference for tighter existing bins overall
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space that is hard to reuse (post_residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: this is the only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 15.0;
        } else {
            score += 6.0;
        }
        // If next item is large and this bin would leave it stranded, penalize.
        if next_item_size > post_residual && post_residual < next_item_size / 2 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bins get a moderate baseline so they are
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Global state coupling: many open bins with large mean residual -> reuse bins.
    if mean_residual > item_size as f64 * 1.5 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    if open_bins_count > 10 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Mild preference for bins tighter than average.
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = pr;
    // smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * (1.0 - t);
    score += 40.0 * poly;
    // reward tight fits more strongly as stream progresses
    score -= 30.0 * fit * fit * (0.5 + t);
    // penalize dead space relative to mean residual, non-linearly
    score += 10.0 * (norm_pr - mean_residual / cap).abs() * (1.0 + t * t);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }
    // lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let room = norm_pr - nx;
        if room < 0.0 {
            score += 15.0 * (-room) * (1.0 - t);
        } else {
            score -= 8.0 * room * (1.0 - room) * t;
        }
    }
    // new-bin candidate: penalize opening a bin when others fit, more so early on
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 30.0 + 40.0 * (1.0 - t);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let pr = post_residual;
    let class = pr % 10;
    let div = pr / 10;

    // Reward post-residuals that form "clean" harmonic classes (multiples of 10, 20, 25, 50)
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        if class == 0 {
            score -= 8.0 * (div as f64).min(5.0);
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 50 == 0 {
            score -= 6.0;
        }
        // Penalize awkward dead space below smallest plausible pairing size
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
            // harmonic coupling: next item leaves a clean class too
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, penalize
    // opening new bins when many open bins exist with slack
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 12.0
            + 0.05 * open_bins_count as f64
            - 0.02 * mean_residual;
    }

    // Slight preference for tight bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.03 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 10 {
        // gap too small for any plausible item -> dead space
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    } else {
        // usable gap: mild reward proportional to how well next item could fit
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            // gap exists but next item won't fit: mild penalty
            score += 8.0;
        }
    }

    // Reward tight fits relative to bin size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation; but allow new bins when fits are scarce.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin gets a base cost so it is only
    // chosen when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 55.0 - 30.0 * progress;
        // if no open bin fits, new bin is fine
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // lookahead: if next item is large, a fresh bin is more attractive
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (bin becomes perfectly closed for next item).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fit
        } else if post_residual > next_item_size {
            let slack = pr - nx;
            // penalize leftover slack that likely becomes dead space
            score += slack * 0.6;
            if slack < 10.0 { score += 8.0; } // near-match bonus still
        } else {
            // next item won't fit here: bin closes anyway, small reward for tightness
            score -= (20.0 - (pr / 10.0)).max(0.0);
        }
        // lookahead relative to mean residual
        if pr < mean_residual * 0.5 { score -= 5.0; }
        if pr > mean_residual * 1.5 { score += 5.0; }
    } else {
        // last item: just prefer tightest fit
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Mild preference for keeping bin count low early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    // Discourage wasting a very full bin when a new bin would do equally well.
    if bin_residual == bin_capacity {
        score += 12.0; // new-bin candidate baseline penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: residuals too small for the smallest item (1..=100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fits exactly well too.
            let chain = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins relative to global mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, tolerate opening new bins (exploration);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score -= 20.0 * (1.0 - progress);
        score += 35.0 * progress;
        // Discourage new bins when many are already open with slack.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Existing bins: slightly favored late.
        score -= 5.0 * progress;
    }

    // Mild penalty for very large item into nearly-empty existing bin (waste potential).
    if item_size as f64 > 0.6 * bin_capacity as f64 && bin_residual == bin_capacity {
        score -= 5.0; // large items start fresh bins well
    }

    // Coupling: when open bin count is low, keep bins open longer (avoid fragmentation).
    score += 1.5 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let progress_weight = 0.35 * progress * (1.0 - progress) * 4.0 + 0.25 * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap;

    // Penalize residuals that cannot fit the lookahead item (smooth via ratio)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_gap = (ni - pr).max(0.0) as f64;
        let fit_ok = (pr - ni).max(0.0) as f64;
        score += 0.5 * fit_gap * (1.0 + progress);
        score -= 0.3 * fit_ok * (1.0 - progress);
    }

    // Last-chance bonus: strongly reward using a bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Dampen preference for bins when many bins are open and mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: mildly penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity / 4 quantization
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Penalize post_residuals in "dead zone" classes: small leftovers that
    // can rarely host future items (mod arithmetic on post_residual).
    let dead_class = post_residual % quarter;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if dead_class == 0 {
        score -= 8.0; // perfectly quarter-aligned leftover
    }

    // Reward tight fits: exact fill or near-exact fill
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use leftover; penalize proportionally to waste
        score += 6.0;
    }

    // Harmonic half-class: bins with residual above half are flexible; keep them
    if bin_residual > half {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; becomes attractive only if all open bins
        // would leave tiny dead space
        let best_possible_waste = if item_size <= bin_capacity { (bin_capacity - item_size) % quarter } else { quarter };
        score = 55.0 + best_possible_waste as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild pressure toward consolidating bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins with residual close to the mean (harmonic balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect closure: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small nonzero post_residual (unusable slivers that future
        // items are unlikely to fill): dead space in (0, 10] is worst.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) * 0.5;
        }
    }

    // Dead-space risk relative to the lookahead item: if the next item
    // exactly fits the post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 30.0; // leaves room for the lookahead
    } else if next_item_size > 0 && next_item_size > 0 {
        score += 15.0; // lookahead cannot use this gap
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // scaled by how many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 80.0 + 6.0 * open_bins_count as f64;
        // Allow opening a fresh bin if it would absorb a large item cleanly.
        if item_size >= 60 {
            score -= 70.0;
        }
    }

    // Mild preference toward tighter bins (small residual) among equals.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: as the stream progresses, discourage
    // spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (slack_after_next as f64 + 1.0).recip();
            if slack_after_next == 0 {
                score -= 10.0; // perfect chain fill
            }
        } else {
            // next item won't fit here; penalize leaving medium dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.15;
    }

    // Slight preference to fill older bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals (dead space), reward medium leftovers
    // that can still host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * item_size as f64;
    }

    // Lookahead: if the next item could exactly use the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize leaving residual close to but below next size
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly attractive
    // only when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = bin_capacity as f64 - 0.5 * fit_ratio * bin_capacity as f64
            - 4.0 * crowded
            - 10.0 * (1.0 - progress);
        // discourage new bin when a decent fit exists elsewhere
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 20.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into fuller bins (larger item_size relative to capacity).
    let pressure = mean_residual / bin_capacity as f64;
    score += 8.0 * pressure * (1.0 - fit_ratio);

    // Time horizon: late in the stream, be more conservative (favor tight fits even more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (smooth gating via lookahead)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (0.5 + 0.5 * progress);
    } else {
        // Last item: pure tightness reward
        score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Reward near-perfect fits with smooth sigmoid-like term
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // Penalize opening new bins when open bins exist, more so early on
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score += 30.0 + 0.4 * open_bins_count as f64 + 0.3 * spread;
        // Allow new bin late in stream if it would be nearly filled
        let fill_ratio = item_size as f64 / cap;
        score -= 55.0 * fill_ratio * fill_ratio * progress;
    }

    // Mild penalty for bins deviating from mean residual (keep bin pool homogeneous)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by common item sizes (or small classes) are more reusable.
    let cap_frac = (bin_capacity as f64) * 0.5;
    let small = post_residual <= 10; // dead space class
    let harmonic = post_residual % 10; // modulo class on decade grid

    // Penalize dead space heavily: residual below the minimum item size is wasted.
    if small {
        score += 60.0;
    } else {
        // Reward residuals that are "harmonic" (divisible by 5/10 grid)
        if harmonic == 0 {
            score -= 8.0;
        } else if harmonic <= 2 {
            score -= 3.0;
        } else {
            score += harmonic as f64 * 0.7;
        }
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 20; // 0..5 classes
    score -= (class as f64) * 5.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (post_residual - next_item_size) / 10;
            score -= 10.0 - (nxt_class as f64) * 2.5;
        } else {
            // next item can't use this bin's leftover: mild penalty scaled by overshoot
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    } else {
        // last item: prefer tightest fit regardless of reusability
        score = post_residual as f64;
        if small { score += 10.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's only
    // chosen when open bins have bad fits (large residuals / dead space).
    if bin_residual == bin_capacity {
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        let base = 55.0 - 15.0 * progress; // slightly cheaper to open bins early
        score = base + (item_size as f64) * 0.1;
        // if next item is huge, opening fresh may be wise
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += ((post_residual as f64) - mean_residual) * 0.25;

    // Fractional capacity coupling: reward filling past half capacity in one go.
    if (bin_residual as f64) >= cap_frac && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is risky since items are >= 1 but often larger.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is very good.
    let pressure = (open_bins_count as f64) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or when an existing bin gives a decent fit.
        score += pressure;
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
    } else {
        // Existing bin: slight reward scaled by how far below mean residual it is
        // (prefer bins that would become tighter than average).
        score -= ((mean_residual - post_residual as f64).max(0.0)) * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would fit in post_residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // residual can host next item; reward closeness of the fit
            let gap = pr - nxt;
            score -= 40.0 / (1.0 + gap);
        } else {
            // residual cannot host next item; penalize dead space scaled by how far off
            let dead = nxt - pr;
            score += 1.5 * dead.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        if next_item_size > 0 {
            // opening a fresh bin is good if item is large or next item pairs well with capacity
            if item_size as f64 > 0.6 * bin_capacity as f64 {
                score -= 20.0;
            }
            if (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 5.0 {
                score -= 15.0;
            }
        }
        // more open bins with small residuals -> new bin more attractive
        if mean_residual < 10.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual below mean (concentrate fragmentation)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early stream: be more liberal with opening bins (better packing later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer opening new bins to keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 + 40.0 * (1.0 - progress));

    // Crowding: many open bins with low mean residual -> prefer filling existing bins
    if open_bins_count > 2 && mean_residual < item_size as f64 * 1.5 {
        score -= 10.0;
    }
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is close to mean residual (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fits favored (low post residual)
    let mut score = pr;

    // Non-linear coupling: quadratic post-residual penalty weighted by stream progress.
    // Later in the stream, dead space matters more (less chance to fill it).
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Smooth interaction: post residual vs mean residual deviation
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - norm_pr);
        } else {
            score += 4.0 * (1.0 - pr / next_item_size.max(1) as f64) * progress;
        }
    }

    // Smooth penalty on opening new bins when many are open: cubic in open count
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        score += 15.0 * open_norm * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect-fit reward (harmonic class 0: post_residual == 0).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    // Residuals in (0, 10) are near-dead; small odd residuals are worst.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Harmonic pairing: does post_residual exactly accommodate the lookahead item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 {
                score += 8.0; // chain would create dead space
            } else {
                score -= 6.0; // chain fits, mild reward
            }
        } else {
            score += 4.0; // lookahead cannot follow here
        }
    }

    // Modulo-class logic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) remain reusable; odd residuals fragment.
    let r = post_residual;
    if r % 10 == 0 {
        score -= 5.0;
    } else if r % 5 == 0 {
        score -= 2.0;
    } else if r % 2 == 1 {
        score += 3.0;
    }

    // Integer-division thresholds: quarter/half classes of residual capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if r >= half {
        score -= 4.0; // roomy bin, flexible
    } else if r >= quarter {
        score += 1.0;
    } else if r > 0 {
        score += 3.0; // tight sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post fit would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 5.0; // still better to use the last chance
        }
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // But if item is large and would leave a clean harmonic residual, allow it.
        if item_size >= half && item_size % 10 == 0 {
            score -= 10.0;
        }
        // If no open bin fits well (this bin is among few fitting), soften penalty.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.7 {
        score -= 5.0;
    }

    // Stream progression: early on, be pickier about dead space (long horizon);
    // late, prioritize closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.15 * (1.0 - progress)); // residual waste matters more early
    if progress > 0.8 && post_residual < 15 {
        score -= 6.0; // near end, close bins aggressively
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // good candidate to absorb the item (keeps residuals balanced).
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for the smallest plausible item are wasted.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward exact and near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Fit quality relative to bin: prefer filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving a gap that the lookahead item could have used but won't fit elsewhere well.
    if next_item_size > 0 && post_residual >= next_item_size {
        // this bin stays useful for the next item -> mild reward
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap is stranded relative to lookahead -> mild penalty
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let waste = post_residual as f64;
        if waste < 0.5 * (bin_residual as f64) {
            score -= 50.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_pressure = 15.0 + 25.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) + 10.0 * progress;
    if bin_residual == bin_capacity {
        // New empty bin candidate: base cost plus pressure; only attractive when
        // the item would leave big dead space in every fitting bin.
        score += new_bin_pressure;
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 25.0; // big items justify a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can pair item with lookahead
        }
    } else {
        // Slight preference to keep using existing bins when mean residual is high.
        if mean_residual > 30.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist, more so early in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 120.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin is good if it can host the next item too
        }
    }

    // Slight preference for filling larger bins tighter as stream progresses.
    score += pr * (0.05 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Wasted space that next item cannot use: penalize proportionally.
            let waste = post_residual as f64;
            let usable = if next_item_size <= bin_residual { next_item_size as f64 } else { 0.0 };
            score += 0.15 * waste * (1.0 - usable / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full on average
        // or very fragmented.
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base penalty so new bins are chosen only under pressure.
        score += 20.0 + 10.0 * avg_fragmentation + 2.0 * open_pressure.sqrt();
        // Late in the stream, avoid opening new bins even more.
        score += 15.0 * progress;
        // But if next item is large and residuals are tiny, new bin becomes attractive.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Prefer filling bins that already deviate below mean residual (consolidate waste).
    if bin_residual as f64 > mean_residual {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for bins whose residual becomes a "hard" leftover (odd small values).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Core: non-linear polynomial in normalized post residual,
    // strongly penalizing mid-range waste, mildly tolerating near-zero.
    let mut score = 4.0 * x * x - 2.0 * x * x * x + 0.5 * x;

    // Stream progress coupling: as the stream advances, waste becomes costlier.
    score += progress * (x * x) * cap * 0.05;

    // Reward tight fits (small post residual) with a smooth bump.
    score -= (1.0 - x) * (1.0 - x) * 2.0;

    // Lookahead: if next item fits the post residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if post >= nx { 1.0 } else { 0.0 };
        let slack = ((post - nx) / cap).max(0.0);
        score -= fits_next * (1.0 - slack) * (1.0 + progress);
        // Penalize post residual that is large but just below next item (dead space).
        let dead = if post < nx { (nx - post) / cap } else { 0.0 };
        score += dead * dead * cap * 0.03;
    }

    // Last-chance bonus: only one fitting bin; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 + progress;
    }

    // New-bin candidate: penalize slightly so it wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 2.0 + mean_residual * 0.02 + (open_bins_count as f64).sqrt() * 0.3;
    } else {
        // Mild preference for filling bins that deviate below mean residual (denser bins).
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: dead space that only small items can fill
    // Class 1: post_residual in 1..10 -> nearly unusable dead space, penalize
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Class 2: post_residual divisible by 10 -> likely fillable by small items, reward
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 15.0;
    }
    // Class 3: post_residual divisible by 5 -> moderately fillable
    else if post_residual > 0 && post_residual % 5 == 0 {
        score -= 7.0;
    }
    // Class 4: awkward odd residuals
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 5.0;
    }

    // Integer division thresholds on post_residual
    let dead_zone = post_residual / 10; // 0..=10
    match dead_zone {
        0 => score += 20.0,          // tiny residual: dead space
        1 | 2 => score += 8.0,       // 10-29: hard to fill
        3 | 4 => score -= 5.0,       // 30-49: useful
        5 | 6 => score -= 10.0,      // 50-69: very useful
        _ => score -= 12.0,          // 70+: spacious
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 60.0 - tight * 0.3;
        } else if next_item_size <= post_residual + 5 {
            // near miss: slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when few bins open or many items left
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * progress - 2.0 * open_bins_count as f64;
        // if next item is large and current item is small, prefer new bin for pairing
        if next_item_size >= item_size.saturating_mul(2) && item_size <= 30 {
            score -= 25.0;
        }
        // avoid opening new bins when mean residual is large
        if mean_residual > 40.0 {
            score += 20.0;
        }
        return score;
    }

    // Tight fit bonus: residual close to item size means good packing
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 25.0;

    // Prefer bins whose residual is close to item size (best-fit coupling)
    let fit_gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += fit_gap * 0.2;

    // Congestion: many open bins -> encourage consolidation into existing bins
    score -= (open_bins_count as f64).min(20.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 stream),
    // but calibrate a dead-space threshold around the smallest typical item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual as f64) * 2.0;
    }

    // Penalize mid-range gaps that likely cannot absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual after placement still fits the lookahead item
    // (chain-friendly placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely the best option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number of open bins.
        score += 15.0 + open_bins_count as f64 * 1.5;
        // But if the current item leaves a large residual in an existing bin
        // relative to mean residual, a fresh bin becomes relatively better:
        // emulate by softening the penalty when mean residual is small.
        if mean_residual < 20.0 {
            score -= 25.0;
        }
    } else {
        // Slight preference for bins tighter than average (waste minimization).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference for larger items going into larger-residual bins.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly/well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_waste / (bin_capacity as f64));
            // Perfect 2-item chain completion bonus
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item cannot chain here: penalize proportionally to leftover dead space
            score += 6.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    } else {
        // Last item: minimize post_residual hard.
        score += post_residual as f64 * 0.5;
    }

    // Penalize bins that deviate from mean residual (avoid fragmenting many medium bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if lookahead chains perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Early in the stream, having many bins open is fine.
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild late-stream consolidation: prefer reusing existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly (dead-space penalty grows for small post_residual).
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 40.0; // perfect fit
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item will need a bin anyway; slight penalty if this wastes capacity.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * progress;
        // If alternatives exist, discourage new bin more; if this is the only option, soften.
        if fitting_bins_count == 0 {
            score -= 45.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0; // keep last-chance preference for existing bin
        }
        // If open bins have large mean residual, opening a new bin is wasteful.
        score += mean_residual * 0.3;
    } else {
        // Favor bins whose residual is close to the item (good fill ratio).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * fill_ratio;

        // Mild preference for bins below mean residual (consolidate emptier space usage).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight bonus for using bins when many are open (avoid bin proliferation).
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: post-residual, mildly super-linear to punish dead space.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth progress coupling: later in stream, dead space matters more (fewer
    // future items to fill gaps), so amplify residual penalty with progress.
    score *= 1.0 + 0.8 * progress * (pr / cap);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + pr + 1.0);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 && !is_new_bin {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize unless residual would be too small for the
    // next item while open bins are fragmented (mean residual high).
    if is_new_bin {
        let next_fits = next_item_size > 0 && (next_item_size as f64) <= pr;
        let fragmentation = mean_residual / cap;
        let mut penalty = 18.0 + 15.0 * (1.0 - progress);
        if next_fits {
            penalty += 10.0 * fragmentation;
        }
        if open_bins_count == 0 {
            penalty = -100.0; // must open first bin
        }
        score += penalty;
    }

    // Lookahead: reward bins whose post-residual exactly accommodates next item.
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.08 * gap;
        if gap < 1.0 {
            score -= 8.0;
        }
    }

    // Mild preference for balancing residuals when many bins are open.
    score += 0.05 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        // exact fill is perfect
        if pr == 0 {
            harmony += 40.0;
        }
        // small dead space (<10) is nearly unusable: penalize
        if pr < 10 {
            harmony -= 25.0;
        } else if pr < 20 {
            harmony -= 10.0;
        }
        // integer-division threshold: residual in [30,60] is a sweet spot
        let half_bucket = pr / 30;
        harmony += match half_bucket {
            1 => 8.0,
            2 => 5.0,
            _ => 0.0,
        };
        score -= harmony;
    } else {
        score -= 50.0; // perfect pack
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + next_item_size as f64 * 0.2;
        // harmonic bonus if next_item_size divides post_residual
        if pr % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space proportionally
        score += (pr as f64 - (pr % next_item_size.max(1)) as f64) * 0.1;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins with decent fits
        score += 45.0;
        // but if the item is huge and would leave bad residue everywhere, new bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // late in stream, fewer open bins => keep consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins: reward small bin_residual relative to capacity
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Coupling with mean residual: avoid wrecking above-average bins
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Mild pressure against bin sprawl
    score += open_bins_count as f64 * 0.05;

    // Modulo tiebreak on post_residual classes of 5 for deterministic diversity
    score -= (pr % 5) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable
    // for future items; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but relax pressure as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make opening a new bin attractive only when this bin's
    // post-fit residual would be a dead gap, or when the next item pairs well
    // with a fresh bin rather than this residual.
    if bin_residual == bin_capacity {
        let base = 15.0 + open_bins_count as f64 * 1.5;
        let next_pairs_here = next_item_size > 0 && next_item_size <= post_residual;
        let next_pairs_new = next_item_size > 0 && next_item_size <= bin_capacity;
        if next_pairs_here && !next_pairs_new {
            // keep item in existing bin context; new bin less attractive
            score += 40.0;
        } else if next_pairs_here && next_pairs_new {
            score += 10.0;
        } else {
            score -= base.min(30.0);
        }
        // Early in the stream, opening bins is cheap and builds flexibility.
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mild normalization toward mean residual state.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead space elimination)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= (post_residual as f64);
        if next_fits {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            // Perfect chain: item + next item leaves tiny residual
            score -= 25.0 + 0.5 * slack_after_next.max(0.0).min(30.0);
            if slack_after_next <= 5.0 {
                score -= 15.0; // near-perfect 2-item chain
            }
        } else {
            // Next item cannot use the leftover: penalize proportionally to wasted space
            let waste = post_residual as f64;
            score += 0.3 * waste;
            // If next item is large and this bin leaves a mid-sized hole, extra penalty
            if next_item_size as f64 > post_residual as f64 {
                score += 0.2 * (next_item_size as f64 - post_residual as f64);
            }
        }
    }

    // Compare residual against mean residual: bins tighter than average are better to fill
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when a tight fit exists elsewhere
    if open_bins_count > 3 && post_residual > 20 {
        score += 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate handling: only attractive early in stream or when item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let huge_item = item_size as f64 > 0.8 * bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0;
        if huge_item || no_good_fit {
            score -= 10.0;
        } else if progress < 0.2 {
            score += 5.0;
        } else {
            score += 25.0 + 20.0 * progress; // prefer existing bins later on
        }
    }

    // Mild preference for bins with small residual overall (best-fit flavor)
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that is too small to fit the average future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 10.0; // next item can't follow here; slight penalty
        } else {
            score += (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer reusing large-residual bins.
    if bin_residual as f64 > mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Many open bins: discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But allow opening a new bin for very large items that leave awkward residuals elsewhere.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (0.5 + 0.5 * t) - prn * (1.0 - t) * (1.0 - t);
    score += 12.0 * poly;

    // Penalize waste relative to mean residual, scaled by progress
    score += t * (pr - mean_residual).abs() * 0.3;

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 20.0 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead: prefer bins whose post residual fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Slight penalty for proliferating open bins early
    score += open_bins_count as f64 * 0.05 * (1.0 - t);

    // New-bin candidate: discourage unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64 / cap;
        score += 6.0 - 10.0 * (1.0 - tight) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue as dead-space signature
    let pr = post_residual;
    let residue = pr % 10;
    let quotient = pr / 10;
    // Penalize awkward residues (small nonzero leftovers are hard to fill)
    if pr > 0 {
        let residue_penalty = match residue {
            0 => -6.0,          // perfectly divisible: reusable chunk
            1 | 2 | 8 | 9 => 8.0, // worst dead space
            3 | 7 => 5.0,
            4 | 6 => 3.0,
            _ => 4.0,           // residue 5
        };
        score += residue_penalty;
        // Deep harmonic bands: prefer post_residual in coarse half-capacity classes
        if quotient >= 5 { score -= 4.0; }         // >50% space left: very reusable
        else if quotient >= 3 { score -= 2.0; }
        else if quotient >= 1 { score += 1.0; }
        else { score += 6.0; }                      // <10% left: near-dead bin
    } else {
        score -= 10.0; // perfect fit
    }

    // Lookahead coupling: harmonic compatibility between post_residual and next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item divides post_residual cleanly?
            if pr % next_item_size == 0 {
                score -= 7.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; leftover must serve later items
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance pressure: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        // Open new bin when mean residual is low (bins nearly full) or early stream
        score = cap - item_size as f64;
        score += fragmentation * 0.2;
        score -= (open_bins_count as f64).ln() * 3.0;
        score += (1.0 - progress) * 5.0;
        if fitting_bins_count <= 1 { score -= 20.0; }
    }

    // Mild stream-phase modulation on waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * (2.0 + 3.0 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest item (size 1) are fine,
    // but gaps in a "dead zone" (very small but nonzero) are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // penalize the empty new-bin candidate more when open_bins_count is high.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that just barely misses the next item (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Deviation from mean residual: prefer bins that are either well-filled or
    // avoid spreading residual unevenly.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // ideal: bin becomes exactly reusable for next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize leftover
        score += 5.0;
    }

    // Relative residual vs mean: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize large absolute waste relative to capacity.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if this placement leaves room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin could have fit the next item but won't after placement.
            score += 6.0;
        }
        // Perfect chaining: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Time horizon: early in the stream, prefer consolidation into few bins;
    // later, allow spreading to reduce fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    // Global residual pressure: if mean residual is high, prefer filling
    // below-average-residual bins (tighter bins) more aggressively.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize opening new bins normally; discount for large items or desperation.
        score += 45.0 - 30.0 * big_item - 50.0 * desperation;
        // Late in stream, a fresh bin is more acceptable to absorb odd sizes.
        score -= 10.0 * progress;
    }

    // Discourage leaving dead space below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, with smooth polynomial shaping
    // (quadratic + quartic terms create a smooth "waste" landscape).
    let mut score = x * (1.0 + 0.8 * x) * cap;

    // Tight-fit reward: smooth bell around near-zero post residual.
    let tight = (-(x * 12.0)).exp();
    score -= 14.0 * tight * (1.0 + 0.5 * progress);

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        let nx = nxs / cap;
        let fit_gap = pr - nxs;
        if fit_gap >= 0.0 {
            let g = fit_gap / cap;
            // smooth reward decreasing with leftover gap after next item
            score -= 10.0 * (-(g * 9.0)).exp() * (1.0 - 0.4 * progress);
        } else {
            // penalize if next item cannot fit here (wasted perfect fit)
            score += 4.0 * nx * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 * (1.0 + 0.6 * (1.0 - progress));
    }

    // New-bin candidate: penalize opening a fresh bin, especially when
    // other bins fit and the item is small relative to capacity.
    if bin_residual == bin_capacity {
        let base_pen = 20.0 + 0.25 * open_bins_count as f64;
        let small_item_pen = 0.35 * (item_size as f64 / cap) * (1.0 - progress);
        score += base_pen + small_item_pen;
    }

    // Mild coupling with mean residual: avoid fragmenting bins when
    // average residual is already small (bins nearly full).
    let mr = mean_residual / cap;
    score += 3.0 * x * (1.0 - mr).max(0.0);

    // Smooth progress interaction: later in the stream, be more tolerant
    // of larger post residuals (fewer options left, keep bins usable).
    score *= 1.0 - 0.15 * progress * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    let phase = post_residual % 10;

    // Reward landing exactly on class boundaries (perfect harmonic fill).
    if phase == 0 {
        score -= 6.0;
    } else {
        score += phase as f64 * 0.35; // penalize off-phase dead space
    }

    // Harmonic class reward: leftover in {0, 10, 20} classes is highly reusable
    // for typical item sizes; leftover < 10 is dead space.
    score += match class {
        0 => 8.0,           // dead space: heavy penalty
        1 => 0.0,
        2 => -2.0,
        3 => -4.0,
        4 => -5.0,
        _ => 0.0,
    };

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_phase = (post_residual - next_item_size) % 10;
            if next_phase == 0 {
                score -= 5.0; // two-step harmonic chain
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; leftover should be as small as possible.
            score += 1.5;
        }
    } else {
        // Last item: only immediate waste matters.
        score += post_residual as f64 * 0.02;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is large
    // relative to capacity (large items pair better with fresh capacity).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 100.0 - frac * 40.0 - pressure * 2.0
            + (post_residual % 10) as f64 * 0.5;
    }

    // Mild stream-progression bias: later in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (bin_residual as f64 / bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are nearly worthless -> heavy penalty.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small gaps may only fit tiny items: moderate dead-space penalty.
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward tight fits (post_residual small but still usable).
    if post_residual > 0 && post_residual <= 30 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (perfect pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is dead space for the known next item -> penalize.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 40 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (this call's post_residual == capacity - item_size is maximal).
    if bin_residual == bin_capacity {
        let fullness = item_size as f64 / bin_capacity as f64;
        if fullness > 0.6 {
            // Large items: fresh bin is fine, slight reward.
            score -= 5.0 * fullness;
        } else {
            // Small items into fresh bins waste capacity -> strong penalty
            // unless many bins are already open and residuals are poor.
            score += 25.0 * (1.0 - fullness);
            if mean_residual > 30.0 {
                score += 15.0;
            }
        }
    }

    // Mild drift: as the stream progresses, prefer consolidating into
    // existing bins (closing out residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space (post_residual too small for typical items).
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual > 50 {
            score += 0.6 * (post_residual as f64 - 50.0);
        }

        // Aggressive 2-step lookahead: reward when next item fits the residual exactly,
        // reward when it fits, penalize when it doesn't.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 300.0; // perfect chain: two exact fills
            } else if next_item_size <= post_residual {
                // reward proportionally to how well next item uses leftover
                let fill_after_next = (post_residual - next_item_size) as f64;
                score -= 60.0 * (1.0 - fill_after_next / post_residual as f64);
            } else {
                // next item cannot fit: leftover likely dead space
                score += 25.0;
            }
        }

        // Compare against mean residual: prefer bins tighter than average.
        score += 0.5 * (bin_residual as f64 - mean_residual);

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Late in the stream: tighten packing, avoid sprawl.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

        // Many open bins: prefer consolidating into existing ones.
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: neutral-ish baseline; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize bins with large residual waste relative to the fleet average.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }
    // If next item cannot fit in post-residual, slight penalty for fragmenting.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0;
    }

    // Early in the stream: prefer filling existing bins less eagerly, keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: mildly discourage spreading into the emptiest bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to how well existing bins could fit,
        // but allow opening a new bin when residual space is fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 + 10.0 * (1.0 - fragmentation);
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let progress_coupling = 2.0 * progress * (1.0 - progress) * norm_pr * cap * 0.5;
    score += progress_coupling;

    // Perfect-fit reward (smooth quadratic trough near zero residual)
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score += 3.0 * diff * diff * cap * 0.1;
        score -= 2.0 * (-diff * diff * 20.0).exp();
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins with residual far below mean (fragmented bins)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // Mild penalty for spreading across many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in small
    // "usable" residue classes are favored; large dead space penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quadratic waste penalty: leftover beyond half capacity is increasingly bad.
    if pr > cap * 0.5 {
        score += (pr - cap * 0.5) * (pr - cap * 0.5) / cap;
    }

    // Reward tight fits: post_residual in [0, 10] is near-perfect packing.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Modulo-class logic: leftover divisible into common item size classes
    // (10, 20, 25, 50) is reusable; odd leftovers are penalized.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual > 0 && post_residual % 10 != 0 && post_residual % 25 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this bin is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 12.0;
            } else {
                score += chain_waste as f64 * 0.15;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much leftover would be stranded.
            score += pr * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + pr * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (mean residual small relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early (amortization), less so later.
        score += 20.0 * (1.0 - progress);
        // If the current item leaves a well-classed residual in a fresh bin,
        // that's fine; otherwise penalize.
        if post_residual % 10 != 0 && post_residual % 25 != 0 {
            score += 8.0;
        }
        // If many bins are open and mean residual is high, discourage new bins.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        // If nothing else fits (this call is the only candidate), the base
        // score stands; subtract so a fresh bin beats a horrible fit.
        if fitting_bins_count == 0 {
            score -= 18.0;
        }
    }

    // Small global tie-breaker: prefer fuller bins (smaller residual).
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small to hold even the lookahead item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Open bins pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual >= 10 && post_residual >= next_item_size.min(80) as u32 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: reward leaving space exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.35 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            // dead space penalty scaled by how far off the next item is
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // last item: prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize bins with residuals far above mean (fragmenting space)
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // Mild bias toward more-filled bins
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Late in the stream, tighten packing (prefer minimal waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64) && post_residual < item_size
        } else {
            false
        };
        if dead {
            score += 15.0;
        }
        // Penalize residuals that fall into awkward small ranges.
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for wasting this bin's tail
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified.
        score += 30.0;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin becomes more attractive.
        score -= (mean_residual / bin_capacity as f64) * 45.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Early in the stream, prefer consolidating into few bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Lookahead synergy: fresh bin can host both this and the next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 18.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins with residual close to item size (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Quadratic-cubic interaction: waste penalized more as stream advances
    let coupling = prn * prn * (1.0 + 2.5 * p) - prn * prn * prn * (1.0 + 3.0 * p);
    score += 18.0 * coupling;

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tight = (1.0 - prn) * (1.0 - prn);
    score -= 12.0 * tight * (0.5 + p);

    // Penalize when this bin's residual drifts far above the mean residual (fragmentation)
    let drift = pr - mean_residual;
    score += 0.05 * drift * drift * (1.0 + p);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + prn);
    }

    // Lookahead: if next item fits exactly into post_residual, reward; if it would be wasted, penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure to prefer existing bins over opening new ones as bins accumulate
    score += 0.02 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 30.0,          // near-perfect fit (0..25 residual)
        1 => score -= 8.0,           // decent fit
        2 => score += 4.0,           // mediocre
        _ => score += 12.0,          // large dead space
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize residuals that no future item (min size 1..10 typical) can use
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Harmonic coupling with next item: reward residuals that can hold the lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins
    // unless residual landscape is fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 10.0 * progress;
        // open a new bin if mean residual across open bins is small (bins nearly full)
        score += (mean_residual / bin_capacity as f64) * 20.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer filling bins that are already relatively full
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac;

    // Modulo threshold: residuals divisible by 8 pack better with common item sizes
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Penalize large leftover space only mildly; it may still be usable.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 20.0; // small-but-usable gaps are decent outcomes
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: prefer already-open bins over proliferation.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: make it unattractive unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.5;
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    } else {
        // Reward bins whose residual is close to what the next item needs.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Prefer bins with residual near mean residual (balanced packing).
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight packing (small post residual), but with a nonlinear push
    // so that small leftovers are strongly preferred over medium dead space.
    score += 0.35 * (post_residual as f64).powf(1.35);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 8.0).exp();           // strong bonus for exact 2-step match
        score += 0.10 * gap;                           // mild penalty for mismatch
        // Perfect two-item chain: post_residual == next_item_size
        if post_residual as i64 == next_item_size as i64 {
            score -= 6.0;
        }
    } else {
        // Last item: only absolute tightness matters
        score -= 3.0 * (post_residual == 0) as i32 as f64;
    }

    // Reward filling below mean residual (closing "hungry" bins early),
    // penalize draining a bin far below the average leftover.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Dead-space penalty: leftover too small for the minimum plausible item
    // (assume items >= 1, but waste below ~10 is hard to reuse given typical sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate logic: an empty bin has large residual; make it unattractive
    // unless every open bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        let open_waste = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };
        // Opening a new bin costs ~1 bin; only worth it when open bins would waste a lot.
        score += 25.0 - 0.15 * open_waste;
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer spreading load when many bins are open and residuals are large
    // (keeps future options open), but only mildly.
    if open_bins_count > 1 && post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize dead space: post_residual too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post) * 2.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    }
    // If next item won't fit post_residual but this is the only fitting bin, mild penalty.
    if next_item_size > post_residual && fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by stream progress
    // and how many open bins already exist (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 25.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // Allow opening a new bin if mean residual across open bins is very low.
        score -= (mean_residual / cap) * 20.0;
    } else {
        // Mild reward for filling bins tighter than the average residual.
        score -= (mean_residual - post) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalize large post residual non-linearly.
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, dead space matters more.
    score += 0.8 * progress * norm_pr * norm_pr;

    // Coupling with mean residual: bins far from the mean residual get adjusted priority.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 1.2 * (item_size as f64 / cap);
    }

    // Lookahead: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= 0.5 * (1.0 - gap) * (1.0 - progress);
        } else {
            score += 0.3 * (-gap);
        }
    }

    // Slight penalty for spreading across many open bins early.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: neutral-ish baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 0.35 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 — small residues (dead space)
    // that can't host typical items (>=1..100 unknown, but small waste is fine)
    let post = post_residual;
    let res_class = post % 10;
    score -= (10 - res_class) as f64 * 0.5; // prefer residues that "round" waste cleanly

    // Penalize large leftover space that is still usable — it's potential, reward it
    if post >= 25 {
        score -= 8.0;
    }
    if post >= 50 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post >= next_item_size {
        let slack = post - next_item_size;
        if slack == 0 {
            score -= 400.0;
        } else if slack <= 10 {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; dead space risk scales with next size class
        let next_class = (next_item_size / 10) as f64;
        score += next_class * 3.0;
    }

    // Last-chance bin: strongly prefer filling it rather than leaving it half-used
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 30.0;
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Integer-division threshold: bins whose residual is in a "harmonic" band
    // (divisible nicely by common item sizes) are worth keeping flexible
    let harmonic = post % 20 == 0 || post % 25 == 0 || post % 50 == 0;
    if harmonic && post > 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap that can still host typical small items: mild reward.
        score -= 5.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage proliferation,
    // but only when the fit is not tight.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    score += pressure * (1.0 - fill_ratio);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // New-bin candidate handling: an empty bin is only attractive when
    // open bins have poor fits (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let mean_tightness = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Prefer new bin when existing bins are crowded and many are open.
        score = 55.0 + 20.0 * (1.0 - mean_tightness) - 1.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 25.0; // don't open new bin if this item has few alternatives... wait, fitting counts exclude new bin; keep neutral
            score -= 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a chain match — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves a new residual; penalize by new dead space.
            let chain_residual = post_residual - next_item_size;
            score -= 30.0 - chain_residual as f64 * 0.5;
        } else {
            // Next item cannot use this bin's remaining space: mild penalty scaled
            // by how far off the match is.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean (tight bin) is good; spreading into large-residual bins wastes them.
    let resid_diff = mean_residual - bin_residual as f64;
    score += resid_diff * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, prefer tightening existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Mild penalty when many bins are open (consolidation pressure).
    score += open_bins_count as f64 * 0.2;

    // Slight preference for filling larger fraction of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused by future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0; // wastes the lookahead opportunity
        }
        // Extra synergy: next item fits snugly after this placement
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 10 {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins for big items);
    // late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor consolidation
    // into bins below the mean (balancing residuals).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Penalize opening new bins when plenty of open bins can already fit the item.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty so it only wins for genuinely poor fits
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        } else if item_size >= 60 && progress < 0.5 {
            score -= 20.0; // early large items: fresh bin can be attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize post_residual with a non-linear (quadratic) term.
    let mut score = pr * (1.0 + 0.5 * pr_norm);

    // Smooth coupling: post_residual value depends on stream progress.
    // Early on, larger residuals are more acceptable (bins can still be filled);
    // late in the stream, residual waste is more costly.
    score += pr * (0.8 * progress * pr_norm) * (1.0 - 0.3 * progress);

    // Cubic interaction: heavily penalize tiny dead space that is hard to fill,
    // scaled by progress so it matters more late in the stream.
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 20.0 * tightness * (0.5 + progress);

    // Reward tight fits (small post_residual) relative to item size.
    let fit_ratio = item_norm / (item_norm + pr_norm + 1e-9);
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Scarcity pressure: when few bins fit the item, penalize waste mildly.
    if fitting_bins_count > 0 {
        score += pr_norm * (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (0.6 + 0.4 * progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual alignment: prefer bins close to the mean residual state.
    score += (pr - mean_residual).abs() * 0.15;

    // Mild new-bin penalty so empty bins are chosen only for poor fits;
    // penalty fades slightly as stream progresses.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: fractional fill of the bin by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Dead-space penalty grows superlinearly for tiny post_residuals that are
    // unusable for typical small items (post_residual < 10 => guaranteed waste).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Harmonic class logic: classify post_residual into residue classes modulo 10.
    // Residuals that are multiples of 10 are "harmonic" with the item-size grid
    // (sizes 1..100 tend to cluster in decades), so they are more reusable.
    let harmonic = post_residual % 10 == 0;
    let semi_harmonic = post_residual % 5 == 0;
    if harmonic {
        score -= 6.0;
    } else if semi_harmonic {
        score -= 3.0;
    } else {
        // Odd dead space is harder to fill later.
        score += 2.0 + (post_residual % 10) as f64 * 0.3;
    }

    // Integer-division threshold: bins whose residual can still host a "large"
    // class item (>= 40) are more valuable; keep them flexible.
    if post_residual / 40 >= 1 {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // Next item fits: mild reward proportional to leftover after next.
            let post2 = post_residual - next_item_size;
            score -= 8.0 * (1.0 - post2 as f64 / bin_capacity as f64);
            if post2 % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item will NOT fit here: penalize leaving an awkward gap.
            score += 3.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (avoid leaving many partially-filled bins open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.15;

    // Crowding: with many open bins, favor filling existing ones over new bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate adjustment: an empty bin has perfect flexibility but
    // wastes the residual of existing bins; make it slightly unattractive
    // unless the current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap too small for the minimum item (1..10)
    // is wasted forever; penalize it quadratically.
    if post_residual < 10 {
        score += 60.0 + 4.0 * (10.0 - post_residual as f64);
    }

    // Tight fits are excellent: reward near-exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading;
    // prefer compacting into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item is huge relative to
    // residual or would leave a bad gap in any existing bin.
    if bin_residual == bin_capacity {
        let would_waste = post_residual > 0 && post_residual < 10;
        if would_waste || item_size > 70 {
            score -= 30.0;
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Lookahead coupling: if the next item could exactly use this bin's
    // post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear emphasis.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap; // quadratic penalty on dead space

    // 2-step lookahead: reward bins whose post_residual exactly/nearly fits next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap); // next item fits: big reward for tight 2-step match
            if slack == 0 {
                score -= 20.0; // perfect chain
            }
        } else {
            // next item won't fit here: mildly penalize leaving a mid-sized hole
            score += 4.0 * (pr / cap);
        }
    }

    // Relative-to-mean coupling: avoid bins far below mean residual (fragmented),
    // but prefer bins close to mean when mean is large.
    score += 0.5 * (pr - mean_residual).abs() / (mean_residual + 1.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (pr as f64) < 0.25 * cap;
        if good_fit_exists {
            score += 30.0; // keep using existing bins
        } else {
            score -= 5.0 * (open_bins_count as f64).min(5.0);
        }
        // Prefer deferring new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for filling larger-residual bins when item is big.
    if item_size > bin_capacity / 2 {
        score -= 0.1 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
