        let after_next = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - after_next / (bin_capacity as f64));
    }

    // Last-chance bonus: this is the only fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 {
