    }

    // Prefer bins below mean residual (fill emptier bins to balance).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: make opening a new bin moderately attractive
    // only when current bin would leave a large, awkward residual and there
    // are many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        // Base reluctance to open new bins grows with number of open bins.
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But if this item wastes > 30% of a fresh bin, discourage strongly.
        if waste > 0.3 {
            score += 25.0 * waste;
        }
        // Early in stream, opening bins is cheaper.
        score -= 10.0 * (1.0 - progress);
        // If many fitting bins exist, definitely prefer them over new bin.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild time-horizon shaping: late in stream, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), modulated by progress
    let mut score = pr * (1.0 + progress * norm_pr);

    // Smooth non-linear coupling: wasted fraction squared grows with stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Perfect fit reward (cubic smooth term)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Last-chance bin: strong reward, decaying smoothly with progress
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 15.0 * snug * snug;
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Prefer fuller bins relative to mean residual (smooth sigmoid-like coupling)
    let mean_term = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * mean_term / (1.0 + (-2.0 * mean_term).exp());

    // Penalize scattering across many open bins late in the stream
    score += (open_bins_count as f64).ln() * 3.0 * progress;

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead-space penalty: post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward (harmonic class 0)
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo-10 class logic: residuals that are multiples of 10 pair well with
    // the common item sizes drawn from a 10-grid
    let class = post_residual % 10;
    match class {
        0 => score -= 25.0,
        5 => score -= 5.0,
        _ => score += 3.0,
    }

    // Integer-division thresholds: post_residual in [10,30] is "medium-usable"
    let div10 = post_residual / 10;
    match div10 {
        1 | 2 | 3 => score -= 8.0,
        4 | 5 => score -= 15.0,
        6 | 7 => score -= 10.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize small leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // or when the current bin's residual would become dead space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (cap_f - item_size as f64) / cap_f;
        score += 30.0 * progress;
        score -= 55.0 * (1.0 - progress);
        // penalize new bin if it would strand a large unusable remainder
        if waste > 0.5 && item_size < 50 {
            score += 25.0 * waste;
        }
        // early stream: fresh bins are cheap
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // (tighter-than-average bins get priority to close them out)
    let dev = (post_f - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins with large residuals when few bins are open
    if open_bins_count < 4 {
        score -= 5.0;
    }

    // Small global progress modulation of tightness reward
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - frac) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual that is too small to hold
    // the smallest plausible item (1..=5) is wasted capacity forever.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0 + (6 - post_residual) as f64 * 10.0;
    }
    // Small-ish gaps (6..=15) are risky: only usable by tiny items.
    else if post_residual > 5 && post_residual <= 15 {
        score += 25.0;
    }

    // If the lookahead item fits into the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If lookahead item nearly fits (small overshoot), mild penalty.
    else if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but keep the new-bin candidate (full residual) slightly penalized
    // so it is only chosen when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Prefer bins tighter than the mean residual (good packing progress).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, avoid opening new bins at all costs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item, penalize residual that strands the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: bonus scaled by tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack;
        } else {
            // Next item won't fit in this bin's leftover: penalize proportional waste.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }

        // Chain bonus: post_residual exactly equals next item -> perfect 2-step match.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer using bins that are already relatively full (small residual).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist, but relax this
    // pressure late in the stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for keeping many open bins consolidated early on.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: smaller post_residual relative to capacity is good (already the base).
    // Penalize very small dead space only if it's likely unusable (< 10% of capacity).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // penalize blocking the next item badly
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or state is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { 1.0 - ((post_residual as f64) / mean_residual) } else { 0.0 };
        // Base penalty for opening a new bin (waste), reduced when many bins are open & fragmented.
        score += 18.0
            - 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0))
            - 10.0 * fragmentation.clamp(0.0, 1.0)
            - 6.0 * progress;
        // Never open a new bin when a perfect fit exists elsewhere: keep score high-ish.
        if post_residual == 0 { score += 100.0; }
    }

    // Mild preference for filling fuller bins overall (relative residual).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Global pressure: when many bins are open, prefer consolidating into existing bins.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth progress coupling: late in stream, tighter packing matters more
    let late = progress * progress;
    score += 20.0 * late * pr / cap;

    // Reward near-perfect fits via smooth exponential-like polynomial term
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 10.0 * gap * (1.0 + gap);
        // Reward leaving exactly the lookahead size
        let match_q = 1.0 - ((pr - nx).abs() / cap);
        score -= 8.0 * match_q * match_q;
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Slight penalty when many bins already open (consolidation pressure)
    score += 0.5 * open_bins_count as f64;

    // Mild attraction toward bins near mean residual (balanced packing)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 18.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets penalize awkward leftovers.
    let class = (post_residual % 10) as f64;
    score += class * 0.8;

    // Dead-space penalty: residual that is small but nonzero is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use leftover: leftover likely becomes dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutral baseline; penalize slightly unless open bins are crowded.
    if bin_residual == bin_capacity {
        score = cap_f - 10.0;
        // If existing bins are fragmented (high mean residual spread), new bin ok.
        if mean_residual > (item_size as f64) {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with small residuals relative to mean (tighter packing).
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Late in stream, consolidate: favor bins already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are dead space; penalize them nonlinearly.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is very desirable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 + (20 - slack.min(20)) as f64;
    } else if next_item_size > 0 && next_item_size > bin_capacity {
        // lookahead unusable, ignore
    } else if next_item_size > 0 {
        // next item cannot use the leftover; mild penalty scaled to gap size
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones;
    // penalize the new-bin candidate and reward using existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with residuals below mean (tighter bins get filled first),
    // keeping looser bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space below the minimum item size (1) is unavoidable, but small
    // residuals that nothing can use are dead weight: penalize residuals
    // smaller than the smallest plausible item more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: strongly reward bins whose post-residual can
    // exactly or comfortably host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where next item leaves a still-usable remainder.
            if slack < 10.0 {
                score -= 150.0;
            } else {
                score -= 80.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize proportionally to how
            // much dead space this placement strands.
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
        }

        // Bonus if the bin could fit BOTH the current and next item tightly.
        if post_residual >= next_item_size && post_residual <= next_item_size + 20 {
            score -= 50.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (best-fit flavor), penalize bins that are far looser than average.
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that fits, opening a new bin
    // is wasteful — reward using it, especially when fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + (item_size as f64 / bin_capacity as f64) * 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let baseline = 150.0 - 60.0 * progress; // later in stream: more reluctant to open bins
        // Deter new bin unless the item is large relative to capacity and
        // existing bins are crowded.
        let crowding = mean_residual / bin_capacity as f64;
        score = baseline + (1.0 - crowding) * 100.0 - (item_size as f64) * 0.5;
    }

    // Mild penalty for spreading across many open bins when a tight fit exists.
    if open_bins_count > 4 && post_residual > 0 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in stream, prefer tighter packing / reuse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward if next item fits in post_residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space relative to next item, worse late in the stream.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty to keep tightest-fit preference via post_residual.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with low residual relative to mean (tighter bins first),
    // unless this is a fresh bin.
    if bin_residual < bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // it creates a large usable residual and existing bins are poor fits.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        // Penalize new bins generally; discount penalty if item is large
        // or no open bin fits and post-residual is roomy.
        let mut penalty = 90.0;
        if poor_fits > 0.0 { penalty -= 40.0; }
        if big_item { penalty -= 25.0; }
        if post_residual >= 50 { penalty -= 10.0; }
        // Early in the stream, opening bins is cheaper (future items can use them).
        penalty *= (1.0 - 0.3 * progress);
        score += penalty;
    }

    // Slight preference for reusing bins with many open bins around (consolidation).
    if bin_residual < bin_capacity && open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted residual, with super-linear growth (dead space is costly)
    let mut score = post * (1.0 + 0.015 * (post / cap) * 100.0 / 100.0);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins can still be filled);
    // late in stream, residual waste is nearly permanent -> amplify penalty.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 1.0 + 0.8 * p2 + 1.2 * p3;

    // Reward tight fits: small normalized post residual gets a smooth discount
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else
    // or when open bins' mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 18.0 * (1.0 - mean_fit_gap.min(1.0));
        // early stream: opening bins is cheap; late: prefer squeezing into open bins
        score += 10.0 * (1.0 - progress);
        // if next item is small, a fresh bin has good future utility
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 6.0;
        }
    }

    // Lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving nothing behind
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: tiny residuals are hard to fill later
    if post_residual > 0 && post_residual < 8 {
        score += 18.0;
    } else if post_residual < 15 {
        score += 6.0;
    }

    // Harmonic class logic: residual modulo classes of 10.
    // Residuals in the "high" half of a decade (e.g. 51..59, 61..69) pair
    // well with mid-sized items; low-half residuals fragment more.
    let decade_class = post_residual % 10;
    score += decade_class as f64 * 0.25;

    // Lookahead coupling (k=2): reward residuals that exactly fit next item,
    // penalize residuals the next item cannot use at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 28.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer the tightest bin: deviation from mean residual
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is discouraged unless the
    // fleet of open bins is already nearly saturated (low mean residual).
    if bin_residual == bin_capacity {
        let saturation = 1.0 - (mean_residual / bin_capacity as f64);
        score += 45.0 - saturation * 55.0 - item_size as f64 * 0.15;
    }

    // Late-stream consolidation: slightly favor existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest possible item (1) are pure waste; residuals below a
    // "usable threshold" are heavily penalized.
    let dead = post_residual == 0;
    let unusable = post_residual > 0 && post_residual < 10;
    if dead {
        score -= 60.0; // perfect fit is ideal
    } else if unusable {
        score += 45.0 - 4.5 * (post_residual as f64); // small gaps are dead space
    }

    // Reward snug fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Penalize leaving a residual that just barely misses the next item,
    // but reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size - 3 {
            score += 10.0; // near-miss: wasted almost-enough space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, be more tolerant.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Discourage placing into bins with large mean residual mismatch
    // (keep residual pool homogeneous for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when this is a genuinely large
    // item or all existing fits would be terrible.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fits && item_size >= 50 {
            score -= 20.0;
        } else {
            score += 35.0; // prefer existing bins by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small unusable dead space (< 10, minimum item size).
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item would perfectly fill this bin.
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Closer gap to a perfect 2-step chain => bigger reward.
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
            if gap < 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit after this placement; mild penalty scaled by overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow / 100.0).min(1.0);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below mean residual is good (it becomes a tight bin).
    let mean_gap = (post_residual as f64) - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere. Penalize the fresh empty bin (post_residual == bin_capacity)
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 35.0 * (1.0 - fill_ratio);
        // Late in the stream, be even more reluctant to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill bins with more residual when many bins are open
    // (consolidation pressure).
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize residual gaps that are unlikely to be reusable later.
    // Typical item sizes are >= 10, so residuals below ~10 are dead space.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted pairing potential
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // More attractive late in the stream (less future to amortize? no—
        // late stream means fewer items remain, so prefer consolidation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many bins are open with slack, discourage a new one.
        score += 0.8 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
        // Exact-size new bin for a large item is fine (item nearly fills it).
        if item_size >= 70 {
            score -= 22.0;
        } else if item_size >= 50 {
            score -= 10.0;
        }
        // Lookahead: if next item can pair with this item in the new bin, reward.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    } else {
        // Reward using bins that are already fairly full (consolidation).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
        // Slight penalty proportional to number of open bins to encourage packing into fewer bins.
        score += 0.15 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth filling; if above mean, less urgent.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover = lower score = favored)
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on small post-residual (dead space),
    // weighted by stream progress.
    let dead_penalty = (1.0 - norm_pr).powi(2) * (20.0 + 60.0 * progress);
    score += dead_penalty;

    // Smooth reward for post_residual close to next item size (lookahead fit),
    // gaussian-like coupling.
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let sigma = 15.0 + 25.0 * (1.0 - progress);
        let fit_bonus = -30.0 * (-(diff * diff) / (2.0 * sigma * sigma)).exp();
        score += fit_bonus;
    }

    // Last-chance bin: strongly favor using it when it's the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Slight preference for placing into bins with lower-than-mean residual
    // (consolidate large gaps), scaled by number of open bins.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * mean_gap * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild early-stream preference for opening fresh bins (keeps large residuals
    // available later); decays smoothly with progress.
    if bin_residual == bin_capacity {
        score -= (1.0 - progress).powi(2) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes are more valuable (tight fits rewarded).
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes (0..10)
    let class_bonus = match class {
        0 => 60.0,                    // residual < 10: nearly perfect fit
        1 => 45.0,                    // 10..19
        2 => 30.0,                    // 20..29
        3 => 18.0,                    // 30..39
        4 => 10.0,                    // 40..49
        5 => 4.0,                     // 50..59 (half-full leftover)
        _ => 0.0,
    };
    score -= class_bonus;

    // Modulo harmonic: leftover that is a multiple of common item sizes
    // (10,20,25,50) is reusable; reward exact divisibility.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a golden pairing — reward strongly.
    if next_item_size > 0 && next_item_size == pr {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits but not perfectly: mild reward scaled by tightness
        let tight = 1.0 - (pr - next_item_size) as f64 / cap;
        score -= 10.0 * tight;
    } else if next_item_size > 0 {
        // next item will NOT fit here: penalize leaving big unusable gaps
        let waste = (next_item_size - pr) as f64;
        score += 0.15 * waste;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the fit elsewhere would be terrible. Penalize mildly by default,
        // but reduce penalty when open bins are nearly full on average.
        let crowded = mean_residual / cap < 0.25;
        let base = if crowded { 10.0 } else { 55.0 };
        // Late in the stream, keep bins tight; slightly favor new bins to
        // avoid fragmenting the tail.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base - 15.0 * progress;
    } else {
        // Prefer fuller bins generally (best-fit bias beyond raw residual).
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 12.0 * fill;
        // Many open bins: encourage consolidation into existing bins.
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // Penalize creating residual that no plausible item (min size 10... but
    // sizes 1..100 here) can use well: tiny crumbs 1..5 are dead space.
    if pr >= 1 && pr <= 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the "unusable gap" band are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: item filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins whose residual is far from item size (wasteful choice).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit < 10 {
            score -= 35.0; // leaves another near-perfect fit
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover: leftover becomes dead space
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins are empty-ish.
    if bin_residual == bin_capacity {
        score += 70.0 + 3.0 * open_bins_count as f64;
        // but if mean residual is low and item is large, new bin is attractive
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Slight preference for bins with residual near mean (keep distribution balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 150.0;
            } else {
                // penalize leaving space that next item leaves wasteful residue
                score -= 50.0 - (gap as f64).min(50.0);
            }
        } else {
            // next item won't fit here: penalize proportionally to how much dead space remains
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement creates bad residue.
    if bin_residual == bin_capacity {
        // empty bin baseline; penalize unless item is large relative to capacity
        score += 80.0 - (item_size as f64 * 0.8);
        if item_size >= 80 {
            score -= 60.0;
        }
    }

    // Small early-stream bonus to consolidate when few bins are open.
    if open_bins_count <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small residuals that few typical items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bins attractive only when current
    // bins would leave large dead space or are nearly exhausted.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_dead = mean_residual / open_bins_count.max(1) as f64;
        // Base cost of opening a new bin, discounted late in the stream.
        score = 55.0 - 20.0 * progress;
        // If existing residuals are large (waste), opening fresh is fine.
        score -= 10.0 * (avg_dead / bin_capacity as f64);
        // If item is big relative to capacity, a fresh bin is safer.
        score -= 0.1 * item_size as f64;
    } else {
        // Prefer bins with lower residual among comparable fits (best-fit bias).
        score += 0.05 * bin_residual as f64;

        // Time horizon: early on, encourage consolidating into fewer bins;
        // later, be more permissive to avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress * (1.0 - fit_ratio);

        // Crowd effect: with many open bins, favor filling existing ones harder.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;
    }

    // Mean-residual coupling: if average residual is small, squeeze more out of
    // existing bins (penalize new space creation).
    if bin_residual != bin_capacity {
        score += 3.0 * (mean_residual / bin_capacity as f64) * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear fill ratio: reward tight fits more than linearly
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill;

    // Dead-space penalty: cubic in post_residual, amplified by stream progress
    score += 0.002 * post * post * post / cap * (0.5 + progress);

    // Interaction: post_residual vs mean residual (prefer bins below mean residual -> compacting)
    let dev = post - mean_residual;
    score += 0.15 * dev * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 0.3 * (nxt - post) * (0.5 + progress);
        } else {
            // reward leaving space exactly usable by next item
            score -= 0.4 * (1.0 - (post - nxt) / cap);
        }
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Small smooth diversification across open bins
    score += 0.01 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form "useful" future slots
    // (multiples of 10 and small residuals <= 9 are valuable; mid-range dead zones penalized).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity class of the post residual
    let frac = pr / cap;
    let harmonic = (1.0 - frac).sin() * 5.0; // oscillatory coupling
    score += harmonic;

    // Penalize dead-space classes: residuals in [21..49] and [61..79] are hard to fill
    let r = post_residual;
    if r > 20 && r < 50 { score += 6.0; }
    if r >= 60 && r < 80 { score += 4.0; }
    // Reward near-perfect closures
    if r == 0 { score -= 30.0; }
    else if r <= 10 { score -= 12.0; }

    // Integer division threshold on post_residual: k = r / 25 harmonic bands
    let band = r / 25;
    score += match band { 0 => -8.0, 1 => 3.0, 2 => 1.0, _ => 0.0 };

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // reward proportional to tightness of next fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; slight penalty for very large residuals
            score += pr * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter current bins when many bins are open (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: neutral-ish baseline; discourage early proliferation,
    // allow it when open bins are all tight or this is a poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tightness = 1.0 - mean_residual / cap;
        score = 45.0 + 20.0 * (1.0 - progress) - 25.0 * avg_tightness;
        if fitting_bins_count == 0 { score -= 20.0; }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 10.0; // big item followed by bigger item: fresh bin reasonable
        }
    }

    // Modulo-10 harmonic bonus: residuals that are multiples of 10 pair well
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item are pure waste. Penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: mild penalty.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward leaving a gap that can exactly host the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap large enough for the next item is valuable.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize lightly per open bin.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: only attractive when open bins would leave
    // very poor fits (large dead space) or are nearly all tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // More attractive if the best existing fit would waste a lot
        // (post_residual on this call is capacity - item for the new bin,
        // so use mean_residual as a proxy for how full open bins are).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 90.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
    } else {
        // Filling existing bins is preferred; reward tighter fits relative
        // to the bin's current residual.
        score -= (bin_residual as f64) * 0.3;
        // Coupling: a good fit (small post_residual) in a well-loaded bin.
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward bins where the next item also fits the post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent — both items pack here.
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 25.0 + 20.0 * chain_tightness;
        } else {
            // Next item won't fit here: penalize dead space proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * gap / bin_capacity as f64 * 10.0;
        }
    } else {
        // Last item: just minimize residual.
        score += 5.0;
    }

    // Penalize creating large unusable residuals relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual is tiny/awkward).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 20.0; // tiny dead space penalty offsets last-chance bonus
        }
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score worse.
    if bin_residual == bin_capacity {
        score = 60.0 - 10.0 * fit_ratio;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild penalty for waste of large residual on small items (bad packing).
    if (item_size as f64) < 0.5 * bin_residual as f64 && bin_residual < bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets nonlinear bonus.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 20.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Penalize creating dead space that no plausible item can fill.
    // Items are 1..100; a residual < next_item_size is likely wasted.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space for the immediate future
        }
        // Reward residual that exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 18.0;
        }
        // Reward leaving room for next item plus a small filler.
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere. Baseline new-bin score should be moderate.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early (few bins) or when item is large
        // relative to capacity (big items pair well with fresh space).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 45.0;
        new_bin_score -= 20.0 * big_item;          // big items like fresh bins
        new_bin_score += 15.0 * progress;          // later in stream, prefer consolidation
        new_bin_score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is low, opening a bin is more justified.
        new_bin_score -= 5.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        return new_bin_score;
    }

    // Penalize filling a bin that still holds room for average-sized items
    // when other bins have larger residuals (spread load).
    let mean_res = mean_residual;
    if (post_residual as f64) < mean_res - 20.0 {
        score += 4.0;
    }

    // Slight preference for bins whose residual is close to item size (best fit).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs().powf(0.9);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = r * r * (1.0 - r) * (1.0 - r);
    score -= 40.0 * poly * (0.5 + progress);
    score += 12.0 * r * r * r * progress;

    // Tight-fit reward (smooth): residual close to zero is excellent
    let tight = (1.0 - r).powi(4);
    score -= 25.0 * tight * (1.0 + progress);

    // Lookahead coupling: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nr = next_item_size as f64 / bin_capacity as f64;
        let compat = if r >= nr { 1.0 - (r - nr).powi(2) } else { 0.0 };
        score -= 18.0 * compat * (1.0 - progress);
        // Penalize residual just barely missing next item
        let near_miss = (r - nr).abs();
        if near_miss < 0.15 {
            score += 20.0 * (0.15 - near_miss) / 0.15;
        }
    } else {
        // last item: strongly prefer filling bins as fully as possible
        score -= 30.0 * tight;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Pull score toward mean residual for stability
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low classes (0..10)
    // are "dead space" classes — heavily penalize unless exactly 0.
    let cls = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if cls == 0 {
        score -= 8.0; // residual is a multiple of 10: easy to fill later
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, unusable for items >= 10
    } else {
        score += 6.0 * (cls as f64) / 10.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for large leftovers
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and mean
    // residual is high (fragmentation control).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive only if current bins are fragmented
        score += 15.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64);
    } else {
        // reward filling existing bins proportionally to how much of the
        // bin this item consumes
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Harmonic fraction: capacity-fraction thresholds on residual before placement.
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.5 && frac < 0.8 && item_size as f64 > frac * bin_capacity as f64 * 0.9 {
        score -= 5.0; // near-full usage of a large residual
    }

    // Slight tie-breaker noise-free decay: prefer compacting early.
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; the smaller the gap, the worse the "usability density".
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        // gap can't fit current item nor lookahead -> likely dead space
        score += (bin_capacity as f64 - pr) * 0.9;
    } else if post_residual > 0 {
        // reward leaving a gap that can still host the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // smooth usability: penalize tiny slivers nonlinearly
        score += 12.0 * (-pr / 15.0).exp();
    }

    // Tight fits are excellent
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins when residuals are large
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (1.0 - progress * 0.5);

    // Prefer bins whose residual is below the mean (compact bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual as f64 <= mean_residual;
        if good_fit_exists || fitting_bins_count <= 1 {
            score += 60.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead: if next item exactly fills the post-residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize tight fits that leave nothing useful
            let overflow = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += 5.0 * (overflow / next_item_size as f64);
            }
        }
    }

    // Compare post_residual against mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Penalize creating small, hard-to-use dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: make it attractive only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let tight_now = post_residual <= 10;
        let next_mismatch = next_item_size > 0 && next_item_size > post_residual;
        if tight_now || next_mismatch {
            score -= 15.0;
        } else {
            score += 40.0;
        }
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    // Late-stream tightening: prefer tighter fits as stream progresses
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if next item fits in post_residual, this is a great pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space for it.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * consolidation * fit_ratio;

    // Prefer bins below mean residual when mean residual is large (balance).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Early stream: slightly favor opening fresh bins for large items to keep
    // flexibility; late stream: strongly avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        score = (bin_capacity - item_size) as f64;
        score -= 20.0 * fit_ratio;
        score += 55.0 * progress; // later => new bins more expensive
        if item_size > 60 {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        score -= 10.0 * progress; // late stream: fill existing bins harder
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog_c = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 12.0 * prn * prn * (1.0 - prn) * (1.0 + prog_c);

    // Penalize dead space more as stream progresses (fewer chances to fill it)
    score += 8.0 * prn * progress * progress;

    // Reward tight fits: subtract when post_residual is small
    let tight = 1.0 - prn;
    score -= 10.0 * tight * tight * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: penalize if next item cannot use this residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * ((nx - pr) / cap) * (0.5 + progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nx).abs() / cap) * (1.0 - progress);
        }
    }

    // Divergence from mean residual across open bins
    score += 0.5 * (pr - mean_residual).abs() / cap * (1.0 + prog_c);

    // Mild penalty for too many open bins
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * prn;

    // New-bin candidate: discourage unless residuals are tight or item is large
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 15.0 * (1.0 - avg_fill) * (1.0 - progress);
        score -= 5.0 * progress;
        score += 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Reward near-perfect fits: post_residual in low harmonic classes.
    let cls = post_residual % (bin_capacity / 4).max(1); // classes of 25
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if cls == 0 {
        score -= 10.0; // exact quarter multiples are reusable slots
    } else if post_residual < 10 {
        score += 25.0; // dead space below min item size
    }

    // Non-linear tightness reward: quadratic in residual fraction.
    score -= (1.0 - frac) * (1.0 - frac) * 30.0;

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += 15.0 + 0.3 * next_item_size as f64;
        } else {
            // Reward if next item fits snugly into post residual.
            let slack = post_residual - next_item_size;
            score -= (1.0 - (slack as f64 / cap)) * 12.0;
            if slack == 0 {
                score -= 20.0; // chain of perfect fits
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // If existing bins are highly fragmented, opening fresh is less bad.
        score -= (mean_residual / cap).min(1.0) * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild penalty for proliferating open bins over stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to item (best-fit flavor).
    score += ((bin_residual - item_size) as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small to fit the next item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect packing (exact fill gets a strong bonus).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Tighter fit relative to capacity is favored.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward bins whose residual is close to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 3.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when the current bin would
    // leave a large unusable gap or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + open_bins_count as f64 * 2.0;
        // But if the item fits poorly in existing bins (huge post residual),
        // a fresh bin becomes competitive.
        if post_residual == 0 {
            score -= 55.0; // item == capacity, perfect new bin
        }
        // Lookahead: if next item is large, a fresh bin is more flexible.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Existing bin: bonus if it can also host the next item afterwards.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize post_residual (tight fit reward)
    let pr = post_residual as f64;
    score = pr * pr * 0.02 + pr;

    // 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        // perfect match for the next item is highly desirable
        score -= 12.0 * (1.0 - diff / 100.0).max(0.0) * (1.0 - diff / 100.0);
        // penalize leaving a residual that is smaller than the next item (dead space)
        if pr < nxt && pr > 0.0 {
            score += 8.0 * (1.0 - pr / nxt);
        }
    }

    // Relative to mean residual: prefer bins whose leftover deviates favorably
    let dev = pr - mean_residual;
    score += 0.05 * dev;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // all existing fits would create large unusable dead space.
    if bin_residual == bin_capacity {
        // baseline cost of a new bin, reduced when few bins are open (early stream)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score += 20.0; // fresh bin wastes potential for the lookahead item
        }
    }

    // Slight preference for filling larger residual bins when many bins are open
    score -= 0.02 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large post-residual.
    score += 0.02 * (post_residual as f64).powi(2);

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward when next item fills leftover nearly exactly.
            let gap = post_residual - next_item_size;
            score -= 0.1 * (bin_capacity as f64 - gap as f64) / bin_capacity as f64;
        } else {
            // Leftover too small for next item: penalize dead space proportionally.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or item is large.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = (post_residual as f64) / bin_capacity as f64;
        score += 30.0;              // base cost of opening a bin
        score -= 20.0 * fit_ratio;  // large items justify new bins
        score -= 10.0 * (1.0 - pressure); // good fill of a fresh bin helps
        // Early in stream: more freedom to open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - t);
        // Many open bins with large mean residual: prefer reusing them.
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Fragmentation guard: penalize leaving slivers below minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: waste matters more as the stream progresses.
    let pr = post / cap;
    score += 30.0 * pr * pr * (0.3 + progress);
    score -= 12.0 * (1.0 - progress) * (post / cap).sin().abs();

    // Reward tight fits (small post_residual) with smooth decay.
    score -= 25.0 * (-post / (0.15 * cap)).exp();

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 10.0 * (nx - post) / cap * (0.5 + progress);
        } else {
            score -= 6.0 * (post - nx) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 20.0 + 25.0 * progress - 20.0 * scarcity;
        score += 5.0 * (open_bins_count as f64).ln1p();
    }

    // Mild pressure to close bins near the mean residual.
    score += 3.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on
    // "nice" fractions of capacity are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;

    // Reward residuals that are exact harmonic fractions (0, quarter, half, 3/4).
    let harmonic_bonus = if post_residual == 0 {
        40.0
    } else if post_residual == quarter {
        18.0
    } else if post_residual == half {
        25.0
    } else if post_residual == 3 * quarter {
        12.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Modulo-class penalty: residuals that are awkward (not divisible by 5 or 10)
    // tend to waste space; penalize them mildly.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow here: penalize proportionally to how
            // "dead" the leftover is relative to the smallest plausible item.
            let dead = (pr / cap).powi(2);
            score += 20.0 * dead;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good
    // host (i.e., mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        let desperation = ((item_size as f64 - mean_residual).max(0.0)) / cap;
        score = 55.0 + 25.0 * openness - 45.0 * desperation;
        if next_item_size > item_size {
            score -= 10.0; // fresh bin can host a growing stream
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64).sqrt();

    // Slight progression tilt: later in the stream, tighten fits more.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (pr / cap);

    // Prefer bins whose residual is already below the mean (dense bins).
    score += 0.15 * (pr - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for any
    // plausible future item (min item size 1..100 unknown, so treat < 20 as
    // likely dead) are heavily penalized; post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual > 80 {
        // Wasteful placement leaving a huge gap in an existing bin
        score += 15.0;
    }

    // Reward filling most of the bin (tight fit)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer
    // compacting into existing bins; few open bins -> new bin is cheap.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for tight residual
            score += 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin; finishing it off is good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev.max(0.0);

    // New-bin candidate: only attractive when no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream
        // and when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 180.0 + 60.0 * (1.0 - progress) - 10.0 * open_bins_count as f64;
        // If the item is huge, a fresh bin is often the best home anyway
        if item_size >= 60 {
            score -= 40.0;
        }
        // Last-chance override: never open a new bin when this is the only fitting bin
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact/near-exact match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can fit here afterwards: reward tight match
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted residual relative to gap
            score += 0.35 * gap;
        }
    }

    // Tight fit now is good
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * tightness;

    // Penalize dead space far from mean residual (fragmentation)
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste ratio penalty
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, this placement is doubly good
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size == post_residual {
            score -= 45.0;
        } else {
            // post_residual becomes dead space relative to next item
            let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.15 * dead;
        }
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so existing bins are preferred unless they fit badly
        score += 55.0;
        // more open bins with low mean residual => opening new bin more attractive
        score -= 2.0 * open_bins_count as f64;
        score -= 0.3 * mean_residual;
        // late in stream, prefer consolidating (fewer new bins)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // large items prefer fresh bins early
        score -= 0.1 * item_size as f64 * (1.0 - progress);
    } else {
        // prefer fuller bins among open ones
        score -= 0.2 * (bin_capacity - bin_residual) as f64;
        // if bin residual is far from mean residual, slight penalty (keep diversity)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: many open bins => pack tighter
    score -= 1.5 * open_bins_count as f64 * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 - progress) + prn * progress * 0.5;
    score += poly * 40.0;

    // Reward tight fits, more aggressively as stream progresses
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (20.0 + 60.0 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - pr) / bin_capacity as f64;
        score += waste * waste * 50.0 * (0.5 + progress);
    }

    // Reward using the bin when next item fits exactly in residual
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize mildly unless open bins are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 10.0 + 20.0 * (1.0 - fragmentation);
    }

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.5;

    // Mean residual deviation coupling
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits are golden,
    // tiny dead slivers are penalized extra.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 5 {
        score += 15.0; // near-useless sliver
    } else if pr <= 10 {
        score += 6.0;
    } else {
        // harmonic classes via integer division thresholds
        let class = pr / 20; // 0..=4 for capacity 100
        score -= class as f64 * 3.0;
    }

    // Lookahead: reward bins whose post-residual still fits the next item,
    // especially exactly.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        if pr == next_item_size {
            score -= 12.0;
        }
        // penalize leaving just barely too little for next item
    } else if next_item_size > 0 && pr > 0 && next_item_size > pr {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is only attractive when current bins
    // fit poorly (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 10.0;
        // if many bins fit, prefer reusing one
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
        // if the next item is large, a fresh bin is useful
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with more residual (keeps big bins for big items)
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // neutral coupling

    // Tie-break toward bins below mean residual (filling emptier bins first)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    let dead_threshold = 12.0f64.min(mean_residual.max(1.0));
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 + (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 150.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up -> reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item cannot use the leftover: mild penalty proportional
            // to the wasted gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins; also make the new-bin candidate
    // (bin_residual == bin_capacity) less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, scaled by pressure.
        score += 55.0 + 25.0 * pressure;
        // But if nothing else fits well (item is large and bins are nearly full),
        // opening a fresh bin can be right: soften when mean residual is low.
        score -= (mean_residual / bin_capacity as f64) * 30.0;
    } else {
        // Existing bin: slight reward to counteract new-bin cost.
        score -= 10.0 * pressure.min(3.0);
    }

    // Prefer bins with residual close to the item (minimal waste) beyond
    // raw post_residual ordering.
    score -= (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits (post_residual == 0) strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into the
    // post_residual, this placement is excellent (chains two perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: penalize wasted gap slightly less
            // proportional to leftover after the second placement.
            let second_leftover = post_residual as f64 - next_item_size as f64;
            score -= 300.0 - second_leftover * 2.0;
        } else {
            // Next item cannot fit in the residual: penalize dead space more
            // as we approach the end of the stream (less time to recover).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (next_item_size - post_residual) as f64 * (1.0 + progress);
        }

        // If next item fits exactly in current residual, keep this bin
        // available for it instead (avoid double consumption).
        if bin_residual as f64 == next_item_size as f64 && post_residual > 0 {
            score += 400.0;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual stays near
    // the mean (balanced packing), penalize outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        // New bin is attractive only if this bin would leave tiny unusable
        // residual and the next item is small enough to use it later.
        let tiny_dead = post_residual < 10 && post_residual > 0;
        if tiny_dead || (next_item_size > 0 && post_residual < next_item_size && post_residual < 15) {
            score -= 150.0;
        } else {
            score += 120.0 + 10.0 * pressure * (1.0 - progress * 0.5);
        }
    }

    // Mild preference for tighter bins (small pre-residual).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keep options open.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin would consume space the next item could have used.
            score += 8.0;
        }
        // Exact chain fit bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> favor filling existing ones; few bins -> be picky.
    let openness = open_bins_count as f64;
    score += 2.0 * (openness.ln()) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far from the mean, adjust slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive for very large items or terrible fits.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit_everywhere = fitting_bins_count == 0;
        if big_item > 0.5 || poor_fit_everywhere {
            score -= 55.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped by progress
    let mut score = pr * (1.0 - 0.3 * progress);

    // Non-linear polynomial coupling of normalized post-residual with progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr.powi(3) * (1.0 + 3.0 * progress);
    score += 40.0 * poly;

    // Perfect fit reward (quadratic in item fraction)
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill * (1.0 + progress);

    // Last chance bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New bin candidate: penalize unless post-residual would be very small
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress - 20.0 * fill;
    }

    // Lookahead: reward if next item fits post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - nxt / cap) * (1.0 + progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual alignment: prefer bins near mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Many open bins: slight penalty for wasting capacity
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (capacity fraction) ----
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Perfect fit: strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: tiny residuals (1..10) are nearly unusable
        // since item sizes are integers 1..100 -> penalize hard.
        if post_residual <= 10 {
            score += 120.0;
        } else if post_residual <= 20 {
            score += 60.0;
        } else if post_residual <= 30 {
            score += 25.0;
        } else if post_residual >= 50 {
            // Large residual: still useful, mild reward
            score -= 15.0;
        }

        // Modulo-class harmony: residuals that are multiples of common
        // small item sizes (10, 20, 25) are more likely to be filled later.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 5 != 0 {
            // awkward class, off the harmonic grid
            score += 6.0;
        }
    }

    // ---- Lookahead (k=2): does the next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: big reward
            score -= 45.0;
            if next_item_size == post_residual {
                score -= 80.0; // exact chain -> two items fill bin
            }
        } else if next_item_size <= bin_residual {
            // Next item would have fit pre-placement but not after: penalize
            score += 35.0;
        }
        // Harmonic coupling: next item shares a divisor class with residual
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline neutral score. Prefer it only when
        // existing bins are crowded (low mean residual) or item is huge.
        score = cap * 0.9
            + 0.15 * (open_bins_count as f64)
            - 0.5 * mean_residual
            - if item_size >= 60 { 30.0 } else { 0.0 }
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // Early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Mild preference for fuller bins (waste-not): scale by fill ratio
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 20.0 * fill;
    }

    // ---- Mean-residual coupling: steer toward bins below/above average ----
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 8.0; // bigger-than-average residual gets used first
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use
    // (below the minimum item size of 1, or tiny slivers) are heavily penalized.
    if post_residual > 0 {
        // A residual is "dead" if it is smaller than the smallest possible item (1)
        // or falls into a narrow unusable band (1..=5) that rarely gets filled.
        if post_residual < 6 {
            score += 40.0 * (6 - post_residual) as f64;
        }
        // Non-linear penalty growing as post_residual shrinks (wasted capacity).
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * frac * frac;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (low slack relative to bin).
    let tightness = item_size as f64 / bin_residual as f64;
    if bin_residual > 0 {
        score -= 10.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward;
    // if the next item cannot fit the post residual, mild penalty for blocking.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins; the empty new-bin candidate has bin_residual == bin_capacity, so we
    // detect it and penalize opening new bins when pressure is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is cheap; later it is expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If a fitting bin exists, opening a new bin should lose.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    } else {
        // Slight bonus for using existing bins when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins
    // less, keep larger residuals for future large items).
    score += 3.0 * (mean_residual - bin_residual as f64).signum() * ((mean_residual - bin_residual as f64).abs() / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 - slack.min(50.0)) * 3.0; // tighter slack => better
        } else {
            // Next item cannot fit here; penalize proportionally to the mismatch.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = mean_residual - post_residual as f64;
    score += dev * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no open bin fits well, allow opening: reduce penalty when
        // the item is large relative to capacity and open bins are crowded.
        if item_size > bin_capacity / 2 && open_bins_count > 0 {
            score -= 60.0;
        }
        if post_residual == 0 {
            score -= 400.0; // opening a fresh bin for a full-fit item is fine
        }
    }

    // Late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but usable.
    if post_residual > 0 {
        score -= 8.0 * (1.0 - post_residual as f64 / 30.0).max(0.0);
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Penalize large dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < item_size {
        score -= 3.0; // residual too small for the current item class, but maybe useful
    }
    if post_residual >= 50 {
        score += 2.0; // very large leftover is wasteful unless bin was fresh
    }

    // Lookahead: favor bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 3.0; // creates stranded residual vs. the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // But discourage hoarding bins when open bins already fit well.
        if fitting_bins_count > 0 && post_residual == bin_capacity - item_size {
            let tightness = (bin_capacity - item_size) as f64 / bin_capacity as f64;
            score += 12.0 * (1.0 - tightness); // poor fit => new bin still favored via low base? invert:
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score += 1.5 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more liberal with new bins (future flexibility);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: late in the stream, waste is costlier
    score *= 1.0 + 0.6 * progress * (1.0 - progress * 0.5);

    // Penalize near-fit dead space smoothly (small post_residual but nonzero)
    let tightness = (1.0 - norm_pr).max(0.0);
    score -= 12.0 * tightness * tightness * tightness * (item_size as f64 / cap);

    // Reward near-perfect fits even more when lookahead item can't use leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr as f64 {
            score -= 8.0 * (1.0 - nxt / cap) * progress;
        } else {
            score += 4.0 * (1.0 - (nxt / pr.max(1.0))) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 + mean_residual / cap);

    // New-bin candidate: prefer opening fresh bin when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = pr + 20.0 - 18.0 * fragmentation * (1.0 - progress) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (capacity fractions)
    let residue_class = post_residual % 10;
    let dead_penalty = match residue_class {
        0 => -6.0,                    // perfect multiple: reusable slot
        1..=3 => 3.0 + 2.0 * residue_class as f64, // tiny slivers are dead space
        4..=7 => -1.0,                // mid-range still usable
        _ => 1.5,                     // 8..9 slightly awkward
    };
    score += dead_penalty;

    // Integer-division thresholds: how many size-10 items still fit
    let slots = post_residual / 10;
    score -= 2.0 * slots as f64;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match: next item exactly fills a class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0;
        }
        // next item's own residue class vs this bin's post class
        let nclass = next_item_size % 10;
        if nclass == residue_class && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= 70 && next_item_size > post_residual.saturating_sub(30) {
            score -= 20.0; // fresh bin useful for big incoming items
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight fits are golden: tiny post_residual relative to item
    if post_residual <= 5 {
        score -= 10.0;
    }

    // Progression: early in stream, prefer consolidation; late, prefer tightness
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Prefer bins below mean residual (tighter bins) mildly
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items (min size 1..100 unknown, but small gaps < 10 are almost surely dead)
    // are heavily penalized. Non-linear superlinear penalty for tiny gaps.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - pr) / 10.0; // small unusable slivers
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is the ideal outcome
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - pr / next_item_size as f64);
    }
    // Reward bins that can also fit the next item (chain potential)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new-bin opening
    // and encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 18.0 + 2.5 * open_bins_count as f64 + 10.0 * progress;
        // A new bin is acceptable if the item is huge relative to residuals.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 20.0;
        }
    } else {
        // Mild reward for filling existing bins, stronger when many bins open.
        score -= 1.5 + 0.3 * open_bins_count as f64;
        // Prefer bins tighter than the mean residual (good fit relative to fleet).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Prefer high fill ratio of this placement.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after the lookahead placement
            score += 0.35 * slack;
            if slack <= 10.0 {
                score -= 15.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot fit here anyway; slight penalty for large post_residual
            score += 0.10 * (post_residual as f64);
        }
    }

    // Penalize creating dead space unusable by typical items (residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer new bin only when no good fit exists
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin; make it attractive only if residuals are large/fragmented
        score = 55.0 + 0.4 * (mean_residual as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * (next_item_size as f64);
        }
    }

    // Mild preference for filling already-open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Slight aversion to leaving residuals near awkward mid-range sizes
    let r = post_residual as f64;
    if r > 20.0 && r < 45.0 {
        score += 6.0 * (1.0 - (r - 20.0) / 25.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize large dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small unusable slivers are fine only if unavoidable
    }
    if post_residual >= 10 {
        // residual that could host future items is good, mildly reward it
        score -= 0.05 * post_residual as f64;
    } else {
        score += 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // Extra reward if next item then fits snugly too
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 8.0;
            } else if rem2 < 10 {
                score += 3.0;
            }
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins with residuals below the mean residual (fill the fullest bins first).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just pack anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let selectivity = 1.0 - 0.5 * progress;
    score *= selectivity;

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins fit poorly and there is room to accumulate a fresh bin.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // baseline cost of a fresh bin
        score = 100.0 - 8.0 * fit_ratio.max(0.0); // fit_ratio = 0 for empty bin
        if next_item_size > 0 && next_item_size >= item_size {
            // new bin can host current + next item comfortably
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, new bin is mandatory anyway
        } else if fitting_bins_count <= 2 {
            score -= 5.0;
        }
        if open_bins_count > 6 {
            score += 10.0; // too many open bins, prefer consolidation
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score *= 1.0 - 0.3 * progress; // late stream: discourage new bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early on, prefer tight fills; late, tolerate residual less aggressively.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Polynomial interaction: residual penalty modulated by progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress;
    score += 12.0 * coupling;

    // Reward near-perfect fits smoothly (quartic dip around small residuals)
    let tightness = (cap - pr) / cap; // fill fraction
    score -= 18.0 * tightness * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth-ish: reward bins that remain usable, penalize dead space vs next item
        let gap = (pr - nxt).abs() / cap;
        score += 6.0 * (1.0 - fits_next) * (1.0 + progress);
        score -= 4.0 * fits_next * (1.0 - gap * gap);
    }

    // Mild pressure from number of open bins: prefer filling existing bins when many are open
    score += 0.4 * open_bins_count as f64 * (1.0 - tightness);

    // Deviation from mean residual: prefer bins close to mean to balance residuals
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make empty bin moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo small divisors
    // capture "nice" leftover sizes that future items (10..80) can reuse.
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr % 10 == 0 { 1 } else if pr % 5 == 0 { 2 } else if pr % 3 == 0 { 3 } else { 4 };
    score -= match class {
        0 => 30.0,          // perfect fit
        1 => 12.0,          // round decile residual, highly reusable
        2 => 6.0,           // half-decade residual
        3 => 2.0,
        _ => 0.0,
    };

    // Penalize dead space that no plausible item can fill (items >= 10,
    // so residuals < 10 are pure waste; residuals in 10..20 are fragile).
    if pr < 10 && pr > 0 {
        score += 15.0;
    } else if pr < 20 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item is close, mild reward; if it cannot fit,
    // slight penalty for hoarding.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= if gap % 10 == 0 { 10.0 } else { 5.0 };
        } else {
            score += 3.0;
        }
        // Integer-division threshold: next item is "large" (> half capacity)
        let _ = next_item_size / (bin_capacity / 2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline pull toward opening fresh bins when existing
    // residuals are small/fragmented; make empty bins moderately attractive.
    if bin_residual == bin_capacity {
        score -= 8.0;
        if open_bins_count == 0 { score -= 20.0; }
        if mean_residual < 15.0 && open_bins_count > 0 { score += 10.0; }
    }

    // Tightness reward: bins that become very full are preferred.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Progression modulation: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fill);

    // Divergence from mean residual: prefer bins whose residual is near the mean
    // (keeps bin population homogeneous) unless it's a last-chance case.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Modulo coupling between item and residual class (harmonic pairing).
    if (item_size % 10) == (bin_residual % 10) && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty scaled by how tiny it is.
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual <= 20 {
            // Marginal gap: moderate penalty, decays toward usefulness.
            score += (20 - post_residual) as f64 * 3.0;
        } else {
            // Large gaps remain usable by future mid-size items; mild reward.
            score -= (post_residual as f64 - 20.0) * 0.15;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already low; encourage consolidation when mean residual is high.
    let mean_res_gap = (mean_residual - item_size as f64).max(0.0);
    score += open_bins_count as f64 * 1.5 * (1.0 - mean_res_gap / bin_capacity as f64).max(0.0);

    // Lookahead: if the next item can use the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap; penalize proportionally to the waste.
        score += (post_residual as f64) * 0.25;
    }

    // New-bin candidate: only attractive when current bin fits are terrible
    // (large dead space) — otherwise keep item in an existing bin.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; becomes competitive only if open-bin
        // scores accumulated enough dead-space penalty.
        score += 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin is fine for a pair of large items
        }
    }

    // Slight early-stream leniency: fewer open bins early means cheaper new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Strong reward for exact match
        if diff < 0.5 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 4.0 * diff;
        } else {
            // Penalize large gaps between post_residual and next item
            score += (diff - 5.0).min(40.0) * 0.8;
        }

        // If next item fits exactly after this placement, big bonus
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: minimize residual directly (score already = post_residual)
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating large dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Reward tighter fits (small post_residual) nonlinearly
    if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when current open bins would leave big waste
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously
        score += 30.0;
        // But if all fitting bins would leave huge residual, new bin becomes viable
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64 - bin_capacity as f64).abs() {
            score -= 10.0;
        }
        // Late in stream, slightly discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to keep many small bins consolidated when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.8 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.5 {
        score -= 10.0 * fit_ratio;
    }

    // Dead-space penalty: small post_residual is good, but a post_residual that
    // can fit almost nothing (1..=9) is wasted space — mild extra penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly (or well) into the post_residual,
    // this placement is chaining nicely — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let chain = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * chain;
        } else {
            // Next item won't fit here after placement; if post_residual is tiny
            // that's fine (bin is closed out), if large it's stranded space.
            if post_residual >= 20 {
                score += 0.05 * post_residual as f64;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: empty bin gets a baseline cost so we only open
    // a new bin when existing fits are poor. Penalize the empty bin by the
    // amount of capacity that would sit idle relative to current mean residual.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (build a spread of bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If open bins are already crowded on average, new bin less costly.
        score -= 0.1 * mean_residual;
    } else {
        // Mild penalty for using very full bins when many bins are open —
        // keep flexibility, unless fit is tight (already rewarded above).
        if open_bins_count > 3 && fit_ratio < 0.5 {
            score += 3.0;
        }
    }

    // Global balance: prefer bins whose residual is below the mean (use up
    // the emptier bins first, keeping tight bins available for small items).
    if bin_residual as f64 > mean_residual + 1.0 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear scaling
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate slack; late in stream, punish dead space quadratically
    let prog2 = progress * progress;
    score += 30.0 * prog2 * (pr / cap).powi(2) * cap * 0.01;
    score -= 20.0 * progress * (1.0 - pr / cap); // reward fuller bins as stream advances

    // Exact fit reward (smooth bump around zero residual)
    score -= 15.0 * (-(pr / 8.0).powi(2)).exp();

    // Lookahead: reward leaving post_residual close to next item size (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / (nx + 10.0);
        score -= 12.0 * (-d * d).exp();
        // penalize if post_residual is just below next item (dead space for lookahead)
        score += 8.0 * (1.0 - (pr / (nx + 1.0)).min(1.0)) * (pr < nx) as i32 as f64;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (pr - mean_residual).abs() / cap;

    // Mild preference for filling emptier bins early
    score += 5.0 * (1.0 - progress) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
