            if gap % 10 == 0 {
                score -= 5.0 + gap as f64 * 0.05;
            } else if gap < 10 {
                score -= 2.0;
            } else {
                score += gap as f64 * 0.03;
            }
        } else {
            score += 3.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are terrible
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened casually
        score = bin_capacity as f64 * 0.85;
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if pressure > 0.55 && fitting_bins_count >= 1 {
            score -= 8.0 * (pressure - 0.55) * (1.0 + progress);
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 && mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild congestion: many open bins -> prefer tighter packing
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Progress-aware waste aversion
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize leftover directly.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Dead-space avoidance: residuals that cannot fit the smallest item (1..10)
    // are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Mid-range unusable gaps: penalize gaps too small for typical items
    // (e.g. residual in [1,15) is often dead space for larger streams).
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * -0.5;
    }
    // If next item would NOT fit in the post residual, mild penalty
    // (this bin becomes dead for the lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate more.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: empty bin has bin_residual == bin_capacity.
    // Only attractive when current bin's fit would be terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // But if lookahead next item is large and this item is small,
        // opening a fresh bin can still be reasonable.
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual penalizes dead space super-linearly.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // 2-step lookahead: strongly reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item does NOT fit leftover: penalize leaving a gap it can't use
            let waste = next_item_size - post_residual;
            score += 0.8 * waste as f64;
        }
    }

    // Compare post residual to mean residual across open bins: leaving below-average
    // residual (tight packing) is good; above-average residual is wasteful.
    if mean_residual > 0.0 {
        score += 0.25 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: make the empty bin unattractive unless all else is bad.
    // Base penalty for opening a new bin, softened late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0 - 30.0 * progress;

        // If the next item is large relative to a fresh bin, opening a new bin
        // preserves a big residual for it — slightly less penalize then.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with more residual when few bins are open
    // (keeps flexibility), and for tighter bins when many are open.
    let openness = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * openness * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small-but-annoying dead space quadratically (unusable slivers).
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 10.0;
        // Reward if the lookahead item can still fit after placement (chaining).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        }
        // Penalize leaving space that no plausible item (>=1) but small residue wastes.
        if post_residual < 10 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer open bins generally, but allow opening
    // a fresh bin when existing residuals are fragmented / mean residual is low-value.
    if bin_residual == bin_capacity {
        // Base tax for opening a new bin.
        score += 15.0;
        // Opening is more attractive when many bins exist but mean residual is small
        // (items won't pack well anywhere) — relative fragmentation penalty.
        let frag = (mean_residual / bin_capacity as f64).max(0.0);
        score -= frag * 10.0;
        // Late in the stream, avoid spawning bins that will never be filled.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If the next item is large, a fresh bin with full room is valuable.
        if next_item_size > 0 && next_item_size >= post_residual.max(1) {
            score -= 6.0;
        }
    }

    // Mild preference to spread load when many bins are open (balance residuals).
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 18.0 * norm_pr * norm_pr * (0.4 + 1.2 * p2);
    score -= 10.0 * norm_pr * (0.3 + 0.9 * p3);

    // Penalize large dead space more strongly as stream advances
    score += (pr * pr) / cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (post_residual as f64 / (item_size.max(1) as f64 + 1.0));
    score -= 6.0 * tightness * (1.0 - progress + 0.5 * p2);

    // Lookahead: reward residual that can fit next item, penalize otherwise
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - 0.5 * progress);
        // Penalize leaving residual just barely too small for next item
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.15 * gap * (1.0 - fits_next);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mean residual context: prefer bins deviating favorably from mean
    score -= 0.5 * (mean_residual - pr);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it moderately attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = cap as f64 * (0.9 + 0.5 * progress) - 12.0 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes (likely dead space) are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = (post_residual / eighth) % 8; // 0..7 harmonic class

    // Penalize residuals that are too small to ever be useful (dead space),
    // but reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0; // perfect fit: excellent
    } else if post_residual <= eighth {
        score -= 40.0; // tiny leftover, nearly perfect
    } else if post_residual < quarter {
        // mid-small residual: mildly good
        score -= 10.0;
    } else if post_residual < 2 * quarter {
        // half-ish leftover: neutral to slightly bad
        score += 5.0;
    } else {
        // large leftover: bin was under-used; penalize proportionally
        score += 15.0 + 0.2 * (post_residual as f64 - 2.0 * quarter as f64);
    }

    // Modulo-10 class coupling: residuals divisible by 10 pair well with
    // typical item sizes; odd "ragged" residuals are less reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0 - 0.3 * slack as f64;
        } else {
            // next item won't fit here: leftover becomes final dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave badly fragmented space and the item is large.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < 0.35 * bin_capacity as f64;
        let big_item = item_size > bin_capacity / 2;
        if fragmented && big_item {
            score -= 45.0;
        } else {
            // discourage opening new bins by default
            score += 55.0 + 0.5 * post_residual as f64;
        }
    }

    // Mean-residual drift: prefer bins below mean residual (tighter bins first),
    // keeping looser bins available for future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.25 * diff;

    // Progress-based mild adaptation: late in the stream, be greedier about
    // exact fits (less future to amortize loose bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual <= eighth {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty, harsher the smaller the dead gap relative to capacity.
        let gap = post_residual as f64;
        score += (1.0 + 40.0 / (gap + 5.0)) * (next_item_size as f64 - gap);
    } else if next_item_size > 0 {
        // Reward keeping the bin usable for the lookahead item.
        score -= 8.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bonus: avoid forcing a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins already tighter than average (fill fuller bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight early-stream conservatism: keep flexibility while many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fit (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: post residual consumed by next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // near-perfect chain
        } else {
            // next item cannot fit: post residual becomes potential dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "fuller"; prefer them
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the new-bin candidate unless it enables a perfect pair with next item
    if bin_residual == bin_capacity {
        let perfect_pair = next_item_size > 0 && (item_size + next_item_size) == bin_capacity;
        if perfect_pair {
            score -= 70.0;
        } else {
            score += 10.0 + 0.3 * (open_bins_count as f64);
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward leaving room for the next item proportionally to how well it fits
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for blocking
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: when many bins are open, prefer consolidating into existing bins
    let open_f = open_bins_count as f64;
    score += open_f * 0.5;

    // Prefer bins whose residual is close to the mean residual (balance across bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: late in the stream, be more conservative (avoid new bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist
        score += 10.0 + 40.0 * progress + 2.0 * open_f;
        // but early on, allow new bins more freely
        score -= 15.0 * (1.0 - progress);
    } else {
        // Existing bins get progressively better relative to new bins over time
        score -= 20.0 * progress;
    }

    // Prefer placing larger items into fuller bins (best-fit flavor)
    score -= 0.1 * (item_size as f64) * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, but with diminishing penalty as post grows
    let mut score = post * post / cap; // quadratic in post_residual

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills; late, tolerate larger residuals less
    let prog_coupling = post * (1.0 - progress) * (1.0 - progress);
    score += 0.5 * prog_coupling;

    // Cubic interaction: residual waste relative to mean residual of open bins
    let waste = (post - mean_residual).abs();
    score += 0.3 * waste * waste / cap;

    // Reward filling bins nearly completely (post near 0)
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to unusable space
        score += 0.2 * post;
    }

    // Many open bins: prefer consolidating into existing bins over opening new ones
    let open_norm = open_bins_count as f64;
    score += 0.05 * open_norm * (post / cap);

    // New-bin candidate: make it moderately attractive only when progress is early
    // and existing bins are crowded, via smooth terms
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
        score -= 0.02 * open_norm * open_norm * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 25 defines "usable slots"
    let class = post_residual % 25;
    // Class 0 (perfect multiples) is ideal, large odd-ish residuals near capacity are wasteful
    match class {
        0 => score -= 12.0,
        1 | 24 => score -= 6.0,
        10 | 20 => score -= 3.0,
        _ => score += (class as f64) * 0.15,
    }

    // Dead-space penalty: residuals that can never fit future min items (assume min 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact pairing bonus (harmonic match)
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item cannot use leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: only fitting bin -> strongly favor using it over opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // early in stream, opening bins is cheap-ish; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.85 {
        score -= 8.0;
    } else if fill < 0.3 {
        score += 5.0;
    }

    // Prefer bins below mean residual (balancing harmonic classes across bins)
    score += ((post_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual gap is "dead" if no plausible future item (>= 1) can fill it well.
    if post_residual > 0 {
        // Non-linear penalty: small gaps (1..=9) are almost unusable since min item is 1..100
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Coupling: dead space is worse late in the stream when fewer chances remain
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.35;

    // Penalize bins whose post-residual cannot fit the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward bins that can also host the next item (chaining)
        score -= 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // encourage consolidation when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 30.0 + 3.0 * open_bins_count as f64;
        // If no open bin fits well, allow new bin when item is large
        if item_size > 70 {
            score -= 20.0;
        }
    } else {
        // Favor packing into bins with already small residuals (tighter bins first)
        score -= 0.5 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 10.0;
        // Prefer bins close to mean residual (balance) mildly
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-step match
        }
        // penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.4;
        }
    } else {
        score += 10.0; // last item: prefer tightest fit strongly
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad,
    // but attractive when all fits leave large waste.
    if bin_residual == bin_capacity {
        score += 8.0 + (post_residual as f64) * 0.15;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: how well the item fills the bin's current residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward excellent fits (item nearly fills the bin)
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 15.0 * fit_ratio;
    }

    // Penalize large dead space after placement, scaled by stream progress
    // (early on, leftover space is more valuable; late, waste is fatal)
    let dead_space_penalty = (post_residual as f64) * (0.5 + 1.5 * progress);
    score += dead_space_penalty * 0.3;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            if next_fit > 0.9 {
                score -= 40.0; // perfect chain: place next here too
            } else if next_fit > 0.5 {
                score -= 20.0 * next_fit;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize more if post_residual is a small useless gap
            if post_residual < 10 {
                score -= 10.0; // small gap is fine, effectively closed
            } else {
                score += (post_residual as f64) * 0.2; // stranded mid-size gap
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let open_pressure = open_bins_count as f64 / (1.0 + progress.max(0.05) * 10.0);
    if bin_residual != bin_capacity {
        score -= open_pressure.min(15.0);
    }

    // Compare against mean residual: bins with residual close to item size are ideal
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.15;

    // Mean residual coupling: when mean residual is high, prefer bins that reduce it most
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.4;

    // New-bin candidate handling: brand-new empty bin gets a moderate default score.
    // Only prefer it when no existing bin fits well (high post_residual relative to capacity
    // or stranded gaps would result elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // Early stream: opening bins is cheaper (builds a portfolio of residuals)
        score -= (1.0 - progress) * 20.0;
        // If current bin would leave a big awkward gap, new bin becomes attractive
        if post_residual > 40 && next_item_size > post_residual && post_residual > 0 {
            score -= 15.0;
        }
        // If many bins already open, discourage opening yet another
        score += open_bins_count as f64 * 1.5;
    }

    // Small stochastic-free tiebreaker based on step parity of residual structure
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual

    let mut score = r;

    // Smooth non-linear coupling of post-residual with stream progress
    score -= 12.0 * rn * (1.0 - rn) * (0.5 + progress);

    // Penalize large residuals more as stream progresses (less time to fill them)
    score += 20.0 * rn * rn * progress;

    // Reward tight fits: small post residual
    score -= 15.0 * (1.0 - rn) * (1.0 - rn);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - rn);
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - rn);
    } else if next_item_size > 0 {
        score += 5.0 * rn;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins)
    score += 3.0 * (mean_residual - r) / cap;

    // Many open bins: prefer consolidation into existing bins
    score -= 4.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - rn);

    // New-bin candidate: penalize slightly unless residuals are tight overall
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) - 12.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let pr = post_residual;
    let class = (pr % 25) as f64;
    let quarter = (pr / 25) as f64;

    // Penalize residuals that fall into awkward classes (not multiples of common item sizes)
    score += 3.0 * class / cap;

    // Reward residual classes that are likely reusable (multiples of 10/20/25/50)
    if pr % 10 == 0 { score -= 2.0; }
    if pr % 20 == 0 { score -= 1.5; }
    if pr % 25 == 0 { score -= 1.0; }
    if pr % 50 == 0 { score -= 2.0; }

    // Perfect fit: huge reward
    if pr == 0 { score -= 50.0; }

    // Dead space: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 { score += 15.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr { score -= 4.0 * (1.0 - (pr - next_item_size) as f64 / cap); }
        else { score += 2.0; }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: prefer new bin only when fit is terrible
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.3;
        if pr % 10 == 0 && pr >= 20 { score -= 4.0; }
    }

    // Tight fill fraction reward
    let fill = 1.0 - post_residual as f64 / cap;
    score -= 5.0 * fill * fill;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill;

    // Many open bins: discourage fragmentation
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);

    // Quarter-class coupling: keep residuals in coarse harmonic bands
    score += quarter * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for likely future items
    // (typical items >= 10, but distribution unknown, so use a soft threshold).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // If next item fits exactly in post_residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        score -= 15.0 - (leftover as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Prefer bins whose residual is already below the mean (consolidating emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin is a fallback; make it unattractive
    // unless the current bin would be left with unusable dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0;
        // Early in the stream, new bins are cheaper (long future to use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= (1.0 - progress) * 10.0;
        // If placing here would create dead space, new bin becomes relatively better.
        if (post_residual as f64) < dead_threshold && post_residual > 0 {
            new_bin_score -= 20.0;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it packs.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving residual that's too small.
            let waste = post_residual as f64;
            score += 30.0 * (waste / bin_capacity as f64) * (waste / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare residual against mean residual across open bins.
    // A bin with residual below mean is "tighter" — placing here keeps diversity.
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Penalize opening a new bin when existing bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with how many bins are open.
        score += 120.0 + 5.0 * open_bins_count as f64;
        // If lookahead item could combine with current item in a fresh bin, soften.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
    }

    // Tight-fit preference: residual just above item size is ideal (best-fit core).
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Penalize leaving dead space that no typical item can fill well.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small leftover often wasted — but here we favor? Actually penalize unusable gap
    }
    // Penalize large awkward gaps relative to capacity
    let gap_frac = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * gap_frac * gap_frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 2.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - gap_frac;
    score -= fill * (open_bins_count as f64).sqrt() * 1.5;

    // Time horizon: early in stream, be more exploratory (favor new bins less);
    // late in stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill;

    // New-bin candidate: only attractive if current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if mean residual across open bins is low (all crowded), new bin is fine
        score -= (mean_residual / bin_capacity as f64) * 6.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item size.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let ni = next_item_size as f64;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on tolerate slack,
    // later on punish residuals more aggressively
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * prog_term * norm_pr * (1.0 + it / cap);

    // Reward tight fits: low post residual gets a smooth bonus
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * tightness;

    // Lookahead: reward leaving room for the next item (smooth kernel around match)
    if ni > 0.0 {
        let fit_next = ((ni - pr).abs() / cap).min(1.0);
        score -= 15.0 * (1.0 - fit_next) * (1.0 - fit_next);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + prog_term);
    }

    // Mean residual context: prefer bins below mean residual (keeps big bins available)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * dev.signum();

    // Slight preference for consolidating into fewer bins as stream progresses
    score += prog_term * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are preferred (waste is quantized).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: residue in [0,10) is near-perfect; [10,50) is reusable
    // for typical items; [50,100) wastes half a bin.
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 50 {
        score -= 8.0;
    } else {
        score += 12.0;
    }

    // Modulo classes: residues divisible by common item sizes (10, 20, 25)
    // are more likely reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportional to leftover size
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when it enables a tight
    // first placement and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when open bins have large mean residual (fragmented)
        // but penalize early and when item is small (better packed later).
        score = 40.0 + 0.5 * item_size as f64 - 15.0 * (mean_residual / cap) - 10.0 * progress;
        if item_size >= 50 { score -= 10.0; }
        if fitting_bins_count == 1 { score += 25.0; } // don't abandon the only fitting bin
    }

    // Slight preference for tighter fits overall.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        // Penalize large leftover space less when it can host plausible future items.
        let usable = (post_residual >= next_item_size && next_item_size > 0) as f64;
        score -= usable * 15.0;
        // Mild non-linear penalty on mid-range gaps that few item sizes can use.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        if gap_frac > 0.0 && gap_frac < 0.25 {
            score += 10.0 * (1.0 - gap_frac * 4.0);
        }
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual is still large.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when existing bins are nearly saturated or fit is terrible.
    if bin_residual == bin_capacity {
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let desperation = (fitting_bins_count == 0) as f64 * 100.0;
        score = 100.0 - desperation + 20.0 * stream_frac - 10.0 * (open_bins_count as f64).min(5.0);
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly or nearly accommodate the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact 2-chain: item + next fills bin perfectly
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 200.0 - 0.5 * slack_after_next as f64;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Penalize residuals that are small and unlikely usable (dead space),
    // unless they are zero (perfect fit handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 300.0;
        // early in stream, be more willing to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * (1.0 - progress);
    }

    // Slight preference for bins with larger residual (better containment)
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, keep bins tight; late, tolerate spread.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 0.5 + 0.5 * progress;

    // Lookahead: reward placements whose post-residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64) * horizon;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the upcoming item.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64) * (1.0 - horizon);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bin),
    // unless it is the new-bin candidate.
    if bin_residual < bin_capacity {
        let gap = mean_residual - post_residual as f64;
        if gap > 0.0 {
            score += 0.15 * gap;
        }
    }

    // New-bin candidate: baseline slightly above a decent fit so it only wins
    // when all open bins would create large unusable residuals.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score = bin_capacity as f64 - 8.0 + 0.5 * open_pressure - 10.0 * horizon;
        if next_item_size > 0 {
            score -= (100 - next_item_size) as f64 * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth coupling of post-residual with stream progress:
    // early stream -> mild penalty on residual; late stream -> stronger.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * norm_pr * norm_pr * cap * 0.2;

    // Reward tight fits (low post_residual) via cubic bonus, stronger late.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * (10.0 + 20.0 * t);

    // Penalize dead space that no typical next item can use (small residuals).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            // residual unusable for lookahead: penalize proportionally
            score += (nx - pr) * (1.0 + 2.0 * t);
        } else {
            // residual fits lookahead: reward
            score -= (nx * (1.0 - (pr - nx) / cap)) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * t;
    }

    // Many open bins: prefer consolidating into existing space.
    let ob = open_bins_count as f64;
    score -= (ob / (ob + 5.0)) * 3.0 * tightness;

    // Align with mean residual: bins near mean residual are "typical" targets.
    score += (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: penalize opening a bin unless current residuals are poor.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score += 8.0 - 10.0 * avg_waste + 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (C/4 classes)
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    // Reward small classes (tight fit) nonlinearly
    let class_reward = match class {
        0 => 30.0,
        1 => 12.0,
        2 => 4.0,
        3 => -2.0,
        _ => -8.0,
    };
    score -= class_reward;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does next item fit into post_residual exactly / well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let slack_class = slack / quarter;
            if slack_class == 0 { score -= 18.0; }
            else if slack_class == 1 { score -= 6.0; }
            else { score += (slack_class as f64) * 3.0; }
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        // but if mean residual across open bins is tiny, new bin is fine
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 25.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += (mean_residual - post_residual as f64) * 0.08;

    // Modulo harmonic penalty: post_residual in awkward residue classes (e.g. % 10 == 1..2) is dead-ish space
    let m = post_residual % 10;
    if m == 1 || m == 2 {
        score += 6.0;
    } else if m == 0 {
        score -= 4.0;
    }

    // Mild pressure when many bins open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space: penalize proportionally to how much of it is unusable.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual == next_item_size {
            // Perfect fit for the next item: strong reward.
            score -= 30.0;
        } else {
            // Usable residual: mild reward scaled by how well next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack / 20.0);
        }
    }

    // Tight fit reward: near-full bins are excellent outcomes.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize tiny unusable gaps (< minimum item size 1 handled implicitly; still
    // penalize residuals in the awkward 1..=10 zone as near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins are congested
    // or mean residuals are too small to matter.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 120.0 - congestion * 10.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is below average, it's a
    // fragmented bin; filling it is good.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for an exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward near-matches of post_residual to next item (small gap = likely chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    }

    // Penalize leaving residuals that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Penalize tiny unusable residuals generally.
    if post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average when fit is good.
    let mean_gap = mean_residual - bin_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-worse unless
    // current bin would leave a large dead residual relative to next item.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 150.0; // fresh bin may serve the next item better
        } else {
            score += 50.0; // prefer filling existing bins when reasonable
        }
    }

    // Mild late-stream pressure to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (best-fit core)
    let fit_ratio = item_size as f64 / bin_residual as f64; // how much of the residual the item consumes
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 1.5; // nearly-full bins are fine; tiny scraps are wasted
    }
    if dead == 0.0 {
        score -= 15.0; // perfect closure is excellent
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post-residual can't host the next item: penalize proportionally to wasted potential
            let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.15 * waste;
        }
    }

    // Prefer filling bins whose residual is close to the item (avoid carving small items out of big gaps)
    let gap = (bin_residual as f64 - item_size as f64);
    score += 0.05 * gap;

    // Global state: when many bins are open and mean residual is low, consolidate into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 0.3 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= consolidation * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; decreases late in stream when fragmentation is high
        score = bin_capacity as f64 * 0.5 + 10.0;
        score -= 2.0 * (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 25.0; // forced new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // new bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Normalized post-residual, smooth polynomial shaping
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;

    // Favor tight fits: reward low post_residual non-linearly
    score -= (1.0 - pr2) * (1.0 - pr2) * 8.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            let waste = nxt - post_residual as f64;
            score += waste * (1.0 + 3.0 * progress);
        } else {
            // Reward leaving room for the next item
            score -= 4.0 * (1.0 - ((post_residual as f64 - nxt) / cap).powi(2));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly unless current bin would leave bad waste
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    // Coupling with mean residual: prefer bins near the mean (balance preservation)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 6.0 * (1.0 - progress);

    // Smooth stream-progress interaction: later in stream, prefer tighter packing
    score *= 1.0 - 0.25 * progress * pr2;

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: modulo classes relative to common item sizes.
    // Small residuals (< 10) are dead space; medium residuals can host small items.
    let pr = post_residual;
    if pr < 10 {
        score += 60.0; // dead space penalty
    } else if pr < 20 {
        score += 25.0;
    } else if pr < 35 {
        score += 8.0;
    }

    // Modulo-10 class: residuals divisible by 10 align with the integer item grid.
    if pr % 10 == 0 {
        score -= 12.0;
    }
    // Harmonic classes of pr mod 5 / mod 3: even divisibility tends to be reusable.
    if pr % 5 == 0 {
        score -= 4.0;
    }
    if pr % 3 == 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            score -= 20.0 * (next_item_size as f64 / pr as f64);
            // harmonic bonus if next item leaves another divisible residual
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize by wasted potential
            score += 10.0 * (1.0 - (pr as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a bin early is wasteful when many bins
    // are open and mean residual is high; make empty bin moderately attractive
    // only when existing residuals are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3 - (open_bins_count as f64).ln() * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for tighter bins overall (below-mean residual is good).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;

    // Small tie-breaker favoring larger items placed into larger residuals.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio * (post_residual as f64);

    // Dead space penalty: post_residual too small for the next item is wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (consolidate large gaps).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap; // 0 = perfect fit

    // Penalize dead space super-linearly, but only when it's truly unusable.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let avg_item = 50.0_f64.min(100.0 - mean_residual.max(0.0)).max(10.0);

    // If post_residual is smaller than the smallest plausible future item,
    // it's dead space -> strong penalty.
    if post_residual > 0 && (post_residual as f64) < avg_item * 0.25 {
        score += 30.0 * (1.0 - post / avg_item.max(1.0));
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            // Perfect chaining: this bin will be exactly refilled by next item.
            score -= 60.0;
        } else if (diff as f64) <= 10.0 {
            score -= 30.0 * (1.0 - diff as f64 / 10.0);
        } else {
            // Next item cannot use the leftover: mild penalty scaled by waste.
            score += 0.3 * diff as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate (empty bin): only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish anchor: slightly worse than a perfect fit in an open bin,
        // better than leaving big unusable leftovers.
        score = cap * 0.45 + 0.5 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative -> open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // next item is large; fresh bin useful
        }
        return score;
    }

    // Reward bins whose residual is already below mean (consolidating small bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Late in the stream: be greedier about tight fits.
    score *= 1.0 + 0.5 * progress * fit_ratio;

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += 6.0 + 0.05 * (post_residual as f64);
        } else {
            // Reward bins that can still host the next item.
            score -= 3.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize unless the current bin's fit would be wasteful.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64) - (item_size as f64);
        // Open a new bin only if best existing fit would leave huge dead space.
        score += 15.0 + 0.4 * waste - (mean_residual - item_size as f64).abs().min(50.0);
        if next_item_size as u32 >= bin_residual {
            score -= 10.0; // next item needs full capacity anyway
        }
    } else {
        // Slight preference for bins whose residual is near the mean (balance).
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Late in the stream, close out bins aggressively.
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) dead-space penalty.
    let mut score = pr + 30.0 * norm_post * norm_post;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let coupling = (2.0 * t - 1.0) * (2.0 * t - 1.0); // smooth 0..1..0 bump
    score += coupling * 25.0 * norm_post * (1.0 - norm_post);

    // Tight-fit reward: cubic interaction between fill ratio and progress.
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 20.0 * fill * fill * fill * (0.5 + t);

    // Penalize leaving a gap that the next item cannot use, scaled by progress.
    if next_item_size > 0 && pr > 0.0 {
        let gap_mismatch = (pr - next_item_size as f64).abs() / cap;
        score += 15.0 * gap_mismatch * gap_mismatch * (0.3 + t);
    } else if next_item_size == 0 {
        // Last item: any residual is dead space.
        score += 10.0 * norm_post;
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening a new bin unless it's early or residuals are tight.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 35.0 * (1.0 - t) * (1.0 - tightness) + 20.0 * (1.0 - t);
    }

    // Mild penalty for bin proliferation.
    score += 0.5 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes (residual in {0, 10, 20, 25, 50})
    // are highly reusable; reward them strongly.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class_bonus = match pr {
            10 | 20 | 25 | 50 => 45.0,
            30 | 40 | 33 | 34 | 66 | 67 => 20.0,
            _ => {
                // penalize tiny unusable slivers (1..=9)
                if pr < 10 { -30.0 } else { 0.0 }
            }
        };
        score -= class_bonus;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 25.0 * fill;
        } else {
            // next item won't fit here: penalize large residuals slightly
            score += 8.0 * (pr as f64 / cap);
        }
    }

    // Harmonic capacity-fraction coupling: residual that is a clean divisor
    // fraction of capacity is more valuable.
    let frac = pr as f64 / cap;
    if (frac * 4.0).round() / 4.0 == frac && pr > 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size > item_size {
            score += 15.0; // big-next-item incoming, new bin may be fine
        } else {
            score += 10.0;
        }
    }

    // Fragmentation pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score += 20.0 * frag * (open_bins_count as f64).ln();
    }

    // Late in stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100)
    // can use are pure waste; penalize especially small unusable gaps.
    if post_residual > 0 {
        // gap smaller than the smallest plausible item (<=10) is dead space
        if post_residual < 10 {
            score += 60.0 + (10.0 - post_residual as f64) * 8.0;
        } else if post_residual < 25 {
            score += 20.0 + (25.0 - post_residual as f64) * 1.5;
        }
    } else {
        // perfect fill is heavily rewarded
        score -= 45.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact fit for next item is even better
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // leftover can't host the next item: mild penalty scaled by waste
            let waste = post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when tight fits exist
    let pressure = open_bins_count as f64;
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // placement would create a large unusable gap.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // if this placement would waste a big chunk of an existing bin, a new
        // bin becomes attractive: reduce the new-bin cost.
        if post_residual < 10 && bin_residual > item_size {
            score -= 55.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean-residual coupling: if open bins are already tight on average,
    // placing here (a good fit) is more valuable.
    if (mean_residual - post_residual as f64).abs() > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 0.5;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 200.0; // aggressive reward for chain completion
        } else if post_residual >= next_item_size {
            // Next item could still fit here: mild penalty to discourage hoarding space
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit in remainder: penalize proportionally to waste
            let waste = post_residual as f64;
            score += waste * 0.8;
            // But if remainder is small (good fill), soften the penalty
            if post_residual <= 10 {
                score -= 25.0;
            }
        }

        // Lookahead coupling with mean residual: bin far below mean is a good host
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        // Last item: just fill the emptiest usable space
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post-fit residual is large (poor fit) and many bins are open
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score so poor fits in existing bins lose to it
        score = bin_capacity as f64 * 0.55
            - 40.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0))
            + (post_residual as f64);
        // If next item is large, a fresh bin is more attractive
        score -= 0.2 * next_item_size as f64;
        // Late in stream, prefer consolidation into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Slight preference for bins that are already well-filled
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful (below typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: residual is dead weight
            score += 6.0 + 0.15 * pr;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine early, or when many bins are open with slack,
        // but costly when few bins exist and item fits well somewhere.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0;
        new_bin_score -= 40.0 * progress;              // later: prefer consolidation
        new_bin_score -= 2.0 * open_bins_count as f64; // many open bins: reuse them
        new_bin_score += (mean_residual - pr) * 0.3;   // high mean slack: reuse better
        score = score.min(score + new_bin_score);
        // If item would leave a perfect residual in a new bin (rare exact split), allow it.
        if item_size * 2 == bin_capacity {
            score -= 20.0;
        }
    } else {
        // Reusing an existing bin: reward relative to mean slack of open bins.
        if mean_residual > 0.0 {
            score -= 5.0 * (bin_residual as f64 / mean_residual);
        }
        // Prefer fuller bins (best-fit bias amplified by number of alternatives).
        score -= (fitting_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.2;
    }

    // Global consolidation pressure: as stream progresses, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let poly = fit_norm * fit_norm * (0.5 + 2.0 * progress) - fit_norm * (1.0 + progress);
    let mut score = pr * (1.0 + 0.4 * progress) + 30.0 * poly * cap;

    // Penalize residual that cannot fit the lookahead item (smooth quadratic falloff)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 40.0 * gap * gap * cap;
        // Reward exact-ish match with lookahead
        let match_term = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 15.0 * match_term * match_term;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Mild penalty when this bin is far below mean residual (wasting large space early)
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * cap;

    // New-bin candidate: make it attractive only when no open bin fits well
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 45.0 + 40.0 * progress;
    }

    // Slight preference for denser packing when many bins are open
    score += 0.3 * open_bins_count as f64 * fit_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100, capacity 100.
    // Residuals divisible by large item sizes are more reusable.
    let cap = bin_capacity as f64;

    // Reward residuals that fall into "harmonic" classes: multiples of common sizes
    let harmonics: [u32; 8] = [100, 50, 25, 20, 10, 40, 33, 34];
    for &h in &harmonics {
        if h <= post_residual && post_residual % h == 0 {
            score -= 8.0 + (h as f64).sqrt();
            break;
        }
    }

    // Penalize awkward residuals: small prime-ish remainders that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty scaled by how badly
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // last item: prefer filling most tightly
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it if all fits are terrible (large post_residual waste elsewhere)
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / cap;
        score += 20.0 - 15.0 * avg_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin is flexible for lookahead
        }
    }

    // Prefer tighter fits overall: reward small post_residual nonlinearly
    score -= 10.0 * (-post_residual as f64 / 30.0).exp();

    // Progression: later in the stream, be more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    // Many open bins: prefer reusing (penalize new bins implicitly via residual)
    if open_bins_count > 4 {
        score -= 2.0 * (mean_residual - post_residual as f64).signum();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

