    // Open bins pressure: prefer existing bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residual is very tight
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // but if item is large and no bin is tight, new bin is reasonable
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates less from mean (keeps bin profile uniform)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
