    // New-bin candidate: only attractive when current bin leaves bad residue
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
        // Encourage new bin early in stream (plenty of future items)
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

