    }
    // If next item cannot fit here, mild penalty proportional to wasted opportunity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate: usually discouraged, unless current fits are loose
    // (high mean residual spread) or late in the stream.
    if is_new_bin {
        let dispersion = (mean_residual - post_residual as f64).abs();
        let mut penalty = 18.0;
        if fitting_bins_count <= 1 {
            penalty -= 12.0; // few alternatives: new bin is acceptable
        }
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < next_item_size {
            penalty -= 4.0; // existing bins would leave awkward gaps anyway
        }
        penalty -= 6.0 * progress; // late stream: consolidation matters less
        penalty -= dispersion.min(10.0) * 0.3;
        score += penalty.max(0.0);
    }

    // Mild preference for bins with residuals near mean (balanced packing),
    // modulated by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.05 + 0.01 * open_bins_count as f64);

    // Early stream: encourage keeping bins balanced; late stream: fill greedily.
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling: tight fits are progressively rewarded
    // more as the stream progresses (later items benefit more from compact bins).
    let tightness = 1.0 - (pr / cap);
    let poly_coupling = tightness * tightness * (0.5 + progress) * 20.0;
    score -= poly_coupling;

    // Penalize dead space that cannot host the lookahead item: cubic penalty
    // growing with progress, since late waste is never recoverable.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let dead = (gap / cap).powi(3) * (1.0 + 2.0 * progress) * 40.0;
        score += dead;
    } else if next_item_size == 0 && post_residual > 0 {
        // Last item: prefer minimal leftover, quartic shaping.
        score += (pr / cap).powi(4) * 30.0;
    }

    // Reward bins that can host the next item too (chained placements),
    // with smooth quadratic interaction of fit ratio and progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = ((next_item_size as f64 / pr.max(1.0)).min(1.0)).powi(2);
        score -= chain * (10.0 + 15.0 * progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin,
    // scaled by how full the bin already is (non-linear fill affinity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = 1.0 - (bin_residual as f64 / cap);
        score -= 25.0 + 30.0 * fill * fill;
    }

    // New-bin candidate (empty bin): penalize moderately when other bins fit,
    // more so early in the stream; relax late when fragmentation dominates.
    if bin_residual == bin_capacity {
        let base = 30.0 * (1.0 - progress).powi(2) + 8.0;
        score += base + (open_bins_count as f64).powf(0.5) * 2.0;
    } else {
        // Mildly prefer bins below mean residual (balance fragmentation),
        // smooth quadratic deviation term.
        let dev = pr - mean_residual;
        score += 0.05 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-eighth buckets.
    let class = post_residual / 12; // 100/12 ≈ 8 classes
    score += (class as f64) * 4.0;

    // Perfect-fit harmonic classes: residuals that pair with common item sizes (multiples of 10/20/25).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Dead space penalty: residual too small for the smallest plausible item (1..100, min 1).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 5.0; }
            score += gap as f64 * 0.2;
        } else {
            // next item won't fit here: mild penalty scaled by overshoot class
            let over = (next_item_size - post_residual) / 15;
            score += over as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with lower residual (best-fit bias) modulated by mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Discourage opening new bins when several bins fit well.
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64) * 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin still useful for upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 12.0; // still a decently tight fit
    }

    // Reward bins whose leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (next_item_size as f64);
    }

    // Open-bin pressure: discourage spreading into many bins.
    score += 1.5 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += 0.6 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive if item is large relative to capacity
    // (opening fresh space for big items avoids fragmentation).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let penalty = 20.0 + 55.0 * (1.0 - fill);
        score += penalty;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        let nz = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect two-item packing bonus
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space
            score += 0.6 * (post_residual as f64 - nz).abs();
        }
    } else {
        // Last item: prefer tightest fit
        score += 2.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Compare post residual against mean residual of open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 8.0 * rel; // penalize bins left much fuller than average (unbalanced)
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: penalize unless current bin fit is very poor
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 15.0 - 10.0 * tightness;
        // Opening a new bin is good if no open bin leaves a good residual for the next item
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for fewer open bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer placements that leave small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals too small for typical items (1..100 unknown,
    // so penalize residuals below a soft floor) — worse early when bins are scarce.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_floor = 10.0_f64.min(post_residual as f64);
    score += (dead_floor * dead_floor) * 0.05 * (1.0 - progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Blocking next item: cost scales with how open the system is.
            score += 6.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        } else {
            // Next item still fits: mild reward proportional to leftover pairing quality.
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is attractive only when no
    // existing bin fits well. Penalize the fresh bin mildly so tight fits win,
    // but reward it when current bins would leave large waste.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 20.0 - 8.0 * open_pressure.min(2.5);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Late in the stream, prefer consolidation into open bins.
        score += 10.0 * progress;
    }

    // Prefer filling bins with larger mean residual (consolidate fragmented space).
    if bin_residual != bin_capacity {
        score -= 3.0 * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as the stream progresses (smooth ramp)
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bin: strong reward, damped by how much dead space remains
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * pr_norm);
    }

    // New-bin candidate: penalize opening a new bin, especially early and when good fits exist
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 18.0 * (1.0 - 0.6 * progress) + 10.0 * fit_pressure;
    }

    // Lookahead: penalize leaving residual too small for next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).max(0.0) / cap;
        let wasted = (ni - pr).max(0.0) / cap;
        score -= 6.0 * gap * (1.0 - gap);
        score += 9.0 * wasted * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins, smoothed by mean residual
    score += 0.4 * open_bins_count as f64 * (mean_residual / cap).powf(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste created by this placement (primary driver).
    let mut score = post;

    // Harmonic class of post_residual: classify leftover space into coarse buckets
    // via integer division on the capacity. Classes near small residuals are good.
    let class = post_residual / 10; // 0..10 harmonic class
    score -= (10 - class as f64) * 3.0; // reward small-residual classes

    // Non-linear penalty for "awkward" dead space: residuals that few future
    // item sizes can fill (residual in 20..40 range is hardest to use).
    if post_residual >= 20 && post_residual < 40 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: this is the only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, prefer consolidating into existing bins less harshly
    // (keep several bins open to enable good pairings later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.1;

    // New-bin candidate (empty bin): make it unattractive unless existing fit is bad.
    if bin_residual == bin_capacity {
        score += cap * 0.6 + post_residual as f64 * 0.0;
        // But if many bins are open and mean residual is small, opening fresh is fine.
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= cap * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // small gap: only useful if the lookahead item fits it
        if next_item_size == 0 || (next_item_size as f64) > post_residual as f64 {
            score += 25.0;
        } else {
            score -= 15.0;
        }
    }

    // Reward tight packing (exact or near-exact fits).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual < 25 {
        // next item won't fit in the leftover gap -> dead space risk
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but
    // relax pressure late in the stream when closing bins matters.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it neutral-ish; only attractive when
    // no open bin offers a decent fit (post_residual near capacity - item)
    // or when mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // open a new bin if existing bins are fragmented or this is a big item
        if fragmentation < 30.0 || item_size > 60 {
            score -= 10.0 + 8.0 * (item_size as f64 / 100.0);
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best fit).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: strongly reward bins whose post-residual exactly
    // matches the next item, or can tightly contain it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize post-residuals that are small but non-zero (unusable slivers),
    // unless the next item can use them.
    if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 80.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean
    // (tighten crowded bins), penalize draining the emptiest bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer the tightest fit.
        score += 0.2 * (bin_residual as f64 - item_size as f64);
    }

    // Opening a new empty bin: only attractive when the current item is
    // large and no good squeeze exists; otherwise penalize new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Reward new bin for large items, penalize for small ones.
        score += 40.0 - 90.0 * item_frac + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 50.0; // discourage abandoning existing fitting bins
        }
    }

    // Mild preference for keeping the number of open bins stable.
    if open_bins_count > 1 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
