pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize residual more strongly
    let prog_coupling = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= prog_coupling;

    // Reward filling bins deeply when many bins are open
    let fill_frac = item_size as f64 / cap;
    score -= 12.0 * fill_frac * (1.0 + progress);

    // Penalize creating dead space relative to mean residual (non-linear)
    let dead = (pr - mean_residual).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Lookahead: reward leaving room for next item (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr as i64 - next_item_size as i64) as f64;
        let match_bonus = (-diff * diff / (2.0 * 900.0)).exp();
        score -= 8.0 * match_bonus * (1.0 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty when many bins open: encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10 units.
    let class = (post_residual / 10) as f64;
    // Non-linear penalty on class: large residuals are fine only if reusable.
    score += class * class * 0.35;

    // Perfect fits are extremely valuable.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: reward bins whose residual can host the next item snugly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Tightness of the next fit: small slack is good.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + slack / 20.0);
        } else {
            // Residual too small for next item: penalize dead space, worse for
            // very small residuals (modulo-10 low classes).
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.6;
            if post_residual < 10 {
                score += 60.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 {
            // A fresh bin always fits the next item; mild reward.
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: opening is fine
        } else if fitting_bins_count == 1 {
            score += 150.0; // discourage stealing the last-chance bin
        }
        // Early in stream, opening bins is cheaper (build a portfolio of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
    } else {
        // Prefer bins with residual close to item_size (tight fit) via harmonic coupling.
        let tight = (bin_residual - item_size) as f64;
        score += tight * 0.05;
        // Favor bins whose residual is near mean residual (balanced portfolio),
        // penalize outliers.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Slight pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward using bins that would otherwise waste space.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 1.5 * open_bins_count as f64;
    }

    // Lookahead: reward residual that can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Prefer bins below mean residual (filling emptier bins keeps balance).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit (minimize post_residual), slightly tightened over time.
    score += 0.5 * progress * post_residual as f64;

    // Reward tight fits: waste ratio penalty for large dead space
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 25.0; // perfect pairing
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving awkward residue
        score += 3.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far below mean residual (fragmenting across many bins)
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // Many open bins: prefer consolidating into existing bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if existing fits are poor
        // (large post_residual would result elsewhere) or early in the stream.
        let poor_fit_threshold = 0.35 * bin_capacity as f64;
        if post_residual == bin_capacity {
            // It's the empty bin itself: its "post_residual" equals capacity.
            // Score it as a fallback: bad unless few fitting bins exist.
            if fitting_bins_count <= 1 {
                score = -50.0; // must open a new bin
            } else {
                score = 100.0 + 50.0 * waste_ratio;
            }
        } else {
            // (defensive; empty bin always has post_residual == capacity)
            score = 100.0;
        }
        // Early stream: opening bins liberally is fine
        score -= 20.0 * (1.0 - progress);
        // If this item would leave a big hole in any existing bin, prefer new bin
        let _ = poor_fit_threshold;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling: tight fits rewarded progressively more as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space quadratically; stronger later in the stream.
    score += 10.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);

    // Reward bins whose residual aligns with the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = ((pr - next_item_size as f64) / cap).abs();
        score += 6.0 * gap * gap - 4.0 * (1.0 - gap);
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: discourage opening a new bin unless residual
    // would be unusually large (poor fit everywhere) or many bins already open.
    if bin_residual == bin_capacity {
        let too_big = (norm_item < 0.35) as i32 as f64;
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (norm_item * 2.0 - 0.7).clamp(-1.0, 1.0);
        score += 18.0 - 22.0 * too_big - 8.0 * crowding + 5.0 * progress;
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (1/4, 1/3, 1/2 bands) to reward "usable" leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits strongly (small post_residual).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if frac <= 0.1 {
        score -= 20.0;
    } else if frac <= 0.25 {
        score -= 8.0;
    } else if frac <= 0.5 {
        score -= 2.0;
    } else {
        // large leftover: penalize dead space super-linearly
        score += (frac - 0.5) * 30.0;
    }

    // Integer-division thresholds on post_residual: leftovers that can
    // still host common small items are valuable.
    if post_residual >= 60 { score += 12.0; }
    else if post_residual >= 40 { score += 5.0; }
    else if post_residual >= 20 { score -= 3.0; }
    else if post_residual >= 1 { score -= 6.0; }

    // Harmonic coupling with lookahead: if the next item fits the
    // post-residual exactly (same harmonic class), reward heavily.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let gap = pr - ni;
            if gap == 0.0 {
                score -= 25.0;
            } else if gap <= 10.0 {
                score -= 10.0;
            } else {
                score -= 4.0 * (1.0 - gap / cap);
            }
        } else {
            // next item won't fit here: leftover becomes dead space
            score += (ni - pr).min(40.0) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when few bins are open,
        // but discourage it when existing bins can absorb the item well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 30.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        score += base;
        // But if the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mild preference for bins below mean residual (keeps balance,
    // preserves larger holes for future large items).
    if (pr as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Modulo-class tiebreak on post_residual (harmonic granularity of 5):
    // leftovers near multiples of 5 align better with typical item sizes.
    let m = post_residual % 5;
    score -= (2 - m.min(5 - m)) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaled by open bins.
        score += 55.0 + 6.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty when this bin's residual is far above the mean (fragmented bin).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter chain => bigger reward.
            score -= 60.0 - slack.min(50.0) * 0.8;
        } else {
            // Post-residual too small for next item: penalize dead space,
            // worse when it is small-but-unusable.
            let dead = post_residual as f64;
            score += dead * 0.6;
        }

        // If the next item also fits almost exactly after this placement,
        // give a bonus proportional to tightness.
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * tightness;
        }
    } else {
        // Last item: minimize leftover waste directly.
        score += post_residual as f64 * 0.3;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (denser bins), penalize placing into unusually empty bins.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    // or no real open bin competes. Base new-bin cost grows with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 70.0 + 30.0 * progress;
        // Allow new bin if placement here would leave large unusable fragment.
        if post_residual > 0 && post_residual < 10 {
            score -= 90.0;
        }
    }

    // Mild preference for tighter fits overall (small item-to-residual gap).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Slight penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual, especially when it is
    // small enough to be "dead space" for typical items.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score -= 12.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward filling bins nearly exactly.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would fit in post-residual anyway, mild reward.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 14.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers
            // that are smaller than typical items.
            if post_residual > 0 && post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // New-bin candidate handling: empty bins should only win when the item
    // fits poorly in existing bins (large item, high mean residual scatter).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 10.0;
        // More open bins -> cheaper to open another? No: penalize more when
        // many bins already exist (fragmentation risk grows).
        new_bin_penalty += (open_bins_count as f64).sqrt() * 1.5;
        // If mean residual is high, existing bins are roomy -> opening a new
        // bin is less justified.
        new_bin_penalty += mean_residual * 0.15;
        // Big items early in the stream justify new bins less (plenty of room).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += (1.0 - progress) * 4.0;
        // If the item is large relative to capacity, a fresh bin is attractive.
        let size_frac = item_size as f64 / bin_capacity as f64;
        new_bin_penalty -= size_frac * 12.0;
        // If few bins can fit the item, new bin becomes more attractive.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for bins whose residual is close to the item (good fit
    // ratio), scaled by global mean residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 4.0;

    // Time-horizon term: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Small tie-breaker toward bins below mean residual (already tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0).max(1.0) } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Non-linear coupling: penalize residual more heavily as stream progresses,
    // since late-stage fragmentation is harder to repair.
    let frag = post_residual as f64 / cap;
    score += 22.0 * frag * frag * (0.4 + 0.6 * p2) * (1.0 + 0.35 * p3);

    // Reward near-perfect fits with a smooth quadratic trough at post_residual == 0.
    let perfect = 1.0 - frag;
    score -= 30.0 * perfect * perfect * perfect * (0.6 + 0.4 * progress);

    // Lookahead: reward residuals that can host the next item (smooth gate).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits = (post_residual as f64 - ni).max(0.0);
        let gate = 1.0 / (1.0 + (fits / 12.0).exp());
        score -= 14.0 * gate * (1.0 - 0.3 * p2);
        // Penalize leaving residual just below the next item (dead space).
        let gap = ni - post_residual as f64;
        if gap > 0.0 && gap <= 20.0 {
            score += 8.0 * (1.0 - gap / 20.0) * (1.0 - gap / 20.0);
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad fits.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        score = cap * 0.55 + 18.0 * (1.0 - (mean_fit_gap / cap).min(1.0)) + 6.0 * (open_bins_count as f64).sqrt() - 20.0 * progress;
        // If some bin fits perfectly-ish, discourage new bin.
        if mean_fit_gap < 4.0 {
            score += 40.0;
        }
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.15 * (open_bins_count as f64) * p2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-exact fills.
    // Class 0: post_residual == 0 (perfect) ; class 1: <= 10 ; class 2: <= 20, etc.
    let cls = (post_residual + 9) / 10; // 1..=10 harmonic decade class
    score -= match cls {
        1 => 60.0,
        2 => 35.0,
        3 => 18.0,
        4 => 8.0,
        _ => 0.0,
    };

    // Exact fit is overwhelmingly good.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits into post_residual, this placement
    // chains nicely; reward proportional to how well it packs the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0 + (slack_after_next as f64) * -0.2; // tighter chain -> bigger reward
        // Harmonic bonus if next item leaves another near-perfect class
        let ncls = (slack_after_next + 9) / 10;
        if ncls <= 2 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving medium dead space.
        if post_residual >= 10 && post_residual < 40 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin
    // packs the item tightly, i.e. penalize opening a bin when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ residual it will hold after placement.
        score = (bin_capacity - item_size) as f64 + 40.0;
        if post_residual <= 20 {
            // item nearly fills a fresh bin alone -> fine to open
            score -= 50.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Mild preference for bins with below-average residual (tighter bins first),
        // keeping loose bins for larger future items.
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.15;
        }
    }

    // Modulo-flavored micro-structure: residual congruent to small values mod 10
    // are more usable by typical small items.
    if post_residual % 10 <= 3 && post_residual > 0 {
        score -= 4.0;
    }

    // Penalize proliferation of open bins slightly to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }
    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Dead-zone shaping: residual just below the minimum item size is dead space.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: penalize spreading across many bins when the new-bin
    // candidate (residual == capacity) would otherwise win too easily.
    if bin_residual == bin_capacity {
        // New bin: baseline cost, plus pressure proportional to open bins.
        score = 50.0 + 6.0 * open_bins_count as f64;
        // A new bin is acceptable if current bins have poor mean residual fit.
        if mean_residual < item_size as f64 * 0.35 {
            score -= 30.0;
        }
    } else {
        score -= 6.0 * open_bins_count as f64;
    }

    // Lookahead (k=2): reward leaving residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 15.0; // next item cannot use this gap
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 25.0 * progress;
    }

    // Mild penalty for wasting a large bin on a small item.
    score += 0.3 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // next item fits too: mild reward proportional to leftover after that
            let after_next = post_residual - next_item_size;
            score -= 50.0 + after_next as f64 * 0.3;
        } else {
            // next item won't fit: penalize dead space, worse when very small
            let dead = post_residual as f64;
            score += (next_item_size - post_residual) as f64 * 1.5 + dead * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize creating tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // default penalty; reduced if item is large relative to capacity
        score = 60.0 - tightness * 55.0
            + if next_item_size > 0 && next_item_size <= bin_capacity {
                (bin_capacity - next_item_size) as f64 * 0.4
            } else {
                0.0
            };
        if fitting_bins_count == 1 {
            score += 250.0; // never open new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
