pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post-residual with stream progress
    let mut score = pr as f64;
    let poly = x * x * (1.0 - progress) + (1.0 - x) * (1.0 - x) * progress;
    score += 40.0 * poly * (x - 0.5) * 2.0;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (30.0 + 40.0 * progress);

    // Penalize last-chance bins being wasted on poor fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            score -= 12.0 * gap * (1.0 - progress);
        } else {
            score += 10.0 * (-gap);
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize by capacity fractions (10% classes).
    let class = (post_residual * 10 / bin_capacity) as i64; // 0..10
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * (1.0 + 0.05 * class as f64);

    // Dead-space penalty: residuals in awkward classes (e.g. 1..9 of 100) are hard to reuse.
    if class >= 1 && class <= 2 {
        score += 12.0;
    }

    // Coupling with lookahead item: reward residual >= next_item_size (item can chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Harmonic match: next item exactly fills a class boundary.
        let next_class = (next_item_size * 10 / bin_capacity) as i64;
        if post_residual == next_item_size {
            score -= 15.0; // perfect pairing
        }
        if class == next_class {
            score -= 3.0;
        }
    } else {
        // Last item: any bin is fine, prefer tightest.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless no other bin fits or mean residual is tiny.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 25.0;
        if fitting_bins_count == 0 {
            penalty = -50.0; // forced open
        }
        penalty -= 10.0 * mean_residual / bin_capacity as f64;
        penalty *= 1.0 - 0.3 * progress;
        score += penalty;
    }

    // Mild pressure to reuse existing bins as stream grows.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score += 15.0 * (15 - post_residual) as f64 / 15.0;
    }

    // Reward bins whose leftover can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Pressure from number of open bins: prefer already-open bins over new ones.
    score -= 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it unattractive unless residual pressure is extreme.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Late in the stream, consolidate: slight bias toward filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits: strong reward, tighter is better
            score -= 30.0 - gap * 0.5;
        } else {
            // next item does not fit: penalize wasted space that blocks it
            score += gap * 0.3;
        }
        // perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (fuller bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 35.0;
        // early in stream, opening bins is cheaper; late in stream, pack tightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if next item is huge, a fresh bin may be valuable
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Dead space penalty: small post_residual that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference to spread load when many bins open (avoid fragmentation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), scaled by how "wasted" the fit is.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual - next_item_size).min(20) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins already have room.
    if bin_residual == bin_capacity {
        let avg_freed = if open_bins_count > 0 { mean_residual } else { 0.0 };
        score += 8.0 + 0.4 * open_bins_count as f64;
        if avg_freed > item_size as f64 {
            score += 5.0; // open bins already have slack; don't add another
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = it / cap;
    let mut score = pr;

    // Base: prefer tight fills; quadratic reward for small post_residual.
    let tight = 1.0 - pr / cap;
    score -= 30.0 * tight * tight;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack (future items may fill it); late, penalize waste.
    let slack_pen = (pr / cap).powi(3) * (20.0 + 60.0 * progress * progress);
    score += slack_pen;

    // Perfect-fit coupling: polynomial interaction of fill ratio and progress.
    let fill = 1.0 - fit_frac;
    score -= 25.0 * fill * fill * (0.5 + progress);

    // Last-chance bin bonus (smooth): avoid opening new bins when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 35.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space more as stream ends.
        score += (pr / cap) * (15.0 + 25.0 * progress);
    }

    // New-bin candidate: penalize opening a bin when open bins exist and fit well,
    // unless current residuals are all poor (mean residual small relative to item).
    if bin_residual == bin_capacity {
        let mean_fit = if cap > 0.0 { mean_residual / cap } else { 0.0 };
        let desperation = (1.0 - mean_fit).powi(2);
        let open_factor = (open_bins_count as f64).ln_1p().max(0.0);
        score += 55.0 * open_factor * (1.0 - desperation) - 25.0 * desperation;
        // Slightly favor new bins early (room to consolidate later).
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild preference to use bins below mean residual (balance loads smoothly).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of the residual: residues divisible by common item sizes (10,20,25,50)
    // are more reusable, so reward them.
    let res = post_residual;
    let reusability: f64 = if res == 0 {
        40.0 // perfect fill
    } else if res % 50 == 0 {
        25.0
    } else if res % 25 == 0 {
        18.0
    } else if res % 20 == 0 {
        15.0
    } else if res % 10 == 0 {
        10.0
    } else if res % 5 == 0 {
        4.0
    } else {
        0.0
    };
    score -= reusability;

    // Reward if next item fits exactly into post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == res {
            score -= 35.0;
        } else if next_item_size <= res {
            let slack = (res - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large leftover less if bin nearly full
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins can still fit the item.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin, discounted by progress
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    } else {
        // existing bin: mild reward scaled by how tight the fit is
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Small penalty for many open bins to encourage consolidation late in stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the smallest item (1) is impossible,
    // but residuals below a "dead zone" threshold are nearly worthless.
    if post_residual > 0 {
        // Penalize non-zero residuals super-linearly in the low range.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // dead-space penalty
        } else if pr < 20.0 {
            score += (20.0 - pr) * 2.0; // semi-dead zone
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item (exact or comfortable fit).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= n {
            // Bonus scaled by how snugly the next item fits the leftover.
            score -= 10.0 * (1.0 - (pr - n).min(30.0) / 30.0);
        } else {
            // Post-residual cannot host next item: mild penalty, worse if gap is tiny.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 15.0 + pressure * 2.0;
        // But if no open bin fits well, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight reward for using it when many bins are open.
        score -= pressure * 0.5;
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller bins)
    // to keep a spread of useful gaps.
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
