    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default mild penalty; open a new bin only if no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is huge and this item nearly fills the bin, opening fresh is fine.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in stream: prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_n = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    let tight = 1.0 - pr_n;

    // Reward tight fits more strongly as stream progresses (smooth cubic coupling)
    score -= 18.0 * tight * tight * (0.5 + prog_cu);
    // Penalize mid-range dead space with a smooth bump
    score += 10.0 * pr_n * (1.0 - pr_n) * (1.0 + prog_sq);

    // Lookahead coupling: bonus if next item fits the post residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx / cap - pr_n).abs();
        let compat = (1.0 - (fits_next * 4.0).min(1.0)) * (1.0 - pr_n);
        score -= 14.0 * compat * (0.6 + 0.4 * progress);
        // Penalize if next item will need a fresh bin while this bin wastes space
        let wasted = (pr_n - nx / cap).max(0.0);
        score += 8.0 * wasted * wasted * 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, allow late or when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap * open_bins_count as f64);
        score += 6.0 - 8.0 * progress - 2.0 * crowding.min(3.0);
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity-fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Integer division thresholds on post_residual (harmonic classes: 0, 1-9, 10-24, 25-49, 50+)
    let class: f64 = if post_residual == 0 { 0.0 }
        else if post_residual < 10 { 1.0 }
        else if post_residual < 25 { 2.0 }
        else if post_residual < 50 { 3.0 }
        else { 4.0 };
    score += class * class * 2.5;

    // Modulo arithmetic: post_residual in small harmonic classes (divisible by 10, 20, 25)
    if post_residual % 10 == 0 && post_residual > 0 { score -= 6.0; }
    if post_residual % 20 == 0 && post_residual > 0 { score -= 4.0; }
    if post_residual % 25 == 0 && post_residual > 0 { score -= 5.0; }

    // Lookahead coupling: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // harmonic-class match: next item leaves a small class again
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 { score -= 12.0; }
            else if nxt_post < 25 { score -= 5.0; }
            else { score += (nxt_post as f64) * 0.15; }
        } else {
            // next item cannot use this residual: penalize proportional to waste potential
            score += (next_item_size as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize fresh-bin choice unless all fits are terrible.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 18.0 + open_f * 0.5;
        if fitting_bins_count == 0 { score -= 60.0; }
        // if item is large relative to capacity, new bin is fine
        if (item_size as f64) / cap_f > 0.7 { score -= 20.0; }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate fullness).
    let mean_dev = (bin_residual as f64) - mean_residual;
    score -= mean_dev * 0.10;

    // Tight fit reward near exact fill.
    if post_residual <= 5 { score -= 15.0; }

    // Mild stream-progression pressure: as stream advances, avoid leaving mid-size gaps.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += frac * t * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..=9)
    // are unusable gaps -> heavy penalty, but only when they don't perfectly fit.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit is the gold standard.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a residual that exactly matches the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a residual the next item just barely misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: fill fraction of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill * fill;

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // slightly discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; acceptable only if the
        // dead-space penalties above make open bins worse.
        score += 25.0 + 3.0 * pressure + 10.0 * progress;
    } else {
        // Mild reward for using existing bins when many are open.
        score -= 1.5 * pressure;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Small penalty for large leftover gaps relative to capacity (wasted space).
    if post_residual >= 10 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item,
    // penalize when next item cannot fit into the leftover space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if (post_residual as f64) < next {
            score += 25.0; // dead space for the known next item
        }
        if post_residual as u32 == next_item_size {
            score -= 300.0; // chain fit
        }
    }

    // Prefer bins with residuals close to the mean residual (harmonize waste).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize creating small unusable slivers (below the minimum item size 1
    // but hard to fill): anything tiny is dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Early in the stream, allow opening new bins more freely (spread risk);
    // late in the stream, tighten packing by penalizing new-bin openings.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 80.0 - 100.0 * progress; // new bin cheaper to open early
    }

    // Mild pressure against accumulating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 0.8 * fit_ratio * fit_ratio;

    // Penalize waste that is small but unusable: residual below typical small item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize slightly less if post_residual is large anyway.
            score += 1.5 * (next_item_size as f64 - post_residual as f64).ln().max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Time horizon: early in stream, be conservative (penalize fragmenting bins);
    // late in stream, prefer closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 2.0 * fit_ratio;

    // Global state: many open bins with large mean residual -> prefer filling existing bins
    // over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist with room.
        if open_bins_count > 0 {
            score += 4.0 + 0.05 * mean_residual + 0.5 * open_bins_count as f64;
        } else {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward relative to mean residual (better than average is good).
        score -= 0.02 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), softened by progress
    let mut score = norm_pr * norm_pr * cap * (1.0 + 0.5 * progress) + pr * (1.0 - progress);

    // Smooth coupling: residual^3 term grows for large dead space
    score += norm_pr * norm_pr * norm_pr * cap * 0.7;

    // Reward tight fits: small post_residual relative to item size
    let item = item_size as f64;
    let tightness = 1.0 - (pr / item.max(1.0));
    score -= tightness * item * 0.35;

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward scaled by how well it fits
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 25.0 * fit_frac * fit_frac;
    } else if next_item_size > post_residual {
        // penalize leaving residual that cannot host next item
        score += 8.0;
    }

    // Penalize opening new bins (empty-bin candidate) more as stream progresses
    if bin_residual == bin_capacity {
        score += 45.0 + 55.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        // mild reward for using existing bins, scaled by how underutilized they are
        score -= (mean_residual - norm_pr * cap).abs().min(10.0) * 0.2;
        // prefer bins with residual below mean (consolidating waste)
        if pr < mean_residual {
            score -= 6.0 * (1.0 - pr / mean_residual.max(1.0));
        }
    }

    // Late-stream: favor aggressive consolidation
    score -= progress * (1.0 - norm_pr) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize leftovers in "dead zone" classes: residues that few item sizes can use.
    // Harmonic classes via integer division: class = post_residual / 10
    let class = post_residual / 10;
    let class_penalty: f64 = match class {
        0 => -30.0,          // near-perfect fit (0..=9 leftover)
        1 => -12.0,          // 10..19: small items can fill
        2 => -4.0,           // 20..29
        3 => 6.0,            // 30..39: awkward
        4 => 2.0,            // 40..49: medium items fit
        5 => 10.0,           // 50..59: awkward
        6 => 0.0,            // 60..69
        7 => 14.0,           // 70..79: very awkward
        8 => 8.0,            // 80..89
        _ => 20.0,           // 90..100: nearly empty bin, wasteful
    };
    score += class_penalty;

    // Modulo-5 harmonic resonance between post_residual and next_item_size:
    // reward when next item's size class aligns with the leftover class.
    if next_item_size > 0 {
        let nres = post_residual.min(next_item_size);
        let gap = post_residual.saturating_sub(next_item_size);
        if gap <= 10 {
            score -= 25.0; // next item fills this bin almost exactly
        } else if gap <= 20 {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score += (gap % 5) as f64 * 1.5; // misalignment penalty
        } else {
            score += 15.0; // next item cannot reuse this bin at all
        }
        // reward exact divisibility patterns
        if post_residual % 10 == 0 && next_item_size % 10 == 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
        let _ = nres;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless the fit is terrible (large post_residual with bad class).
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * frac;
        // but if all open bins would leave huge dead space, new bin looks good:
        if post_residual > 0 && item_size > 60 {
            score -= 12.0;
        }
    }

    // Prefer bins with residual below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - frac);

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.3 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to hold the next item
    // (or the smallest plausible item) are "unusable" and heavily penalized.
    let min_item = 1.0f64;
    if post > 0.0 && post < next_item_size.max(min_item as u32) as f64 {
        score += 3.0 * (cap - post) + 10.0;
    }
    // Non-linear penalty for tiny residual slivers.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (10.0 - post) / 10.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post / cap);
    score -= 15.0 * tightness * tightness;

    // Perfect fit reward.
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Penalize if post-residual is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.4 * pressure;

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing); penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate calibration: an empty bin has post = cap - item;
    // make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Exact-ish fit: post_residual small relative to capacity is great.
    let pr = post_residual as f64;
    score -= 30.0 * (-pr / 10.0).exp();

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if pr >= n {
            // Next item fits perfectly in the leftover: excellent chaining.
            score -= 45.0 * (-gap / 12.0).exp();
            // Bonus for chains that nearly empty the bin over two steps.
            if pr + item_size as f64 >= bin_capacity as f64 - 1.0 {
                score -= 15.0;
            }
        } else {
            // Leftover too small for next item: penalize dead space growth.
            score += 0.6 * (n - pr);
        }
    }

    // Relative-to-mean adjustment: prefer bins with residual above the mean
    // (consume slack in looser bins first, keep tight bins tight).
    score += 0.25 * (mean_residual - pr);

    // Last-chance bin: strongly reward using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // or lookahead suggests a better use of remaining open bins.
    if bin_residual == bin_capacity {
        let bad_fit = fill_ratio < 0.5 && next_item_size > 0 && (pr as f64) < next_item_size as f64;
        if bad_fit {
            score -= 20.0; // opening a new bin is attractive
        } else {
            score += 35.0 + 5.0 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Slight stream-position modulation: late in the stream, squeeze harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // how well item fills the bin's current space

    let mut score = post;

    // Reward tight fits: the more of the residual the item consumes, the better.
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating awkward dead space: post residual that is too small to be
    // useful for typical future items (i.e., in (0, 10)) is nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much of the leftover the next item uses
            score -= 10.0 * (next_item_size as f64 / post) * (next_item_size as f64 / post);
        } else {
            // next item cannot use this leftover; mild penalty proportional to gap
            score += 3.0 * ((next_item_size as f64 - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer placing here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with large mean residual -> encourage consolidation
    // into existing bins rather than spreading.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual / (open_bins_count as f64 + 1.0);
    }

    // Time horizon: early in the stream, be slightly more willing to open fresh bins
    // (flexibility later); late in the stream, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate handling: brand-new empty bin. Opening a new bin is generally
    // worse than using an existing one, so add a fixed offset, but if the item is very
    // small relative to capacity the offset grows (wasteful), and if no other bin fits
    // well (post residual would be tiny in existing bins) the offset shrinks.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let mut new_bin_score = post + 15.0; // default: prefer existing bins
        // tiny items in a fresh bin waste capacity
        new_bin_score += 20.0 * (1.0 - fill) * (1.0 - fill);
        // but if this is the only fitting option at all, make new bin attractive
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // late in stream, discourage opening bins
        new_bin_score += 10.0 * progress;
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness: reward near-full packing quadratically.
    let tightness = 1.0 - post / cap;
    score -= 25.0 * tightness * tightness;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, small residuals matter more (fewer chances to fill them).
    score += 40.0 * (post / cap) * (1.0 - progress) * (0.5 + 0.5 * progress);

    // Penalize dead space that no plausible future item can fill (sizes 1..100).
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (10.0 - post); // unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 20.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // more so when good alternatives exist and stream is late.
    if bin_residual == bin_capacity {
        let alt = fitting_bins_count as f64;
        score += 30.0 + 8.0 * alt * (1.0 - progress) - 10.0 * progress;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - post).max(0.0).sqrt() * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod arithmetic) ---
    // Residuals that are "nice" (multiples of 10, or small) are more reusable.
    let pr = post_residual as u32;
    let nice = (pr % 10 == 0) as f64;
    score -= 6.0 * nice;

    // Integer-division thresholds: classify leftover into usability bands.
    // Band 0: pr == 0 (perfect fill) -> huge reward.
    // Band 1: pr <= 5 (dead space, likely unusable) -> strong penalty.
    // Band 2: 6..=15 (small but possibly usable) -> mild penalty.
    // Band 3: 16..=40 (workable) -> mild reward.
    // Band 4: > 40 (very roomy) -> neutral-to-slight penalty (wasteful fit).
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score += 18.0;
    } else if pr <= 15 {
        score += 6.0;
    } else if pr <= 40 {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 12.0;
    } else if fill_ratio > 0.6 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chaining
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // Next item won't fit here; leftover becomes dead space for it.
            score += 4.0;
            // If next item is large, prefer bins where it still fits later.
            if next_item_size > bin_capacity / 2 && pr < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when
    // no open bin gives a decent fit; allow early opening when stream is
    // young or all fits are terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut new_bin_penalty = 30.0;
        // If the item fits poorly everywhere (post_residual tiny relative to
        // item), opening fresh is fine: reduce penalty.
        if post_residual <= 5 && fitting_bins_count >= 1 {
            new_bin_penalty -= 10.0;
        }
        // Early in the stream, keep some flexibility to open bins.
        new_bin_penalty *= (0.6 + 0.4 * progress);
        // If open bins are nearly full on average, opening is natural.
        new_bin_penalty *= (0.5 + 0.5 * desperation);
        score += new_bin_penalty;
    }

    // Prefer consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.3;
    }

    // Mean-residual alignment: placing into a bin whose residual is far
    // from the mean leaves fragmented bins; mildly prefer near-mean bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small progress-based tie-break noise via deterministic mixing.
    let phase = ((step_index % 7) as f64) * 0.05;
    score += phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (>=1) can usefully fill
    // are heavily penalized, with a hard cliff at the typical minimum item size.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfect or near-perfect fill: strongly reward.
        if post_residual == 0 {
            score -= 50.0;
        } else {
            score -= 30.0 - (post_residual as f64) * 2.5;
        }
    } else {
        // Non-linear preference for tight fits: quadratic shaping of post_residual.
        let pr = post_residual as f64;
        score += 0.35 * (pr / bin_capacity as f64) * pr * 0.1;
    }

    // Reward bins whose residual exactly matches the item (perfect packing).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if the next item still fits after placement.
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a gap the next item cannot use (future dead space).
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // relative to capacity or there are no open bins.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 35.0 - pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // As the stream progresses, mildly discourage bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing ones.
    score += 0.8 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight; reward filling tight bins further.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, waste tolerance is low; later, prefer tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: exact match with next item is a jackpot ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: bin becomes exactly full after next item.
            score -= 60.0 + 40.0 * (1.0 - progress);
        } else if post_residual >= next_item_size {
            // Next item still fits in this bin: strong bonus, scaled by how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.15;
        } else {
            // Next item cannot fit: residual becomes dead space for the lookahead.
            let gap = (next_item_size - post_residual) as f64;
            // Penalize more when the leftover is small-but-useless (worst dead space).
            score += gap * 0.25 + (1.0 - (post_residual as f64 / bin_capacity as f64)) * 5.0;
        }
    }

    // --- Relative-to-mean coupling: bins far below mean residual are "rich" ---
    // Placing into a bin whose residual is much larger than mean wastes big space.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel > 1.0 {
            // Post-residual above mean: leaving more than average -> mild penalty.
            score += (rel - 1.0) * 8.0;
        } else {
            // Tighter than average: reward.
            score -= (1.0 - rel) * 5.0;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else {
            // Discourage opening a new bin when existing bins fit,
            // unless the item would leave a near-perfect residual (>= 70 empty).
            if post_residual >= 70 {
                score -= 5.0;
            } else {
                score += 12.0;
            }
        }
    }

    // --- Dead-space shaping: residuals too small for the minimum item are worthless ---
    if post_residual < 10 {
        score -= 10.0; // tiny leftover is effectively full: good
    } else if post_residual < 20 {
        // Awkward zone: residual between 10 and 19 is hard to fill.
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 8 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fills bin nearly exactly.
            let gap = post_residual - next_item_size;
            if gap < 8 {
                score -= 10.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit this bin anyway; prefer conserving residual here.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to prefer spreading load onto best-fit candidates.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: penalize opening new bins when open bins have plenty of residual capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 6.0 + 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // existing bins have ample room; avoid new bin
        }
        // Late in stream, opening a new bin wastes capacity; discourage more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    } else {
        // Reward using existing bins, more so as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for bins with large residual when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.03 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, non-linearly (waste grows quadratically).
    let mut score = pr * pr / cap;

    // Stream-progress coupling: early on, prefer tight fits (low residual);
    // later, tolerate residual since bins accumulate anyway.
    let tightness = 1.0 - (pr / cap);
    score -= (1.0 - progress) * tightness * tightness * 20.0;
    score += progress * tightness * 10.0;

    // Lookahead coupling: reward residual that fits the next item,
    // with a smooth polynomial in the match quality.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit = 1.0 - (pr - nx) / cap;
            score -= fit * fit * 15.0;
        } else {
            let miss = (nx - pr) / cap;
            score += miss * miss * 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: if this bin's post-residual deviates far below
    // the mean, it's a good consolidation; penalize creating outliers above mean.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0 - dev * 4.0;

    // Mild penalty for spreading across many bins when residual is large.
    score += (pr / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit classes are gold.
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Perfect fit -> overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes: leftover divisible into useful chunks.
    let r = post_residual % 10;
    if r == 0 {
        score -= 12.0; // multiple of 10: likely reusable by future items
    } else {
        score += r as f64 * 0.8; // penalize ragged remainders
    }

    // Dead-space bands: residual too small for typical items (1..=100 unknown dist,
    // but small items are common) is less harmful than mid-range waste.
    if post_residual > 0 && post_residual <= 3 {
        score += 15.0; // near-dead space
    } else if post_residual >= 45 {
        score -= 6.0; // large residual keeps bin flexible
    }

    // Integer-division threshold: how many "average" items still fit.
    let avg_item = 30.0f64;
    let fits_k = (post_f / avg_item).floor();
    score -= fits_k * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
        } else {
            // next item won't fit here; mildly penalize hoarding space it can't use
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are tight and this is early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / capacity_f;
        // reward new bin when open bins are nearly full, penalize otherwise
        score += 40.0 - tight * 90.0 - progress * 10.0 + open_bins_count as f64 * 1.5;
        // never open a bin for a tiny item
        if item_size <= 20 {
            score += 25.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += (tightness / capacity_f) * 8.0;
        // Prefer fuller bins slightly (best-fit bias beyond post_residual).
        score += (capacity_f - bin_residual as f64) * 0.05;
    }

    // Mean-residual drift: if this bin is far above mean residual, it's a good
    // candidate to drain (reduce fragmentation across many open bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to hold typical future
    // items (assume min plausible item ~ 10% of capacity) are "lost" space.
    let dead_threshold = 0.10 * cap;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 3.0; // unusable sliver => strong penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    let item = item_size as f64;
    score -= 8.0 / (1.0 + post / item.max(1.0));

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item exactly fills this bin's post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // bin stays useful for the lookahead item
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        score += 6.0; // placing here blocks the next item from this bin
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.05 * (open_bins_count as f64);
    }

    // Open-bins pressure: with many open bins, prefer consolidation;
    // with few open bins, a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how poor the current fits are (mean residual vs required space).
    if bin_residual == bin_capacity {
        let fit_quality = if mean_residual > 0.0 { mean_residual } else { 0.0 };
        let poor_fits = (fit_quality - item).max(0.0);
        score = cap as f64 + 20.0 - 0.8 * poor_fits - 0.4 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // matches the next item exactly (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward decays with leftover slack after next item
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * miss;
        }
    } else {
        // last item: just prefer tightest fit
        score -= 5.0;
    }

    // Prefer bins with residuals below the mean residual (tight bins first),
    // penalize dumping items into loose bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.5 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the item fits poorly everywhere:
    // new-bin candidate gets a moderate penalty that shrinks when the
    // post-residual is large (a fresh bin is only good if it stays usable).
    if bin_residual == bin_capacity {
        score += 20.0;
        // reward a fresh bin that can still host the next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight penalty for very small dead space that becomes unusable
    // (post_residual in [1, 9] is likely dead weight for items >= 10... but
    // sizes 1..100 allowed, so weight by how unlikely it is to be filled).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild bonus for tight fits overall
    score -= 0.2 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor minimal post residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead item: penalize unusable remainder.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // New-bin candidate handling: only attractive when all open bins are poor fits
    // (i.e., fitting_bins_count is 0 among open bins or residuals are large).
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // Prefer new bin when existing open bins are mostly empty anyway.
        score = bin_capacity as f64 - 0.3 * open_pressure;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight preference for bins whose residual is below the mean (balancing).
    score += 0.1 * (post_residual as f64 - mean_residual);

    // Small penalty for very large items leaving large residuals elsewhere.
    score += 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on wasted residual, sharpening as the stream progresses.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits: subtract for small post_residual relative to item size.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * (1.0 - progress);
        // If no open bin fits well, allow opening (post_residual == cap - item is good).
        if post < 30.0 {
            score -= 55.0;
        }
    }

    // Lookahead coupling: prefer bins whose post_residual pairs with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 18.0 * (-gap / cap).exp();
    }

    // Mild dispersion pressure: avoid scattering residual far from the mean.
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that belong to
    // "usable" classes (small or exactly matching common item sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows superlinearly for awkward mid-range residuals.
        let frac = pr as f64 / cap;
        if pr < 10 {
            score -= 50.0; // tiny waste is fine
        } else if pr <= 20 {
            score -= 10.0;
        } else if pr <= 30 {
            // 30 is a common small-item size; keep it attractive
            score -= 5.0;
        } else {
            // mid-range dead space: penalize extra
            score += frac * frac * 40.0;
        }

        // Harmonic / modulo classes on post_residual: residuals divisible by
        // common item granularities (10, 20, 25) are more reusable.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 6.0; }
        // Odd, prime-prone residuals are hard to fill.
        if pr % 10 != 0 && pr % 5 != 0 { score += 6.0; }
    }

    // Lookahead: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 120.0;
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
        // If next item also fits, this bin is doubly useful.
        if next_item_size <= pr && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits (already via post_residual).
        score += fitting_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score = cap * 0.9;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // Few open bins -> cheaper to open another.
        score -= (10 - open_bins_count.min(10)) as f64 * 2.0;
        // Large items deserve fresh bins.
        if item_size >= 60 { score -= 25.0; }
        // Lookahead synergy: big item now + big next item -> fresh bin good.
        if next_item_size >= 50 && item_size >= 50 { score -= 30.0; }
    }

    // Mild preference to balance residuals across open bins.
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but typical small items ~10) are
    // heavily penalized. A residual below 10 is essentially dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on small-but-usable residuals that are unlikely to
    // be filled exactly: penalize residuals in (0, 30) softly quadratically.
    if post_residual > 0 && post_residual < 30 {
        score += 0.6 * (30.0 - post_residual as f64) * (30.0 - post_residual as f64) / 30.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but nonzero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // current bin already fits well; encourage using existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item would leave a very awkward residual in every existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild baseline penalty so a new bin is chosen only when clearly better.
        score += 15.0;
        // If lookahead item is large, a fresh bin preserves ordering flexibility.
        if next_item_size > 60 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it's a tight fit already; favor packing it further.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.3 * residual_gap;

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item would fit in post_residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Penalize leftover after chaining; small gaps are dead space.
                score += gap * 0.8;
                // But still prefer bins where next item fits vs not.
                score -= 15.0;
            }
        } else {
            // Next item cannot fit in the residual left behind.
            score += (nxt - post).min(bin_capacity as f64) * 0.25;
        }
    }

    // Relative to mean residual: prefer bins with residual near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer filling many open bins rather than spreading: slight penalty
    // scaled by number of fitting bins (more choices -> prefer best fit only).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for leaving large unusable residue (>50 dead space).
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item (wasted gap).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward gaps that exactly or nearly fit the next item.
            let gap_slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (-gap_slack / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are mostly full
    // (mean residual low) or this bin would otherwise be a terrible fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 15.0 + 30.0 * (1.0 - mean_residual / bin_capacity as f64) + 20.0 * progress;
        score = bin_capacity as f64 - new_bin_bonus;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    // Encourage filling bins above half when stream is late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity && bin_residual < bin_capacity / 2 {
        score -= 8.0 * progress;
    }

    // Small jitter-free tie-break: prefer bins with residual close to item size.
    score += 0.05 * ((bin_residual - item_size).abs() as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = prn.powf(1.5 + 1.5 * progress) * cap;

    // Smooth polynomial coupling with stream progress
    let t = progress;
    score += 8.0 * (t * t - t + 0.25) * prn * cap;

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / br.max(1.0);
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 + t);

    // Penalize dead space that next item likely cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0);
        score += 0.6 * waste * (0.5 + t);
        // Reward leaving space exactly usable by next item
        let gap = (pr - nx).abs();
        score -= 10.0 * (-gap / 15.0) * (1.0 + t);
    } else {
        // Last item: strongly prefer tightest packing
        score += 2.0 * pr;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // New-bin candidate: penalize unless open bins are very fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - cap * 0.5).abs() / cap;
        score += 25.0 - 20.0 * (1.0 - frag) * (1.0 - t);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Harmonic class: classify post_residual by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score -= 20.0; // nearly-full bin: excellent
    } else if frac < 0.30 {
        score += 5.0;
    } else if frac < 0.60 {
        score += 15.0;
    } else {
        score += 30.0; // wasteful large hole
    }

    // Modulo arithmetic on post_residual: dead-space "harmonics".
    // Residuals that are multiples of common small item sizes are reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 12.0; // residual aligns with common item granularities
    }
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver below minimum item size
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 35.0 + (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize if we leave a large awkward hole
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // item barely fits nowhere well / many open bins with large mean residual.
    if bin_residual == bin_capacity {
        // New empty bin: baseline cost = capacity minus item (potential waste).
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        } else if mean_residual > item_size as f64 * 1.5 {
            score += 40.0; // existing bins have room; avoid opening new
        } else {
            score += 15.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference to fill bins with larger residuals when many bins open.
    score += (open_bins_count as f64).ln() * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

