    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Open-bin pressure: penalize adding bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But if this bin is the last chance, avoid opening new bins.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to use it.
        score -= 25.0;
    }

    // Mild preference for bins with below-mean residual (concentrate waste).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Slight late-stream conservatism: reuse bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
