    score -= (cap - post).max(0.0) * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the item (best-fit shaping).
    score += (bin_residual as f64 - item).abs() * 0.3;

    // Global balance: discourage dumping into bins far from the mean residual,
    // which keeps the bin population homogeneous and easier to pack.
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 10.0;

    // New-bin candidate handling: opening a fresh bin is penalized by a threshold
    // that shrinks as the item grows (big items deserve fresh space) and as the
    // stream progresses (fewer chances to consolidate later).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 18.0 + 0.4 * item - 8.0 * progress;
        score += new_bin_penalty.max(2.0);
    }

    // Slight pressure against accumulating too many open bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    let mut score = pr * (1.0 + 0.3 * progress) + 25.0 * poly;

    // Penalize tiny dead space (waste) more aggressively as stream advances
    if pr < item_size as f64 * 0.25 {
        score += (1.0 - progress) * 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Reward last-chance bins strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress + 0.5);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 * (1.0 + progress);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward consolidating into fewer bins
    score -= (open_bins_count as f64).ln() * 2.0;
    score += (mean_residual - pr).abs() * 0.15;

    // New-bin candidate: prefer it only when residuals are tight late in stream
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 20.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 50.0; // avoid abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small denominators) are rewarded.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr % 25 == 0 {
        -14.0
    } else if pr <= 9 {
        12.0 // dead space: too small for the smallest item
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: reward residuals that can host the
    // lookahead item exactly (post_residual == next_item_size) or with
    // harmonic alignment (both divisible by 10).
    if next_item_size > 0 {
        let nx = next_item_size;
        if pr == nx {
            score -= 45.0;
        } else if pr >= nx {
            if pr % 10 == 0 && nx % 10 == 0 {
                score -= 8.0;
            }
            if (pr - nx) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Lookahead cannot fit here: penalize proportionally to how
            // "wasted" the residual is relative to lookahead size.
            score += (nx - pr) as f64 * 0.35;
        }
    }

    // Fraction of capacity filled by this placement: nonlinear reward for
    // tight packing via squared fill fraction.
    let fill = (bin_capacity - post_residual) as f64 / cap_f;
    score -= fill * fill * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; open new bins only when
    // existing residuals are poor (high mean residual) or many bins open.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.25 * mean_residual + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size % 10 == 0 && next_item_size % 10 == 0 {
            score -= 5.0; // harmonic pair fits well in a fresh bin
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..=9)
    // are "dead" and should be heavily penalized, since nothing can ever use them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // smaller dead gap => worse
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits (post_residual small but usable).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight * 4.0).max(0.0);

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; penalize candidates that leave large residuals when
    // open_bins_count is high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * tight * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: default neutral-ish; open a new bin only if existing fits
    // are bad (large post_residual or dead-space prone).
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        // If next item is small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size <= item_size / 2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting space now.
        score += 5.0;
    }

    // Early in stream, keep bins tight; late, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty for large dead space.
    let tightness = post_residual as f64 / cap;
    score += 8.0 * tightness * tightness * cap * 0.1;

    // Reward near-perfect fills strongly.
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // mild bonus proportional to how well next item uses leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * use_ratio;
        } else {
            // next item cannot use leftover: penalize leaving medium dead space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Scarcity of fitting bins: mild reward when few options exist.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins whose residual is below mean residual (consolidate space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more conservative about filling bins
    // unevenly; late in the stream, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (1.0 - tightness);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64 * tightness;

    // New-bin candidate: only attractive when it beats wasting space elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when item is large or stream is late
        let mut new_bin_score = 55.0;
        new_bin_score -= 0.3 * item_size as f64;
        new_bin_score -= 10.0 * t;
        if fitting_bins_count <= 1 {
            new_bin_score -= 40.0; // no real alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score += 5.0; // big items may need fresh space anyway
        }
        score = score.min(score) * 0.0 + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual waste, amplified by stream progress (late waste matters more).
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Non-linear coupling: penalize residuals that are too large to be useful,
    // smooth quadratic in normalized residual.
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post_residual) with a saturating exponential bonus.
    score -= 25.0 * (-pr / 20.0).exp() * (0.5 + 0.5 * progress);

    // If this bin is the last chance, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    // and when many bins are open, unless it would create a very clean residual.
    if bin_residual == bin_capacity {
        let cleanliness = 1.0 - (pr / cap); // = 1.0 for empty bin
        score = 60.0 + 40.0 * progress + 3.0 * open_bins_count as f64 - 30.0 * cleanliness;
    }

    // Lookahead coupling: if next item fits the resulting residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (-slack.abs() * 10.0).exp() * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by how close it was.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * (-gap * 8.0).exp();
    }

    // Mean-residual alignment: prefer bins whose residual tracks the fleet mean.
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction bands.
    let q = (post_residual as f64 / cap) * 4.0; // quarter-classes of remaining space
    let class = q.floor();

    // Reward tight fits: post_residual in lowest class (<=25) is strong packing.
    score -= 12.0 * (1.0 - q).max(0.0);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize residuals that no future item (min size 1, typical small) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Harmonic pairing: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits into post_residual, mildly reward leaving compatible space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // leftover space unusable by lookahead
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // fits are poor (item leaves large residual everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of a fresh bin; reduce when many bins open and residual mean is high (fragmented state).
        let mut nb = 35.0;
        nb -= 10.0 * mean_residual / cap; // if open bins are roomy, prefer them less penalized? keep fresh cost high when roomy
        nb += 5.0 * poor_fit * (1.0 - progress);
        // If item is large (leaves small post_residual), fresh bin is good.
        nb -= (1.0 - post_residual as f64 / cap) * 20.0;
        // If this is the only option (fitting_bins_count==0), must be attractive.
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        score = nb + class * 2.0;
    }

    // Modulo-harmonic nudge: residuals divisible by common item sizes (10/20/25) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Mild preference for filling already-open bins as stream matures.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // A residual < 10 (minimum plausible item) is pure waste; residuals that cannot
    // fit the known next item are penalized more when the next item is large.
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead);
        } else if next_item_size > 0 && post_residual < next_item_size {
            // wasted opportunity for the lookahead item
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += 4.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (new bin adds open_bins_count).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if all existing fits would leave large
    // dead space relative to mean residual, or the next item is huge.
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual - post_residual as f64;
        score += 25.0;
        if next_item_size >= 90 || waste_elsewhere > 45.0 {
            score -= 20.0;
        }
        // early in the stream, opening bins is fine
        score -= 15.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins whose post_residual stays near the mean
    // (keeps future items placeable across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward a post_residual that exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;                 // penalize imperfect match
        score -= 12.0 * (post_residual == next_item_size) as f64; // bonus for perfect pairing
        // If the next item cannot fit anywhere else after this placement, penalize lightly.
        if post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fullness;

    // Penalize bins far from the mean residual (favor homogeneous residual pools).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless placement is very tight.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual <= 5 {
            score -= 20.0; // opening a bin for an almost-perfect fill is great
        }
    }

    // Early in the stream, be more willing to open bins (score new bins lower).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_residual == bin_capacity) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residuals below ~10 are wasted; residuals just above small-item
    // sizes are reusable). Use a U-shaped penalty on post_residual.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let waste = if pr < 10.0 { 40.0 * (10.0 - pr) / 10.0 } else { 0.0 };
        score += waste;
        // Mid-range residual (10..=50) is reusable: mild reward.
        if pr >= 10.0 && pr <= 50.0 {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward if next item exactly consumes remaining space.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Post residual can't host the next item: penalize proportionally
            // to how "orphaned" the leftover space is.
            let gap = (next_item_size - post_residual as u32) as f64;
            score += 0.3 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open new bins early in the stream (more future items
        // to amortize) and when many bins are already open (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        // If current item is large and would leave a bad residual in an
        // existing bin, a fresh bin is more attractive.
        if item_size >= 60 {
            score -= 10.0;
        }
        // If next item is small, a new bin can host both: reward.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: prefer bins whose residual is close to the mean
        // (balanced packing) with a mild coupling.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Global pressure: when many bins are open, discourage marginal fits
    // that create dead space; when few bins are open, be permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual < 10.0 {
        score += 8.0 * pressure;
    }

    // Time-horizon coupling: late in the stream, prioritize closing bins
    // out (filling them fully) over balance.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual < 15.0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with smooth polynomial sharpening
    let x = post / cap;
    let mut score = post * (1.0 + 2.0 * x * x);

    // Smooth coupling: as stream progresses, penalize large residuals more strongly
    score += progress * 30.0 * x * x;

    // Reward tight fits (post_residual near zero) with smooth decay
    let tight = (1.0 - x).powi(3);
    score -= 25.0 * tight;

    // Lookahead: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = (next_item_size as f64 / post).powi(2);
        score -= 20.0 * fit_quality;
    } else if next_item_size > 0 {
        // next item cannot use residual: mild penalty scaled by wasted space
        score += 5.0 * x;
    }

    // Last-chance bonus: only fitting bin -> strong reward to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, less so early in stream
    if bin_residual == bin_capacity {
        let decay = (1.0 - progress).powi(2);
        score += 60.0 - 35.0 * decay;
    }

    // Slight preference for bins with residuals above mean (keep flexible bins flexible)
    score += 3.0 * (post - mean_residual) / cap;

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // --- Tight-fit rewards with harmonic thresholds on post_residual ---
    if post_residual == 0 {
        score -= 60.0 + 20.0 * progress; // perfect closure, increasingly valuable late in the stream
    } else if post_residual <= 3 {
        score -= 30.0 + 10.0 * progress;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // --- Harmonic class logic via integer division on capacity quarters ---
    let quarter = (bin_capacity / 4).max(1);
    let item_class = ((item_size + quarter - 1) / quarter) as f64;
    let residual_class = ((post_residual + quarter - 1) / quarter) as f64;
    if residual_class >= item_class {
        score -= 4.0; // leftover stays within a usable harmonic band relative to the item
    }
    // penalize residuals sitting just above a harmonic boundary (25/50/75): awkward dead zone
    for k in 1..4 {
        let b = k * quarter;
        if post_residual > b && post_residual <= b + 5 {
            score += 3.0;
        }
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if next_item_size > post_residual {
            if post_residual > 0 {
                // leftover is dead space at least until after the next item
                score += 6.0 + post_residual as f64 * 0.4;
            }
        } else {
            // next item chains into this bin: strong reward
            let post2 = post_residual - next_item_size;
            score -= 10.0;
            if post2 == 0 {
                score -= 15.0; // two-item perfect closure
            } else if post2 <= 10 {
                score -= 6.0;
            }
        }
    }

    // --- Last-chance bin: only open bin that fits the item ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 2.0; // prefer consolidating into open bins
        if fitting_bins_count == 0 {
            // nothing anywhere can hold the item: opening a new bin is mandatory
            score -= 100.0;
        }
    }

    // --- Fragmentation pressure: many open bins -> favor existing bins ---
    if !is_new_bin {
        score -= open_bins_count as f64 * 0.5;
    }

    // --- Mean-residual pull: favor placements that end fuller than the average open bin ---
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize unusable "dead" gaps: residuals too small for the smallest plausible item.
    let min_item = 1.0;
    if post_residual > 0 && (post_residual as f64) < min_item * 4.0 {
        score += 50.0;
    }
    // Smooth dead-space penalty: residuals in a "hard to fill" band (small but nonzero)
    if post_residual > 0 && (post_residual as u32) < item_size / 2 {
        score += 20.0 + 0.5 * (post_residual as f64);
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect lookahead fit: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Lookahead fits into the gap left behind
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // gap too small for the known next item: extra dead-space penalty
        score += 12.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New-bin candidate: penalize unless current bins are quite full
        let mean_fill = cap - mean_residual;
        score += 10.0 + pressure * 2.0 - (mean_fill / cap) * 15.0;
        // Opening a new bin is fine if the item would leave a nasty gap elsewhere
        if post_residual > 0 && (post_residual as f64) < 0.2 * cap {
            score -= 18.0;
        }
    }

    // Mild preference for bins whose residual deviates favorably from the mean
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to bin).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: moderate reward proportional to leftover after it.
            let after_next = post_residual - next_item_size;
            score -= 10.0 + 20.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Dead space: post_residual can't hold the next item.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 8.0 * waste;
        }

        // Chain fit: next item also fits current residual tightly (pairing).
        if bin_residual >= item_size + next_item_size {
            score -= 6.0;
        }
    }

    // Penalize residuals far below the mean (fragmented bins).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    if dev < 0.0 {
        score -= 15.0 * dev; // below mean residual = tighter = good
    } else {
        score += 5.0 * dev;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only if this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Neutral base; lookahead already governs. Slight penalty when many bins open.
        score += 2.0 * open_bins_count as f64;
        // Favor new bin when item is large relative to mean residual (poor fits elsewhere likely).
        score -= (item_size as f64 - mean_residual).max(0.0) * 0.3;
    }

    // Late-stream consolidation: as stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: strongly reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, 1 = perfect fit
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    // Small residuals (< smallest plausible item ~10) are dead; large residuals are useful.
    if post_residual < 10 {
        score += 60.0;
    } else {
        // Reward leaving residuals that common item sizes can still fill.
        let useful = (post_residual as f64 / bin_capacity as f64).sqrt();
        score -= 20.0 * useful;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how much of post_residual next item consumes
            let consume = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * consume;
        } else {
            // next item cannot follow here; mild penalty scaled by overflow amount
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when current
    // bins are crowded (mean residual small) or fit is terrible.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin = its full residual (100) minus adjustments
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // late in stream, prefer consolidating into open bins
        score -= 10.0 * (1.0 - progress);
        // if many open bins have slack, opening new bin is wasteful
        score += 0.4 * mean_residual;
        // if few bins fit the item, opening a new one is reasonable
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: slight bonus for keeping bin count low when many bins are open.
        score -= 0.15 * open_bins_count as f64;
    }

    // Time-horizon modulation: early on, be picky (penalize mediocre fits);
    // late in stream, accept decent fits to avoid opening extra bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * (1.0 - progress) * (1.0 - fit_ratio); // early pickiness
    score -= 8.0 * progress * fit_ratio;                  // late acceptance

    // Discourage leaving residuals in the awkward 10..25 band that rarely fill well
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let size_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = pr_norm * pr_norm * cap;

    // Smooth coupling: residual waste interacts with stream progress
    score += 8.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_norm > 0.0 {
        let fits_next = ((pr_norm - next_norm).max(0.0)) * (1.0 - progress);
        score += 5.0 * fits_next;
        // bonus if next item fits perfectly-ish
        let gap = (pr_norm - next_norm).abs();
        score -= 4.0 * (1.0 - gap) * (1.0 - pr_norm) * progress;
    }

    // Penalize last-chance bins less (must use them)
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        // Slight penalty when many bins fit: prefer scarcity
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening new bins mildly, more when many open
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
        // but if no open bin fits well, new bin becomes attractive
        score -= 15.0 * pr_norm;
    }

    // Mean residual context: avoid bins far from mean (fragmentation)
    score += 1.5 * (pr - mean_residual).abs() / cap;

    // Fill-rate reward scaled by progress
    score -= 3.0 * size_norm * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no plausible item (1..100)
    // can use well is penalized. Residues 1..9 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Integer-division threshold: post_residual in the "large but awkward" band
    // (50..90) is a poor outcome for future items; add mild penalty.
    if post_residual >= 50 && post_residual < bin_capacity {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual
    // class (post_residual >= next_item_size), reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size.min(30)) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for stranding capacity.
        score += 4.0;
    }

    // Modulo-10 class bonus: residues that are multiples of 10 align with
    // common item sizes and tend to be reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // New-bin candidate: bin_residual == bin_capacity. Prefer it only when
    // existing fits are poor (large post_residual). Score sits in ~[55, 100].
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.5 * item_size as f64
            + 0.1 * open_bins_count as f64
            - 0.05 * (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        // gaps too small for the smallest plausible item are dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
        // reward tight fits (small post_residual relative to residual)
        let tightness = post_residual as f64 / bin_residual.max(1) as f64;
        score -= (1.0 - tightness) * 15.0;
    } else {
        // perfect fill
        score -= 50.0;
    }

    // Penalize creating gaps that the lookahead item cannot use
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            score += 12.0; // gap unusable for next item
        } else {
            score -= 6.0; // gap could host next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: placing into a bin far from mean residual
    // is either very good (consolidating) or wasteful; favor consolidation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: prefer keeping items in open bins unless the fit
    // is terrible; make empty bin mildly unattractive.
    if bin_residual == bin_capacity {
        score += 30.0 + post_residual as f64 * 0.5;
    }

    // Slight preference for filling bins earlier in the stream (bin consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward perfect chaining with the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remnant: penalize wasted space
            score += 0.35 * post_residual as f64;
        }
    } else {
        // last item: only exact fills matter
        if post_residual == 0 { score -= 50.0; }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: avoid wasting the only fitting bin on a poor fit
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early stream: be more tolerant of new bins to build a diverse pool
    score -= 6.0 * (1.0 - progress);

    // New empty bin candidate: attractive only when placement leaves big waste
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = (post_residual as f64) / cap;
    score += tightness * 30.0;

    // Reward using residual that would otherwise be dead space.
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    score -= fill_ratio * 40.0;

    // Penalize leaving a residual that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) / (post_residual as f64) * 10.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in stream, be more conservative about fragmenting bins.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += (1.0 - progress) * tightness * 10.0;

    // Many open bins with high mean residual: prefer consolidating into bins
    // below mean residual (larger holes) to balance loads.
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive when the item fills it
    // near-perfectly; otherwise heavily penalized so existing bins are used.
    if bin_residual == bin_capacity {
        let waste = cap - (item_size as f64);
        score = waste * 2.0 + 20.0;
        if item_size == bin_capacity {
            score = -100.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, opening a fresh bin is cheaper than fragmenting.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + progress) - 0.5 * pr_norm * progress;

    // Reward tight fits (small post_residual), scaled smoothly by progress
    let tightness = -(1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 2.0 * progress);

    // Penalize dead space that cannot fit the next item
    let next_penalty = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 { 0.5 * (-gap / cap) * (1.0 + progress) } else { -0.3 * (gap / cap) * (1.0 - progress) }
    } else { 0.0 };

    // Last-chance bonus: strongly favor the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -3.0 * (1.0 + progress) } else { 0.0 };

    // Mild penalty for spreading across many bins late in stream
    let spread = (open_bins_count as f64).ln().max(0.0) * 0.1 * progress;

    let mut score = pr + poly * cap * 0.2 + tightness * cap * 0.5 + next_penalty + last_chance + spread;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes of dead space
    score += match class {
        0 => -60.0,                       // near-perfect fit: strongly reward
        1 => -30.0,                       // good
        2 => -10.0,
        3 => 5.0,
        4 => 15.0,
        5 => 25.0,
        6 => 40.0,
        _ => 60.0,                        // huge dead space: penalize
    };

    // Integer-division thresholds on post_residual: can it host common small items?
    if post_residual >= 10 { score -= 8.0; }
    if post_residual >= 25 { score -= 8.0; }
    if post_residual >= 50 { score -= 8.0; }

    // Lookahead: does post_residual also fit the next item (chained fit)?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if post_residual - next_item lands in a good class again
        let post2 = post_residual - next_item_size;
        if post2 < 10 { score -= 10.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // this bin can't serve the next item anyway
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline slightly above good fits,
    // but attractive when all open bins would create huge dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.0; // new bin trivially fits everything; keep baseline
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Mild penalty when this bin's residual deviates far from the mean residual
    // (keeps bin residuals balanced, harmonic homogeneity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold a
    // typical future item (1..100 unknown distribution) are toxic.
    let dead_zone = 40.0;
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < dead_zone {
            // unusable sliver: quadratic blow-up as it shrinks
            score += (dead_zone - pr) * (dead_zone - pr) * 0.35;
        } else {
            // larger residuals are genuinely reusable: reward them
            score -= (pr - dead_zone) * 0.25;
        }
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as f64) >= nx * 0.8 {
            score += 8.0; // next item likely strands this residual
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(25.0);
    } else {
        // New-bin candidate: only attractive when existing bins fit badly.
        // Base cost of opening a bin, discounted by mean residual waste.
        score += 20.0 + mean_residual * 0.3 - 10.0 * progress;
    }

    // Mild preference for bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + post_residual as f64 * 0.3;
        } else {
            // dead space penalty scaled by how far the next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.5;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + mean_residual * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin is good for chaining
        }
    }

    // Small bonus for tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early stream: prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && !is_new_bin {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual shrinks to near zero.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 2.5 * tight * tight * cap;

    // Penalize dead space that can't fit typical future items: residual too small
    // to be useful but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 8.0 * (1.0 - ((post_residual as f64 - nx) / cap));
        } else if post_residual as f64 > 0.0 {
            // next item won't fit here; slight penalty proportional to wasted residual
            score += 0.3 * post_residual as f64 / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.5 * tight * cap;
    }

    // New-bin candidate handling: neutral baseline, penalized when decent fits exist,
    // rewarded when the item fits poorly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score = cap * (1.0 - tight); // = cap, baseline
        if fitting_bins_count == 0 {
            score -= cap; // must open new bin
        } else {
            // penalize opening new bin when existing fits are decent
            score += 4.0 + 0.4 * (fitting_bins_count as f64);
            // but if item is large and fits would leave bad residuals, allow new bin
            let best_possible = item_size as f64 / cap;
            if best_possible > 0.8 && fitting_bins_count <= 2 {
                score -= 6.0;
            }
        }
    }

    // Global state coupling: with many open bins, prefer consolidation
    // (bins with residual below mean are better consolidation targets).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * (0.5 + t);
        // more open bins -> stronger pressure to fill existing bins tightly
        score -= 0.15 * (open_bins_count as f64).ln().max(0.0) * tight * cap;
    }

    // Late stream: waste less, pack tighter.
    score -= 2.0 * t * tight * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.4 * t * t;
    let mut score = pr * poly;

    // Reward tight fits (non-linear)
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize residual far from useful small-item sizes, smooth in progress
    let dead = (pr - 10.0).max(0.0) as f64;
    score += 0.05 * dead * dead * (0.5 + t);

    // Lookahead: reward leaving room for next item (smooth)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).max(0.0);
        score -= 8.0 * (1.0 - (d / cap).min(1.0));
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize early, allow late when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) + 20.0 * fit_ratio * (1.0 - t);
    }

    // Mean residual alignment penalty
    score += 0.1 * (pr - mean_residual).abs();

    // Mild bin-count pressure
    score += 0.3 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: bins whose residual belongs to
        // "useful" small classes (0..=10) are near-perfect fills.
        let class = post_residual % 25; // harmonic class on capacity quarters
        score -= match class {
            0 => 40.0,           // exactly a quarter/half/three-quarter fill left
            1..=5 => 25.0,       // tiny dead space, very usable
            6..=15 => 12.0,      // moderate residual
            _ => 0.0,
        };
        // Integer-division threshold: residual that cannot hold the smallest
        // item (size 1..10 typical) is dead space — penalize strongly.
        if post_residual < 10 {
            score += 30.0; // unusable sliver
        }
        // Fractional tightness: how much of the bin the item consumes.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill_frac;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is ideal (sets up a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item still fits: good, but not perfect
            score -= 20.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here afterwards: slight penalty scaled
            // by how far off we are
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.1 * gap;
        }
        // Harmonic modulo coupling between next item and post residual
        if post_residual > 0 && (next_item_size % post_residual.max(1)) == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate penalty: opening a new bin should only win when the
    // item is large (poor fit anywhere) or no tight option exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // base cost of a fresh bin, discounted for large items
        score += 90.0 - 70.0 * frac;
        // if many bins fit the item, opening a new one is wasteful
        score += 8.0 * fitting_bins_count as f64;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild pressure to keep the fleet of open bins coherent: prefer bins
    // whose residual is close to the mean residual (balanced packing).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer bins with smaller residual overall (best-fit bias), stronger
    // when many bins compete.
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }
    // Penalize small-but-usable gaps that are unlikely to absorb the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward exact-ish fit with the lookahead item.
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Tight-fit reward: low post_residual relative to capacity is good.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open bins pressure: discourage spreading across many bins.
    if bin_residual != bin_capacity {
        score -= 2.0;
    } else {
        // New-bin candidate: penalize opening a new bin, more so with many open bins.
        score += 6.0 + open_bins_count as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild reward when bin residual is far below mean residual (bin is nearly full).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Late-stream tightening: as stream progresses, penalize waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward when next item can fit into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // exact match of next item into leftover space is ideal
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // penalize leftover space that cannot host the next item
        score += 15.0;
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 10.0;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // opening a new bin is only acceptable if all fits are loose
            let best_possible = (post_residual as f64).min(mean_residual);
            score += 5.0 * (1.0 - best_possible / (bin_capacity as f64));
        }
    }

    // Early stream: be slightly more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize residuals that strand the next item.
        score += 6.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize dumping into bins with large residuals relative to the mean
    // (preserve "big-hole" bins for larger future items).
    if (bin_residual as f64) > mean_residual * 1.4 {
        score += 4.0;
    }

    // Early in the stream, be more willing to open/use fresh bins flexibly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if post-residual is large
        // (item leaves a useful hole) or few bins are open.
        score = post_residual as f64 * 0.9
            + 20.0 * (1.0 - progress)
            - (open_bins_count as f64).ln().max(0.0) * 3.0;
        if post_residual < 20 {
            score += 25.0; // opening a bin for a near-full item is wasteful
        }
    }

    // Late in the stream, tighten everything to close out bins.
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) coupling
    let mut score = pr + 0.015 * pr * pr / cap;

    // Stream progress amplifies waste penalty later in the stream
    score += (0.5 + 1.5 * progress) * (pr / cap).powi(3) * 20.0;

    // Coupling with mean residual: bins far from mean residual are slightly deprioritized
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (smooth bonus)
    if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        if slack >= 0.0 {
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            score += 2.0 * (-slack / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score = cap as f64 * 1.2 - 30.0 * progress - 10.0 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong discount.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Harmonic class of the leftover space: leftovers in "small" classes
        // (1..=10) are near-perfect, larger leftovers are dead space.
        let pr = post_residual;
        if pr <= 10 {
            score -= 40.0;
        } else if pr <= 20 {
            score -= 18.0;
        } else if pr <= 30 {
            score -= 6.0;
        }

        // Modulo-10 harmonic class: leftover divisible by 10 is more reusable
        // against integer item sizes.
        if pr % 10 == 0 {
            score -= 4.0;
        }

        // Penalize dead space that no future item (1..=100) can pair with well:
        // leftovers slightly above common small sizes are wasted.
        if pr > 50 {
            score += (pr - 50) as f64 * 0.3;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement; if it nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would have fit here but won't after this placement
            score += 5.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming fresh capacity.
        score += 15.0;
        // More acceptable early in the stream or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 12.0; // open bins are too full anyway
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Mild preference for bins that are already well utilized.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
        // Slight penalty for spreading across too many bins.
        score += open_bins_count as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // dead space penalty, strongest for tiny gaps
    }

    // Reward tight fits (post_residual near zero but not wasteful).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        // usable gap that next item might fill
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    }

    // Perfect-fit lookahead: if next item exactly matches post_residual, strong reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin when open bins can fit, scaled by fit quality.
            let best_possible = (bin_capacity as f64 - item_size as f64).abs();
            score += 35.0 + best_possible * 0.1 + (open_bins_count as f64) * 2.0;
        } else {
            // No open bin fits: opening a new bin is required, make it attractive.
            score -= 20.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.5 {
            score += 15.0 * (1.0 - fill_ratio);
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Mild preference for filling fuller bins (larger item relative to residual).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically (dead space).
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: if the next item fits into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.15 * slack; // perfect chaining bonus, decaying with slack
        } else {
            // Next item won't chain: penalize proportionally to wasted pairing potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss.min(50.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when the current item fits well somewhere.
        if post_residual == 0 {
            score -= 10.0; // perfect new bin usage
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
        // More attractive late in the stream if open bins are nearly full on average.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to mean (balanced usage),
        // slight preference for fuller bins.
        score -= 0.05 * (bin_residual as f64 - mean_residual).abs().recip().min(5.0);
    }

    // Mild global pressure: as stream progresses, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual quadratically.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        let waste = (next_item_size.min(post_residual)) as f64;
        score += 8.0 * (1.0 - waste / post_residual.max(1) as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the mean residual (balance load),
    // but only when there are multiple open bins.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * dev;
    }

    // Early in the stream, be more willing to open new bins (exploration);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early, penalized late.
        let new_bin_cost = 55.0 + 60.0 * progress;
        // Opening a new bin is attractive if existing fits are poor (large post_residual).
        score = new_bin_cost + 0.3 * post_residual as f64;
        // If no open bin fits well and item is large, opening is better.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Late stream: penalize leaving large residuals in open bins.
        score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = post * (1.0 + 0.5 * pr * pr);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, dead space matters more; early on, be more lenient
    score += 8.0 * progress * pr * pr * cap * 0.1;

    // Reward bins whose leftover could host the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr * cap - nx;
        if diff >= 0.0 {
            score -= 4.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 2.0 * (diff / cap).powi(2) * cap * 0.05;
        }
    }

    // Penalize wasting a nearly-full bin's uniqueness vs spreading across bins
    let fit = fitting_bins_count as f64;
    if fit > 0.0 {
        score += 6.0 / fit - 6.0 / (fit + 1.0);
    }

    // Mild penalty when this bin is far below mean residual (fragmentation tendency)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for fewer open bins early, more freedom late
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "usable" residue
    // classes (multiples of 10, or large enough for common items) are preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        let class = pr % 10;
        // Dead space penalty grows for awkward residues (1..=4 hard to fill)
        if class >= 1 && class <= 4 {
            score += (5 - class) as f64 * 2.0;
        } else if class == 0 {
            score -= 4.0; // round leftover is reusable
        }
        // Large leftovers are inherently fine; small ones are wasteful
        if pr < 10 {
            score += 15.0; // dead space below min item size
        } else if pr < 20 {
            score += 6.0;
        } else if pr < 35 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: reward leftovers that exactly fit the next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr >= next_item_size && pr - next_item_size < 10 {
            score -= 10.0; // leaves near-perfect chain fit
        } else if pr < next_item_size && pr >= 10 {
            score += 3.0; // next item can't go here anyway; mild penalty
        }
        // Harmonic threshold classes on next item size
        let nc = if next_item_size <= 25 { 0 } else if next_item_size <= 50 { 1 } else { 2 };
        match nc {
            0 => { if pr >= 25 { score -= 3.0; } }
            1 => { if pr >= next_item_size { score -= 5.0; } }
            _ => { if pr >= next_item_size { score -= 8.0; } } // big next item: keep roomy bins
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins when many are open (reduce bin count pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Slight pull toward bins below mean residual (balance / close small bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever host
    // typical items (1..=10) are wasted forever -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward placements that leave a gap large enough to be reusable
    // (>= next item or >= a comfortable threshold).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if post_residual >= 30 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would create severe dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: mild reward for reusing bins to keep count low.
    score -= 0.8 * open_bins_count as f64;

    // Slightly prefer bins whose residual is close to the mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Late in the stream, tighten packing: penalize loose fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.4 * progress;

    // New-bin candidate: only attractive when the item is large and would
    // leave a well-usable residual, or when no open bin fits well.
    if bin_residual == bin_capacity {
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: keep it moderately attractive only when
    // no open bin offers a good fit; otherwise penalize slightly.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // discourage opening a new bin when an existing bin fits well
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post_residual (perfect chain), penalize when next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect 2-step completion
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item still fits: reward proportionally to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * tight;
        } else {
            // next item won't fit in this bin: penalize dead space
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    // Reward tight fits of the current item (small post_residual).
    score -= 15.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are more
    // "committed"; prefer filling them to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (open_bins_count as f64 / (open_bins_count + 5.0) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual small relative to item).
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the stream is early (amortization favors filling bins over time).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
        if tightness > 0.85 {
            score -= 10.0; // allow new bin only when fit here is bad anyway
        }
    }

    // Prefer bins with residuals close to the mean (keeps bin profile balanced).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, larger dead space is penalized more (wasted capacity matters more)
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= 0.5 + 0.5 * progress_coupling;

    // Polynomial interaction between post-residual and mean residual across open bins
    let norm_mean = mean_residual / cap;
    let interaction = norm_pr * norm_mean * (norm_pr - norm_mean);
    score += 30.0 * interaction;

    // Reward tight fits: subtract smooth function of (residual - item)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score -= 25.0 * (1.0 - tightness) * (1.0 - tightness) * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits exactly into post-residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_frac = 1.0 - (diff / cap).min(1.0);
        score -= 20.0 * fit_frac * fit_frac * fit_frac;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 2.0 * open_bins_count as f64 * progress * progress;

    // Slight preference for opening a new bin early when residuals are small
    let new_bin_bias = if bin_residual == bin_capacity {
        -10.0 * (1.0 - progress) * (1.0 - norm_mean)
    } else {
        0.0
    };
    score += new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "coarse" dead space
    let post = post_residual as i64;
    let harmonic_class = post % 10;
    // Reward post-residuals that are multiples of 10 (likely to accept future items)
    if harmonic_class == 0 && post > 0 {
        score -= 12.0;
    } else if harmonic_class <= 3 && post > 0 {
        score -= 4.0;
    } else if harmonic_class >= 7 && post > 0 {
        score += 6.0; // awkward slivers
    }

    // Integer-division threshold: how many average items still fit
    let fits_count = post / item_size.max(1);
    score -= (fits_count.min(4) as f64) * 3.0;

    // Next-item lookahead: reward bins whose post_residual accommodates next item exactly/near-exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect pair
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 10.0 / (1.0 + gap as f64 / 10.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins are fragmented or item is huge
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // big items prefer fresh bins; small items prefer filling existing ones
        let size_pull = (item_size as f64 - 50.0) / 50.0;
        score += 40.0 - 25.0 * fragmentation - 20.0 * size_pull - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter fits generally (small post_residual relative to capacity)
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight preference for bins with below-mean residual (consolidation)
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for the smallest plausible item are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize residuals too small to hold the lookahead item (forces future new bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.1;

    // Mild new-bin bias: opening a new bin is only attractive when the current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late-stream conservatism: keep bins tight as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item can still land here: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Unusable dead space for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit flavor), penalize very loose bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.4 * (mean_residual - residual_f);
    } else {
        score += 0.2 * (residual_f - mean_residual);
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is huge
    // relative to the residual space dynamics. Penalize scaled by stream progress,
    // slightly relaxing early when opening fresh bins is cheap.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 20.0 * progress;
        // If the item is large, a fresh bin is more acceptable.
        score -= 0.15 * item_size as f64;
    }

    // Mild penalty for leaving tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead chaining: reward if the next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize leaving a gap slightly smaller than the next item (dead space trap).
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.05 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless the item fits terribly everywhere.
    if bin_residual == bin_capacity {
        let avg_waste = (bin_capacity as f64 - mean_residual).max(0.0);
        let pressure = 1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 25.0 * pressure * (0.5 + 0.5 * progress) - 0.1 * avg_waste;
        if item_size > 70 {
            score -= 20.0; // big items prefer fresh bins
        }
    }

    // Mild preference for bins below mean residual (keep balanced residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let t = progress;
    let poly = pr * pr * (0.5 + t) - pr * (1.0 + 2.0 * t) + t * t * 10.0;
    score += 0.01 * poly;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual.
    let dead = (pr - mean_residual).abs();
    score += 0.05 * dead * (1.0 + t);

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * t);
    }

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 * (1.0 - t);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - t);
    }

    // Mild penalty on opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes capture "nice" leftover slots
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_bonus = match class {
        0 => 12.0,                       // perfectly aligned leftover
        1..=3 => 4.0,                    // near-aligned
        4..=7 => -3.0,                   // awkward mid-range dead space
        _ => 1.0,
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: small unusable slivers are bad
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Dead space band 10..=20 is semi-usable (fits small items 10..20)
    if pr >= 10 && pr <= 20 {
        score -= 6.0;
    }

    // Next item lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger the tighter the chain
            let tightness = 1.0 - (pr as f64 - next_item_size as f64) / cap;
            score -= 8.0 + 10.0 * tightness;
            // modulo coupling: next item lands on a harmonic boundary
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot follow here -> this residual likely becomes waste
            score += 6.0 + (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // last item: just fill as much as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    if fitting_bins_count == 1 && bin_residual == bin_capacity {
        score += 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless the fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // waste of a fresh bin is proportional to how much current item leaves behind
        let fit_ratio = item_size as f64 / cap;
        score += 20.0 - 25.0 * fit_ratio;
        // opening bins early in the stream is cheaper (amortization)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // penalize proliferation when many bins are already open
        score += open_bins_count as f64 * 0.5;
    } else {
        // reward tightening relative to the mean residual of open bins
        score -= (mean_residual - post_residual as f64).clamp(-cap, cap) * 0.1;
    }

    // Tight fits are gold: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 15.0 / (1.0 + tightness * tightness);

    // Harmonic capacity-fraction classes of item_size (quarter/eighth alignment)
    let frac = (item_size as f64 / cap) * 8.0;
    if (frac - frac.round()).abs() < 1e-6 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min item size 1, but small gaps < ~15 are hard
    // to fill) are heavily penalized.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 20.0;

    // Open-bin pressure: penalize using bins when many bins are already open,
    // encouraging consolidation into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item: penalize.
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no good
    // fit exists. Make the empty bin moderately expensive so it's chosen
    // only when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if many bins are open and mean residual is fragmented,
        // a fresh bin becomes relatively more attractive.
        score -= mean_residual * 0.1;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    // Stream progression: late in the stream, be slightly more conservative
    // about opening new bins (fewer chances to consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect two-item match: bin closes exactly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits exactly into the residual after placement (tight chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space relative to mean residual.
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Penalize tiny unusable post-residuals (dead space) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Compare against mean residual: prefer filling bins that are already low.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && next_item_size > post_residual && post_residual > 0;
        if poor_fit || fitting_bins_count == 0 {
            score -= 30.0; // open a fresh bin rather than fragmenting
        } else {
            score += 25.0; // discourage opening bins when good fits exist
        }
    }

    // Slight early-stream preference for tight packing to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize creating small, hard-to-use dead space (< 10 is unusable for min item size 1... use relative threshold).
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Penalize blocking the next item into this bin.
            score += 6.0;
        }
        // If next item is large, prefer leaving roomy bins.
        if next_item_size >= 50 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual.saturating_sub(item_size) as f64) <= mean_residual * 0.6;
        if good_fit_exists {
            score += 45.0; // discourage opening new bin when decent fit exists
        } else {
            score -= 15.0 + 10.0 * (1.0 - progress);
        }
        // Many open bins: discourage proliferation.
        score += open_bins_count as f64 * 2.0;
    }

    // Mild preference for bins below mean residual (consolidate space).
    if !is_new_bin {
        score += 0.05 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // penalize large dead space more aggressively as stream progresses
    score += 18.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // reward tight fits (small post residual) especially early
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // prefer bins already below mean residual (consolidation)
    score += 3.0 * (pr - mean_residual) / cap;

    // mild penalty for opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets create integer
    // division thresholds. Small post_residual = tight fit = good.
    let r = post_residual;
    let class = r / 10; // 0..=10 harmonic class
    score += class as f64 * 1.5;

    // Dead-space penalty: residual that no plausible item (>=1) can use well.
    if r > 0 && r < 10 {
        score += 25.0; // tiny sliver is dead space
    }

    // Reward near-perfect fills.
    if r == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            // Harmonic class of the two-step residual
            score -= 8.0 + (nxt_post as f64).recip() * 4.0;
            if nxt_post == 0 {
                score -= 30.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so
    // we only open when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0;
        // open a fresh bin early when mean residual is already large
        score -= (mean_residual / bin_capacity as f64) * 5.0;
        // avoid opening when many bins already fit the item
        score += fitting_bins_count as f64 * 4.0;
    }

    // Progress modulation: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Fraction-of-capacity coupling on the filled fraction.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 5.0;

    // Mean-residual harmonics: penalize bins far from the mean (outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64);
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Dead-space penalty: gaps too small for the minimum item size are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Gaps below a practical threshold (small unusable slivers) are penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: mild reward for consolidating into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0; // open fresh bin when open bins are tight
        } else {
            score += 25.0; // discourage wasting a fresh bin
        }
    }

    // Slight preference for filling bins with less mean residual (denser bins first).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item: huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits comfortably: moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize small unusable gaps.
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize the brand-new empty bin candidate unless it gives a perfect next-fit.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if perfect {
            score -= 500.0;
        } else {
            score += 40.0;
        }
    }

    // Late in the stream, closing gaps matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Base cost of opening a new bin: high, but decays if we're late in the
        // stream (leftover residual matters less) or if many bins are already open.
        let mut open_cost = 60.0 - 30.0 * progress + 2.0 * open_bins_count as f64;

        // If this bin is the only one that fits, opening a bin is unavoidable-ish,
        // but the score call for it still needs to compete: soften the penalty.
        if fitting_bins_count <= 1 {
            open_cost -= 40.0;
        }

        // If the item leaves a residual that can hold the (known) next item,
        // an existing bin would be more valuable; if not, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            open_cost += 15.0;
        }

        // Late in the stream, dead space in a fresh bin is cheap.
        score += open_cost.max(0.0);
        return score;
    }

    // Existing-bin logic: reward tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize leaving dead space that nothing can use: residual too small
    // relative to the minimum plausible item size.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // strongly (chained packing); if next item is blocked by this placement,
    // penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global state coupling: if mean residual across open bins is high,
    // prefer consolidating into bins (tight fits) rather than spreading.
    if mean_residual > 30.0 {
        score += 0.15 * (mean_residual - 30.0);
    }

    // Mild preference late in stream for very tight fits (minimize wasted space
    // in bins that may never be reused).
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: minimize post residual, with polynomial stream coupling.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via a smooth bell on fill ratio.
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize tiny dead space that is unusable: smooth quadratic in pr near small values.
    let dead = (1.0 - pr / 20.0).max(0.0);
    score -= 25.0 * dead * dead;

    // Smooth coupling: if next item fits exactly into post_residual, reward strongly (quartic window).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let closeness = (1.0 - (diff / cap).abs()).max(0.0);
        score -= 20.0 * closeness * closeness * closeness * closeness;
        // Penalize if next item cannot fit (bin becomes dead end), scaled by progress.
        if nx > pr {
            score += 10.0 * progress * (nx - pr) / cap;
        }
    }

    // Last-chance bin: smooth bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize mildly early, more later unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - it / cap;
        score += 12.0 * (1.0 - progress) + 20.0 * progress * (1.0 - poor_fit);
    }

    // Diversity term: avoid over-concentrating on high-mean-residual bins.
    score += 0.05 * (mean_residual - pr) * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that commonly pair with item sizes
    // (multiples of 10, and small residues) are penalized as dead space.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 6.0; // perfectly aligned leftover, reusable by aligned items
    } else if class <= 2 {
        score += 4.0; // sliver dead space
    }

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // partial credit scaled by how well it fills the leftover
            let fill = (next_item_size as f64) / (pr as f64);
            score -= 15.0 * fill;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr as f64) * 0.15;
            // harmonic mismatch: next_item class vs pr class
            if next_item_size % 10 == pr % 10 && pr >= 10 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is large
    // relative to capacity or current bins are fragmented.
    if bin_residual == bin_capacity {
        let frac = (item_size as f64) / (bin_capacity as f64);
        let mut nb = 25.0 - 30.0 * frac; // large items want fresh bins
        // penalize opening when many bins already exist with mean residual >= item
        if (mean_residual >= item_size as f64) && open_bins_count > 2 {
            nb += 15.0;
        }
        // early stream: slightly prefer consolidation into existing bins
        let prog = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * (1.0 - prog);
        score += nb;
    }

    // Prefer filling bins that are already mostly full (low residual) overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Fragmentation guard: mean residual far above this bin's post residual
    // suggests this bin is a good consolidator.
    if (mean_residual - pr as f64) > 10.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but treat dead space non-linearly.
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward exact match or containment of next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual as f64 - nxt) / (bin_capacity as f64));
        } else {
            // next item won't fit: penalize proportionally to wasted lookahead
            score += 10.0 + 0.4 * (nxt - post_residual as f64);
        }
        // Bonus if next item also nearly fills after chaining
        if post_residual >= next_item_size {
            let chained = post_residual as f64 - nxt;
            score -= 15.0 * (1.0 - chained / (bin_capacity as f64));
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitter.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (more filled), but only if the fit is decent.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.7 {
        score -= 12.0 * fit_ratio;
    }
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut newbin = 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            newbin -= 100.0; // forced
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // opening a fresh bin keeps a perfect slot for the lookahead? no—open bin would too
            newbin += 10.0;
        }
        if item_size >= 70 && fitting_bins_count > 0 {
            newbin += 15.0; // big item into fresh bin is fine
        }
        score += newbin;
    }

    // Slight preference for fewer open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize very small dead space that is hard to reuse (0 < post < ~15)
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 - post_residual as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mild penalty unless bin is nearly full anyway
            score += 5.0;
        }
    }

    // Prefer filling bins that are already more loaded (best-fit flavor)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // Time horizon: early in stream, be more willing to open new bins (penalize existing bins less);
    // late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 15.0 + 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Many open bins: encourage closing them out (favor bins with small residual)
    score += mean_residual * 0.1;
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = r;

    // Smooth non-linear coupling of post_residual with stream progress
    let prog = t * t * (3.0 - 2.0 * t); // smoothstep
    score -= 12.0 * (r / c) * (1.0 - prog);

    // Penalize large dead space quadratically, scaled by progress
    let dead = r / c;
    score += 30.0 * dead * dead * prog;

    // Reward tight fits when bin is the last fitting option
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 * (next_item_size as f64 / c);
    }

    // Prefer bins below mean residual slightly (fill fuller bins)
    score += 0.05 * (r - mean_residual);

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item sizes (or their complements) are "usable" dead space.
    let post = post_residual;
    if post > 0 {
        // Reward residuals that are exactly divisible into likely item sizes
        // (10, 20, 25, 50 classes) — these can be filled perfectly later.
        let harmonic_bonus = if post % 50 == 0 { 40.0 }
        else if post % 25 == 0 { 30.0 }
        else if post % 20 == 0 { 25.0 }
        else if post % 10 == 0 { 15.0 }
        else { 0.0 };
        score -= harmonic_bonus;
    } else {
        // Perfect fit: strongly favored.
        score -= 120.0;
    }

    // Penalize awkward small dead space (1..9) — nearly unusable.
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 90.0;
        } else if post > next_item_size {
            // Next item fits: penalize by leftover after next placement.
            score += 0.3 * (post - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's remainder.
            score += 0.15 * post as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // (low mean residual) or item is large and fits nowhere tightly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Open new bin if mean residual is small (bins nearly full) —
        // otherwise penalize so existing bins get used.
        score += 60.0 - 120.0 * (1.0 - crowding) - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Mild pressure to consolidate into fewer bins early in the stream.
    score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical future items.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 50.0;
    }

    // Strong penalty for leaving a small gap that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 20.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bins pressure: penalize contributing to bin sprawl lightly.
    score += 0.1 * open_bins_count as f64;

    // Prefer bins whose residual is above mean (keep large gaps flexible).
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that cannot fit the next item (2-step lookahead)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual == next_item_size {
            // Perfect 2-step match: strongly reward
            score -= 25.0;
        } else {
            // Next item fits: reward proportional to tightness of the pair
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits (small post_residual)
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Relative to mean residual: prefer bins with less residual than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
        // Exception: if no existing bin leaves a usable residual for the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.004;

    // Penalize dead space that can't hold typical small items (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding: prefer bins in a moderately loaded fleet.
    if open_bins_count > 1 {
        score -= 3.0;
    }

    // Prefer bins with residual below mean (consolidate waste).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (post_residual as f64).max(0.0) };
        score += 55.0 + desperation * 0.2 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Smooth non-linear coupling: penalize large residual more as stream progresses
    score += rn * rn * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly over time
    score -= (1.0 - rn) * (1.0 - rn) * item_size as f64 * (0.3 + 0.7 * progress);

    // Dead-space penalty: residual too small for typical next item
    if next_item_size > 0 {
        let nn = next_item_size as f64;
        if r < nn {
            score += (nn - r) * 0.6 * (1.0 - progress);
        } else {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild preference for bins below mean residual (keeps larger gaps distributed)
    score += 0.15 * (r - mean_residual);

    // Discard new-bin candidate early; allow it late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into coarse "waste bands" of size 10.
    let band = post_residual / 10;
    // Penalize small-but-nonzero leftovers (dead space) superlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.5 * post_residual as f64;
    }

    // Modulo arithmetic: leftovers that are multiples of 10 (or 5) are
    // "harmonic" — likely reusable by future items. Reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Harmonic-class check: does next item leave a multiple-of-10 remainder?
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 12.0;
            }
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            // Next item cannot use this leftover: mild penalty scaled by gap.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Late in the stream, prefer tightening existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Penalize bins far below the mean residual when many bins are open
    // (keeps residual distribution tight).
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: empty bin should only win when the fit into open bins
    // would be very poor. Give the empty bin a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * (item_size as f64) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Residuals below the item size range floor but usable only by tiny items.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many
    // are already open; encourage consolidating into existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 6.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late, avoid it.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chaining placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins whose residual is below the mean (filling fuller bins first),
    // keeping emptier bins flexible.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (good chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable gap
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize very small post residuals (unusable dead space)
    if post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless item is large or fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 60 {
            score -= 20.0;
        }
    } else {
        // Tightness reward: prefer bins where item fills a large fraction of residual
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.5 * (pr / cap) * (pr / cap) * 100.0;

    // Penalize dead space that can never be used again (post_residual too small
    // for the smallest plausible item, i.e., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: penalize if the next item can no longer fit in this bin's
    // post-residual, especially when it could have fit before placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            score += 0.8 * nx;
        }
        // Reward leaving room that accommodates the next item exactly-ish.
        if (next_item_size as u32) == post_residual {
            score -= 25.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 0.3 * (post_residual as f64 - nx);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when the item would leave a large unusable residue elsewhere,
    // or when open bins are already quite full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 0.55 * cap;
        // Cheaper to open a bin early in the stream (more future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // More expensive when many bins are already open.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is high, prefer existing bins.
        score += 0.4 * mean_residual;
        // Opening a new bin is good if the item is huge (tight elsewhere unlikely).
        if item_size >= 70 {
            score -= 20.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 15.0;
        }
    }

    // Slight preference for bins with below-average residual (fill fuller bins
    // first, keeping slack concentrated in fewer bins).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling: penalize mid-range dead space quadratically,
    // reward near-full fills more aggressively as stream progresses.
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);
    score += 6.0 * x * (1.0 - x) * (1.5 - progress);

    // Smooth interaction with mean residual: prefer bins whose residual deviates
    // favorably (smaller) from the mean, coupled non-linearly with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev * (1.0 + progress);

    // Lookahead term: smooth reward if next item fits remaining space.
    if next_item_size > 0 {
        let fits = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 5.0 * fits * (0.5 + progress);
    } else {
        score -= 3.0 * (1.0 - x);
    }

    // Last-chance bonus: smooth pressure to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 7.0 * (1.0 - x) * (0.5 + progress);
    }

    // Congestion term: mild penalty for many open bins, smoothed.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits (small post_residual), strongest when leftover is in a "usable" class.
    let tight_fit = (post_residual <= eighth) as f64;
    score -= 25.0 * tight_fit;

    // Penalize dead space: leftovers that no typical item (>= next_item_size) can use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        }
        // Reward leftovers that exactly or nearly fit the next item (harmonic pairing).
        if post_residual >= next_item_size {
            let pair_gap = post_residual - next_item_size;
            if pair_gap <= eighth {
                score -= 14.0;
            }
        }
        // Modulo class: leftover divisible into halves/quarters is reusable.
        if post_residual % quarter == 0 && post_residual > 0 {
            score -= 6.0;
        } else if post_residual % (eighth.max(1)) == 0 && post_residual > 0 {
            score -= 3.0;
        }
    } else {
        // Last item: just minimize waste aggressively.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 22.0 + 10.0 * progress;
        // If no open bin fits well, allow new bin: reduce penalty when mean residual is low.
        new_bin_penalty -= 15.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        let _ = crowd;
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins (small bin_residual).
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * -0.0;

    // Spread-awareness: prefer bins below mean residual (relatively full).
    score += 0.08 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: leaving almost nothing behind is excellent.
    if pr <= 5.0 {
        score -= 12.0;
    } else if pr <= 10.0 {
        score -= 6.0;
    }

    // Lookahead dead-space avoidance: if the leftover gap can't host the next
    // item, it is likely wasted dead space (unless it's tiny/tight).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr > 10.0 && pr < n {
            score += 8.0 * (1.0 - pr / n);
        } else if pr >= n {
            // This bin can also serve the next item: chain-fit bonus.
            score -= 4.0;
        }
    }

    // Last-chance pressure: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Prefer bins that are already well-filled (waste-aware tiebreak).
    score -= 0.05 * (cap - bin_residual as f64);

    // New-bin candidate penalty: opening a bin is costly, scaled by how many
    // bins are already open and how large the item is (large items justify
    // fresh bins more, so soften the penalty for them).
    if bin_residual == bin_capacity {
        let item = item_size as f64;
        let softening = 0.25 * item * (item / cap);
        score += 12.0 + 0.6 * open_bins_count as f64 - softening;
    }

    // Mild stream-progress pressure: late in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 3.0 * progress;
        } else {
            score += 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact 2-chain match
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // post_residual cannot host next item: penalize proportional dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when good open bins exist; allow it only for huge items
    // that would leave tiny dead space elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual >= next_item_size && next_item_size > 0 {
            score += 400.0; // an open bin can chain the next item; don't open new
        } else if fitting_bins_count > 0 && post_residual < 15 {
            score -= 100.0; // new bin gives near-perfect fit, worth it
        } else if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead space that can't host even the smallest future item is worst
        let dead = if pr < 10.0 { 1.5 } else { 0.4 };
        score += dead * pr * (1.0 - fill_ratio);
    }

    // Lookahead: reward if the next item fits exactly/roughly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for lookahead item: penalize proportionally
        score += 6.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Discourage opening new bins when plenty of open bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fitting_bins_count as f64;
        score += 22.0 + 15.0 * (1.0 - progress) + 4.0 * pressure;
        // but allow new-bin opening late in stream when mean residual is large (fragmentation)
        if mean_residual > item_size as f64 * 1.6 {
            score -= 8.0;
        }
    }

    // Mild preference for bins with residual close to the global mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for more-filled bins among equals.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // base: prefer small post residual, softened late in stream
    let mut score = norm_pr * (1.0 + 0.5 * progress * (1.0 - norm_pr));

    // non-linear polynomial coupling of post_residual with progress
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress);
    score -= 0.8 * coupling;

    // penalize dead space relative to mean residual
    let dead = (pr - mean_residual).abs() / cap;
    score += 0.3 * dead * dead;

    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 0.6 * slack * (1.0 - slack);
        } else {
            score += 0.4 * (ns - pr) / cap;
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // slight preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 0.7 + 0.5 * progress;
    } else {
        score -= 0.2 / (open_bins_count as f64 + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (bin closed exactly)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: tiny leftovers are nearly unusable (items >= 10 typically)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class logic: penalize post_residual by its residue class mod 10
    // (residuals that are small multiples of common item sizes are more reusable)
    let class = post_residual % 10;
    score += class as f64 * 0.8;

    // Quantized class of next item vs post_residual: does the lookahead item
    // land in the same "harmonic band" (same integer-division bucket of 10)?
    if next_item_size > 0 {
        let next_class = (next_item_size % 10) as f64;
        if next_item_size <= post_residual {
            score -= 15.0 + next_class * 0.3; // lookahead fits: reward
        } else if post_residual > 0 {
            score += 12.0; // lookahead cannot fit: this leftover is likely dead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        } else if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits elsewhere: new bin is correct
        } else {
            // big items deserve fresh bins; small items should squeeze into open bins
            score += 35.0 - 40.0 * frac;
        }
    }

    // Prefer bins whose residual diverges sensibly from the mean (balance keeping
    // some bins tight and some flexible)
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Late in the stream: tighten bins harder (less room to recover)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * t * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below next_item_size can't serve lookahead.
    if post_residual > 0 {
        if post_residual < 10 {
            // tiny sliver: nearly dead space -> strong penalty
            score += 40.0 - (post_residual as f64) * 2.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // can't hold the lookahead item: partial dead weight
            score += 12.0;
        } else if next_item_size > 0 && post_residual == next_item_size {
            // perfect lookahead fit: big reward
            score -= 25.0;
        }
    } else {
        // perfect closure of the bin
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, prefer reusing over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bin would leave bad dead space
        // and open bins are few (early stream) — allow fresh bins when pressure low.
        score += 20.0 + pressure;
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            // the alternative bin creates dead space; soften new-bin penalty
            score -= 35.0;
        }
    } else {
        // mild reward for consolidating into already-open bins
        score -= 3.0;
        // prefer bins whose residual deviates from mean toward being smaller (more filled)
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // combined two-item fill
        if item_size + next_item_size <= bin_residual {
            score -= 150.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        // early stream: new bins are fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // discourage leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is fine; large dead space penalized super-linearly.
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mildly good, scaled by leftover after next
            let after2 = post_residual - next_item_size;
            score -= 40.0 - (after2 as f64) * 0.2;
        } else {
            // next item cannot use this residual: penalize proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: only one bin fits the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Time horizon: early in the stream, be more willing to open/keep flexible bins;
    // late in the stream, prioritize filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Global state: many open bins with high mean residual -> tighten packing,
    // favor bins below mean residual (tighter bins).
    if open_bins_count > 2 {
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only if no open bin
    // offers a good fit. Make it slightly unattractive so real fits win, but not
    // so unattractive that terrible fits (huge dead space) win instead.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + (next_item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 0.5 * norm_pr * progress;
    score += 12.0 * poly;

    // Penalize residual that neither fits the lookahead item nor is small
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap).abs();
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    } else {
        score -= 2.0;
    }

    // Last-chance bonus: only one bin fits this item
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild pressure to prefer fuller bins as many bins are open
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Reward tight fits near capacity
    score -= 6.0 * (1.0 - (pr / cap).powf(2.0)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (large chunks) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward exact or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division classes: leftover bucketed by quarters of capacity.
        let quarter = bin_capacity / 4;
        let class = post_residual / quarter.max(1);
        score -= (4 - class) as f64 * 15.0; // smaller leftover class -> better
    }

    // Penalize dead space that no plausible future item can use:
    // if post_residual is smaller than the minimum plausible item (harmonic floor),
    // it is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this bin is a harmonic pair -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let pair_waste = post_residual - next_item_size;
            if pair_waste <= 10 {
                score -= 150.0;
            } else {
                score -= 50.0;
            }
        } else {
            // next item cannot use this bin's leftover: slight penalty scaled
            // by how much of the residual would be stranded.
            score += (post_residual as f64 - cap * 0.5).max(0.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + (bin_residual - item_size) as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin has high raw residual;
    // only let it win when existing bins would leave very poor fits.
    if bin_residual == bin_capacity {
        // New bin starts with a handicap that shrinks as stream progresses
        // (late in stream, consolidation matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * progress;
        // But if next item is large and current bins are fragmented, opening
        // a fresh bin can be wise.
        if next_item_size >= 60 && mean_residual < 40.0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score += (post - mean_residual) * 0.15;

    // Slight preference for keeping number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the smallest item size (1)
    // are pure waste; residuals too small for typical items are near-waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty scales with how large the unusable gap is relative to item.
    if post_residual < item_size as u32 {
        score += 0.5 * (item_size - post_residual as u32) as f64;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate implicitly via residual, but add pressure).
    score += 0.15 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the remaining space, slight penalty for stranding.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Progress-based mild tightening: later in stream, be greedier about fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins that end with near-zero residual.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // Exact two-item chain: post_residual - next_item_size == 0 is ideal.
            let chain_left = post_residual as f64 - next;
            score -= 150.0 - chain_left * 0.5;
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            let waste = next - post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Relative tightness vs mean residual: prefer bins tighter than average.
    let mean = mean_residual;
    if mean > 0.0 {
        let rel = post_residual as f64 / mean;
        if rel < 1.0 {
            score -= (1.0 - rel) * 50.0;
        } else {
            score += (rel - 1.0) * 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but allow it if the item is large and would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let awkward = item_size > 50 && post_residual < 20;
        score += if awkward { 50.0 } else { 300.0 };
    }

    // Prefer using bins with more accumulated fill early in the stream;
    // keep more bins open later to preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill of the bin after placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Penalize small dead space that is hard to reuse (post_residual too small for typical items)
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to wasted opportunity
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only for large items
    // or when mean residual across open bins is very low (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        let new_bin_bias = 55.0
            - 40.0 * (item_size as f64 / bin_capacity as f64)
            - 30.0 * fragmentation
            - 15.0 * (1.0 - progress);
        score += new_bin_bias;
    } else {
        // Mild preference for reusing bins when many are open (avoid bin sprawl)
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Prefer bins whose residual deviates from mean (consolidate space)
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Small time-horizon modulation: early in stream, be greedy for tight fits;
    // late in stream, prioritize closing out bins (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (small post_residual dominates).
    // Late stream: tolerate some residual to keep bins usable for future items.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 40.0
                 + pr_norm * progress * 10.0;
    score += coupling;

    // Penalize residuals that cannot fit the lookahead item (dead space),
    // smoothly weighted by how close the next item is to fitting.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += gap * gap * 60.0;
        } else {
            // Reward bins that leave room for the next item.
            let slack = (pr - ns) / cap;
            score -= (1.0 - slack) * 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by item size (bigger items benefit more).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // Mild penalty when this bin deviates from mean residual (keep bin pool balanced),
    // with a smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 12.0;

    // New-bin candidate: neutral baseline plus mild progress-dependent reluctance,
    // so a fresh bin wins only when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else {
        // Penalize residuals in "dead zones": small unusable slivers (1..10)
        // modulo-class analysis: residual % 10 == 0 leaves room for small items
        let m = post_residual % 10;
        if m != 0 && post_residual < 20 {
            score += 30.0; // tiny awkward sliver
        }
        if post_residual % 10 == 0 {
            score -= 15.0; // decade-aligned residual is reusable
        }
    }

    // Integer-division threshold classes on post_residual
    let q = post_residual / 25; // 0..4 quartile class
    score += match q {
        0 => 20.0,          // 0..24: near-dead space
        1 => 5.0,           // 25..49
        2 => -5.0,          // 50..74
        3 => -10.0,         // 75..99
        _ => -25.0,         // full-ish bin, great
    };

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly
            // exact harmonic match: residual becomes 0 after next item
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                let pr2 = post_residual - next_item_size;
                if pr2 <= 5 {
                    score -= 25.0; // two-item perfect packing
                }
            }
        } else {
            // next item won't fit here; sliver risk scales with gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 10.0).min(20.0);
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 40.0;
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // base penalty so we prefer reusing bins with decent fits
        score += 80.0
            - 60.0 * progress
            - (open_bins_count as f64).sqrt() * 3.0;
        // if existing bins are crowded (low mean residual), new bin more attractive
        score -= (mean_residual / 10.0).min(40.0);
        if post_residual == 0 { score = -1e9; } // placing full item in empty bin: perfect
    }

    // Slight preference for bins tighter than average (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual <= 25 {
        // Small gaps are unlikely to be filled later; moderate penalty.
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit (i.e. when mean residual is small or
    // this bin is the only fitting one and its fit is bad).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress
        // (early on, keeping bins open is cheap; later, prefer consolidation).
        let mut new_bin_cost = 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // If lookahead item would fit nicely in the fresh residual, discount
        // opening a new bin slightly.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            if item_size + next_item_size <= bin_capacity {
                new_bin_cost -= 10.0;
            }
        }
        // If mean residual across open bins is large, open bins are wasteful;
        // opening a new bin is relatively more attractive.
        new_bin_cost -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        score += new_bin_cost;
    } else {
        // Placing into an existing bin: small bonus for keeping the bin
        // footprint aligned with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leaving a gap that neither fits the next item nor is useful.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Mild preference for bins whose residual is closest to the item,
    // refining tightness selection.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: this bin absorbs the next item exactly
        } else {
            // continuous penalty growing with mismatch, but only if next item could still fit
            if post_residual >= next_item_size {
                score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // next item cannot follow into this bin: penalize dead space
                score += 8.0 + gap / 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Reward tight fits relative to current mean residual of open bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Penalize leaving very small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for keeping large residuals available early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    // New-bin candidate: only attractive when existing fits are poor (high post_residual waste).
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fill anywhere.
        score -= 10.0;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are fragmented or very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 40.0
            - 15.0 * progress
            - (mean_residual / bin_capacity as f64) * 20.0
            - (fragmentation / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins relative to fleet state.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Tie-break: fewer open bins favored slightly.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: tight fit preferred, with polynomial shaping of residual
    let mut score = pr * (1.0 + 0.35 * prn * prn);

    // Non-linear coupling of residual with stream progress:
    // later in stream -> value tight fits more strongly
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 8.0 * progress_coupling * (1.0 - prn);

    // Penalize near-capacity residuals (dead space) with smooth cubic
    score += 0.002 * pr * pr * pr / cap;

    // Last chance bin: strong reward for using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs();
        score += fits_next * (-6.0 + 0.05 * gap);
        score += (1.0 - fits_next) * 5.0;
    }

    // Slight preference for consolidating into fewer bins
    score += 0.4 * open_bins_count as f64 * prn;

    // Mean residual deviation: prefer bins close to mean (balanced packing)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - prn) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that stay "usable"
    // in modular terms (multiples of common size classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Penalize residuals in awkward harmonic classes (e.g. 1..10 dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward residuals that are multiples of 10 or 25 (common item sizes)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when the current bin
    // would leave a very tight dead space AND lookahead item is large.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        if next_item_size > 0 && (next_item_size as f64) > frac * cap {
            // new bin can host next item directly
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Tightness: reward filling bins that are already mostly full
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * tightness * tightness;

    // Lookahead compatibility: if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting space
        score += 0.05 * ((next_item_size - post_residual) as f64);
    }

    // Prefer bins with residual below mean (fill the emptier-trending bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Cap open bins: if many bins open, discourage new ones
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype.
    let mut score = post_residual as f64;

    // Hard penalty for "unusable" small gaps: residuals that cannot hold
    // the smallest plausible item (<= 10) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty for small-but-usable gaps that are unlikely to be filled:
    // gaps below ~20 are hard to fill with typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (waste-proportional quadratic term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward it;
    // if next item barely misses, penalize creating a near-miss gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins; new empty bins
    // (residual == capacity) get a penalty that grows with stream progress.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 2.0 * open_bins_count.min(10) as f64;
    }

    // Slight preference for bins with residuals below the mean (consolidate
    // small residuals into one bin rather than spreading waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to tightness
            score -= 0.5 * (next_item_size as f64 / post_residual as f64) * 100.0;
        } else {
            // next item won't fit: penalize wasted residual relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals too small to ever hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Prefer bins below mean residual (tighter bins) when fitting bins are scarce
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Deviation from mean residual: prefer near-mean consolidation early, extremes late
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev * (1.0 - progress);

    // Mild penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + 0.5 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combo_waste = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - combo_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a gap that just barely fails the next item.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: only attractive when existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // In early stream, be more willing to open bins (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If mean residual of open bins is high, prefer using them.
        score += (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // Large items: better to give them a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Slight penalty when many bins are open: encourage closing gaps.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: post residual, mildly discounted early (keep bins open for future items)
    let mut score = r * (0.8 + 0.4 * progress);

    // Non-linear polynomial coupling of residual with stream progress
    let poly = norm_r * norm_r * (1.0 - progress) + norm_r * progress * progress;
    score += 12.0 * poly;

    // Penalize small residuals that become dead space, smoothly
    let dead = (1.0 - norm_r).powi(3);
    score += 8.0 * dead * (0.5 + progress);

    // Lookahead: reward residual that fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            score -= 6.0 * (1.0 - ((r - nx) / cap).powi(2));
        } else {
            score += 4.0 * ((nx - r) / cap);
        }
    }

    // Last-chance fitting bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferation of open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (good packing)
    score += 3.0 * (mean_residual - r) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // leaves room for future items; prime/unusual residuals become dead space.
    let dead = if post_residual == 0 { 0.0 } else {
        let mut d = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 { d -= 8.0; }
        }
        if post_residual < 10 { d += 25.0; } // unusable sliver
        d
    };
    score += dead;

    // Integer-division threshold: post_residual bucketed into fifths of capacity.
    let fifth = bin_capacity / 5;
    let bucket = post_residual / fifth;
    score += bucket as f64 * 3.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic complement: next item exactly consumes remainder
            if post_residual == next_item_size { score -= 30.0; }
            else { score -= 10.0; }
        } else {
            score += 12.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes residual elsewhere.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        // Prefer new bin only if no open bin fits well (tight fit threshold).
        let tight_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) < (bin_capacity as f64 * 0.15);
        if tight_elsewhere {
            score -= 35.0 + pressure;
        } else {
            score += 45.0 + pressure * 2.0;
        }
    }

    // Slight early-stream bias to consolidate bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post_residual gaps that no future item can use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // Tiny dead space is nearly worthless; penalize proportionally.
        score += (10.0 - gap) * 2.5;
    }

    // Reward tight fits (small post_residual overall).
    score -= (bin_capacity as f64 - gap) * 0.05;

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids waste).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mildly penalize leaving awkward gaps.
        score += gap * 0.3;
    }

    // Mean residual coupling: bins deviating far below the mean residual are
    // already tight; prefer them slightly (they absorb large items well).
    score -= (mean_residual - gap) * 0.2;

    // Brand-new bin candidate: neutral baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/chain fits with the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot chain here: penalize residual that becomes dead space
        let dead = post_residual as f64;
        score += 6.0 * dead / bin_capacity as f64;
    }

    // Reward tight fits relative to mean residual
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * tightness;

    // Penalize bins whose residual deviates far above mean (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mildly discourage opening new bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty, stronger if this was the only fit.
            score += 6.0;
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 20.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below the mean (consolidate waste), penalize above-mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative with new bins; late, pack greedily.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, ease up later.
        score += 20.0 * (1.0 - t) + 5.0;
        // Discourage new bin if many open bins exist with room.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        score -= 8.0 * t;
    }

    // Mild penalty for proliferating open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: favor small post-residual, with smooth non-linear shaping
    let mut score = pr
        - 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr
        + 10.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post-residual with stream progress:
    // late in the stream, tighten up more aggressively on waste
    let tight = 12.0 * progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score -= tight * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Dead-space penalty: residual too small to fit typical small items
    let dead = if norm_pr > 0.0 && norm_pr < 0.1 { (0.1 - norm_pr) * 100.0 } else { 0.0 };
    score += dead;

    // Last-chance bonus: only one fitting bin -> prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Prefer bins below mean residual slightly (balance-aware smooth coupling)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx) / cap).max(0.0);
        score -= 6.0 * fit_next * (1.0 - slack * slack);
        score += 4.0 * (1.0 - fit_next) * (nx / cap);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste quantization in units of 10
    let waste_class = post_residual / 10;
    score += (waste_class % 3) as f64 * 1.5;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Integer-division threshold: bins whose residual becomes a "useful" class
    // (divisible by common small item sizes) are favored.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does post_residual still admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // Harmonic bonus: next item leaves another clean class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            if next_post == 0 {
                score -= 60.0;
            }
        } else {
            // Dead space for the lookahead item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // But if the item is large relative to mean residual, new bin becomes attractive
        if (item_size as f64) > mean_residual {
            score -= 55.0;
        }
    }

    // Prefer filling bins with small residuals first (tightness pressure)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Stream progression: early on, be slightly more willing to open bins (flexibility),
    // later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Pressure from too many open bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward; if it would leave dead space, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 60.0 + 4.0 * open_bins_count as f64 - 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large-item streams favor fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // dead space the next item cannot use
            score += 25.0 + diff * 0.5;
        }
        // near-exact chain fit
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // last item: prefer tightest fit (post_residual already does this)
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, use it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0;
        // but if next item is large and would waste this bin, allow new bin
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 120.0;
        }
    }

    // Progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize large post-residual more as stream advances (dead space is costly later).
    score += (post_residual as f64 / bin_capacity as f64) * (30.0 + 90.0 * progress);

    // Reward tight fits: exact fill gets big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = post_residual - next_item_size;
        score -= 25.0 * (1.0 - lookahead_fit as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize wasted potential slightly.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Compare residual against mean residual: below-mean residual bins (fuller) are favored.
    score += 0.5 * ((post_residual as f64 - mean_residual).max(-50.0).min(50.0));

    // Penalize scattering across many open bins when post_residual is small and unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 + 0.3 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large or existing fits are poor. Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by remaining stream length.
        let remaining = (total_items - step_index) as f64;
        let horizon_factor = 1.0 / (1.0 + remaining / 100.0);
        score += 55.0 * horizon_factor + 10.0;

        // Encourage new bin for big items that would leave tiny residuals anywhere else.
        if item_size >= 70 {
            score -= 30.0;
        }
        // If next item is large and current item is large, fresh bin pairs well.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild reward for placing large items (harder to place later).
    score -= 0.15 * item_size as f64 * (0.5 + 0.5 * progress);

    // Small penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, with non-linear (quartic) penalty on large residuals
    let mut score = pr as f64 * (1.0 + 2.0 * x * x * (1.0 - x) * (1.0 - x));

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tolerate slightly larger residuals less (dead space matters more)
    score += 12.0 * x.powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - x);
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size as u32) as f64 / cap);
        score -= 6.0 * snug;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by how much space is wasted
        score += 3.0 * x;
    }

    // Smooth interaction with mean residual: prefer bins below mean residual (compact usage)
    score += 2.0 * (x - mean_residual / cap).abs().powi(2);

    // New-bin candidate: keep it moderately attractive only when residuals are all poor
    if bin_residual == bin_capacity {
        score = cap - 4.0 * progress + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 capture "dead-space classes".
    let r = post_residual % 10;
    // Residues 1..9 (non-decade) are least reusable; 0 is best (decade alignment).
    let residue_penalty = match r {
        0 => -14.0,
        5 => 2.0,
        2 | 8 => 4.0,
        1 | 9 => 7.0,
        _ => 5.0,
    };
    score += residue_penalty;

    // Integer division thresholds: post_residual in harmonic thirds of capacity.
    let third = bin_capacity / 3;
    if post_residual < third {
        score += 10.0; // tiny sliver, likely dead space
    } else if post_residual < 2 * third {
        score -= 6.0; // sweet-spot leftover
    } else {
        score -= 3.0; // large leftover, still flexible
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial credit scaled by how well next item harmonizes (mod 10 alignment).
        let nr = (post_residual - next_item_size) % 10;
        if nr == 0 {
            score -= 12.0;
        } else {
            score += nr as f64 * 0.6;
        }
    } else if next_item_size > post_residual {
        // Next item can't use this bin's leftover anyway; slight penalty if leftover small.
        if post_residual < 10 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / bin_capacity as f64;
        score += 45.0 - 30.0 * crowd - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for tighter bins overall relative to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Small tie-break toward bins whose residual is a multiple of 5 (harmonic reuse).
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // tiny gaps are worst
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward filling a bin that is the only fitting option (last chance),
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; the new-bin candidate (residual == capacity) gets this
    // penalty at full strength, making it unattractive unless it's the
    // only sane option.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        score += pressure + 20.0;
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual is close to the item (tight packing),
    // penalize wasteful placement into a much larger bin.
    let slack = (bin_residual - item_size) as f64;
    score += slack * 0.15;

    // Lookahead: if the next item would fit exactly into the post_residual,
    // this placement is excellent; if post_residual barely misses it, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (reduce variance of gaps).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect two-step fit: keep this bin for the next item
        } else {
            score += 0.35 * diff; // penalize mismatch with lookahead
        }
        // If post_residual cannot hold next item but is small, mild penalty for dead space
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 0.25 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: just prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Penalize leaving large unusable residual relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // Penalize very small residuals (dead space < typical min item size)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 30.0; // fresh bin perfectly fits next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual < 10 {
        score -= 25.0; // perfect fill is great
    } else if post_residual <= 15 {
        score += 6.0; // tiny dead space is worst-case waste
    } else {
        let t = (post_residual as f64 - 15.0).ln_1p();
        score += 2.0 * t; // mild penalty growing with residual
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a residual that blocks it badly.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64; // post_residual for empty bin
        score += 8.0; // mild bias against opening new bins
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // Later in the stream, prefer consolidating into open bins more strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
    }

    // Global state: many open bins with low mean residual -> favor filling existing bins.
    if open_bins_count > 2 && mean_residual < 40.0 {
        if bin_residual != bin_capacity {
            score -= 0.1 * (open_bins_count as f64) * (40.0 - mean_residual) / 40.0;
        }
    }

    // Mild time-decay of residual penalty: early stream, waste matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = norm_post * norm_post * (1.0 - progress) * 8.0;
    score += progress_coupling * cap;

    // Cubic dead-space penalty, amplified late in the stream
    let dead = norm_post * norm_post * norm_post;
    score += dead * cap * (0.5 + 2.0 * progress);

    // Reward tight fits smoothly (small post_residual relative to capacity)
    let tightness = (-norm_post * 4.0).exp();
    score -= tightness * cap * 0.35;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / cap;
        score -= cap * fit_ratio * (0.6 + 0.8 * progress);
    }

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= cap * 0.5 * (1.0 + progress);
    }

    // Mild penalty for many open bins with large residual dispersion
    let spread = (mean_residual - post).abs();
    score += spread * 0.05 * (open_bins_count as f64).sqrt();

    // New-bin candidate: penalize slightly unless current residual is very poor
    if bin_residual == bin_capacity {
        let penalty = cap * (0.25 + 0.5 * (1.0 - norm_post));
        let bad_fit = (norm_post - 0.5).abs();
        score += penalty - cap * bad_fit * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
