pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Perfect fit is excellent; tiny-but-nonzero dead space is terrible.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        score += 15.0; // awkward small gap: penalize beyond raw residual
    }

    // Reward tight fits proportionally (small post_residual already low,
    // amplify the ordering among good fits).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here, mild bonus proportional to how well
        score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 {
        // next item would not fit here: mild penalty if this bin becomes dead
        if (post_residual as f64) < dead_threshold * 2.0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // New-bin candidate handling: an empty bin has large post_residual, which
    // already scores high; add a fixed offset so it only wins when open bins
    // have genuinely poor fits (large residuals far above item needs).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        score -= 25.0 * (1.0 - progress);
        // If no open bin can even fit the item, the new bin must win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for bins below mean residual (keep residuals balanced),
    // which preserves flexibility for future items.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // 2-step lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: mild reward proportional to how well it pairs
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // next item would NOT fit after this placement: penalize creating dead space
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
    }

    // Relative to mean residual: bins with residual far below mean are precious,
    // prefer filling them; bins with residual above mean are less attractive.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when good fits exist, especially early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress);
    }

    // Slight penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasteful
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for large leftover
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: prefer the tightest, dampen differences
        score += 2.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fits are poor (large post residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        if poor_fit > 0.5 && fitting_bins_count <= 2 {
            score -= 15.0 * poor_fit; // open fresh bin rather than waste space
        } else {
            score += 10.0; // prefer existing bins otherwise
        }
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= 0.05 * consolidation_pressure * (1.0 - progress);

    // Late in the stream, avoid opening new bins.
    score += 15.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild preference for filling fuller bins overall.
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth polynomial coupling to stream progress.
    // Early on, prefer tight fits (penalize post_residual strongly);
    // late in the stream, prefer leaving slightly larger usable space.
    let early_weight = (1.0 - progress) * (1.0 - progress);
    let late_weight = progress * progress;

    let mut score = pr * (0.8 + 0.6 * early_weight) + norm_pr * norm_pr * 40.0 * (1.0 - late_weight);

    // Smooth dead-space penalty: polynomial in normalized post_residual.
    let dead = norm_pr * norm_pr * norm_pr;
    score += dead * 25.0;

    // Reward perfect fits with a smooth quadratic bonus.
    if post_residual == 0 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_quality * (0.5 + 0.5 * early_weight);
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - progress * 0.3);
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // more strongly early in the stream (prefer consolidating).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.2 - progress);
        // But if no existing bin fits well, allow opening: reduce penalty
        // when mean residual across open bins is small.
        score -= 10.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    // Mild diversification pressure as open bins accumulate.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // small classes (0..=10, 11..=20, ...) get a reward for tight packing.
    let class = (post_residual / 11) as f64;
    score += class * 3.0;

    // Perfect fit reward: residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Penalize residuals in the "dead zone": too small for the smallest item (1)
    // is fine, but residuals just above common item sizes waste space. Use
    // modulo arithmetic on post_residual to detect awkward leftovers.
    let pr = post_residual as i64;
    if pr > 0 && (pr % 10 == 1 || pr % 10 == 2) && pr <= 30 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left <= 5 {
                score -= 15.0;
            } else {
                score += (chain_left as f64) * 0.3;
            }
        } else {
            // next item cannot follow here; residual is final -> penalize waste
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or the fit here would be poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // base cost of a fresh bin
        score += 25.0;
        // if open bins are nearly full on average, new bin is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
        if pressure > 30.0 {
            score -= 10.0;
        }
        // big items justify fresh bins
        if item_size >= 60 {
            score -= 8.0;
        }
    } else {
        // Existing-bin bonus scaled by how well item fills the bin.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 10.0;
    }

    // Stream progression: early on, be conservative with new bins; late in the
    // stream, prefer closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Mild penalty for too many open bins (fragmentation control).
    if open_bins_count > 8 {
        score += ((open_bins_count - 8) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (below min item size) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the known next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward perfect or near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 90.0 } else { 0.0 };
        score += 25.0 + bad_fit + (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

