pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = post / cap;

    // Base: quadratic penalty on wasted residual (dead space grows superlinearly in cost).
    let mut score = post * (1.0 + fit_norm);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, waste is punished more aggressively (smooth polynomial ramp).
    let ramp = 0.5 + 1.5 * progress * progress * (3.0 - 2.0 * progress);
    score *= ramp;

    // Reward near-perfect fits smoothly (smooth exponential bonus for small post_residual).
    score -= 40.0 * (-post / (0.15 * cap)).exp();

    // Lookahead coupling: if the next item exactly fits the post residual, strongly reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / (0.25 * cap)).exp();
        // Penalize leaving a residual that is awkwardly larger than the next item.
        score += 0.15 * (gap / cap) * post;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (smooth interaction with post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - fit_norm);
    }

    // New-bin candidate handling: an empty bin should only win when existing bins fit badly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = cap * (1.2 + 0.6 * progress)
            + 8.0 * (open_bins_count as f64).ln_1p()
            - 20.0 * pressure * (1.0 - fit_norm);
        // If some open bin gives a near-perfect fit, make the new bin clearly worse.
        score += 60.0 * (-post / (0.05 * cap)).exp().min(1.0);
    } else {
        // Mild penalty for spreading across too many open bins (fragmentation control).
        score += 0.5 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: bins far below mean residual are less attractive (hoarding small bins).
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 35.0;
    } else if post_residual < 25 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: dead space in awkward classes is costly
    let pr = post_residual as f64;
    let frac = pr / bin_capacity as f64;
    score += 20.0 * (frac * frac);

    // Penalize dead space that no future item (10..100) can realistically use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty for wasting a well-fitting alternative
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins are congested / mean residual is low
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 40.0 + 5.0 * congestion - 0.5 * mean_gap;
        // Late in the stream, prefer reusing bins more strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Modulo harmonic: post_residual divisible by common small sizes is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but keep it viable when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // A new bin is attractive if the next item is large and this item fits poorly.
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 12.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins near the mean to keep balance.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // Slight late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but keep usable space.
    score = post_residual as f64 * 0.9;

    // 2-step lookahead coupling with next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Reward bins whose leftover exactly/loosely hosts the next item.
            let gap = post_residual as f64 - next;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect match bonus.
            if gap < 1.0 {
                score -= 20.0;
            }
        } else {
            // Dead space: leftover too small for the next item.
            let deadness = 1.0 - post_residual as f64 / next.max(1.0);
            score += 15.0 * deadness;
        }
    } else {
        // Last item: pure tight fit.
        score -= 10.0;
    }

    // Compare against mean residual across open bins.
    let mean = mean_residual.max(1.0);
    if (post_residual as f64) > mean {
        score += 0.15 * (post_residual as f64 - mean);
    } else {
        score -= 0.15 * (mean - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
