    if pr % 50 == 0 && pr > 0 { score -= 15.0; }
    else if pr % 25 == 0 && pr > 0 { score -= 10.0; }
    else if pr % 10 == 0 && pr > 0 { score -= 8.0; }
    else if pr % 5 == 0 { score -= 2.0; }
    else { score += 6.0; } // awkward residue class

