        } else {
            // next item won't fit here: penalize mildly unless this is a near-perfect fill
            score += 8.0;
        }
        // harmonic coupling: next item size class vs post residual class
        let next_class = ((next_item_size as f64 / cap) * 10.0).floor() as i32;
        if next_class == class && next_item_size > 0 && next_item_size <= pr {
            score -= 6.0; // same harmonic class, likely chainable
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are poor
    if bin_residual == bin_capacity {
        // neutral-ish base; open new bin only if it beats bad residuals
        score = cap * 0.55 + (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: later in stream, prefer consolidating into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (open_bins_count as f64).sqrt().min(6.0);

    // Mean residual coupling: if this bin is far from mean residual, slight penalty
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold on post_residual: bins in [1..20] residual are nearly dead
    if pr >= 1 && pr / 20 == 0 && pr > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for any item (min size 1..10) -> dead space
        score += (10.0 - pr) * 6.0;
    } else if pr == 0.0 {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Dead-space coupling with lookahead: if post_residual cannot host next_item_size
    // but could host smaller items, mild penalty; if it can host next item, reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 12.0;
        } else if pr > 0.0 {
            score += (n - pr).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate: only attractive when residual is large and current fit is loose.
    if bin_residual == bin_capacity {
        let loose = 1.0 - fit_ratio;
        score += 18.0 - loose * 30.0;
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect 2-step match:
    // post_residual exactly equals next item size -> chain two items.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // If next item fits exactly after this placement, big bonus.
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 20.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a large bin on a small item early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let waste = (post_residual as f64) / (bin_capacity as f64);
    score += 10.0 * waste * (1.0 - progress);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (<=10) is wasted. Penalize residuals
    // that are nonzero but too small for any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += 5.0 + ((next_item_size - post_residual) as f64).min(50.0) * 0.2;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // residuals are fragmented (high mean residual spread vs item size) or
    // few bins are open relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).abs();
        let new_bin_penalty = 45.0
            + open_bins_count as f64 * 2.0
            + fragmentation * 0.3
            - progress * 10.0;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins whose residual is already small (consolidate fragments)
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score += 10.0 * tightness;

    // Slight preference for larger items filling large residual bins
    score -= (item_size as f64) * 0.05;

    // Late in the stream, be more conservative: penalize leaving large gaps
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;

    // Base: post residual, with smooth polynomial decay of its "waste" weight.
    let waste_weight = 1.0 + 0.8 * progress;
    let mut score = post * waste_weight;

    // Non-linear dead-space penalty: residuals that are too small to be useful
    // (likely dead space) get progressively punished via a smooth saturating term.
    let dead_frac = post / cap;
    score += 6.0 * dead_frac * dead_frac * (1.0 - dead_frac);

    // Reward tight fills (small post_residual relative to item size).
    score -= 4.0 * (item / cap) * (1.0 - dead_frac).powi(2);

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        score -= 5.0 * (-gap / 12.0).exp();
        // Penalize leaving a residual that matches nothing plausible.
        score += 1.5 * (post / cap) * (nx / cap);
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty for over-crowding choice when alternatives exist,
        // modulated by how average residual compares to this bin.
        let rel = resid - mean_residual;
        score += 0.05 * rel;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score = cap - 10.0 * (1.0 - (scarcity - 1.0).min(3.0) / 3.0);
        // Late in stream, prefer reusing bins: raise new-bin score.
        score += 15.0 * progress;
    }

    // Mild diversity pressure: many open bins -> favor filling existing ones.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes mod 20 (capacity/5). Small leftovers in "good" classes
    // are more likely to be fillable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: leftover in {0} is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class-based bonus: leftovers divisible by 10 are "harmonic" and easy
    // to fill later (items are 1..100, commonly multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Penalize dead space: leftovers below 10 can never be filled
    // (min item size is 1, but very tiny leftovers are still wasteful when
    // they are below typical small items).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // big reward (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // existing bins would leave bad residue.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 5.0 * progress;
        // If many bins are open, discourage spreading.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (keep spread balanced, save
    // large-residual bins for larger future items).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are penalized super-linearly (unusable gap creation).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that can still accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 8.0;
        } else {
            score += 10.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 2.0 * pressure;
        // But if this is the last-chance situation and the fit is terrible,
        // new bin becomes attractive.
        if fitting_bins_count == 1 && post_residual < 5 {
            score -= 40.0;
        }
    } else {
        // Existing bin: slight reward for using it, scaled by pressure.
        score -= 2.0 + 0.1 * pressure;
    }

    // Prefer bins tighter than the mean (well-packed bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Last fitting bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // If next item would fit post-residual almost exactly, extra reward.
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer open bins generally, but allow
    // opening a fresh bin when the fit would be very poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.35;
        if poor_fit && fitting_bins_count > 0 {
            score -= 15.0; // opening a new bin is fine for tiny items
        } else {
            score += 35.0; // otherwise keep filling open bins
        }
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual
    // suggests fragmentation; push score to consolidate into emptier bins.
    let mean_gap = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * mean_gap;

    // Prefer filling bins with larger current residual when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: normalized post residual, shaped by stream progress.
    let x = post / cap; // in [0, 1]
    let shape = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += (x * x * x) * cap * 0.5 * shape;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - x;
    score -= tightness * tightness * cap * (0.3 + 0.4 * progress);

    // Penalize dead space that cannot fit a typical next item: smooth interaction
    // between post_residual and lookahead size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (post - next_item_size as f64).max(0.0) / cap;
        let waste = (nx - x).max(0.0);
        score += waste * waste * cap * 0.6 * (1.0 - usable);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure),
    // coupled smoothly with open bins count.
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * cap * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // New-bin candidate: make empty bins attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = x; // for empty bin post == cap so x == 1 -> poor_fit == 1 only if item tiny
        let fit_quality = 1.0 - (post as f64 / cap);
        let open_pressure = 1.0 / (1.0 + open_bins_count as f64);
        // Favor new bin when placing would leave large waste elsewhere relative to progress
        score = cap * (0.2 + 0.6 * (1.0 - fit_quality)) - cap * 0.3 * open_pressure * (1.0 - progress) - poor_fit * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity/4 bands
    let band = post_residual / (bin_capacity / 4);
    score -= (3 - band) as f64 * 8.0; // prefer bins landing in low-residual bands

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Modulo classes: residuals divisible by small moduli remain more usable
    for m in [5u32, 7, 10] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Lookahead harmonic class: does next item divide the post-residual well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 150.0;
            } else if rem2 <= 10 {
                score -= 60.0;
            }
            // next item fits into a quarter-band of leftover
            if rem2 / (bin_capacity / 4) == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += post_residual as f64 * 0.3;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current item is large relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 100.0 * frac;
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            score -= 20.0; // new bin can host current + next item
        }
    }

    // Late-stream tightening: waste less as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    // Slight preference for bins below mean residual (tighter bins first)
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
