    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild progression scaling: as stream advances, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

