}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after the lookahead placement
            score += slack * 0.35;
            // small bonus if lookahead leaves a very small gap
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize dead space creation
            score += 12.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose remainder stays close to (or below) the mean -> balanced packing.
    let post = post_residual as f64;
    let diff = post - mean_residual;
    score += 0.15 * diff;

    // Penalize tiny unusable remainders (dead space) but allow exact fills.
    if post > 0.0 && post < 10.0 {
        score -= 5.0; // near-full bin is good, keep it attractive
    }
    if post == 0.0 {
        score -= 25.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are poor
    // (post_residual would be tiny/dead) or the lookahead cannot chain anywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so open bins win when they fit well
        score += 30.0;
        // if placing here would leave a dead remainder in every fitting bin context,
        // opening a fresh bin becomes attractive: reduce penalty for large items
        if item_size >= 60 || next_item_size >= 60 {
            score -= 20.0;
        }
        // late in the stream, consolidation matters more: make new bins less appealing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for tighter bins overall (smaller residual before placement).
    score += 0.05 * (bin_residual as f64);

    // Mild entropy: prefer bins among many fitting options less strongly
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly penalize wasted residual, superlinearly (dead space is the enemy).
    let waste_ratio = post / cap;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 15.0 * (item_size as f64) / (bin_residual as f64).max(1.0);
    }

    // Lookahead: if next item fits in the post residual, this bin becomes doubly valuable.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 25.0 + 0.5 * (next_item_size as f64);
    }
    // If next item almost fits, mild penalty for leaving a tantalizing gap.
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well. Penalize new bins when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 20.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, consolidation matters more.
        new_bin_penalty *= 1.0 + progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If the item is large relative to mean residual, new bin may be reasonable.
        if (mean_residual > 0.0) && ((item_size as f64) > mean_residual * 0.8) {
            new_bin_penalty -= 18.0;
        }
        // Large items leave flexible residual in a fresh bin.
        if item_size >= 50 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins with residual near the item (best-fit flavor)
    // already covered; add mild penalty for very large open bins count to encourage packing.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with polynomial smoothing
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Tight fits reward: bonus when post_residual is small relative to capacity
    score -= (1.0 - norm_pr).powi(3) * 12.0;

    // Stream progress coupling: as stream advances, penalize larger residuals more
    score += progress * norm_pr * 15.0;

    // Dead-space penalty: residuals too small for any item (min item ~1) matter late
    let dead = ((8.0 - pr).max(0.0) / 8.0).powi(2);
    score += dead * (20.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty for wasting tight space
        score += 5.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 6.0;

    // New-bin candidate handling: make empty bins attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        // Early or highly fragmented: opening new bin is fine; late & tight: discourage
        score = 10.0 + progress * 20.0 - fragmentation * 15.0;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify by capacity fractions (integer division)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tight-fit reward: perfect fill strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    // Harmonic classes: residual mod 10 classes; small odd leftovers are dead space.
    let class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }
    if class == 1 || class == 3 || class == 7 {
        score += 5.0; // awkward harmonic class
    }

    // Fractional residual tiers (capacity fractions)
    let frac = post / cap;
    if frac > 0.5 {
        score -= 20.0; // plenty of room left, good bin
    } else if frac < 0.1 && post_residual > 0 {
        score += 15.0; // nearly-full bin wastes little, but risky
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 10.0; // next item won't fit here
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate logic: empty bin gets a baseline cost that scales
    // with how many open bins exist and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + open_bins_count as f64 * 4.0 + progress * 20.0;
        // open a new bin only if the item is large and no good fit exists
        if item_size as f64 > cap * 0.6 && fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (<= ~10) are worthless; punish them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Non-linear dead-space penalty: quadratic in unusable gap fraction.
    let gap_frac = post_residual as f64 / bin_capacity as f64;
    if gap_frac < 0.2 {
        score += 80.0 * (0.2 - gap_frac) * (0.2 - gap_frac);
    }

    // Reward excellent fits (small but usable residual).
    if post_residual > 0 {
        score -= 30.0 * (1.0 - gap_frac);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, strongly prefer reuse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + 0.5 * progress);
    score -= 4.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would be blocked by this placement's residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Prefer bins whose residual is close to the item (tight packing),
    // and discourage spreading across bins when mean residual is small.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // New-bin candidate: keep it competitive only when open bins are poor fits
    // (i.e., when mean residual is very small or pressure is low).
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect closure of the bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to tightness
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 40.0 * tightness;
        } else {
            // next item cannot use this bin's leftover: penalize large dead space
            score += 0.25 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean
    // (tighter bins get emptied first, keeping loose bins flexible).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize the brand-new empty bin candidate unless nothing sensible fits,
    // or unless the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 20;
        if !awkward {
            score += 300.0;
        } else {
            score += 30.0;
        }
    }

    // Slight late-stream conservatism: reuse bins more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space, especially small unusable slivers
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 50.0; // tiny sliver is nearly dead space
        }
        score += pr * pr / (bin_capacity as f64 * 2.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 30.0 + 0.3 * nxt; // chain-friendly placement
        } else if (post_residual as f64) > 0.0 && (post_residual as f64) < nxt * 0.5 {
            score += 20.0; // blocks next item badly
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into fuller bins
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score -= crowding * (bin_residual as f64 - post_residual as f64);

    // Time horizon: late in stream, be conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and mean residual is high
        score += 40.0 + 80.0 * progress + 0.5 * mean_residual;
        if fitting_bins_count > 0 {
            score += 60.0; // never open new bin when alternatives exist, unless heavily rewarded elsewhere
        }
    } else {
        // Existing bin: slight discount late in stream
        score -= 10.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (fuller bins)
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - progress);
    score += 40.0 * poly;
    // penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - progress);
    }
    // reward lookahead fit
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // new-bin candidate: prefer it only when residuals are tight late in stream
    if bin_residual == bin_capacity {
        let tight = (mean_residual / bin_capacity as f64 - 0.5).abs();
        score += 25.0 * (1.0 - progress) + 30.0 * tight * (1.0 - progress);
        score -= 20.0 * progress * norm_pr;
    }
    // slight preference for bins tighter than average
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity/10 buckets
    let class = post_residual % 10;
    // Dead space penalty: residuals that are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }
    // Favor residuals that are harmonic multiples (easy future fits)
    let m = (post_residual % 25) as f64;
    score -= 8.0 * (1.0 - m / 25.0);

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack as f64) * 0.3;
        if slack == 0 {
            score -= 15.0; // perfect closure
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // next item won't fit here
    }

    // Last-chance bin: strongly prefer filling it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        // But if current item is huge relative to mean residual, opening fresh is fine
        if (item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Waste penalty relative to capacity fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_frac * waste_frac;

    // Progress-coupled tightening: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * waste_frac;

    // Prefer bins with residual below mean (denser bins)
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // ---- Perfect fit: overwhelming reward ----
    if post_residual == 0 {
        score -= 1000.0;
    }

    // ---- Strict dead-space avoidance ----
    // Leftovers below ~12% of capacity are unlikely to host any future item:
    // the smaller the leftover, the "deader" it is, so the penalty grows as pr shrinks.
    let dead_threshold = (cap * 0.12).max(next_item_size as f64 * 0.9).min(cap * 0.30);
    if pr > 0.0 && pr < dead_threshold {
        let deadness = (dead_threshold - pr) / dead_threshold; // (0,1)
        score += 30.0 + 90.0 * deadness;
    }

    // ---- Lookahead coupling ----
    // If the next item cannot use this leftover, the gap is likely dead weight.
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size {
        score += 20.0 + 0.5 * (next_item_size as f64 - pr);
    }

    // ---- Last-chance pressure ----
    // If this is the only open bin that fits, strongly prefer using it over
    // opening a new bin (scaled up as the stream progresses / consolidation matters more).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (0.7 + 0.6 * progress);
    }

    // ---- open_bins_count pressure on the new-bin candidate ----
    if bin_residual == bin_capacity {
        // Proliferating bins is costly when many are already open.
        score += 8.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is cheap and keeps future options flexible.
        if open_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // ---- Consolidation nudge ----
    // Favor bins already tighter than the fleet average (closer to closure).
    score += 0.05 * (pr - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tightness * tightness);

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // host the next item exactly or nearly exactly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chaining: post_residual == next_item_size is ideal.
            score -= 10.0 * (1.0 - slack / 100.0);
        } else {
            // Next item won't chain here; penalize wasted lookahead space.
            score += 6.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    } else {
        // Last item: only tightness matters.
        score += 5.0 * tightness;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    // (consume the fullest bins first), punish bins looser than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // penalize it so it only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Scale penalty with stream position: early on prefer reusing bins,
        // later allow opening new bins more readily (keeps open-bin count low).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 6.0 * progress;
        // If next item is large, opening a fresh bin is less attractive.
        if next_item_size >= 60 {
            score += 5.0;
        }
        // If many open bins already, opening a new one is fine.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Small penalty for very large items in nearly-full bins is already
    // captured via tightness; add mild regularization on item size coupling:
    score += 0.02 * (item_size as f64) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powf(3.0);

    // Penalize leaving dead space that likely cannot be reused by the next item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let next = next_item_size as f64;
        if next > gap {
            // Next item cannot fit in this leftover: dead space penalty grows with gap.
            score += 8.0 * (gap / bin_capacity as f64);
        } else {
            // Next item fits: reward reserving usable space.
            score -= 6.0 * (1.0 - (gap - next) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or many bins are open.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let open_pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
        let phase = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 40.0
            - 25.0 * poor_fits
            - 15.0 * open_pressure
            - 10.0 * (1.0 - phase);
        score += penalty.max(2.0);
    }

    // Mild global pressure: when mean residual is low, prefer consolidating into existing bins.
    score += 0.05 * mean_residual;

    // Slight time-decay: later in the stream, favor tighter packing even more.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += poly * cap * 0.35;

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (progress * 6.0 + 1.0);

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dead = post - mean_residual.max(0.0);
    score += 0.08 * dead * dead / cap;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: reward leaving space close to the next item size (smooth Gaussian-like term).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let d = (post - n) / cap;
        score -= 6.0 * (-20.0 * d * d);
    } else {
        // Last item: pure tightness preference.
        score -= 4.0 * (1.0 - norm_post);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class: post_residual bucketed by integer division.
        let class = post_residual / 10;
        // Small classes (<10 residual) are near-dead space: penalize gently,
        // but a tiny leftover can absorb a small next item.
        score += (class as f64) * 0.5 - 3.0;

        // Modulo arithmetic on post_residual vs next item: if the next item
        // divides the leftover into a small remainder, reward heavily.
        if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 200.0; // next item exactly fills this bin later
            } else if rem < 5 {
                score -= 30.0;
            }
            // Next item fits tightly: bonus scaled by fit quality
            let tight = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + tight);
        } else if next_item_size > 0 {
            // Next item cannot use leftover: leftover is likely dead space
            score += (next_item_size as f64) * 0.3;
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Penalize bins whose residual deviates far from mean (fragmentation).
        let dev = bin_residual as f64 - mean_residual;
        score += dev.abs() * 0.2;

        // Fraction-of-capacity thresholds: residual in (0, 20] is awkward.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac > 0.0 && frac <= 0.2 {
            score += 15.0;
        }
        // Sweet spot: residual in [30, 60] can host mid-size items.
        if frac >= 0.3 && frac <= 0.6 {
            score -= 10.0;
        }
    }

    // Early stream: prefer consolidating into few bins; late stream: be greedy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Many open bins: encourage filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open bins pressure: more open bins -> favor existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize so it is only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Last chance bin: if this is the only fitting bin, prefer it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference for bins tighter than the mean residual (better fill).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead. Reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - next).abs();
        if pr >= next {
            // Next item fits here afterwards: reward tight chaining.
            score -= 30.0 * (1.0 - gap / 100.0);
            if gap < 1.0 {
                score -= 20.0; // perfect chain
            }
        } else {
            // Next item cannot follow here: penalize leaving a gap that
            // is dead space for the lookahead item.
            score += 0.5 * gap;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful fit).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post residual) generally.
    score -= 0.2 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., current item barely fits anywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is large and few bins fit it.
        score += 40.0 * (1.0 - tightness);
        score -= 10.0 * (1.0 - progress);
        // If next item chains perfectly with this placement in a fresh bin, discourage.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            let chain_gap = post_residual as f64 - next_item_size as f64;
            if chain_gap < 5.0 {
                score += 25.0;
            }
        }
    }

    // Mild penalty for proliferating bins when item is small.
    score += 0.05 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never hold the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect chain fit: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.25 * (item_size as f64);
    }

    // Penalize bins whose residual is far from the mean (fragmentation pressure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, consolidate into open bins; early, allow new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early or when mean residual is already large,
        // otherwise discourage opening new bins.
        score += 20.0 * progress + 0.3 * mean_residual - 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can host the next big item too
        }
    } else {
        // Existing bin: late stream strongly favors reuse.
        score -= 10.0 * progress;
    }

    // Slight preference for fuller bins (smaller residual) as open-bin count grows.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, with non-linear (quadratic) penalty on wasted space
    let mut score = post + 30.0 * norm_post * norm_post * cap;

    // Smooth coupling of wasted space with stream progress:
    // later in the stream, dead space becomes more costly
    score += 40.0 * norm_post * progress * progress;

    // Reward bins that can also fit the lookahead item (chaining), smoothly scaled
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - post / (cap + 1.0)) * (0.5 + 0.5 * progress);
    }

    // Penalize last-chance bins slightly less when post-residual is small
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Encourage opening new bins early when current bin would leave awkward gap
    let awkward = (norm_post - 0.5 * (1.0 - progress)).abs();
    score += 10.0 * awkward * awkward;

    // New-bin candidate bias: prefer reusing bins unless new bin is clearly better long-term
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, or small enough to be near-full) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr <= 10 {
        score -= 25.0; // dead space minimal
    } else {
        // residue class penalty: leftovers not divisible by 10 waste space
        let class = pr % 10;
        score += class as f64 * 1.5;
        // mid-range leftovers (20..60) are the classic "dead zone"
        if pr > 20 && pr < 60 {
            score += (pr as f64 - 20.0) * 0.8;
        }
    }

    // Capacity fraction coupling: favor bins that become >70% full after placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (fill_frac * fill_frac) * 30.0;

    // Lookahead harmonic: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits but leaves a residue; penalize bad harmonic match
            let nxt_res = pr - next_item_size;
            score += (nxt_res % 10) as f64 * 0.7;
            if nxt_res > 15 && nxt_res < 45 { score += 8.0; }
            score -= 10.0;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr as f64 / 10.0) * 1.2;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let base = 55.0
            - (open_bins_count as f64).ln().max(0.0) * 5.0
            + mean_residual * 0.35;
        score += base.max(0.0);
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the smallest useful
    // item size are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize "unusable" small gaps more aggressively: anything that cannot
    // plausibly hold a future item is dead space. Estimate typical future item
    // size as a fraction of capacity; gaps below half of that are suspect.
    let typical = (bin_capacity as f64) * 0.25;
    if (post_residual as f64) < typical && post_residual > 0 {
        score += (typical - post_residual as f64) * 3.0;
    }

    // Reward tight fits (perfect fills are ideal).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Tightness bonus: smaller post_residual relative to item size is better.
        let tightness = post_residual as f64 / (item_size.max(1) as f64);
        score -= 20.0 / (1.0 + tightness);
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and favor consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 30.0 + (open_bins_count as f64) * 5.0;
        // Late in the stream, new bins are even less desirable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Existing bin: reward using it, especially when bin count is high.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Leftover that next item can't use: mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., closer to full) to keep the mean residual low and bins tight.
    score += ((mean_residual - post_residual as f64).max(0.0)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) — already the base term.

    // 2-step lookahead: reward bins whose post_residual exactly matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + diff);
        // Perfect chaining bonus: next item fills this bin exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space smaller than the smallest possible item (1..100 unknown,
        // but avoid stranding tiny slivers relative to mean residual)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
            score += 8.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate waste)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are poor;
    // scale penalty down late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 6.0 * (1.0 - 0.5 * progress);
        // If next item would also fit in a fresh bin chain, opening is more attractive
        if next_item_size > 0 && next_item_size <= bin_capacity {
            penalty -= 2.0;
        }
        score += penalty;
    }

    // Mild reward for reducing open-bin count pressure
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify with ratio.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot plausibly fit future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 14.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins with smaller residual (best-fit flavor).
        score += 0.35 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, consolidate tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let spread = mean_residual - post_residual as f64;
    score += 0.25 * spread * (open_bins_count as f64).ln().max(0.0);

    // Brand-new bin candidate: only attractive when it enables a near-perfect
    // split with the lookahead item, or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && (bin_capacity as f64 - pair).abs() <= 5.0 {
            score -= 45.0;
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (exact fit).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress)
        - 6.0 * (norm_pr * (1.0 - norm_pr)).sqrt() * (1.0 + progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 5.0 + 10.0 * progress * (nx - pr) / cap;
        } else {
            score -= 2.0 * (1.0 - ((pr - nx) / cap).abs());
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for fragmenting many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Mean-residual alignment term
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead-space classes".
    // Small nonzero residues are nearly unusable (items are >=1 but typical sizes larger);
    // reward exact fits and post-residuals in highly reusable classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class = pr % 10;
        // Dead-space penalty for tiny unusable remainders
        if class == 1 || class == 2 {
            score += 18.0;
        }
        // Highly reusable classes (multiples of 10, 25-ish chunks)
        if class == 0 {
            score -= 12.0;
        }
        if pr % 25 == 0 {
            score -= 10.0;
        }
        // Small absolute residual is dead space
        if pr < 10 {
            score += 25.0;
        } else if pr <= 20 {
            score += 8.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: strong reward, scaled by how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 20.0 - snug * 0.15;
            // harmonic bonus if next item exactly fills
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // next item would not fit here: mild penalty proportional to overshoot
            let over = (next_item_size - pr) as f64;
            score += over * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // harmonic-friendly future (large item arriving, few open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        // If next item is large and current bin would be nearly emptied, new bin ok
        if next_item_size > 60 && item_size > 60 {
            new_bin_penalty -= 20.0;
        }
        // Few open bins: opening is cheaper
        if open_bins_count <= 2 {
            new_bin_penalty -= 15.0;
        }
        // Late in stream: avoid spreading residue
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Prefer tighter bins overall: reward when bin residual is much below mean
    let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score -= tightness * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32; // items can be as small as 1, but treat tiny gaps relative to next item
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        // gap cannot host the next item -> dead space penalty, stronger for smaller gaps
        let deadness = (next_item_size - post_residual) as f64;
        score += 12.0 + deadness * 0.35;
    }
    if post_residual > 0 && post_residual < min_item {
        score += 50.0; // exact-full bonus handled below; unreachable normally
    }
    if post_residual == 0 {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Penalize bins whose residual is far above mean (wasteful large-bin usage)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Open-bins pressure: with many open bins, prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.25 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.6;
    } else {
        // New-bin candidate: only attractive when no good fits exist.
        // Penalize new bins when decent fitting bins exist; reward when it's a last chance.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        } else {
            score += 10.0 + pressure;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 10.0 - slack * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward a bin whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64;
            score -= 40.0 + 25.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize dead space proportionally.
            score += 15.0 + 0.5 * (next_item_size as f64);
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with below-average residual (fill tighter bins first),
    // but soften when many bins are open.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Mild preference for tighter fits relative to capacity.
    score += 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64);

    // Slight preference for reusing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1) could be wasted on:
    // very small post residuals are actually GOOD (near-perfect fill).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // excellent fill, strongly prefer
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when the item is large relative to capacity
        // or the current bin would leave an awkward residual.
        let awkward = (post_residual as f64) > 0.0 && (post_residual as f64) < (item_size as f64) * 0.5;
        // Penalize new bin mildly by default; reward when current fits are bad.
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            // new bin could also host the next item: slight bonus
            score -= 6.0;
        }
        if awkward {
            score -= 4.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward using existing bins when they fit well.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fit_ratio > 0.8 {
            score -= 10.0;
        }
        // Lookahead synergy: if next item fits the post residual, big bonus.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 14.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            // next item won't fit here; slight penalty for blocking
            score += 3.0;
        }
        // Prefer bins with below-average residual (consolidate fullness).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 8.0 * dev;
    }

    // Global pressure: many open bins -> favor filling existing ones harder.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 2.0 * pressure;
    } else {
        score += 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // smooth non-linear coupling: dead-space penalty grows quadratically with progress
    score += 60.0 * progress * norm_pr * norm_pr;

    // tight fits rewarded, scaled by progress
    score -= 40.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 25.0 * (1.0 - progress) * (nx / cap);
        } else {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // penalty for spreading across many bins
    score += 2.0 * (open_bins_count as f64).ln();

    // mean residual divergence penalty
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // new-bin candidate: mild bias so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items of size 10..80 make residuals
    // in small classes most valuable (they can be filled by tiny future items).
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Class A: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: very small residual (1..=10) -> near-perfect, strong reward.
    else if pr <= 10 {
        score -= 500.0 - pr as f64 * 10.0;
    }
    // Class C: residual divisible by 5 (common item granularity) -> moderate reward.
    else if pr % 5 == 0 {
        score -= 100.0;
        // Extra reward if next item could exactly fill it.
        if next_item_size > 0 && (next_item_size as i64) == pr {
            score -= 300.0;
        }
    }
    // Class D: residual divisible by 10 -> mild reward.
    else if pr % 10 == 0 {
        score -= 60.0;
    }

    // Penalize dead space proportional to how unusable it is:
    // residual that no plausible item (1..=100) can use is impossible, but
    // residual smaller than the smallest plausible chunk is wasted.
    if pr > 0 && pr < 10 {
        score += 40.0; // awkward sliver
    }

    // Coupling with next item lookahead (k=2):
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 400.0; // next item exactly fills this bin
        } else if ni <= pr {
            // next item fits here: reward proportionally to tightness
            score -= 200.0 * (ni as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here: mild penalty for splitting stream
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 350.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that scales with
    // how many open bins already exist (encourage consolidation when many bins).
    if bin_residual == bin_capacity {
        score = cap * 0.5 + (open_bins_count as f64) * 15.0;
        // If nothing fits anywhere else, new bin must win.
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        // Late in the stream, prefer reusing bins over opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 50.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin; favor tightening it further (best-fit behavior).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 2.0;
    } else {
        score += (-diff) * 1.0;
    }

    // Integer-division threshold on post_residual: buckets of 20.
    let bucket = pr / 20;
    score += bucket as f64 * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize small unusable dead-space gaps (1..=10) heavily;
    // gap 11..=20 is semi-usable, mild penalty.
    let gap = post_residual as f64;
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 3.0 * gap; // small gaps are near-wasted space
    } else if post_residual > 10 && post_residual <= 20 {
        score += 10.0 - 0.2 * gap;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins;
    // the empty-bin candidate has residual == capacity, penalize it more
    // as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post residual too small for next item: if also small gap, extra penalty
        if post_residual <= 10 {
            score += 20.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight stream progression bias: later in stream, be more conservative
    // about leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: next item fills this bin perfectly afterwards
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item can still fit after this placement: gentle reward proportional to closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize wasted space relative to what next item needs
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small dead space that nothing (min size 1, typically >=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make it attractive only when it enables a good
    // two-item chain (item + next item both fit), otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Fresh bin can host current + next item: competitive option
            score -= 5.0;
        } else {
            // Opening a new bin for a single item wastes capacity: penalize
            score += 25.0;
        }
        // Late in the stream, avoid spawning bins that will end mostly empty
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins that are already quite full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - chain_fit / bin_capacity as f64);
    }
    // If next item cannot fit in post-residual but could fit elsewhere, penalize leaving big dead space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when many bins are open with slack (encourage consolidation).
    if bin_residual == bin_capacity {
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual.max(0.0);
        score += 15.0 + avg_slack * 0.5 - horizon * 10.0;
        if avg_slack >= item_size as f64 {
            score += 20.0; // an open bin could already take this item
        }
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, penalize waste quadratically.
    let waste_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += waste_penalty * cap;

    // Smooth cubic term: very small residuals are great (nearly full bins),
    // rewarded more as stream progresses.
    let tight_reward = (1.0 - norm_pr).powi(3) * (10.0 + 30.0 * progress);
    score -= tight_reward;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), scaled smoothly by how well the item fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_frac = item_size as f64 / cap;
        score -= 25.0 + 40.0 * fit_frac * (1.0 - progress);
    }

    // New-bin candidate handling: make empty bin mildly unattractive unless
    // residuals across open bins are poor (high mean residual relative to item).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_bad = (mean_residual - item_size as f64) / cap;
        let pressure = (mean_bad.max(0.0)).powi(2) * 60.0;
        score += 8.0 + 20.0 * progress - pressure - 30.0 * scarcity;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    // smoothly (companion packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let compat = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 5.0 + 15.0 * compat * compat;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving moderately-sized dead space.
        score += (pr / cap) * (1.0 - pr / cap) * 20.0;
    }

    // Mild penalty for spreading across many open bins early (encourage consolidation),
    // smoothly relaxed as stream progresses.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // --- Harmonic class fragmentation penalty ---
    // Within a decade class of post_residual, penalize ragged leftovers
    // (post_residual % 10) so e.g. residual 37 is slightly worse than 40.
    score += (post_residual % 10) as f64 * 0.15;

    // --- Quarter-capacity class bonus (integer division threshold) ---
    // Bins whose leftover falls into a coarser quarter-class are more
    // reusable; reward lower quarter classes mildly.
    let quarter_class = post_residual / (bin_capacity / 4).max(1);
    score -= (quarter_class.min(4)) as f64 * 2.0;

    // --- Perfect fit reward ---
    if post_residual == 0 {
        score -= cap; // close the bin exactly: best possible outcome
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: chain reward,
            // scaled by how much of the next item actually fits.
            score -= (next_item_size as f64) * 0.35;
        } else {
            // Dead space relative to the next item: penalize the gap,
            // capped so tiny leftovers aren't overpunished.
            let gap = (next_item_size as f64 - pr).min(cap * 0.25);
            score += gap * 0.2;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.6;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Default: strongly discourage opening a new bin when existing
        // bins could fit the item.
        score += cap * 0.8;
        // If the item is larger than the mean residual across open bins,
        // existing bins are poor hosts; soften the penalty.
        if (item_size as f64) > mean_residual {
            score -= cap * 0.25;
        }
        // Late in the stream, opening fresh bins is less costly in
        // expectation; soften slightly with progress.
        let prog = step_index as f64 / (total_items.max(1) as f64);
        score -= prog * cap * 0.15;
    }

    // Mild global progress term (uniform across bins, breaks ties toward
    // tighter packing as the stream matures).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fill is strongly rewarded.
        score -= 60.0;
    }

    // Non-linear penalty on residual waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: prefer filling existing bins over proliferating bins.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the remaining gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current
    // residuals are nearly exhausted (item barely fits nowhere else).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 55.0 - 45.0 * pressure;
    }

    // Mean residual coupling: prefer bins tighter than the mean.
    score += 0.4 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact match between post_residual and next_item_size (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Penalize bins whose residual is far below the mean (already tight bins are precious).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Discourage opening a new bin when plenty of fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin is fine if next item is big
        }
    }

    // Mild bonus for tight fits overall.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // If post_residual cannot hold next item but is large-ish, mild penalty
            // for fragmenting space.
            if post_residual > 0 && (post_residual as f64) < 0.5 * (next_item_size as f64) {
                score += 4.0;
            }
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are nearly full overall), otherwise allow spreading.
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (keep residual space flexible); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * tightness - progress * 4.0;

    // New-bin candidate handling: an empty bin gets a baseline that must be
    // beaten by genuinely good fits, but is attractive when no tight fit exists.
    if bin_residual == bin_capacity {
        score = 45.0 + (1.0 - progress) * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Don't open a new bin if next item is large and current bins are empty-ish.
        if next_item_size > 60 && mean_residual > 50.0 {
            score += 15.0;
        }
    }

    // Mild penalty for proliferating bins when existing ones are roomy.
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual, with non-linear emphasis.
    let mut score = post * (1.0 + 0.8 * post / cap) * (1.0 + 0.5 * progress);

    // Reward using bins with residual close to item size (tight fit coupling).
    let tightness = 1.0 - ((bin_residual as f64 - item) / cap).abs();
    score -= 15.0 * tightness * tightness;

    // Penalize leaving dead space that most future items can't use.
    if post > 0.0 {
        let dead = post / cap;
        score += 25.0 * dead * dead * (0.5 + progress);
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-slightly-high unless open bins waste space.
    if bin_residual == bin_capacity {
        let waste_pressure = mean_residual / cap;
        score = 30.0 + post * (1.0 + 0.3 * progress) - 10.0 * waste_pressure * waste_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of the post-fit residual ---
    // Class residual into "harmonic" buckets relative to capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted after placement

    // Dead-space penalty: non-linear, penalize residuals that are too small
    // to ever fit a typical item (1..100) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // tiny unusable slivers
    }

    // Perfect fit bonus (post_residual == 0)
    if post_residual == 0 {
        score -= 120.0;
    }

    // --- Modulo / integer-division thresholds on post_residual ---
    // Harmonic classes: multiples of common item sizes (10..80 step 10).
    let harmonic_hit = post_residual % 10 == 0 && post_residual > 0;
    if harmonic_hit {
        // Residual aligned to a harmonic class is more likely reusable by
        // future items; reward it proportionally.
        score -= 15.0 + (post_residual as f64) * 0.25;
    } else if post_residual > 0 {
        // Off-harmonic residuals: penalize by distance to nearest class.
        let dist = (post_residual % 10) as f64;
        score += dist * 1.5;
    }

    // Integer-division threshold: residuals >= 50 are "half-class" and can
    // host large items; residuals in [10, 50) are "quarter-class".
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual >= 10 {
        score -= 4.0;
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: strong chain bonus.
            score -= 25.0 + (next_item_size as f64) * 0.2;
            // Extra reward if next item exactly fills the remaining space.
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize by overshoot size.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    } else {
        // Last item in stream: minimize waste aggressively.
        score += frac * 30.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin can fit the item; avoid opening a new bin.
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of opening a bin. Attractive early
        // or when mean residual across open bins is small (poor fits).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 35.0 + progress * 25.0;

        // If existing bins are congested (low mean residual), opening a new
        // bin is more competitive.
        new_bin_score -= mean_residual * 0.35;

        // If the item is large and next item is also large, a fresh bin is
        // often better than fragmenting a partially-filled one.
        if item_size >= 50 && next_item_size >= 50 {
            new_bin_score -= 20.0;
        }

        // If many bins can fit, prefer reusing an existing one.
        if fitting_bins_count > 2 {
            new_bin_score += 30.0;
        }

        score = score.min(new_bin_score) * 0.0 + new_bin_score;
    }

    // --- Congestion-aware scaling ---
    // With many open bins, prefer tightening fills (reduce waste).
    if open_bins_count > 4 {
        score += frac * (open_bins_count as f64) * 2.0;
    }

    // Small tie-break toward bins whose residual is close to the item
    // (best-fit refinement) using integer division class.
    let tightness = (bin_residual / item_size.max(1)) as f64;
    score += tightness * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space avoidance: residuals too small for any item (min size 1,
    // but tiny gaps are hard to fill) get a nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium gaps: mild penalty proportional to unusability risk.
        score += 0.5 * (25 - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * progress;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Reward bins whose residual matches the lookahead item (future-friendly).
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        }
        // Prefer bins tighter than average (concentrate fill).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: strongly reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // post_residual can't host next item: penalize dead space, worse if very small
            let dead = post_residual as f64;
            score += dead * (dead / (next_item_size as f64 + 1.0));
        }
    }

    // Compare against mean residual of open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 5.0 * (rel - 1.0).abs();
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it's genuinely needed
    if bin_residual == bin_capacity {
        let mut penalty = 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            penalty += 15.0; // pair could go into one bin elsewhere
        }
        if fitting_bins_count == 0 {
            penalty = 0.0;
        }
        // later in stream: less willing to sprawl
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        penalty += 10.0 * progress;
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let frac_used = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * frac_used * frac_used;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // More fitting bins => this bin is less critical; slight penalty to spread load.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate: penalize opening a new bin unless it produces a great fit
    // or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 18.0;
        // A large item leaving small waste justifies a fresh bin.
        if waste < 10.0 {
            score -= 30.0;
        } else if waste < 20.0 {
            score -= 12.0;
        }
        // Late in the stream, avoid spawning bins that won't be reused.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * t;
        // If many bins are open and residuals are large, opening new bins is wasteful.
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item would fit the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 10.0 * snug;
        } else {
            // Post residual too small for next item: dead space penalty scaled by waste.
            let dead = post_residual as f64;
            score += 0.15 * dead;
        }
    }

    // Prefer bins whose residual is already below the mean (consolidating waste).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.05 * (mean_residual - res);
    } else {
        score += 0.05 * (res - mean_residual);
    }

    // Mild preference for keeping few open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: minimize post residual (tight fit), non-linearly
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 8.0;

    // Smooth polynomial coupling of fit quality with stream progress:
    // early on, prefer flexibility (higher residual OK); late, pack tight aggressively.
    let flexibility = (1.0 - progress) * (1.0 - progress);
    score += flexibility * (norm_pr - 0.5) * (norm_pr - 0.5) * 12.0;
    score -= progress * progress * (1.0 - norm_pr) * 10.0;

    // Reward large fills (small item fraction) with smooth decay
    score -= (1.0 - norm_item) * (1.0 - norm_item) * 5.0;

    // Lookahead: penalize if post residual can't host next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Mild pressure against proliferating bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 1.5;

    // New-bin candidate: keep it slightly unattractive unless residual would be near zero elsewhere
    if bin_residual == bin_capacity {
        score += 3.0 + norm_item * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: residuals that are "usable" divisors
    // of capacity are worth keeping; odd/dead-space residuals are penalized.
    let pr = post_residual;
    if pr > 0 {
        // classify residual into harmonic slots of capacity/4
        let quarter = bin_capacity / 4;
        let slot = pr / quarter.max(1);
        match slot {
            0 => score -= 60.0, // tiny residual: fine if item was large
            1 => score += 25.0, // half-ish leftover: often dead space
            2 => score -= 10.0, // quarter leftover: usually reusable
            _ => score -= 40.0, // large leftover: good
        }
        // modulo arithmetic: residuals divisible by small item classes stay useful
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 5 == 0 && pr % 10 != 0 { score += 8.0; }
        if pr < 10 { score += 30.0; } // sub-minimum dead space
    }

    // Lookahead: can the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 45.0;
            // exact harmonic match between next item and post residual
            if pr == next_item_size { score -= 80.0; }
            if pr % next_item_size == 0 { score -= 20.0; }
        } else {
            score += (next_item_size - pr) as f64 * 0.5;
        }
    } else {
        // last item: prefer any bin, avoid opening new bins
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // base penalty so a decent existing fit wins
        score += 150.0;
        // large items (integer-division threshold at capacity/2) pair well with fresh bins
        if item_size > bin_capacity / 2 { score -= 90.0; }
        // late in the stream, opening new bins is less costly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
        // if many bins are open and mean residual is large, prefer consolidation
        if mean_residual > cap_f * 0.4 && open_bins_count > 3 { score += 60.0; }
    }

    // Slight preference for fuller bins overall (waste-aware tiebreak)
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Density coupling: reward placing into bins whose residual is close to item size
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += gap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // possible future item (size 1) are never truly "dead", but gaps below the
    // typical item scale are hard to reuse. Penalize unusable small gaps hard.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if the leftover gap cannot fit the next item while the next item
    // would otherwise need a new bin soon.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones and
    // consolidate into existing residual mass.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // Prefer bins whose residual is below the mean (tighter packs) when many
    // bins are open; prefer looser bins when few are open.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * (if open_bins_count > 4 { 0.5 } else { -0.3 });

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64) < 0.25;
        if crowded && fitting_bins_count >= 1 {
            score += 40.0; // discourage new bin when open bins are roomy
        } else {
            score -= 10.0; // mild encouragement to open fresh bin otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact match with next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly usable next step
        } else if (post_residual as i64) >= (next_item_size as i64) {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // leftover smaller than next item: dead space penalty scaled by gap
            score += 10.0 + 0.5 * gap;
        }
    } else {
        // Last item: just minimize waste directly
        score -= 5.0;
    }

    // Reward tight fits relative to current residual (small waste now).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize bins far below mean residual (avoid scattering small leftovers),
    // unless this is the only fitting bin (last-chance bonus).
    if (bin_residual as f64) > mean_residual + 1.0 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it expensive unless item is large or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item_bonus = if item_size >= 60 { 40.0 } else { 0.0 };
        score += 55.0 - 30.0 * progress - big_item_bonus
            + 0.2 * open_bins_count as f64;
    }

    // Mild pressure to reuse bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize leaving large dead space: post_residual unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // perfect-ish fill
    } else if post_residual >= 10 && post_residual < 50 {
        score += 3.0; // moderate dead space
    } else if post_residual >= 50 {
        score += 12.0; // large leftover, likely wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_future = 55.0; // rough expected item size for unknown distribution
        let usable_left = bin_capacity as f64 - item_size as f64;
        // Opening a new bin is good if it leaves space usable by the next item
        // and existing bins fit poorly (many open bins with slack).
        let next_fits_new = next_item_size as f64 <= usable_left;
        let mut new_bin_penalty = 25.0;
        if next_item_size > 0 && next_fits_new {
            new_bin_penalty -= 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > usable_left {
            new_bin_penalty += 15.0;
        }
        // Early in the stream, new bins are cheap; late, prefer consolidation.
        new_bin_penalty += 20.0 * progress;
        // Many open bins with slack: avoid adding another.
        if mean_residual > 30.0 && open_bins_count > 2 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if this placement leaves room exactly (or nearly) matching the
    // next item, reward it; if it strands the next item, penalize.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            let slack_gap = post_residual as f64 - nr;
            if slack_gap < 10.0 {
                score -= 12.0; // leaves a slot for the next item
            } else {
                score -= 4.0 * (1.0 - slack_gap / bin_capacity as f64);
            }
        } else {
            score += 6.0; // next item won't fit here; bin will be dead after this
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly; and prefer using bins with less residual overall (fill fullest first).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Mild pressure to use open bins as their count grows.
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p = progress;
    let poly = 1.0 + 0.8 * p - 0.6 * p * p + 0.4 * p * p * p;
    score *= poly;

    // Penalize large dead space more than linearly (quadratic waste term).
    let waste = post / cap;
    score += 12.0 * waste * waste * cap * 0.01;

    // Reward tight fits (small post_residual) increasingly.
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tight * tight;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    score += 0.05 * ((post - mean_residual) / cap);

    // Mild penalty for spreading across many open bins early in the stream.
    score += 0.3 * (open_bins_count as f64) * (1.0 - p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Leftovers in "awkward" bands (just above a
    // typical item size) are dead space; penalize them.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -50.0 // perfect fit, strongly reward
    } else if pr <= 10 {
        -20.0 // tiny leftover, nearly perfect
    } else if pr <= 25 {
        0.0 // usable band
    } else if pr <= 34 {
        15.0 // awkward: too small for many items
    } else if pr <= 50 {
        0.0
    } else if pr <= 67 {
        10.0
    } else {
        25.0 // large leftover means we wasted a big gap
    };
    score += class;

    // Integer-division threshold on post_residual: multiples of common
    // item sizes (10/20/25) are re-usable; reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // this is a harmonic chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chain matters
            let chain_left = pr - next_item_size;
            score -= 10.0 - (chain_left as f64) * 0.15;
        } else {
            // next item won't fit here; penalize less if post_residual
            // is small anyway (bin is nearly full)
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // New-bin candidate handling: fresh bin should only win when current
    // fit is poor (large post_residual) or late in the stream is not relevant;
    // make empty bin moderately attractive only for small items.
    if bin_residual == bin_capacity {
        // empty bin: base score is its full residual; tilt by item size
        score = post_residual as f64 - (item_size as f64) * 0.35;
        if item_size >= 50 {
            score += 10.0; // big items prefer existing bins with room
        }
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 6.0;
        }
    }

    // Progress-aware tie-breaking: early in the stream, keep bins tight;
    // late in the stream, filling existing bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / cap);

    // Prefer bins tighter than the mean residual (compactness).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect 2-step fit: chain placement
        } else if post_residual >= next_item_size {
            // post-residual can host next item: reward closeness of the leftover-after-next
            let after_next = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - after_next / bin_capacity as f64);
            // penalize large dead space after chaining next item
            if after_next < 10.0 {
                score += 15.0 * (10.0 - after_next);
            }
        } else {
            // next item won't fit here: penalize proportionally to the miss
            let miss = nxt - post_residual as f64;
            score += 0.8 * miss;
        }
    } else {
        // last item: minimize residual directly (already the base score)
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect closure reward
    if post_residual == 0 {
        score -= 35.0;
    }

    // Late in the stream, consolidate: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    // Mild pressure to keep number of open bins low
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let cap = bin_capacity as f64;
    let waste_frac = post_residual as f64 / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64 - ni).abs() < 1.0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild bonus proportional to how snugly.
            score -= 10.0 * (1.0 - (post_residual as f64 - ni) / cap);
        } else {
            // Next item cannot fit here: penalize leaving a gap smaller than next item (dead space).
            if post_residual < next_item_size {
                score += 8.0 * (1.0 - post_residual as f64 / ni);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when the item is large
    // relative to remaining residuals, or when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: moderate, so poor fits elsewhere beat it.
        score += 15.0;
        // Large items are better placed fresh.
        score -= (item_size as f64 / 100.0) * 20.0;
        // If mean residual across open bins is small, opening fresh is sensible.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Late in the stream, discourage scattering across many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Many open bins: prefer consolidation into existing bins.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild preference for fuller bins (larger item_size relative to residual gap).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fit_ratio;

    // Penalize bins whose residual deviates strongly from the mean (keeps bin states homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;

    // Base: penalize leftover space, modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of normalized post_residual with progress.
    let t = norm_pr;
    score += 40.0 * (t * t) * (0.5 + progress);
    score -= 25.0 * (t * t * t) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 15.0 * (1.0 - t) * (1.0 - t) * progress;

    // Penalize dead space too small for typical items (near-zero residual is fine).
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins early.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Mean-residual coupling: prefer bins deviating below mean (consolidate small leftovers).
    score += 0.5 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space penalty grows when the leftover
    // falls into a "hard to fill" residue class (small odd remainders).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Modulo-10 class penalty: leftovers in [1..10] are nearly dead space.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,                 // perfectly divisible leftover -> easy refills
        1..=9 => 4.0 + (9 - class) as f64 * 0.8, // smaller leftover = harder to reuse
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: leftover that cannot hold the next item is dead
    // unless it is exactly zero.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 12.0; // perfect fit: reward strongly
        } else if post_residual < next_item_size {
            // dead leftover for the lookahead; penalize proportionally to how
            // much capacity is wasted, scaled by how many bins can still fit.
            let waste = pr / cap;
            score += waste * 14.0;
            if fitting_bins_count == 1 {
                // last chance bin: better to use it than open a new bin
                score -= 10.0;
            }
        } else {
            // leftover can host the next item: reward pairings, especially
            // when leftover + next_item_size forms a near-perfect fit chain.
            let chain = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain / cap);
        }
    } else {
        // last item: any bin that fits is fine; prefer exact fill
        score -= 5.0 * (1.0 - frac);
    }

    // Harmonic capacity-fraction coupling: reward bins whose residual is a nice
    // fraction of capacity (e.g. 1/2, 1/4, 3/4) since they pair well.
    let harmonic = (frac * 4.0).round() / 4.0;
    score -= 3.0 * (1.0 - (frac - harmonic).abs() * 4.0);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the stream is early,
        // open bins are plentiful, and the item is large (poor fit anywhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64 / cap) > 0.5;
        let mut new_bin_bias = 6.0 + open_bins_count as f64 * 0.15;
        if large_item {
            new_bin_bias += 4.0;
        }
        if fitting_bins_count <= 1 {
            // keep using the last available bin rather than opening a new one
            new_bin_bias += 25.0;
        }
        if progress > 0.85 {
            new_bin_bias += 10.0; // late in stream: consolidate
        }
        score += new_bin_bias;
    }

    // Slight preference for tighter bins among equals (small residual = fuller bin)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small gaps are only usable by tiny items; mild penalty.
        score += 8.0;
    } else {
        // Larger usable residuals are valuable: reward keeping them.
        score -= (post_residual as f64 - 20.0) * 0.25;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        // Next item won't fit here; dead space likely. Penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bins pressure: when many bins are open, discourage spreading
    // into more residual; encourage tight packing to allow bin closure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin wastes capacity. Only attractive
    // if the item would leave a very poor residual in every existing bin.
    if bin_residual == bin_capacity {
        let base = 45.0 + open_bins_count as f64 * 2.0;
        // If existing fit is terrible (dead space), new bin becomes viable.
        if post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size) {
            // score here reflects the hypothetical existing-bin placement;
            // the new-bin call itself has post_residual = capacity - item.
            // We offset so new bin wins only against bad fits.
            score -= 0.0;
        }
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space, quadratic in post_residual.
    score += 0.02 * (post_residual as f64).powi(2);

    // 2-step lookahead: reward perfect chaining where next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item fills the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill_ratio;
        } else {
            // next item cannot use the residual: penalize wasted space
            score += 25.0;
        }
    }

    // Compare residual against mean residual across open bins: prefer tighter bins.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Progression: as stream advances, prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress;

    // New-bin candidate handling: mildly penalize opening a new bin unless it's a great fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (bin_capacity as u64 - next_item_size as u64) >= item_size as u64 {
            score -= 10.0; // new bin supports a chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't chain here; mildly penalize unless residual is near zero.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: discourage opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if open bins are all poorly filled and stream is early, allow new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 || (progress < 0.3 && mean_residual < item_size as f64) {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, be more conservative: keep small residuals usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Tight-fit reward: smooth coupling of fit quality with stream progress
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Dead-space penalty for residuals too small to matter, growing with progress
    if post_residual > 0 {
        let unusable = (1.0 - pr / cap).powi(3);
        score += 8.0 * unusable * (0.3 + 0.7 * progress);
    }

    // Perfect fit bonus (non-linear, strong)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = 1.0 - ((pr - nx) / cap);
            score -= 6.0 * slack * slack;
        } else {
            // penalize wasting residual if next item won't fit
            score += 4.0 * (nx / cap);
        }
    }

    // Prefer filling bins with large residual relative to mean (balance-aware)
    let res_norm = bin_residual as f64 / cap;
    let mean_norm = mean_residual / cap;
    score -= 3.0 * (res_norm - mean_norm) * (res_norm - mean_norm).abs();

    // Mild penalty on proliferating many open bins early
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: neutral baseline, slightly discouraged unless nothing fits well
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (or leave room for
    // typical small items) are valuable; tiny awkward residuals are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals divisible by small harmonic units (5, 10, 20, 25, 50).
    let mut harmonic_bonus = 0.0;
    for unit in [5u32, 10, 20, 25, 50] {
        if post_residual >= unit && post_residual % unit == 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward dead space: residual in (0, 10) is nearly unusable
    // since items are >= 1 but small residuals waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Tight fit band: leaving very little but nonzero space is still good.
    if post_residual > 0 && post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this bin chains perfectly — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to how much would remain
            let next_post = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - next_post / cap);
        } else {
            // next item cannot fit here; if residual is tiny, this bin is done
            // anyway — mildly fine. If residual is large but unusable, penalize.
            if post_residual > next_item_size * 2 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its natural score is high (post_residual = capacity - item), which
    // discourages opening new bins by default. But if all open bins fit
    // poorly (large post residual wasted), opening a fresh bin can be better.
    if bin_residual == bin_capacity {
        // Base new-bin score: keep it competitive but slightly conservative.
        score = (bin_capacity - item_size) as f64 + 15.0;

        // If the stream is early or many bins are open and mean residual is
        // high (open bins are fragmented), opening a new bin is attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 0.55 * cap && open_bins_count > 2 {
            score -= 30.0 * (mean_residual / cap);
        }
        // Large items early: better to give them a fresh bin.
        if item_size > 60 && progress < 0.5 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        if progress > 0.8 {
            score += 20.0 * progress;
        }
    } else {
        // Existing bin: mild preference when mean residual indicates the
        // fleet is fragmented — consolidate into bins with below-mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Modular threshold on post_residual: residuals in [10, 30] leave room
    // for a mid-size item; reward. Residuals in (30, 50) are semi-awkward.
    let q = post_residual / 10;
    match q {
        0 => { if post_residual > 0 { score += 10.0; } }        // tiny dead space
        1 | 2 => score -= 15.0,                                  // usable for small/mid items
        3 | 4 => score += 5.0,                                   // semi-awkward middle
        _ => {}                                                  // large residual: neutral
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps that cannot fit a typical item
    if post_residual > 0 && post_residual < item_size {
        score += 25.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Reward tight fits (exact or near-exact)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from many open bins: prefer filling existing bins over opening new ones
    let open_pressure = open_bins_count as f64 * 3.0;
    if bin_residual == bin_capacity {
        score += open_pressure + 20.0;
    } else {
        score -= open_pressure * 0.1;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: avoid bins far from the mean (keeps a spread of sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in stream: be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), normalized by capacity.
    score = post_residual as f64 / bin_capacity as f64 * 100.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // accommodate the next item exactly or near-exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward perfect chain: post_residual == next_item_size leaves 0 slack.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus for exact match.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted residual.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are valuable;
    // prefer placing into them only if the fit is good.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are quite full (high mean utilization) or nothing fits well.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Opening a new bin is attractive only when open bins are mostly full.
        score += 40.0 * (1.0 - mean_fill);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        }
        // Early in stream, new bins are cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for very small dead space that can never be reused
    // (post_residual < 10 assumed unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead space: post_residual too small for any plausible future item (min size 1..100 unknown,
    // but small leftovers are hard to fill) — penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here anyway; slightly favor keeping larger residuals
            // for the next item if this bin would be left with a useless remainder.
            score += 5.0;
        }
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize more when open bins are underutilized
        // or late in the stream (consolidation matters more as stream ends).
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to item_size + next_item_size.
    if next_item_size > 0 {
        let combo = item_size + next_item_size;
        if combo <= bin_residual {
            let gap = (bin_residual - combo) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Prefer filling bins that are already heavily used (fewer partially-filled bins left).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * 0.5;
    score += 8.0 * poly;

    // Penalize large dead space more as stream advances (less time to reuse it)
    score += 6.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, especially when this is the only fitting bin
    let tight = 1.0 - norm_pr;
    score -= 5.0 * tight * tight * if fitting_bins_count == 1 { 1.5 } else { 1.0 };

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let slack_after_next = (pr - next_item_size as f64) / cap;
        score -= 4.0 * fits_next * (1.0 - slack_after_next) * (1.0 - progress * 0.5);
    }

    // Mild bonus for using crowded bins vs. opening new ones
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space severity by residue class
    let pr = post_residual as i64;
    if pr > 0 {
        let class = pr % 10;
        // residues that are hard to fill (prime-ish / odd gaps) get penalized
        let penalty = match class {
            1 => 12.0, 3 => 9.0, 7 => 7.0, 9 => 5.0,
            5 => 8.0, 2 => 2.0, 4 => 1.0, 6 => 0.5, 8 => 0.2,
            _ => 0.0,
        };
        score += penalty;
        // very small dead space is fine (near-perfect fit)
        if pr <= 3 { score -= 25.0; }
        else if pr <= 10 { score -= 10.0; }
        // medium dead space (11..30) is worst: hard to reuse
        else if pr <= 30 { score += 15.0; }
        // large residual is reusable if future items may fit
        else {
            let next_fits = next_item_size > 0 && (next_item_size as u32) <= post_residual;
            if next_fits { score -= 8.0; } else { score += 6.0; }
        }
    } else {
        // perfect fill
        score -= 40.0;
    }

    // Lookahead coupling: does the next item slot into the post residual?
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // chain fill
        } else if gap > 0 && gap <= 5 {
            score -= 18.0;
        } else if gap < 0 {
            // next item won't fit here: residual becomes dead unless large
            score += (gap.abs() as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // opening new bin penalized mildly; less so early in stream
        score += 5.0 + 10.0 * progress - 0.5 * crowded;
        if fitting_bins_count == 0 { score -= 15.0; }
        // prefer new bin if current best residual would be badly fragmented
        if post_residual > 0 && post_residual < 20 { score -= 5.0; }
    }

    // Slight preference for tighter (fuller) bins overall
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Mean-residual context: if this bin is much emptier than average, deprioritize
    let dev = mean_residual - post_residual as f64;
    score += dev.max(0.0) * 0.15 - dev.min(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving residual that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residual that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty if this bin is much emptier than average (prefer filling emptier bins first).
    let residual = bin_residual as f64;
    if residual > mean_residual + 5.0 {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when current item would leave bad dead space
    // in existing bins; otherwise keep it slightly worse than a good fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving enough room for the next item, scaled by tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    } else {
        // Next item won't fit: penalize dead space creation
        score += 10.0;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    score -= (mean_residual - post_residual as f64).clamp(-20.0, 20.0) * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current item is huge
    // relative to typical residuals (better to open fresh bin for big items)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 55.0 - 20.0 * progress;
        if item_size as f64 > mean_residual + 15.0 {
            score -= new_bin_penalty * 0.5;
        } else {
            score += new_bin_penalty;
        }
    }

    // Prefer filling fuller bins (tighter fits) with a mild non-linear term
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead: prefer bins whose post-residual cannot fit the next item
    // only if this bin is a "last chance"; otherwise prefer leaving room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // can still host the next item
        } else if fitting_bins_count == 1 {
            score -= 15.0; // last chance bin: place here rather than open new bin
        } else {
            score += 6.0; // creates dead space relative to lookahead
        }
        // Exact pair completion is excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance urgency: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless no good open bin exists.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening bins is cheaper (fewer future items to strand).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
        // If the item is huge relative to mean residual, new bin may be right.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 30.0;
        }
    }

    // Global state: many open bins with large mean residual -> encourage consolidation.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 0.15 * (mean_residual - 30.0);
    }

    // Mild time-horizon scaling: early on, keep bins flexible (favor larger post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-fit slack
    let slack = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize slack quadratically as stream progresses,
    // so late in the stream we strongly prefer tight fits (small dead space).
    let w = 0.5 + 3.0 * progress * progress;
    score += w * slack * slack * bin_capacity as f64;

    // Reward near-perfect fits (smooth kernel around slack ~ 0)
    score -= (1.0 - slack).powi(4) * 12.0;

    // Lookahead coupling: reward bins whose post-residual can host the next item,
    // with a smooth interaction between slack and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 * (1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64)).powi(2);
        } else {
            // post-residual dead relative to lookahead: penalize proportionally
            score += 4.0 * (nxt - post_residual as f64) / bin_capacity as f64 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // especially early/mid stream when bins are expensive to create.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    // Mild dispersion penalty: bins far from mean residual are less attractive.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev * bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Harmonic penalty: residual classes near half/quarter capacities are
    // "usable" slots; tiny residuals are dead space, large residuals are fine.
    let harmonic = (frac * std::f64::consts::PI).sin().abs(); // peaks at frac=0.5
    score += (1.0 - harmonic) * 12.0;

    // Modulo classes on post_residual: multiples of 10 and 25 are harmonically
    // compatible with typical item sizes (10..80 range).
    let pr = post_residual;
    if pr % 10 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 4.0; }
    if pr % 50 == 0 { score -= 5.0; }
    // Odd/awkward small dead space
    if pr < 10 && pr > 0 { score += 15.0; }

    // Perfect fit is ideal
    if post_residual == 0 { score -= 30.0; }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but residual after that matters
            let pr2 = post_residual - next_item_size;
            score += (pr2 as f64) * 0.3;
            if pr2 % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here: leaving large residual is wasted
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 10.0 + 0.5 * (open_bins_count as f64);
        // If current item fits very well somewhere, don't open a new bin
        if post_residual == 0 { score += 60.0; }
        // If mean residual across open bins is small (all bins tight),
        // opening a new bin is reasonable.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    } else {
        // Slight preference for fuller bins (best-fit bias beyond raw residual)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Penalize spreading across many bins when few fitting bins exist
    if fitting_bins_count > 1 {
        score += 1.0; // mild tie-break noise-free
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1) can't be "unusable", but gaps that
    // are small relative to typical item sizes create dead space. Penalize
    // post_residual that falls into a "hard to fill" band (very small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64).powi(2) * 0.01;

    // Open-bins pressure: discourage spreading across many bins when a
    // reasonably tight fit exists; scale with number of open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: residual becomes dead space if too small
        score += 10.0;
    }

    // Prefer bins with below-average residual (fill the emptier-trend bins
    // less aggressively? No: prefer bins closer to full, i.e. residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: make empty bins attractive only when existing bins
    // would leave a very poor fit (large post_residual). Baseline penalty
    // keeps new bins as a fallback.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fill bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if post_residual as f64 >= nxt {
            score -= 200.0 / diff.sqrt();
        } else {
            // next item cannot fit; post_residual is likely dead space
            score += (nxt - post_residual as f64) * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it moderately attractive only when item is large
    // and residuals across bins are small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 50.0 * pressure + item_size as f64 * 0.2;
    }

    // Slight late-stream conservatism: consolidate more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual fits the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate control: only open a new bin when current residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit = mean_residual / bin_capacity as f64;
        score += 18.0;
        if avg_fit < 0.15 {
            score -= 30.0;
        }
        if progress > 0.9 {
            score += 10.0;
        }
    }

    // Mild preference for fuller bins relative to the fleet mean.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Spread usage when many bins are open and residuals are large.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual + 20.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * 0.5;
    score += 8.0 * poly;

    // Reward tight fits (small post_residual), smoothly
    score -= 4.0 * (1.0 - pr_norm).powi(3);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual {
        score += 2.0;
    }

    // Mild pressure to consolidate into fewer bins as open bin count grows
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // Penalize opening a new bin late in the stream unless residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 * (0.5 + 0.5 * progress) + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: dead space in low classes is more wasteful.
    let cls = post_residual / (bin_capacity / 4); // 0..3 harmonic quarters
    score += match cls {
        0 => -4.0,   // tiny leftover: nearly perfect fit
        1 => 1.5,
        2 => 3.0,
        _ => 0.0,
    };

    // Reward tight fits more when few bins can take the item (last chance).
    if fitting_bins_count <= 1 {
        score -= 6.0;
    } else if fitting_bins_count <= 3 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0; // perfect chain
        } else if gap < bin_capacity / 8 {
            score -= 4.0;
        } else {
            score -= 1.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; residual becomes dead space until later.
        score += (post_residual as f64) * 0.25;
    }

    // Modulo-10 harmonic: residuals divisible by 10 are more reusable.
    if post_residual % 10 == 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Penalize opening a new bin when existing bins fit decently.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0;
        // But if no open bin fits, new bin is the only option: cancel penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early stream: keep more bins open for flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Spread-aware: prefer bins below mean residual slightly (balance load).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Integer-division threshold: very large items prefer exact-fill bins.
    if item_size >= bin_capacity * 3 / 4 && post_residual < bin_capacity / 8 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    }
    // Near-perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Waste scaled by fraction of capacity lost
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, new bins are cheap
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // New-bin candidate: baseline cost, cheaper early, costlier late
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + pressure * 0.5 - 10.0;
        // don't open a new bin if this bin would otherwise be a dead-space maker
    }

    // Lookahead: if next item fits the post-residual, reward leaving useful space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongly reward bins that become exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // leftover after next item would be placed
            let tail = post_residual as f64 - next_item_size as f64;
            score -= 80.0 - tail * 0.5;
        } else {
            // dead space: next item cannot use the leftover
            score += 40.0 + (next_item_size as f64 - post_residual as f64) * 0.6;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins already tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a brand-new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
        // open new bin more readily early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space more than proportionally (unusable gaps).
        let pr = post_residual as f64;
        score += 200.0 / pr; // tiny post_residual -> big penalty? No: invert logic below
        score -= 200.0 / pr; // keep net zero, replaced by explicit term
        score -= 0.0;
        // Explicit: small leftover (<20) is a penalty since few items fit it.
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 3.0;
        }
    }

    // Lookahead: if next item fits in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalty scaled by gap.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 120.0;
        // Cheap to open early in stream or when many bins already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 60.0 * (1.0 - progress);
        // If no open bin can fit, opening is necessary: reduce cost.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If many open bins fit, discourage opening a new one.
        if fitting_bins_count >= 2 {
            score += 40.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Large items waste less in a fresh bin.
        score -= 0.5 * item_size as f64;
    }

    // Prefer bins whose residual is close to mean residual (balance load),
    // mild effect.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer fuller bins generally (small residual before placement).
    score += 0.1 * bin_residual as f64;

    // Slight preference to spread across bins when many open with slack.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * fill * fill);

    // Tight fits rewarded quadratically as stream progresses
    score -= (fill * fill * fill) * cap * (0.4 + 0.6 * progress);

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0);
        score += gap * gap / cap * (0.5 + 0.5 * progress);
        // Reward leaving space exactly useful for next item
        if pr >= nx {
            score -= (nx / cap) * 8.0 * (1.0 - progress * 0.5);
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score += pr * pr / cap;
    }

    // Last-chance bin bonus (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * fill;
    }

    // Mild penalty for bins far from the mean residual (smooth dispersion term)
    let dev = (pr - mean_residual).abs();
    score += dev / cap * 2.0 * (1.0 - progress);

    // Prefer consolidating into fewer bins early
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize unless residual would be very small
    if bin_residual == bin_capacity {
        score += cap * 0.3 - fill * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket it lands in.
    // Classes: 0 (perfect/empty-ish), 1..7 progressively worse dead space.
    let class_count: f64 = 8.0;
    let class_size = bin_capacity as f64 / class_count;
    let post_class = ((post_residual as f64) / class_size).floor().min(class_count - 1.0);

    // Reward tight fits: the lower the class, the bigger the bonus.
    score -= (class_count - post_class) * (bin_capacity as f64 * 0.12);

    // Perfect fit gets an extra harmonic bonus (post_residual is a multiple of a capacity fraction).
    if post_residual == 0 {
        score -= bin_capacity as f64 * 1.5;
    } else if bin_capacity % post_residual.max(1) == 0 {
        score -= bin_capacity as f64 * 0.05;
    }

    // Dead-space penalty: if the next item cannot fit in the leftover, this bin is likely closed.
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalize proportionally to how much dead space is stranded.
        let dead = post_residual as f64;
        let dead_frac = dead / bin_capacity as f64;
        score += dead * 0.6 + dead_frac * bin_capacity as f64 * 0.4;
    } else if next_item_size > 0 {
        // Next item fits: reward leaving exactly a good class for it.
        let next_post = post_residual - next_item_size;
        let next_class = ((next_post as f64) / class_size).floor().min(class_count - 1.0);
        score -= (class_count - next_class) * 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= bin_capacity as f64 * 0.8;
    }

    // New-bin candidate (empty bin): make it attractive only when current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a new bin.
        score = bin_capacity as f64 * 0.35;
        // More attractive early in the stream (long future amortizes a new bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * bin_capacity as f64 * 0.15;
        // If the item would leave a horrible class in an existing bin, new bin looks better;
        // if a tight class is achievable in an existing bin, new bin looks worse.
        let item_class = ((item_size as f64) / class_size).floor().min(class_count - 1.0);
        score -= (class_count - item_class) * 1.5;
        // Many open bins with high mean residual: avoid adding another bin.
        score += (open_bins_count as f64).sqrt() * 3.0 + mean_residual * 0.02;
    }

    // Slight global preference for consolidating into bins already below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Integer-division threshold: bins whose residual divided by 10 lands in a "usable" band get a nudge.
    let decile = post_residual / 10;
    if decile >= 3 && decile <= 6 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap is heavily penalized.
    // A residual is "dead" if it cannot hold even a small item (min item size 1..~20 band).
    if post_residual > 0 {
        let dead_threshold = 15.0;
        if (post_residual as f64) < dead_threshold {
            // Gap too small to be useful -> large penalty proportional to its uselessness
            score += (dead_threshold - post_residual as f64) * 4.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Open bins pressure: discourage opening new bins when many bins are already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 3.0 + 8.0;
    } else {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream progression: later in the stream, be slightly more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5.0 - post_residual as f64) * 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits perfectly-ish after this placement.
            score -= 250.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // Next item won't fit here; penalize leaving large unusable-ish gaps.
            score += 0.5 * diff;
        }
    }

    // Penalize residual far below mean residual (wasting a roomy bin on a small item).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement
    // would leave a very awkward residual and other options exist.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64;
        if awkward && fitting_bins_count > 0 {
            score -= 50.0; // open a new bin rather than create tiny dead space
        } else {
            score += 200.0; // generally discourage opening new bins
        }
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space quadratically relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln() * tightness;
    }

    // Time horizon: early on, keep bins flexible (favor larger post_residual);
    // late in the stream, be aggressive about filling bins completely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * tightness;
    score -= progress * 20.0 * (1.0 - tightness);

    // Mean residual coupling: if this bin is far below average residual, it is
    // already fragmented; prefer bins closer to the mean for balanced packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    // (item is large relative to typical residual) or stream is nearly done.
    if bin_residual == bin_capacity {
        let avg_need = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let poor_options = fitting_bins_count == 0
            || (item_size as f64 > avg_need * 0.8 && fitting_bins_count <= 2);
        if poor_options && progress < 0.9 {
            score -= 45.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual, polynomially coupled with stream progress.
    let x = post / cap; // in [0, 1]
    // Smooth interaction: waste penalty grows super-linearly as stream progresses.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += (x * x * x) * (1.0 + 6.0 * progress_poly) * cap * 0.25;

    // Perfect fit reward, strengthened late in the stream.
    if post_residual == 0 {
        score -= 8.0 + 12.0 * progress_poly;
    } else if post_residual <= 10 {
        score -= 3.0 + 5.0 * progress_poly;
    }

    // Last-chance bonus: penalize alternatives when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * ((fitting_bins_count - 1) as f64).min(3.0);
    }

    // Lookahead coupling: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = (nxt <= post) as i32 as f64;
        let coupling = fit_next * (1.0 - (gap / cap).powi(2));
        score -= 4.0 * coupling * (0.5 + 0.5 * progress_poly);
    }

    // Mild preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 2.0;

    // Discourage opening new bins when decent fits exist, more so early on.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress_poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of common size bands) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is king
    } else if pr <= 10 {
        -35.0 // small dead space, still very good
    } else {
        // reward leftovers that are near-multiples of 10/20/25/50 (harmonic divisors)
        let mut harm = 0.0;
        for d in [10u32, 20, 25, 50] {
            let r = pr % d;
            let dist = r.min(d - r) as f64;
            harm += (d as f64 / 10.0) * (1.0 - dist / (d as f64 / 2.0));
        }
        -harm * 2.0
    };
    score -= class_bonus;

    // Penalize leftover that cannot fit the lookahead item (dead space w.r.t. k=2)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.45;
        }
        // Bonus if post_residual exactly or nearly matches next item (chaining)
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 5 {
            score -= 12.0 - gap as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bins are very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + fragmentation * 0.3 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0; // item can't fit anywhere but fresh bin anyway
        }
    } else {
        // Prefer tighter bins: normalize residual closeness
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
        // Slight preference for bins below mean residual (tighter than average)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Integer-division threshold on post_residual: leftovers in [11..19] and [26..34]
    // are historically poor (odd dead zones); penalize them.
    let q = post_residual / 10;
    if q == 1 && post_residual < 20 {
        score += 6.0;
    }
    if post_residual >= 21 && post_residual <= 24 {
        score += 4.0;
    }

    // Late-stream consolidation: as stream ends, prefer filling existing bins fully
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual.min(40) as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small unusable dead-space gaps (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward bins whose residual can still host the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has residual == capacity, so this raises its score).
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Mildly favor filling already-open bins when bin count is high.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Prefer bins tighter than the current mean residual (good consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Late in the stream, slightly favor tighter fills to avoid leftover fragments.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a golden pairing; reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Slack left after both placements: mild penalty proportional to slack.
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.6;
            // Bonus when the pair nearly fills the bin.
            if slack <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item cannot use the remaining space: dead space penalty,
            // scaled by how much is wasted relative to mean residual.
            let dead = post_residual as f64;
            score += dead * 1.5 + (dead - mean_residual).abs() * 0.4;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: strongly discourage unless item is large
    // (>= 60% of capacity) or no open bin could otherwise fit well.
    if bin_residual == bin_capacity {
        score += 400.0;
        if item_size >= 60 {
            score -= 250.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0; // pairable with lookahead in a fresh bin
        }
    }

    // Mild stream-progression pressure: late in the stream, prefer tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Crowding: many open bins -> favor consolidation into existing ones.
    if open_bins_count > 4 {
        score -= 10.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space that is hard to reuse (post_residual small but nonzero).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead / bin_capacity as f64).powf(0.5) * 10.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure bonus
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.15;
        let poor_fit = fill_ratio < 0.55;
        let mut new_bin_penalty = 30.0;
        if crowded { new_bin_penalty -= 18.0; }
        if poor_fit { new_bin_penalty -= 10.0; }
        if open_bins_count == 0 { new_bin_penalty -= 30.0; }
        // Late in stream, avoid proliferating bins.
        new_bin_penalty += 15.0 * progress;
        score += new_bin_penalty;
    } else {
        // Prefer bins whose residual is above the mean (keep big holes open for big items).
        score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);
        // Reward bins that can also host the lookahead item after placement.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else if next_item_size > 0 && post_residual < next_item_size {
                score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
            }
        }
    }

    // Mild preference for spreading load when many bins are open and residual is high.
    if open_bins_count > 2 && bin_residual as f64 > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (waste), non-linearly reweighted by stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for residual that is too small to be useful for any item (dead space),
    // modeled as a smooth bump around small residuals.
    let dead = (1.0 - post / cap).max(0.0);
    score += 20.0 * dead * dead * (1.0 - dead);

    // Reward tight fits: coupling of post_residual with item size.
    let item = item_size as f64;
    score -= 0.15 * item * (1.0 - post / cap);

    // Penalize opening a new bin when existing bins fit (smooth in fitting_bins_count).
    if bin_residual == bin_capacity {
        let fit = fitting_bins_count as f64;
        score += 12.0 / (1.0 + fit * fit);
        // Early in the stream, opening bins is cheaper.
        score -= 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward leaving residual compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 6.0 * (-gap / cap).exp();
        // Penalize leaving residual just below next item size (unusable for lookahead).
        if post < nxt {
            score += 4.0 * (1.0 - post / nxt);
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    // Deviation from mean residual: prefer bins that reduce residual dispersion.
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "useful"
    // for common small items (multiples of 10 up to 50), penalize dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit: excellent
    } else if pr <= 50 {
        // usable residual: reward, better when it matches a harmonic class
        let class = pr / 10;
        score -= 6.0 + (class as f64) * 1.5;
        if pr % 10 == 0 {
            score -= 4.0; // aligned with capacity fraction grid
        }
    } else if pr <= 80 {
        score += 5.0; // mediocre residual
    } else {
        score += 12.0; // near-empty bin used for a small item: wasteful
    }

    // Penalize leaving residual smaller than the smallest plausible item (1..10)
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space trap
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 + slack * 0.2;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits now but won't after this placement: mild penalty
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        // prefer new bin when existing residuals are small (little usable space)
        let small_mean = (30.0 - mean_residual).max(0.0) * 0.5;
        score += 40.0 - pressure * 2.0 - small_mean;
        // late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Fit tightness: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Mean-residual divergence: placing into a bin far below mean residual
    // balances the pool of open bins.
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-5.0).min(5.0);

    // Modulo harmonic penalty on item size class vs post residual alignment
    if pr > 0 && (pr % (item_size.max(1))) == 0 {
        score -= 3.0; // residual is a multiple of the item: likely reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps that cannot accommodate the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, prefer filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (good fill).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Slight bias toward keeping new-bin option open when residual is large but awkward.
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 500.0; // chain perfect fit
        } else {
            score -= 100.0 + post_residual as f64 - next_item_size as f64;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space: next item cannot use leftover
        score += 50.0 + post_residual as f64 * 0.5;
    }

    // Penalize deviation from mean residual (prefer balanced / tight fits)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: mildly discourage unless residuals are large
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in stream: tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize creating dead space too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover space; penalize proportionally
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    // or few bins are open (early stream, cheap to open).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64) < 0.6 * mean_residual.max(1.0);
        let early = progress < 0.25;
        if poor_fit && !early {
            score -= 20.0; // opening a fresh bin beats wasting a big residual
        } else {
            score += 45.0 + 10.0 * (1.0 - progress); // prefer existing bins generally
        }
    }

    // Mild pressure to fill bins when many are open (reduce open-bin sprawl).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from mean in a useful way:
    // a bin much larger than mean residual can absorb the item with less waste.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 2.0 * t * t - 3.0 * t + 1.0; // smooth parabola in [0,1]
    score -= poly * norm_pr * cap * 0.5;

    // Penalize small dead space quadratically (unusable残 space)
    if norm_pr > 0.0 {
        let dead = (norm_pr - (norm_pr * norm_pr)) * cap;
        score += 0.3 * dead * (1.0 - t);
    }

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.5 + t);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - (ni / cap)) * (0.5 + 0.5 * t);
        } else {
            score += 6.0 * (ni / cap);
        }
    }

    // Mild penalty when many bins are open (discourage bin sprawl)
    score += (open_bins_count as f64).ln() * 1.5 * (1.0 - t);

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - t) - 10.0 * t;
        score += mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity / 4 bands
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let band = post_residual / quarter; // 0..4 integer division class

    // Penalize dead space in awkward harmonic classes (small unusable slivers)
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 10) {
        score += 25.0;
    }

    // Reward near-perfect fills (post_residual in lowest harmonic class)
    if band == 0 {
        score -= 30.0;
    } else if band == 1 {
        score -= 12.0;
    } else if band == 2 {
        score += 5.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains that also host the next item, scaled by fit tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 15.0 * tightness;
        } else {
            // Penalize leaving a gap just below next item size (dead zone)
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly late in the stream or when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
    }

    // Prefer packing into bins with below-average residual (tight bins first)
    let diff = (mean_residual - bin_residual as f64) / cap_f;
    score += 10.0 * diff;

    // Modulo-10 harmonic bonus: residuals divisible by 10 pair well with
    // typical item sizes, making leftovers reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the
    // smallest plausible item (<= 10) are essentially wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Tight-but-usable gaps are risky; mild penalty.
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, tolerate new bins less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual >= 0 { 0.0 } else { 0.0 };
        let _ = bad_fit;
        // Base cost of opening a new bin, discounted when the current item is large
        // (large items are hard to place later) or few bins are open.
        let item_pressure = (item_size as f64 / 100.0) * 30.0;
        score = 40.0 + item_pressure - (fitting_bins_count.max(1) as f64 - 1.0) * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // An empty bin can host both current and next item comfortably.
            score -= 25.0;
        }
        if fitting_bins_count == 1 {
            // Only alternative is a poor fit elsewhere; new bin is reasonable.
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (balancing load).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: if next item fits exactly in the post residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // next item fits, but not perfectly: reward proportional to tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else if next_item_size > 0 {
            // next item won't fit in leftover: penalize dead space.
            score += 50.0;
        }

        // Penalize small unusable leftovers (dead space) nonlinearly.
        if post_residual < 10 {
            score += 150.0 * (10.0 - post_residual as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below mean
    // (tighter bins) when fit is good; avoid wasting large-residual bins on small items.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.5 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Late in the stream, consolidate more aggressively (fewer wasted partial bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Mild penalty for leaving a new empty bin unused when many bins are open.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + 10.0 * open_bins_count as f64;
        } else {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't chain here; slight penalty proportional to gap
        score += 0.10 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Prefer more crowded alternatives slightly; mild penalty to spread less
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(8.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize filling existing bins less);
    // late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with low mean residual -> consolidate to avoid fragmentation.
    if mean_residual < 20.0 && open_bins_count > 4 {
        score += 10.0;
    } else if open_bins_count > 10 {
        score -= 5.0; // encourage using existing bins to avoid opening even more
    }

    // New-bin candidate: empty bin should only win when existing fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // but early stream with few bins, opening fresh is cheaper
        if progress < 0.3 && open_bins_count < 6 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer bins leaving small post_residual (tight packing).
    // Late (progress ~ 1): prefer conserving large residuals for flexibility.
    let w_tight = (1.0 - progress).powi(2);
    let w_flex = progress.powi(2);
    score += w_tight * (post / cap) * (post / cap) * 30.0;
    score -= w_flex * (post / cap) * 10.0;

    // Penalize near-full bins that leave unusable slivers (dead space), smoothly.
    let dead = (1.0 - post / cap).powi(3);
    score += dead * 12.0;

    // Reward very tight fits (small post_residual) with smooth exponential shaping.
    score -= (-(post / cap) * 4.0).exp() * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_gap = (post - nxt) / cap;
            score -= 15.0 * (1.0 - fit_gap).powi(2);
        } else {
            // Next item won't fit: mildly penalize wasting a large residual here.
            score += (post / cap) * 6.0;
        }
    }

    // Crowd penalty: many open bins -> favor filling existing ones over spreading.
    let crowd = (open_bins_count as f64 / 20.0).min(1.0);
    score += crowd * (post / cap) * 5.0;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced usage), with smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: neutral baseline that is beaten only when some open bin
    // offers a genuinely good fit; penalize opening new bins when crowd is high.
    if bin_residual == bin_capacity {
        score += 40.0 + crowd * 20.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 as "capacity fractions".
    let post = post_residual as i64;
    let residue = (post % 10) as f64;
    // Residue penalty: dead space that is not a multiple of 10 is harder to fill.
    score += residue * 0.35;

    // Integer-division thresholds: reward post_residual in "usable" bands.
    let band = post / 10; // how many 10-sized slots remain
    if band == 0 {
        // Nearly sealed bin: excellent if fit succeeded.
        score -= 25.0;
    } else if band <= 2 {
        // Small leftover, moderately good.
        score -= 8.0;
    } else if band >= 6 {
        // Huge leftover means this was a nearly-empty bin; mild penalty to
        // avoid wasting big bins on small items.
        score += 6.0;
    }

    // Perfect-fit style rewards via modulo arithmetic on post_residual.
    if post == 0 {
        score -= 60.0; // exact fill
    } else if post % 20 == 0 {
        score -= 15.0; // leaves a "half bin" style slot
    } else if post % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or in a harmonic class, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == post {
            score -= 45.0;
        } else if nxt <= post && (post - nxt) % 10 == 0 {
            score -= 18.0;
        } else if nxt > post {
            // Next item cannot follow here; penalize if we burned a big slot.
            score += (nxt - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (consolidation pressure) or early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 40.0 - 20.0 * progress;
        if open_bins_count > 4 {
            new_bin_cost += 8.0; // too many open bins already
        }
        if next_item_size > 0 && (next_item_size as i64) >= (bin_capacity as i64) - (item_size as i64) {
            // Next item pairs perfectly with current in a fresh bin.
            new_bin_cost -= 35.0;
        }
        score += new_bin_cost;
    }

    // Slight preference for bins below mean residual (use emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to fit the smallest plausible
    // next item are unusable dead space -> heavy penalty.
    if post_residual > 0 {
        let dead_threshold = 12u32;
        if post_residual <= dead_threshold {
            score += 40.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
        }
        // Perfect fit bonus (subtract) scaled by how much of the bin is consumed.
        if post_residual == 0 {
            score -= 25.0;
        }
    } else {
        score -= 25.0;
    }

    // Reward high fill ratio of the bin (tight packing).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Open-bins pressure: when many bins are open, prefer reusing existing bins
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less desirable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well,
    // reward leaving a usable gap for it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Post residual too small for next item -> dead space risk.
            score += 4.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or nearly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Next item fits: reward tight coupling (perfect wrap gets big bonus).
            let tightness = 1.0 - (gap / bin_capacity as f64);
            score -= 12.0 * tightness * tightness;
            // Perfect match bonus (post_residual == next_item_size)
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item does NOT fit: penalize leaving awkward leftover space.
            score += 6.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: avoid making bin an outlier of dead space.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (post_f - mean_residual).abs();
        score += 0.08 * dev;
        // Favor bins whose residual is below mean (more filled than average)
        if post_f < mean_residual {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize large dead space (small post_residual is good, already base; add non-linear term).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Mild preference for filling existing bins early in the stream when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: only attractive when current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; discourage unless item is huge relative to capacity
        score += 25.0 - 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (0.5 + progress);

    // Penalize dead space: post_residual too small to ever be useful (< 10).
    if post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    } else if post_residual > 40 {
        // Large leftover is flexible; mild reward.
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Perfect chaining: next item exactly fills leftover.
        if next_item_size == post_residual {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize if we also create awkward leftover.
        score += 1.5;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score += 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score -= 1.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate handling: empty bin gets a penalty unless few bins open
    // or the fit in existing bins is poor (large post_residual).
    if bin_residual == bin_capacity {
        let escape = if open_bins_count == 0 {
            -100.0
        } else if fitting_bins_count == 0 {
            -50.0
        } else {
            // discourage new bin mildly; more so early in stream when future is long
            6.0 + 10.0 * (1.0 - progress)
        };
        score += escape;
    }

    // Mild penalty for bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + p) - 8.0 * norm_pr * p * (1.0 - p);
    // Penalize large post-residual more as stream progresses (dead space matters later)
    score += 20.0 * norm_pr * norm_pr * norm_pr * p;
    // Reward tight fits (small post_residual) especially early
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - p);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }
    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - pr / next_item_size as f64).max(0.0);
    }
    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr * p;
    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * (0.5 + p);
    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - p) - 10.0 * (mean_residual / cap).min(1.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small powers of 2
    // are more reusable by typical item sizes.
    let r = post_residual;
    let harmonic_bonus = if r == 0 {
        -50.0 // perfect fit
    } else if r % 10 == 0 {
        -8.0
    } else if r % 5 == 0 {
        -4.0
    } else if r % 25 == 0 {
        -10.0
    } else if r % 2 == 0 {
        -1.0
    } else {
        2.0 // odd residuals are harder to pair
    };
    score += harmonic_bonus;

    // Integer-division threshold classes on post_residual.
    let q = r / 10;
    score -= (q as f64) * 1.5; // larger usable chunks are better

    // Penalize tiny dead space (waste) more than proportionally.
    if r > 0 && r < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size < r {
            let slack = r - next_item_size;
            if slack < 10 {
                score -= 10.0; // near-tight chain
            } else {
                score -= (slack as f64).min(20.0) * 0.2;
            }
        } else {
            score += 5.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are fragmented.
        score = 40.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item benefits from a fresh bin
        }
    } else {
        // Slight preference for tighter existing bins (lower residual before placement).
        score += (bin_residual as f64) * 0.05;
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual context: when mean residual is high, packing into open bins is fine.
    score -= mean_residual.min(50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is pure waste
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 6.0;
        }
    } else {
        // Perfect fit is highly desirable.
        score -= 25.0;
    }

    // Pressure term: prefer filling existing bins when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if this bin's post-residual is far below the mean,
    // we are compacting well; reward it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual will be dead space for the known next item; penalize.
        score += 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // fallback only when no open bin offers a decent fit. Penalize opening
    // new bins mildly, but leave escape hatch for large items.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > bin_capacity / 2 {
            score -= 5.0; // large items start fresh bins more readily
        }
    }

    // Stream progression: later in the stream, tighten up (avoid new bins).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-step match: post_residual exactly equals next item size.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
            // Bonus for exact chaining (dead space ~ 0 after next placement).
            if slack < 1.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0);
        }
    }

    // Penalize bins whose residual deviates strongly above the mean residual
    // (keeps bins homogeneous, preserves tight bins for future items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for keeping many open bins consolidated early on.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Never prefer opening a new bin unless residuals of open bins are very tight.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, prefer tighter packing (squash residual differences).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more dead space -> mild penalty on leftover
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize bins that strand too much space
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage placing into bins whose residual deviates far above the mean
    // (keeps a portfolio of residuals diverse rather than wasting mid-size gaps).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Many open bins: encourage closing out small-residual bins.
    if open_bins_count > 4 {
        score += 0.3 * (post_residual as f64);
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // (large item relative to residuals) or early stream with room to plan.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (item_size as f64) > 0.6 * bin_capacity as f64
            || mean_residual < item_size as f64 * 0.9;
        if poor_alternatives {
            score -= 15.0;
        } else {
            score += 40.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild preference for placing large items into the emptiest usable bins.
    if item_size >= 50 {
        score -= 0.1 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let shape = 1.0 + 0.6 * progress * progress + 0.4 * progress * pr_norm;
    score *= shape;

    // Penalize small unusable leftovers, more strongly as stream progresses.
    let dead_threshold = 0.2 * cap;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / cap;
        score += 6.0 * d * d * (1.0 + progress);
    }

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 4.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Coupling with mean residual: prefer bins near the mean (smooth Gaussian-like term).
    let diff = (pr - mean_residual) / cap;
    score += 3.0 * diff * diff * cap * 0.01;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 5.0 * (1.0 - slack * slack);
    } else if next_item_size > post_residual as u32 {
        score += 2.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins, smoothed by progress.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
