    // nearly unusable for typical items -> penalize heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic bands of 12)
    let band = post_residual / 12;
    match band {
        0 => score += 18.0,                       // 0..11 : near-dead space
        1 => score += 6.0,                        // 12..23 : poor
        2 => score -= 2.0,                        // 24..35 : decent
        3 => score -= 6.0,                        // 36..47 : good
        4 => score -= 8.0,                        // 48..59 : very good
        5 => score -= 9.0,                        // 60..71 : excellent
        6 => score -= 10.0,                       // 72..83 : excellent
        7 => score -= 11.0,                       // 84..95 : near-perfect
        _ => score -= 12.0,                       // 96..100 : pristine
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are "harmonic" and likely to be filled exactly later.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }
    // Odd/prime-ish residuals are awkward: slight penalty
    if post_residual % 2 == 1 && post_residual < 30 {
        score += 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap <= 10 {
            score -= 8.0;
        } else if gap <= 25 {
            score -= 3.0;
        } else {
            score += (gap as f64) * 0.05; // next item leaves dead space -> mild penalty
        }
    } else if next_item_size > 0 && next_item_size <= item_size.max(1) {
        // next item cannot fit here anyway; neutral
        score += 0.0;
    } else if next_item_size > 0 {
        // post_residual too small for next item: dead space confirmed
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are all poor and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // Base cost of opening a new bin, reduced late in the stream
        let mut new_bin_score = 55.0 - 15.0 * progress;
        // If many bins already open with slack, discourage fragmentation
        new_bin_score += openness * 1.5;
        // If mean residual is large, prefer reusing open bins
        new_bin_score += mean_residual * 0.4;
        // Large items relative to capacity justify a fresh bin more
        new_bin_score -= (item_size as f64 / cap) * 10.0;
        // Small items should almost never open a bin
        if item_size <= 30 {
            new_bin_score += 25.0;
        }
        score += new_bin_score;
    }

    // Prefer tighter existing bins overall (relative tightness term)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Prefer bins whose residual was already small relative to mean residual.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Open-bin pressure: mildly discourage spreading across too many bins,
    // but relax late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.2 - 0.6 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is useless for the next item: penalize.
        score += 8.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly favored when the
    // fit into any open bin would be terrible (post_residual very small).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item leaves minimal dead space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 30.0 * fit_ratio;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size,
    // penalize post_residuals that waste space relative to the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + gap); // closer gap to next item => better
        } else {
            // next item cannot fit here: penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
        // exact 2-step chain (item then next item fills bin exactly)
        if post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Relative-to-mean coupling: bins with residuals far from the mean are
    // either nearly full (good targets) or oddly sparse (avoid fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    if bin_residual < mean_residual {
        score -= 0.3 * dev; // tighter-than-average bins are preferred
    } else {
        score += 0.1 * dev;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 || pressure > 0.6 {
            score -= 40.0; // open a fresh bin for large items / no alternatives
        } else {
            score += 60.0; // discourage wasting a fresh bin on small items
        }
    }

    // Slight preference for filling bins earlier in the stream to keep
    // open-bin count low.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize when next item would leave this bin wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 8.0;
        }
        // Bonus if post_residual matches next item exactly.
        if post_residual == next_item_size {
            score -= 22.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: later in the stream, be more conservative — favor tight fits,
    // penalize opening bins with lots of leftover space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, favor bins below mean residual
    // (consolidate into emptier bins to balance future packing).
    if mean_residual > 0.0 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * diff;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins open / late stream.
        score = 0.5 * bin_capacity as f64 + 30.0;
        score -= 15.0 * progress;
        if next_item_size > 0 && bin_capacity >= next_item_size + item_size {
            score -= 12.0; // fresh bin can host next item too
        }
        if fitting_bins_count > 0 {
            score += 10.0; // discourage new bin if some open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial base: reward tight fits, penalize dead space non-linearly.
    let mut score = 3.0 * x * x + 1.5 * x;

    // Progress coupling: later in stream, tighter packing matters more.
    score *= 1.0 + 1.2 * progress * (1.0 - x);

    // Penalize bins that deviate from mean residual (prefer balanced fills),
    // with smooth quadratic coupling scaled by stream progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    }

    // Lookahead: if next item would fit in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty for stranding space.
        score += 0.5 * x * progress;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score; opening a new
    // bin is discouraged unless existing fits are poor (post_residual large).
    if bin_residual == bin_capacity {
        score = 2.5 + 2.0 * progress + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity quarters
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    // Residuals landing in a "dead zone" (small but hard to fill) get penalized
    if post_residual > 0 && class < 10 {
        score += (10 - class) as f64 * 2.5;
    }
    // Perfect or near-perfect fits rewarded
    if post_residual == 0 {
        score -= 40.0;
    } else if class == 0 {
        score -= 15.0;
    }

    // Harmonic coupling: can the lookahead item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward proportionally to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: penalize leftover dead space more
            score += (post_residual.min(next_item_size)) as f64 * 0.3;
        }
        // harmonic class of next item: items near half-capacity like complementary pairs
        if post_residual > 0 && next_item_size as f64 / post_residual as f64 > 0.9 {
            score -= 10.0;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are too full
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base new-bin score: mild, so open bins usually win unless they are poor
        score = bin_capacity as f64 * 0.55 - pressure * 60.0
            + (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Tightness reward: bins whose residual is close to item size give best packing
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tight) * 0.05;

    // Stream progression: later in the stream, be greedier about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Penalize spreading across too many open bins when mean residual is already large
    score += (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are "dead". Penalize them heavily.
    let dead_threshold = 10u32.min(bin_capacity / 10).max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: relative fill quality of this placement.
    let fill = (bin_residual - post_residual) as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 30 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: empty bin is attractive only if no open bin
    // offers a decent fit. Penalize the fresh bin mildly so tight fits in open
    // bins win, but let it win over badly fitting placements.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Opening a fresh bin lets the next item pair with this one.
            score -= 8.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: many open bins -> consolidate; few bins -> spreading
    // out (fresh bin) is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual != bin_capacity {
        score -= pressure.min(10.0);
    }

    // Mean residual coupling: prefer bins whose residual is far from the mean
    // (i.e., close the outliers, keep balanced bins flexible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);

        // Penalize leaving residual that next item cannot use (wasted dead space)
        if post_residual < next_item_size {
            score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative-to-mean residual shaping
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (dead space < 10)
    if post_residual < 10 {
        score += 20.0;
    }

    // Prefer tighter fits generally
    score += 0.3 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - post_residual as f64);

    // Slight bias against opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill = item_size as f64 / residual;
        score -= 40.0 * fill * fill;
    }

    // Penalize small unusable dead space (post residual that likely fits nothing).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 30.0;
            // extra bonus if next item exactly complements
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // dead end for the lookahead item
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would be badly fragmented or open bins are few relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0;
        // If mean residual across open bins is small (fragmented), opening new bin less bad.
        new_bin_penalty -= 0.3 * mean_residual;
        // Few open bins with lots of stream left: opening a bin can be strategic.
        new_bin_penalty -= 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
        // Penalize more if this bin is the last chance (should use it, not open new).
        if fitting_bins_count == 1 {
            new_bin_penalty += 30.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing bins.
    score += 0.05 * open_bins_count as f64;

    // Slight time decay: early in stream, be more tolerant of loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let fit = fitting_bins_count as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // early on, waste matters less; later, penalize residuals more aggressively
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * progress;
    score += 40.0 * progress_coupling;

    // Reward near-perfect fits more strongly as the stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residual that cannot fit the lookahead item
    if nxt > 0.0 {
        if pr < nxt {
            score += 15.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving exactly enough room for the next item
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty proportional to crowdedness of open bins
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // New-bin candidate: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score = pr + 55.0 - 45.0 * (1.0 - norm_pr) - 20.0 * (1.0 - (item / cap));
        score -= 25.0 * progress * (1.0 - norm_pr);
    }

    // Smooth mean-residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds on capacity fractions.
    // Class 0: perfect fit (post_residual == 0) -> strongest reward.
    // Class 1: residual <= 10 (dead space unlikely to be reused) -> heavy penalty.
    // Class 2: residual <= 20 -> moderate penalty.
    // Class 3: residual <= 33 (1/3 capacity) -> mild penalty.
    // Class 4: residual <= 50 (1/2 capacity) -> near-neutral.
    // Class 5: large residual -> slight reward (bin stays flexible).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 33 {
        score += 8.0;
    } else if post_residual <= 50 {
        score -= 2.0;
    } else {
        score -= 6.0;
    }

    // Modulo-arithmetic coupling: if the next item exactly tiles the post_residual
    // (post_residual % next_item_size == 0 or next_item_size fits cleanly), reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect tiling of leftover
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // reward proportional to how small the second leftover is
            if leftover == 0 {
                score -= 200.0;
            } else if leftover <= 10 {
                score -= 30.0;
            } else if leftover <= 25 {
                score -= 10.0;
            }
            // penalize if next item leaves a dead zone again
            if leftover > 0 && leftover < 10 {
                score += 5.0;
            }
        } else {
            // next item cannot fit here; residual is dead space for the lookahead
            if post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when other bins can fit the item,
        // unless the fit elsewhere would be terrible (tiny post_residual class).
        if fitting_bins_count > 0 {
            score += 55.0;
            // but if all existing fits are awful (we don't know their scores directly),
            // soften via mean_residual coupling: high mean residual means bins are roomy,
            // so new bin is even less attractive.
            score += mean_residual * 0.15;
        } else {
            score -= 20.0; // no alternative: new bin is fine
        }
        // Later in the stream, prefer consolidating into open bins more strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
    }

    // Mild pressure to use bins with less residual (best-fit bias beyond raw residual):
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Spread-aware term: many open bins -> prefer tighter packing.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

