        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strong reward
    }

    // Reward post_residuals that can still host a typical future item.
    if post_residual >= 50 {
        score -= 15.0;
    } else if post_residual >= 30 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates dead space relative to the known next item
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from number of open bins: consolidate when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to the item (tight fit relative to mean).
    score += 0.2 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match => strong bonus; degrade smoothly with slack.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
            // Extra reward if the chain leaves a tiny residual (tight packing).
            if slack <= 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow: penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
        // Prefer to keep room for larger upcoming items when this bin is roomy.
        if next_item_size > item_size && post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: just minimize post_residual (already the base).
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        if rel < 1.0 {
            score -= 12.0 * (1.0 - rel); // tighter-than-average bin favored
        } else {
            score += 6.0 * (rel - 1.0).min(1.5); // looser-than-average penalized
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to the residual landscape (poor fits elsewhere)
    // or no good lookahead chain exists. Make the empty bin moderately costly
    // so it only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 20.0
            - 10.0 * (waste / bin_capacity as f64)
            - 15.0 * progress * (mean_residual / bin_capacity as f64).min(1.0);
        // If item nearly fills a fresh bin, opening is genuinely good.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving large dead space that no typical item (<=80)
    // can fill later.
    if post_residual > 80 {
        score += (post_residual - 80) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 20.0 } else { 0.0 };
        score += dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item could have used this residual better.
    if next_item_size > 0 {
        let next_fits_here = next_item_size <= post_residual;
        let next_fits_now = next_item_size <= bin_residual;
        if next_fits_now && !next_fits_here {
            // placing here strands the next item's potential slot
            score += 8.0;
        }
        if next_fits_here {
            // chaining both items in this bin is excellent
            score -= 12.0;
        }
        // If next item is large and would leave this bin nearly empty anyway,
        // a fresh bin may serve it better.
        if next_item_size >= 70 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open bins (spread load);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_penalty = 60.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic openness penalty.
        score += 15.0 + open_penalty;
        // But if no existing bin fits well, allow opening.
        if fit_ratio > 0.9 || (fitting_bins_count == 0 && bin_residual == bin_capacity) {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward, scaled by how crowded the bin set is.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global residual pressure: if mean residual is high, prefer filling the fullest bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Mild preference for bins with residual close to item_size (waste-minimizing).
    let waste_gap = (bin_residual as f64 - item_size as f64).abs();
    score += waste_gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothed quadratically
    let mut score = norm_pr * norm_pr * cap;

    // Non-linear coupling: post_residual value decays with stream progress
    // (early on, leftover space is more reusable; later, waste is penalized harder)
    score += pr * (0.5 + progress * progress);

    // Interaction: post_residual vs mean residual — penalize bins whose post
    // residual diverges from the fleet average (keeps residual spread compact)
    let spread = pr - mean_residual;
    score += 0.35 * spread * spread / cap;

    // Reward near-perfect fits with a smooth cubic-shaped bonus
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: smooth exponential-style reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - pr / (pr + next_item_size as f64));
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty growing with wasted space
        score += 0.02 * pr * (1.0 + progress);
    }

    // Mild penalty on opening new bins when many are open and residuals are large
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * mean_residual / cap + (open_bins_count as f64).sqrt();
        // but allow new bins early when item is large relative to mean residual
        score -= 4.0 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: dead space is worse when it falls in "awkward" residue classes.
    // post_residual in [0,100]. Classes mod 10: values like 1..9 are nearly unusable.
    let pr = post_residual;
    let r = (pr % 10) as f64;
    if pr > 0 {
        // Penalize tiny unusable slivers heavily; reward exact closures (pr==0).
        if pr == 0 {
            score -= 40.0;
        } else if pr < 10 {
            score += (10.0 - r) * 2.5; // sliver penalty
        }
        // Mid-range residuals that still fit typical items are good.
        if pr >= 10 && pr <= 80 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds: how many more "average" items fit?
    let avg_item = 55.0f64.max(1.0);
    let fits_again = (pr as f64 / avg_item).floor();
    score -= fits_again * 4.0;

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 6.0; // next item won't fit here; bin likely closes
        }
        // Harmonic check: next item exactly fills the bin after placement
        if pr == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += pressure * 18.0; // discourage opening new bins by default
        if pr >= 20 && pr <= 90 {
            score -= 5.0; // fresh bin keeps flexible residual
        }
    }

    // Prefer filling nearly-full bins early in the stream (best-fit bias).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * (10.0 + 10.0 * progress);

    // Mild tie-break toward bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward placements that leave a gap still usable for typical items.
    if post_residual >= 10 {
        score -= 12.0;
        // Extra reward if the leftover can host the lookahead item (k=2).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Penalize leftovers that can host nothing in the plausible size range.
        if next_item_size > 0 && post_residual < next_item_size.min(10) {
            score += 10.0;
        }
    }

    // Penalize waste of large residual on small items (bad utilization).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    if item_size < 30 && waste > 50.0 {
        score += 15.0;
    }

    // Open-bin pressure: discourage opening new bins when stream is early/mid
    // and decent alternatives exist; encourage closing out bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is "tight" — prefer filling tight bins (low residual = low score).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.10;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave
    // bad dead space or lookahead won't fit anywhere well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual == bin_capacity && mean_residual < 20.0);
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact chain fit is excellent; larger slack is mildly wasteful.
            score -= 40.0 - slack * 0.3;
            if slack == 0.0 {
                score -= 60.0; // perfect two-item chain
            }
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize new-bin candidates so we only open when open fits are poor,
    // except early in the stream or when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0; // later in stream, prefer filling existing bins
    }

    // Mild preference for tightest absolute fit already covered by post_residual base.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2);

    // Penalize creating dead space smaller than the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit in leftover: penalize wasted space.
        score += 6.0;
    }

    // Prefer bins already tighter than average (best-fit style coupling with global state).
    if bin_residual < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins (spread load);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize late.
        score += 18.0 * progress;
        score += 0.5 * open_bins_count as f64;
    } else {
        score -= 6.0 * progress;
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, tighten aggressively.
    let tightness = 0.5 + 2.5 * progress * progress;
    score += tightness * (pr / cap) * (pr / cap) * cap * 0.3;

    // Penalize dead space that is too small for typical items (smooth quadratic well)
    let dead = if pr > 0.0 { (pr / cap - 0.1).abs() } else { 0.0 };
    score += 4.0 * dead * dead * cap * (1.0 - progress);

    // Reward bins whose residual can fit the next item (smooth sigmoid-ish coupling)
    if next > 0.0 {
        let fits_next = (pr - next).max(0.0) / cap;
        let slack = (next / cap) * (1.0 - fits_next);
        score -= 6.0 * slack * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild preference for fuller bins among many candidates
        score -= (item / cap) * 2.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // penalize opening new bins mildly, more when many bins open or mean residual large
        score = cap * 0.55 + 0.15 * open_bins_count as f64 + 0.3 * mean_residual;
        if next > 0.0 && fitting_bins_count <= 1 {
            score -= 5.0; // allow escape hatch when it's the last chance anyway
        }
    }

    // Small coupling with mean residual: prefer bins below mean (keep spread balanced)
    score += 0.4 * (pr as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: capacity fractions of 100
    let cap = bin_capacity as f64;
    let frac = bin_residual as f64 / cap; // residual fraction
    let post_frac = post_residual as f64 / cap;

    // Classify post_residual into harmonic classes via integer division
    let cls = post_residual / 10; // 0..=9 class
    match cls {
        0 => score -= 60.0,               // tiny dead space, great
        1 => score -= 35.0,               // 10-19: still usable by small items
        2 => score -= 15.0,               // 20-29
        3 => score -= 5.0,
        4 => score += 10.0,               // 40-49: awkward middle zone
        5 => score += 15.0,
        6 => score += 10.0,
        7 => score -= 5.0,                // 70-79: large leftover is fine
        8 => score -= 20.0,
        9 => score -= 40.0,               // near-empty bin, keep flexible
        _ => {}
    }

    // Modulo coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.5 * tight.min(50.0) as f64;
        } else {
            score += 20.0;
            // penalize more if post_residual is in awkward class next item can't use
            if post_residual < 20 {
                score += 15.0;
            }
        }
        // harmonic pair: item + next summing to capacity class
        let s = item_size + next_item_size;
        if s == bin_capacity {
            score -= 30.0;
        } else if s > bin_capacity {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // but if existing fit leaves awkward dead space, new bin becomes attractive
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score -= 55.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // fewer open bins -> cheaper to open new one? no: keep consolidation
        score += 0.3 * open_bins_count as f64;
    }

    // Progress-aware: late in stream, prefer tighter packing (less room to recover)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_frac);

    // Prefer bins whose residual deviates favorably from mean (fill the fullest bins)
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest plausible item are pure waste.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // unusable sliver
    } else if (post_residual as f64) < 20.0 {
        score += 18.0; // near-dead gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Next-item lookahead: if the post gap can host the next item, this placement is flexible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is far below the mean (i.e., already dense bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current item is huge and no good fit.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0
            - 20.0 * (item_size as f64 / cap)
            + 8.0 * open_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize leftover dead space.
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.15 * waste;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.5 * post_residual as f64;
    }

    // Penalize creating residuals that no typical item can use (dead space below min size).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        // Prefer new bin if post_residual would leave lots of unusable space in existing bins,
        // but discourage opening new bins when a good fit exists.
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = 45.0 + 0.5 * item_size as f64 - 35.0 * poor_fit - (fitting_bins_count as f64) * 5.0;
    }

    // Slight stream progression term: pack tighter later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 10.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual is close to item size (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many options: mild penalty to prefer the best-fitting ones via post_residual already.
        score += 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin anyway; neutral.
            score += 0.0;
        } else {
            // Placing here creates dead space relative to next item.
            score += 4.0;
        }
    }

    // Prefer high-residual bins when many bins are open (balance load).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let residual_dev = bin_residual as f64 - mean_residual;
    score += residual_dev * 0.03 * (1.0 - progress);

    // Penalize opening new bins as stream progresses, unless residual is tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin is a decent fit.
        let openness = open_bins_count as f64;
        let desperation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score += 30.0 - desperation * 40.0 - openness * 0.5;
        // Early in stream, new bins are cheaper.
        score -= (1.0 - progress) * 8.0;
    } else {
        // Using an existing bin: small bonus scaled by progress.
        score -= progress * 3.0;
    }

    // Penalize leaving residuals smaller than the minimum item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits: reward quadratic smallness of post_residual, stronger later in stream
    score -= (1.0 - post / cap).powi(2) * (30.0 + 40.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.5 + 2.0 * progress);
        } else {
            // next item fits: slight reward for leaving exactly usable space
            score -= (1.0 - ((post - nxt) / cap).powi(2)) * 10.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= (1.0 - post / cap).powi(3) * 60.0;
    }

    // Last-chance bin bonus: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer it only when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 15.0 + 10.0 * progress + crowd * 2.0;
        if next_item_size > 0 && (bin_residual as f64) >= next_item_size as f64 + item_size as f64 {
            score -= 12.0; // new bin can host both current and next item
        }
    }

    // Mild penalty for fragmenting bins with large residual relative to mean
    score += ((post - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes into small-item-friendly chunks
    let harmonic = |r: u32| -> f64 {
        if r == 0 { return 0.0; } // perfect fit, ideal
        // class by divisibility / capacity fractions
        let cap_frac = (r * 4) as f64 / bin_capacity as f64; // residual as quarter-fractions
        let mut h = 0.0;
        if r % 10 == 0 { h -= 6.0; }          // residual is a multiple of 10: reusable
        else if r % 5 == 0 { h -= 3.0; }      // half-decade class
        if r <= 10 { h += 25.0; }             // nearly dead space
        else if r <= 20 { h += 12.0; }
        if cap_frac.fract() == 0.0 { h -= 2.0; }
        h
    };

    score += harmonic(post_residual);

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)).min(8.0);
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins generally
        score += 40.0;
        // but if post residual in this new bin would pair perfectly with next item, allow it
        if next_item_size > 0 && post_residual == bin_capacity - item_size && next_item_size <= post_residual {
            score -= 10.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Lookahead: penalize residuals that neither fit nor complement the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host next item: reward closeness of match
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // harmonic bonus if next item divides residual exactly
            if post_residual % next_item_size.max(1) == 0 { score -= 8.0; }
        } else {
            // next item cannot use this residual: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Coupling with mean residual: avoid making bin set residual distribution more skewed
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Integer-division threshold: residuals in [25,50) are "half-bin" sweet spots
    if post_residual >= 25 && post_residual < 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is also risky since min item is 1..100 unknown.
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Progression: early on, prefer packing into existing bins slightly less strictly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize slightly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: next item can follow here — reward tighter match
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 - gap.min(200.0);
        } else {
            // Next item won't fit here; penalize leaving awkward residue
            score += 50.0 + post_residual as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Early stream: be more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (quadratic in post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize wasteful residuals that can never fit a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // dead space
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (consolidate small leftovers), else prefer balanced usage.
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Prefer bins whose residual is a "nice" size (common item sizes 10..80).
    for k in 1..=8u32 {
        if post_residual == k * 10 {
            score -= 6.0;
            break;
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 18.0 * pr_norm * pr_norm * (1.0 - t);
    score -= 22.0 * pr_norm * (1.0 - pr_norm) * t;

    // Penalize dead space relative to mean residual
    score += 0.35 * (pr - mean_residual).abs();

    // Reward near-perfect fits
    if pr == 0 { score -= 40.0; }
    else if pr < 10.0 { score -= 25.0 * (1.0 - pr / 10.0); }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 { score -= 15.0; }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // New-bin candidate: prefer it only late in the stream or when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 30.0 + 25.0 * crowd * (1.0 - t) - 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into capacity-fraction classes (1/4, 1/2, 3/4 of C).
    // Residuals in the "dead zone" (small but not zero) are penalized: they are
    // too small to host typical items, wasting bin capacity.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let three_quarter = 3.0 * quarter;

    if post_residual == 0 {
        // Perfect fill: extremely desirable.
        score -= 60.0;
    } else if pr < 10.0 {
        // Tiny sliver: nearly dead space.
        score += 25.0;
    } else if pr < quarter {
        // Small residual: only fits tiny items; penalize moderately.
        score += 12.0;
    } else if pr < half {
        // Usable mid-range residual: neutral to slightly good.
        score -= 4.0;
    } else if pr < three_quarter {
        // Large residual: keep bins flexible.
        score -= 8.0;
    } else {
        // Mostly-empty bin: great for future large items.
        score -= 10.0;
    }

    // --- Integer-division thresholds: residual / next_item lookahead ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Can the next item fit exactly into this post-residual? Strong reward.
        if next_item_size <= post_residual {
            let k = (post_residual / next_item_size) as f64; // integer division: how many next-items fit
            score -= 10.0 * k.min(3.0);
            // Exact harmonic match: post_residual is an integer multiple of next_item_size.
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to how far off it is.
            score += 6.0 * ((nxt - pr) / cap).min(0.5);
        }
        // Modulo-class coupling: if next item's size class matches this bin's
        // residual class (same 10-unit band), the bin is likely reusable.
        if (next_item_size / 10) == (post_residual / 10) && post_residual > 0 {
            score -= 5.0;
        }
    }

    // --- Last-chance logic: only one fitting bin remains ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Using the last available bin avoids opening a new one.
        score -= 20.0;
        // Extra reward if the placement leaves a "clean" residual class.
        if post_residual == 0 || post_residual >= half as u32 {
            score -= 8.0;
        }
    }

    // --- Stream progression: early on, prefer consolidating into few bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln_1p();
    // Reward bins whose residual is below the mean (tighter packing).
    score -= 6.0 * (1.0 - progress) * (mean_residual - pr) / cap;
    // Penalize spreading across many bins early in the stream.
    score += 3.0 * consolidation * (pr / cap);

    // --- Fine harmonic bonus: post_residual divisible by common item classes ---
    if post_residual > 0 {
        let mut div_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                div_bonus += 2.0;
            }
        }
        score -= div_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size (1..~10)
    // are effectively wasted, so strongly penalize residuals in the dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward heavily
        score -= 40.0;
    }

    // Penalize post_residuals that cannot fit a plausible next item
    // (lookahead coupling): if next item cannot fit in the gap, the gap is dead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Reward filling bins tightly when many bins are open (bin pressure)
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild pressure against opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    // Late in the stream, prefer tighter packing to finish cleanly
    let progress = step_index as f64 / total_items as f64;
    score -= fill_ratio * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (item_size as f64);

    // 2-step lookahead: reward if the next item exactly fits the post_residual,
    // penalize if next item cannot fit but post_residual is small-ish dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: dead space penalty grows with leftover size
            score += 0.3 * post_residual as f64;
        }
    } else {
        // last item: strongly prefer minimal leftover
        score += 1.0 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0; // default: prefer existing bins
        if item_size >= 60 {
            score -= 15.0; // large items start fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference to fill bins with residual below mean (compactify).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in stream: be more willing to open bins (diversify).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 5.0;
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to keep flexibility.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        if mean_fit_gap > 30.0 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // Discourage opening new bins early/mid stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 15.0 + 20.0 * (1.0 - progress);
        }
    }

    // Global load balancing: prefer bins with residual near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;
    }

    // Penalize spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 8.0 * (norm_pr * norm_pr) * (1.0 + progress);
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize dead space relative to mean residual, smoothed by progress
    score += 3.0 * (pr - mean_residual) / cap * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - gap * gap).max(0.0);
    }

    // Last-chance fitting bonus, stronger later in the stream
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.3 + 0.7 * progress);
    }

    // Mild congestion penalty to prefer opening new bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_item * 2.0;

    // Slight preference for tight fits at the end of the stream
    score -= 4.0 * norm_item * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create dead-space classes.
    let residue = post_residual % 10;
    // Penalize "awkward" residues that rarely match future item sizes (1..100 unknown).
    // Residues near 0 (perfect fit) are great; large residues (7,8,9) are near-next-class dead space.
    let residue_penalty = match residue {
        0 => -30.0,                      // perfect fit class
        1 | 2 => 2.0,
        3 | 4 => 5.0,
        5 | 6 => 8.0,
        7 | 8 => 12.0,
        _ => 15.0,                       // 9: worst near-miss class
    };
    score += residue_penalty;

    // Integer-division thresholds on post_residual: how many half-capacity chunks remain.
    let half_chunks = post_residual / (bin_capacity / 2);
    let quarter_chunks = (post_residual % (bin_capacity / 2)) / (bin_capacity / 4);
    // Fewer usable chunks = worse bin; reward bins retaining at least one half-chunk.
    score -= 20.0 * half_chunks as f64;
    score -= 6.0 * quarter_chunks as f64;

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to post_residual
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * ratio;
        } else {
            // next item cannot use this residual: penalize proportion of wasted space
            let waste = post_residual as f64 / cap;
            score += 18.0 * waste;
        }
    } else {
        // Last item: any residual is pure waste; prefer tightest fit only.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and current residuals are fragmented.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / cap;
        // Base reluctance to open new bins, offset by item size and fragmentation.
        score = 0.55 * cap;
        score -= 40.0 * item_ratio;
        // Fragmentation signal: mean residual high & many open bins -> prefer fresh bin.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (mean_residual / cap) * (open_bins_count as f64).sqrt() * (0.5 + progress);
        // If item is small, opening a bin is wasteful.
        if item_ratio < 0.4 {
            score += 25.0;
        }
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight preference for fuller bins overall (tight packing pressure).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    // A post_residual that cannot fit the next item (or the minimum item size 1..10)
    // is likely stranded; penalize it nonlinearly.
    let min_item = 1u32;
    let next_ref = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < next_ref {
        // Gap too small for the lookahead: heavy penalty scaled by how close it is to zero.
        let dead = next_ref - post_residual;
        score += 30.0 + (dead as f64) * 2.0;
    }
    if post_residual < 10 {
        // Classic unusable dead space under the minimum item size.
        score += 25.0 + (10 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward: exact fill leaves zero waste.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, tolerate opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        // Existing bin: reward using it more when pressure is high.
        score -= pressure * 5.0;
    } else {
        // New-bin candidate: penalize proportional to pressure so we only
        // open new bins when fits into open bins are truly bad.
        score += pressure * 8.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this placement (sets up a chain of tight fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 15.0;
        } else if slack < 10 {
            score -= 8.0;
        }
    }

    // Mean-residual alignment: prefer bins whose post residual stays near
    // the mean residual of open bins (keeps the fleet balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Late in the stream, tighten up: less tolerance for waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the leftover exactly (or nearly)
    // accommodates the next item -> chain of two placements in one bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leftover dead space that is too
        // small to be useful (below the minimum plausible item size).
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Exact 2-item fill is golden: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good candidates to keep filling; loose bins should absorb big items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Penalize opening new bins when plenty of open bins exist and the fit is
    // reasonable; brand-new empty bin gets a mild handicap so only genuinely
    // poor fits trigger bin opening.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Late in the stream, tighten up: avoid leaving unusable fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but heavily reward exact/near-exact fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress and congestion
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
        score = bin_capacity as f64 - 20.0 + progress * 10.0 + congestion * 2.0;
        // If the next item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // If only one bin fits the item, never open a new bin.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    // Mild preference for filling bins that are already more depleted than average.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Strong preference for tight fits: quadratic in normalized post-residual
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate loose fits (keep residuals flexible); late, demand tightness
    score += 25.0 * norm_pr * progress * (1.0 - progress + 0.25);

    // Reward bins whose residual after placement can host the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = 1.0 - ((pr - nxt) / cap).min(1.0);
            score -= 15.0 * slack_fit * (1.0 - progress);
        } else {
            // dead space for the known next item
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Penalize opening a new bin when plenty of open bins can still fit the item
    if bin_residual == bin_capacity {
        let fit_frac = if open_bins_count > 0 {
            fitting_bins_count as f64 / open_bins_count as f64
        } else {
            0.0
        };
        score += 30.0 * (1.0 - progress) * (0.5 + fit_frac);
        // but allow new bin late in stream if mean residual is fragmented
        score -= 10.0 * progress * (mean_residual / cap).min(1.0);
    } else {
        // mild reward for consolidating into already-open bins
        score -= 3.0 * (item_size as f64 / cap);
        // prefer bins below mean residual (denser bins)
        score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let q = bin_capacity / 4;
    let class = post_residual % q;
    // Reward residuals that fall in "usable" harmonic classes (small or near-half)
    if class <= q / 2 {
        score -= 6.0 * (1.0 - class as f64 / (q as f64 / 2.0));
    } else {
        score += 3.0 * (class as f64 - q as f64 / 2.0) / (q as f64 / 2.0);
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Next-item lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.15 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 0.5 + 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Discourage fragmenting bins with large residuals when item is small
    if item_size < bin_capacity / 4 && post_residual > bin_capacity / 2 {
        score += 10.0;
    }

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Tie-break toward bins below mean residual (tighter bins)
    score += 0.5 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it can't hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 15 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 15.0;
            } else {
                score += slack * 0.3;
            }
        } else {
            // next item can't use this gap: dead-space penalty proportional
            score += (post_residual as f64) * 0.2;
        }
    }

    // Open-bin pressure: discourage proliferation of bins with scattered residual.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins below mean residual (consolidate space).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Prefer fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Early stream: be slightly more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when the item is large or fit is exact.
        let exact = (bin_capacity - item_size) == post_residual;
        if item_size >= 50 || exact {
            score -= 10.0;
        } else {
            score += 8.0;
        }
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins where item leaves near-zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt == pr {
            score -= 800.0;
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 250.0 - (pr - nxt) * 10.0;
        } else if pr < nxt && pr >= 1.0 {
            // residual too small for next item: penalize dead space proportionally
            score += (nxt - pr) * 2.0;
        }

        // If next item could fill this bin's residual but this bin can't fit it later,
        // slightly discourage leaving awkward gaps.
        if pr > 0.0 && pr < nxt && pr < 20.0 {
            score += (20.0 - pr) * 1.5;
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual > 0 {
            score += 50.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter",
    // prefer packing into tighter bins (best-fit flavor) but avoid creating tiny slivers.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (bin_residual as f64) > mr {
        score += ((bin_residual as f64) - mr) * 0.8;
    } else {
        score -= (mr - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 400.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild penalty to encourage discrimination among fits.
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 150.0;
        // But if current item is large relative to capacity, opening a fresh bin
        // avoids fragmenting an existing bin's usable residual.
        let large_item = (item_size as f64) / (bin_capacity as f64) > 0.6;
        let poor_fit = post_residual > 0 && (post_residual as f64) < 15.0;
        if large_item && poor_fit {
            score -= 350.0;
        }
        // Late in the stream, prefer closing out bins tightly rather than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress > 0.8 {
            score += 100.0;
        }
    }

    // Mild preference for bins that will become nearly full (low post residual
    // relative to capacity) — standard best-fit shaping with a non-linear touch.
    let pr_norm = (post_residual as f64) / (bin_capacity as f64);
    score += pr_norm * pr_norm * 60.0;

    // Slight scaling by number of open bins: many open bins -> consolidate.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Strongly reward exact or near-exhausting placements.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if post_residual is large but next item cannot use it, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral score with slight preference when
    // no open bin fits well or open-bin residuals are fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if mean_residual > item_size as f64 * 2.0 {
            score += 15.0; // plenty of slack elsewhere; avoid opening
        }
        // Late in stream, prefer reusing open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        return score;
    }

    // Prefer filling already-open bins over spreading; slight pressure by
    // number of open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual close to item (best-fit flavor) globally.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.2;

    // Coupling with mean residual: bins far below mean are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate slack; later, demand tight fits.
    let tightness = 1.0 + 2.0 * t * t + 1.5 * t * t * t;
    score += 6.0 * fit_norm * fit_norm * cap * (tightness - 1.0);

    // Reward near-perfect fits smoothly (small post_residual quadratically).
    score -= 4.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 + t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * t;
    }

    // Prefer bins whose residual is below the mean (already tight bins).
    score += 0.15 * (pr - mean_residual) * (1.0 + t);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement;
    // if post-residual is just barely too small for the next item, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (pr - nxt) / cap) * (1.0 + t);
        } else {
            score += 2.0 * (nxt - pr) / cap * (1.0 + t);
        }
    }

    // Mild penalty for proliferation of open bins.
    score += 0.02 * open_bins_count as f64 * (1.0 + t);

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when open bins would create large unusable residuals.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * fit_norm * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New empty bin candidate: mild baseline so it only wins when open bins are bad fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Reward tight fits (small post_residual) with a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Harmonic class logic on post_residual: perfect leftovers get big rewards.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // exact fill
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr % 10 == 0 {
        score -= 15.0; // decile-aligned leftover is reusable
    } else if pr % 5 == 0 {
        score -= 8.0;
    } else if pr < 10 {
        score += 25.0; // dead space under 10 is nearly unusable
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr && pr - next_item_size <= 5 {
            score -= 18.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if next_item_size > pr {
            score += 12.0; // next item won't fit here anyway
        }
        // Harmonic class match: same decade family as the item just placed.
        if next_item_size / 10 == item_size / 10 {
            score -= 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Penalize scattering across many open bins; encourage consolidation.
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins with residual below the mean (denser bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Integer division thresholds on residual: coarse capacity classes.
    match bin_residual / 25 {
        0 => score -= 6.0,   // nearly full bin, finish it off
        1 => score -= 2.0,
        2 => score += 1.0,
        _ => score += 4.0,   // mostly empty bin, save it for big items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no plausible item can fill.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let min_item = 1.0f64;
        // Gap too small for even the smallest item is pure waste -> heavy penalty.
        if gap < min_item {
            score += 1000.0;
        } else {
            // Dead-space pressure grows as gap shrinks relative to typical item sizes.
            let waste_factor = 1.0 / gap.sqrt();
            score += 8.0 * waste_factor;
        }
        // Non-linear penalty for gaps in the "awkward" range (1..=20) that few items fit.
        if post_residual <= 20 {
            score += (21.0 - post_residual as f64) * 2.5;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward filling a bin tightly (high fill ratio of residual used).
    let use_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * use_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = open_bins_count as f64 * (1.0 + 2.0 * progress);
    if bin_residual == bin_capacity {
        score += 30.0 + new_bin_penalty;
        // But allow new bin if all existing fits would leave large dead space
        // (handled implicitly since dead-space penalties add to open bins too).
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Penalize if post-residual is smaller than next item but nonzero (blocks next item).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mild tie-break: prefer bins with residual below mean (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here afterwards -> strong reward
            score -= (bin_capacity as f64 - diff) * 0.6;
        } else {
            // next item won't fit after this placement -> penalize
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // perfect two-item chain bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize unusable dead space relative to typical item sizes
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Tight fit reward: small post residual is good
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Compare against mean residual: prefer bins with less residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New bin candidate: penalize mildly so it's chosen only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if next item is huge and nothing fits well, opening fresh can help
        if next_item_size > 50 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Stream progression: early on, be more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable gap
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // extra reward for near-exact two-item chain
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 40.0;
        // Opening a new bin is more attractive if existing residuals are small.
        new_bin_score -= (mean_residual / 10.0).min(20.0);
        // Late in stream, consolidate more; early, allow expansion.
        new_bin_score += 10.0 * progress;
        // If many bins already open, penalize opening yet another.
        new_bin_score += (open_bins_count as f64).min(15.0);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= item_size {
            new_bin_score -= 5.0;
        }
        score += new_bin_score;
    } else {
        // Reusing existing bins: slight reward scaled by how full the bin already is.
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * fill_ratio;
        // Divergence from mean residual: prefer bins near average to balance load.
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * diff;
    }

    // Mild noise-free time modulation: early on, be slightly pickier about fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (small post_residual) but keep flexibility.
    // Late: strongly prefer minimal post_residual to seal bins.
    let poly = base * base * (1.0 - progress) + base * base * base * progress;
    let mut score = pr * (0.4 + 1.6 * poly);

    // Reward near-perfect fills with a smooth quadratic bonus.
    let fill = 1.0 - base;
    score -= 18.0 * fill * fill * fill;

    // Lookahead coupling: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.2 + progress);
        } else {
            let waste = pr - ns;
            score -= 6.0 * (-waste / (cap * 0.35)).exp();
        }
    } else {
        // Last item: close bins aggressively.
        score -= 10.0 * fill;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize when this bin's residual deviates from mean (fragmentation signal),
    // smoothly weighted by number of open bins.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Mild pressure to use existing bins as stream progresses.
    score += progress * 3.0 * (pr / cap);

    // New-bin candidate: penalize slightly unless residual would be very small
    // relative to capacity (i.e., item is large).
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - item_size as f64 / cap) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod 10 determines
    // how "reusable" the dead space is for typical item sizes.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.7; // penalize non-aligned leftovers

    // Perfect fit / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Small leftovers are dangerous dead space; large leftovers are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item fits exactly in a harmonic class sense.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.4 * slack.max(0.0).min(20.0);
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the current fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = if open_bins_count > 0 { mean_residual } else { cap };
        let poor_fit = post_residual as f64 > 0.5 * cap; // item tiny relative to bin
        if avg_open < item_size as f64 * 1.2 || poor_fit {
            score -= 15.0 + 20.0 * progress;
        } else {
            score += 25.0;
        }
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins)
    // unless this placement is exact.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Integer-division threshold on post_residual: bucket the leftover into
    // capacity tenths and prefer bins whose bucket stays high.
    let tenth = post_residual / 10;
    score -= tenth as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 - (post_residual as f64) * 4.0; // tiny gap => worst
        } else if post_residual <= 20 {
            score += 18.0 - (post_residual as f64) * 0.5;
        } else {
            score -= (post_residual as f64 - 20.0) * 0.3; // larger usable residual rewarded
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Coupling: dead space penalty amplified when few bins can fit the item
    // (last-chance bin => avoid creating waste here).
    if fitting_bins_count <= 1 && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: many open bins => prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 + 0.4 * progress);

    // Mean-residual coupling: if this bin is below average residual, it is a good filler.
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot fit: residual becomes dead space for the future
            score += (post_residual as f64) * 0.15;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit_exists = fitting_bins_count > 0 && (mean_residual < 15.0);
        if bad_fit_exists {
            score -= 5.0; // open new bin rather than wreck a nearly-full bin
        } else {
            score += 40.0; // default: discourage opening new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect chain fit: strong reward.
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: partial reward scaled by how well it fills.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - fill_after / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize wasted space relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // Bonus if post_residual accommodates next item with little slack.
        if next_item_size <= post_residual {
            let slack = post - nxt;
            if slack < 10.0 {
                score -= 8.0;
            }
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates well.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (post_f - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize leaving dead space that is too small for typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_f / (bin_capacity as f64));

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        score += 15.0 + poor_fit;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Penalize dead space: very small post_residual that likely becomes waste,
    // unless the next item can use it (lookahead coupling).
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Next item fits exactly into the leftover: strong reward.
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * gap;
        } else {
            // Leftover unusable by lookahead: penalize small residuals.
            let t = post_residual as f64 / bin_capacity as f64;
            score += 14.0 * (1.0 - t) * (1.0 - t);
        }
    } else {
        // Perfect closure of the bin.
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty so the best-fit among many wins.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate (bin_residual == bin_capacity): neutral-ish score so it
    // only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.15 * next_item_size as f64;
        }
        // Many open bins with high mean residual: avoid spreading further.
        score += 0.05 * open_bins_count as f64 + 0.08 * mean_residual;
    } else {
        // Prefer bins below the mean residual (fill emptier bins first, keeping
        // tight bins for tight fits is handled by post_residual anyway).
        let dev = mean_residual - bin_residual as f64;
        score += 0.06 * dev;
    }

    // Slight late-stream tightening: as the stream ends, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let size = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with non-linear (quadratic) coupling.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth reward for tight fits: normalized fill ratio coupled with progress.
    let fill = size / cap;
    score -= 18.0 * fill * (1.0 + progress);

    // Non-linear penalty on leaving dead space that nothing typical can use:
    // dead-space danger grows as post_residual shrinks relative to small item sizes.
    let tiny = (post / cap).powi(3);
    score += 40.0 * tiny * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 6.0 * ((-gap) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation early on).
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a moderate default score,
    // slightly reduced late in the stream.
    if bin_residual == bin_capacity {
        score = cap * (0.85 - 0.25 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // accommodate any plausible future item. Classify via modulo classes.
    let progress = step_index as f64 / total_items as f64;

    // Penalize tiny dead space (wasted capacity) more than generous leftovers.
    if post_residual > 0 {
        let class = post_residual % 10;
        // Residuals in classes 1..9 that are < 10 are pure waste.
        if post_residual < 10 {
            score += 25.0 - 2.0 * class as f64;
        }
        // Harmonic tier: reward residuals that are multiples of 10 (divisible
        // capacity fractions align with common item sizes).
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        // Integer-division thresholds: residual >= 40 keeps room for medium items.
        if post_residual / 10 >= 4 {
            score -= 4.0;
        }
        // Exact-fit reward.
        if post_residual == 0 {
            score -= 15.0;
        }
    } else {
        score -= 15.0;
    }

    // Lookahead coupling: penalize if the next item cannot fit the post residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
        } else {
            // Reward if next item would leave a multiple-of-10 residue too.
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // or when the current bin's post residual is unusably small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of a fresh bin: waste of (capacity - post_residual) = 0
        // here, but discourage when open bins could still absorb the item well.
        score += 10.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // Allow new bin late in the stream when mean residual is fragmented.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
    }

    // Mild pressure toward tight fits overall.
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (<10, minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly larger but awkward gaps (10..20) are semi-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it enables a great pair with the next item,
    // or when open bins are congested (high mean residual usage pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
        // Base cost of opening a new bin, discounted by stream progress and congestion.
        score += 55.0 - 15.0 * progress;
        // If next item would perfectly fill the remaining space of this item, new bin is great.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 50.0;
            }
        }
        // Under congestion, opening a fresh bin is cheaper.
        score -= congestion.min(10.0) * 2.0;
    }

    // Mild pressure: prefer filling already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a great chain placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how much would remain after.
        let after_next = post_residual - next_item_size;
        score -= 50.0 - after_next as f64 * 0.5;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; dead space is less costly, but
        // penalize leaving a residual too small to be useful for typical items.
        if post_residual < 10 {
            score += 100.0;
        }
    }

    // Penalize residuals that no realistic item (>=1) can use well:
    // small dead space is waste; compare against mean residual of open bins.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Late in the stream, prefer closing bins out rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New empty bin candidate: penalize unless current item is large or
    // no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size >= 70 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 0.35 * (next_item_size as f64 - dead).min(30.0);
        }
        // Reward residuals that can still host a mid-size chunk.
        if dead >= 20.0 {
            score -= 2.0;
        } else {
            score += (20.0 - dead) * 0.6; // small unusable slivers penalized
        }
    } else {
        score -= 12.0; // perfect fill
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) < post_residual {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    let consolidation = mean_residual / (bin_capacity as f64);
    if consolidation > 0.5 && open_bins_count > 2 {
        score -= 3.0 * consolidation;
    }

    // Time horizon: early in the stream, prefer opening fresh bins for large items;
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: open early or for large items, resist late for small items.
        let bias = 6.0 + 10.0 * (1.0 - progress) + 0.12 * (item_size as f64);
        score += bias;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity - item_size {
            score -= 5.0; // new bin leaves room for lookahead
        }
    } else {
        score -= 4.0 * progress; // late stream: favor existing bins
    }

    // Mild penalty when this bin is much emptier than average (avoid scattering).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (bins can absorb future items); late, penalize waste strongly.
    let progress_coupling = 1.0 + 1.5 * progress * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Penalize post_residual that is small but nonzero (dead space) using smooth bump
    if pr > 0.0 {
        let dead = (pr / cap) * (1.0 - pr / cap);
        score += 12.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_quality = 1.0 - (pr - ni) / cap;
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Slight preference to fill bins with larger residuals relative to the mean
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bin mildly attractive only early, costly later
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (residual 0) are best,
    // small residuals (<10) are dead space, mid residuals are reusable slots.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score += 20.0;
    } else if post_residual <= 15 {
        score += 8.0;
    }

    // Reward residuals that lie in "harmonic" classes: multiples of common
    // item sizes (10,20,25,50) are more likely to be filled later.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 4.0;
    }
    if r % 50 == 0 && r > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to
            // how much of the residual becomes stranded.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // fit into open bins is poor. Penalize the fresh bin mildly so that
    // decent fits win, but allow it when the placement creates lots of
    // dead space elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large relative to capacity, opening fresh
        // space can be fine: reduce the penalty a bit.
        if item_size * 2 >= bin_capacity {
            score -= 4.0;
        }
        // Early in the stream, having few bins, opening new ones is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates below the mean (tighter bins
    // get closed out, consolidating open bins).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to consolidate: many open bins -> favor tighter fits.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (items are >= 10 per the classic regime, but guard for 1..100 items too:
    // gaps below the smallest plausible item are wasted capacity).
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        // Heavily penalize creating an unusable sliver.
        score += (dead_threshold - post_residual as f64 + 1.0) * 40.0;
    }

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits: the smaller the gap relative to the bin, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Reward filling a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placing into bins when many bins are already
    // open, but only mildly — we prefer compacting into existing bins, so this
    // actually discourages the new-bin candidate when open_bins_count is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive if the item would leave a large,
    // awkward residual in every existing bin, or if no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Attractive if the item is large (it will use most of the new bin).
        score -= (item_size as f64 / bin_capacity as f64) * 18.0;
        // Unattractive when plenty of existing bins could take the item.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // Lookahead: if next item could combine with current item's residual,
        // opening a fresh bin is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    } else {
        // Existing bin: bonus if the leftover can host the lookahead item,
        // enabling a perfect two-item packing.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Leftover too small for next item: mild penalty, potential dead space.
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (compact the small-residual bins first, keep big-residual bins flexible).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
