pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual that is unlikely usable later.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dead = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64 * 2.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits (small post_residual) more aggressively.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else if next_item_size <= bin_residual {
            // next item fits this bin but not after current placement: penalize
            score += 4.0;
        }
        // perfect pair: item + next fills bin exactly
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps spread even),
    // but prefer bins above mean when many bins are open (consolidate).
    let dev = bin_residual as f64 - mean_residual;
    if open_bins_count > 3 {
        score += 0.05 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Early stream: favor opening/using fresh space less; late stream: squeeze tightly.
    score += t * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference against opening new bins when reasonable fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling: post_residual warped by stream progress
    let warp = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = pr * (1.0 + 0.15 * warp * fill * fill);

    // Penalize residual that is polynomially "dead" (small but nonzero)
    let deadness = (1.0 - pr / cap) * (1.0 - pr / cap);
    score += 8.0 * deadness * (1.0 - fill);

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0 + 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating many open bins
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it slightly costly unless residual space is scarce
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod small moduli identifies
    // "good" leftover sizes that other items can still fill.
    let pr = post_residual;
    let r4 = pr % 4;
    let r10 = pr % 10;
    let r20 = pr % 20;

    // Reward residuals that are multiples of 10 or 20 (likely complements).
    if pr > 0 {
        if r10 == 0 { score -= 6.0; }
        if r20 == 0 { score -= 4.0; }
        if r4 == 0 { score -= 1.5; }
        // Penalize awkward residues (1..3 mod 10) that create dead space.
        if r10 >= 1 && r10 <= 3 { score += 2.0 + (3 - r10) as f64; }
        // Very small unusable leftovers are dead space.
        if pr < 5 { score += 12.0; }
        else if pr < 10 { score += 5.0; }
    } else {
        // Perfect fit is best.
        score -= 20.0;
    }

    // Exact-fill lookahead: if next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == pr {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits: mild reward scaled by how well it fills.
        let fill_frac = next_item_size as f64 / pr as f64;
        if fill_frac > 0.8 { score -= 4.0; }
        else if fill_frac < 0.2 { score += 2.0; }
        // Harmonic check: does next item land post-residual on a multiple of 10?
        if (pr - next_item_size) % 10 == 0 { score -= 2.0; }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize large wasted residuals.
        score += 0.05 * (pr as f64 - next_item_size as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Tight-fit bonus: item occupies most of the bin.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 { score -= 3.0; }
    else if tightness < 0.4 { score += 1.0; }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good fit (i.e., best open fit would leave large dead space) or the
    // item is huge relative to capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; discount when item is large.
        score += 8.0 - 0.05 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Next item can pair with this item in a fresh bin: reward pairing.
            let pair_sum = item_size + next_item_size;
            if pair_sum >= bin_capacity { score -= 12.0; }
            else if (bin_capacity - pair_sum) % 10 == 0 { score -= 3.0; }
        }
        // Early in stream, allow more bins (exploration).
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 2.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier space).
    score += 0.02 * (mean_residual - bin_residual as f64).max(0.0);

    // Tie-break: prefer fewer open bins being used efficiently.
    if open_bins_count > 0 {
        score += 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (items are >= 1, and typical sizes are much larger), so penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0;
    }

    // If the lookahead item cannot fit into the resulting gap, the residual
    // is likely to become permanent dead space: penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Last-chance pressure: if this is the only open bin that can fit the
    // item, using it avoids opening a new bin — reward strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (bin_residual == bin_capacity):
    // base score already equals post_residual (large for small items).
    // Add extra penalty when other open bins could fit the item, and scale
    // by how poorly the item fills a fresh bin.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - fill_ratio);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate into existing bins as the open-bin count grows.
    score += open_bins_count as f64 * 0.05;

    // Slight early-stream bias toward keeping bins tidy (tight fits) since
    // many items remain; later, accept looser fits to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already rewarded).

    // 2-step lookahead: reward when the next item exactly fills post_residual
    // (perfect chaining), penalize when next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits into the gap
            score -= (item_size as f64) * (1.0 - slack / bin_capacity as f64) * 0.5;
        } else {
            // next item cannot use the gap: gap becomes dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Relative to mean residual: prefer bins below-average residual (denser bins),
    // penalize dipping into already-fragmented bins.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.1; // mild bonus for below-mean residual
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it costly unless it enables a perfect chain
    // (empty bin + item + next item == capacity).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (item_size + next_item_size) >= bin_capacity {
            score -= 70.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in the stream, avoid opening new bins lightly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild penalty for creating very small unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer fewer open bins overall (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: post_residual too small to fit typical future items
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about loose fits
        score += tightness * 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // penalize leaving awkward gap relative to next item
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 10 {
                score += gap as f64 * 1.5;
            }
        } else {
            // next item won't fit here anyway; slight reward for using this bin now
            score -= 4.0;
        }
    }

    // Global state: prefer filling bins when many are open (reduce fragmentation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Compare against mean residual: bins below mean residual are "emptier",
    // favor placing into emptier bins to consolidate
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open a new bin late in stream or when open bins are nearly full
        score -= progress * 20.0;
        score -= mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mild time-horizon shaping: early on, be conservative (avoid waste), later be aggressive
    score += (1.0 - progress) * tightness * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, large residuals are fine (bins stay flexible); late, we
    // want tight fits, so penalize residual more as progress grows.
    let mut score = pr * (1.0 + 2.5 * progress * progress);

    // Cubic smooth term: reward very small residuals (good fits),
    // penalize mid-range dead space super-linearly.
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Reward using nearly-full bins (post_residual near 0) more as stream advances.
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item would leave a very tight residual elsewhere.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let tightness = 1.0 - (pr / cap);
        score += 15.0 - 12.0 * tightness * tightness;
    }

    // Lookahead coupling: if the next item could fit in the post-residual,
    // reward this placement (keeps bin useful for the following item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 4.0 * progress;
        }
    }

    // Mild penalty when this bin's residual is far from the mean (outliers waste space).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions (integer division thresholds).
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;   // 25
    let half = bin_capacity / 2;      // 50
    let third = bin_capacity / 3;     // 33

    // Dead-space penalty: tiny leftovers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < quarter {
        score += 25.0;
    } else if post_residual < third {
        score += 10.0;
    } else if post_residual < half {
        score += 4.0;
    }

    // Modulo-10 harmonic class: leftovers that are multiples of 10 are
    // reusable by typical item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    // Multiples of 5 are second-best.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (two-item chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a residue: grade by that residue's class.
            let r2 = post_residual - next_item_size;
            score -= 40.0 - (r2 as f64) * 0.5;
            if r2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much space would be wasted.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < half {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual. Make it
    // moderately attractive only when the current bin would leave a bad
    // residue class (odd, tiny, or > half wasted).
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: keep it slightly worse than a good fit
        // but better than a bad fit in an open bin.
        score = 0.35 * cap;
        if item_size % 10 == 0 {
            score -= 10.0; // round items start bins cleanly
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // room for the lookahead item
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If many bins are open and one fits, discourage new bins.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        return score;
    }

    // Tie-break by tightness relative to the fleet mean residual: prefer
    // bins tighter than average (concentrate waste).
    let tightness = (mean_residual - bin_residual as f64) / cap;
    score += 20.0 * tightness;

    // Slight preference for bins with larger residual when item is large.
    if item_size > half {
        score -= 0.1 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps that cannot fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty scaled by how unusable the gap is relative to capacity.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.0 && gap_ratio < 0.15 {
        score += 40.0 * (0.15 - gap_ratio);
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that (chained dead space)
            let chain_left = post_residual - next_item_size;
            score -= 150.0 - (chain_left as f64).min(150.0);
        } else {
            // next item does NOT fit this bin's remainder: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 1.5;
        }
    }

    // Penalize tiny unusable residuals (dead space < smallest plausible item).
    if post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer using existing bins over opening new ones when fit is decent;
    // make the empty new-bin candidate less attractive unless item is huge.
    if bin_residual == bin_capacity {
        score += 80.0 + (item_size as f64).max(0.0) * 0.5;
    }

    // Slight preference for tighter bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

