    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 8.0 * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item can fit into the post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't chain here; penalize proportionally to leftover waste.
            let waste = post_residual as f64;
            score += 0.3 * waste;
            // If next item fits exactly nowhere else well, prefer bins leaving rounder space.
            if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins when few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
