    }

    // Global state coupling: if mean residual is large, prefer consolidating into fuller bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item relative to mean residual, or many fragmented bins).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base new-bin score: fresh capacity minus a penalty that grows with progress.
        let mut new_bin_score = bin_capacity as f64 - item_size as f64;
        new_bin_score += 25.0 * desperation;
        new_bin_score += 10.0 * progress;
        // If the item is large and would leave a useless sliver in an open bin, opening is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 8.0;
        }
        // If next item pairs with the leftover of this item, opening a fresh bin is good.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual and item size
    let pr_n = pr / cap;
    let it_n = it / cap;

    // Non-linear polynomial coupling: small residuals are only acceptable late in the stream
    let tightness = (pr_n - 0.15) * (pr_n - 0.15) * (1.0 + 3.0 * progress);
    score += 40.0 * tightness;

    // Reward near-perfect fits with a smooth quadratic bonus
    let perfect = (1.0 - pr_n) * (1.0 - pr_n);
    score -= 30.0 * perfect * it_n;

    // Penalize residuals that are too small to be useful for typical future items,
    // scaled by stream progress (dead space matters more later)
    let dead = (pr_n.max(0.0) * (0.35 - pr_n).max(0.0)).sqrt();
    score -= 20.0 * dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly in the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mean_n = mean_residual / cap;
    score += 5.0 * (open_bins_count as f64).ln().max(0.0) * (mean_n - pr_n).abs();

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fill and small-waste classes are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score -= 300.0; // near-perfect, dead space is negligible
    } else if post_residual <= 20 {
        score += 40.0; // moderate dead space
    } else {
        score += 80.0; // large residual left behind
    }

    // Residual divisible into useful classes (multiples of common item sizes)
    let harmonic = post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0;
    if harmonic && post_residual > 0 {
        score -= 60.0; // residual aligned with typical item granularity
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability reward, stronger the tighter the chained fit
            let chain_waste = post_residual - next_item_size;
            score -= 120.0 - (chain_waste as f64).min(120.0);
        } else {
            // next item cannot use this bin's residual: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
    score += crowd * 0.5 * (0.5 + progress);

    // New-bin candidate logic: an empty bin should only win when current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 200.0;
        // but if the item is large, a fresh bin is actually good (avoids fragmentation)
        if item_size > bin_capacity / 2 {
            score -= 220.0;
        }
        // early stream: opening bins is cheaper
        score -= 100.0 * (1.0 - progress);
    }

    // Prefer tightest fits overall: small post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Tie-break: prefer bins whose residual is close to mean (balanced packing)
    score -= (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 0.35 * (25.0 - post_residual as f64).powi(2) / 25.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to the next item: penalize proportional to gap.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    // to keep loose bins available for larger future items.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when it yields a
    // perfect fit potential (empty bin) and existing fits are poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral residual, but discouraged when open bins exist.
        score += 10.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late in stream: be more conservative, keep dead space minimal.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.4;
    }
    // Next item cannot follow: leftover becomes dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.35;
    }

    // Penalize tiny unusable residuals (dead space).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits relative to current mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.15;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.10;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - large_item * 45.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host both items cleanly
        }
    }

    // Late in stream: consolidate, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= 2.5 * tightness;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 2.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only if
    // current bin fits are poor (large post_residual) or no bins fit well.
    if bin_residual == bin_capacity {
        // Baseline competitiveness: slightly worse than a perfect fit,
        // better than mediocre fits.
        score = bin_capacity as f64 * 0.5;
        if next_item_size > 0 {
            // A fresh bin can host both current and next item comfortably.
            if item_size + next_item_size <= bin_capacity {
                score -= 5.0;
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage opening more.
        score += 0.4 * open_bins_count as f64;
    }

    // Global state coupling: if mean residual across bins is small,
    // bins are nearly full — prefer bins with larger residual (higher post_residual is fine),
    // otherwise prefer spreading into emptier bins.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.3 * residual_gap;

    // Prefer filling bins that are already partially used (reduce bin count pressure).
    if bin_residual < bin_capacity {
        score -= 1.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: reward small post_residual (tight fit), non-linearly.
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic/cubic shaping of the residual penalty.
    // Small residuals get extra reward (dead space is convexly bad).
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 40.0 * tightness * tightness * tightness;

    // Polynomial interaction between post_residual and stream progress:
    // early on, tolerate larger residuals; later, demand tight fits.
    let prog_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_coupling * 30.0 * norm_pr;
    score -= (1.0 - prog_coupling) * 10.0 * norm_pr;

    // Perfect-fit bonus, strengthened as stream progresses.
    if post_residual == 0 {
        score -= 25.0 + 20.0 * prog_coupling;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // partial reward scaled by how well next item uses leftover space
        let use_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 12.0 * use_ratio * use_ratio;
    }

    // Penalize bins whose residual is far below the mean residual (fragmented bins),
    // smoothly weighted by open bin count pressure.
    let frag = ((mean_residual - pr) / cap).abs();
    score += 8.0 * frag * frag * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: mild penalty so we prefer reusing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * prog_coupling;
        // allow opening a new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "clean" capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual by harmonic fraction of capacity
        let frac = pr / cap;
        let harmonics = [0.1f64, 0.2, 0.25, 0.3, 0.3333333, 0.4, 0.5, 0.6, 0.6666667, 0.75, 0.8];
        let mut best_h = f64::INFINITY;
        for h in harmonics.iter() {
            let d = (frac - h).abs();
            if d < best_h {
                best_h = d;
            }
        }
        // Reward proximity to harmonic fractions (usable space for future items)
        score -= 30.0 * (1.0 - best_h * 10.0).max(0.0);

        // Modulo classes: residuals divisible by common item sizes are more reusable
        let pr_u = post_residual;
        if pr_u % 10 == 0 { score -= 12.0; }
        if pr_u % 20 == 0 { score -= 6.0; }
        if pr_u % 5 == 0 { score -= 4.0; }
        if pr_u % 25 == 0 { score -= 3.0; }

        // Dead-space penalty: unusably small residuals (below typical min item size)
        if pr_u < 10 && pr_u > 0 {
            score += 40.0 + (10 - pr_u) as f64 * 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how snugly next item fits
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here regardless; slight penalty for large wasted residual
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current residual is very tight
    if bin_residual == bin_capacity {
        // Opening new bin: baseline cost; make it attractive only if item is large relative to open residuals
        score = 35.0 + item_size as f64 * 0.3;
        // If item is small, opening a new bin is wasteful
        if item_size < 40 { score += 25.0; }
        // If many bins are open with mean residual able to hold item, discourage new bin
        if mean_residual >= item_size as f64 { score += 60.0; }
        // Late in stream, prefer consolidating
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 { score += 20.0; }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Tie-break: slight preference for earlier-opened (fewer open bins context)
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual is only "useful" if it can hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // leaves room for the next item
        } else if post_residual > 0 {
            score += (post_residual as f64) * 1.5; // gap is likely dead space
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure from many open bins: encourage filling existing bins.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins with residual close to (or above) the mean residual to balance load.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Mild penalty for wasting a nearly full bin on a small item.
    if item_size < bin_residual / 3 && bin_residual < bin_capacity {
        score += 5.0;
    }

    // Early in the stream, tolerate opening bins slightly more (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless nothing good is available.
        score += 30.0 - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
