    // Prefer bins with residual close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins over time
    score -= progress * (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

