    // early on, prefer tight packing (low post_residual); later, tolerate spread.
    let prn = pr / cap;
    score += 18.0 * prn * prn * (1.0 - progress) - 6.0 * prn * progress;

    // Reward using space relative to mean residual across open bins.
    let mean_frac = mean_residual / cap;
    score -= 10.0 * (prn - mean_frac) * (prn - mean_frac) * (0.5 + progress);

    // Lookahead: bonus if next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
