        } else if next_item_size <= pr {
            let leftover2 = pr - next_item_size;
            // prefer residues that leave a well-structured remainder
            score -= 20.0;
            if leftover2 % 10 == 0 {
                score -= 6.0;
            }
            if leftover2 < 10 {
