    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Waste-relative-to-mean coupling
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild tie-break toward fuller bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure waste; residuals below the typical item
    // floor are near-waste. Penalize them super-linearly.
    if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space (below min item size) - heavy penalty.
        score += (10 - post_residual) as f64 * 40.0;
    } else {
        // Usable leftover: mild quadratic penalty scaled by tightness.
        let pr = post_residual as f64;
        score += 0.08 * pr * pr / 10.0;
    }

    // Reward tight fits: small post_residual relative to bin_residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // closing bins out when count grows.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if current bin would leave a bad gap AND the next item could use
    // the fresh capacity well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 60.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size as f64 <= (bin_capacity as f64 * 0.9) {
            new_bin_score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 80.0 * progress;
        // Compare against current placement quality.
        let bad_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        if bad_fit < 0.5 {
            // Current placement is decent; make new bin unattractive.
            new_bin_score += 150.0;
        }
        return new_bin_score;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward heavily; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        } else {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates
    // beneficially from the mean (below-mean residual = tighter bin).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match leaves zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 50.0 + 20.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 200.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: penalize proportionally to wasted capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste;
    }

    // Relative-to-mean residual shaping: prefer leaving residuals near the mean
    // (balanced bins), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer denser bins early; as stream progresses, be more tolerant of new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current item leaves a large residual
        // that likely fits future items, and few bins are open.
        score = 100.0 - 0.3 * post_residual as f64 - 2.0 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            // Post-residual can host the next item: strong reward.
            score -= 25.0;
        }
        // Bonus if next item exactly fits the post-residual.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by alternatives count.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with high mean residual -> discourage opening new bins,
    // prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already have slack.
        let slack_penalty = (mean_residual / bin_capacity as f64) * 60.0;
        score += 20.0 + slack_penalty * (1.0 - 0.5 * progress);
        // Late in the stream, opening new bins is even less attractive.
        score += 15.0 * progress;
    } else {
        // Reward placing into existing bins when mean residual is high.
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // Penalize creating residuals in the "awkward" zone (too big to waste, too small to be useful).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 6.0; // awkward zone
    }

    // Dynamic time horizon: early on, be conservative (penalize fragmenting large residuals);
    // late, prioritize closing bins tightly.
    if progress < 0.3 && post_residual > 40 {
        score += 8.0;
    } else if progress > 0.7 {
        score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Mild preference to balance across bins when many are open.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress.
    // Residual waste is penalized more sharply as the stream matures.
    let pr_norm = pr / cap;
    let waste_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += 40.0 * waste_penalty;

    // Reward tight fits: low post_residual gets a non-linear bonus.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize slightly so we only open when fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    // Lookahead: bonus if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 15.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let mean_gap = (mean_residual - pr) / cap;
    score += 5.0 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions.
    // Residuals in "small" classes (0..10, i.e. near-perfect fills) are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect / near-perfect fills: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Modulo-class coupling: residual mod 10; small residues are more reusable
    // by typical item sizes (multiples of 5/10 dominate many distributions).
    let residue_class = post_residual % 10;
    score -= (10 - residue_class) as f64 * 8.0;

    // Integer-division thresholds: how many "typical small items" (size 10)
    // could still fit into post_residual.
    let slots10 = post_residual / 10;
    score -= slots10 as f64 * 30.0;
    let slots20 = post_residual / 20;
    score -= slots20 as f64 * 20.0;

    // Dead-space penalty: residual that cannot host even the smallest item (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let fit_gap = post_residual - next_item_size;
            score -= 120.0 - fit_gap as f64 * 3.0;
        } else {
            // Next item won't fit here: penalize leaving large unusable gaps
            let overflow = next_item_size - post_residual;
            if overflow <= 10 {
                score += overflow as f64 * 6.0;
            } else {
                score += 60.0 + (overflow as f64 - 10.0) * 1.5;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are poor fits. Penalize opening a new bin progressively with stream length
    // and number of open bins, but relax if mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        let mean_r = mean_residual.max(0.0);
        // If open bins have plenty of room, opening a new bin is wasteful.
        let waste = (mean_r / cap).clamp(0.0, 1.0);
        score += 350.0 + open_pressure * 25.0 + progress * 100.0 - waste * 200.0;
        // Empty bin's raw residual is full capacity; neutralize that baseline so
        // the decision is governed by the terms above.
        score -= cap;
    }

    // Mild preference for tighter bins overall (waste-averse tie-breaking).
    score += (bin_residual as f64 / cap) * 15.0;

    // Small stochastic-free harmonic jitter via step parity classes to break ties
    // deterministically without randomness.
    let parity = (step_index % 3) as f64;
    score += parity * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a residual too small for the smallest plausible item,
    // scaled by the known item size range (1..=100).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0; // unreachable in practice, safe guard
    }
    // Dead-space zone: residual below a threshold that likely can't fit future items.
    // Use next_item_size lookahead: if the next item cannot use this gap, penalize hard.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_gap = (next_item_size - post_residual) as f64;
        score += 4.0 * dead_gap;
    }
    // General small-gap penalty: gaps below 25% capacity are likely dead space.
    let small_gap_threshold = bin_capacity as f64 * 0.25;
    if (post_residual as f64) < small_gap_threshold && post_residual > 0 {
        let gap_deficit = small_gap_threshold - post_residual as f64;
        score += 2.0 * gap_deficit;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual tightly matches the item (low waste relative to fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins rather than fragmenting; penalize new-bin candidate mildly.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well (large mean residual mismatch), allow new bin.
        if (mean_residual - item_size as f64).abs() > 30.0 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item fits into post-residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 5.0;
    }

    // Late-stream consolidation: as the stream progresses, tighten placement to
    // reduce fragmentation in the tail.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * post_residual as f64 / bin_capacity as f64;

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal leftover space after placement.
    let mut score = post;

    // ---- Aggressive 2-step lookahead coupling with next_item_size ----
    if next > 0.0 {
        if post == next {
            // Perfect two-item completion: this bin closes exactly with the next item.
            score -= 55.0 + 45.0 * progress;
        } else if post > next {
            // Leftover can host the next item: reward snug (small-gap) matches.
            let snugness = 1.0 - (post - next) / cap;
            score -= 18.0 * snugness * (0.5 + 0.5 * progress);
        } else {
            // Dead space: leftover too small for the next item -> penalize proportionally.
            score += 10.0 * (next - post) / cap * 10.0;
        }
    }

    // ---- Last-chance bin: only one open bin fits; strongly prefer using it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    score += (mean_residual - bin_residual as f64) * 0.15;

    // ---- New empty bin candidate ----
    if bin_residual == bin_capacity {
        // Cost of a new bin = immediate waste (capacity - item) plus opening overhead.
        score = (cap - item) + 6.0;
        if fitting_bins_count >= 1 {
            // An open bin could take it: penalize opening a new one,
            // more strongly early in the stream (keep bins open for future combos).
            score += 15.0 + 35.0 * (1.0 - progress);
        }
        if fitting_bins_count == 1 {
            // Never open a new bin when exactly one open bin fits.
            score += 80.0;
        }
        // If item nearly fills a fresh bin, opening is naturally attractive.
        score -= 10.0 * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    score -= 0.9 * (bin_residual - post_residual) as f64;

    // Penalize small dead space that nothing (min size 1) can use later:
    // nonlinear penalty growing as post_residual shrinks into "dead zone".
    let dead = (post_residual as f64) / bin_capacity as f64;
    score += 8.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if this item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin unless item is large relative to capacity.
        score += 20.0 * (1.0 - fit_ratio);
        // If many bins could fit the item, opening a new bin is wasteful.
        score += 3.0 * fitting_bins_count as f64;
        // Late in the stream, avoid opening bins for leftover fragments.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress * (1.0 - fit_ratio);
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * next_item_size as f64;
    }
    // If next item would leave this bin's post-residual as dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Prefer filling bins with below-average residual (balance / close out stragglers).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Prefer using more crowded bin sets (fewer bins overall).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post-residual, but dampened by smooth non-linear progress coupling
    let mut score = pr * (1.0 - 0.35 * progress * progress);

    // Non-linear polynomial coupling: small post-residuals are good (tight fit),
    // but dead space penalty grows quadratically with progress
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize residual that is unusable for typical items (quadratic dead-space term)
    let dead = if pr_norm > 0.0 { pr_norm * pr_norm } else { 0.0 };
    score += 20.0 * dead * (0.3 + 0.7 * progress);

    // Reward leaving room for the lookahead item when it can fit afterwards
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr) * (1.0 - (next_item_size as f64 / pr));
        score -= 8.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Lookahead cannot fit in the leftover: penalize more as stream progresses
        score += 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);

    // Smooth interaction: item size vs post residual cross-term
    score += 5.0 * item_norm * pr_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod small divisors
    // captures "how divisible" the leftover space is by common item sizes.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -40.0 // perfect closure: huge reward
    } else {
        let mut pen = 0.0;
        if pr % 10 == 0 { pen -= 6.0; }
        if pr % 20 == 0 { pen -= 4.0; }
        if pr % 25 == 0 { pen -= 3.0; }
        if pr < 10 { pen += 25.0; } // dead space below minimum item size
        if pr < 5 { pen += 15.0; }
        pen
    };
    score += class_penalty;

    // Tightness reward: fraction of bin used by this placement
    let tight = (item_size as f64) / cap;
    score -= 18.0 * tight;

    // Lookahead: if next item fits exactly in post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && next_item_size > 0 {
            let fit_frac = (next_item_size as f64) / (pr as f64);
            if fit_frac > 0.8 {
                score -= 12.0;
            } else if fit_frac < 0.25 && pr < 40 {
                score += 8.0; // would strand most of the residual
            }
        } else {
            // next item doesn't fit here; small residual left behind is worse
            if pr < 20 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let pressure = 30.0 * (mean_residual / cap) + 5.0 * crowded.sqrt();
        score += 60.0 - pressure - 10.0 * progress;
        // never open a new bin when a perfect/tight fit exists elsewhere
        if pr == 0 { score += 100.0; }
    }

    // Mild preference to spread across many open bins when mean residual is high
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are already unavoidable, but gaps that are unusable
    // for typical items create real waste. Penalize small-but-nonzero gaps
    // super-linearly.
    if post_residual > 0 {
        // A gap is "dead" if it is smaller than the next item or generally tiny.
        let tiny_gap = (post_residual as f64) / (bin_capacity as f64);
        score += (tiny_gap * tiny_gap) * 40.0;
    }

    // If the gap left behind cannot fit the next item, it is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading further
    // unless the fit is exceptionally tight.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Prefer bins whose residual is already close to the mean (balanced use),
    // penalize outliers that would become fragmented.
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15;

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well; give it a mild penalty so tight fits win, but
    // keep it competitive when all open fits would leave large waste.
    if bin_residual == bin_capacity {
        let waste_if_forced = if fitting_bins_count == 0 { 0.0 } else {
            // estimated waste of best alternative is unknown; use mean residual
            (mean_residual - item_size as f64).max(0.0)
        };
        score = 55.0 - waste_if_forced * 0.3 - pressure * 2.0;
        if post_residual == 0 { score -= 60.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 80.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 100.0;
        }
    }

    // Penalize residual far below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins that are already fuller.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize opening a new bin, unless current open bins have large residuals
    // (fragmentation) or the item is big relative to capacity.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let mut new_bin_penalty = 40.0 + 60.0 * (1.0 - fragmentation);
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 30.0; // new bin can still host next item: less bad
        }
        if item_size >= 80 {
            new_bin_penalty -= 30.0; // big items prefer a fresh bin
        }
        score += new_bin_penalty * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large dead space relative to item size (fragmentation risk).
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
        score += 15.0 * waste_ratio * waste_ratio;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item exactly complements the post residual.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Dead space that cannot host the next item is more costly.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (fitting_bins_count as f64).max(0.0);
        // Base cost of opening a new bin.
        score += 30.0;
        // If few bins fit, opening a new bin becomes more attractive.
        if pressure <= 1.0 {
            score -= 35.0;
        } else {
            score += 8.0 * (pressure - 1.0);
        }
        // Late in the stream, prefer closing out existing bins.
        score += 10.0 * progress;
        // If the item is large relative to mean residual, new bin may be better.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 1.5 {
            score -= 8.0;
        }
    }

    // Mild bonus for balancing residuals toward the mean across open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins that keep residual above typical small-item size.
    if post_residual < 10 && post_residual > 0 {
        score += 5.0; // tiny useless slivers are dead space
    }

    // Encourage filling bins completely as open bin count grows (bin consolidation).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize remaining residual, with non-linear polynomial shaping
    let mut score = pr;

    // Quadratic/cubic coupling of post_residual with stream progress:
    // early in stream, tolerate slack (open many bins); late, compress tightly.
    let slack_bias = norm_pr * norm_pr * (1.0 - progress) * 40.0;
    let tight_bias = norm_pr * progress * progress * 60.0;
    score += slack_bias;
    score -= tight_bias;

    // Cubic interaction: large post-residuals get progressively penalized
    score += norm_pr * norm_pr * norm_pr * 30.0;

    // Favor bins whose post-residual could host the next item (smooth reward)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx).max(0.0);
        let closeness = 1.0 - (fit_next / cap);
        score -= closeness * closeness * 25.0;
        // Penalize wasting a bin that fits next item exactly but leaves nothing
        let waste = (pr - nx).max(0.0) / cap;
        score += (1.0 - waste) * (1.0 - waste) * 10.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0 + 30.0 * progress;
    }

    // Reward bins with residual below mean (denser bins), smooth sigmoid-ish
    let dense = (mean_residual - pr) / cap;
    score -= dense * 20.0;

    // Mild penalty for many open bins relative to progress (bin count control)
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small divisors.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod20 = (pr % 20) as f64;

    // Penalize post-residuals that fall in "dead zone" classes (small awkward remainders).
    if pr > 0 {
        if pr < 10 {
            score += 25.0 - 2.0 * pr as f64; // unusable sliver
        } else {
            // fractional capacity classes: encourage post_residual landing on nice fractions
            let frac = pr as f64 / cap;
            let target = [0.0, 0.1, 0.2, 0.25, 0.3, 0.4, 0.5, 0.6, 0.75, 1.0]
                .iter()
                .map(|t| (frac - t).abs())
                .fold(f64::INFINITY, f64::min);
            score -= 12.0 * (1.0 - target);
            score += 0.15 * mod5 + 0.1 * mod10 + 0.05 * mod20;
        }
    }

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with lookahead: reward leaving room exactly for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            score += 8.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item barely fits anywhere
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            (item_size as f64) / mean_residual.max(1.0)
        } else {
            2.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 25.0 * tightness - 10.0 * progress;
        if item_size >= 60 {
            score += 15.0; // big items prefer a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold the next item (or a minimal item ~10).
    let min_useful = if next_item_size > 0 { next_item_size.min(60) } else { 20 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 3.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Reward leaving room for the lookahead item to co-fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let open_pressure = open_bins_count as f64 * 0.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., mean residual is small relative to item) — otherwise penalize it.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / item_size.max(1) as f64;
        if tightness < 1.0 {
            score -= 5.0; // nothing fits well; fresh bin is fine
        } else {
            score += 20.0 + tightness * 5.0; // prefer existing bins
        }
    }

    // Mild preference for bins already below average residual (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight tightening of tolerance as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: reward tighter remaining fits
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: next item cannot fit in this bin's leftover
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins left tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit the item
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But allow a new bin if it gives a perfect match for the next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 65.0;
        }
    }

    // Mild late-stream tightening: keep bins tight as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 50.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }
    // Penalize post_residual that is a trap: too small for anything useful
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last chance: strongly favor using the only bin that fits (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless all fits are poor (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_post = (mean_residual - item_size as f64).max(0.0);
        let fits_bad = mean_post > 0.5 * bin_capacity as f64;
        if poor_fits > 0.0 || fits_bad {
            score -= 60.0; // open a fresh bin rather than waste space
        } else {
            score += 120.0; // prefer existing bins with decent fits
        }
        // Late in the stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && fitting_bins_count > 0 && !fits_bad {
            score += 100.0;
        }
    }

    // Mild preference for fuller bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Prefer bins whose residual is close to mean (balance) slightly
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes increasingly costly
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += norm_pr * (1.0 + 2.0 * (1.0 - progress_coupling)) * 10.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize placements leaving residual too small for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * 8.0; // next item fits snugly: reward
        } else {
            let miss = (nx - pr) / cap;
            score += miss * miss * 25.0; // next item won't fit: penalize dead space
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals
    // across open bins are already very tight
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap);
        let pressure = mean_tightness * (1.0 - progress);
        score += 20.0 + 30.0 * (1.0 - pressure);
    } else {
        // mild preference for bins below mean residual (use the fuller bins)
        score += (mean_residual - pr) / cap * 5.0;
    }

    // Slight penalty for bin proliferation
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Dead-space penalty: small but nonzero residuals are hard to fill
    if pr > 0 && pr <= sixteenth {
        score += 25.0;
    } else if pr > sixteenth && pr <= eighth {
        score += 8.0;
    } else if pr > eighth && pr < quarter {
        score += 2.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does next_item_size fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // exact chaining
        } else if next_item_size <= pr {
            let chain_residual = pr - next_item_size;
            if chain_residual <= sixteenth {
                score -= 12.0;
            } else {
                score -= (chain_residual as f64) * 0.05;
            }
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (pr as f64) * 0.03;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're bad,
    // but allow opening when mean residual is small (fragmented bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55
            + (mean_residual - cap * 0.3) * 0.5
            - 10.0 * progress;
    } else {
        // Prefer bins with residual close to item (tight fit) via harmonic distance
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score += (1.0 - fit_ratio).abs() * 5.0;

        // Favor fuller bins (harmonic thirds of residual)
        if bin_residual <= bin_capacity / 3 {
            score -= 6.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits: fraction of the residual consumed by this item.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Penalize leaving a gap that exactly matches nothing useful but
    // reward when post_residual could still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (more packed bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in the stream, tolerate new bins slightly more; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too: reward tight two-item packing
            score -= (post_residual - next_item_size) as f64 * 0.5;
            if post_residual - next_item_size == 0 {
                score -= 300.0;
            }
        } else {
            // next item won't fit: penalize wasted gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        // new bin: baseline score is full residual; add penalty unless item is large
        score += 50.0 - item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Progress-based mild adaptation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual (nonlinear).
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 12.0 * tightness * tightness;

    // Reward exact/near-perfect fills disproportionately.
    if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space relative to what future items likely need.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // wasted space that can't fit the lookahead item
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 5.0; // leaves a slot the next item can use
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full/fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / cap_f;
        // Opening a bin is good when mean residual is small (bins crowded)
        // and many bins are open; bad early in the stream with roomy bins.
        let open_bonus = (open_bins_count as f64).ln_1p();
        score += 30.0 + 10.0 * fragmentation - 8.0 * open_bonus - 5.0 * progress;
    } else {
        // Slight preference for filling bins that are already committed.
        score -= 0.05 * (cap_f - bin_residual as f64);
    }

    // Mild preference to keep mean residual balanced: avoid dumping into
    // the fullest bin when other options exist.
    if !is_new_bin && (bin_residual as f64) < mean_residual - 15.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += 18.0 * pr_norm * pr_norm * (0.35 + 0.65 * prog_sq);
    score -= 12.0 * pr_norm * prog_cu;

    // Reward tight fits, smoothly scaled by progress
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 9.0 * fit_tightness * (0.5 + 0.5 * prog_sq);

    // Dead-space penalty: residual too small to hold even the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 14.0 * gap * gap;
        // Smooth lookahead coupling: residual matching next item is valuable
        let match_term = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 6.0 * match_term.max(0.0) * match_term * (1.0 - progress);
    }

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual diverges from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // Penalize opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * prog_sq + 30.0 * prog_cu;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds.
    // Dead-space classes: residuals in [1..=5] are nearly unusable -> strong penalty
    // (we prefer to fill them now rather than leave crumbs).
    if post_residual <= 5 {
        score -= 40.0; // excellent: almost perfect fit
    } else if post_residual <= 12 {
        score -= 15.0;
    } else if post_residual <= 25 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score += 6.0;
    } else {
        score += 12.0;
    }

    // Modulo arithmetic: residual congruent to small moduli classes that commonly
    // pair with typical item sizes get a bonus (harmonic matching).
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0; // round residual likely reusable by 10-multiple items
    }
    if pr % 5 == 0 && pr > 0 && pr % 10 != 0 {
        score -= 2.0;
    }

    // Lookahead coupling (k=2): if the next item fits exactly into the resulting
    // residual, this placement is harmonically perfect.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            // reward proportionally to how well next item consumes the residual
            score -= 10.0 * (nxt / pr as f64);
            // harmonic class: residual after next placement
            let pr2 = pr - next_item_size;
            if pr2 <= 5 {
                score -= 15.0;
            } else if pr2 <= 12 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are badly fragmented
    // (high mean residual relative to capacity) or many bins already open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(1.0);
        score = 60.0 + 40.0 * (1.0 - fragmentation) - 20.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // next item needs a fresh bin anyway
        }
        // early in stream, opening bins is cheap
        if step_index < total_items / 10 {
            score -= 10.0;
        }
    }

    // Mild preference to balance load across many open bins when mean residual is low.
    score -= 2.0 * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }
    // Penalize gaps too small to fit the lookahead item if the lookahead could fit elsewhere
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero but usable)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far below mean residual (fragmenting the fleet)
    score += 0.5 * ((mean_residual - post_residual as f64).abs() / 10.0);

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (i.e., this empty-bin call should usually lose unless fits are awful)
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 10.0; // item nearly fills bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how well next item fits the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * slack;
            if post_residual == next_item_size {
                score -= 500.0; // perfect 2-item chain fill
            }
        } else {
            // Penalize leftovers too small for the next item (dead space).
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins already tighter than average
    // (consolidate fragments), penalize bins much looser than average.
    let resid_f = post_residual as f64;
    score += 0.4 * (resid_f - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 90 {
            score -= 60.0; // big items deserve a fresh bin
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 30.0; // fresh bin pairs well with the next item
        }
    }

    // Early in the stream, mildly prefer keeping bins compact for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.3 * (bin_capacity as f64 - resid_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize awkward dead space: residual after placement that is too small
    // for typical future items (below half capacity) but nonzero.
    if post_residual > 0 && post_residual < bin_capacity / 2 {
        score += 3.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64 / 2.0));
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if next item fits into post_residual, this placement is great.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // Even better if post_residual - next_item is small (chains well).
            score -= 2.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this
    // empty bin if it's called when fitting bins exist. Penalize moderately so
    // it only wins when all existing bins give bad scores.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But late in the stream with many open bins, a fresh bin is more attractive
        // than fragmenting a nearly-full bin.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Slight preference for bins with below-mean residual (consolidate fuller bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling
    let mut score = pr + (pr * pr) / cap;

    // Tight-fit reward: strongly subtract when item nearly fills the bin
    let fill = isz / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Penalize post-residual that is small but unusable relative to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // dead space: next item cannot fit here
            score += 6.0 * (nx - pr) / cap * (1.0 + pr / cap);
        } else {
            // next item fits: reward chain packing, smooth coupling
            score -= 5.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but relax penalty late in the stream or when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let new_bin_penalty = 4.0 + 10.0 * (1.0 - progress) * (1.0 - fragmentation * 0.5);
        score += new_bin_penalty;
    } else {
        // Prefer bins with residual below mean (consolidate fullness)
        score += 2.0 * (pr - mean_residual) / cap;
    }

    // Smooth stream-progress interaction: later items tolerate tighter residuals
    score *= 1.0 + 0.15 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it divides the capacity
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are "harmonic" divisors of capacity (usable by future items)
        let cap_u = bin_capacity;
        if pr % 10 == 0 { score -= 6.0; }
        if cap_u % pr == 0 { score -= 8.0; }
        // Penalize awkward residual classes (just above small-item thresholds)
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }
        else if pr < 30 { score -= 2.0; }
        // Integer-division threshold: residual in the "sweet band" 30..50
        if pr >= 30 && pr <= 50 { score -= 5.0; }
    } else {
        // Perfect fit is ideal
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted amount
            score += (next_item_size - pr) as f64 * 0.1;
        }
    } else {
        // Last item: prefer tightest packing
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: default neutral-ish; open new bin only when
    // the best existing fit would leave a bad residual class
    if bin_residual == bin_capacity {
        // New bin is attractive early (few open bins) or when mean residual is low (poor fits)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 15.0 * progress - 0.15 * mean_residual - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the next item
    // (or for the smallest plausible item) are wasted space -> heavy penalty.
    let min_item = 1u32;
    let look = if next_item_size > 0 { next_item_size } else { min_item };
    if post_residual < look {
        score += 25.0 + 0.5 * (look - post_residual) as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow a new bin if the item would leave a very roomy, reusable bin
        // and all existing fits are poor (large post_residual).
        if post_residual >= 60 {
            score -= 18.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // filling a bin below-mean residual (large gap) tightens the pool.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose residual after placement matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
        if slack == 0.0 {
            score -= 150.0; // exact 2-item chain fill
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead: penalize proportionally
        let dead = post_residual as f64;
        score += dead * 0.5;
    }

    // Penalize creating small unusable residuals (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // late in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 60.0;
    }

    // Prefer fuller bins overall
    score -= (bin_residual - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (wasted residual unlikely to be reused).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * dead * dead;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual) or few bins can host the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let poor_fit = post_residual as f64 / bin_capacity as f64; // for new bin this is (C - item)/C
        score += 120.0; // base cost of opening a new bin
        score -= 90.0 * pressure * pressure;
        score -= 80.0 * poor_fit * poor_fit;
        // Early in the stream, opening bins is cheaper (future items can share).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // If mean residual of open bins is high, prefer reusing them.
        score += 0.5 * mean_residual;
    } else {
        // Reward reusing existing bins, more so when alternatives are scarce.
        if fitting_bins_count == 1 {
            score -= 25.0; // last-chance bin before opening a new one
        }
        // Lookahead: if the next item fits exactly in post_residual, big bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * next_fit;
            if next_item_size == post_residual {
                score -= 25.0; // perfect two-item closure
            }
        } else if next_item_size > post_residual {
            // Next item won't fit here; leftover is likely dead space.
            score += 0.3 * post_residual as f64;
        }
        // Slightly prefer bins whose residual is below the mean (keep big holes open).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Mild bonus for keeping open-bin count low.
        score += 0.5 * open_bins_count as f64;
    }

    // Small time-dependent noise-free tiebreaker to diversify bin selection.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling of residual quality with stream progress:
    // early on, prefer tight packing (low post residual); later, tolerate slack
    let progress_weight = 0.5 + 1.5 * t;
    score += progress_weight * (post * post) / cap;

    // Penalize dead space relative to mean residual across open bins
    score += 0.6 * (post - mean_residual).abs();

    // Lookahead: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0);
        let fit_quality = 1.0 - (fits / cap).powf(1.5);
        score -= 12.0 * fit_quality * (1.0 - t);
        // penalize near-exact-but-wasteful fits for the next item
        score += 0.3 * (fits * fits) / cap;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate (empty bin) calibration: only attractive when
    // existing residuals are poor relative to item size
    if bin_residual == bin_capacity {
        score = post + 8.0 + 0.5 * mean_residual - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: modulo classes on capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead space penalty: residuals too small for typical items (1..100) are wasteful.
    if post_residual < 10 {
        score += 80.0 * (10 - post_residual) as f64;
    }

    // Modulo-class logic on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    score += class as f64 * 0.4;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 200.0;
            } else {
                score -= gap as f64 * 0.5;
            }
        } else {
            // Next item won't fit here: penalize leaving large but awkward residuals.
            let over = next_item_size - post_residual;
            score += over as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline, but avoid opening new bins when
    // existing residual capacity is high and item is small.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // If item is small relative to capacity and open bins are roomy, discourage new bin.
        if (item_size as f64) < mean_residual {
            score += 40.0;
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    score -= (item_size as f64 / cap) * 30.0;

    // Stream progression: later in stream, waste matters more (fewer future chances).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += pr * 0.2 * progress;

    // Prefer bins with below-mean residual (tighter bins first, best-fit style).
    score -= (mean_residual - pr) * 0.3;

    // Integer-division threshold: residuals that are exact divisors of 100 are reusable.
    if post_residual > 0 && (bin_capacity % post_residual == 0) {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0; // reusable gap
        } else {
            score += 15.0; // gap too small for next item
        }
    }

    // Pressure against proliferating open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are nearly full
    // or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 1.5;
        if tight && open_bins_count > 0 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight packing).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 24.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 18.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if (post_residual as u32) < next_item_size {
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Tightness reward: prefer small post_residual relative to capacity.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= 6.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin useful for a chain of large items
        }
    }

    // Late in the stream, be more conservative about spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize large dead space quadratically
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more when open bins fit well
        let best_possible_waste = if fitting_bins_count > 0 {
            open_bins_count as f64
        } else {
            0.0
        };
        score += 25.0 + best_possible_waste;
        // If post_residual of new bin leaves room for next item, soften
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead: penalize leaving residual that is awkwardly below next item size
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // residual can host next item: reward
            score -= 5.0;
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling those
    if open_bins_count > 0 && bin_residual < bin_capacity {
        let rel = bin_residual as f64 - mean_residual;
        score -= rel * 0.3;
    }

    // Penalize bins whose residual is in the awkward zone (1..10) after placement
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Time horizon: early stream, be more conservative about tight fits; late, pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = pr_norm * (1.0 - pr_norm) * (0.5 + progress);
    score += 6.0 * progress_coupling;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 12.0 * gap * gap * (1.0 + progress);
        } else {
            // Reward a fit for the lookahead item, more so mid-stream
            let fit_quality = (pr - nxt) / cap;
            score -= 4.0 * fit_quality * (1.0 - fit_quality) * (0.3 + 0.7 * progress);
        }
    } else {
        // End of stream: strongly prefer tight packing
        score -= 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * (1.0 - pr_norm);
    }

    // Mild penalty proportional to crowdedness of open bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Prefer bins whose residual deviates favorably from the mean residual
    score -= 0.5 * (mean_residual - pr) / cap;

    // Slight bias toward filling bins more tightly overall
    score -= 0.3 * (item_size as f64 / cap) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are "dead space"
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity classes (sixteenths) — residual in lowest classes is nearly dead
    let frac = pr / c;
    if frac <= 0.0625 {
        score -= 40.0; // tiny residual is fine (effectively full)
    } else if frac <= 0.125 {
        score += 10.0;
    } else if frac <= 0.25 {
        score += 30.0;
    } else {
        score += 55.0; // large leftover: wasteful
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 align with typical item sizes
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0; // chains a second item into this bin
            let slack = (post_residual - next_item_size) as f64;
            score -= slack * 0.3; // tighter chain is better
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 90.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // open new bin if existing fits leave huge waste
        if (post_residual as f64) > 0.5 * c && fitting_bins_count > 0 {
            score -= 60.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual differs from mean (diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.2;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Late-stream tightening
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small but nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (small post_residual strongly discounted).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is close to the mean (keeps residuals uniform).
    score += 0.5 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, this placement is valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would exactly fill the post-residual, even better.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins -> discourage opening a new one).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + 5.0 * (fitting_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is always desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match => strong discount; loose match => mild penalty.
        if diff <= 10.0 {
            score -= 60.0 - 3.0 * diff;
        } else if post_residual < next_item_size as u32 {
            // Dead space the next item cannot use.
            score += 0.25 * diff;
        } else {
            score += 0.05 * diff;
        }
        // If next item also fits perfectly after this placement, big bonus.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Chain fit: next item fits and leaves room for a small item.
        if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal waste, slight preference for filling a bin.
        score -= 5.0;
    }

    // Compare against mean residual: bins with more room than average are
    // less precious; bins below average residual are tight — prefer using them.
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 20.0 + 0.5 * (item_size as f64);
        // Opening a new bin is fine if item is large or no tight fits exist.
        if item_size > 50 {
            score += base * 0.3;
        } else {
            score += base;
        }
        // Early in the stream, new bins are cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins already: discourage more sprawl.
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer keeping a little usable slack rather than tiny unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
