    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly over time to encourage consolidation.
        score += 10.0 + 20.0 * progress;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize very fragmented states: many open bins with large residuals.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr_norm * pr_norm * 100.0 + pr_norm * 20.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, demand tight packing.
    let tightness = 0.5 + 0.5 * progress;
    score += (1.0 - pr_norm) * (1.0 - pr_norm) * 30.0 * (1.0 - tightness);

    // Penalize very small dead space asymmetrically (waste is wasted either way,
    // but near-perfect fits deserve extra reward)
    let perfect = (pr_norm - 0.02).abs();
    score -= 15.0 * (-perfect * 40.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins fit well
    if bin_residual == bin_capacity {
        let newbin_penalty = 40.0 - 10.0 * progress;
        // If next item is large, a fresh bin may be valuable
        let lookahead_bonus = if next_item_size as f64 > 0.6 * cap { 12.0 } else { 0.0 };
        score += newbin_penalty - lookahead_bonus;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 8.0 * (diff / cap);
        if pr >= next_item_size as f64 && pr < next_item_size as f64 + 5.0 {
            score -= 10.0;
        }
    }

    // Mild pressure against bin proliferation
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual deviation: prefer bins whose residual is near mean (balanced use)
    let mean_pr = mean_residual;
    score += 2.0 * ((pr - mean_pr) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (small, reusable pockets) are rewarded.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Class A: post_residual is an exact divisor-class of capacity (tight fit)
    if post_residual > 0 && bin_capacity % post_residual.max(1) == 0 {
        score -= 6.0; // leftover can be exactly tiled later
    }
    // Class B: post_residual in small harmonic band (<= 10): near-perfect fit
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 3.0;
    } else if post_residual > 2.0 * cap / 3.0 {
        // large dead space: penalize extra so a new bin may win
        score += 4.0;
    }

    // Integer-division threshold: does next item fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how snugly
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            // harmonic bonus if next item leaves a divisor-class residue too
            let nxt_post = post_residual - next_item_size;
            if nxt_post > 0 && bin_capacity % nxt_post == 0 {
                score -= 4.0;
            }
        } else {
            // lookahead cannot use this bin's leftover: mild penalty unless
            // leftover is tiny anyway
            if post_residual > 15 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's
    // post-fit leftover is large and wasteful.
    if bin_residual == bin_capacity {
        // base new-bin score is already post_residual == capacity; add
        // pressure so it only wins when open bins would waste a lot
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: early on, prefer consolidating (fewer bins);
    // late, prefer tight fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (1.0 - post / cap);

    // Prefer bins whose residual deviates favorably from mean residual
    // (use the bin that is closest to being filled relative to average).
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1, but practically tiny gaps) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect or near-perfect fits are gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Pressure from number of open bins: prefer consolidation when many
    // bins are open, but allow opening new bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Mean residual coupling: bins far below mean residual are poor picks
    // late in the stream (they should stay for smaller items).
    if mean_residual > 0.0 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15 * progress;
    }

    // Last-chance bin: strongly favor using it rather than opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward;
    // if this placement would leave a gap the next item cannot use, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            score += 12.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 20.0 * (5 - post_residual) as f64;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after next placement is good
            score -= 120.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here: penalize proportionally to wasted post-residual
            let waste = (next_item_size - post_residual) as f64;
            score += 30.0 * (waste / 100.0).min(1.0);
        }
    }

    // Relative to mean residual: bins with more residual than average are better targets
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer fuller bins (low residual) slightly
    score += 0.3 * bin_residual as f64 / bin_capacity as f64 * 10.0;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -50.0 } else { 250.0 + 20.0 * fitting_bins_count as f64 };
        score += penalty;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: waste relative to bin capacity
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fits: bonus scaled by how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space unusable by next item
            let dead = post_residual as f64;
            let unusable = if dead < next_item_size as f64 { 1.0 - dead / next_item_size as f64 } else { 0.0 };
            score += 20.0 * unusable;
        }
    } else {
        // last item: strongly prefer zero residual
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            1.0
        };
        score += 40.0 * (1.0 - crowding); // cheap to open when bins are full-ish
        score -= 15.0 * crowding;         // expensive when open bins are roomy
        score += 10.0 * progress;         // slightly more willing to open early? no: penalize early opening
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    if open_bins_count > 2 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - post / cap; // how well the item fills the bin
    let mut score = post;

    // Reward tight fits more strongly as the stream progresses.
    let fill_bonus = tightness * tightness * (1.0 + 3.0 * progress);
    score -= 40.0 * fill_bonus;

    // Penalize large dead space non-linearly (quartic-ish growth).
    let dead = post / cap;
    score += 30.0 * dead * dead * dead * (1.0 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless post_residual is very small
    // (i.e., item nearly fills a fresh bin) or no existing bin fits well.
    if bin_residual == bin_capacity {
        let waste_new = cap - item_size as f64;
        let opening_penalty = 60.0
            - 40.0 * (1.0 - waste_new / cap)
            + 20.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        score += opening_penalty;
        // If the next item could use the leftover of this fresh bin, soften slightly.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward leaving a residual that fits the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Mild dispersion penalty: prefer bins whose residual deviates favorably
    // from the mean (consolidating small residuals).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // classes (multiples of common small sizes) are worth keeping tidy.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit — strongly reward
    } else if pr <= 10 {
        8.0 // tiny dead space, nearly useless
    } else if pr % 10 == 0 {
        -6.0 // round residual, likely reusable
    } else if pr % 5 == 0 {
        -3.0
    } else {
        2.0
    };
    score += harmonic_bonus;

    // Integer-division thresholds: residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 6.0; // bin nearly full; residual likely unusable -> deprioritize? no: lower score = select. Penalize wasting capacity on near-full bins is fine; but we prefer filling them. Reward instead:
        score -= 10.0;
    } else if pr < 2 * quarter {
        score += 1.0;
    } else {
        score += 3.0; // large residual: keep for bigger items
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 8.0 * (pr as f64 - next_item_size as f64) / cap;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is penalized mildly unless
    // the item fits poorly everywhere (poor fit = large leftover fraction).
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        if fit_ratio > 0.7 {
            score -= 5.0; // big items justify fresh bins
        } else {
            score += 12.0 + 10.0 * (1.0 - fit_ratio);
        }
        // early stream: bins are cheap to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Scale slightly by open bin count pressure.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Reward bins whose residual is close to item size (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - gap) * 0.05;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 10 { score -= 15.0; } else { score -= 4.0; }
    }
    // Penalize if next item would NOT fit here (this bin becomes dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.6;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win unless they create dead space.
        score += 35.0;
        // Early in stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If no open bin fits, this is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward when post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly reusable
        } else if post_residual >= next_item_size {
            // partial reward, decaying with leftover slack after the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.35;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Reward tight fits relative to capacity (low post_residual is good, but
    // only if it is still usable: very small residues are dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Compare against mean residual of open bins: prefer bins whose post_residual
    // sits near/below the mean (keeps bin states homogeneous, easier to chain).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is wasteful while other bins fit,
    // unless the item is huge and would leave a nicely reusable large residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 20.0; // fresh bin can chain with next item
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = -50.0; // no alternative: must open
        }
        // late in stream, opening is slightly cheaper than fragmenting
        new_bin_penalty -= progress * 10.0;
        score += new_bin_penalty;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item fills most of the residual
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space left behind, superlinearly
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * dead;
    }
    // Perfect closure bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size < post_residual {
            let nxt_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nxt_fit;
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the fit in existing bins is poor (low fill ratio) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fill_ratio < 0.0 || fitting_bins_count == 0;
        // Base cost of a fresh bin, discounted by global fragmentation
        let mut new_bin_cost = 35.0
            - 10.0 * (mean_residual / bin_capacity as f64).min(1.0)
            - 10.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_cost = -100.0; // must open a bin
        }
        if poor_fit_elsewhere && fitting_bins_count == 0 {
            new_bin_cost -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins
        if progress > 0.8 && fitting_bins_count > 0 {
            new_bin_cost += 15.0;
        }
        score += new_bin_cost;
    } else {
        // Reward using existing bins more when many bins are open (reduce spread)
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Slightly favor bins with residual close to the mean (balance residuals)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-dependent tie-break noise-free deterministic jitter
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Quadratic dead-space penalty: small post-residuals are great, mid-range waste is punished.
    score += 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;

    // Perfect-fit reward (smooth cubic decay away from zero residual).
    score -= 25.0 * (1.0 - norm_pr).powi(3) * cap;

    // Lookahead coupling: reward if post_residual can host the next item.
    if next_item_size > 0 {
        let fits_next = (norm_pr - norm_next).max(0.0) / cap;
        score -= 40.0 * fits_next * (1.0 + progress);
        // Penalize leaving residual just above next item size (dead zone).
        let gap = (norm_pr - norm_next).max(0.0);
        score += 15.0 * gap * (1.0 - gap) * cap;
    }

    // Stream-progress coupling: early on, keep bins flexible (favor spreading); late, pack tight.
    let tightness = 0.5 + 0.5 * progress;
    score += (1.0 - tightness) * 10.0 * (1.0 - norm_item) * cap * 0.1;
    score -= tightness * 12.0 * norm_item * cap * 0.1;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + norm_item);
    }
    // Many fitting bins: mild penalty to prefer scarcer fits.
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean residual context: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - pr);

    // New-bin candidate: make it moderately attractive only when open bins are mostly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - 30.0 * avg_fill * avg_fill + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" residue classes are more reusable, reward them.
    let post = post_residual;
    let class = post / 10; // integer division into decade classes
    score -= (class as f64) * 2.5;

    // Perfect fit: huge reward.
    if post == 0 {
        score -= 500.0;
    }

    // Tight fit: leftover too small for the minimum item size (1..100 unknown,
    // but small leftovers are dead space) -> penalize.
    if post > 0 && post < 10 {
        score += 120.0;
    }

    // Coupling with lookahead: if next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 300.0;
        } else if next_item_size <= post {
            // next item fits with a residue in a good class
            let npost = post - next_item_size;
            score -= (npost / 10) as f64 * 3.0;
            if npost == 0 {
                score -= 150.0;
            }
            if npost < 10 && npost > 0 {
                score += 40.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += ((next_item_size - post) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post >= 10 {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent
    // fitting bins exist; the new-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keeps it from winning unless all fits are bad.
        score += 90.0;
        // Late in the stream, prefer closing out existing bins less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / cap) * 20.0;
    } else {
        // Reward using bins whose residual is above mean (balance the pool).
        if (bin_residual as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Modulo-based harmonic preference: residuals that are multiples of common
    // item sizes (10/20/25) pair well with typical streams.
    if post % 10 == 0 { score -= 12.0; }
    if post % 20 == 0 { score -= 8.0; }
    if post % 25 == 0 { score -= 6.0; }

    // Slight preference to keep number of open bins from exploding early.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small for the
    // smallest plausible item (1..100 unknown distribution) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect fill, strongly reward
    }

    // Nonlinear dead-space penalty: small gaps quadratic in badness
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 200.0 / (pr * pr + 1.0);
    }

    // Open-bins pressure: penalize spreading across many bins slightly
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the lookahead item
    }

    // Prefer tighter bins (small residual before placement)
    score += (bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when open bins would leave bad gaps
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (non-linear: dead space hurts more when large).
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward perfect/near-perfect match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: big reward.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit in residual: penalize leftover that is too small to be useful.
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 1.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item would leave a nicely reusable residual, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: tighten packing, discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small unusable post-residuals (dead space) but reward exact fills.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // next item won't fit here; mild penalty proportional to wasted opportunity
            score += 5.0;
        }
    } else {
        // Last item: strongly prefer exact / near-exact fills.
        score -= 40.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // When many bins can fit the item, prefer the one with least residual (tightest).
    if fitting_bins_count > 1 {
        score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate logic: opening a new bin is only attractive when no
    // good fit exists. Make the empty bin costly unless it's a good deal.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin for large items that would leave big
        // awkward residuals elsewhere, or when open bins are already fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 - 0.4 * item_size as f64 + 0.3 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can also host the next item
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative
        }
    }

    // Mild time-horizon modulation: late in the stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (1.0 - tightness);

    // Prefer bins with residual close to item_size (best-fit style).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear curvature
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, punish leftover space more strongly
    score += progress * norm_pr * norm_pr * 3.0;

    // Reward bins whose residual closely matches the item (smooth coupling)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fit_ratio * (1.0 - fit_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward if next item fits into post_residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 1.5 * (1.0 - slack).exp();
        } else {
            let miss = (nxt - pr) / cap;
            score += 1.0 * (1.0 - (-miss * miss).exp());
        }
    }

    // Divergence from mean residual: prefer bins deviating usefully
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Penalize opening new bins when many open bins exist and residual is large
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 + progress * 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small remainders are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space unlikely usable
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Modulo-classes of residual against common item sizes (1..=100 unknown dist):
    // reward residuals that sit in "reachable" harmonic bands.
    let res_class = (pr % 25) as f64;
    score -= 6.0 * (1.0 - res_class / 25.0) * (pr as f64 / cap);

    // Tightness coupling: prefer bins where item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Lookahead: penalize leaving a residual that neither fits nor nearly fits next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as f64) < nx {
            score += 8.0; // next item cannot go here anyway
        } else if (pr as f64) - nx <= 10.0 {
            score -= 18.0; // next item will near-perfectly fill this bin
        }
    }

    // Last chance: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    // Spread pressure: many open bins -> prefer consolidating into low-residual bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Progress-based mild bias toward tighter packing late in the stream.
    let prog = step_index as f64 / total_items.max(1) as f64;
    score += prog * (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item size (1..100 unknown dist,
    // assume items >= 1, so any gap is technically usable; but penalize gaps smaller than
    // the lookahead item or smaller than a typical small item) are effectively dead.
    let min_useful = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (min_useful - post_residual) as f64;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // mildly encourage consolidation when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins and progress.
        score += 40.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
        // If nothing fits elsewhere this is forced; fitting_bins_count==1 with empty bin
        // means only this candidate: soften.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    } else {
        // Reward packing into already-open bins, scaled by how full they are.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 15.0 * fullness;
        // Prefer bins with residual close to mean (balanced packing) mildly.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Near match: next item still fits with little slack left.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.4;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size <= bin_capacity {
            1.0
        } else {
            0.0
        };
        score += 15.0 + 0.1 * open_bins_count as f64 - 10.0 * pressure;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward small post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Exact or near-exact fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // bonus scaled by how well next item fills the remainder too
            let chain_left = post_residual - next_item_size;
            score -= 5.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // dead space the next item cannot use
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer open bins unless fit is terrible
    // or there are no open bins at all.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // cost of a new bin, discounted when item is large and fit elsewhere is bad
            let mut new_bin_penalty = 30.0 + 0.5 * open_bins_count as f64;
            if item_size > 60 {
                new_bin_penalty -= 10.0;
            }
            if next_item_size > 0 && next_item_size >= post_residual && post_residual >= bin_capacity {
                // fresh bin will fit next item too
                new_bin_penalty -= 8.0;
            }
            score += new_bin_penalty;
        }
    }

    // Global state: if mean residual is high, bins are loose — encourage
    // consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        if mean_residual > 30.0 {
            score -= 3.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in the stream, avoid leaving awkward residuals.
        if progress > 0.7 && post_residual > 0 && post_residual < 20 {
            score += 3.0;
        }
    }

    // Mild preference for bins with larger residual when many bins are open
    // (keeps small bins available for small items).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Tight fits (small post_residual) get quadratically rewarded, more so late in stream.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 20.0 * progress);

    // Penalize large dead space super-linearly (polynomial coupling).
    score += pr_norm * pr_norm * pr_norm * 15.0;

    // Reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Penalize opening new bins when many bins are open with slack (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.05;
    } else {
        score -= 2.0;
    }

    // Slight preference for bins with below-mean residual (better local packing).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (multiples of common item sizes), penalize dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual by integer division thresholds (harmonic bands)
    let frac = pr / cap;
    if frac < 0.05 {
        score -= 30.0; // near-perfect fit, very desirable
    } else if frac < 0.20 {
        score += 15.0; // dead-space band: too small for most items
    } else if frac < 0.45 {
        score -= 10.0; // sweet spot for mid-size items
    } else {
        score -= 5.0; // large residual still flexible
    }

    // Modulo arithmetic: residuals divisible by common size classes (10/20/25)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: strongly reward, scale with tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * tight;
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.25 * over;
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // current bin fit is terrible. Penalize the fresh empty bin mildly.
    if bin_residual == bin_capacity {
        // base cost of a new bin: proportional to item waste potential
        score += 45.0 + 0.5 * (item_size as f64);
        // early in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // if many open bins already, opening another is worse
        score += 2.0 * open_bins_count as f64;
    } else {
        // favor bins with below-mean residual (tighter bins first)
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Mild tie-break: prefer bins whose residual is closest to item size
    score += 0.1 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space penalty: leftover gap that cannot host the next item is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Unusable sliver: penalize proportionally to how close it is to being useless.
        let dead = next_item_size as f64 - post_residual as f64;
        score += 18.0 + 0.6 * dead;
    }

    // Reward tight fits: small post_residual (but still usable) is good.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin costs, scaled by open bins
    // and stream progress; but if the new bin's residual perfectly suits the
    // next item, discount the penalty.
    if bin_residual == bin_capacity {
        let mut open_cost = 8.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            open_cost -= 5.0;
        }
        if fitting_bins_count == 0 {
            open_cost = 0.0; // no alternative, new bin is fine
        }
        score += open_cost;
    }

    // Mild coupling to mean residual: bins far below average residual are
    // less attractive targets (keep homogeneous fill levels).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item fits perfectly into the post residual.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits, penalize proportional to leftover slack after next item.
            score -= 25.0 - 0.5 * diff;
        } else {
            // Next item does not fit: penalize dead space relative to capacity.
            score += 0.3 * diff;
        }
        // Small coupling: if next item nearly matches, dampen reward.
        if diff < 5.0 {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is below mean (tight bins get filled first).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no tight fit is available.
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 10.0;
        }
        // Slight bonus for new bin early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * (1.0 - progress);
    }

    // Penalize large unusable dead space (waste).
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0; // nearly perfect fill
    }
    if post_residual > 60 {
        score += 5.0; // leaving a very loose bin is wasteful
    }

    // Mild pressure against proliferation of open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * frac_used * frac_used;

    // Dead-space penalty: residuals too small for the minimum item size are waste.
    if post_residual < 10 {
        score -= 6.0; // perfect closure, great
    } else if post_residual < item_size {
        // residual smaller than the item itself is likely dead space
        score += 0.35 * (post_residual as f64);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.10 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of consuming fresh capacity.
        score += 18.0;
        // More tolerable early in the stream, worse later (waste avoidance over time).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If many bins are already open and mean residual is large, discourage new bins.
        score += 0.02 * open_bins_count as f64;
        score += 0.05 * mean_residual;
        // But if next item is large and current residuals are tight, a new bin is fine.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post_residual (tight fit), with polynomial sharpening
    let mut score = pr * (1.0 + 0.02 * (pr / cap) * (pr / cap));

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing is rewarded more.
    score -= (cap - pr) * (0.3 + 0.7 * progress * progress) * 0.5;

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
        } else {
            // penalize leaving residual that no plausible next item uses
            score += 0.05 * (pr - nx).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly by default; relax late in stream
    // when mean residual across open bins is high (open fresh bins then).
    if is_new_bin {
        score += 10.0 - 8.0 * progress * (mean_residual / cap).min(1.0);
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.01 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic classes of post_residual
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect (dead space unusable for most items)
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Modulo arithmetic: residual classes w.r.t. capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual % quarter;
    score += class as f64 * 0.6; // prefer residuals landing on quarter boundaries

    // Penalize residuals just below common item-size multiples
    for m in [10u32, 20, 25, 30, 40, 50] {
        if post_residual > 0 && post_residual < m && post_residual >= m.saturating_sub(8) {
            score += 8.0; // awkward sliver just under a plausible item size
        }
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact/near match with lookahead is excellent
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / cap);
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // last item: minimize leftover aggressively
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Many alternatives: prefer bins where fit is tightest (score already does via post_residual)

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.75;
        // Open a new bin if existing bins would leave bad residuals
        if post_residual == cap - item_size {
            let new_res = cap - item_size as f64;
            // good start if item is large (leaves small residual)
            if new_res <= 30.0 {
                score -= 25.0;
            }
            // lookahead chain: new bin tailored for next item too
            if next_item_size > 0 && new_res + cap >= next_item_size as f64 + item_size as f64 {
                score -= 5.0;
            }
        }
        // As stream matures, be more conservative about opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // Few open bins: opening is cheaper than fragmenting
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (more filled)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1..100 unknown, assume >=10 typical) are "dead".
    // Penalize heavily when post_residual falls into unusable gap band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver: nearly useless
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger residuals are reusable: reward proportionally
        score -= (post_residual as f64 - 35.0) * 0.4;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (favor bins with small residuals to close them out); when few bins,
    // opening new bins is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 1.5;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a big usable residual, or no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: mid-range so good fits in open bins win.
        score = 45.0 + (100 - item_size.min(100)) as f64 * 0.3;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // packing next item here too is attractive
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits elsewhere: new bin is fine
        }
    }

    // Stream progression: early on, slightly favor keeping residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Next item fits in the post residual (good lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space, worse when residual is tiny.
        let dead = post_residual as f64;
        score += 12.0 * (dead / bin_capacity as f64);
    }

    // Tight fit bonus: small post residual is generally good.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: below-average waste is attractive.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin still useful for lookahead chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer filling existing bins fully.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: open a new bin only when the current fit is poor
    // and there is slack in the stream (plenty of items remain).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Good fits (small post_residual) make new-bin unattractive.
        let bias = 45.0 * fit_quality * fit_quality + 10.0 * (1.0 - progress);
        // If open bins are nearly full on average, a new bin is fine.
        let bias = bias - 15.0 * (mean_residual / bin_capacity as f64);
        score += bias.max(-20.0);
    }

    // Slight preference to keep number of open bins moderate early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Reward bins whose residual is above mean (use the crowded ones first).
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post-residual
    let x = pr / cap;
    // base: prefer tight fits (small post_residual), non-linear
    let mut score = 100.0 * x * x + 10.0 * x;
    // smooth coupling of post_residual with stream progress:
    // later in the stream, waste is more costly -> amplify residual penalty
    let coupling = (0.5 + progress) * pr * pr / cap;
    score += 0.5 * coupling;
    // dead-space term: residuals too small for typical future items are dead
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        gap * gap / cap
    } else {
        0.0
    };
    score += 2.0 * dead;
    // reward using nearly-full bins (small residual relative to mean)
    score -= 5.0 * (1.0 - x) * (1.0 - x);
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // mildly penalize spreading across many open bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    // prefer bins whose residual deviates from the mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * (1.0 - progress);
    // new-bin candidate penalty: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0 - 10.0 * x;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" size classes (multiples of common item granularity bands).
    let post = post_residual as u32;
    let class = post / 10; // coarse harmonic class 0..10
    let phase = post % 10; // fine phase within class

    // Dead-space penalty: tiny residuals are wasted; big residuals are fine.
    if post < 10 {
        score += 40.0 * (10.0 - post as f64);
    }

    // Reward alignment: residuals that are multiples of 5/10 are more likely
    // to be exactly filled by future items.
    if phase == 0 {
        score -= 12.0;
    } else if phase == 5 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Mid-class residuals (20..50) are the most reusable; reward them.
    if class >= 2 && class <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or
    // nearly, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post as f64).abs() < 1.0 {
            score -= 30.0;
        } else if nxt <= post as f64 {
            score -= 10.0 * (1.0 - (post as f64 - nxt) / cap);
        } else {
            // next item won't fit here; slight penalty scaled by waste
            score += 5.0 * ((nxt - post as f64) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = mean_residual / cap;
        // penalize new bin when existing bins have plenty of room
        score += 15.0 + 60.0 * tightness - 20.0 * (1.0 - progress);
        // but reward new bin if the item would leave bad residual elsewhere
        if post >= 70 {
            score -= 20.0;
        }
    }

    // Mild preference to fill fuller bins (low residual) as stream progresses.
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill_frac * (0.5 + 0.5 * (step_index as f64 / (total_items.max(1) as f64)));

    // Penalize spreading across too many open bins.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are waste.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fill, ideal
        score -= 50.0;
    } else if post_residual > 0 && post_residual < 10 {
        // unusable sliver: heavy penalty
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // only fits very small items: moderate penalty
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading across many bins when mean residual is low
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln() * 2.0;
        score += pressure * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for leaving awkward gap
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets neutral base but should only win
    // when fits are poor. Penalize slightly so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills post residual -> huge reward.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving dead space that
            // is smaller than the next item (unusable for the lookahead).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual above mean are
    // preferable targets (keep low-residual bins for small future items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * residual_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large and fills the new bin well, soften.
        score -= 0.1 * item_size as f64;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize bins whose post-residual can't host the next item
    // if the next item would then need a fresh bin anyway.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain placement potential
        } else if next_item_size > bin_residual {
            score += 5.0; // next item won't fit here regardless; mild penalty avoided
        } else {
            score += 8.0; // would create unusable gap for next item
        }
    }

    // Dead-space guard: residuals too small for the minimum item size (1..100 unknown,
    // use small threshold) are near-wasted.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Time horizon: early on, prefer consolidating into existing bins (fewer opens);
    // later, tightness dominates so relax the new-bin aversion.
    let consolidation_bias = 25.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late or when many bins are strained.
        score += consolidation_bias;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0; // existing bins nearly full; opening is fine
        }
    } else {
        // Existing bin: slight reward scaled by how much it's already used.
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: when open bins are on average loose, prefer filling them.
    score -= 0.02 * mean_residual * (1.0 - progress);

    // Tie-break deterministic jitter via state mixing (no RNG).
    score += ((step_index.wrapping_mul(2654435761).wrapping_shift_right(16) % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong non-linear reward for tight fits: quadratic/quartic decay of post_residual.
    let x = post / cap;
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);
    score += 8.0 * x * x * x;

    // Penalize residuals that are too small to ever fit future items (dead space),
    // coupled smoothly with stream progress: dead space matters more early on.
    let dead = if post > 0 && post < item_size.max(next_item_size) { 1.0 } else { 0.0 };
    score += dead * (6.0 + 10.0 * (1.0 - progress)) * (1.0 - x * x);

    // Lookahead coupling: reward bins whose post_residual fits the next item,
    // with smooth polynomial interaction in progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            let miss = (nx - post) / cap;
            score += 4.0 * miss * miss * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let avg_tight = (mean_residual - post) / cap;
        score += 10.0 + 8.0 * (1.0 - progress) - 6.0 * avg_tight.max(0.0);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" sizes.
    // Class A: post_residual >= 40 (still fits a large future item) -> strong reward.
    // Class B: 20..40 (fits medium) -> mild reward.
    // Class C: 1..20 (dead space risk) -> penalty proportional to how close to full the bin was.
    if post_residual >= 40 {
        score -= 12.0;
    } else if post_residual >= 20 {
        score -= 4.0;
    } else if post_residual > 0 {
        score += (20 - post_residual) as f64 * 0.6;
    }

    // Perfect / near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness ratio: reward filling a large fraction of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves its own residual; scale by how cleanly it fits
            let next_post = post_residual - next_item_size;
            score -= 8.0 - (next_post as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of the residual
    // left behind in other bins; penalize new bins when open bins exist and mean
    // residual is large, but allow new bins when mean residual is small (bins nearly full).
    if bin_residual == bin_capacity {
        let waste = if open_bins_count > 0 { mean_residual } else { 0.0 };
        score += waste * 0.8 + 5.0;
        // Early in the stream, be more willing to open bins (keep options open).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If next item is large and no open bin likely fits it, opening a fresh bin is fine.
        if next_item_size > 0 && open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Modulo-class coupling: residuals divisible by common item sizes (10, 20, 25, 50)
    // are more reusable; reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
    }

    // Crowding: many open bins with high mean residual -> prefer consolidating into
    // existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

