    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Prefer bins already below mean residual (consolidate waste)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish default, but allow it when this stream
    // is early or the fit here would be terrible (huge dead space)
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 10.0;
        if post_residual >= 90 {
            score -= 20.0; // tiny item into fresh bin is fine
        }
    }

    // Penalize very large post_residual mildly (wasted capacity) unless new bin
    if bin_residual < bin_capacity && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
