    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64) * mean_residual / (bin_capacity as f64);
    score += pressure * 2.0;

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // slightly less); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0;

    // New-bin candidate handling: an empty bin gets a baseline cost so that
    // opening a new bin only wins when open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.35 * mean_residual;
        // Late in stream, discourage opening new bins even more.
        score += progress * 10.0;
    }

    // Slight preference for bins whose residual is close to mean residual
    // (keeps the pool of residuals homogeneous and packable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

