    let pr_norm = post_residual as f64 / bin_capacity as f64;
    score += (pr_norm * pr_norm) * (bin_capacity as f64) * (0.5 + progress);

    // Reward tight fits more strongly later in the stream.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (item_size as f64) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * (0.5 + progress);
        } else {
