            let fit_ratio = post_residual as f64 / (next_item_size as f64 + 1.0);
            score -= (fit_ratio.ln().abs()) * (1.0 - progress) * 2.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= (bin_capacity as f64) * (0.6 + 0.6 * progress);
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins.
        score += (fitting_bins_count as f64).sqrt() * (1.0 + progress);
    }

    // Coupling with mean residual: prefer bins close to the mean state early,
    // but diverge (fill fuller bins) later.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.2 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has maximal post_residual; make it
    // attractive only when no open bin fits well (its raw score is naturally high,
    // so add a mild early-stream discount, fading as stream progresses).
    if bin_residual == bin_capacity {
        score -= (bin_capacity as f64) * (1.0 - progress) * 0.4;
    }

    score
}

