    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave another dead gap, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 5 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit or residual space is badly fragmented.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64;
        if decent_fit_exists && fitting_bins_count > 0 {
            // Penalize opening a new bin when open bins can still fit the item.
            score += 30.0 + 2.0 * open_bins_count as f64;
        } else {
            // Mild reward so a fresh bin beats a terrible fragmented fit.
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect pair
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss.min(60.0);
        }
    }

    // Compare residual against mean residual: prefer bins with less residual
    // (tighter bins get used up first), keeping large residuals for big items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin early when decent open bins exist,
    // but allow it late in the stream or when the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size > 60 { 50.0 } else { 0.0 };
        score += 120.0 * (1.0 - progress) - large_item_bonus;
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for very fragmented bins that remain after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the lookahead item (dead space).
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score = waste + 30.0 - 0.25 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, opening is fine
        }
        if next_item_size > 0 && waste < next_item_size as f64 {
            score += 10.0; // new bin would be immediately fragmented
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with below-average residual (fill emptier bins first).
    if bin_residual < bin_capacity {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer filling bins tightly (low post_residual), non-linearly.
    let mut score = post * (1.0 + 0.8 * progress);

    // Reward near-perfect fits with a smooth quadratic term.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    let dead = post / cap;
    score += 20.0 * dead * dead * (1.0 - tightness);

    // Lookahead coupling: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_gap = (post - nxt) / cap;
            score -= 15.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: make it unattractive unless no reasonable open bin exists.
    if bin_residual == bin_capacity {
        score += cap * (1.2 + 0.6 * progress) - 4.0 * fitting_bins_count as f64;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.3 * (mean_residual - post).abs() * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small" residue classes are nearly perfect fits.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect closure, always best
    } else {
        // residue classes mod 10: tiny residuals are dead space
        let r10 = (pr % 10) as f64;
        score += r10 * 0.8;

        // harmonic penalty: residual in (0,10) is unusable for items >=10
        if pr < 10 {
            score += 60.0;
        }
        // integer division threshold: residual / smallest item class
        let div4 = pr / 25; // how many "quarter chunks" remain
        score -= div4 as f64 * 12.0;

        // non-linear: reward residuals that pair with typical next items
        if next_item_size > 0 {
            let gap = if next_item_size <= pr { pr - next_item_size } else { 0 };
            let gap_class = gap % 20;
            score -= (gap_class as f64) * 0.5;
            if next_item_size <= pr {
                score -= 25.0; // lookahead fits here
            } else {
                score += 15.0; // lookahead won't fit, residual likely wasted
            }
        }
    }

    // last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // penalize spreading across many open bins when mean residual is low
    if open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);
    }

    // new-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = 55.0 + (mean_residual * 0.3) - (fitting_bins_count as f64) * 6.0;
    }

    // fraction-of-capacity coupling: residual as fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap: only acceptable if the lookahead item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 35.0;
        }
    } else if post_residual < 35 {
        // Mid gap: mildly penalize unless it exactly matches lookahead.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness coupling: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Dead-space ratio: penalize leaving a gap larger than the item itself.
    if post_residual > item_size {
        score += (post_residual - item_size) as f64 * 0.6;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spawning new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: strong base penalty, softened when the current
        // bin set is badly fragmented (high mean residual spread) or this
        // would be the only fitting option.
        score += 45.0 + 8.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items together in fresh bins
        }
        if mean_residual > 40.0 {
            score -= 10.0; // existing bins are fragmented anyway
        }
    } else {
        // Existing bin: reward when many bins compete, penalize last-chance.
        score -= 3.0 * pressure;
        if fitting_bins_count == 1 {
            score -= 25.0; // last chance: use it or lose it
        }
    }

    // Lookahead synergy: prefer bins where this item leaves room exactly
    // for the next item (perfect pair).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Stream-progression annealing: late in the stream, be stricter about
    // waste since fewer future items remain to fill gaps.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact / tight fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space, quadratically
        let pr = post_residual as f64;
        score += 0.5 * (pr * pr) / cap;
    }

    // 2-step lookahead: reward if next item exactly fills the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 150.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else {
            // next item won't fit here: mild penalty proportional to mismatch
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates usefully
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.2 * dev; // prefer fuller-than-average bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened frivolously
        score += 250.0;
        // but if item is large and would leave awkward residual in any bin, ease opening
        let pr = post_residual as f64;
        if pr > 0.0 && pr < 10.0 {
            score -= 200.0; // near-perfect fill of a fresh bin
        }
        // later in the stream, slightly discourage bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 * progress;
    }

    // Many open bins: encourage consolidating into existing ones
    score += 2.0 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong discount as post_residual approaches zero.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = item_size as f64 / cap;
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Dead-space penalty: penalize residuals too small for typical future items.
        score += (pr / cap).powf(2.0) * 40.0;
        // Reward tight fits relative to bin capacity.
        score -= fill * fill * 30.0;
        // Penalize leaving a residual that is awkward (small but nonzero).
        if pr < 10.0 {
            score += 25.0;
        } else if pr < 20.0 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 15.0 + 20.0 * (nxt / cap);
        } else {
            // Penalize blocking the next item.
            let gap = (post_residual as f64 - nxt).abs();
            score += 8.0 + 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: mild preference toward tighter fits, add small noise-free spread.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Global state: mean residual coupling — prefer bins near the mean residual (balanced packing).
    let res = bin_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor spreading across bins);
    // late in the stream, consolidate aggressively to close bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 20.0 * fill;
    score += (1.0 - t) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if the item is huge, opening a fresh bin is natural.
        score -= fill * 40.0;
        // If no other bin can fit the item, the new bin must be chosen.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 30.0
                 - norm_pr * norm_pr * norm_pr * progress * 25.0;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Penalize creating dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * (25.0 + 20.0 * (1.0 - progress));
        // Reward leaving room exactly for the next item
        let match_term = 1.0 - ((pr - nxt) / cap).abs();
        score -= match_term.max(0.0) * 8.0;
    }

    // Last-chance bonus: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 + 2.0 * progress);

    // Deviation from mean residual: prefer bins near/below mean residual (fill fuller bins)
    let dev = (pr - mean_residual) / cap;
    score += dev * 5.0 + dev * dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..=100 partition residuals into
    // "dead zones" (too small for typical items) vs "usable zones".
    // Class boundaries at multiples of 10 (min item size historically) and 25.
    let dead_zone = post_residual < 10;
    let tight_zone = (10..20).contains(&post_residual);
    let mid_zone = (20..50).contains(&post_residual);

    if dead_zone {
        // Perfect fill or near-perfect fill: heavily reward.
        score -= 60.0;
    } else if tight_zone {
        // Tight residuals are hard to reuse: penalize.
        score += 18.0;
    } else if mid_zone {
        score += 4.0;
    } else {
        // Large residual left: generally fine, mild reward for big bins.
        score -= 2.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0;
    if harmonic && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division class of next_item_size relative to post_residual:
    // does the lookahead item fit exactly / comfortably?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Lookahead perfect fit: strong reward.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let class = post_residual / next_item_size.max(1); // integer division
            if class >= 2 {
                score -= 6.0; // room for multiple future items
            } else {
                score -= 12.0; // lookahead fits
            }
        } else {
            // Lookahead does NOT fit here: if this bin would be nearly full,
            // that's fine; if we waste a big residual, penalize.
            let waste = post_residual as f64 / bin_capacity as f64;
            if waste > 0.3 {
                score += 20.0 * waste;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual is a dead zone).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when all open bins would leave
    // tight/dead residuals and lookahead is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        let poor_fits = fitting_bins_count == 0
            || (post_residual == bin_capacity && next_item_size > 0 && next_item_size <= 20);
        if poor_fits {
            score -= 10.0 + 15.0 * (1.0 - progress) + pressure.min(20.0);
        } else {
            score += 40.0; // discourage opening new bins when decent fits exist
        }
    }

    // Slight tie-break: prefer bins whose residual is above item size with margin.
    if bin_residual >= item_size + 10 && bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=12)
    // are the worst waste; penalize them super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many alternatives: mild penalty so tightest bin wins.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheap.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: prefer it only if current bin would leave a large
    // dead gap that the next item cannot use.
    if bin_residual == bin_capacity {
        score += 40.0; // baseline cost of opening a bin
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 15.0; // existing bins still useful, avoid new bin
        }
        if post_residual == bin_capacity && item_size >= 60 {
            score -= 20.0; // big items deserve fresh bins
        }
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5; // dead space next item can't use
    }

    // Late in stream, waste matters more (no future to amortize into).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // Perfect chain: post_residual == next_item_size is ideal.
            let diff = (post_residual as f64 - n).abs();
            score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
            // Extra bonus if next item exactly fills the bin afterwards.
            if post_residual as u32 == next_item_size {
                score -= 15.0;
            }
        } else {
            // Dead space for the next item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Penalize residuals far from mean (fragmentation indicator).
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect fits are always great.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny residual is near-perfect (items >= 10 originally, but allow 1..100).
        score -= 20.0;
    }

    // Early in the stream, be slightly more willing to spread items across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; prefer tight packing.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good, but dead space below
    // the minimum item size is worthless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 100.0; // perfect fill
    }

    // Penalize post_residual that no future item can plausibly use:
    // waste grows quadratically for large leftovers.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item barely misses, penalize this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            score += 8.0 * ((nxt - post) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.25 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: opening a new bin is only attractive when current
    // open bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            0.0
        } else {
            (mean_residual / bin_capacity as f64).max(0.0)
        };
        // Penalize new bin when existing bins have plenty of room; reward
        // when residuals are small (pressure low) or many bins are open.
        score += 25.0 * pressure - 0.5 * open_bins_count as f64;
        // Large items justify fresh bins more.
        score -= 0.1 * item_size as f64;
    }

    // Time-horizon modulation: early in the stream, be conservative with
    // new bins; late in the stream, prioritize finishing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste);

    // Prefer bins whose residual deviates favorably from the mean
    // (fill below-average-residual bins to consolidate space).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Mild preference to keep many bins from being opened: slight penalty
    // scaled by fragmentation of this bin after placement.
    let frag = if post_residual > 0 && post_residual < 10 {
        1.0
    } else {
        0.0
    };
    score += 10.0 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening of the residual penalty.
    let mut score = pr_norm.powf(2.0) * 120.0 + pr_norm * 30.0;

    // Smooth cubic interaction between residual and stream progress:
    // early on, be tolerant; late, penalize loose fits more strongly.
    score += (0.5 - progress) * (pr_norm.powi(3)) * 90.0;
    score += progress * pr_norm * 25.0;

    // Reward filling bins tightly (post residual near zero) via smooth exponential-free coupling.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 20.0;

    // Dead-space penalty: residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let unusable = ((ns - pr) / cap).max(0.0);
        score += unusable * unusable * 80.0 * (0.5 + progress);
        // Bonus if this placement leaves room exactly for the lookahead item.
        let gap = (pr - ns).abs() / cap;
        score -= (1.0 - gap.min(1.0)) * 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 3.0;
    }

    // Slight penalty for scattering across many bins relative to mean residual.
    score += ((open_bins_count as f64) / (1.0 + mean_residual / cap)) * 0.5;

    // New-bin candidate must not win unless open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes (high packing density) are strongly favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits with a strong non-linear bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Harmonic class penalty: leftover space that is a small prime-ish residue
    // (1..=9 mod 30) is hard to fill later; penalize those classes.
    let class = post_residual % 30;
    if (1..=9).contains(&class) {
        score += 12.0;
    } else if (10..=19).contains(&class) {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement chains perfectly — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let chained_pr = post_residual - next_item_size;
            score -= (30.0 * (1.0 - chained_pr as f64 / cap)).max(0.0);
            if chained_pr <= 10 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's leftover; mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when current
    // open bins have poor residuals or the fit is bad.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly above a good fit, below a bad one.
        score = cap * 0.55;
        if mean_residual < cap * 0.25 && open_bins_count > 0 {
            score -= 15.0; // existing bins are nearly full anyway
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // opening a bin when alternatives are scarce is fine
        }
        // Early stream: allow more bins; late stream: discourage sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        return score;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (pr - mean_residual) * 0.3;

    // Small global pressure: with many open bins, push toward consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let min_useful = 10.0_f64.min(next_item_size as f64).max(1.0);
    if post_residual > 0 && (post_residual as f64) < min_useful {
        score += 25.0 + (min_useful - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual as f64 <= item_size as f64 * 0.1 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: favor bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Slight alignment with mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fill bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.4;
            if slack < 10.0 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: just minimize post residual
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit is bad everywhere.
    if bin_residual == bin_capacity {
        score += 90.0 - 30.0 * progress; // cheaper to open bins early, expensive later
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain next item
        }
    }

    // Mild penalty for very small dead space that is hard to fill (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual exactly or well, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
        } else {
            // Post residual can't host the next item: penalize wasted potential.
            score += post_residual as f64 * 0.10;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to prefer conserving the best-fitting bins.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate logic: opening a new bin should be penalized unless
    // the item fits poorly everywhere (large post_residual in this bin).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // More open bins already available => discourage new bins.
        score += open_bins_count as f64 * 1.2;
        // Early in the stream, opening bins is cheaper (future items may pair).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += (mean_residual - item_size as f64).max(0.0) * 0.20;
    } else {
        // Using an existing bin: reward keeping open bin count low.
        score -= 3.0;
        // Prefer bins whose residual is close to the item (best fit among open bins).
        let fit_gap = (bin_residual - item_size) as f64;
        score += fit_gap * 0.05;
        // Prefer filling bins with small residual (avoid many half-empty bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild time horizon coupling: later in stream, prefer aggressive consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual (tight fit), with non-linear sharpening
    let norm_post = post / cap; // 0..1
    let mut score = norm_post * (1.0 + 2.5 * norm_post * norm_post);

    // Smooth reward for near-perfect fits (post_residual close to 0)
    score -= (1.0 - norm_post).powi(4) * 3.0;

    // Penalize dead space that cannot fit typical future items
    let dead = if post < 10.0 { 0.0 } else { post };
    score += (dead / cap).powi(2) * 1.2;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (fragmented) or stream is early
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual / cap) - 0.5).max(0.0);
        let openness = 1.0 - progress;
        score += 4.0 - 2.5 * fragmentation - 2.0 * openness * openness;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 0.8 * (1.0 - slack).powi(2);
        } else {
            score += 0.5 * (nxt - post) / cap;
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.15 * progress;

    // Smooth stream-progress coupling: late stream favors tighter packing
    score *= 1.0 + 0.5 * progress * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (divisible into common small sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward post-residuals that are "harmonic": divisible by 5 or 10,
    // i.e. reusable by typical item sizes.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize tiny dead space classes (1..=5) that are nearly unusable.
        if pr <= 5 {
            score += 4.0 * (6 - pr) as f64;
        }
        // Nonlinear penalty on mid-range unusable leftovers.
        if pr > 0 && pr < 10 {
            score += 2.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 12.0;
    }

    // Harmonic fraction of capacity filled.
    let fill = 1.0 - frac;
    score -= 5.0 * fill * fill; // quadratic bonus for fuller bins

    // Modulo threshold coupling with next item (lookahead, k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        // If the next item fits exactly into post_residual, big reward.
        if post_residual == next_item_size {
            score -= 10.0;
        } else if (post_residual - next_item_size) % 5 == 0 {
            score -= 4.0;
        } else {
            score -= 1.5;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; leftover becomes stranded until stream ends.
        score += 0.03 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // nearly full or the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        // Penalize new bins mildly; relief when open bins are congested.
        score += 10.0 - 6.0 * (1.0 - pressure.min(1.0)) - 3.0 * progress;
        if item_size > 50 && mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild preference to spread load when many bins are open.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize heavily when post_residual is nonzero but too small for typical items.
    if post_residual > 0 {
        // Unusable gap threshold: gap below minimum item size is pure dead space.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Small-but-usable gaps (10..25) are fragile: likely to become dead space.
        if post_residual < 25 {
            score += 25.0 * (25.0 - post_residual as f64) / 15.0;
        }
        // Perfect or near-perfect fits are strongly rewarded.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Coupling with lookahead: if the next item fits the post_residual exactly,
    // this placement chains nicely; penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 50.0;
        } else if next_item_size > post_residual {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 15.0 {
                score += 20.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Open-bin pressure: discourage scattering across many bins; prefer filling
    // existing bins when the fit is decent, but allow new bins for perfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 3.0 * (1.0 - progress * 0.5);

    // Mean-residual coupling: if this bin's residual deviates below the mean
    // (i.e., we're compacting it), reward; if it stays far above mean, penalize.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the current-bin alternatives
    // would create dead space (their penalties above already push score high).
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is heavily rewarded.
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).powi(6);
        // Extra bonus if the next item fits EXACTLY (zero waste after two steps).
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that the next item cannot use at all
        // (dead space relative to the lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += 0.3 * post_residual as f64;
    }

    // Penalize dead space below typical small-item threshold (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with mean residual: prefer bins whose post-residual sits near the
    // open-bin average (keeps the fleet of bins homogeneous and reusable).
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make the empty bin moderately unattractive so we only
    // open new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // But if the next item is large and current post_residual would be tiny,
        // opening a fresh bin becomes more appealing.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Slight late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.5 * waste;
    }
    // Reward exact fit for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64) * (1.0 + progress)
        };
        score = bin_capacity as f64 - 10.0 + pressure * 40.0;
        // Late in the stream, prefer reusing open bins more strongly.
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is flexible for next item
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor consolidation.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += 0.15 * mean_gap;
    } else {
        score -= 0.10 * (-mean_gap);
    }

    // Slight penalty for bins much emptier than average (keep large residual bins available).
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    }

    // Prefer filling bins that are already fairly full (low residual) even more.
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small post-residuals more strongly later in the stream (dead space)
    score += 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (pr / (next_item_size as f64 + 1.0)).min(1.0));
    }

    // Prefer bins with residual below mean residual (denser bins) smoothly
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Reward post-residuals that fall into "usable" harmonic classes
    // (small residues are more likely to be filled by future small items).
    if r10 == 0 {
        score -= 8.0; // perfectly divisible residual: excellent anchor class
    } else if r10 <= 2 {
        score -= 4.0;
    } else if r10 >= 8 {
        score += 5.0; // large dead-space residue class
    }

    // Integer-division thresholds: quarter classes of the capacity.
    let quarter = post_residual / (bin_capacity / 4);
    match quarter {
        0 => score -= 3.0,          // post_residual < 25: near-full bin, good
        1 => score += 0.5,          // 25..49: middling
        2 => score += 2.0,          // 50..74: half-empty bin kept open
        _ => score += 1.0,          // 75..100: nearly empty
    }

    // Modulo coupling with next item: if next_item_size divides into
    // post_residual cleanly (same harmonic family), reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = post_residual % next_item_size == 0;
        let tight_next = post_residual - next_item_size < 10;
        if fits_next {
            score -= 10.0;
        }
        if tight_next {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // Next item can't use this residual at all: penalize leftover class
        score += (post_residual % 20) as f64 * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        // Base penalty so open bins are preferred unless they are bad hosts.
        score += 30.0;
        // If mean residual is small (bins are tight), opening a new bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // Late in the stream with many open bins, avoid proliferation.
        if total_items > 0 && (step_index as f64) > 0.7 * (total_items as f64) {
            score += 10.0 * pressure;
        }
        // If the item is large, a fresh bin is a natural host.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Fraction-of-capacity tightness reward for real bins.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_frac;

    // Small global pressure term: when many bins are open, prefer tightening.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small but nonzero leftovers (1..10)
    // are effectively unusable for future items (min size 1, but typical
    // stream items are >=10); penalize them heavily, scaled by how dead
    // the gap is relative to the smallest plausible item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (10.0 - post_residual as f64);
    }

    // Mid-range gaps (10..=20) are semi-dead: mild penalty since only
    // small items can use them.
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so this bias
    // only affects genuinely open bins via mean_residual coupling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 3.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);
    } else {
        // New-bin candidate: penalize more when many bins are already open
        // and the stream is far along; allow new bins early or when open
        // bins have poor residuals.
        score += 8.0 * (open_bins_count as f64).sqrt() * (0.3 + progress);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0; // open bins are nearly full; new bin is fine
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward residual that matches the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0; // perfect two-item chain: fill bin completely next step
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space relative to its size
        score += 6.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
