pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // later, penalize residual waste more aggressively.
    let coupling = 1.0 + progress * progress * (pr / cap) * (1.0 - progress);
    score *= coupling;

    // Dead-space penalty: residuals too small for any plausible item (>=1)
    let dead = if pr < 1.0 { 0.0 } else { (1.0 - pr / cap).powi(6) };
    score += dead * cap * (0.2 + 0.8 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage opening new bins while open bins fit,
    // scaled by how much slack already exists across open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which quarter of capacity it occupies
    let item_class = item_size / 25; // 0..3 harmonic class
    let post_class = post_residual / 25;

    // Reward tight fits: post_residual near zero or landing on a "harmonic" residue
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic residue bonus: post_residual divisible by common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: reward leaving room exactly for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here; slight penalty
        }
        // Harmonic coupling: next item class matches leftover class
        if next_item_size / 25 == post_class && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists (encourage packing into open bins by default)
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 35.0; // big item with no open-bin fit -> new bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 5.0; // don't open new bins when pairing is possible elsewhere
        }
    }

    // Late in stream: consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Prefer bins below mean residual (keeps residual variance low)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 4.0 * dev;

    // Mild penalty per open bin to discourage bin proliferation
    score += 0.5 * open_bins_count as f64;

    // Small item into a big-residual bin: reward (pairing potential)
    if item_class == 0 && bin_residual >= 60 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

