    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals become more costly (dead space risk)
    let poly = x * x * (1.0 - progress) + (1.0 - x) * (1.0 - x) * progress;
    score += 40.0 * poly;

    // Reward near-perfect fits more strongly as stream advances
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.5 };
        let gap = (pr - next_item_size as f64).abs();
        score += 12.0 * (1.0 - fits_next) * (1.0 + gap / cap);
        score -= 6.0 * fits_next * (1.0 - gap / cap) * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x * x);
    }

    // Mild penalty when many bins are open and this placement leaves large residual
    score += (open_bins_count as f64).ln().max(0.0) * x * 5.0;

    // Deviation from mean residual: prefer bins below/at mean residual (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = 45.0 + 20.0 * (1.0 - progress) - 15.0 * x;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are worth more.
    let usable = |r: u32| -> f64 {
        if r == 0 { return -6.0; } // perfect fill is excellent
        let mut bonus = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if r % d == 0 { bonus -= 2.0; }
        }
        if r <= 10 { bonus -= 3.0; }        // nearly-full bin: tiny dead space
        else if r <= 25 { bonus -= 1.5; }
        else if r >= 60 { bonus += 2.0; }   // large leftover = wasteful placement
        bonus
    };

    score += usable(post_residual);

    // Penalize leaving a gap that cannot fit the known next item when the gap
    // would otherwise be "almost" usable.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 2.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: make it unattractive unless all open residuals are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 5.0 - 3.0 * pressure;
    }

    // Late in the stream, tighten up: prefer fuller placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    // Integer-division threshold: bins whose residual class bucket is small
    // (tight fit) get a nudge.
    let bucket = post_residual / 10;
    score -= (10 - bucket.min(10)) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residual that cannot fit next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residual that can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.35;

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening: be more selective as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item,
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.9;
            // exact 2-chain fit bonus
            if post_residual == next_item_size {
                score -= 300.0;
            }
        } else {
            // next item cannot use leftover: penalize proportionally to wasted space
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Tight fit relative to current residual: prefer filling bins snugly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Compare post_residual against mean residual: prefer leaving less than average
    // (i.e., filling tighter than typical open bins).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit likely in existing bins) or when open bins are already tight.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 45.0 - 40.0 * tightness;
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Late in stream: be more conservative, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with a mild quadratic penalty
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && post_residual > 0 {
            // dead space for the known next item
            score += 8.0 + 0.1 * (post_residual as f64);
        } else if (post_residual as f64) >= nxt {
            // this bin can also host the next item: strong reward
            score -= 6.0 + 0.05 * nxt;
        }
        // reward exact two-item closure
        if item_size as f64 + nxt == bin_residual as f64 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate unless open bins fit poorly
    if bin_residual == bin_capacity {
        // new bin baseline: its post residual equals capacity - item_size
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64) * 0.5 + mean_residual * 0.1;
        // open new bin early or when mean residual is low (fragmented bins)
        score += 30.0 + pressure * (1.0 - progress) - 10.0 * progress;
    } else {
        // Slight preference for filling already-open bins with large residual
        score -= 0.02 * (bin_residual as f64);
    }

    // Prefer bins whose residual deviates below mean (consolidate emptier space)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Reward tight fits more strongly as the stream progresses
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + p2);
    // Penalize large dead space, amplified late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + p3);
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0 * (1.0 + p2);
    }
    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 25.0 * (1.0 - ((pr - nxt) / cap).abs()) * (0.3 + p2);
        } else {
            score += 15.0 * (1.0 + progress);
        }
    }
    // Prefer filling bins when many bins are open
    score -= 10.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);
    // Mild pull toward mean residual alignment
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls in
    // "awkward" residue classes modulo small integers.
    let r = post_residual as i64;
    let awkward = ((r % 10) as f64 * 0.6) + ((r % 7) as f64 * 0.4) + ((r % 5) as f64 * 0.5);
    score += awkward;

    // Perfect fit bonus (harmonic zero class).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or nearly (chained harmonic classes).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0;
        } else if gap > 0 && gap <= 10 {
            score -= (10 - gap) as f64 * 2.5;
        } else if gap < 0 {
            // next item won't fit here: penalize large leftover
            score += (-gap) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.5;
        score += 90.0 - pressure - progress * 10.0;
        if item_size >= 60 {
            score -= 40.0; // large items fine in fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0; // pair potential in fresh bin
        }
    }

    // Tightness coupling: prefer bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Deviation from mean residual: prefer bins below-mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Many open bins: mild pressure to close bins out.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are fine,
    // but residuals that are small yet nonzero relative to the item stream are risky.
    // Penalize gaps that can't fit a typical future item (mean residual scale).
    if post_residual > 0 {
        // gap too small to be useful for the lookahead item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // gap below the typical small-item scale: dead space
        if (post_residual as f64) < mean_residual * 0.35 {
            score += 15.0;
        }
        // very tiny slivers are almost always dead
        if post_residual <= 3 {
            score += 20.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits relative to residual (best-fit flavor)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio) * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; reduce if stream is early or open count is high
        let base = 18.0;
        let early_discount = 10.0 * (1.0 - progress);
        score += base - early_discount;
        // if current bin would leave a bad gap anyway, new bin becomes relatively better
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
            score -= 8.0;
        }
    }

    // Lookahead synergy: if residual after placement exactly fits next item, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (2-step lookahead chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-diff / 12.0).exp();
        // Soft coupling to mean residual: prefer bins whose leftover tracks the fleet average.
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    } else {
        // Last item: just minimize waste.
        score += 0.05 * post_residual as f64;
    }

    // Penalize large dead space that nothing (min size 1, typically >=10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is actually great; but tiny useless sliver after big item
    }
    if post_residual >= 10 {
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0
            && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 2;
        if tight_fit_exists {
            score -= 45.0; // open fresh bin for a perfect 2-item chain
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64; // discourage needless bin opening
        }
    }

    // Early stream: slightly favor consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead fit: reward proportional to how well it nests.
            let nest = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 10.0 * nest;
        } else {
            // Next item cannot use this bin's leftover: penalize large dead space.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight penalty to encourage diversity of choice elsewhere.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global residual alignment: prefer bins whose residual is close to the mean (avoid
    // fragmenting one very-full bin while leaving another very-empty).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, keep bins flexible (penalize very small residuals);
    // late in the stream, prioritize filling bins as tightly as possible.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= t * 8.0 * fill_ratio;
    score += (1.0 - t) * 0.04 * post_residual as f64;

    // Many open bins: encourage closing them out by filling existing bins rather than
    // opening new ones — penalize the empty-bin candidate implicitly via its large residual.
    if open_bins_count > 4 {
        score -= 0.15 * open_bins_count as f64 * (1.0 - post_residual as f64 / cap);
    }

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, slightly convex to prefer tight fits
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins fully (tight fits); later, tolerate spread
    let coupling = norm_pr * (1.0 - norm_pr); // peaks at half-empty residual
    score += 60.0 * coupling * (1.0 - progress) * (1.0 - progress);

    // Penalize residual below next item size (dead space), smoothly
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * (0.5 + 0.5 * progress);
        } else {
            // reward residuals that can host the lookahead item
            score -= 8.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Nudge toward bins close to mean residual (balance), smooth
    score += 0.1 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual belongs to "dead"
    // classes (small leftovers nothing can fill) are penalized; classes in the
    // reusable sweet spot are rewarded.
    let dead_zone = 1u32..10;
    if dead_zone.contains(&post_residual) {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward residuals that are multiples of common item-size classes
    // (harmonic classes via integer division thresholds).
    let classes: [u32; 5] = [10, 20, 25, 40, 50];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            harmonic_bonus += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect pair — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            let new_res = post_residual - next_item_size;
            if new_res < 10 {
                score += (10 - new_res) as f64 * 2.0; // would create dead space
            } else {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.4;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 20.0;
        }
    }

    // Tight fits are good: penalize less when item nearly fills the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * open_bins_count as f64 * 0.5;

    // Mild attraction to below-mean residual bins (pack fuller bins together).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (or the lookahead item) are unusable dead space -> heavy penalty.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 12.0;
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward exact match with the lookahead item (sets up a perfect fit next step).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Keep enough room for the next item: mild reward proportional to slack.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This placement kills the chance to co-locate the next item.
        score += 10.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // or open-bin count is low relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        // Base cost of a fresh bin; discounted when few bins can fit the item.
        score = 100.0 - scarcity * 60.0 - progress * 10.0;
        if post_residual == 0 { /* unreachable, keep symmetric */ }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference to balance residuals toward the mean (avoid skewed bins).
    score += ((post_residual as f64 - mean_residual) / 50.0).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 60.0;
        // Penalize opening a new bin when an open bin fits the item well.
        if fitting_bins_count > 0 {
            let tight = (bin_residual - item_size) as f64;
            let best_gap = (mean_residual - item_size as f64).abs();
            if best_gap < 12.0 {
                score += 25.0; // an open bin fits nearly perfectly -> avoid new bin
            }
        }
        // Reward new bin when it is the last resort.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Slight preference to keep bins open early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        return score;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - gap / 100.0).max(0.0);
        // Bonus if next item fits exactly into post_residual.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer tightest fit, no lookahead needed.
        score -= 10.0;
    }

    // Relative-to-mean coupling: favor bins whose residual is below average
    // (concentrating waste in few bins), penalize above-average bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance logic: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Reward filling bins completely (small post_residual is inherently rewarded
    // by the base term, add a mild non-linear boost).
    score -= 5.0 * ((post_residual as f64 / bin_capacity as f64).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Quadratic penalty for leftover dead space, scaled by capacity.
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    }

    // Reward tight fits relative to residual (small waste fraction).
    let residual_f = bin_residual as f64;
    if residual_f > 0.0 {
        let fill_ratio = item_size as f64 / residual_f;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits: reward proportional to how well it fills the leftover.
            score -= 18.0 * (nxt / post);
        } else {
            // Next item won't fit here: slight penalty, this bin is a dead end.
            score += 8.0 * (1.0 - post / (nxt + 1.0));
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and fits many open bins poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Discount the new bin when few bins fit the item (crowding pressure).
        if fitting_bins_count > 0 {
            score -= 30.0 / fitting_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper (build inventory).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If mean residual is high, prefer reusing existing bins.
        score += (mean_residual / bin_capacity as f64).min(1.0) * 25.0;
    }

    // Mild penalty when many open bins already exist (avoid bin proliferation).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Small time-dependent tie-breaker noise-free deterministic jitter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.01 * ((progress * 100.0).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear penalty growth
    let mut score = post + 0.15 * (post * post) / cap;

    // Smooth interaction: late in the stream, dead space matters more
    let late = progress * progress;
    score += late * (post * post) / (cap * cap) * 8.0;

    // Reward filling bins nearly exactly (post near 0) more strongly over time
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead: bonus if next item fits the post-residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0) / cap;
        score += 5.0 * fits * fits - 3.0 * (1.0 - fits) * (nxt / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap) + 5.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * (dev * dev) / cap;

    // Prefer consolidating into fewer bins when many are open
    score += 0.2 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize dead space by capacity fractions.
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i64; // 0..=10 harmonic classes
    score += match class {
        0 => 0.0,
        1 => 8.0,
        2 => 5.0,
        3 => 12.0,
        4 => 9.0,
        5 => 3.0,
        6 => 14.0,
        7 => 10.0,
        8 => 6.0,
        9 => 2.0,
        _ => 0.0,
    };

    // Modulo arithmetic on post_residual: values that are multiples of common
    // item sizes (e.g. multiples of 10 or 25) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.3;
            // next item leaves a harmonic-friendly residual too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = mean_residual / cap;
        score = 40.0 + pressure * 20.0 - tight * 30.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0;
        }
    }

    // Stream progression: early on, be more willing to keep bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Slight penalty for very small post_residual that wastes little but blocks nothing.
    if post_residual > 0 && post_residual < 5 {
        score -= 2.0;
    }

    // Tie-break by mean residual alignment: prefer bins near the mean (keeps balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // Modulo threshold on next_item_size classes: common sizes (multiples of 5)
    // are more likely to recur, so favor residuals they can consume.
    if next_item_size % 5 == 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect/near-perfect closure of the bin
    } else if post_residual < 20 {
        score += 35.0; // small unusable gap penalty
    } else if post_residual < 40 {
        score += 12.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap blocks the known next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this is a bad fit.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0
            + (mean_residual - item_size as f64).max(0.0) * 0.5
            + if post_residual > 0 && post_residual < 10 { -25.0 } else { 0.0 };
    } else {
        // Open-bin pressure: mild reward for filling existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 + progress * 5.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-item fill: post_residual exactly consumed by next item.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 + (slack_after_next as f64).min(20.0);
        } else {
            // Penalize dead space that next item cannot use.
            score += (post_residual as f64) * 0.35;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual), already in base.
    }

    // Relative-to-mean coupling: bins with residual below mean are precious; prefer filling them.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize creating large unusable gaps (< smallest item) beyond next item.
    if post_residual > 0 && post_residual < 10.min(item_size) {
        score += 25.0;
    }

    // New-bin candidate: prefer reusing open bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
        // Opening a new bin is attractive when no open bin gives a good 2-step fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Progress coupling: tighten packing more aggressively later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), slightly superlinear.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 30.0;

    // Reward filling bins completely (post_residual small relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Penalize dead space that no plausible future item can use:
    // residual space below the minimum item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fill: strongly reward
    } else if post_residual > 0 && post_residual < item_size {
        // dead space smaller than current item: mildly bad
        score += (item_size - post_residual) as f64 * 0.15;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin mildly,
    // more so early in the stream or when mean residual is still large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + open_pressure * 4.0 + mean_residual * 0.08 - progress * 8.0;
        // If the item is large and mean residual is small, new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 9.0;
        }
    }

    // Global state: many open bins with large mean residual -> encourage
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // Prefer placing small items into bins with small residuals
    // (preserve large residual bins for large future items).
    let residual_norm = bin_residual as f64 / bin_capacity as f64;
    if item_size < 40 && residual_norm > 0.5 {
        score += 5.0 * residual_norm;
    } else if item_size >= 40 && residual_norm < 0.5 {
        score -= 3.0;
    }

    // Late stream: tighten packing, penalize any leftover more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Quadratic dead-space penalty, amplified later in the stream
    let quad = norm_pr * norm_pr * cap;
    score += quad * (0.3 + 0.7 * progress);

    // Cubic term: strongly punish large unusable gaps as stream matures
    score += norm_pr * norm_pr * norm_pr * cap * progress;

    // Reward tight fits (small post_residual) smoothly via negative coupling
    let tight = 1.0 - norm_pr;
    score -= tight * tight * item_size as f64 * (1.0 - progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    }

    // Last-chance bonus: only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * progress;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += (pr - mean_residual).abs() * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = match post_residual {
        0 => 0u32,                 // perfect closure
        p if p < eighth => 1,      // tiny dead space
        p if p < quarter => 2,     // small
        p if p < 2 * quarter => 3, // half-ish
        _ => 4,                    // large residual
    };

    // Reward exact/near closure strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else {
        // Non-linear penalty per class: tiny residuals are nearly worthless space.
        let class_penalty = match post_class {
            1 => 30.0,
            2 => 8.0,
            3 => 0.0,
            _ => -6.0,
        };
        score += class_penalty;

        // Dead-space ratio with quadratic coupling to item size class.
        let item_class = item_size / quarter; // 0..3 harmonic item tier
        let waste = (post_residual as f64 / cap).powi(2) * (50.0 + 20.0 * item_class as f64);
        score += waste;
    }

    // Lookahead: does the next item fit the post-residual? Harmonic compatibility.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward, scaled by how snugly next item nests (integer division tier).
            let snug = (next_item_size * 4) / bin_capacity.max(1); // 0..4 tier
            score -= 25.0 + 10.0 * snug as f64;
        } else {
            // Next item won't fit here: penalize leaving a medium residual that nothing typical can use.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 + gap.min(40.0) * 0.5;
        }
    } else {
        // Last item: closure is everything.
        score -= 60.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Many open bins: prefer consolidating into bins with low residual (tight packing).
    if open_bins_count > 3 {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness * ((open_bins_count as f64).ln());
    }

    // Mean residual pull: prefer bins below mean residual (tighter bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let early = (step_index as f64) / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure + 20.0 * (1.0 - early) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (low post residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate (empty bin): penalize mildly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // Slight preference toward bins below mean residual (balance usage).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement enables a perfect follow-up — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64) * 0.5;
        } else {
            // Next item cannot use this bin's remainder; penalize large dead space.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is above mean (they have more slack to waste),
    // penalize draining below-mean bins into unusable fragments.
    if post_residual as f64 > mean_residual {
        score -= 5.0;
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If next item is large, a fresh bin is more valuable.
        score -= (next_item_size as f64) * 0.1;
    }

    // Penalize very large post_residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (wasted capacity grows super-linearly).
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Reward tight fits: small post_residual strongly favored.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 25 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // When many bins are open, prefer consolidating into fuller bins
    // (bin with residual far below mean residual is more "full").
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff;

    // Early in the stream, be more willing to open new bins (exploration);
    // later, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses,
        // but less when open bins are mostly full (mean residual small).
        let new_bin_penalty = 30.0 + 60.0 * progress - 0.4 * mean_residual;
        score += new_bin_penalty.max(5.0);
    } else {
        // Existing bin: mild reward that grows with progress.
        score -= 10.0 * progress;
    }

    // Slight preference for bins with less residual overall (fuller bins first).
    score += 0.2 * bin_residual as f64;

    // If few bins are open and item is small, allow spreading (exploration).
    if open_bins_count <= 2 && item_size <= 30 && bin_residual == bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with mild non-linear penalty
    let mut score = post * (1.0 + 0.5 * (post / cap) * (post / cap));

    // Penalize residuals that are too small to be useful (dead space), smoothly
    let dead = (1.0 - post / cap).max(0.0);
    score += 20.0 * dead * dead * dead;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late in stream, demand tight fits
    score += 30.0 * (post / cap) * progress * (1.0 - progress) * 2.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 15.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // Slight preference toward filling existing bins when many are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: mild penalty so it's chosen only on very poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by 10
    // are "clean" slots that future items (drawn from a coarse grid) reuse well.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.8; // penalize off-grid dead space

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small but awkward residual (< 10) is dead space: strongly penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits relative to capacity fraction.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a chain placement -> reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // prefer leaving a harmonic residual for the next item
            if post_residual % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; larger post residual is wasted
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // or the fit here would be very poor.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let poor_fit = (post_residual as f64) > item_size as f64 * 0.9;
        if avg_pressure < 15.0 || (poor_fit && fitting_bins_count <= 2) {
            score -= 40.0;
        } else {
            score += 120.0; // keep using existing bins when fits are decent
        }
    }

    // Late in the stream, consolidate: fewer open bins preferred.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 1.5;

    // Prefer bins tighter than average (best-fit bias).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it is smaller than the smallest plausible item (1),
    // but practically, gaps below ~10 (typical minimum) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across too many bins.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap -> mild penalty proportional to gap waste
        score += 0.1 * post_residual as f64;
    }

    // Prefer filling bins with lower mean residual (consolidate fullness).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fill
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare against mean residual: bins tighter than mean are attractive.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when this item is huge relative to
    // typical residuals (poor fit everywhere else) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (fitting_bins_count == 0) as i32 as f64;
        score += 30.0 - 20.0 * poor_fit - 25.0 * (1.0 - progress) - 0.1 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pair packing into fresh bin is promising
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with slight superlinearity
    let pr = post_residual as f64;
    score = pr * (1.0 + pr / bin_capacity as f64);

    // Reward placements where the next item also fits into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            // residual likely dead space relative to lookahead
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small residual that most items can't use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins -> prefer consolidating into existing bins
    score -= 0.05 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (balance) early, exploit best-fit late
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * (1.0 - t);

    // New-bin candidate handling: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit the item
        if fitting_bins_count > 0 {
            let best_possible = pr.min(item_size as f64); // post_residual == capacity here
            score = bin_capacity as f64 + 5.0 * fitting_bins_count as f64;
            // If lookahead item is large, a fresh bin is more valuable
            if next_item_size >= item_size && next_item_size > 50 {
                score -= 6.0;
            }
        } else {
            score = 0.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: reward tight fits (low post residual), with quadratic sharpening.
    let mut score = pr * (1.0 + 2.0 * fit_norm * fit_norm);

    // Dead-space penalty: residuals that are too small to ever fit typical items.
    let dead = (pr / cap).powi(4);
    score += 60.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use this bin's post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 + progress);
        // Reward if next item fits snugly into post residual.
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap));
        }
    }

    // Stream-progress coupling: early on, keep bins flexible (favor moderate residuals);
    // later, prefer filling bins tightly.
    let flex = (mean_residual / cap).max(0.0).min(1.0);
    score += (1.0 - progress) * 10.0 * (pr / cap) * (1.0 - flex);
    score -= progress * 12.0 * (1.0 - fit_norm);

    // Crowd penalty: with many open bins, discourage spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fit_norm);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = pr + 40.0 - 35.0 * (fitting_bins_count == 0) as i32 as f64 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

