    let pr = post_residual;
    // Perfect fit bonus
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty grows superlinearly for tiny unusable residuals
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Modulo classes: residuals divisible by 10 are "harmonic" — easier to fill later
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
        // Integer-division thresholds: penalize residuals in awkward bands
        let band = pr / 25; // 0..4
        score += match band {
            0 => 25.0, // 1..24: nearly dead
            1 => 5.0,  // 25..49
            2 => 0.0,  // 50..74
            _ => -3.0, // 75..99: still roomy
        };
        // Reward residuals that can exactly host a typical lookahead chunk
        if next_item_size > 0 && pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 15.0;
            }
            score -= slack as f64 * 0.1;
        }
        // Next item cannot fit here afterwards: penalize mildly
        if next_item_size > 0 && pr < next_item_size && pr > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        // If mean residual across open bins is small, opening a new bin is fine
        score = 40.0 + 200.0 * congestion;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            score += 120.0; // don't abandon the only fitting bin
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Small tie-break coupling with open bin count
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are unusable by
