    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 25 {
        // Medium-small gaps: moderate penalty scaled by gap tininess.
        score += 0.6 * (25.0 - post_residual as f64);
