            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        } else {
            // next item can't use this gap: penalize proportional dead space.
            score += 0.25 * post_residual as f64;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or no open bin fits well. Penalize opening new bins generally.
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
