        }
        if post_residual >= 30 {
            score -= 10.0; // fresh bin leaves useful space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item fits after this one.
        let lookahead_slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - lookahead_slack * 0.5;
        // Extra reward if the chain continues (post_residual - next_item_size still usable).
        if post_residual - next_item_size >= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 25.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize new-bin candidate mildly unless it is genuinely needed
    // (empty bin has large post_residual; lookahead reward may already favor it).
    if bin_residual == bin_capacity {
        score += 40.0;
        // If next item is large, opening a fresh bin can be wise.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    // Slight preference for fewer open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 20.0;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    // Time horizon: early in the stream, be more conservative (favor packing
    // into existing bins); late in the stream, weight post residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it is a very
    // large item that would leave open bins badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else {
            0.0
        };
        score += 10.0 - 25.0 * (item_size as f64 / bin_capacity as f64);
        if fragmentation < 0.2 {
            score += 5.0; // big item, opening a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, but with non-linear (quadratic) coupling to stream progress.
    // Early in the stream, keep residuals flexible; late, pack tightly.
    let mut score = pr * (1.0 + 0.6 * progress) - 12.0 * fill * fill * (0.5 + progress);

    // Penalize dead space quadratically when it's too small for typical future items.
    let dead = (pr / cap).powi(3);
    score += 25.0 * dead * (1.0 + progress);

    // Lookahead coupling: reward leaving room for the next item (smooth interaction).
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = pr - ni;
        let gapn = gap / cap;
        // smooth bump: reward when post_residual is just above next_item_size
        score -= 8.0 * (-(gapn * gapn * 400.0)).exp() * (1.0 - progress * 0.5);
        // penalize if placing here blocks the next item elsewhere
        if gap < 0.0 {
            score += 4.0 * (-gap / cap) * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // spread load mildly when many bins fit
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Prefer bins with residuals near the mean residual (keeps bin states homogeneous),
    // smooth quadratic coupling.
    let dev = bin_residual as f64 - mean_residual;
    score += 2.0 * (dev / cap).powi(2);

    // Mild preference for using fewer bins overall (favor existing bins vs new bin).
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible,
    // with smooth dependence on progress and item size.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (item_size as f64) / cap;
        score += 10.0 + 20.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo capacity in 10-unit classes
    let class = post_residual % 10;
    // Dead-space penalty: residuals that are unusable for typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Class-based coupling: residuals near multiples of 10 are more reusable
    score += class as f64 * 1.5;

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let waste = next_item_size.saturating_sub(post_residual);
            score += waste as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if pressure > 3.0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Mild best-fit sharpening: prefer tighter fits among similar residuals
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Stream progression: early on, be conservative about fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum plausible item are pure waste; penalize them hard.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit, no dead space at all -> handled below
    }
    if post_residual == 0 {
        score -= 500.0; // perfect fill is the best possible outcome
    } else if post_residual < 10 {
        // tiny unusable gap: severe dead-space penalty
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // moderately awkward gap
        score += 15.0 + (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // no open bin offers a good fit; add pressure that grows with open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // If lookahead item could pair with a fresh bin, slightly soften.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Open-bins pressure: penalize placements that leave bins scattered;
    // encourage consolidating into bins whose residual is near mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for bins with larger residuals when many bins open
    // (keep few near-full bins "finished" and use roomy ones).
    score -= 0.1 * (bin_residual as f64) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Late in the stream, tighten up: weight dead space more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 25.0; // perfect chain: next item closes this bin
        } else if nxt <= pr {
            // next item fits; reward proportionally to how much of post space it consumes
            score -= 12.0 * (nxt / pr);
        } else {
            // dead space for the next item: penalize leftover smaller than next item
            score += 0.35 * (nxt - pr);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // using them tightly is good, wasting them is bad.
    let mr = mean_residual.max(1.0);
    let rel = post_residual as f64 / mr;
    if rel < 0.5 {
        score -= 6.0 * (0.5 - rel); // tight vs. average: reward
    } else if rel > 1.5 {
        score += 4.0 * (rel - 1.5); // leaving more than average: mild penalty
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 45.0 + 5.0 * open_bins_count as f64;
        } else {
            // forced new bin: small bonus so it wins over nothing
            score -= 30.0;
        }
    }

    // Progression: as the stream matures, be more conservative with slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space below next item is worthless.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains usable by the next item: reward.
            score -= 0.35 * next_item_size as f64;
            // Perfect two-item chaining: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            // Dead space: penalize proportionally to how far below the next item it is.
            let gap = (next_item_size as f64 - post_residual as f64).min(item_size as f64);
            score += 0.25 * gap;
            // Very small unusable slivers are pure waste.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: only one open bin fits; avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }
    // Many bins fit: mild penalty so we prefer scarce options elsewhere.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // New-bin candidate: opening a bin is only attractive when the item fits poorly
    // everywhere (large residual mismatch) or few bins exist early in the stream.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual equals capacity - item.
        score += 12.0;
        // Early stream with few open bins: opening is cheap, discount it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 14.0 * (1.0 - progress) * (1.0 - progress);
        // If current bin would leave a big gap vs next item, opening looks better.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a "tight" direction:
    // packing into tighter-than-average bins consolidates space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild reward for filling large items into already-open bins as stream ends near.
    if total_items > 0 && step_index + 1 >= total_items.saturating_sub(2) {
        score -= 3.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Tie-break: exact-fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: strongly favor bins whose post residual is near zero,
    // scaled non-linearly (quartic) so tiny residuals dominate.
    score -= 12.0 * (1.0 - pr / cap).powi(4) * (pr / cap).powi(2) * 100.0;

    // Penalize dead space that the next item cannot use (smooth coupling).
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let unusable = (nx - pr).max(0.0) / cap;
        score += 25.0 * unusable * unusable * (0.5 + progress);
        // Reward when next item fits exactly in the post residual.
        let gap = (pr - nx).max(0.0) / cap;
        score += 8.0 * gap * (1.0 - progress);
    } else {
        // End of stream: only zero-residual placements matter.
        score += 15.0 * (pr / cap);
    }

    // Last-chance bin: reward using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize mildly early, more when open bins are scarce.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
        score -= 5.0 * progress * (1.0 - pr / cap);
    }

    // Slight preference for bins with below-mean residual (consolidate).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);

    // Progressive tightening: later in stream, waste is costlier.
    score += progress * (pr / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: strong bonus as post_residual approaches 0.
    let tight = (1.0 - post / cap).powi(4);
    score -= 60.0 * tight;

    // Harmonic classes: reward post_residual landing in "useful" residue classes.
    // Small residues (<=10) are near-perfect; multiples of 10 pair well with typical sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 80.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        // Penalize awkward dead space in the 1..10 band of a fresh-ish bin.
        score += 8.0 * (10 - (pr % 10)) as f64 / 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            score -= 20.0 * (1.0 - npost as f64 / cap);
            if npost % 10 == 0 { score -= 10.0; }
        } else {
            // Next item won't fit here; penalize leaving large but unusable-for-next space.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when all
    // open bins would leave large awkward residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin scales with stream progression and open-bin count.
        score = cap * 0.75 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 60.0; // discourage skipping the last fitting bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 15.0; // fresh bin can host a follow-up pair
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (fuller bins).
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 4.0 * (mean_residual - bin_res) / cap;
    } else {
        score += 3.0 * (bin_res - mean_residual) / cap;
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1) are never
    // literally unusable, but tiny gaps are hard to fill. Penalize the "unusable
    // band" (post_residual < ~10) heavily since only small items can fill them.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 12.0; // dead-space band penalty
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly rewarded
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.6;
    } else if next_item_size > 0 {
        // lookahead can't fit here: if it could fit nowhere else, opening/keeping
        // a roomier bin matters more
        score += next_item_size as f64 * 0.35;
    }

    // Tight-fit bonus: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 8.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid fragmentation); with few bins, spreading is cheap.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin costly unless this item is large
    // and would leave a big awkward gap elsewhere. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // but if the item nearly fills a fresh bin, a new bin is fine
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 22.0;
        }
    }

    // Mean-residual coupling: if average residual is small, conserve tight bins;
    // if average residual is large, prefer bins above-average fullness.
    let rel = bin_residual as f64 - mean_residual;
    score -= rel * 0.15;

    // Stream progression: late in the stream, pack tighter (fewer wasted bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit relative to mean residual of open bins.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin will be closed by next item
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much would remain after next
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * waste;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize candidates that leave tiny unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so good fits
    // in existing bins win, but a large bonus when no existing bin fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 50.0; // fresh bin perfectly fits next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // discourage wasting a fresh bin when decent fits exist
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Late in the stream: consolidate more aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead (k=2): reward if the next item fits into the resulting residual,
    // with extra reward for an exact two-item match.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= nxt * 0.35;
        } else {
            // next item won't fit here: mild penalty for creating a residual too small to reuse
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin by default,
    // but relax the penalty late in the stream or for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 22.0 - 12.0 * progress;
        if item_size >= 60 {
            score -= 14.0;
        }
        // if no open bin can fit the item, opening a new bin is unavoidable
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual is tighter than the global mean (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // When many bins are open, encourage tighter packing to consolidate.
    if open_bins_count > 8 {
        score -= 2.5;
    }

    // Small dynamic time-horizon coupling: early on, be slightly greedy toward
    // low post-residual; later, weight lookahead more (already handled) and
    // penalize fragmentation.
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: minimize post residual, with smooth polynomial shaping.
    let mut score = r * (1.0 + 0.5 * rn * rn);

    // Non-linear coupling of residual with stream progress:
    // later in the stream, tight fills matter more.
    let tight = 1.0 - rn;
    score -= 8.0 * tight * tight * progress;

    // Penalize dead space that next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let waste = (r - next_item_size as f64).max(0.0) / cap;
        score += 12.0 * waste * waste * (1.0 + progress);
    } else {
        // last item: prefer fullest fit
        score -= 5.0 * tight;
    }

    // Reward using a bin when it's the only fitting one (avoid new bin).
    if fitting_bins_count == 1 {
        score -= 6.0 * tight;
    }

    // Smooth penalty relative to mean residual: avoid placing into
    // bins with unusually small residuals when alternatives exist.
    let dev = (mean_residual - r) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for large open-bin counts to encourage consolidation.
    score += 0.15 * open_bins_count as f64 * rn;

    // New-bin candidate: smooth discouragement early, more openness later.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are highly rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-exact fills strongly (dead space classes).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    } else {
        // Modulo-10 harmonic class penalty: leftovers in awkward classes are worse.
        let class = post_residual % 10;
        let class_penalty = match class {
            0 => -30.0,          // round leftover: reusable by many item sizes
            1..=3 => 40.0,       // awkward sliver classes
            4..=6 => 10.0,
            7..=9 => 25.0,
            _ => 0.0,
        };
        score += class_penalty as f64;

        // Fractional capacity coupling: leftover relative to capacity.
        score += 0.5 * (post / cap) * (post / cap) * cap;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic compatibility: next item pairs well (reward, more if snug).
            let snug = (post_residual - next_item_size) as f64;
            score -= 120.0 - 2.0 * snug;
            // Bonus if next item exactly fills the bin after this one.
            if next_item_size == post_residual {
                score -= 300.0;
            }
        } else {
            // Next item won't fit here: penalize proportional to overflow gap,
            // softened when the leftover is in a reusable class (multiple of 10).
            let gap = (next_item_size - post_residual) as f64;
            let soft = if post_residual % 10 == 0 { 0.5 } else { 1.0 };
            score += soft * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bins get a mild penalty so we prefer
    // existing bins, unless the current bin would leave a large dead zone.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.1 * open_bins_count as f64;
    } else {
        // Slight preference for tighter existing bins (lower residual first).
        score += 0.05 * (bin_residual as f64 - post);
    }

    // Stream progression: late in the stream, be greedier about perfect fits.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 50.0 * t * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible future item (>=1, but practically tiny gaps < ~10 are wasted)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize "awkward" gaps that can't fit typical mid-size items.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (low post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (consolidate early), encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the item is huge and would leave a big gap in any open bin,
        // a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins as open count grows.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item would not fit in post residual but fits in residual,
    // slight penalty (may want to save space).
    if next_item_size > post_residual && next_item_size <= bin_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (fill the emptier-relative bins less, keep large residuals for big items).
    if (bin_residual as f64) > mean_residual {
        score += 6.0;
    } else {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residual too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty for blocking good residual space.
        score += 5.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Early in the stream: be more willing to open new bins for large items
    // (keep flexibility); later: consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when item is large and fits poorly elsewhere.
        let flexibility_bonus = (1.0 - progress) * 20.0;
        score -= flexibility_bonus;
        if item_size > 60 {
            score -= 10.0;
        }
        // Late in stream, discourage opening new bins unless residual elsewhere is bad.
        score += progress * 30.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    } else {
        // Existing bin: late in stream, favor existing bins more strongly.
        score -= progress * 10.0;
    }

    // Small global pressure: if mean residual is high, reward using up slack.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, but with non-linear (quadratic/cubic) shaping
    let mut score = pr as f64 * (1.0 + 0.9 * x * x + 0.6 * x * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter fits matter more (dead space is permanent)
    let coupling = 1.0 + progress * (2.0 * x - 1.0) + progress * progress * (1.0 - 3.0 * x + 2.5 * x * x);
    score *= coupling.max(0.05);

    // Reward near-perfect fits smoothly (small post residual relative to item)
    let tightness = 1.0 - (pr as f64) / (item_size.max(1) as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like term)
    if next_item_size > 0 {
        let gap = (pr as f64 - next_item_size as f64).abs();
        score -= 10.0 * (-(gap * gap) / 900.0).exp();
    } else {
        // near the end, prefer filling bins completely
        score -= 8.0 * (1.0 - x) * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Deviation from mean residual: prefer bins close to mean residual usage pattern
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: residues in low classes (small dead space)
    // are more reusable by typical items (items >= 10 here), so bucket them.
    let cls = post_residual / 10; // integer division bucket
    score += match cls {
        0 => -20.0,          // 0..9 dead space, nearly unusable but tiny
        1 => -8.0,           // 10..19 usable by small items
        2 => 0.0,
        3 => 4.0,
        4 => 8.0,
        _ => 12.0,           // large residual is fine (new bin case)
    };

    // Modulo-10 resonance: residual matching common size multiples stays usable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 + (10 - slack.min(10)) as f64;
        } else {
            // next item cannot use this residual: penalize small residuals more
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin late in stream? no — early stream benefits from
        // spreading; late stream should consolidate. Penalize more as stream ends.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if many bins already open, discourage adding more unless item is huge
        score += 2.0 * open_bins_count as f64;
        if item_size > 60 {
            score -= 25.0;
        }
    } else {
        // Slight preference for tighter existing bins beyond raw post_residual
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 8.0;
    }

    // Mean residual context: if this bin is much tighter than average, reward
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste — penalize them quadratically.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0 + (post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the leftover gap could still host the lookahead item, reward that.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the gap cannot host the next item but the bin residual could have,
    // mild penalty for leaving a stranded gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost plus pressure.
        score = bin_capacity as f64
            + open_bins_count as f64 * 3.0
            + progress * 20.0
            - 5.0;
        // Opening a bin is fine if no open bin fits well (large mean residual spread).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins whose residual is close to the item
        // (tight packing), scaled by how far post_residual is from mean_residual.
        score += ((post_residual as f64) - mean_residual).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly here -> strong reward.
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64)) - gap * 0.3;
        } else {
            // Next item won't fit; penalize leftover dead space relative to gap.
            score += gap * 0.25;
        }
    }

    // Penalize large post_residual waste relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Reward tight fits (small post_residual).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual != bin_capacity) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: penalize killing space needed by the next item,
    // reward leaving exactly room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 15 {
            score -= 18.0; // perfect two-item chain
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 + 0.25 * (next_item_size - post_residual) as f64; // dead space
        }
    }

    // New-bin candidate: penalize unless current bins are crowded / fit is bad.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let mut penalty = 30.0;
        if fitting_bins_count == 0 {
            penalty -= 40.0; // nothing fits anywhere: new bin is fine
        } else if crowding < 0.25 && post_residual <= 20 {
            penalty += 15.0; // plenty of roomy bins and this item fits poorly anyway
        }
        score += penalty;
    } else {
        // Prefer filling bins with larger residual when mean residual is high.
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
        // Slight time pressure: as stream progresses, avoid opening slack.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear base: reward tight fits via polynomial decay of post_residual
    let mut score = norm_post * norm_post * (3.0 - 2.0 * norm_post) * cap;

    // Non-linear coupling with stream progress: tolerate slack early, punish late
    score += post * (0.2 + 1.5 * progress * progress);

    // Penalize creating dead space relative to mean residual (smooth cubic term)
    let dead = (post - mean_residual).abs();
    score += 0.05 * dead * dead / cap;

    // Lookahead coupling: if next item fits the post-residual, reward smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = if post > 0.0 { (nxt / post).min(1.0) } else { 0.0 };
        score -= 8.0 * fit_ratio * fit_ratio;
    }

    // Last-chance bonus: smooth quadratic reward when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.02 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residual that is too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // Harmonic reward: post_residual exactly divisible into capacity fractions
    // (perfect harmonic residual is ideal for future items).
    if post_residual > 0 {
        let mut harmonicity = 0.0;
        if post_residual % eighth == 0 { harmonicity += 2.0; }
        if post_residual % quarter == 0 { harmonicity += 2.0; }
        if post_residual % half == 0 { harmonicity += 3.0; }
        if bin_capacity % post_residual == 0 { harmonicity += 3.0; }
        score -= harmonicity * 4.0;
    }

    // Integer-division class of item size relative to capacity.
    let item_class = item_size / quarter; // 0..3
    match item_class {
        0 => score -= 5.0,   // tiny item: easy to place anywhere
        1 => score += 0.0,
        2 => score -= 2.0,   // half-class: prefer bins that keep harmonic residual
        _ => score += 3.0,   // huge item: penalize slightly, avoid wasting big bins
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next fits: reward, especially if next is in same harmonic class
            score -= 12.0;
            if next_item_size % quarter == 0 { score -= 6.0; }
        } else {
            // next won't fit here: penalize if post_residual becomes dead space
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += waste * 0.8;
            }
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current bin would leave bad residual or many bins already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Later in stream: prefer reusing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it's a fragmented bin; using it tightens the pool.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Modulo tie-break on step for harmonic diversity.
    if (step_index + post_residual as usize) % 3 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward bins whose residual can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // would strand space before next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or early in stream.
        score += 20.0 + 4.0 * open_bins_count as f64 + 30.0 * (1.0 - progress);
    } else {
        // Mild bonus for filling already-open bins.
        score -= 2.0 * open_bins_count as f64 * 0.1;
    }

    // Prefer bins tighter than the mean residual (compactness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fill: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of that future fit.
            let future_tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 40.0 + 60.0 * future_tightness;
        } else {
            // Next item will not fit here: penalize dead space relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier waste.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr > mean_residual * 1.5 {
            score += (pr - mean_residual * 1.5) * 0.8;
        } else if pr < mean_residual * 0.5 {
            score -= (mean_residual * 0.5 - pr) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild preference for compacting into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Slight bias toward bins with less residual before placement (tighter bins first).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: very small post-residuals that can't fit even the
    // smallest plausible item are wasted capacity — but if this is the last
    // fitting bin, we should actually prefer filling it tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: post_residual smaller than the next item means the
    // leftover is likely unusable anyway — good, close the bin out.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score -= 10.0 + 0.25 * post_residual as f64;
    }

    // But if the next item COULD fit in the leftover, reward keeping room for it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // Mild penalty so a decent existing fit wins; scale with how many
            // bins could fit the item (more alternatives => worse to open new).
            score += 15.0 + 5.0 * fitting_bins_count as f64;
            // Late in the stream, avoid proliferating bins with one item each.
            score += 20.0 * progress;
        }
    }

    // Prefer bins whose residual is below the mean (consolidating emptier space
    // into fewer bins), i.e. favor filling the fullest-fitting bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild penalty for leaving exactly awkward residuals (e.g. 1..=5 units)
    if post_residual >= 1 && post_residual <= 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = pr / cap;
    let tightness = 1.0 - norm_post;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * tightness * tightness);
    score -= 8.0 * norm_post * (1.0 - progress);

    // Reward tight fits via smooth quadratic term
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize crowding relative to mean residual
    score += 0.1 * (mean_residual - pr);

    // Dead-space penalty for unusable slivers
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 6.0 * (pr / cap) * (1.0 - progress);
    }

    // New-bin candidate: keep it attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score -= 15.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10, 20, 25, 50) is more reusable than an odd leftover.
    let mut harmony_bonus = 0.0;
    for d in [10u32, 20, 25, 50, 100] {
        if post_residual > 0 && post_residual % d == 0 {
            harmony_bonus += 8.0;
        }
    }
    score -= harmony_bonus;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead space: tiny post_residual (unusable for items >= 10 in the classic
    // regime, but sizes 1..100 allowed) penalized non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo-class coupling: item and post_residual sharing gcd structure
    // suggests future items of the same class can stack.
    let g = gcd(item_size.max(1), post_residual.max(1));
    if g > 10 {
        score -= (g as f64) * 0.5;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // reward this bin heavily (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        // If next item cannot fit here anyway, mild penalty for tight residuals.
        if next_item_size > post_residual && post_residual < 15 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when residuals across
    // open bins are already tight or the fit here is poor.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // Prefer keeping existing bins when they can absorb the item well.
        if post_residual < 40 {
            score += 120.0; // opening fresh bin wastes the tight residual
        }
        // As stream progresses and many bins are open, discourage new bins mildly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If mean residual is large, existing bins are roomy: penalize new bin.
        score += (mean_r / bin_capacity as f64) * 60.0;
    }

    // Integer-division threshold: penalize residuals in awkward bands
    // (11..19, 21..24, 26..49) that fit few standard classes.
    let band = post_residual / 10;
    match band {
        1 => score += 12.0,
        2 => score += 6.0,
        3 => score += 3.0,
        4 => score += 1.5,
        _ => {}
    }

    // Mild tie-break toward filling fuller bins (lower post_residual already
    // does this, but scale it by openness of the system).
    score += (post_residual as f64) * (1.0 + open_bins_count as f64 / 50.0);

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else {
        // Larger usable leftovers are mildly rewarded.
        score -= 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += pressure;
        // But allow opening if current bin would leave a tiny dead gap.
        if post_residual >= 1 && post_residual <= 10 {
            score -= 20.0;
        }
    } else {
        score -= pressure * 0.1;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0;
    }

    // Prefer bins with residual close to the mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score -= 5.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for opening new bins early in the stream when current fit is loose
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0; // usable by small items
    }

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.15 * next_fit;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting large residual.
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes open capacity.
    if bin_residual == bin_capacity {
        // Only attractive when open bins have poor fits (large mean residual mismatch)
        // or very few bins are open early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (mean_residual - item_size as f64).abs();
        score += 25.0 + 50.0 * progress - (poor_fit / 10.0).min(20.0);
        // Encourage consolidation when many bins are open.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be more aggressive about closing gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr + 3.0 * progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Penalize dead space that can never be used by the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) / cap * (1.0 + progress);
        } else {
            // reward exact-ish fit for upcoming item
            score -= (1.0 - (pr - ns) / cap) * 0.5 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 + progress;
    }

    // Slight penalty for leaving very small unusable slivers
    let sliver = norm_pr * (1.0 - norm_pr);
    score += 0.3 * (0.25 - sliver) * (1.0 + progress);

    // Mild dispersion penalty relative to mean residual
    score += 0.2 * (pr - mean_residual) / cap;

    // New-bin candidate: neutral baseline scaled by open bins
    if bin_residual == bin_capacity {
        score = 0.9 + 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Reward near-full bins strongly (dead space minimization).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 100.0;
    } else if post_residual <= 30 {
        score -= 40.0;
    }

    // Harmonic classes: residuals that are "reusable" for common item sizes
    // (multiples of 10 within 1..100 interface) are less dead than odd gaps.
    let reusable = post_residual >= 10 && post_residual <= 80;
    if reusable {
        score -= 30.0;
    } else if post_residual > 0 {
        score += 25.0; // tiny unusable slivers
    }

    // Non-linear coupling: penalize residual quadratic beyond half capacity.
    if frac > 0.5 {
        score += (frac - 0.5) * (frac - 0.5) * 120.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many bins are open (fragmentation cost).
        score += 180.0 + pressure * 2.0 + progress * 40.0;
        // But if the item fits nothing well elsewhere (large residual gaps),
        // opening a fresh bin may be better: soften penalty when mean residual low.
        if mean_residual < item_size as f64 {
            score -= 160.0;
        }
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; slight penalty for leaving large gap.
            score += 10.0;
        }
    }

    // Tightness reward relative to item size: perfect packing ratio.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 60.0;

    // Prefer fuller bins among equals (mild first-fit-decreasing flavor).
    let used = (bin_capacity.saturating_sub(bin_residual)) as f64;
    score -= used * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    // Strict dead-space avoidance: post_residual that is small but nonzero
    // (unusable gap) is heavily penalized; exact fit (0) is rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        // tiny unusable gap: worst outcome
        score += 45.0;
    } else if post_residual <= 20 {
        score += 18.0;
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones;
    // the empty-bin candidate gets penalized when bins are plentiful.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // Early in stream, new bins are cheap to open; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Deviation from mean residual: prefer bins that tighten the spread.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.4;

    // Slight bonus for filling larger residuals (consolidation).
    score -= bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (add) only the truly wasted space.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly or nearly host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // exact match is ideal; larger gaps are progressively worse
            score -= 30.0 - gap.min(40.0) * 0.5;
        } else {
            // next item won't fit here: dead-space risk scaled by leftover size
            score += (post_residual as f64) * 0.15;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // item is large relative to residual alternatives; default slightly penalized.
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if the item is huge, opening a fresh bin may be best
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (min size 1..10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Spread load when many bins fit the item.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 / (1.0 + slack);
        } else {
            score += 2.0; // next item won't fit here; slight penalty
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low,
    // prefer spreading when mean residual is high.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.05 * (mean_r - post_residual as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But allow a new bin if this item is huge and would leave awkward residue.
        if item_size > 60 && fitting_bins_count > 0 {
            // keep the penalty; consolidation preferred
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post / cap);
    score -= 24.0 * tight * tight * tight;

    // Penalize unusable dead space: residual too small for typical future items.
    let dead = (1.0 - post / cap).max(0.0);
    let unusable = ((10.0 - post).max(0.0) / 10.0).min(1.0);
    score += 30.0 * unusable * (1.0 + progress);

    // Smooth coupling with stream progress: later in stream, prefer filling existing bins more.
    score += 6.0 * (post / cap) * progress;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the mean
    // residual of open bins is small (they are nearly full) or item is huge.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let huge = item_size as f64 / cap;
        score += 18.0 * (1.0 - mean_fill) * (1.0 - huge);
        score -= 8.0 * mean_fill;
        // lookahead: if next item could share this new bin, mildly encourage opening
        if next_item_size > 0 && (next_item_size as f64) <= post - item_size as f64 {
            score -= 3.0;
        }
    }

    // Divergence from mean residual: prefer bins whose leftover deviates usefully.
    score += 2.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in some residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement.
    let fill = 1.0 - pr / cap;

    // Reward high fill non-linearly (tight packing is the core objective).
    score -= 60.0 * fill * fill;

    // Harmonic classes on post_residual: residuals that are "useful" sizes
    // (multiples of small integers / common item sizes) are less penalized.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 12.0,           // exact decade residual: highly reusable
        5 => 6.0,            // half-decade: moderately reusable
        1 | 9 => 2.0,        // near-decade: mild
        _ => -4.0,           // awkward odd residuals: dead space
    };
    score -= class_bonus;

    // Integer-division threshold: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0;
            score += slack * 0.15; // prefer exact next-fit chains
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 6.0; // harmonic divisibility bonus
            }
        } else {
            // Next item cannot follow here; mildly penalize if it could have
            // fit before placement (we destroyed a chain).
            if bin_residual >= next_item_size {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let crowd = open_bins_count as f64;
        let mean_tight = 1.0 - (mean_residual / cap);
        // Penalize opening a new bin unless open bins are mostly full.
        score += 30.0 - 25.0 * mean_tight;
        if crowd < 3.0 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Large items with no good home may justify a fresh bin.
        if item_size > 60 && mean_residual < (item_size as f64) {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins
    // get filled first, keeping loose bins flexible).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Small penalty scaling with post_residual to break exact ties toward
    // minimal leftover space.
    score += pr * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: penalize small unusable gaps heavily.
    let max_item = 100u32;
    if post_residual > 0 && post_residual < max_item {
        // Smaller gap relative to the smallest possible item => worse.
        let deadness = (max_item - post_residual) as f64;
        score += 3.0 * deadness;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 1.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize creating yet another open bin when many are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
    }

    // Mild preference for bins tighter than average (better packing).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect two-item fill: huge reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit here after placing current, penalize leftover dead space
        if post_residual < next_item_size {
            score += 0.4 * post_residual as f64;
        }
    } else {
        // Last item: prefer minimal residual
        score += 0.2 * post_residual as f64;
    }

    // Penalize creating unusable dead space relative to smallest possible item (1)
    if post_residual > 0 {
        score += 0.15 * (post_residual as f64).sqrt() * 10.0;
    }

    // Reward tight fits (low post_residual overall)
    score -= 0.3 * (bin_residual - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current open bins have poor fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more when many open bins exist with slack
        score += 15.0 + 0.05 * open_bins_count as f64 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && bin_residual - item_size >= 0 {
            // opening new bin is reasonable when item is large and next item may pair
            score -= 5.0;
        }
    }

    // Mild preference toward bins with residual below mean (filling emptier-first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Near-perfect fit bonus (dead space <= 5).
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize creating dead space smaller than the smallest plausible item
    // (unusable gap): post_residual < 10 is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // next item cannot follow here; slight penalty unless gap is tiny
            if post_residual >= 10 {
                score += 6.0;
            }
        }
    } else {
        // Last item in stream: just fill tightest, reduce weight of residual.
        score *= 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we only
    // open a new bin when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If all fits are bad (large post residual elsewhere), opening fresh
        // is fine: the quadratic term above already makes bad fits costly.
        // Encourage fresh bins early in the stream when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 10.0 * (0.2 - progress);
        }
        // If next item is large relative to capacity, a fresh bin preserves
        // flexibility for it.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual deviates from the mean residual in a
        // way that consolidates space: filling a below-mean bin tightens
        // the overall state.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild pressure to reuse existing bins when many are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants
    score += 12.0 * poly * norm_pr * (1.0 - norm_pr);

    // Penalize large dead space more than linearly as stream progresses
    score += 8.0 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits: small post residual gets subtracted
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * t);
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - slack) * (0.5 + 0.5 * t);
    } else if next_item_size > 0 {
        score += 4.0 * t;
    }

    // Slight preference for consolidating into fewer bins when many open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Mean residual deviation penalty
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: only attractive early or when fit is terrible
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t) * (1.0 - norm_pr);
        score += 14.0 * t * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo capacity fraction classes.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Penalize residuals that fall into "dead zones" (small, hard-to-fill remainders).
    if post_residual > 0 && post_residual <= eighth {
        score += 12.0;
    } else if post_residual <= quarter {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    } else {
        score -= 6.0; // large residual keeps the bin versatile
    }

    // Integer-division harmonic classes: post_residual / 10 bucket parity coupling.
    let cls = (post_residual / 10) % 4;
    match cls {
        0 => score += 3.0,          // residual 0-9: nearly full, only good if exact
        1 => score += 0.0,
        2 => score -= 1.5,
        _ => score -= 2.5,
    }

    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item can fit exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next fits: residual class pairing bonus
            let pair = ((post_residual / 10) + (next_item_size / 10)) % 3;
            score -= 5.0 + pair as f64;
        } else {
            // next item cannot use this residual: penalize more when residual is small
            score += (post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening fresh is penalized mildly; becomes viable if current open bins are fragmented.
        score = cap * 0.5 + mean_residual * 0.3 - (open_bins_count as f64) * 1.0;
        if fitting_bins_count == 0 {
            score -= cap; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Stream progression: prefer consolidating into fewer bins early, tighten later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;
    score += progress * (open_bins_count as f64) * 0.05;

    // Mean residual alignment: prefer bins close to the mean residual (balance).
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // A residual below the minimum plausible item size (1..100 stream => treat <12 as dead)
    // is nearly worthless; a residual >= 50 is still quite usable.
    if post_residual > 0 {
        if post_residual < 12 {
            score += 60.0; // dead space penalty
        } else if post_residual < 25 {
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (i.e., penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 8.0 * pressure;
        // But if no existing bin fits well, opening may be right: soften when lookahead
        // item is large and would leave this bin useless anyway.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 + 11.0 {
            score -= 12.0; // this bin would be dead after placement anyway
        }
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Early in the stream, allow more bin openings (flexibility); later, be frugal.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits perfectly in the chain -> strongly favor.
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 45.0 + 25.0 * chain_fit;
        } else {
            // Next item won't fit here: penalize proportional to wasted residual.
            let dead = post_residual as f64;
            score += 0.25 * dead;
            // If next item would fit better elsewhere, mild penalty.
            if next_item_size > bin_residual {
                score += 10.0;
            }
        }
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // relative to all residuals or no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 55.0 + 0.3 * (open_bins_count as f64);
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (open_bins_count as f64 - 1.0).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = post_residual as f64 - nx;
            if slack <= 5.0 { score -= 20.0; } // perfect chaining
            else { score += 5.0 * (slack / bin_capacity as f64); } // mild penalty for wasting space
        } else {
            let miss = (next_item_size as f64) - (post_residual as f64);
            if miss <= 10.0 { score += 15.0; } // near-miss wastes potential
        }
    }

    // Compare against mean residual: bins with much less residual than average are precious.
    let dev = mean_residual - (bin_residual as f64);
    score += 0.3 * dev;

    // New-bin candidate handling: neutral baseline, penalize opening new bins unless current fits are bad.
    if bin_residual == bin_capacity {
        let mut base = bin_capacity as f64 - 10.0 * tightness; // slightly worse than a decent fit
        // Early stream: allow opening bins freely to build a portfolio.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 { base -= 15.0; }
        // Many fitting bins: opening a new bin is rarely good.
        if fitting_bins_count > 2 { base += 20.0; }
        // Large item: new bin gives full flexibility.
        if item_size > bin_capacity / 2 { base -= 10.0; }
        score = base;
    }

    // Prefer filling bins that are already mostly full (consolidation).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Late stream: discourage opening new bins more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
