    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += poly * cap * 0.5;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (1.0 + progress) * 6.0;

    // Lookahead: penalize residual that cannot hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
