    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * (1.0 - progress);
    }

    // Penalize leaving residual near mean (wasted similar-space bins)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: mild penalty so it is chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

