        } else {
            score -= 100.0;
        }
    }

    // Open-bin pressure: mildly discourage accumulating many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below mean (tighter bins first) to keep loose bins available.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late-stream tightening: as the stream progresses, be stricter about waste.
