pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain;
    }

    // Penalize leaving a dead gap that the next item cannot use.
