    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if mean residual is very low (all bins nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit flexibility); late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
