}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, softly normalized
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 + p) - norm_pr * (1.0 - p);
    score += 40.0 * coupling;

    // Penalize waste more as stream progresses (smooth cubic in progress)
    score += pr * (0.5 + 0.5 * p * p * p);

    // Reward tight fits: small post residual relative to item size
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 20.0 * tightness * (1.0 - p);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
