        if nx <= pr {
            let nx_fit = nx / (pr + 1.0);
            score -= 15.0 * nx_fit * nx_fit;
        } else {
            // next item won't fit; mild penalty scaled by excess
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Encourage filling bins when many are open
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    // Slight pull toward mean residual to balance loads
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (0..10, 10..25, 25..50, 50..75, 75..100).
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead space penalty: super-linear cost for unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - post_f / 10.0);
    }

    // Reward tight fits (post residual in the smallest harmonic class).
    if post_residual == 0 {
        score -= 60.0; // perfect packing
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    } else if post_residual > bin_capacity / 2 {
        score -= 5.0; // large leftovers may still be usable
    }

    // Lookahead coupling: penalize if the next item cannot use this bin's
    // post residual (creates a stranded bin).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.2 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover exactly hosts the next item's class
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else if gap < 10 {
                score -= 15.0;
            }
        }
    } else {
        // Last item: strongly prefer zero-waste closure.
        score += 0.5 * post_f;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or all fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / cap_f;
        // Base cost of a fresh bin; cheap early, expensive late.
        let mut nb = 40.0 + 30.0 * progress;
        if fill_ratio > 0.5 {
            nb -= 20.0; // large items start fresh bins happily
        }
        if post_residual > 0 && post_residual < 10 {
            nb -= 25.0; // fresh bin leaves the ideal small-item class
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            nb += 10.0; // open bins collectively have room; discourage new bin
        }
        score += nb;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Harmonic modulo nudge: bins whose residual lies on common class
    // boundaries (multiples of 10) pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

