    // Reward tight fits (small post_residual) more strongly later in the stream
    let mut score = poly * (1.0 + 0.5 * progress * (norm_pr * norm_pr));

    // Penalize creating dead space below next item size (unusable gap)
    if next_item_size > 0 && (pr as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * (1.0 + 0.7 * progress) * 10.0;
    }

    // Reward lookahead compatibility: post_residual can host next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let fit_margin = 1.0 - ((pr as u32 - next_item_size) as f64) / cap;
        score -= 2.0 * fit_margin * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: baseline score slightly above good fits, decreasing with progress
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (consolidation)
    score += 0.3 * (mean_residual - pr).max(-cap) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity/10 (dead-space classes)
    let class_len = bin_capacity / 10; // 10
    let post_class = (post_residual % class_len) as f64;
    let post_div = (post_residual / class_len) as f64;

    // Reward tight fits: lower post_residual, especially when it lands in a
    // "usable" harmonic class (small residue mod class_len).
    score -= 8.0 * (1.0 - post_class / class_len as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }
    // Near-perfect fits (residual too small for min item 1..100 -> effectively dead)
    if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward leaving exactly enough room for the next item
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Post-residual unusable for next item: penalize harmonic mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating many nearly-empty parallel bins
    if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
        score += 10.0;
    }

    // New-bin candidate: prefer it only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // Early in the stream, opening bins is cheaper (build inventory)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If few bins fit the item, opening new may be right
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late stream: discourage opening extra bins
        score += 25.0 * progress;
    }

    // Mild preference for bins with less residual overall (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0) * post_div * 0.0
        + 0.02 * post_div;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for the smallest
    // plausible item are wasted capacity — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post residual too small to fit the lookahead item: likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // (penalize the empty new-bin candidate implicitly via residual, but add
    // explicit pressure against fragmentation).
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if current bins fit poorly.
        score += 25.0 + open_pressure * 1.5;
        if fitting_bins_count == 1 {
            // Even so, avoid new bin if an existing bin can take the item.
            score += 40.0;
        }
    } else {
        // Slight preference for bins already below mean residual (consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, graded penalty otherwise.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }

        // If the next item can also fit into post_residual, mildly reward leaving room.
        if post_residual >= next_item_size {
            score -= 8.0;
        }

        // Penalize creating dead space that cannot fit the next item, scaled by how dead it is.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    } else {
        // Last item: just minimize leftover waste.
        score += 20.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize deviations from mean residual: prefer balanced bins unless it's a tight fit.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.25 * (1.0 - fill_ratio);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.5 };
        score = 100.0 - desperation * 30.0
            + (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item can fit exactly into the post-residual,
    // this placement is highly desirable (perfect pair).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves even more slack: mild reward, scaled by
        // how much of the remaining space the next item would consume.
        let pair_eff = (next_item_size as f64) / (post_residual as f64);
        score -= 10.0 * pair_eff;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual becomes dead space relative to the upcoming item:
        // penalize proportionally to wasted capacity.
        let waste = (post_residual as f64) / cap;
        score += 12.0 * waste * waste;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (post_residual as f64);
    }

    // Penalize opening new bins when plenty of open bins have room.
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (fitting_bins_count as f64);
        let stream_pos = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bins are more acceptable early (exploration) and when
        // fitting options are scarce; costly late with many alternatives.
        score += 8.0 * fit_pressure + 10.0 * (1.0 - stream_pos);
        // Discard the base post_residual advantage of an empty bin
        // (it equals capacity, huge); neutralize it.
        score -= 0.5 * (post_residual as f64 - cap).abs() * 0.0;
        score -= (post_residual as f64) * 0.5;
    }

    // Global slack management: when mean residual across open bins is high,
    // prefer filling existing bins rather than fragmenting space.
    let mean_frac = mean_residual / cap;
    if bin_residual != bin_capacity {
        score -= 6.0 * mean_frac;
    } else {
        score += 6.0 * mean_frac;
    }

    // Slight preference for bins whose residual is close to the mean
    // (balanced depletion keeps future options flexible).
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.05 * dev;

    // Mild decay of lookahead influence late in the stream (less to gain).
    let horizon = if total_items > 0 { 1.0 - step_index as f64 / total_items as f64 } else { 1.0 };
    score *= 0.8 + 0.2 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: post_residual weighted by a smooth progress-dependent factor.
    // Early on, waste matters less; late in the stream, minimize residual aggressively.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * post * post / cap;

    // Reward tight fits (small post_residual relative to capacity) with a smooth saturating term.
    let tightness = 1.0 - (post / cap);
    score -= 20.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly (smooth bell).
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        let norm = diff / cap;
        score -= 15.0 * (-100.0 * norm * norm).exp();
    }

    // Penalize bins whose residual deviates far from the mean residual (keeps bin portfolio balanced).
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild baseline penalty so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
        // Prefer a fresh bin when mean residual of open bins is very small (all bins nearly full).
        score -= (mean_residual / cap).max(0.0) * 20.0;
    }

    // Slight preference for fewer open bins as stream progresses (consolidation pressure).
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 100.0; // near-perfect: dead space <= min item size
    } else {
        // Harmonic class penalty: dead space is only "usable" if a future item can fill it
        // Class bins by post_residual modulo small divisors (harmonic classes)
        let pr = post_residual;
        let usable = (pr >= 1 && pr <= 100);
        let harmonic_bonus = if pr % 10 == 0 {
            40.0 // residue divisible by 10: likely matchable by 10-multiples
        } else if pr % 5 == 0 {
            20.0
        } else if pr % 2 == 0 {
            8.0
        } else {
            0.0
        };
        if usable {
            score -= harmonic_bonus;
        }
        // Penalize dead space in awkward band (e.g. 11..19 rarely fillable)
        if pr >= 11 && pr <= 19 {
            score += 30.0;
        }
    }

    // Fractional capacity coupling: reward filling large fraction of bin
    let fill_frac = item_size as f64 / cap;
    score -= 50.0 * fill_frac * fill_frac;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline so it's chosen
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if item is large relative to capacity, opening fresh is fine
        if item_size as f64 / cap > 0.8 {
            score -= 40.0;
        }
    }

    // Progress coupling: late in stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    // Prefer bins with below-mean residual (concentrate packing)
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Many open bins: encourage closing them out (prefer fuller bins)
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual is the base cost.
    // Penalize small unusable gaps (< 10, since item sizes are >= 1 but
    // typical items are larger; a residual below 10 is essentially dead space).
    if post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Soft penalty for small gaps that only very small items could use
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 * (1.0 - tightness.min(1.0));
    }

    // Open bins pressure: penalize placements that leave large residuals
    // when many bins are open (encourage consolidation).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here; penalize leaving a gap that blocks it
        score += 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all poor fits (mean residual small or fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 {
            (post_residual as f64 / mean_residual).min(3.0)
        } else {
            3.0
        };
        score += 20.0 + 10.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
    }

    // Stream progression: later in the stream, be more conservative about
    // leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // exact chain match: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover space; penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Relative to mean residual: prefer bins tighter than the mean
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * (bin_capacity - post_residual) as f64;
    }

    // Late in the stream, consolidate into open bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 50.0 * progress;
    } else {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits nicely in the leftover: reward.
            score -= 0.25 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But early in the stream, opening new bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If the next item is large and this bin is fresh, opening a new bin reserves space.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Penalize leaving dead space that nothing (min size ~1) can ever reuse usefully.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild preference for filling bins with larger residuals when residuals are heterogeneous.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let fit = post_residual as f64 / cap;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    score -= 45.0 * (1.0 - fit) * (1.0 - fit) * (1.0 + t);

    // Penalize dead space that cannot hold the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post_residual as f64 - nxt;
        if gap > 0.0 {
            let wasted = gap / cap;
            score += 25.0 * wasted * wasted * (1.0 + 2.0 * t);
        } else {
            // Bonus when the next item exactly fills this bin afterwards.
            score -= 30.0 * (-gap / cap) * (1.0 + t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * t;
    }

    // New-bin candidate: penalize opening a bin unless residuals of open bins are low.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 35.0 * (1.0 - pressure).max(0.0) * (1.0 + 0.5 * t);
        // Allow new bin late in the stream when many bins are already open.
        score -= 10.0 * t * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    // Mild preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Smooth quadratic coupling of post_residual with stream progress.
    score += 12.0 * fit * fit * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) rewarded heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize residuals in "dead zones": too small for typical items (1..100).
        // Class A: residual < 10 -> nearly unusable dead space.
        if post_residual < 10 {
            score += 25.0;
        }
        // Class B: residual in 10..20 usable only by tiny items.
        if post_residual >= 10 && post_residual < 20 {
            score += 8.0;
        }
        // Modular harmonic classes on post_residual modulo 10: residuals that are
        // multiples of 10 align with common item sizes -> slight reward.
        let m = post_residual % 10;
        if m == 0 {
            score -= 3.0;
        } else if m >= 7 {
            score += 2.0;
        }
    }

    // Next-item lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill_ratio;
        } else {
            // Next item cannot fit here: leftover likely dead -> penalize.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for tighter bins among many candidates (already via post_residual).
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when this bin would leave a large, awkward residual
    // and there are other bins that fit.
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: neutral-ish, high residual.
        score = bin_capacity as f64 * 0.5;
        // If current bin choice is poor (big residual left), new bin is competitive.
        if post_residual > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins already: discourage spreading.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild tie-break: prefer bins with below-mean residual (tighter packing).
    score += 0.5 * (mean_residual - bin_residual as f64).signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
        // The smaller the dead gap relative to the smallest plausible item, the worse.
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Gaps that are "almost full" but still usable are mildly good.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 5.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open; discourage
    // opening new bins unless the fit into existing bins is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + open_bins_count as f64 * 0.5;
        // If placing in an existing bin would create dead space, opening a new
        // bin becomes relatively more attractive.
        if post_residual >= 10 {
            score -= 6.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
            // next item would create dead space here — slight penalty
            score += 4.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && !is_new_bin {
        // leftover too small for the next item: mild dead-space risk
        score += (post_residual as f64) * 0.1;
    }

    // Stream progression: early on, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — using it up is good (it would be wasted anyway).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- 2-step lookahead: reward bins whose post-residual exactly matches next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // smooth exact-match reward: strongest when post_residual == next_item_size
        score -= 7.0 * (1.0 - diff / cap).max(0.0);
        // penalize dead space that is *just* too small for the next item (unusable sliver)
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0 * (nxt - post) / nxt;
        }
        // small residual that cannot fit typical future items is dead space
        if post_residual > 0 && post_residual < 10.0 {
            score += 5.0;
        }
    }

    // --- perfect / near-perfect fit rewards ---
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // --- last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // --- new-bin candidate: penalize, but less when item is large (efficient fill) ---
    if bin_residual == bin_capacity {
        score += 12.0 - 0.08 * item_size as f64;
        // if no other bin fits, opening is forced anyway; soften penalty
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // --- compare against mean residual: prefer bins that are already more filled ---
    score += 0.06 * (post - mean_residual);

    // --- early stream: be slightly greedier about tight fits since many items remain ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score -= (1.0 - progress) * 0.03 * (cap - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: strongly favor tight fits.
    let tight = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tight * tight;

    // Penalize large dead space, especially unusable slivers (post_residual < 10).
    if post_residual < 10 {
        score -= 15.0; // perfect fill: dead space is bounded anyway
    } else {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 8.0; // creates a bin that likely can't serve the next item
        }
        // Avoid leaving exactly a sliver that neither fits next item nor is useful
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 10.0;
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.05 * crowd * (1.0 - progress);

    // Mean residual coupling: if this bin is far below mean residual, it's a "junk" bin;
    // filling junk bins is cheap, so reward that.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.10 * dev.min(50.0);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (bin_residual == bin_capacity). Make it moderately expensive so real bins win,
    // but cheaper late in the stream when fragmentation dominates.
    if bin_residual == bin_capacity {
        let new_bin_cost = 60.0 - 25.0 * progress - 0.15 * open_bins_count as f64;
        score = new_bin_cost + item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with non-linear sharpening.
    let mut score = x * x * (3.0 - 2.0 * x) * 60.0 + 0.35 * pr;

    // Smooth polynomial coupling with stream progress: later in stream,
    // value tight fits more strongly (penalize wasted space progressively).
    score += 40.0 * progress * x * x * (1.0 - x);

    // Reward filling bins nearly full, more so as stream progresses.
    let fill = 1.0 - x;
    score -= 25.0 * fill * fill * (0.5 + 0.5 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let slack = (pr as f64 - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (nxt - pr as f64) / cap;
            score += 12.0 * gap * gap;
        }
    }

    // Penalize divergence from mean residual to avoid creating outlier dead space.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" integer-division bands (>= 50 half-bin, >= 25 quarter-bin).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual >= 50 {
        score -= 12.0; // half-bin class still useful
    } else if post_residual >= 25 {
        score -= 3.0;
    } else if post_residual <= 10 {
        score += 8.0; // dead-space band
    } else {
        score += 4.0; // awkward middle band (11..24)
    }

    // Harmonic coupling with lookahead: if the next item fits the post residual
    // exactly or within a tight class, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 15.0;
            } else {
                score -= slack as f64 * 0.2;
            }
        } else {
            // next item cannot follow into this bin: penalize by leftover gap class
            let gap = next_item_size - post_residual;
            score += (gap / 10).min(4) as f64 * 3.0;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight {
            score -= 25.0 + 15.0 * pressure;
        } else {
            score += 18.0; // discourage wasting fresh bins when fits exist
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty proportional to crowding of open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size is 1, but tiny gaps waste capacity); penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // dead space guaranteed for next item
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    if bin_residual == bin_capacity {
        // New bin candidate: penalize proportional to open bins count.
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (high mean residual fragmentation),
        // new bin becomes more attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 4.0;
        // Last item: no need for a new bin.
        if next_item_size == 0 {
            score += 100.0;
        }
    } else {
        // Placing into existing bin reduces pressure slightly with progress.
        score -= 1.5 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Fragmentation pressure: prefer bins whose residual is below mean
    // (consolidate fullness into already-full bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for wasted space, scaled by how unusable it is.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Two-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain fit is heavily rewarded.
        if slack < 1.0 {
            score -= 40.0;
        } else {
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Relative-to-mean coupling: bins below mean residual are "emptier", prefer filling them
    // when they still fit well; penalize dumping into already-tight bins.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate aggressively into fewest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / 100.0;

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., current item would leave a large dead zone everywhere else).
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_residual - item_size) as f64;
        score += 30.0; // default cost of opening a new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin chains nicely with next item
        }
        if waste_if_forced < 20.0 {
            score -= 20.0; // item nearly fills a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Bonus if post-residual plus next item nearly fills the bin.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 12.0;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild penalty spread across many fitting bins to encourage tight ones.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit); late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let openness = 20.0 * (1.0 - progress);
        // Opening a bin is fine if current bins have poor fit potential.
        let poor_fit = (post_residual as f64) > (bin_capacity as f64) - (item_size as f64) - 5.0;
        if poor_fit { score -= openness; } else { score += openness + 10.0; }
    }

    // Global state: if mean residual is high, prefer consolidating into
    // already-loose bins; if low, avoid fragmenting tight bins.
    if (mean_residual - post_residual as f64) > 20.0 {
        score -= 5.0;
    }
    if open_bins_count > 10 && new_bin {
        score += 15.0 * progress;
    }

    // Small nudge toward bins with residual close to item size (perfect fill).
    let exact_gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 10.0 / (1.0 + exact_gap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, softly damped as stream progresses
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear penalty for awkward dead space (mid-size residuals are least useful)
    let bump = norm_pr * (1.0 - norm_pr);
    score += 30.0 * bump * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly over time
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 25.0 * progress);

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bonus: only fitting bin => strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for larger residuals (keep small holes for small items)
    score -= 0.05 * bin_residual as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 8.0 + 2.0 * progress * open_bins_count as f64 - crowd.min(6.0);
    }

    // Mean residual divergence: prefer bins near the mean to keep residuals uniform
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "large slack" classes are penalized slightly (wasted space),
    // bins with small-but-usable residual are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Integer-division thresholds on post_residual (harmonic classes mod 10)
    let class = post_residual % 10;
    match class {
        0 => score -= 6.0,          // perfectly round residual: reusable
        1 | 2 => score -= 2.5,
        3 | 4 | 5 | 6 | 7 => score += 1.5, // awkward dead space zone
        8 | 9 => score += 3.0,
        _ => {}
    }

    // Reward tight fits: post_residual small relative to capacity
    if frac < 0.1 {
        score -= 8.0;
    } else if frac < 0.2 {
        score -= 4.0;
    } else if frac > 0.7 {
        score += 4.0; // leaving a huge slack is bad unless new-bin candidate
    }

    // Lookahead coupling: if next item can exactly fill the remaining space,
    // strongly favor this bin (modular match on post_residual vs next size).
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post_residual {
            score -= 12.0;
        } else if post_residual >= nxt && (post_residual - nxt) < 5 {
            score -= 7.0; // next item nearly fills leftover
        } else if post_residual >= nxt {
            score -= 2.0;
        } else {
            score += 3.0; // leftover too small for lookahead item: dead space
        }
        // Harmonic divisibility: residual divisible by next item size
        if nxt > 0 && post_residual % nxt == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (1.0 - mean_residual / cap);
        if fitting_bins_count == 0 || mean_residual < item_size as f64 {
            score -= 5.0; // open a new bin when open bins are crowded
        } else if pressure > 3.0 {
            score -= 1.0;
        } else {
            score += 6.0; // prefer filling existing bins early on
        }
    }

    // Mean residual alignment: prefer bins close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Stream progression: late in the stream, be more conservative (favor tight fits)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.35 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins far from average (extremes consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 10.0; // next item can't use this gap
    }

    // New-bin candidate: make it moderately attractive only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 - 0.2 * open_bins_count as f64;
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            score -= 25.0; // big item alone in fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
        } else {
            // next item will NOT fit here: penalize proportionally to the shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.8;
        }
    }

    // Penalize residual far below mean (creating unusable dead space relative to average).
    score += (mean_residual - post_residual as f64).abs() * 0.15;
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the item
    // is large or no good fit exists; otherwise discourage spreading load.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 || item_size >= bin_capacity / 2 {
            score -= 60.0;
        } else {
            score += 80.0;
        }
    }

    // Slight preference to fill earlier-opened bins as the stream progresses.
    if open_bins_count > 0 {
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too — chaining is good
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // next item fits current residual but not post residual — mild penalty
            score += 6.0;
        }
        // exact pairing bonus
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, adjusted by state
        let mut new_bin_cost = 25.0;
        if fitting_bins_count > 0 {
            new_bin_cost += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // early in stream, more open bins is fine; late, prefer consolidation
        let t = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost *= 0.5 + t;
        // if mean residual is high, existing bins likely absorb future items
        new_bin_cost += mean_residual * 0.15;
        score += new_bin_cost;
    } else {
        // slight preference for bins with residual above the mean (keep small-residual bins for small items)
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: as stream progresses, be more conservative with new bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 5.0;

    // Dead space penalty: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;
    // reward tight fits, stronger late in the stream
    score -= 30.0 * (1.0 - norm_pr) * (0.5 + progress);
    // penalize dead space relative to mean residual
    score += 5.0 * (pr - mean_residual) / cap;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: reward leaving space that fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }
    // mild penalty for bin proliferation
    score += 0.5 * open_bins_count as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize residual left behind (waste), scaled slightly sublinearly.
    let mut score = post * (1.0 + 0.01 * (post / cap));

    // Harmonic class of post_residual: residues divisible by common size
    // classes (5, 10, 20) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Perfect-fill classes: residual that matches typical small item sizes
        if pr == 0 {
            score -= 25.0; // exact fit, ideal
        } else if pr < 10 {
            score += 12.0; // dead space below minimum item size
        }
    } else {
        score -= 25.0;
    }

    // Integer-division threshold: bucket post_residual into capacity fractions.
    let frac = post / cap;
    if frac > 0.5 {
        score -= 4.0; // still roomy, flexible
    } else if frac < 0.1 {
        score += 5.0; // nearly full, low value slot
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0 + 0.05 * nxt;
            // harmonic match: next item exactly fills post residual class
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            score += 0.02 * (nxt - post as u32 as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits, must open new bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - (post / cap).min(1.0));

    // Stream progression: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space): residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (perfect or near-perfect fills)
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Bonus scaled by how well the item fills the bin
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill_ratio;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // Last chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (already tighter)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening new bins unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (quadratic in dead space).
    let dead = post_residual as f64;
    score += 0.08 * dead * dead / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly/well
    // into the post_residual of this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward for next item fitting: bigger reward for tighter follow-up fit.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                // Perfect 2-item packing: huge reward.
                score -= 40.0;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by
            // how much post_residual falls short of next_item_size.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss.min(50.0);
        }
    }

    // Relative-to-mean-residual term: prefer bins whose post_residual stays
    // near the mean (balanced packing), penalize outliers.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Discourage opening new bins when good open bins exist and stream is young.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late in the stream when
        // fragmentation is high anyway.
        score += 45.0 - 20.0 * progress;
        // If many bins are open, slightly discourage adding more.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer filling fuller bins (small residual before placement).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize post_residual that is small but unusable for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }
    // Reward residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Penalize when many bins fit but this one is a mediocre fit
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(10.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless item is large or
    // existing bins would leave very poor residuals.
    if bin_residual == bin_capacity {
        let waste_penalty = (0.0f64).max(mean_residual - item_size as f64 - 5.0);
        score += 35.0 - 0.3 * item_size as f64 - 0.5 * waste_penalty.min(50.0);
        // Early in the stream, opening new bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for leaving residual far from mean (fragmentation avoidance)
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Slight preference to fill bins with high residual relative to capacity
    score += 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Quadratic waste penalty: dead space grows quadratically worse.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Smooth non-linear coupling of waste with stream progress:
    // early on, waste is cheap; late in the stream, waste is heavily penalized.
    let urgency = progress * progress;
    score += 1.8 * urgency * (pr / cap) * cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (pr / cap);
    score -= 0.9 * tightness * tightness * (item_size as f64);

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 25.0 * (1.0 + urgency);
        } else if nxt <= pr {
            // next item fits: residual is reusable, mild reward
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item cannot use the residual: penalize proportionally
            score += 3.0 * (1.0 - pr / nxt) * (1.0 + urgency);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.25 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates from the mean (targeted packing).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when the item is large
    // relative to any residual or no good fit exists; otherwise discourage.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.5 * cap;
        let poor_alternatives = fitting_bins_count == 0
            || (pr - mean_residual).abs() > 0.4 * cap;
        if big_item || poor_alternatives {
            score -= 8.0 + 10.0 * urgency;
        } else {
            score += 12.0 + 20.0 * urgency;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 classes.
    let r = post_residual;
    let class = r % 10;
    // Residuals that are "harmonic" (multiples of 10 / 5) are more reusable.
    let harmonic_bonus = match class {
        0 => 12.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division dead-space threshold: tiny residuals are wasted.
    if r < 10 {
        score += 20.0 + (10 - r) as f64 * 2.0;
    } else if r <= 20 {
        score += 4.0;
    }

    // Capacity fraction coupling: tight fits (post_residual small relative to capacity) rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * 15.0;

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // prefer leaving exactly enough or harmonic slack for next item
            score -= 8.0;
            if slack % 10 == 0 || slack < 5 {
                score -= 4.0;
            }
        } else {
            score += 6.0;
            // if next item could fit a fresh bin better, mild penalty
            if next_item_size > post_residual && bin_residual - item_size < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += open_bins_count as f64 * 1.5 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins near mean residual (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual < 10 && next_item_size > post_residual);
        if bad_fit {
            score -= 18.0;
        } else {
            score += 30.0 + open_bins_count as f64 * -1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Medium dead space (10..20) mildly penalized
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }
    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit into post_residual, dead space is truly wasted
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if this bin is far below mean residual, mildly discourage
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: baseline cost of opening a bin, decreasing with stream progress
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64
            + 55.0 - 30.0 * progress
            + (open_bins_count as f64) * 2.0;
        // Opening a bin is acceptable if it enables a perfect fit for the next item
        if next_item_size == item_size && item_size <= 50 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: next item exactly fills this bin -> strong reward
            score -= 60.0 + 20.0 * progress;
        } else if post_residual > next_item_size {
            // Next item still fits after placement -> mild reward, tighter is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 - gap.min(40.0) as f64 * 0.2;
        } else {
            // Dead space: next item cannot use the remainder -> penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
    } else {
        // Last item: only tightness matters
        score -= 5.0;
    }

    // ---- Relative-to-mean-residual coupling ----
    // Favor bins whose residual deviates favorably: placing into a bin with
    // residual well above mean absorbs surplus space efficiently.
    let resid = bin_residual as f64;
    if resid > mean_residual + 1.0 {
        score -= (resid - mean_residual).min(30.0) * 0.3;
    } else if resid < mean_residual - 1.0 {
        // Bins below mean residual are already tight; slight penalty to preserve them
        score += (mean_residual - resid).min(30.0) * 0.15;
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin unnecessarily
        score -= 12.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline should be moderately attractive.
        // Prefer it only when current item leaves a very large unusable remainder
        // in existing bins or when open bins are nearly full on average.
        let tight_open_bins = mean_residual < item_size as f64 * 0.6;
        if tight_open_bins && open_bins_count > 0 {
            score -= 10.0; // allow opening when open bins are cramped
        } else {
            score += 25.0; // discourage spreading when existing bins suffice
        }
        // Early in the stream, opening bins is cheap; late, consolidate
        score += 20.0 * (1.0 - progress);
    }

    // ---- Tightness bonus: small post_residual is always good ----
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead (k=2): if the next item can still fit in the post residual,
    // this placement chains nicely -> reward. Otherwise the leftover is dead
    // space relative to the known future -> penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // leftover remains usable by the immediate future item
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 6.0 + 0.05 * chain_fit;
        } else {
            // leftover cannot host the next item: dead space for the lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    } else {
        // last item of the stream: minimize residual aggressively
        score += 0.5 * waste;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible, handled by waste).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening yet another; few open bins -> new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 * (0.5 + progress);
    score += 0.02 * crowding;

    // Global residual state: if mean residual across open bins is high,
    // we have slack everywhere -> tolerate looser fits; if low, be picky.
    score -= 0.03 * mean_residual;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: moderate, grows with progress
        // (late in the stream, consolidating matters more) and with the
        // number of already open bins.
        let mut open_cost = 20.0 + 15.0 * progress + 1.5 * open_bins_count as f64;
        // If the item is large, a fresh bin guarantees a perfect fit later;
        // if the item is tiny, opening a bin for it is wasteful.
        open_cost -= 0.05 * item_size as f64;
        // If no existing bin fits well (post_residual would be tiny), opening
        // a new bin becomes attractive: the new-bin call has post_residual =
        // capacity - item_size which is naturally large, so the waste term
        // already hurts it; compensate when the best alternative is bad.
        if fitting_bins_count == 0 {
            open_cost -= 25.0;
        } else if fitting_bins_count == 1 {
            // an existing bin fits and is the only one: keep using it
            open_cost += 10.0;
        }
        score += open_cost;
    } else {
        // Existing bin: reward near-perfect fits explicitly.
        if post_residual <= 5 {
            score -= 8.0;
        } else if post_residual <= 15 {
            score -= 3.0;
        }
        // Penalize leaving a residual that is in the "awkward zone" —
        // too small for typical mid-size items but too large to be dead.
        if post_residual > 15 && post_residual < 30 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 8.0
                 - pr_norm * progress * 6.0
                 + (1.0 - pr_norm) * (1.0 - pr_norm) * progress * 4.0;
    score += coupling;

    // Reward tight fits smoothly
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * 12.0;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual).abs() / cap;
    score += dead * dead * 5.0;

    // Last-chance bin bonus (smooth sigmoid-like gate)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can hold next item (smooth match term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - (pr - nxt).abs() / cap;
        if match_term > 0.0 {
            score -= match_term * match_term * 10.0;
        } else {
            score += 6.0;
        }
    }

    // Mild penalty for many open bins early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: smaller post_residual is better (already encoded by starting score).

    // Dead-space penalty: residual below the minimum item size (10) is unusable.
    if post_residual < 10 {
        score += 12.0;
    }

    // Harmonic classes: residue modulo 10 of post_residual.
    // Residuals in "nice" classes (multiples of 10) tend to pair with future items.
    let pr = post_residual;
    let class = pr % 10;
    score -= match class {
        0 => 6.0,                       // perfectly harmonic residual
        5 => 3.0,                       // half-class still quite usable
        1 | 3 | 7 | 9 => 2.0,           // awkward odd classes
        _ => 0.0,                       // 2,4,6,8 neutral
    };

    // Integer-division thresholds: how many minimum items still fit.
    let min_items_fit = pr / 10;
    score -= (min_items_fit.min(5)) as f64 * 2.5;

    // Lookahead: reward if the next item fits exactly or snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;              // perfect harmonic pairing with lookahead
        } else if next_item_size <= pr {
            score -= 4.0 + (pr - next_item_size) as f64 / 20.0;
        } else {
            // next item cannot use this residual at all: mild penalty proportional to waste
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (fragmentation avoidance).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Large items justify a fresh bin; small items should pack into open bins.
        let large_item_bonus = if item_size > 50 { 8.0 } else { 0.0 };
        score += 30.0 - large_item_bonus
                 - fragmentation * 20.0
                 - (open_bins_count as f64).min(10.0) * 0.5
                 - progress * 3.0;
        // Exact-fill temptation: item filling a fresh bin perfectly.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild tie-break: prefer bins that are already partially filled (denser packing).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1, but practically small gaps < 12 are waste) get a heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight relative fit (small post_residual as fraction of residual).
    if bin_residual > 0 {
        score -= (bin_capacity as f64 / bin_residual as f64) * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it attractive only when open bins would leave
    // large dead space or the next item would benefit from fresh capacity.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if fitting_bins_count > 0 {
            // how much waste would the best open-bin placement create? approximate via mean residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        let next_item_benefit = if next_item_size > 0 && next_item_size >= item_size {
            15.0
        } else {
            0.0
        };
        score = 30.0 + dead_space_penalty * 0.5 + next_item_benefit - (post_residual as f64);
        // As stream progresses, prefer consolidating into open bins.
        if total_items > 0 {
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the gap: mild penalty proportional to gap size.
        score += post_residual as f64 * 0.3;
    }

    // Mild penalty if this bin's residual deviates far above mean residual
    // (keep bins balanced so fits stay likely).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly / well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64); // good follow-up
        } else {
            // next item won't fit here: penalize wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose leftover stays near/below the mean (balanced waste)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.6 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small dead space that is hard to reuse later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin offers a good fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // mild penalty so open bins with decent fits win; large post_residual of a fresh
        // bin (capacity - item) is already naturally large
        score += 10.0 + 0.2 * open_bins_count as f64;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for closing out nearly-full bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 5 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (<=10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting pairing chance.
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 6.0 * open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins whose residual is close to mean residual
    // (keeps pool homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin unless it's a great fit
    // (item small relative to capacity) or stream is early and no bins exist.
    if bin_residual == bin_capacity {
        let early = (step_index as f64 / (total_items.max(1) as f64)) < 0.1;
        if open_bins_count == 0 || early {
            score -= 5.0;
        } else {
            score += 20.0 + 0.3 * item_size as f64;
            // Allow opening when current bins are very fragmented.
            if mean_residual < 0.25 * bin_capacity as f64 && fitting_bins_count == 0 {
                score -= 30.0;
            }
        }
    }

    // Mild time-horizon scaling: later in stream, value conservation of space more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear waste penalty: quadratic coupling of post_residual with progress.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) more aggressively as stream advances.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // Lookahead coupling: penalize if post_residual is slightly larger than next item
    // (near-miss dead space), reward if next item fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score += 30.0 * slack * (1.0 - slack);
            if post == nxt {
                score -= 35.0;
            }
        } else {
            // post_residual too small for next item: mild penalty scaled by progress
            score += 8.0 * (1.0 - post / nxt) * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening new bins early / when many bins open;
    // encourage it late if mean residual is fragmented.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild tie-break toward bins with residual near mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let q = post_residual / 10; // classes 0..=9 (residual 0..100)
    // Dead-space penalty: tiny residuals (<10) are nearly useless -> big reward for them.
    match q {
        0 => score -= 60.0,                       // perfect/near-perfect fit
        1 => score -= 25.0,                       // leaves a 10..19 sliver
        2 => score -= 10.0,
        3 => score -= 2.0,
        4 => score -= 0.0,
        5 => score += 5.0,                        // half-full: mediocre
        6 => score += 8.0,
        7 => score += 12.0,
        8 => score += 18.0,
        _ => score += 25.0,                       // nearly empty bin used wastefully
    }

    // Exact fill is always ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            // Harmonic class of the leftover after the hypothetical next placement.
            let q2 = (post_residual - next_item_size) / 10;
            score -= (9 - q2 as i32) as f64 * 2.0;
        } else {
            // Next item cannot use this bin's leftover anyway; slight penalty if
            // we leave a residual in an awkward class that nothing can pair with.
            if post_residual > 0 && post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or open-bin residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Large items are better placed fresh (avoid fragmenting existing bins).
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 45.0 * (frac - 0.5) * 2.0;
        }
        // If many bins are open but few fit, a new bin may be preferable anyway.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Prefer already-open bins slightly to consolidate.
        score -= 3.0;
        // Favor bins whose residual is close to the mean residual (keep residuals uniform).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Mild consolidation pressure: fewer open bins -> prefer reusing them.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linearly).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver under the minimum item size
        } else if post_residual <= 20 {
            score += 35.0; // very likely dead space
        } else if post_residual < item_size {
            score += 12.0; // moderately risky gap
        }
    } else {
        score -= 40.0; // perfect fill, strongly favored
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // extra bonus for exact lookahead fit
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Tight-fit reward: item occupying most of the residual is a great fit.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    } else if fill_ratio < 0.3 {
        score += 6.0; // wasteful placement into a large residual
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is excellent; encourages consolidation when bins are few.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when current fit is poor
    // (large dead space) or no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        let crowded = open_bins_count == 0 || mean_residual < (item_size as f64) * 0.5;
        if poor_fit || crowded {
            score -= 20.0; // opening a new bin is preferable
        } else {
            score += 30.0; // prefer existing bins with decent fits
        }
    }

    // Slight drift correction toward mean residual balance late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space pressure: penalize residual quadratically (wasted space).
    score += 0.02 * (post_residual as f64).powi(2) / 100.0;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            // Perfect chain: this placement enables a perfect second fit.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward closeness of match.
            score -= 30.0 * (1.0 - (post - nxt).abs() / 100.0);
        } else {
            // Next item does not fit here: mild penalty scaled by overflow size.
            score += 0.3 * (nxt - post);
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical";
    // placing into a bin far above mean residual is wasteful.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residual would be huge (bad fits elsewhere)
    // or no bins fit. A fresh bin starts with residual == capacity.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many bins already fit the item.
        score += 40.0 + 8.0 * fitting_bins_count as f64;
        // But if lookahead item is large and would need a fresh bin anyway,
        // opening one is less costly.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; prefer tight packing into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize large dead space that can't fit the average future item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score -= 8.0; // below-average leftover: bin becomes well-utilized
    }
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - progress);
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good fits exist, more so early on.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 + 10.0 * (1.0 - progress) };
        score += pressure + open_bins_count as f64 * 0.5;
        // If item is large relative to capacity, opening fresh bin is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
        // If many open bins have big residuals, prefer reusing them.
        if (mean_residual - bin_capacity as f64).abs() > 1.0 && mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (low post_residual), with non-linear amplification.
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, demand tight packing.
    score += 25.0 * (pr / cap).powi(2) * (0.5 + 0.5 * progress);

    // Penalize new bins, but the penalty decays smoothly with progress.
    if is_new_bin {
        score += 40.0 * (1.0 - 0.6 * progress);
    } else {
        // Reward using existing bins, stronger when few alternatives exist.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Reward bins whose residual stays compatible with the lookahead item.
        if next_item_size > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score += 0.15 * gap * (1.0 - progress);
        }
        // Slight pull toward the mean residual to keep bins balanced.
        score += 0.05 * (pr - mean_residual).abs();
    }

    // Mild entropy term: very full bins are precious, use them.
    score -= 8.0 * (1.0 - pr / cap) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit baseline already in `score`; refine with harmonic class logic.

    // Perfect fit bonus: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the smallest plausible item are wasted.
    // Harmonic classes: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        // Tiny sliver: nearly dead space, penalize heavily.
        score += 40.0 * (0.10 - frac) * 10.0;
    } else if frac < 0.25 {
        // Quarter-class residual: only usable by small items; moderate penalty.
        score += 8.0 * (0.25 - frac);
    }

    // Harmonic class match: reward when post_residual is a "nice" class
    // (integer division thresholds: 100/2, /3, /4).
    if post_residual == bin_capacity / 2
        || post_residual == bin_capacity / 3
        || post_residual == bin_capacity / 4 {
        score -= 15.0;
    }

    // Lookahead: reward when the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0; // chain of perfect fits
            } else {
                score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's remainder: penalize leftover.
            score += 12.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty-bin fallback costly unless
    // item is large relative to residual of existing bins (i.e., poor fits everywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 1.05;
        // If item is huge, opening fresh may be wise: discount.
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.5 {
            score -= 25.0 * (item_frac - 0.5) * 2.0;
        }
        // If many bins are open but none fit well (fitting count low), discount new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, prefer consolidating: penalize new bins slightly more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure to fill fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.05;

    // Tie-break toward bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are effectively wasted capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += 40.0 + 30.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Tight fits are strongly rewarded (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity.max(1) as f64;
    score -= 25.0 * tightness * (1.0 - (post_residual as f64 / bin_capacity.max(1) as f64));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than spawning more; when few are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin count is high, reward slightly
        // when mean residual across open bins is large (they are all poor fits).
        score += 15.0 + 8.0 * pressure;
        score -= 0.5 * mean_residual.min(50.0);
        // Late in the stream, opening fresh bins is less costly.
        score -= 20.0 * progress;
    } else {
        // Reward placing into bins whose residual is close to the item size.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * gap;
        // Mild bonus for consuming large chunks of a bin's remaining space.
        score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Lookahead: if the next item exactly fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 0.4 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += 0.2 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Prefer bins already below mean residual (consolidating emptier space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or nearly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            // prefer chains where next item leaves a small remainder
            let next_post = slack - next_item_size.min(slack);
            score -= 150.0 - (slack as f64).min(150.0);
            if next_post == 0 && slack >= next_item_size {
                score -= 100.0;
            }
        } else {
            // next item cannot fit here; penalize wasted residual
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual: favor bins that are
    // already "tight" (below mean residual) since they'll close out soon
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post_f / mean_residual;
        score += 40.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: make empty bins attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score = (bin_capacity as f64) - 60.0;
        // if the item fits poorly anywhere else (large dead space), new bin wins
        if post_residual > 30 && next_item_size > post_residual {
            score -= 120.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
        // many open bins: discourage proliferation
        score += 8.0 * open_bins_count as f64;
    }

    // Slight preference for filling bins when many are open
    score += 0.05 * open_bins_count as f64 * post_f / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // If the lookahead item can reuse the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward when residual closely matches the next item (perfect chain).
        let chain_gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_gap / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize, scaled by item size.
        score += 4.0 * (next_item_size as f64 / 100.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (low mean residual) or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows as the stream progresses (less room to amortize).
        score += 10.0 + 15.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).sqrt();
        }
        // Attractive only if existing residuals are tight and item is large.
        score -= 6.0 * fit_ratio * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
    } else {
        // Slight penalty for leaving a bin very fragmented (many tiny residuals).
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        // Prefer spreading load when many bins are open and residuals are high.
        score -= 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Time-horizon coupling: later in the stream, minimize residual slack more aggressively.
    score -= 5.0 * progress * tightness;

    // Small item into a large residual wastes the bin; large item into large residual is good.
    score -= 4.0 * fit_ratio * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (0.5 + progress) * cap;

    let mut score = pr - 12.0 * coupling;

    // Lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.35 * diff;
        if pr >= next_item_size as f64 {
            score -= 4.0 * (1.0 - diff / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Penalize residuals far from mean (dead space)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: slightly favor early, penalize late
    if bin_residual == bin_capacity {
        score += 3.0 * progress - 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class logic: residuals that are multiples of common small sizes
    // (10, 20, 25, 50) are "usable" and should be mildly penalized less.
    let r = post_residual;
    let harmonic_usable = (r % 10 == 0) || (r % 25 == 0) || (r % 50 == 0);
    if harmonic_usable {
        score -= 6.0;
    } else {
        score += 4.0; // awkward dead space
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // next item fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / r as f64;
            score -= 15.0 * fill;
            // harmonic match of leftover after next item
            let r2 = r - next_item_size;
            if r2 % 10 == 0 || r2 % 25 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize blocking
            score += 8.0 * ((next_item_size - r) as f64 / cap);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating many fragmented bins when few fit anyway.
    if fitting_bins_count > 1 {
        // among competing bins, prefer tighter packing: score already tracks post_residual
        score += 0.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when the current bin would leave a large awkward residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early, expensive later.
        score = cap * 0.75 + 25.0 * progress;
        // If no open bin fits at all (this is the only candidate), allow it.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference to balance against mean residual: bins far below mean
    // residual are "fresher" and better to fill first.
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Slight pressure to keep open bin count low late in the stream.
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily (post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits the post residual,
    // this placement is excellent — reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - chain_fit / cap);
        // Perfect chain: post residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, scaled by
        // how far the next item overshoots.
        let overshoot = (next_item_size - post_residual) as f64;
        score += 0.35 * overshoot.min(cap);
    }

    // Compare post_residual against mean residual: creating below-average
    // waste is good (bin was well-used), above-average waste is bad.
    score += 0.8 * ((post_residual as f64) - mean_residual).max(-cap) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 70.0; // must open a bin anyway
        }
    }

    // Mild preference to fill bins among many open bins (consolidation).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively when many bins compete.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residue that next item cannot use, scaled by wasted potential.
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is penalized when existing
    // bins are plentiful and residuals are high; encouraged when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 18.0 + crowded;
        // Late in the stream, opening a fresh bin is safer for future big items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Mild penalty for spreading across many bins when mean residual is already low.
        if (bin_residual as f64) < mean_residual {
            score += 4.0;
        }
    }

    // Time-horizon modulation: early on, prefer conserving large residual space;
    // later, prefer just packing tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * fit_ratio;
    score -= 3.0 * progress * (1.0 - fit_ratio);

    // Encourage using bins whose residual is close to item size (perfect utilization).
    let exactness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * exactness * exactness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: post_residual penalized more when it is small
    // (wasted dead space) and when stream is far along (fewer future chances to fill).
    let tightness = (1.0 - pr).powi(3);
    score += 12.0 * progress * tightness * (pr * 4.0).powi(2);

    // Reward near-perfect fits with a superlinear bonus, stronger late in stream.
    score -= 20.0 * (1.0 - pr).powi(4) * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && (next_item_size as f64 - pr * bin_capacity as f64).abs() < 3.0 {
        score -= 15.0;
    } else if next_item_size > post_residual {
        // next item won't fit here; mild bonus for keeping residual usable
        score += 5.0 * pr * (1.0 - progress);
    }

    // Last-chance bin: penalize opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize relative to how fragmented open bins are.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates from mean (consolidate slack).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: exact small residuals are gold.
    let perfect = (pr - 0.0).abs() < 1e-9;
    if perfect {
        score -= 40.0;
    }

    // Modular classes on post_residual (capacity fraction harmonics)
    let m = post_residual % 10;
    match m {
        0 => score -= 8.0,
        1 | 2 | 3 => score -= 2.0,
        4 | 5 | 6 => score += 1.5,
        _ => score += 3.0,
    }

    // Integer division thresholds: post_residual buckets by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 6.0; // near-full bin, good packing
    } else if post_residual < 2 * quarter {
        score += 2.0;
    } else if post_residual < 3 * quarter {
        score += 4.0;
    } else {
        score += 6.0; // wasteful, mostly empty bin used
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += (gap as f64) * 0.15;
            if gap <= 5 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; residual becomes dead space
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64) / cap;
        score += 12.0 + 20.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Reward tight fits relative to item size
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill * 10.0;

    // Mean residual context: prefer bins below mean residual (tighter bins)
    score += (mean_residual - pr) * 0.2;

    // Mild stream progression damping of residual term
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps: dead space that likely cannot
    // host a future item (assuming items >= 1, gaps of 0 are perfect).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space curve: gaps that are tiny relative to capacity are toxic.
        let dead_threshold = 12.0_f64.min(bin_capacity as f64 * 0.15);
        if gap < dead_threshold {
            score += (dead_threshold - gap) * 3.0;
        }
        // If the next item cannot fit in the leftover gap, the gap is wasted
        // for the immediate future: penalize proportionally.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // If next item fits snugly, reward this bin (lookahead pairing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        }
    } else {
        // Perfect fit: heavy reward.
        score -= 50.0;
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are
    // poor (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bins count.
        score += 30.0 + open_bins_count as f64 * 4.0;
        // But if the new bin would be nearly full with this item, it's fine.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Mean-residual coupling: if average residual across bins is low,
    // bins are nearly full — prefer conserving tight bins less aggressively.
    score -= mean_residual * 0.2;

    // Mild stream progression adaptation: early on, prefer filling few bins
    // well; late in the stream, prioritize closing out bins (perfect fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // how well item fills the residual

    // Reward high fill ratio (tight packing) with a strong subtraction.
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly fits the post residual,
    // this is a perfect chain -> heavily reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 25.0;
        } else if nxt <= pr {
            // Next item can still fit after this placement: good chaining.
            let chain_tightness = nxt / pr.max(1.0);
            score -= 12.0 * chain_tightness;
        } else {
            // Next item cannot use the post residual: penalize wasted space.
            let waste = pr / cap;
            score += 10.0 * waste;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "special",
    // prefer using them while they are still usable.
    if pr < mean_residual {
        score -= 4.0 * (mean_residual - pr) / cap;
    } else {
        score += 2.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin; slight penalty so tight fits win.
        score += 8.0;
        if item_size as f64 > 0.6 * cap {
            score -= 6.0; // large items into fresh bins is fine
        }
    }

    // Early in the stream, allow more bins to open (build a diverse residual pool).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 3.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are already open and this placement leaves
    // an awkward residual (small but not zero).
    if pr > 0.0 && pr < 10.0 {
        score += 3.0; // tiny dead space is nearly useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Nonlinear tightness reward: convex in leftover space so near-perfect fits win big.
    score = score.powf(1.25);

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // scaled by how much of the next item they would absorb.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= next_item_size as f64 * 0.9;
    }
    // Penalize leaving a sliver that almost certainly can't fit anything (dead space),
    // unless the lookahead item actually fits there.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && next_item_size <= post_residual) {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spending a large-residual bin on a small item when alternatives exist.
    if item_size <= bin_residual / 3 && fitting_bins_count > 1 {
        score += item_size as f64 * 0.4;
    }

    // New empty bin candidate: discourage unless open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 5.0;
        // If existing bins are nearly full on average, opening fresh is cheaper.
        score -= (mean_residual / bin_capacity as f64).powf(2.0) * 20.0;
        // Large items into a fresh bin are fine (clean fit, no fragmentation).
        score -= item_size as f64 * 0.15;
        // Early in the stream, opening bins is less costly (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal leftover space, scaled non-linearly.
    let mut score = post;

    // Non-linear tightness reward: strong quadratic-quartic discount for small post_residual.
    let post_frac = post / cap;
    score -= 0.35 * cap * (1.0 - post_frac) * (1.0 - post_frac) * (1.0 - post_frac);

    // Exact-fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize dead space in the "unusable" range: post_residual too small for the
    // smallest plausible item (<=10) yet nonzero, creating stranded capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose residual can still host the next item,
    // penalize bins that leave residual just below next_item_size (bad stranding).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.25 * nxt;
        } else if nxt > post && post > 0.0 {
            score += 0.20 * (1.0 - post / nxt) * nxt * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (penalize new-bin alternative via its own branch below).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes existing residual.
    // Penalize it, more so late in the stream and when many bins could fit.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score += 12.0 + 0.5 * waste * (0.5 + progress);
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
    }

    // Smooth stream-progress coupling: early on, consolidation matters less;
    // late in the stream, tighten placements aggressively.
    score *= 1.0 - 0.15 * progress * progress;

    // Mild tie-breaker: prefer bins with residual far from mean (balanced spread).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify by capacity fraction.
    // Small residuals (< 20% of capacity) are near-dead space; penalize.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score += 30.0 * (0.2 - frac);
    }

    // Harmonic classes via integer division thresholds on post_residual.
    // Residuals that are multiples of common item-size classes are reusable.
    let class = post_residual / 10; // harmonic class index (item sizes 1..100)
    if class >= 1 && post_residual % 10 == 0 {
        score -= 8.0; // round residual = reusable for round items
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if lookahead would then fit almost exactly.
            let pr2 = post_residual - next_item_size;
            if pr2 <= 5 {
                score -= 15.0;
            }
        } else {
            // Lookahead won't fit here; slight penalty unless post_residual tiny.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (better-packed bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early in stream, be slightly more exploratory toward new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score = 40.0 - 60.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // item can't fit anywhere else anyway handled elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps below ~20 are usable only by the smallest items; mild penalty.
        score += 12.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin becomes dead for the next item; extra penalty.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (high mean residual spread or many nearly-full bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin grows with number of open bins.
        score = bin_capacity as f64 + 5.0 * (open_bins_count as f64);
        // If some open bin fits decently, discourage new bin.
        if fitting_bins_count >= 1 && (mean_residual - item_size as f64).abs() < 15.0 {
            score += 50.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer tighter packing
    // (lower post_residual dominates anyway, add coupling).
    score += 0.15 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Slight preference for bins with residuals close to the item
    // (tight fit relative to the fleet mean).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect lookahead fit bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space next item cannot use
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score -= 20.0 * tightness;
    }

    // Compare against mean residual across open bins
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow new bin if item is huge and no bin fits well
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild penalty for very large leftover fragments (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small waste).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large leftover dead space nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a sliver that the next item cannot use.
        score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless the fit into open bins is bad.
    if bin_residual == bin_capacity {
        score = 25.0 + 0.35 * open_bins_count as f64;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 4.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If mean residual is large, open bins are wasteful; opening a fresh bin is fine.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Mild preference for filling already-open bins when many are open.
    if bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // Global state: if mean residual is low, conserve space more aggressively.
    score -= 3.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal waste, with a non-linear (cubic) amplification of dead space.
    let mut score = pr + 18.0 * (pr / cap).powi(3);

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, large residuals become increasingly costly.
    score += 10.0 * t * (pr / cap).powi(2);

    // Deviation from mean residual across open bins: prefer bins whose
    // remaining space is small relative to the fleet average (tight packing).
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev - 4.0 * dev * dev;

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // with a smooth quadratic bonus based on how well the next item fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 8.0 * fit_quality;
        } else {
            // penalize bins that strand the next item proportionally to the gap
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // scaled by how little slack remains (smooth interaction).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr / cap);
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a new
    // bin early in the stream, easing off smoothly as the stream progresses;
    // also penalize more when many bins are already open (fragmentation).
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - t) + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for too many open bins relative to progress (encourages consolidation).
    score += 0.5 * (open_bins_count as f64) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue classes
    // modulo 10 (item granularity) and by capacity fractions.
    let residue_class = (post_residual % 10) as f64;
    let tenth = bin_capacity as f64 / 10.0;

    // Penalize leftovers that are "useless" (small nonzero remainders that few
    // future items can fill). Dead space = small post_residual but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - residue_class; // waste penalty for unusable slivers
    }

    // Reward post_residuals that exactly match common item sizes (perfect fit classes)
    let perfect_fit_classes: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    if perfect_fit_classes.contains(&post_residual) {
        score -= 15.0;
    }

    // Integer-division threshold: post_residual / 10 buckets; deeper bins (more
    // leftover capacity in coarse terms) are mildly preferred.
    score -= (post_residual / 10) as f64 * 0.8;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // penalize gap by its harmonic class: gaps < 10 are dead space
            if gap < 10.0 {
                score += 6.0 + gap * 0.5;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot follow into this bin: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are crowded or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * 0.5 + mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin; discounted when bins are crowded or late in stream
        score += 45.0 - crowded * 6.0 - progress * 10.0;
        if item_size >= 70 {
            score -= 20.0; // huge items justify fresh bins
        }
    }

    // Slight preference to fill fuller bins (small residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Prefer bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space relative to lookahead
    }

    // Align with mean residual: bins far from mean residual treated cautiously.
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: baseline competitive score, adjusted by open-bin pressure.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0 + pressure * 0.4;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative, opening new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 8 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits too: strong reward scaled by tightness.
            score -= 40.0 - gap.min(40.0);
        } else {
            // Next item won't fit: mild penalty proportional to overshoot.
            score += gap * 0.3;
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // New bin more attractive late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference to fill bins with larger residual spread.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer minimal post-residual (already the base).
    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is nearly dead space
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty unless post_residual is tiny.
        score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // More competition: mild preference for tightest fit (post_residual base handles it).
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residuals below mean residual (tighter bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early in stream: encourage keeping large residuals open (avoid fragmenting early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., this bin is empty and current bins are crowded or fit is poor).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let crowding = open_bins_count as f64;
        // If many bins open but none fit well, opening new bin is fine; otherwise penalize.
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + 2.0 * (1.0 - poor_fit) - 0.5 * crowding.min(10.0);
            // Late in stream, prefer filling existing bins even more.
            score += 10.0 * progress;
        }
    }

    // Large items: prefer to place them where they nearly fill the bin.
    if item_size >= bin_capacity * 3 / 4 {
        score -= 0.1 * (bin_residual - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits with quadratic decay over progress
    let tightness = (norm_post - 0.05).powi(2);
    score -= (1.0 - progress) * 8.0 * (-tightness * 40.0).exp();

    // Penalize large dead space superlinearly, more so late in the stream
    score += progress * 6.0 * norm_post * norm_post * cap;

    // Reward bins whose residual matches the next item's needs (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_term = (norm_post - nx).abs();
        score -= 4.0 * (-match_term * 6.0).exp();
    }

    // Penalize crowded bin pools mildly; encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mean-residual deviation penalty: prefer bins near the mean to keep balance
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // Slight preference for filling larger items into fuller bins
    score -= norm_item * norm_item * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            _ => 0.0,
        };
        score -= class_bonus as f64;

        // Dead-space penalty: residuals too small for the minimum item size.
        if pr < 10 {
            score += 30.0 + (10 - pr) as f64;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Fraction-of-capacity coupling: prefer filling bins past the halfway
    // harmonic threshold.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac >= 0.5 {
        score -= 8.0 * fill_frac;
    } else {
        score += 4.0 * (0.5 - fill_frac);
    }

    // Lookahead harmonic: if next item exactly divides into the post residual
    // (or into a harmonic class of it), reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size.max(1) == 0 {
            score -= 15.0;
        }
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving awkward space.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = 45.0 + pressure;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild stream-progress adaptation: later in the stream, consolidate more
    // aggressively (tolerate tighter fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: hard penalty.
            score += 60.0;
        } else if post_residual <= 20 {
            // Only fits the smallest items: strong penalty.
            score += 25.0;
        } else {
            // Mild superlinear penalty on residual waste.
            score += (post_residual as f64) * (post_residual as f64) / 200.0;
        }
    } else {
        // Perfect fit: large reward.
        score -= 50.0;
    }

    // Reward tight fits relative to the bin.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins with residual below the mean (pack the emptiest tight bins first).
    score -= 2.0 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0) / 10.0;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 10.0; // next item can't use this gap
        }
    }

    // New-bin candidate: neutral-ish baseline, chosen only when no open bin scores better.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mildly reward
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize proportionally to the dead gap
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize residuals far below the mean residual (creating outlier dead space)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discard near-empty placements that fragment a fresh bin
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let poor_fit = if next_item_size > 0 && post_residual != next_item_size { 1.0 } else { 0.0 };
        score += 40.0 - 5.0 * crowding + 20.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual penalizes dead space nonlinearly.
    let pr = post_residual as f64;
    score += 0.6 * (pr / cap) * pr;

    // Reward filling bins nearly full (post_residual small relative to item).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Lookahead: if the next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here; slight penalty proportional to wasted potential
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing roomy bins less,
    // encourage consolidation into tighter bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (0.5 + progress);

    // Late in the stream, be more conservative: penalize leaving large residuals.
    score += 6.0 * progress * (pr / cap);

    // New-bin candidate handling: opening a new bin is generally costly, but attractive when
    // open bins fit poorly (item barely fits elsewhere) or when open-bin count is low.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 45.0 + 10.0 * progress;
        // If item is large relative to capacity, opening fresh bin avoids fragmentation.
        new_bin_score -= 12.0 * (item_size as f64 / cap);
        // If only one fitting bin and it's not this (i.e. some bin barely fits), discourage new bin.
        if fitting_bins_count >= 1 {
            new_bin_score += 18.0;
        }
        // If mean residual across open bins is large, reuse is cheap: penalize new bin.
        new_bin_score += 0.15 * mean_residual;
        // If next item is big, a fresh bin may serve both: slight discount.
        if next_item_size >= 50 {
            new_bin_score -= 6.0;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals; late, penalize them super-linearly.
    let progress_coupling = pr * pr / cap * (0.5 + progress) + pr * progress * progress;
    score += 0.35 * progress_coupling;

    // Reward tight fits: small post_residual relative to item size.
    if it > 0.0 {
        score -= 0.5 * (it / (pr + it)) * (it / (pr + it)) * cap * 0.1;
    }

    // Lookahead: penalize if post_residual cannot serve next item; reward if it exactly fits.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 0.4 * (1.0 - slack / cap) * (ni / cap);
        } else {
            score += 0.15 * (ni - pr) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.6 * cap;
    }

    // Penalize bins far below mean residual (fragmentation asymmetry) smoothly.
    score += 0.2 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate handling: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = cap * (0.5 + 0.5 * progress);
        score = base + if fitting_bins_count == 0 { -cap } else { 0.0 } + 0.1 * (open_bins_count as f64);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls in
    // "awkward" classes relative to typical item sizes (1..=100).
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify residual into harmonic bands via integer division thresholds.
        let band = pr / 10; // 0..=10 harmonic class
        // Small residuals (band 0..3) are near-perfect fits: reward.
        if band <= 3 {
            score -= (4 - band) as f64 * 8.0;
        }
        // Mid residuals (band 4..6) are risky dead space: penalize extra.
        else if band <= 6 {
            score += 6.0 + (pr % 10) as f64 * 0.5;
        }
        // Large residuals are fine (bin stays useful).
        else {
            score -= 2.0;
        }
        // Modulo coupling: residual that is a multiple of common item sizes
        // (10, 20, 25, 50) is more likely reusable.
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.0; }
    }

    // Lookahead: if next item exactly fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Slack after next placement: penalize if it creates awkward gap.
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.3;
            if gap <= 5 { score -= 10.0; }
        } else {
            // Next item cannot use this residual: residual likely dead.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or many bins are open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * pressure - 10.0 * progress;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild bias toward fuller bins overall.
    score -= (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 4.0;

    // Tie-break with mean residual divergence: prefer bins close to mean
    // to keep a balanced residual pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste -> heavy quadratic penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Small-but-reusable gaps (10..=20) are risky dead space if the next item
    // cannot use them; penalize proportionally to mismatch with lookahead.
    if post_residual >= 10 && post_residual < 20 {
        if next_item_size > post_residual {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            score -= 5.0; // next item fits this gap: reward tight chaining
        }
    }

    // Reward exact/very tight fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to item size (best-fit coupling).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading when many open.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is already cramped; prefer filling such bins (lower their score).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well or
    // stream is early; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 18.0 + (item_size as f64 * 0.1);
        if step_index as f64 / (total_items.max(1) as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item would exactly fill post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits aggressively
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits the post-residual exactly, strongly favor
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 150.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remaining space: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness relative to mean residual: bins with less residual than average are
    // "tighter" — prefer filling them (lower score) when they fit well.
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when plenty of well-fitting open bins exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 + 40.0 * (open_bins_count as f64).ln().max(0.0) + 30.0 * progress;
        // Allow opening a new bin only if the item leaves a lot of dead space elsewhere
        // is impossible here; but if item is huge relative to capacity, new bin is fine
        if item_size as f64 > 0.9 * bin_capacity as f64 {
            score -= 200.0;
        }
        // If no open bin really fits well (post_residual would be tiny elsewhere),
        // the base penalty stands, discouraging bin proliferation.
    }

    // Mild preference to keep scores distinct across bins with equal post_residual
    score += 0.01 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to strongly penalize dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item can fit in the post-residual, this bin remains useful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Post-residual too small for next item: dead space penalty scaled by how close it came.
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += gap * 0.3;
            }
        }
    } else {
        // Last item: strongly prefer filling any bin completely.
        score -= post_residual as f64 * 0.5;
    }

    // New-bin candidate logic: opening a new bin is fine early or when few bins are open,
    // but costly when many bins already exist with slack (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let slack_pressure = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Penalize new bins more as slack accumulates in existing bins.
        score = 70.0 + progress * 30.0 + slack_pressure * 40.0 + open_bins_count as f64 * 2.0;
        // If no existing bin fits well (this call happens anyway), allow new bin when
        // item is large and would leave little residual elsewhere.
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Mild preference for bins whose residual was already small (consolidation).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Slight time-decay urgency: late in the stream, avoid opening bins / favor packing tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly damped
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (small post_residual); late, tolerate slack.
    let tightness = norm_pr * norm_pr * (1.0 - progress);
    score += 30.0 * tightness;

    // Reward using an existing bin more strongly as stream progresses
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if !is_new_bin {
        score -= 12.0 + 8.0 * progress;
    } else {
        // Penalize opening a new bin when good fits exist, relax late in stream
        score += 5.0 * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for next item, penalize near-misses
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) as f64;
            score -= 6.0 * (1.0 - (slack / cap).powi(2));
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += 3.0 * (pr as f64 - mean_residual) / cap;

    // Mild penalty for many open bins to encourage consolidation early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers divisible by 10 (capacity fractions)
    // are more reusable than odd remainders.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => { score -= 12.0; }                     // perfect decade leftover
        5 => { score -= 6.0; }                      // half-decade leftover
        2 | 4 | 6 | 8 => { score -= 2.5; }          // even, mildly reusable
        _ => { score += 3.0; }                      // odd remainder, dead-space risk
    }

    // Integer-division thresholds on post_residual: coarse capacity-fraction buckets.
    let tenth = bin_capacity / 10;
    let frac_bucket = pr / tenth; // 0..=10
    score += match frac_bucket {
        0 => 20.0,          // nearly full bin: excellent
        1 => 8.0,
        2 => 2.0,
        3 | 4 => 0.0,
        5 | 6 => -1.0,
        7 | 8 => -4.0,
        _ => -8.0,          // mostly empty bin: wasteful placement
    };

    // Lookahead coupling: reward leaving a residual that exactly fits the next item
    // (modulo-harmonic match), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 5.0;
            } else if gap <= 5 {
                score += 2.0; // tight near-miss leaves sliver
            }
        } else {
            // next item cannot fit in this leftover anyway
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when this item is huge relative to
    // capacity or all open bins would leave bad odd remainders.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 6.0 + 0.35 * open_bins_count as f64; // default penalty
        if big_item > 0.8 {
            new_bin_score -= 25.0; // huge item: fresh bin is fine
        }
        if fitting_bins_count > 0 {
            // compare worst-case leftover if placed in an open bin
            let open_leftover_penalty = (mean_residual - item_size as f64).max(0.0) % 10.0;
            if open_leftover_penalty > 5.0 {
                new_bin_score -= 10.0;
            }
        }
        if next_item_size >= item_size && next_item_size <= bin_capacity {
            new_bin_score -= 3.0; // fresh bin can host the next big item too
        }
        score = new_bin_score;
    }

    // Slight late-stream consolidation pressure: prefer filling existing bins as the
    // stream progresses to reduce final open-bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are pure waste.
    // A post_residual in [1, 9] can never be used again -> heavy penalty.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Small-but-usable residual: mild penalty to prefer tighter fits elsewhere.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Reward bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin only when fit is bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive if this bin would otherwise create dead space
    // or the item is large relative to the residual.
    if bin_residual == bin_capacity {
        let waste_if_placed_elsewhere = (bin_residual - item_size) as f64;
        let dead_space_risk = if post_residual < 10 { 30.0 } else { 0.0 };
        let large_item_bonus = if item_size > 50 { 12.0 } else { 0.0 };
        score += 20.0 - dead_space_risk - large_item_bonus + waste_if_placed_elsewhere * 0.05;
    }

    // Lookahead: if next item could exactly use this bin's post_residual, reward placement.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 20.0;
        } else if diff < 10 {
            score -= 10.0 / (diff as f64);
        } else {
            score += diff as f64 * 0.1;
        }
    }

    // Slight pull toward bins near the mean residual (keeps residuals balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits — penalize residual far from zero but also
    // penalize near-full bins slightly less than awkward mid-range leftovers.
    let pr = post_residual as f64;
    score += 0.35 * (pr - mean_residual).abs();

    // Aggressive 2-step lookahead: reward if the next item fits exactly or
    // nearly into the post-residual of this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            // Next item fits after this placement: reward exact chaining.
            score -= 45.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to the overshoot,
            // unless the leftover is small (dead space anyway).
            score += 0.8 * (-diff).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good chaining exists and
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && (pr as f64 - next_item_size as f64).abs() < 5.0 { 1.0 } else { 0.0 };
        score += 12.0 + 6.0 * chain_bonus;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize creating residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference for keeping mean residual balanced across open bins.
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with slight nonlinearity
    score = post_residual as f64 * (1.0 + 0.002 * (post_residual as f64 / bin_capacity as f64));

    // Penalize creating tiny unusable dead space (below min item size ~1..100 range)
    let min_size = 1.0f64;
    if (post_residual as f64) < min_size * 10.0 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / (min_size * 10.0));
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins already fit well
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin
        score = bin_capacity as f64 * 0.8;
        // Acceptable if no open bin fits or fits are poor
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
        // Lookahead: if next item fits better in a fresh bin, encourage opening
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.6 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Few open bins -> opening is cheap
        score -= 4.0 * open_bins_count as f64;
        // If mean residual is small, open bins are nearly full -> new bin attractive
        score -= (bin_capacity as f64 - mean_residual).max(0.0) * 0.3;
    } else {
        // Lookahead synergy: reward if next item fits into the post residual
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0 + 0.1 * next_item_size as f64;
        }
        // Penalize leaving residual just barely below next item size (dead space)
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
        // Mild preference for bins below mean residual (balance load)
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_frac = pr / cap;

    // Base: minimize wasted space with a non-linear (quadratic-cubic) penalty.
    let mut score = pr * (1.0 + residual_frac * residual_frac);

    // Smooth coupling: as the stream progresses, tight fits become more valuable.
    let tightness = 1.0 - residual_frac; // 1.0 = perfect fit
    score -= 18.0 * tightness * tightness * (0.4 + progress);

    // Favor bins whose residual is small relative to the mean residual
    // (i.e., we are consolidating space into fewer bins).
    let mean_frac = mean_residual / cap;
    score += 8.0 * (residual_frac - mean_frac) * (1.0 + progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward placements that still leave room for the next item,
    // penalize placements that block it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early on and when
    // existing bins fit reasonably well. Decay the penalty as stream progresses.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += (1.0 - progress) * 30.0 * escape + 12.0;
        // If the item is large, a fresh bin is a natural home; soften penalty.
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Mild preference for keeping the number of open bins manageable.
    score += open_bins_count as f64 * 0.15 * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small divisors) are more attractive.
    let pr = post_residual as u32;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr <= 10 {
        25.0 // dead space: unusable for min item size 10
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold: leftover must be able to host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 / cap * 10.0;
        } else {
            score += 15.0; // cannot chain the lookahead item here
        }
        // Harmonic pairing: post_residual % next_item_size small => future fit likely
        if next_item_size > 0 && post_residual % next_item_size <= 5 {
            score -= 5.0;
        }
    }

    // Fractional capacity coupling: prefer filling large fraction of capacity.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are fragmented (low mean residual) or crowded.
    if bin_residual == bin_capacity {
        score = 45.0
            + (open_bins_count as f64) * 2.0
            - mean_residual / cap * 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item followed by bigger one: fresh bin fine
        }
    }

    // Late-stream conservatism: near the end, waste less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item can exactly use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 + progress) * 0.35;

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += ((mean_residual - bin_residual as f64).abs()) * 0.15
        - (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: mildly penalize so it's chosen only when fits are bad,
    // but relax the penalty late in the stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 45.0 - (open_bins_count as f64) * 1.5 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 20.0 * (5 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
        } else {
            // next item won't fit here: penalize wasted lookahead potential
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post-residual is below average (tighter packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0);
    } else {
        score += (pr - mean_residual).min(50.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin's fit is bad
    // and no other bins can fit the item.
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin is fine
        }
        // If next item is large, a fresh bin may be better than fragmenting
        if next_item_size >= 70 && post_residual < 20 {
            score -= 100.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize creating residual that is too small for the next item (dead space).
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (many competing bins) or when the item is large and would fragment a bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (fitting_bins_count as f64).ln().max(0.0);
        score -= 8.0 + 10.0 * openness + 6.0 * progress;
        // If the item is a tight fit somewhere else, opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        // If next item is large, an empty bin is valuable.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Global state: penalize adding to bins whose residual deviates from mean
    // (keeps residual distribution homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild pressure to fill existing bins rather than proliferate.
    score += 0.05 * open_bins_count as f64;

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are fine; late, penalize dead space quadratically.
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (post_residual near zero), stronger late in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Perfect fit: strong reward, amplified with progress.
    if post_residual == 0 {
        score -= 20.0 + 15.0 * progress;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 5.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // New-bin candidate: keep it attractive early when few bins are open,
    // discourage unnecessary new bins late in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 4.0 * progress * (1.0 + open_f / 20.0).min(2.0);
        score -= 3.0 * (1.0 - progress);
    }

    // Mild preference for bins tighter than the current mean residual.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "usable" slots
    // for typical item sizes; odd/prime residues tend to become dead space.
    let res = post_residual as i64;
    let class_bonus: f64 = match res % 10 {
        0 => 12.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward when the leftover after the next item lands on a harmonic class
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item
        score += 4.0;
    }

    // Integer-division threshold: bins whose residual is in the "tight" band
    // (residual / 10 <= 3) are precious — favor filling them exactly.
    let tight = post_residual / 10;
    if tight <= 3 && post_residual < item_size + 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when no
    // open bin offers a decent fit; relax the penalty late in the stream
    // when mean residual across bins is large (fragmentation is high).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let penalty = 20.0 + 15.0 * (1.0 - progress) - 10.0 * frag;
        score += penalty.max(2.0);
    }

    // Prefer bins whose residual is closest to the item (best-fit flavor),
    // scaled by how many bins compete.
    let fit_gap = (bin_residual as i64 - item_size as i64).max(0) as f64;
    score += 0.05 * fit_gap * (1.0 + fitting_bins_count as f64).ln();

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score += 40.0; // tiny gap is worthless; slight penalty relative to perfect fit
    } else if post_residual <= 20 {
        // Small gap that likely can't fit most items: penalize heavily.
        score += 15.0 + (20 - post_residual) as f64 * 0.8;
    } else if post_residual <= 40 {
        score += 4.0;
    } else {
        // Large usable residual: reward keeping big usable space.
        score -= 2.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty to sharpen discrimination among them.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Open bins pressure: when many bins are open, discourage spreading items thin;
    // when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few open bins or no good fits exist.
        score += 5.0 + bin_pressure * 1.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        score -= bin_pressure * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; mild penalty for leaving gap it could have used
            score += 1.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // to keep the pool of usable gaps homogeneous.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (post_residual small) non-linearly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    if pr == 0.0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // Tightness bonus: smaller post_residual relative to capacity is better.
        score -= 60.0 * (1.0 - pr / cap).powi(6);

        // 2-step lookahead: strongly reward bins whose post_residual matches next item.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            let diff = (pr - n).abs();
            if pr >= n {
                // Next item fits exactly into the leftover: chain reward.
                score -= 40.0 * (1.0 - diff / cap).powi(4);
            } else {
                // Leftover too small for next item: penalize dead space proportionally.
                score += 8.0 * (1.0 - pr / n).max(0.0);
            }
            // Mild penalty if post_residual is a "dead zone" (too small for typical items 1..100).
            if pr < 10.0 {
                score += 15.0;
            }
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (fill fuller bins first, keep sparse bins flexible).
    score += 0.5 * (mean_residual - pr);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large relative to capacity and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Offset when item is big (new bin gives it a full home).
        score -= 0.45 * item_size as f64;
        // Offset when few bins can fit the item (poor fit elsewhere).
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins that will end up with usable leftovers
    // (>= 10) so future small items can still land there.
    if post_residual >= 10 && post_residual < 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (dead space below small-item threshold is fine).
    let small = 10.0f64;
    if (post_residual as f64) < small {
        score -= 40.0;
    }
    // Non-linear penalty on wasted residual, scaled by how much of the bin remains.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste;

    // Lookahead: reward if the next item fits into the post-residual (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize residuals that no plausible item can use (dead space).
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is bad and many open bins already have slack.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 30.0;
        let crowded = mean_residual > 25.0 && open_bins_count > 2;
        if poor_fit && crowded {
            score -= 10.0; // allow opening a fresh bin
        } else {
            score += 20.0; // prefer existing bins otherwise
        }
    }

    // Time horizon: early in the stream, keep bins tight (long game);
    // late in the stream, tolerate slack since few items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins tighter than average (consolidation).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * (1.0 + 2.0 * progress * pr_norm + 3.0 * progress * progress * pr_norm * pr_norm);
    score += 12.0 * poly * progress;

    // Reward tight fits more strongly as the stream matures.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to the mean residual across open bins.
    score += 0.35 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 6.0 * progress;
        } else {
            score += 10.0 * (1.0 - pr / (next_item_size as f64).max(1.0));
        }
    }

    // Make the fresh empty bin attractive only for poor fits / large items.
    if bin_residual == bin_capacity {
        let poor_fit = tightness < 0.25;
        if poor_fit || fitting_bins_count == 0 {
            score -= 55.0;
        } else {
            score += 45.0 + 30.0 * progress;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions
    let c = bin_capacity as f64;
    let frac = post_residual as f64 / c; // 0..1

    // Dead-space classes: residuals that are hard to fill get penalized
    // (small odd residuals below typical item sizes 10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }
    // Harmonic bucket penalty: which quarter of the bin does the leftover live in
    let bucket = (post_residual * 4) / bin_capacity.max(1);
    score += match bucket {
        0 => 0.0,
        1 => 5.0,
        2 => 12.0,
        _ => 0.0,
    };

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: exact-ish fit rewarded
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / c);
        } else {
            score += 8.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but allow it when remaining residual would be dead space anyway
    if bin_residual == bin_capacity {
        // fresh bin score: baseline of capacity minus a small opening discount
        score = c - 10.0;
        // if current item leaves a nice harmonic residual in a fresh bin, slight bonus
        if post_residual >= 20 && post_residual % 10 == 0 {
            score -= 5.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are useless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill, excellent
    } else if post_residual < 10 {
        // Dead space: gap below the smallest possible item size.
        score += 500.0;
    } else {
        // Usable gap: reward proportionally if it can still host typical items.
        let usable = (post_residual >= 10) as f64;
        score -= usable * 0.5 * (post_residual as f64);
    }

    // Reward when post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 60.0; // gap becomes dead relative to the known next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 150.0 + 40.0 * (open_bins_count as f64);
        // But a new bin is fine if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Mild bonus for consolidating into bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    // Stream progression: later in the stream, be slightly more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus decaying with distance from next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + gap * 0.25);
    }

    // Penalize dead space that no plausible item (>=1) can fill usefully;
    // worse when post_residual is small but nonzero relative to bin capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility; extreme small residuals waste bins.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev - 0.10 * pr.min(mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (post_residual very small relative to capacity, i.e. tight fit elsewhere is fine;
    // but an empty bin should lose when a good fit exists).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Encourage new bin early in the stream when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 10.0).min(1.0));
    }

    // Mild penalty for leaving large residuals when many bins are already open.
    score += 0.02 * pr * (open_bins_count as f64).min(20.0) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward high fill ratio non-linearly
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize dead space that nothing typical can use
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // nearly perfect fit
        } else if post_residual <= 30 {
            score += 0.3 * post_residual as f64; // mildly awkward
        } else {
            score += 1.2 * post_residual as f64; // large dead space penalty
        }
    }

    // Lookahead: if the next item fits into the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 15.0 - 0.4 * pair_waste as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // next item won't fit here
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are poorly usable
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bin more readily when open bins are full-ish or few fitting bins exist
        score += 30.0 - 25.0 * (1.0 - pressure) - 15.0 * scarcity - 5.0 * progress;
    } else {
        // mild bonus to consolidate into existing bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Slight penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic cost on leftover space (smooth, punishes dead space super-linearly).
    let mut score = (post / cap) * (post / cap) * cap;

    // Small linear term keeps ordering sane near zero.
    score += 0.35 * post;

    // Reward bins whose leftover can still host the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_tightness = 1.0 - ((post - nxt) / cap);
            score -= 12.0 * fit_tightness;
        } else {
            // Leftover too small for the next item: penalize proportionally to waste.
            score += 6.0 * (nxt - post) / cap * cap / 100.0;
        }
    }

    // Stream-progress coupling: early on, prefer tight fits less aggressively
    // (keep bins flexible); later, squeeze hard into existing bins.
    let progress_bias = 1.0 + 1.5 * progress;
    score *= progress_bias;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - (post / cap);
        score -= 25.0 * fit_quality * (1.0 + progress);
    }

    // Penalize scattering across many open bins mildly; encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Mean-residual interaction: if this bin's residual deviates from the mean,
    // prefer bins closer to the mean (keeps bin portfolio balanced).
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual).abs() / cap;
    score += 8.0 * dev * (0.5 + progress);

    // New-bin candidate: make it attractive only when the fit into it is very good
    // (item nearly fills a fresh bin) or late in the stream with poor alternatives.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 0.5 * cap * (1.0 - fill) * (1.0 - fill) + 10.0 * (1.0 - fill);
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: coarse buckets via integer division.
    let class = post_residual / (bin_capacity / 5); // 5 residual classes (0..=5)
    score += class as f64 * 7.0;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        // Near-perfect fit: dead space too small for any item.
        score -= 120.0;
    } else if post_residual <= 20 {
        // Small but potentially usable dead space.
        score -= 30.0;
    }

    // Reward if the next item fits into the post-residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Extra reward for tight chaining (little slack after the pair).
        let pair_slack = post_residual - next_item_size;
        if pair_slack < 10 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leftovers that cannot host the lookahead item.
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // Cheaper to open a new bin when many bins are open and mean residual is high.
        score -= (open_bins_count as f64).sqrt() * 5.0;
        score -= mean_residual * 0.4;
        // If the next item also fits in a fresh bin, slightly better.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Modulo-arithmetic coupling: residuals divisible by common item sizes (e.g. 10, 20, 25)
    // are more likely to be filled later; reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 6.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open bins (score new bins lower);
    // later, prefer compacting into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 - progress * 10.0;

    // Mild penalty proportional to fill of the bin (prefer using emptier bins when ties),
    // scaled by number of fitting bins to break ties toward emptier bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0
        + (fitting_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that is too small to ever hold a meaningful future item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual is well above the item (comfortable fit),
    // but not so large that we waste a nearly-full bin.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving a gap that fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0; // gap won't fit next item
        }
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = 45.0 + crowd * 10.0 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack -> reward proportional to tightness
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item won't fit here -> mild penalty scaled by leftover size
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * next_item_size as f64;
    }

    // Penalize dead space below minimum plausible item size (1..100 interface)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual across open bins: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open new bins (keep bins tidy)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items (typical min size 1..100, but
    // dead space below ~20 is nearly unusable; nonlinear penalty for awkward leftovers).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 20.0 {
            score += (20.0 - dead) * 1.5;
        }
        // Perfect closure bonus
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses the leftover
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * nl * nl;
        } else {
            // next item cannot use leftover: penalize large wasted residuals slightly
            score += 0.05 * (post_residual as f64 - (bin_capacity - next_item_size).min(post_residual)) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: waste of (capacity - item) plus fixed opening cost.
        score = (bin_capacity - item_size) as f64 + 8.0;
        // If many bins are open and mean residual is large, prefer reusing existing space.
        score += 0.15 * open_bins_count as f64;
        score += 0.5 * (mean_residual - post_residual as f64).max(0.0);
        // Early in stream, opening bins is fine; late in stream prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
        // If next item is large, a fresh bin keeps flexibility for it.
        if next_item_size > 60 && item_size <= 40 {
            score -= 5.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on tolerate residual, later penalize waste more strongly
    let prog_weight = 1.0 + 1.5 * progress * progress;
    score += 6.0 * prog_weight * pr_norm;

    // Dead-space penalty: residual too small to hold anything useful (smooth ramp)
    let dead = ((35.0 - pr).max(0.0) / 35.0).powi(2);
    score += 12.0 * dead * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let miss = ((nxt - pr).max(0.0) / cap).powi(2);
        score -= 8.0 * fits;
        score += 10.0 * miss;
    }

    // Last-chance bonus: only fitting bin -> strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild dispersion penalty: prefer bins near mean residual (balance load)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Congestion: many open bins -> discourage hoarding low-fill bins late
    score += 0.5 * open_bins_count as f64 * progress * pr_norm;

    // New-bin candidate: make it moderately attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score = 20.0 + 30.0 * progress - 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but avoid tiny dead space (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver penalty
    }

    // Harmonic class: post_residual bucket via integer division
    let pr_class = post_residual / 12; // classes 0..8
    score += pr_class as f64 * 4.0;

    // Reward exact-fill classes (post_residual divisible into small harmonic slots)
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain potential
            let leftover = post_residual - next_item_size;
            if leftover < 10 && leftover > 0 {
                score += 10.0; // chains into dead space
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, unless all fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score = 0.0; // must open
        }
    }

    // Progression: tighten packing later in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score += (open_bins_count as f64) * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to plausibly
    // host a future item are "dead". Penalize the awkward gap band hard.
    if post_residual > 0 && post_residual < 15 {
        score += 30.0 + (15 - post_residual) as f64 * 3.0;
    } else if post_residual >= 15 && post_residual < 30 {
        // moderately awkward gap: mild penalty
        score += (30 - post_residual) as f64 * 0.4;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can use the leftover space, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the known next item: slight dead-space penalty
        score += 4.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate (brand-new empty bin): strong penalty so it only wins
    // when every open bin is a terrible fit.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild drift term: as the stream progresses, tighten packing slightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // leftover too small for next item: penalize wasted dead space
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        score += 20.0 + 60.0 * avg_fill;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin useful when next item is large
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Penalize dead space that is too small to ever be useful (min item 1,
    // but typical items are larger; treat residual < 12 as near-dead).
    if post_residual < 12 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for hoarding space it can't use.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin mildly unattractive so we
    // prefer existing bins with decent fits, but attractive when the fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else if item_size > bin_residual * 3 / 4 {
        // Very poor fit into a partially-filled bin: encourage opening a new bin.
        score += 6.0;
    }

    // Global state: many open bins with large mean residual -> consolidate,
    // favor bins with residual below mean (filler bins).
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = pr / cap;
    let mut score = pr;

    // Non-linear waste penalty: dead space is increasingly bad as residuals shrink
    score += 12.0 * fit * fit * (1.0 - fit) * cap;

    // Tight fits favored, with smooth cubic coupling to stream progress
    score -= 20.0 * (1.0 - fit) * (1.0 - fit) * (1.0 + progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit);
    }

    // Prefer bins below mean residual early, above later (smooth interaction)
    score += 6.0 * (pr - mean_residual) * (0.5 - progress);

    // Lookahead: reward leaving room for next item (smooth quadratic overlap)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0);
        score -= 8.0 * (slack / cap) * (1.0 - (slack / cap));
        if nx > pr {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * fit;

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define dead-space classes.
    let post = post_residual;
    let class = post % 10;
    // Penalize small nonzero residues (unusable slivers), reward exact fits.
    if post == 0 {
        score -= 50.0; // perfect fit
    } else if post < 10 {
        score += 30.0 + (10 - post) as f64 * 2.0; // tiny dead space
    } else {
        // reward post_residuals that are "harmonic": multiples of 10 or 25
        if post % 25 == 0 {
            score -= 8.0;
        } else if post % 10 == 0 {
            score -= 4.0;
        } else {
            score += class as f64 * 0.5;
        }
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size < post {
            let gap = post - next_item_size;
            if gap < 10 {
                score -= 15.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item cannot use this residual anyway
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize when bin residual deviates from mean residual (imbalance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Late in the stream, prefer tightening (waste less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral baseline; only chosen if open bins look bad.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100),
    // but treat gaps that still fit the next item as alive.
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            // Nonzero residual that likely cannot serve the next item: dead space.
            // Penalize proportionally to how small the gap is relative to capacity.
            let dead = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 40.0 * dead * dead;
        }
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = item_size as f64 / (item_size + post_residual) as f64;
        score -= 15.0 * tightness;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor closing out bins with larger residuals by penalizing high post_residual more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Align with mean residual: prefer bins whose resulting residual is near/below
    // the current mean (drives residuals down uniformly, reducing fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Lookahead coupling: if the next item exactly matches the resulting residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., existing residuals would leave large dead space). A fresh bin has
    // full residual; make it costly unless open bins are highly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Opening a new bin is cheap only when open bins are mostly full (low mean residual)
        score += 10.0 + 30.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted residual
            score += (post_residual as f64 - 0.0) * 0.3;
        }
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, slightly prefer opening fresh bins for large items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize dead space that is too small to be useful (below min item size ~1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 0.15 * post_residual as f64; // moderately awkward gap
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: mild penalty for leaving a gap it almost fits
        let miss = (next_item_size - post_residual) as f64;
        if miss < 10.0 {
            score += 8.0 * (1.0 - miss / 10.0);
        }
    }

    // Prefer filling already-open bins when many bins are open (bin count pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with below-average residual are "well used",
    // placing into them is cheap; bins with large residual waste potential
    if bin_residual as f64 > mean_residual {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate: neutral-ish baseline; open a fresh bin only when it beats
    // squeezing into a poor fit. Penalize opening new bins early in the stream
    // or when few bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        // but if current item is large and would leave a big gap anywhere, new bin is fine
        if fill > 0.7 {
            score -= 12.0;
        }
    }

    // Small tie-break toward higher fill percentage
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post residual (dead space), scaled by stream progress
    let mut score = post * (1.0 + 0.5 * progress * norm_post);

    // Smooth coupling: reward tight fits more as stream progresses
    score -= (1.0 - norm_post).powi(2) * cap * (0.3 + 0.7 * progress);

    // Cubic interaction: penalize medium dead space, tolerate tiny residuals
    score += norm_post.powi(3) * cap * 0.8 * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - ((post - nxt) / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Prefer bins with residual below mean (compact usage), smooth sigmoid-like term
    let diff = (mean_residual - post) / cap;
    score += diff * 5.0;

    // Mild penalty for too many open bins relative to progress
    score += open_bins_count as f64 * (1.0 - progress) * 0.05;

    // New-bin candidate: penalize slightly so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i64; // 0..3 quartile class

    // Reward tight fits (small post_residual), with class-dependent bonuses
    match class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score -= 5.0,                        // good fit
        2 => score -= 1.0,                        // mediocre
        _ => score += 3.0,                        // mostly empty, wasteful
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic lookahead: does next item pair with post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 15.0 / (1.0 + pair_waste as f64 / 10.0);
        } else {
            // next item cannot use residual: penalize large leftover less if bin would be dead anyway
            score += (post_residual as f64 - bin_capacity as f64 * 0.25).max(0.0) * 0.1;
        }
    }

    // Integer-division thresholds on post_residual
    let dead_zone = post_residual / 10; // decile
    if dead_zone > 0 && dead_zone < 3 {
        score += 4.0; // small unusable slivers are dead space
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // late in stream, prefer consolidation into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Prefer filling bins below mean residual (balance toward closing bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Slight preference for bins that will be closed soon (low residual relative to capacity)
    if post_residual < item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    } else {
        // Larger leftover space is still somewhat wasteful but recoverable
        score += (post_residual as f64) * 0.15;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits proportionally to fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Open-bin pressure: discourage opening new bins when many are open;
    // encourage consolidation when few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open_bins_count is high
        score += 5.0 + (open_bins_count as f64) * 2.5;
        // Allow new bin only if existing bins would leave very tight fits
        if fitting_bins_count > 0 {
            let best_possible = mean_residual;
            if best_possible - item_size as f64 >= 20.0 {
                score += 15.0; // existing bins fit reasonably, avoid new bin
            }
        }
    } else {
        // Reward using existing bins, more so when open_bins_count is high
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Late-stream pressure: as the stream progresses, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect two-item packing chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match: strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 4.0 * diff;
        } else {
            // Penalize residual that the next item cannot use at all.
            if post_residual < next_item_size {
                score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
            } else {
                score += 0.25 * diff;
            }
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far above the
    // mean are "loose" — prefer filling them; tight bins get penalized.
    let resid = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { resid };
    score += 0.35 * (resid - mean);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is huge relative
    // to capacity and no open bin is a good home; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64) * 0.05 + (step_index as f64 / (total_items.max(1) as f64)) * 2.0;
        score += 55.0 - 40.0 * frac - pressure * 3.0;
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score += 15.0; // chain likely wastes a fresh bin
        }
    }

    // Mild preference for keeping few open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual and apply superlinear penalty.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 60.0;

    // Lookahead: if the next item fits into this bin's post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            // Extra reward when the pair nearly fills the bin.
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= pair_fill * 25.0;
        } else {
            // Dead space the next item cannot use: penalize.
            score += 10.0;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // placing there preserves looser bins for larger future items.
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += rel * 20.0;
    }

    // Time horizon: early in the stream, be more conservative (favor tight fits);
    // late in the stream, just minimize waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable if no open bin fits well
        // (post_residual would be large) or few bins are open.
        let waste_elsewhere = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score = post_residual as f64
            + 25.0
            - waste_elsewhere * 20.0
            - (open_bins_count as f64).min(10.0) * 1.5
            + frac * 10.0;
        // Late in stream: slightly discourage proliferating bins.
        score += progress * 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln() * 2.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear waste term: squared normalized post-residual
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * cap * 0.01;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (20.0 + 30.0 * progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= 15.0 + 25.0 * snug * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that next item cannot use
        score += 8.0 * ((post - next_item_size as f64) / cap).abs();
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when open bins exist and mean residual is large
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 10.0 + 50.0 * mean_frac * mean_frac + 5.0 * open_bins_count as f64;
        // New bin more acceptable late in stream if current bins are tight
        score -= 40.0 * progress * (1.0 - mean_frac) * (1.0 - mean_frac);
    }

    // Mild preference for fuller bins relative to mean residual
    score += (post - mean_residual) * 0.3;

    // Smooth polynomial interaction between fill ratio and progress
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 classes create "usable zone" bonuses.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => -30.0,               // perfectly reusable residual
        1..=5 => -10.0 - (5 - class) as f64 * 2.0,
        6..=9 => (class as f64 - 5.0) * 4.0, // awkward sliver, penalize
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds: residual bands relative to capacity.
    let band = post_residual / (bin_capacity / 4); // 0..=4 quarter bands
    score -= match band {
        0 => 25.0, // nearly full bin -> great, seal it
        1 => 10.0,
        2 => 0.0,
        3 => -5.0,
        _ => -8.0,
    };

    // Lookahead coupling: reward residuals that exactly or nearly fit next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item closure
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 25.0 * (1.0 - gap as f64 / cap_f);
            if gap % 10 == 0 { score -= 8.0; }
        } else {
            // next item can't fit here: penalize more as slack shrinks
            let overshoot = next_item_size - post_residual;
            score += 6.0 + overshoot as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score = cap_f - item_size as f64;
        if fitting_bins_count == 0 { score -= 20.0; }
        if post_residual % 10 == 0 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity && (bin_capacity - next_item_size) % 10 == 0 { score -= 5.0; }
    } else {
        // Waste fraction penalty (nonlinear, quadratic in fill).
        let fill = (bin_capacity - post_residual) as f64 / cap_f;
        score -= 20.0 * fill * fill;

        // Mean-residual steering: prefer bins below mean residual (tighter packs).
        score += (mean_residual - post_residual as f64) * 0.3;

        // Stream progression: late in the stream, favor closing bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * (post_residual as f64) * 0.1;

        // Many open bins: discourage spreading, reward consolidation.
        if open_bins_count > 4 {
            score += open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: post_residual near zero relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size < 10 {
        // Next item is tiny and won't fit here; the leftover is likely dead space.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few bins fit.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin only attractive when no open bin
    // offers a decent fit (i.e., mean residual is small) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - mean_residual * 0.5 - (1.0 - progress) * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Mild preference for bins whose residual deviates favorably from the mean.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact 2-step lookahead match:
    // if the next item fits the post-residual, this placement is excellent.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_scale = (post_residual as f64 / bin_capacity as f64).max(0.0);
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        // Perfect 2-chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Small post residual that still accommodates the next item is great
        if next_item_size <= post_residual && post_residual <= next_item_size + 5 {
            score -= 40.0 * match_scale;
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: simply prefer tightest fit
        score += 10.0;
    }

    // Penalize creating tiny unusable slivers (dead space below minimum item size ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Reward bins with residual below the current mean (efficiently filled bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current bins would waste a lot
    // or there are many open bins already fragmenting capacity.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a perfect fit, better than a bad one.
        score = 0.6 * bin_capacity as f64
            + 0.4 * (open_bins_count as f64)
            + (mean_residual / bin_capacity as f64) * 20.0;
        // If the next item is huge, a fresh bin is more flexible
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared post-residual penalty scaled by capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 2.0 * tight * tight * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64) / (post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps.
            score += 0.05 * (post_residual as f64);
        }
    } else {
        // Last item: reward filling as much as possible.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * (open_bins_count as f64);
        // But if mean residual is small (open bins are crowded), opening new is fine.
        score -= (mean_residual / 10.0).min(25.0);
        // If item is large relative to capacity, opening fresh may be wise.
        if (item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 12.0;
        }
    }

    // Time horizon: late in stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Prefer bins below mean residual (more room) slightly, to balance loads.
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (pr / cap).powi(2); // high when bin becomes full
    let mut score = pr;

    // Reward tight fits more strongly as stream progresses (smooth coupling)
    score -= tightness * (10.0 + 40.0 * progress);

    // Penalize dead space that likely can't be used later
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 2.0 } else { 0.0 };
    score += dead;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Discard new-bin candidate slightly when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space bands".
    let residue = post_residual % 10;
    score += (residue as f64) * 0.9; // prefer residuals landing on decade boundaries

    // Integer-division harmonic classes: how many 10-blocks fit in the leftover.
    let harmonic = post_residual / 10;
    score -= harmonic as f64 * 2.5; // larger usable blocks are good

    // Fraction of capacity used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0; // reward big fills

    // Tight fit bonus: post_residual small relative to item size.
    if post_residual > 0 {
        let tightness = item_size as f64 / (item_size + post_residual) as f64;
        score -= tightness * 8.0;
    } else {
        score -= 25.0; // perfect fit: strong reward
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= next_fit * 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover too small for next item: penalize proportional dead space
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // or residuals across open bins are already large.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty keeps existing-bin preference; relax when open bins are packed.
        let mut new_bin_penalty = 18.0
            - avg_pressure * 25.0
            - (open_bins_count as f64 * 0.4)
            + progress * 5.0;
        // If item is large and would leave tiny residue anywhere, new bin attractive.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 6.0;
        }
        if new_bin_penalty < -10.0 {
            new_bin_penalty = -10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference to consolidate: fewer open bins is better.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 { score -= 20.0; } else if gap < 10 { score += 10.0; } else { score -= 5.0; }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect 2-step fit: post_residual exactly equals next_item_size
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // post_residual too small to fit next item: penalize dead space relative to mean residual
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
            score += 0.3 * (mean_residual - post_residual as f64).max(0.0);
        }
    } else {
        // Last item: any placement is fine; prefer tightest fit only.
        score += 0.1 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Penalize creating tiny unusable slivers (below min item size 1..=10 heuristic band)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only when no good open bin exists,
    // but keep it competitive when open bins would leave large residuals.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large and current item is small, opening a fresh bin can be good
        if next_item_size > 0 && next_item_size > post_residual && item_size <= 30 {
            score -= 55.0;
        }
    }

    // Mild preference for filling bins tighter than the mean residual
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.8 {
        score -= 25.0 * (tightness - 0.8);
    } else if tightness < 0.3 {
        score += 15.0 * (0.3 - tightness); // wasteful placement penalty
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_tight = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * nxt_tight;
        } else {
            score += 8.0; // post_residual unusable by next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large (so the fresh bin will be well used) and global residuals are low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 0.5 * post_residual as f64
            + 40.0 * (1.0 - big_item)
            + 10.0 * (mean_residual / bin_capacity as f64)
            - 5.0 * progress;
    } else {
        // Slight penalty when the bin is far below the mean residual (unbalanced fill).
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth non-linear penalty on dead space
    let mut score = pr + 60.0 * pr_norm * pr_norm;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Penalize opening new bins late in the stream / when many bins open
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Lookahead: bonus if next item fits post-residual exactly-ish
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - pr) / cap;
    }

    // Smooth coupling with mean residual: prefer bins deviating below mean (concentrate waste)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by large common item sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let harmony_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: ideal
    } else if pr % 50 == 0 {
        -35.0
    } else if pr % 25 == 0 {
        -22.0
    } else if pr % 20 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr < 10 {
        25.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score += harmony_bonus;

    // Lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize wasting space it could have used
            score += 8.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last chance: strongly prefer using the only bin that fits, avoids a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins mildly; offset when many open bins are cluttered
        score += 12.0
            - 0.05 * open_bins_count as f64
            - 10.0 * (mean_residual / cap).min(1.0);
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tightness;
        // prefer bins with residual below the mean (denser bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Penalize creating post residual that no plausible item (10..80) can use
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 6.0; // gap 1..9 -> +54..+6
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving a gap that wastes the next item's chance
        score += 4.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly anywhere else.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let last_chance = fitting_bins_count == 1;
        // Opening a new bin is cheap early, expensive when many bins are open.
        score += 12.0 + 0.8 * pressure;
        if last_chance {
            // If this is the only fitting bin (the new bin itself), make it viable
            // when the fit would leave a tiny dead gap elsewhere.
            score -= 20.0;
        }
        if post_residual >= 40 {
            score -= 6.0; // roomy new bin is fine
        }
    } else {
        // Open-bin pressure: mildly discourage spreading when many bins already open.
        score += 0.15 * open_bins_count as f64;
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (consume the nearly-full bins first, keep roomy bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about creating dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin bonus: avoid opening new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 150.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * 40.0;

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize wasted residual the next item cannot use, scaled by its size.
            score += 0.10 * (post_residual as f64).min(next_item_size as f64);
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let base = 55.0 + 0.5 * open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in stream, opening fresh bins is cheaper than fragmenting.
        let time_adj = 15.0 * (1.0 - progress);
        score += base + time_adj;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items pair well with fresh space
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if mean_residual > 0.0 {
        let tightness = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += tightness * 10.0; // favor bins tighter than average
        if open_bins_count > 4 && bin_residual > mean_residual as u32 {
            score += 6.0;
        }
    }

    // Mild time-varying pressure to keep exploration dynamic across the stream.
    let phase = ((step_index as f64) * 0.37).sin();
    score += 2.0 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space, amplified as stream progresses.
    let mut score = pr * pr / cap + pr;

    // Smooth coupling: waste matters more later in the stream.
    score *= 1.0 + progress * progress;

    // Reward tight fits: item filling most of the residual gets a bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless item is large relative to capacity
    // or current bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap - 40.0 * fill - 0.5 * mean_residual;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Lookahead: penalize leaving a residual that fails to fit the next item
    // in a smooth way (sigmoid-like coupling).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = (pr - ni) / cap;
        let sig = 1.0 / (1.0 + (-slack * 8.0).exp());
        score += (1.0 - sig) * 15.0 * (1.0 - progress);
    }

    // Mild penalty for bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo common item sizes (10..80 grid)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        // dead-space penalty grows superlinearly for unusable slivers
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
        // modulo harmonic classes: residuals that divide evenly into many
        // future item sizes are more reusable
        let mut divis = 0u32;
        for d in 10..=80 {
            if d > pr { break; }
            if pr % d == 0 { divis += 1; }
        }
        score -= 6.0 * divis as f64;
        // integer-division thresholds: quarter classes of capacity
        let q = pr / 25; // 0..4
        score -= [0.0, 4.0, 8.0, 12.0, 16.0][q as usize];
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // early stream: allow more bins to spread load
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to the item (tight fit)
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * tight;

    // Prefer bins below mean residual (fill emptier bins first)
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // slight pressure against bin sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are pure waste,
    // but gaps too small for the NEXT item are even worse (likely dead forever).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // This gap cannot host the lookahead item: penalize proportionally to its uselessness
            score += 12.0 + (next_item_size - post_residual) as f64;
        }
        // Reward bins whose post_residual still fits the next item (keeps chains alive)
        if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (new bin would add a full-capacity residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // (their residuals are small and fragmented) or many bins are open.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // Opening a new bin wastes the residual mass of existing bins; penalize when
        // mean residual is large (existing bins still have room to consolidate).
        score += 5.0 + mean_r * 0.5;
        // Mild relief under bin-count pressure (avoid unbounded bin growth)
        score -= (open_bins_count as f64).sqrt() * 1.5;
        // If no existing bin fits well (this is the only fitting candidate = new bin),
        // the last-chance logic above already pushed open bins down; keep new bin moderate.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            // New bin can host the next item too: slightly more attractive
            score -= 3.0;
        }
    }

    // Tightness coupling: reward small post_residual non-linearly
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Mild penalty for leaving exactly awkward mid-range gaps (e.g. 6..15) that
    // rarely fit typical items but are too big to ignore.
    if post_residual >= 6 && post_residual <= 15 {
        score += 3.0;
    }

    // Slight preference for filling bins that are already mostly used
    // (keeps residual distribution bimodal: near-empty or near-full).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * item_size as f64;

    if next_item_size > 0 {
        // Perfect 2-step match: next item exactly fills post_residual -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space scaled by mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.6 * mismatch;
            // Extra penalty if post_residual is small unusable dead space
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual below mean are "well-used",
    // favor finishing them off; bins above mean are wasteful to top up slightly.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Late in the stream, consolidation matters more: penalize opening/using sparse bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 20.0 + 30.0 * progress;
        // But if no open bin gives a good 2-step fit, new bin becomes attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for many open bins: encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit quality: reward tight fits relative to capacity
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Strong reward for near-perfect fills
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 - (post_residual as f64) * 1.5;
    }

    // Last chance: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheap (build flexibility)
        score -= (1.0 - progress) * 20.0;
        // If item is large relative to capacity, a fresh bin is attractive
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Dead-space penalty: leaving residuals that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally to waste
            score += (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
        // If this bin's residual can't fit next item but another layout could, mild penalty
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.05 * (open_bins_count as f64).ln().max(1.0);
    }

    // Prefer bins with less residual when many bins are open (keep some bins tight)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0 * (open_bins_count as f64).sqrt();

    // Late-stream conservatism: waste matters more near the end
    score *= 1.0 + progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its non-linear decay
    let r_norm = pr / cap;
    let r_poly = r_norm * r_norm * (3.0 - 2.0 * r_norm); // smoothstep of residual

    // Base: post residual, shaped by progress (late stream -> penalize wasted space more)
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: small post-residual is valuable, especially late in stream
    score -= (1.0 - r_poly) * 30.0 * (0.5 + progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            // reward leaving room exactly usable by next item
            score -= 15.0 * (-((pr - nxt) / cap).powi(2) + 0.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalty for many open bins relative to residual spread
    score += (open_bins_count as f64).ln() * 2.0 + (pr - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        score += 12.0 * (1.0 - fit_quality).powi(2) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    let decade = pr / 10;

    // Dead-space penalty: small residuals (< next item) are wasted
    if pr > 0 && next_item_size > 0 && pr < next_item_size {
        score += 18.0 + 0.35 * (next_item_size - pr) as f64;
    }

    // Reward residuals that form "complement classes" with common item sizes
    // Classes 0, 5, and values near multiples of 10 are highly reusable
    match class {
        0 => score -= 12.0 + decade as f64 * 0.8,
        5 => score -= 9.0,
        1 | 9 => score += 4.0,
        2 | 8 => score += 2.0,
        _ => {}
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 25.0;
    }

    // Harmonic pairing: does post_residual pair with next_item_size exactly?
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap % 10 == 0 {
            score -= 8.0; // leaves a harmonic class-0 residual
        } else if gap < 5 {
            score -= 5.0; // near-perfect chain
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 - 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0;
        }
        // If mean residual is high, prefer existing bins
        score += mean_residual * 0.3;
    }

    // Tightness reward: the fuller the bin relative to capacity, the better
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 20.0;

    // Late-stream consolidation: prefer compacting as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (decade as f64);

    // Slight preference for bins below mean residual (spread small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let post = post_residual as f64;
    if post > 0.0 {
        // Dead-space zone: residuals too small for the smallest plausible item (1..=10).
        if post < 10.0 {
            score += 40.0 * (10.0 - post) / 10.0; // up to +40 for near-zero waste
        } else if post < 20.0 {
            // Moderately dead zone: only tiny future items can use it.
            score += 8.0 * (20.0 - post) / 10.0;
        }
        // Reward tight fits exponentially.
        let tightness = 1.0 - post / bin_capacity as f64;
        score -= 30.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward this bin.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 15.0;
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by waste.
            score += 5.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; make it attractive only when
        // no open bin offers a decent fit (its raw post_residual = capacity is high,
        // so it only wins when bonuses push it below open bins' scores).
        score = bin_capacity as f64 + 20.0 + 10.0 * pressure;
        if next_item_size > 0 && next_item_size as f64 <= bin_residual as f64 {
            score -= 5.0;
        }
        // If item is large relative to capacity, opening fresh is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Existing bins get a mild pressure discount so they win when fits are comparable.
        score -= 2.0 * pressure;
        // Prefer bins whose residual deviates favorably from the mean (balanced packing).
        score += 0.5 * (post - mean_residual);
    }

    // Stream progression: late in the stream, waste becomes costlier (no future to recover).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit is a gift: crush the score so it's essentially always chosen.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Residual below the minimum item size is dead space; mild extra reward since nothing else fits anyway.
        score -= 15.0;
    } else {
        // Penalize residuals that are large enough to be "wasted" but awkward (not reusable by typical items).
        let awkward = ((post_residual as f64) - 50.0).abs();
        score += 0.08 * awkward;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 12.0 + 20.0 * chain_quality;
    } else if next_item_size > 0 {
        // Placing here makes the next item less likely to fit here; penalize proportionally to how close it was.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.10 * miss;
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: be pickier, prefer the tightest among them (already handled) but add mild
        // pressure toward consolidating into bins with low mean deviation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item fits poorly
    // everywhere or the open-bin pool is saturated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 55.0;
        // Early in the stream, opening bins is cheap (future items can fill them).
        new_bin_penalty *= (1.0 - 0.5 * (1.0 - progress));
        // If item is large, a fresh bin gives maximal future flexibility.
        if item_size > 60 { new_bin_penalty -= 10.0; }
        // If several bins fit, discourage spreading.
        new_bin_penalty += 8.0 * (fitting_bins_count as f64);
        // If open bins are already crowded on average, new bin is more attractive.
        if mean_residual < item_size as f64 { new_bin_penalty -= 20.0; }
        // If no open bin fits (fitting_bins_count == 0 handled by caller), still slight penalty.
        score += new_bin_penalty;
    }

    // Mild global pressure: as many bins accumulate, prefer reusing existing space.
    score += 0.02 * (open_bins_count as f64);

    // Time-horizon modulation: late in the stream, waste matters more (no future to fill gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let post_norm = post_residual as f64 / bin_capacity as f64;
    let mean_norm = mean_residual / bin_capacity as f64;

    // Reward tight fits: subtract more as post_residual shrinks non-linearly
    score -= (1.0 - post_norm) * (1.0 - post_norm) * (30.0 + 40.0 * progress);

    // Penalize dead space: small residuals that likely become unusable
    if post_residual > 0 {
        let dead = (bin_capacity as f64 - post_residual as f64).min(post_residual as f64);
        score += (1.0 - dead / bin_capacity as f64) * 10.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post_residual as f64 {
            score -= 20.0 * (1.0 - (ns / post_residual as f64).powi(2));
        } else {
            score += 8.0 * ((ns - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_norm / (open_bins_count.max(1) as f64).sqrt();
        score += 15.0 - 20.0 * crowding + 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3 * post_norm;

    // Smooth polynomial coupling of fit ratio with stream progress
    score -= 12.0 * fit_ratio * (1.0 - fit_ratio) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Harmonic class of post_residual: residue classes mod small integers
    let pr = post_residual;
    // Penalize post-residuals that are "dead" (too small to ever be useful)
    let min_useful = 10u32; // smallest plausible item
    if pr > 0 && pr < min_useful {
        score += 60.0; // unusable sliver
    }

    // Reward residuals that fall into "usable" harmonic classes
    // class by integer division: which item-size decade fits
    let class = pr / 10;
    score -= (class as f64) * 4.0;

    // Modulo coupling: post_residual mod 10 near zero => tighter packing
    let m = pr % 10;
    score += m as f64 * 1.5;

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to gap
        score += (next_item_size as f64 - post).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // and no open bin gives a tight fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // new bin baseline: score ~ remaining capacity in new bin
        score = cap - item_size as f64;
        // favor opening a new bin for large items or when existing bins are fragmented
        score -= tightness * 15.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 {
            // competing with existing bins: make new bin less attractive unless
            // existing residuals are small (fragmented)
            score += (mean_residual / cap).max(0.0) * 20.0;
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild preference to fill bins with high residual when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Tie-break toward bins whose residual is close to item size (perfect fit)
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < item_size of small items) are wasted. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    // New-bin candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 3.0;
        // Don't open a new bin when a reasonable fit exists elsewhere.
        if fitting_bins_count >= 1 && item_size <= bin_capacity - 10 {
            score += 20.0;
        }
    } else {
        // Favor bins whose residual is close to the item (good fit ratio).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fit_ratio;
        // Slight preference for bins below mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    // (creates useful space); otherwise penalize leaving a gap that misleads.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Early in the stream, allow slightly more freedom; later, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tight packing strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much of post_residual it consumes
            score -= 200.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item does NOT fit: penalize leaving a residual that is
            // too small to be useful for the next item (dead space risk)
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual below mean means we tightened a relatively loose bin — good.
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= 0.3 * (mean_r - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_r);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to capacity (poor fit elsewhere likely) or few bins open.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        if !large_item && fitting_bins_count > 1 {
            score += 300.0; // discourage wasteful new bin
        } else if large_item {
            score -= 50.0; // big items may deserve a fresh bin
        }
        // early stream: allow new bins more freely
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 30.0;
        }
    }

    // Mild pressure against accumulating many open bins with large residuals.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    // Base: waste after placement, mildly discounted as stream progresses
    let mut score = pr * (1.0 - 0.3 * progress);

    // Smooth non-linear coupling of post_residual with progress
    let prn = pr / cap;
    score += 25.0 * prn * prn * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) non-linearly
    score -= 15.0 * (1.0 - prn) * (1.0 - prn) * fit_ratio;

    // Lookahead: reward residual matching the next item size (smooth kernel)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (-d * d * 8.0).exp() * next_ratio;
    }

    // Penalize when this bin is one of many fitting bins (prefer scarce capacity)
    if fitting_bins_count > 1 {
        score += 5.0 * ((fitting_bins_count - 1) as f64).ln_1p() * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - prn);
    }

    // New-bin candidate: neutral baseline, slightly discouraged early, encouraged
    // when open bins have small residuals (poor fit landscape)
    if bin_residual == bin_capacity {
        score = cap * 0.8 - 20.0 * mean_r * (1.0 - progress) + 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small post_residual in "nice" divisor classes
    // are more reusable. Classes based on capacity fractions and divisibility.
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        // Divisibility bonus: residuals that divide capacity (50, 25, 20, 10) are reusable
        if bin_capacity % post_residual == 0 {
            score -= 6.0;
        }
        // Half / quarter class residuals are prime targets
        if post_residual == bin_capacity / 2 {
            score -= 8.0;
        }
        if post_residual == bin_capacity / 4 {
            score -= 5.0;
        }
        // Dead space penalty: residual below min item size is unusable
        if post_residual < 10 {
            score += 40.0 * (1.0 - cap_frac);
        }
        // Mid-range residual (30..60) is most reusable: reward mildly
        if post_residual >= 30 && post_residual <= 60 {
            score -= 3.0;
        }
        // Integer-division threshold: post_residual in [item_size, 2*item_size) wastes less
        if post_residual >= item_size {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 4.0 * (nxt_post as f64 / bin_capacity as f64);
            if bin_capacity % nxt_post.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize slightly less if residual is still large
            score += 3.0 * (1.0 - cap_frac);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (tighter packing first)
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate logic: only attractive when current item is large or few bins fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good when the item is big and would leave a fragmented residual
        if large_item > 0.6 || (fitting_bins_count <= 2 && open_bins_count > 0) {
            score -= 20.0 + 15.0 * large_item + 5.0 * progress;
        } else {
            score += 30.0;
        }
        // With many open bins and small item, discourage spreading
        if open_bins_count > 4 && large_item < 0.5 {
            score += 20.0;
        }
    }

    // Mild stream-progress modulation: tighten packing as stream advances
    score *= 1.0 + 0.05 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are "dead" -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        // Quasi-dead gap: unlikely to be filled by typical items.
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating gaps that cannot fit the known next item
    // while the bin could otherwise have hosted it (wasted lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap exactly usable by the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate (empty bin): make it costly unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Large items justify a fresh bin more than small ones.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild alignment with mean residual: prefer bins whose leftover
    // stays near the fleet mean (keeps residual profile homogeneous).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;
    }

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual <= 20 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize slightly if we waste large residual
        score += 0.02 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 10.0;
        // But if no good fit exists (large mean residual mismatch), new bin is attractive
        let fit_quality = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        if fit_quality < 0.15 {
            score -= 6.0;
        }
        // Late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // Many open bins: discourage opening more
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residual close to item (best-fit flavor), scaled by global mean
    let deviation = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.1 * deviation;

    // Mild preference for filling already-open bins when many are open
    if bin_residual < bin_capacity {
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: strongly favor bins left with little residual.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Exact-fit bonus when residual becomes very small relative to capacity.
    if post_residual <= item_size.min(bin_capacity) {
        score -= 6.0;
    }

    // Penalize creating dead space that likely cannot be used by the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && nx > pr {
            score += 4.0 * (nx - pr) / cap;
        } else if pr >= nx {
            // Reward bins that can also host the lookahead item (chaining).
            score -= 3.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item fills it well.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        score -= 10.0 * (item_size as f64 / cap);
        // Late in the stream, prefer consolidation into open bins.
        score += 8.0 * progress;
    }

    // Mild preference for bins below mean residual (keeps spread balanced).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic: reward post_residual values that are "usable" ---
    // Dead space penalty: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Harmonic reward: post_residual divisible by common item sizes (10,20,25,50)
    // makes future perfect fits likely; subtract a bonus.
    let pr = post_residual;
    if pr > 0 {
        let mut harm: f64 = 0.0;
        for &d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                harm += 8.0;
            }
        }
        // Integer-division band: pr / 10 gives coarse class; mid classes are best targets
        let band = pr / 10;
        if (10..=20).contains(&band) {
            harm += 5.0;
        }
        score -= harm;
    }

    // Lookahead coupling: strongly reward leaving exactly next_item_size of room
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // slack beyond the next item is mildly penalized relative to mean residual
            score += 0.3 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else if post_residual > 0 {
            // cannot host next item: penalize proportionally
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress and bin count
        score = 55.0 + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 30.0; // next item won't fit a fresh bin either... keep anyway
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    } else {
        // Mild preference for tighter existing bins relative to mean residual
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (low waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Penalize leaving a gap that exactly wastes capacity fraction.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the gap: penalize proportionally to wasted gap.
            score += 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a new bin early when mean residual is high
    // (open bins are fragmented), penalize opening new bins late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = 60.0 + 40.0 * progress - 30.0 * fragmentation;
        // If a perfect/tight fit exists elsewhere, opening a new bin is unattractive;
        // handled implicitly since tight fits get large negative bonuses.
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: this bin becomes ideal for the next item
        } else if gap <= 5.0 {
            score -= 35.0 - gap * 4.0;
        } else {
            // penalize residuals that are awkwardly close but not usable
            score += gap * 0.15;
        }
        // If next item cannot fit this bin's post-residual, mild penalty scaled by tightness
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: strongly prefer minimal waste
        score += 0.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.5;
    } else {
        score += (pr - mean_residual).min(30.0) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        } else {
            // discourage opening new bins when existing bins fit; stronger early in stream
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 55.0 - progress * 20.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Penalize large dead space nonlinearly.
    score += (pr * pr) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin densely.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / bin_capacity as f64;
        let crowd = open_bins_count as f64 / (mean_residual + 1.0);
        score += 20.0 - 15.0 * pressure - 2.0 * crowd;
        if fitting_bins_count > 0 {
            score += 35.0; // discourage opening new bin when alternatives exist
        }
    }

    // Time horizon: late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * 0.5;

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, large residuals become increasingly costly (dead space).
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (0.5 + 3.0 * progress) + norm_post * progress * progress;
    score += 30.0 * poly;

    // Reward near-perfect fits (small post_residual) with a smooth quadratic bonus.
    let tightness = (cap - post) / cap;
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_term = 1.0 - (diff / cap).min(1.0);
        score -= 20.0 * match_term * match_term;
    }

    // Last-chance bin: penalize if this is the only fitting bin but fit is poor,
    // reward if fit is decent (avoiding a new bin is valuable).
    if fitting_bins_count == 1 {
        if norm_post < 0.2 {
            score -= 15.0 * (1.0 - norm_post);
        } else {
            score += 12.0 * norm_post;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // and the stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap).max(0.01);
        let fill_potential = (mean_residual / cap).clamp(0.0, 1.0);
        score += 60.0 - 25.0 * fill_potential - 5.0 * (1.0 - progress) - 2.0 * crowd.min(10.0);
    }

    // Mild penalty for bins far below mean residual (fragmenting outliers).
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core waste term: quadratic penalty on unusable dead space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Harmonic class of post_residual: residue classes modulo small divisors
    // reveal how "reusable" the leftover space is for typical future items.
    let pr = post_residual;
    let class_score: f64 = if pr == 0 {
        -40.0 // perfect fit, strongly reward
    } else {
        let mut s = 0.0;
        // post_residual divisible by 10 pairs well with the 10..80 grid
        if pr % 10 == 0 { s -= 6.0; }
        if pr % 20 == 0 { s -= 4.0; }
        if pr % 25 == 0 { s -= 3.0; }
        // awkward residues (odd, prime-ish leftovers) are dead space
        if pr % 2 == 1 { s += 3.0; }
        if pr < 10 { s += 12.0; } // sliver below minimum item size
        s
    };
    score += class_score;

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - 0.1 * slack as f64; // reward chaining
            // harmonic bonus if next item exactly consumes the class
            if pr == next_item_size { score -= 15.0; }
            if pr % next_item_size == 0 && pr > next_item_size { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover; dead space likely
            score += 6.0 + 0.15 * (next_item_size - pr) as f64;
        }
    } else {
        // last item: only perfect fits matter
        if pr > 0 { score += 8.0; }
    }

    // Last-chance bin: strongly prefer using the sole fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // this item leaves a large, well-structured residual in a fresh bin,
    // or when the current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        // fresh bin: score is its post_residual (item_size leftover),
        // adjusted by how structured that leftover is.
        score -= 8.0;
        if item_size % 10 == 0 { score -= 4.0; }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        score += 2.0 * open_bins_count as f64;
    } else {
        // existing bin: mild reward for keeping bins consolidated
        score -= 3.0;
        // if this bin's residual deviates badly from the mean, it's a
        // fragmented outlier; discourage dumping into it
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Fractional capacity thresholds: reward placements leaving residual
    // in "usable bands" (>= half capacity or exactly small multiples).
    let half = bin_capacity / 2;
    if pr >= half { score -= 5.0; }
    if pr > 0 && pr <= bin_capacity / 10 { score += 10.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1..100 range, but practically small gaps < ~15 are waste)
    // are heavily penalized, unless post_residual == 0 (perfect fit).
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 30.0; // unusable tiny gap
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins whose residual is above the mean residual (keeps big gaps
    // available in less-used bins, consolidates fullness).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 6.0; // next item won't fit here; slight penalty
        } else {
            score += (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when no open bin offers a decent fit (post_residual small
    // on existing bins is already penalized above).
    if bin_residual == bin_capacity {
        // Neutral base: opening a new bin costs open-bin pressure implicitly,
        // but give a mild penalty so good fits in existing bins win.
        score += 5.0 + open_bins_count as f64 * 0.3;
        // But if the item is large relative to mean residual, opening fresh
        // may be better; reduce penalty.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact match between the
    // post-placement residual and the next item's size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap == 0.0 {
            score -= 40.0 + 0.5 * nxt; // perfect 2-step chain: place here
        } else if nxt <= post {
            // next item fits after this one: mild reward proportional to tightness
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += 4.0 + 0.15 * (nxt - post);
        }
        // reward residuals that stay reusable for a range of future items
        if post >= 10.0 && post <= 40.0 {
            score -= 3.0;
        } else if post < 10.0 && post > 0.0 {
            // tiny unusable sliver
            score += 6.0;
        }
    } else {
        // last item: just minimize waste
        score += 2.0;
    }

    // Compare against mean residual of open bins: prefer bins that are already
    // below-average full (keeping tight bins for tighter fits).
    if (bin_residual as f64) > mean_residual {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive when no open bin fits well (large item, few options).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let openness = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        // penalize opening new bins when good fits exist; small bonus early in stream
        score += 18.0 / pressure - 6.0 * openness;
        if item_size >= 70 {
            score -= 5.0; // huge items pair well with a fresh bin
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: bonus if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: mildly prefer bins where this item leaves a rounder residual.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a bin is attractive only when few bins
    // fit the item or mean residual across open bins is very low (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        let mut new_bin_score = 55.0;
        new_bin_score -= 20.0 * fragmentation;      // fragmented state -> new bin ok
        new_bin_score += 15.0 / open_pressure;      // many open bins -> discourage
        new_bin_score -= 10.0 * progress;           // late stream -> consolidate
        if fitting_bins_count <= 1 {
            new_bin_score += 40.0;                  // no real alternative
        }
        // Anchor new-bin score around a neutral band so comparisons are meaningful.
        score = new_bin_score + post_residual as f64 * 0.5;
    } else {
        // Mild global consolidation pressure: prefer filling bins when many are open.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual deviates favorably from the mean (above-mean residual
    // bins can absorb big items later; below-mean bins should be finished off).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;

    // Reward tight fits: penalize small post_residual less, using smooth quadratic coupling
    let fit_quality = post / cap;
    score -= (1.0 - fit_quality) * (1.0 - fit_quality) * item * 0.5;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - chain_fit / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't chain here; mild penalty scaled by wasted potential
        let waste = (next_item_size as f64 - post).max(0.0) / cap;
        score += 10.0 * waste * progress;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item).max(0.0);
        score += 60.0 - 25.0 * (mean_gap / cap);
        // Later in stream, prefer reusing bins more strongly
        score += 40.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates from mean (fragmentation avoidance), smoothly
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Slight preference for bins with larger residual early, tighter late
    score += (bin_residual as f64 / cap) * (1.0 - 2.0 * progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" classes are wasteful; near-zero leftovers are perfect.
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / capacity_f;

    // Perfect-fit reward: strong bonus for tiny post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Modulo/harmonic classes on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4
    match class {
        0 => { score -= 60.0; }          // leftover < 25%: dense packing
        1 => { score += 10.0; }          // 25-50%: moderately reusable
        2 => { score += 40.0; }          // 50-75%: wasteful but large chunks
        _ => { score += 80.0; }          // >75%: nearly empty bin used badly
    }

    // Lookahead coupling: reward when next item fits exactly into the post residual,
    // penalize when next item is close but misses (dead-space creation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;              // guaranteed perfect chain
        } else if next_item_size < post_residual {
            // next fits: the smaller the leftover after the next item, the better
            let nxt_post = post_residual - next_item_size;
            score -= 150.0 * (1.0 - nxt_post as f64 / capacity_f);
        } else {
            // next item misses this residual: penalty grows with closeness (frustration)
            let miss = nxt - post_f;
            score += 40.0 * (1.0 - miss / capacity_f);
        }
    }

    // Dead-space avoidance: penalize residuals that are too small to hold any
    // realistic item (below the minimum item size of 1, scaled by stream position).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress); // early dead space is costlier
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Penalize the empty-bin call by default.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when alternatives score badly.
        score += 250.0;
        // If no open bin fits, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Large item in a fresh bin leaves a big reusable residual: mild discount.
        score -= 0.5 * (item_size as f64);
        // Late in the stream, consolidation matters more: raise the bar slightly.
        score += 50.0 * progress;
    }

    // Tie-break with mean residual: prefer bins deviating from the mean downward
    // (use up bins that are already mostly full).
    score += 0.3 * (mean_residual - post_f);

    // Prefer bins whose residual was tight before placement (harmonic density).
    let pre_frac = bin_residual as f64 / capacity_f;
    score += 30.0 * pre_frac;

    // Mild scaling by open bin count: many open bins -> favor consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        // A residual that cannot fit even the smallest plausible item is dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < item_size {
            // Gap smaller than the current item: likely hard to reuse.
            score += 15.0 * (1.0 - post_residual as f64 / item_size as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Best-fit flavor: tighter fit is better.
    score += 0.3 * post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to item) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tight = mean_residual < item_size as f64 * 1.2;
        if mean_tight && open_bins_count > 0 {
            score -= 30.0; // open a fresh bin rather than wreck a tight one
        } else {
            score += 35.0 + 20.0 * (1.0 - progress); // early on, prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual <= 10 {
            // leftover too small for next item but nearly full: still good.
            score -= 8.0;
        } else if post_residual < next_item_size {
            // dead space that next item cannot use: penalize.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 55.0 * large;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (avoid spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let waste = bin_capacity as f64 - item_size as f64;
        // New bin is attractive only if the item is large (low waste) or late in stream.
        score += 15.0 + waste * (0.5 + 0.5 * (1.0 - progress));
        // If no open bin fits, opening a new bin is necessary: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Lookahead: if next item is large, opening fresh bin is fine.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if next item fits into this bin's post_residual,
    // reward; if it would leave this bin with unusable residue, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // dead space likely
        }
    }

    // Prefer bins with below-average residual (concentrate filling).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.15 * diff;

    // Mild pressure against accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    // Small time-varying exploration term (deterministic, grounded in stream state).
    let phase = (step_index as f64 / 7.0).sin();
    score += 1.5 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm * (1.0 + progress);

    // Smooth coupling: penalize post_residual that matches the lookahead item poorly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        // reward when next item fits exactly into post residual (small |diff|, pr>=nxt)
        score -= 25.0 * (1.0 - (diff * cap).abs().min(cap) / cap) * (1.0 - (diff * cap < 0.0) as i32 as f64 * 0.5);
        // smooth exact-fit reward
        score -= 30.0 * (-8.0 * diff * diff * cap).exp();
    }

    // Mean residual interplay: deviating from mean residual is penalized smoothly
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Slight bias against opening new bins early when open bins exist
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 12.0 * scarcity * (1.0 - progress) + 8.0 * pr_norm;
    }

    // Late-stream tightening: prefer minimal waste as stream ends
    score += 20.0 * progress * pr_norm * pr_norm * (pr / (pr + item_size as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" fractions
    // of capacity (0, 25, 50, 75) are reusable; odd leftovers are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = match pr {
        0 => 60.0,                       // perfect fit
        1..=5 => 45.0,                   // near-perfect
        _ => {
            if pr % 25 == 0 { 35.0 }
            else if pr % 10 == 0 { 25.0 }
            else if pr % 5 == 0 { 12.0 }
            else { -8.0 }                // awkward residue penalized
        }
    };
    score -= harmonic_bonus;

    // Lookahead coupling: reward if next item fits the post-residual well.
    if next_item_size > 0 && (pr as u64) >= (next_item_size as u64) {
        let gap = pr - next_item_size;
        let gap_score = match gap {
            0 => 55.0,
            1..=5 => 38.0,
            _ => {
                if gap % 10 == 0 { 22.0 }
                else { 8.0 - (gap as f64) * 0.05 }
            }
        };
        score -= gap_score;
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to wasted class
        score += (pr as f64) * 0.12;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate: opening a bin is expensive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 20.0;
        score += 90.0 + crowded * 10.0 - progress * 20.0;
        // small bins fit trivially anywhere; new bin less attractive
        if item_size <= bin_capacity / 4 {
            score += 25.0;
        }
    }

    // Prefer tighter fits: item filling a large fraction of the residual is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Slight preference for bins below mean residual (balance the pool).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit the smallest plausible next item
    // (interface allows items down to size 1).
    if post_residual > 0 && post_residual < next_item_size as f64 {
        score += 15.0;
    }
    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (i.e., favor filling existing bins) by penalizing the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mild bonus for bins already below mean residual (consolidating slack).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Lookahead: favor bins where the leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        // Bonus grows as the pair leaves little dead space.
        score -= 60.0 + (leftover_after_next as f64).min(60.0);
        // Extra reward for a perfect two-item chain.
        if leftover_after_next == 0 {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving post_residual that is too small for the next item (dead space).
        let waste = post_residual as f64;
        score += 0.5 * waste;
        // Harsher penalty for classic trap residuals (e.g. 51..=99 unusable for medium items).
        if post_residual >= 40 && post_residual <= 99 && next_item_size > post_residual {
            score += 40.0;
        }
    }

    // Compare fit quality relative to mean residual across open bins.
    if post_residual as f64 > mean_residual + 15.0 {
        score += 15.0; // this bin would remain unusually full-ish... penalize loose fits
    } else if (post_residual as f64) < mean_residual {
        score -= 10.0; // tighter than average: good compaction
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit in any open bin would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count == 0;
        let bad_fit_everywhere = fitting_bins_count == 0;
        let lookahead_needs_space = next_item_size > 0 && next_item_size > 60;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if crowded || bad_fit_everywhere {
            score -= 300.0;
        } else if lookahead_needs_space && post_residual >= 80 {
            score -= 50.0;
        } else {
            // Mildly discourage spreading out early; allow later when many bins open.
            score += 80.0 - 40.0 * progress;
        }
    }

    // Slight preference for bins that are already partially filled (compact usage).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post-residual).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize large wasted residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Penalize creating residual that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            // Next item won't fit here; mild penalty if we waste space anyway.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // or too many bins already open relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 55.0 + 10.0 * (1.0 - progress) };
        score = 45.0 + mean_residual * 0.3 + scarcity;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // new bin will pair well with next item
        }
        if post_residual <= 20 {
            score -= 20.0; // item nearly fills a fresh bin
        }
    }

    // Mild penalty for scattering across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Time-varying tightness pressure: as stream progresses, prefer fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker toward bins below mean residual (balancing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fits preferred (low post residual), with smooth non-linear shaping
    let mut score = pr.powf(1.3);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; late in the stream demand tight packing
    let tightness = 1.0 + 2.0 * progress * progress;
    score += 40.0 * tightness * norm_pr * norm_pr;

    // Reward using bins that are already "committed" (residual far below mean)
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 15.0 * mean_gap;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that neither fits nor matches next item;
    // reward residuals that exactly accommodate the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 10.0;
        }
    }

    // Penalize excessive bin proliferation early
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    // Slight penalty for new empty bin candidate unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 20.0 * norm_pr * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward post_residuals divisible by common small sizes
    let pr = post_residual;
    if pr >= 10 && pr % 10 == 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 {
        score -= 5.0;
    }

    // Penalize awkward dead space (small but nonzero residuals)
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr < 20 {
        score += 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 500.0;
    } else if next_item_size > 0 && pr >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size > pr {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0;
        // But opening a new bin is good late in the stream or when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
    }

    // Prefer tighter bins overall (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Slight pull toward mean residual to keep balance
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (post_residual near zero).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.2;
        } else {
            // Post residual cannot host next item: penalize proportional to dead space.
            score += post_residual as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage scattering across many bins,
    // but slightly favor filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate handling: empty bin gets residual == capacity.
    // Make it attractive only when the fit is good (item large) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - post_residual as f64 / bin_capacity as f64;
        // Penalize new bin when existing bins could fit well; reward when item is big.
        score += 30.0 * (1.0 - fit_quality) - 20.0 * fit_quality * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 - gap.min(100.0);
        } else {
            // Next item won't fit here; penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let tight_fit = fitting_bins_count <= 1;
        let fragmentation = mean_residual / bin_capacity as f64;
        if tight_fit || fragmentation < 0.25 {
            score -= 30.0;
        } else {
            score += 50.0 + fragmentation * 100.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits the post residual, reward this bin strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // next item won't chain here; penalize proportionally to wasted chain potential
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    } else {
        // last item: prefer fullest packing
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is crowded
    if bin_residual == bin_capacity {
        // opening new bin is neutral baseline; slightly penalize so tight fits win,
        // but reward opening when open bins are fragmented (high mean residual spread)
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 8.0 - fragmentation.min(8.0);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Time horizon: early in stream, be pickier about fragmentation (long future);
    // late in stream, just close bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pickiness = 1.0 - progress;
    score += pickiness * 0.15 * post_residual as f64;

    // Prefer keeping many open bins balanced vs concentrating: if this bin's residual
    // is far below mean, it's a good filler; penalize if above mean (bad target).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.08 * residual_diff;

    // Mild penalty for very empty existing bins being consumed too eagerly
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;
    // Smooth polynomial coupling: normalized post-residual shaped by stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let shape = 1.0 + 0.6 * progress * (1.0 - pr) * pr;
    score *= shape;
    // Penalize tight fits that leave dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);
    // Reward using a last-chance bin (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }
    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0;
    }
    // Slight preference for compacting into fewer bins late in the stream
    score += 0.02 * open_bins_count as f64 * pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Modulo-10 harmonic classes: small residues in {0,1,2,5} are classic "usable" gaps.
    let m = post_residual % 10;
    match m {
        0 => score -= 60.0,
        1 | 2 => score -= 30.0,
        5 => score -= 20.0,
        9 => score += 25.0,
        _ => {}
    }

    // Integer-division thresholds: dead space bands.
    let q = post_residual / 10;
    if q >= 1 && q <= 2 {
        score += 15.0 * q as f64; // small-medium gaps are wasteful
    } else if q >= 6 {
        score -= 10.0 * q as f64; // large gaps still reusable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / 20.0).max(0.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 30.0; // next item can't use this gap
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        if post_residual > 40 {
            score -= 40.0;
        }
    }

    // Progress-aware pressure: late in stream, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Prefer bins below mean residual (keeps bins balanced).
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) but awkwardly small are heavily penalized.
    // Small unusable gaps (post_residual in 1..=9) are "dead space".
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0;
    } else if post_residual > 9 && post_residual <= 15 {
        score += 6.0; // risky gap: only tiny items could reuse it
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 15.0 - slack;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this leftover: mild penalty proportional to gap
        score += 3.0;
    }

    // Open-bins pressure: discourage scattering across many open bins
    // unless the fit is good. Mild additive term scaled by bin count.
    score += (open_bins_count as f64) * 0.35;

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., closer to being filled) when this bin is tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high; add a fixed premium so it only wins when
    // all open bins offer poor fits (large residuals / dead space).
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large relative to capacity, opening fresh
        // may be preferable to fragmenting a partially filled bin.
        if (item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt == pr {
            score -= 500.0; // perfect chain: item + next item fills bin
        } else if nxt <= pr {
            // next item fits: reward proportionally to how well it chains
            let chain_quality = 1.0 - ((pr - nxt) / bin_capacity as f64);
            score -= 60.0 + 120.0 * chain_quality;
        } else {
            // next item won't fit here; penalize leaving a gap smaller than next item
            let gap = pr;
            if gap > 0.0 && gap < nxt {
                score += 0.5 * (nxt - gap);
            }
        }
    }

    // Compare residual against mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Acceptable to open a new bin when mean residual is small (bins are full-ish)
        score = 30.0 - 25.0 * crowding + 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 {
            // new empty bin can always chain with next item
            score -= 5.0;
        }
        // discourage new bin if a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity as f64 - mean_residual).abs();
            if best_possible < 20.0 {
                score += 20.0;
            }
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score -= 4.0; // still fillable by small items
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 3.0; // creates stranded space relative to lookahead
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residuals) or many bins are open.
    if bin_residual == bin_capacity {
        let new_bin_base = item_size as f64 + 20.0;
        let scarcity_penalty = if fitting_bins_count == 0 { 0.0 } else { 15.0 + 3.0 * fitting_bins_count as f64 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = new_bin_base + scarcity_penalty - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // fresh bin pairs well with next item
        }
    }

    // Mild preference to consolidate into bins with below-average residual
    // (keeps a few "large-residual" bins available for big future items).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Late-stream urgency: as the stream ends, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Dead-space penalty: residual too small to ever be useful (min item size 1,
    // but penalize very small residuals non-linearly)
    let small = (1.0 - pr / cap).max(0.0);
    score += 8.0 * small * small * small;

    // Smooth coupling with stream progress: early on, keep bins flexible
    // (penalize low post_residual less as stream ends -> prefer tight packing late)
    let flexibility = (1.0 - progress).powi(2);
    score += flexibility * (pr / cap) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize wasting residual
        score += 3.0 * (pr / cap) * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Penalize opening new bins; stronger early and when many bins fit
        score = cap + 20.0 + 30.0 * (1.0 - progress) + 5.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
    }

    // Mild preference for bins below mean residual (balance load smoothly)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead space is exponentially worse.
    let class = post_residual / 10;
    let dead_penalty = match class {
        0 => 60.0,                       // 0-9: nearly perfect fit, reward heavily
        1 => 12.0,                       // 10-19
        2 => 6.0,                        // 20-29
        3 => 3.0,                        // 30-39
        4 => 1.0,                        // 40-49
        5 => 0.5,                        // 50-59
        6 => 0.25,                       // 60-69
        7 => 0.1,                        // 70-79
        8 => 0.05,                       // 80-89
        _ => 0.0,                        // 90-100: fresh bin
    };
    score += dead_penalty;

    // Reward exact-fit modularity: post residual divisible by common item sizes
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this space; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Fresh-bin candidate handling: neutral-ish, but prefer it over terrible fits
    if bin_residual == bin_capacity {
        score -= 5.0;
        // discourage opening new bins when mean residual across open bins is still large
        score += mean_residual * 0.15;
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.05;

    // Prefer bins whose residual is below the mean (tighter bins get used first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: small gaps that no future item
    // (sizes >= 1, but practically small) can fill are wasted capacity.
    if post_residual > 0 {
        // Dead-space penalty grows as the gap shrinks below the smallest
        // practically usable size; a gap of 0 is perfect (best fit).
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += dead * dead * 1.5;
    } else {
        // Perfect fit: reward heavily.
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if the next item would be blocked by this placement's leftover.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: prefer spreading across already-open bins when many
    // are open, to avoid unbounded bin proliferation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.35 + 0.25 * progress);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to the bin or few bins are open; otherwise prefer
    // filling existing bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let openness = open_bins_count as f64;
        // Large items early, or when mean residual across bins is small,
        // justify opening a fresh bin.
        score -= fill_ratio * 30.0;
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        score += openness * 2.0;
        // Slight late-stream preference to consolidate rather than open bins.
        score += progress * 12.0;
    }

    // Mild preference for bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    // Prefer bins with below-average residual (fill the emptiest usable bins
    // first keeps more medium gaps available).
    let avg_gap = (mean_residual - post_residual as f64).abs();
    score += avg_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: leave exactly the next item's size.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here; small reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.15;
        } else {
            // Next item won't fit after this placement; penalize dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Tight fit reward relative to current residual (classic best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Penalize bins far above the mean residual (wasteful pick) but reward below-mean fits.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.08;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Discourage opening new bins early in the stream when open bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core with superlinear penalty).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.5) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small dead space below the minimum item size is nearly free.
        score -= 6.0;
    }

    // Penalize leaving a residual that the next item cannot use (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that can host the next item, scaled by slack.
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space for the lookahead item: penalize more if gap is small-but-unusable.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 + 8.0 * (gap / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit. Make the empty bin slightly less attractive
    // than a good existing fit, but attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // As the stream progresses, avoid proliferation of bins with tiny residuals.
        let crowding = open_bins_count as f64 * 0.4;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        let mean_r = mean_residual;
        let new_bin_penalty = 30.0 + crowding + 20.0 * progress - (mean_r / bin_capacity as f64) * 15.0;
        // If the item is large relative to capacity, new bin is more tempting.
        let size_pull = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += new_bin_penalty - size_pull;
    }

    // Mild preference for filling bins with larger residuals when many bins are open
    // (consolidation pressure), to reduce fragmentation.
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64) * 0.3;

    // Slight time-decay: early in the stream, be more conservative (keep bins tidy);
    // later, prioritize just fitting the item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear coupling: penalize both large wasted space and tiny unusable slivers
    let waste_penalty = x * x * (1.0 + t) * 40.0;
    let sliver_penalty = (1.0 - x) * (1.0 - x) * (1.0 - t) * 15.0;
    score += waste_penalty + sliver_penalty;

    // Perfect fit reward, stronger later in the stream
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit * fit * (0.5 + t) * 30.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 0.5 {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mean residual coupling: prefer bins close to mean (balance), smooth term
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: penalize opening new bins mildly, less so late in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // in terms of common item-size quantum classes (multiples of 10 and 5).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic residue classes of post_residual modulo 10 / 5.
        let class10 = (post_residual % 10) as f64;
        let class5 = (post_residual % 5) as f64;
        // Leftovers that align to quantum boundaries are more reusable.
        score -= (10.0 - class10) * 2.0;
        score -= (5.0 - class5) * 1.0;

        // Dead-space penalty: residuals too small for the minimum item (1..100 range,
        // use a soft threshold around 10% of capacity).
        let dead_threshold = cap * 0.1;
        if post < dead_threshold {
            score += (dead_threshold - post) * 3.0;
        }

        // Harmonic fraction of the bin filled: reward filling past half, three-quarters.
        let fill = (bin_residual as f64) / cap;
        if fill > 0.75 {
            score -= 20.0 * (fill - 0.75);
        } else if fill > 0.5 {
            score -= 8.0 * (fill - 0.5);
        }

        // Lookahead harmonic coupling: if next item fits exactly in post_residual
        // (harmonic complement), strongly favor this bin.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size < post_residual {
                let next_post = post_residual - next_item_size;
                // Reward chains where next placement also lands on a quantum class.
                if next_post % 10 == 0 || next_post == 0 {
                    score -= 60.0;
                }
                score -= (post - next_item_size as f64) * 0.5;
            } else {
                // Next item cannot follow here: mild penalty scaled by overflow.
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }

        // Last-chance bin: strongly prefer using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Prefer filling existing bins when many are open (bin-count pressure).
        score -= open_bins_count as f64 * 0.5;

        // Early in the stream, be slightly more willing to spread (keep flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;

        // Mean residual coupling: if this bin is below-average residual (more full),
        // favor it (best-fit flavor with harmonic offset).
        score += (mean_residual - (bin_residual as f64)) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item * 10.0 {
        score += 60.0; // unusable sliver
    } else if pr > 0.0 && pr < min_item * 25.0 {
        score += 25.0; // hard-to-fill gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n && pr - n < 10.0 {
            score -= 30.0; // next item fits snugly
        } else if pr >= n {
            score -= 10.0;
        } else if pr > 0.0 {
            score += 15.0; // blocks the lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure from number of open bins: encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 - 25.0 * progress; // new bin less attractive later on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // 2-step lookahead: if the NEXT item fits perfectly into the post residual,
    // this placement chains into a near-perfect packing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 200.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // post residual is dead space for the next item; penalize proportionally
            score += (post_residual as f64) * 0.5;
        }
        // Bonus if next item can't fit anywhere else and this bin's post residual can host it
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 100.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual
    // is close to the mean (keeps bins homogeneous, easier future matches).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // typical residuals or open bins are all poor fits.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) > mean_residual + 20.0;
        if tight {
            score -= 150.0;
        } else {
            score += 120.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Early in stream: encourage opening fresh bins for large items to build
    // diverse residual structure; late in stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && item_size >= 50 && bin_residual == bin_capacity {
        score -= 80.0;
    } else if progress > 0.8 {
        score += 0.2 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively later in the stream.
    score -= (100.0 - post_residual as f64) * (0.35 + 0.65 * progress) * 0.5;

    // Penalize dead space: post residuals that no plausible item (1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (1.0 - progress); // early dead space less costly
    }

    // Lookahead coupling: if the next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 50.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate logic: open a fresh bin when the fit is loose or residual
    // is large but future items may need it; keep it cheap only when justified.
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items (poor packing into partials) early on,
        // and when existing bins are crowded (few fitting alternatives).
        let crowd = 1.0 / (1.0 + fitting_bins_count as f64);
        score = 90.0 * fit_ratio + 30.0 * crowd + 20.0 * progress;
        if fitting_bins_count == 0 {
            score = -1000.0; // no open bin fits: must open
        }
        // Late in stream, discourage opening new bins to consolidate.
        score += 30.0 * progress;
    } else {
        // Mild penalty proportional to how "wasteful" the placement is vs mean residual.
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 15.0 * waste * (1.0 - progress);
        // Prefer bins with residuals close to mean (balance the pool).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Small bonus for using bins with many alternatives less often.
        score += 2.0 * (fitting_bins_count.min(10) as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = r / cap; // normalized post residual

    // Smooth polynomial coupling of residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 0.35 * x * x - 0.15 * x * x * x * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 0.5 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item, penalize near-miss residuals
    if next_item_size > 0 {
        let n = next_item_size as f64 / cap;
        let gap = (x - n).abs();
        score -= 0.6 * (1.0 - gap).clamp(0.0, 1.0);
        score += 0.4 * if x < n && x > 0.0 { (n - x) } else { 0.0 };
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Mildly discourage hoarding many open bins with scattered residuals
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * x;
    score += 0.1 * (x - mean_residual / cap).abs();

    // New-bin candidate: neutral-ish baseline so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 1.2 - 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 buckets
    let r = post_residual % 10;
    // Dead-space penalty: residuals that are small but nonzero are the worst
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else {
        // reward "perfect" residuals (zero or exactly matching common item classes)
        if post_residual == 0 {
            score -= 30.0;
        }
        // residual classes matching typical item sizes (multiples of 10)
        if r == 0 {
            score -= 8.0;
        } else if r >= 7 {
            score += 5.0; // awkward sliver
        }
    }

    // Harmonic coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else if slack < 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's residual: penalize proportionally
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.05;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin if existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin scales with how many bins are already open
        score = 60.0 + (open_bins_count as f64) * 2.0;
        if post_residual >= 50 {
            score -= 10.0; // a fresh bin leaves roomy residual for future items
        }
        if next_item_size > 0 && next_item_size >= 50 && item_size <= 50 {
            score -= 15.0; // big item coming: fresh bin is attractive
        }
    }

    // Progress-based mild tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    // Prefer bins whose residual is close to mean (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item are "dead space" -> heavy penalty.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on very small gaps (waste zone 1..15).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (good fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item cannot use the leftover: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // plenty of alternatives exist; encourage filling when few bins fit.
    score += open_bins_count as f64 * 0.8;

    if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 70.0;
    } else if fitting_bins_count > 4 {
        // Many options: be pickier about residual quality.
        score += post_residual as f64 * 0.25;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 20.0 * progress;

        // If the item perfectly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 200.0;
        }

        // If only one bin fits the item elsewhere, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 80.0;
        }

        // Lookahead: if next item could join this item in the fresh bin,
        // opening becomes more attractive.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // Reward closeness of post_residual to next_item_size (lookahead matching).
            score -= 25.0 / (1.0 + diff * 0.15);
            // Penalize leaving residual that next item cannot use at all.
            if post_residual < next_item_size {
                score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Penalize creating unusable dead space (residual below minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins tighter than average (relative to mean residual).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Progress-based tuning: later in the stream, be more conservative about residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Slight penalty when many bins are open, encouraging consolidation.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && (post_residual < 10 || !good_lookahead) {
            // discourage opening a new bin when a reasonable fit exists
            score += 30.0;
        } else if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that is hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine if truly tiny
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.35 * (post_residual as f64 - 10.0); // awkward zone
    }

    // Lookahead: if the next item fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.15 * next_item_size as f64;
        } else {
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.10 * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.9;
        if fitting_bins_count == 0 || (poor_fit_elsewhere && mean_residual < 25.0) {
            score -= 40.0; // justified opening
        } else {
            score += 45.0 + 20.0 * progress; // discourage waste, more so late in stream
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score += 0.05 * open_bins_count as f64 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.01;

    // Reward using bins whose residual is close to item size (good coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: strongly favor small post_residual (non-linear).
    score += 0.6 * (pr / cap) * (pr / cap) * cap;

    // Penalize wasting a nearly-full bin's scarcity; reward using it now.
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 12.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).sqrt();
    }

    // Smooth interaction: residual vs. stream progress — later in stream, prefer
    // compacting into existing bins rather than spreading.
    score += 8.0 * progress * (pr / cap) * cap * 0.1;

    // Penalize bins whose residual deviates far above mean (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is bad unless it's early or no good fit exists.
        let waste = pr / cap; // residual left after placing in fresh bin
        score += 18.0 * (1.0 - progress) + 10.0 * (1.0 - waste);
        // If item nearly fills a fresh bin, opening is fine.
        score -= 20.0 * (item_size as f64 / cap).powi(3);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        } else {
            // Leaving a residual that nothing typical fits: dead-space penalty.
            score += 4.0 * (pr / cap) * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that fall into "awkward" harmonic bands (just above small-item sizes)
    let awkward = |r: u32| -> f64 {
        let mut pen = 0.0;
        for k in 1..=8u32 {
            let t = k * 12; // harmonic grid on capacity 100
            if r > t && r <= t + 4 {
                pen += 6.0 * (1.0 - (r - t) as f64 / 5.0);
            }
        }
        pen
    };
    score += awkward(post_residual);

    // Reward tight fits strongly (near-perfect packing)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with lookahead item: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 12.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // next item can't use the leftover: penalize proportionally to wasted space
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, discouraged unless current fit is bad
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64 - 0.3 * mean_residual;
        if next_item_size > 0 && item_size <= 50 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // fresh bin can host item+next: attractive
        }
    }

    // Modulo-class bonus: prefer residuals that are multiples of common item classes
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // Late in the stream: consolidate harder, discourage leaving many open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - frac);

    // Mild bonus for bins below mean residual (fill emptier bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are heavily penalized (wasted capacity).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Gap too small for the next item: mild dead-space penalty.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // (mean residual low) or the fit here would be very poor.
    if bin_residual == bin_capacity {
        score = 100.0
            - mean_residual * 0.8
            + open_bins_count as f64 * 2.0
            - (bin_residual - item_size) as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        }
    } else {
        // Prefer bins with larger residual when fits are comparable,
        // but temper with open-bin pressure to avoid bin proliferation.
        score -= bin_residual as f64 * 0.05;
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact 2-chain match
        } else if next_item_size < post_residual {
            // scale reward by how much of the residual the next item consumes
            let consumed_ratio = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * consumed_ratio;
        } else {
            // next item cannot use this residual: penalize leaving dead space
            let waste = post_residual as f64;
            let dead = if next_item_size > 0 && next_item_size > waste { 1.0 } else { 0.0 };
            score += 30.0 * dead * (waste / 10.0);
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with less residual than average (tighter bins fill first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables
    // an exact chain with the next item or few bins fit the item.
    if bin_residual == bin_capacity {
        let mut penalty = 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 80.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            penalty = -50.0; // no open bin fits: new bin is required
        }
        score += penalty;
    }

    // Mild progression term: later in the stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual, with quadratic shaping.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill:
    // residuals smaller than the smallest plausible item (1..100 range) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / (bin_capacity as f64));
        } else {
            // Post-residual cannot host next item: mild penalty scaled by wasted fraction.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    } else {
        // Last item: any residual is dead weight, so fill as much as possible.
        score += 25.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Cheaper to open a new bin when many bins are already open and fragmented.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is small (fragmented state), new bin is fine.
        score -= 0.1 * mean_residual;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If item would leave a big hole in any existing bin, new bin looks better.
        if post_residual > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Mild penalty for using an already-open bin proportional to how full it is,
        // encouraging balanced residual distribution.
        score += 0.05 * ((bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64);
    }

    // Global pressure: when open bins are nearly exhausted on average, be greedy
    // about filling them tightly.
    if mean_residual < 20.0 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - mean_residual / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified as stream progresses
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.1 + pr * 0.5;

    // Smooth coupling: residual vs item size ratio interaction
    let fit_ratio = it / (bin_residual as f64).max(1.0);
    score -= fit_ratio * fit_ratio * 40.0 * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual too small for next item, reward exact chains
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - (gap / cap).powf(2.0));
        } else {
            score += (-gap / cap).powf(1.5) * 30.0;
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 3.0 / (1.0 + open_bins_count as f64);

    // Mean residual alignment: prefer bins near mean (keeps spread usable)
    score += ((pr as f64 - mean_residual).abs() / cap) * 15.0 * (0.5 + progress);

    // New-bin candidate: only attractive when existing bins would waste badly
    if bin_residual == bin_capacity {
        score = 120.0 + pr * 0.3 - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    // capture "nice" leftover sizes that pair well with common item sizes.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -50.0 // perfect fit, strongly favored
    } else if pr < 10 {
        25.0 // tiny dead space, nearly useless
    } else {
        match pr % 10 {
            0 => -12.0, // round residual, very reusable
            5 => -6.0,  // half-class, moderately reusable
            2 | 4 | 6 | 8 => -2.0,
            _ => 4.0,   // odd residues pair worse
        }
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual vs next item lookahead
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportional to tightness of the chain
            let tightness = (next_item_size as f64) / (pr as f64);
            score -= 8.0 * tightness;
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0; // exact subdivision, harmonic match
            }
        } else {
            // Next item cannot use this residual: penalize large stranded space
            score += 0.05 * (pr as f64).powi(2) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh bin has residual == capacity.
    // Only prefer it when current residual creates bad dead space and
    // item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = (item_size as f64) / (bin_capacity as f64);
        // Opening a new bin is attractive when item is big and would leave
        // an awkward residual in existing bins.
        score = 40.0 - 30.0 * frac;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can also chain the next item
        }
        if fitting_bins_count > 2 {
            score += 8.0; // plenty of alternatives, keep bins consolidated
        }
    }

    // Late in stream: consolidate, penalize opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // item size (tight fit) relative to fleet state.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tight;
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // Slight preference to fill more-loaded bins (fewer partially open bins)
    score += 0.3 * open_bins_count as f64 * 0.01 * (bin_capacity - bin_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small non-zero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post-residual that can still host the next item is favored.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain fit: item + next item exactly fills
        } else if post_residual >= next_item_size {
            // reward tight-but-feasible leftovers for the next item
            score -= 200.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, more if very small
            let dead = post_residual as f64;
            score += 150.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Tightness relative to current residual: prefer minimal waste now
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 80.0 * tightness;

    // Compare against mean residual: filling a bin far below mean residual wastes capacity
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Late in the stream: consolidate, avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 60.0 + 120.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space quadratically (dead space grows worse).
    let mut score = post * post / cap;

    // Reward tight fits: small post_residual relative to item size.
    score -= 12.0 * (item / (post + 1.0)).min(3.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize leaving residuals that are unlikely usable later:
    // small post_residuals (< 10) are nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 18.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here; slight penalty scaled by gap
            score += 4.0 * ((nxt - post) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item wastes least relative to others
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let mean_resid_gap = (mean_residual - post).abs();
    score += 0.05 * mean_resid_gap;
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post / cap);

    // New-bin candidate handling: empty bin (residual == capacity).
    // Opening new bin is only attractive when item fits existing bins terribly
    // (huge post_residual) or no real competition exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress; // default: discourage opening new bins
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if post_residual < 15 {
            score -= 20.0; // item nearly fills a fresh bin alone
        }
    }

    // Late stream: consolidate harder, avoid waste.
    score += 10.0 * progress * (post / cap);

    // Mild noise-free tiebreaker: prefer fuller bins.
    score -= 0.1 * (resid - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with capacity norm
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap * (0.5 + progress);

    // Interaction of post_residual with mean residual: penalize bins whose leftover
    // deviates upward from the fleet mean (fragmentation signal)
    let dev = pr - mean_residual;
    score += 0.35 * dev * dev / (1.0 + mean_residual);

    // Reward tight fits (smooth, saturating)
    score -= 18.0 * (1.0 - pr_norm).exp() * (item_size as f64 / cap);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits into post_residual (chained fit)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Penalize opening new bins when many open bins can still fit the item
    if bin_residual == bin_capacity {
        let f = fitting_bins_count as f64;
        score += 6.0 + 3.0 * f + 8.0 * (1.0 - progress) * (1.0 + open_bins_count as f64 * 0.05);
    } else {
        // Slight preference for fuller bins among open candidates
        score -= 3.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Smooth progress-driven tightening: later in stream, demand better fits
    score += 6.0 * progress * pr_norm * (1.0 - pr_norm) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: modulo classes on capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
    let pr_class = pr % quarter;
    let pr_div = pr / quarter;

    // Reward residuals that land in "usable" harmonic classes (multiples of 1/8 capacity).
    if pr % eighth == 0 && pr > 0 {
        score -= 12.0;
    }
    // Penalize dead space in the awkward 1..quarter band (too small for typical items).
    if pr > 0 && pr < eighth {
        score += 18.0;
    }
    if pr > eighth && pr < quarter {
        score += 7.0;
    }

    // Coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how snugly the next item nests.
            let snug = (pr - next_item_size) as f64;
            score -= 10.0 + 20.0 * (1.0 - snug / bin_capacity as f64);
            // Extra reward if next item also lands on a harmonic class boundary.
            if (pr - next_item_size) % eighth == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit: penalize more if residual is just barely too small.
            let gap = (next_item_size - pr) as f64;
            score += 8.0 + 0.4 * gap;
        }
    } else {
        // Last item: prefer tightest fit overall, dead space harmless.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: prefer the tightest, add mild pressure scaled by count.
    if fitting_bins_count > 1 {
        score += 0.8 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin is a good harmonic match.
    if bin_residual == bin_capacity {
        let good_open = mean_residual >= item_size as f64 * 1.15;
        if good_open && open_bins_count > 0 {
            score += 30.0; // keep using open bins
        } else if open_bins_count == 0 {
            score -= 5.0;
        } else {
            // Mean residual too small to be useful: opening fresh is fine.
            score -= 10.0 + mean_residual * 0.1;
        }
    }

    // Stream progression: early on, consolidate aggressively; late, tolerate new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Integer-division threshold bonus: residual in top harmonic band is prime space.
    if pr_div == 0 && pr > 0 {
        score += 5.0;
    } else if pr_div >= 2 {
        score -= 4.0 * (pr_div as f64 - 1.0).min(3.0);
    }

    // Mild tie-break toward bins whose residual deviates from the mean (specialization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: strict dead-space avoidance. Gaps too small to hold even the
    // smallest plausible item are "dead" — penalize them hard.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: massive reward.
        score -= 120.0;
    } else {
        // Diminishing utility of large residuals is fine, but reward
        // tight-but-usable fits quadratically.
        score -= (post_residual as f64).sqrt() * 3.0;
    }

    // Reward bins whose residual exactly matches the item (perfect fill).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            if post2 < dead_threshold {
                score += (dead_threshold - post2) as f64 * 4.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item can't use the gap: mild penalty proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 40.0 + (open_bins_count as f64) * 6.0;
        // Opening is acceptable if mean residual across open bins is small
        // (they are all nearly full anyway).
        score -= mean_residual * 0.5;
        // Late in the stream, slightly prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (tighter bins get used first, preserving slack in others).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
