            // reward proportional to how well next item fills the leftover
            score -= 200.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit: penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual matching: prefer bins whose residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin early in the stream when open bins could fit
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * (step_index as f64 / (total_items.max(1) as f64)).min(1.0);
        // allow new bin if item is huge and would leave unusable space in others
        if item_size as f64 > 0.8 * bin_capacity as f64 {
