}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual reusable by lookahead -> reward
            score -= 12.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        } else if post_residual > 0 {
            // dead space: penalize more when close-but-unusable
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - gap / item_size.max(1) as f64).max(0.0);
        }
    } else {
        // last item: just minimize waste
        score += 5.0 * fit_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well. Base penalty for opening when alternatives exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_penalty = 30.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            // if some open bin fits, opening is worse the better that fit is
            open_penalty += 15.0;
        }
        // with few open bins, keeping bins tight matters less
        if open_bins_count <= 2 {
            open_penalty -= 10.0;
        }
        // mean residual high => open bins have room, avoid new bin
        open_penalty += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        score += open_penalty;
    } else {
        // Prefer filling bins that are already partially used (fewer bins overall).
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * used;

        // Slight preference for bins whose residual is below mean (tight bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Mild time-decay: later in the stream, waste matters relatively more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
