    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - prn) * (nxt / cap);
        } else {
            score += 1.5 * (prn - nxt / cap).abs();
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize opening a new bin when open bins have plenty of room
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 8.0 + 4.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mild preference for fuller bins as stream progresses
    score -= 2.0 * progress * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (divisible into common item sizes), penalize awkward dead space.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongest reward.
        score -= 60.0;
    } else if pr <= 10 {
        // Very small dead space, nearly perfect.
        score -= 40.0;
    } else {
        // Class by capacity fraction: residuals near multiples of common sizes
        // (e.g. 20, 25, 50) remain reusable.
        let frac = post / cap;
        if (pr % 10 == 0) {
            score -= 12.0; // reusable in 10-steps
        }
        if (pr % 20 == 0) {
            score -= 6.0;
        }
        if (pr % 25 == 0 || pr % 50 == 0) {
            score -= 5.0;
        }
        // Penalize residuals in awkward mid-range (just above small items)
        if pr > 10 && pr < 20 {
            score += 8.0;
        }
        // Large leftover fraction is fine (bin stays flexible)
        if frac > 0.5 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / cap)).max(0.0);
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty if leftover is small
            if pr < 10 {
                score += 3.0;
            }
        }
    } else {
        // Last item: prefer zero waste.
        score -= (cap - post) * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if pressure < 0.15 && open_bins_count > 0 {
            // open bins nearly full: opening fresh bin is reasonable
            score -= 15.0;
        } else {
            score += 20.0; // prefer filling existing bins
        }
        // Late in the stream, discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for many open bins already (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min size 1, but practically small gaps <= 10)
    // are pure waste. Penalize them superlinearly.
    if post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual < 25 {
        // Moderately awkward gaps: quadratic penalty as they shrink.
        score += ((25.0 - post_residual as f64) / 15.0).powi(2) * 8.0;
    } else {
        // Larger usable gaps are mildly rewarded relative to raw residual.
        score -= 6.0;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else if next_item_size <= post_residual + 10 {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // as open_bins_count grows, mildly discourage stuffing more into many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins.
        score += 30.0 + open_bins_count as f64 * 2.5 + progress * 10.0;
        // A new bin is more attractive if existing mean residual is tiny
        // (existing bins are nearly full anyway).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    } else {
        // Slight reward for consolidating into fewer bins early on.
        score -= (bin_capacity as f64 - mean_residual.max(1.0)) * 0.05;
    }

    // Prefer using bins with larger current residual for big items (tight packing).
    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item gets a big bonus; near matches get graded bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // Next item still fits after this placement: mild reward scaled by closeness.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item would not fit: penalize proportionally to leftover waste.
            score += 10.0 + diff * 0.3;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin leaves unusable sliver.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless fit is terrible.
        score += 15.0;
        // If item leaves a small unusable gap in an existing bin, opening is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual as i64 >= next_item_size as i64 {
            score -= 10.0; // fresh bin can serve the next item too.
        }
    }

    // Slight preference for consolidating when many bins are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 1.5;
    }

    // Late in stream: waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, but only when it is truly unusable
    // relative to the smallest plausible item (1).
    if post_residual > 0 {
        score += (post_residual as f64).sqrt() * 1.5;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tight = next_item_size as f64 / post_residual as f64;
        score -= 6.0 + 8.0 * next_tight;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the lookahead item cannot use: mild penalty.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is
    // large relative to capacity (good utilization of fresh space) or when existing
    // fits are very loose.
    if bin_residual == bin_capacity {
        let utilization = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by how well the item fills it.
        score = 55.0 - 40.0 * utilization;
        // Early in the stream, be more willing to open bins (flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        score += 0.6 * open_bins_count as f64;
        // If mean residual of open bins is large, a new bin is wasteful.
        score += 0.15 * mean_residual;
        // If lookahead item is big, fresh bin may serve both items.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Slight preference for placing into bins that are already below average residual
    // (keeps a subset of bins tight, leaving others flexible).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 + p * p) * cap;
    score += 0.35 * coupling;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + p) * 12.0;

    // Penalize opening a new bin when existing bins fit, especially late
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0 + 20.0 * p;
        }
        score += open_bins_count as f64 * 0.5;
    } else {
        // Last-chance bonus: prefer using the only bin that fits
        if fitting_bins_count <= 1 {
            score -= 15.0 + 10.0 * p;
        }
    }

    // Lookahead: favor bins whose post_residual can hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for deviating from mean residual (keeps balance)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands in "useful"
    // residue classes (multiples of small sizes) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr <= 10 {
        12.0 // dead space: unusable for min-size items
    } else {
        0.0
    };
    score += class_bonus;

    // Fractional capacity coupling: reward leaving residual that pairs with
    // typical item sizes (quarter/third/half fractions of capacity).
    let frac = pr as f64 / cap;
    if (frac - 0.25).abs() < 0.02 || (frac - 0.5).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
        score -= 5.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > pr && next_item_size > 0 {
        score += 6.0; // next item won't fit here anyway
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - item_size as f64).abs();
        let penalty = if fitting_bins_count == 0 {
            -40.0 // must open
        } else if spread > cap * 0.4 {
            -2.0 // poor fits elsewhere, new bin ok
        } else {
            25.0 + open_bins_count as f64 * 2.0
        };
        score += penalty;
    }

    // Late-stream tightening: prefer tighter fills as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * 10.0 * progress;

    // Prefer bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that can also fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item.
        score += 10.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let post = post_residual as u32;
        if next_item_size == post {
            // Chain perfect fit: extremely desirable.
            score -= 500.0;
        } else if next_item_size <= post {
            // Next item fits; reward proportional to how snugly.
            let slack = (post - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
        } else {
            // Next item won't fit: penalize small dead space more than large.
            let waste = (next_item_size - post) as f64;
            score += waste * waste * 0.05 + 30.0;
        }
    }

    // Reward tight fits relative to bin capacity (small post_residual fraction).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 50.0;

    // Compare against mean residual across open bins: prefer bins with below-mean residual
    // (fill the fullest bins first), penalize placing into already-large-residual bins.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin unattractive unless the item is large
    // relative to typical residuals or nothing else fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 400.0;
        // Large items are hard to place later; if item is big, opening fresh space is OK.
        new_bin_score -= (item_size as f64 - 50.0).max(0.0) * 4.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 200.0;
        // If many bins are open already, discourage adding more.
        new_bin_score += open_bins_count as f64 * 10.0;
        // If mean residual across open bins can't accommodate the item well, new bin is fine.
        if mean_residual < item_size as f64 {
            new_bin_score -= 250.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual that is hard to reuse later gets penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would need this bin's current space; placing here may be fine,
            // slight penalty if next item is large and post_residual too fragmented.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Prefer filling nearly-full bins over spreading load.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Time horizon: early in stream, be more conservative about dead space;
    // late in stream, favor closing out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += waste * (1.0 - progress) * 20.0;
    score -= progress * 10.0;

    // Global state: many open bins -> encourage consolidating into existing bins.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln();
        score += waste * pressure * 15.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good target.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no bin fits well (post_residual on empty bin = capacity - item_size).
    if bin_residual == bin_capacity {
        score += 70.0;
        // Allow new bin if item is huge and would leave reasonable residual elsewhere anyway.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in stream, prefer new bins less.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = pr.powf(1.5);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress + 3.0 * progress);
    score += coupling * cap;

    // Reward filling bins that are nearly full (small residual waste bonus).
    let tightness = (cap - pr) / cap;
    score -= 20.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.5 + progress);
        } else {
            // Reward leaving room exactly usable by the next item.
            let usable = 1.0 - ((pr - ns) / cap).powf(2.0);
            score -= 15.0 * usable * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Slight preference for bins with residuals close to mean residual
    // (keeps a balanced pool of bin sizes).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for spreading across too many open bins early.
    score += (open_bins_count as f64).powf(1.2) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod 10 and
    // capacity-fraction thresholds. Small "dead" residuals (1..=9) are
    // almost unusable for items >= 10, so penalize them heavily.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0;
    }

    // Reward leaving a residual that exactly fits the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward leaving residual that can host the next item at all.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here afterwards; slight penalty scaled by gap.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Integer-division threshold: classify post_residual by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter / 2 {
        score += 20.0; // tiny leftover: dead-space risk
    } else if post_residual <= quarter {
        score += 5.0;
    } else if post_residual <= 2 * quarter {
        score -= 6.0; // half-ish residual is versatile
    } else if post_residual <= 3 * quarter {
        score -= 10.0; // large residual: very reusable
    } else {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // (mean residual low) or the fit here is poor (large post_residual).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (bin_capacity as f64) * 0.25;
        let poor_fit = post_residual < 15;
        if crowded || poor_fit {
            score -= 25.0;
        } else {
            score += 15.0; // prefer packing into existing bins early on
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 {
            score -= 8.0;
        }
    }

    // Mild preference for fuller bins overall (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mean-residual coupling: bins below average residual are more "spent",
    // prefer filling them to keep the fleet balanced.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Modulo-10 harmonic: residuals that are multiples of 10 pair well with
    // the 10..80 item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size is pure waste
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else {
        // reward tight fits: shrink score as post_residual shrinks
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0; // sets up a future perfect fit
        } else {
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += 3.0 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64 * 10.0;

    // New-bin candidate handling: attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 40.0; // prefer using the last-chance open bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // large next item may prefer fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the leftover space can
    // exactly (or nearly) host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual >= next_item_size {
            // Next item fits here: strongly reward tightness of the match.
            score -= (cap - gap) * 0.9;
            if gap < 1.0 {
                score -= 40.0; // perfect 2-step pairing bonus
            }
        } else {
            // Leftover is dead space relative to the lookahead item.
            score += gap * 0.5;
        }
    }

    // Tight fit reward: prefer bins where the item leaves little slack.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Penalize bins whose residual is far below the mean residual
    // (i.e. already crowded bins) unless the fit is very tight.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (poor fit = large post_residual or item nearly fills a fresh bin badly).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // A fresh bin is good for large items; bad for tiny items.
        if fill_ratio > 0.7 {
            score -= 45.0;
        } else {
            score += 55.0 * (0.7 - fill_ratio);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to keep the number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    let tight = if bin_residual > 0 { post_residual as f64 / bin_residual as f64 } else { 1.0 };
    score += tight * 20.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chain packing),
    // penalize if post residual is a "dead zone" the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when post_residual in an existing bin would be very small anyway
    // or the new bin keeps large flexibility. Penalize opening new bins mildly,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the item is large, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out open bins rather than spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // leaving emptier bins for future large items.
    let mean_gap = mean_residual - bin_residual as f64;
    score -= mean_gap * 0.2;

    // Mild global pressure: when many bins are open, pack tighter.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: quadratic coupling of post_residual with progress
    let tight = 1.0 - (post / cap);
    score -= 18.0 * tight * tight * (0.5 + 0.5 * progress);

    // Penalize dead space that no plausible future item can use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.6 * gap;
        // Reward bins whose leftover exactly accommodates the lookahead item
        if post >= next_item_size as f64 {
            let match_quality = 1.0 - (post - next_item_size as f64) / cap;
            score -= 10.0 * match_quality * match_quality;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, less so early in the stream
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * progress;
    } else {
        // Prefer fuller bins among open ones; couple with mean residual
        score -= 4.0 * (1.0 - (bin_residual as f64 / cap)) * (mean_residual / cap);
        // Mild penalty for spreading across many open bins
        score += 0.15 * open_bins_count as f64 * progress;
    }

    // Smooth cubic waste penalty normalized by capacity
    let waste = post / cap;
    score += 8.0 * waste * waste * waste * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveals
    // how "composable" the leftover space is for future items (sizes 1..=100).
    let r = post_residual;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;
    let m50 = (r % 50) as f64;

    // Penalize residuals that are awkward classes (non-multiples of 10/25/50).
    score += (10.0 - m10) * 0.30;
    score += (25.0 - m25) * 0.15;
    score += (50.0 - m50) * 0.05;

    // Perfect fits are golden.
    if r == 0 {
        score -= 60.0;
    }

    // Dead-zone thresholds via integer division on post_residual.
    let q = r / 10; // harmonic decade class
    if q == 0 {
        score -= 25.0; // near-perfect packing
    } else if q == 1 {
        score += 8.0; // 10..19 leftover: often unusable
    } else if q == 2 {
        score += 14.0; // 20..29: medium-dead space
    } else if q >= 3 && q <= 5 {
        score -= 5.0; // 30..59: still useful for mid items
    }

    // Coupling with lookahead: if next item fits the post residual exactly
    // or nearly, strongly reward this bin.
    if next_item_size > 0 {
        let gap = (r as i64 - next_item_size as i64).unsigned_abs() as f64;
        if next_item_size as u32 <= r {
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 30.0; // perfect chaining
            }
        } else {
            // Next item cannot use this leftover; penalize proportional to waste.
            score += (next_item_size as f64 - r as f64).min(50.0) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is bad.
    if bin_residual == bin_capacity {
        // Brand-new bin: score = full capacity + penalties, so it only wins
        // when every open bin scores worse. Scale with stream progress and
        // current load of open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + 25.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits anywhere: must open
        }
        if mean_residual > item_size as f64 + 15.0 {
            score += 20.0; // open bins still have room; discourage new bin
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Small nudge: reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1,
    // realistically >= 10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: bonus grows as post_residual shrinks toward 0.
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading further.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly into this bin's post-residual,
    // reward; if post_residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 20.0; } else if slack < 10 { score += 15.0; }
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate: acceptable early, discouraged once many bins are open
    // unless it enables a very tight fit later (baseline residual = capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.8 * open_bins_count as f64;
        if fitting_bins_count == 0 { score -= 50.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent (chains two items perfectly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // Reward only if the chain leaves little dead space afterwards.
            score -= (post_residual as f64) * 0.5 - (leftover as f64) * 0.8;
        } else {
            // Next item cannot follow in this bin; penalize proportionally
            // to how much of the post residual is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.3;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose residual after
    // placement deviates favorably from the fleet mean.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        // Slightly below-mean residual = tighter packing, mild reward.
        if dev < 0.0 {
            score += dev * 20.0; // negative => subtract
        } else {
            score += dev * 10.0; // above-mean residual penalized mildly
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual < 10 {
            score -= 100.0;
        }
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no good open fit exists; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 50.0;
        } else {
            score += 120.0 + (1.0 - fill_ratio) * 200.0;
        }
        // With many open bins, discourage adding more unless necessary.
        score += open_bins_count as f64 * 5.0;
    }

    // Early in the stream, allow slightly more freedom to open bins /
    // spread items; later, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear decay.
    let t = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * t * t;

    // Perfect-fill bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward residuals that pair perfectly with the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score -= 40.0 / (1.0 + gap as f64);
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize residuals too small for the next item (dead space risk).
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as f64 - item_size as f64).abs() < (mean_residual - item_size as f64).abs();
        score += 55.0;
        if good_fit_exists {
            score += 45.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 70.0 * (1.0 - progress);
    }

    // Mild penalty for wasting space in bins whose residual is far above mean.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.15 * dev;
        }
    }

    // Slight preference to fill already-open bins to reduce bin count.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste from post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Quadratic dead-space penalty: large residuals waste capacity quadratically
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Cubic interaction: small residuals near progress end are great fits
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_after = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack_after) * (1.0 - slack_after);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty when many bins open and mean residual is high (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Mild bonus for tighter fits relative to mean residual
    score -= (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks (harmonic-like).
    if post_residual > 0 {
        score -= (bin_capacity as f64) / (post_residual as f64);
    } else {
        score -= 200.0; // perfect fill
    }

    // Penalize dead space: residuals that no typical item can use.
    let dead = if post_residual < 10 && post_residual > 0 { 30.0 } else { 0.0 };
    score += dead;

    // Harmonic class of post_residual: small residuals (<20) are nearly useless.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 40.0 - (gap as f64).min(40.0);
    }
    // If next item cannot fit this bin's residual, mild penalty for wasting space.
    if next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in stream, more open bins exist; opening new bins is cheap then.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins can fit, opening a new one is wasteful.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > 50 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is already below the mean (well-utilized bins).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Modulo-10 harmony: residuals in multiples of 10 are more reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    } else {
        // Perfect fill.
        score -= 25.0;
    }

    // Reward bins whose residual was already small (consolidating near-full bins).
    score += 0.35 * bin_residual as f64;

    // Pressure from open bin count: prefer filling existing bins when many are open.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: when open bins are slack on average, avoid adding slack.
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Early in stream, be more willing to open new bins (spread items); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late, discount early.
        score += 45.0 * progress - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: does the leftover space fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable leftover: reward proportionally to how well next item fills it.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
        } else {
            // Dead space relative to next item: penalize more as it approaches capacity/2.
            let dead = post_residual as f64;
            let half_cap = bin_capacity as f64 * 0.5;
            let dead_penalty = if dead < half_cap {
                18.0 * (dead / half_cap)
            } else {
                18.0
            };
            score += dead_penalty;
        }
    }

    // Compare against mean residual of open bins: prefer bins that end up tighter than average.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 3.0 * mean_gap.max(-50.0).min(50.0) / 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: neutral-ish baseline so it's chosen only over poor fits.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin is fine
        }
    }

    // Slight preference for fewer open bins overall (packing tightness pressure).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual with a convex term.
    let tight = post_residual as f64 / cap;
    score += 0.5 * tight * tight * cap;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // this is a great chain placement; if post_residual is too small for
    // the next item, penalize dead space slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Time horizon: early in the stream, favor opening fresh bins for
    // future flexibility; late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when residuals elsewhere are
        // fragmented or few bins fit the item.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 20.0 * progress - 0.3 * open_bins_count as f64;
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        let _ = fragmentation;
    } else {
        // Prefer bins whose residual deviates below the mean (compact bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer filling larger items into tighter bins (waste-avoidance).
    score += 0.1 * (item_size as f64 / cap) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling: waste penalty grows non-linearly with residual
    // and stream progress (later in the stream, dead space is costlier).
    let waste = norm_post * norm_post * (0.5 + 1.5 * progress);
    score += 40.0 * waste;

    // Reward tight fits: quadratic bonus as post_residual approaches zero.
    let tight = (1.0 - norm_post).powi(3);
    score -= 30.0 * tight * (0.5 + 0.5 * progress);

    // Lookahead coupling: favor bins whose post_residual pairs well with next item.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (norm_post - norm_next).abs();
        score += 15.0 * diff * diff;
        // Perfect lookahead fill bonus
        let pair_fill = (norm_item + norm_next - 1.0).abs();
        score -= 10.0 * (1.0 - pair_fill.min(1.0)) * (1.0 - norm_post);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // but allow early in the stream or when mean residual is high.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 12.0 * (1.0 - progress) * (1.0 - mean_norm);
        score += 8.0 * norm_item;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: reward post_residual in "useful" classes (small, or exactly matching
    // common item sizes via modulo classes of capacity)
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class of post_residual by integer division into capacity fractions
    let class = pr / (cap / 4); // 4 harmonic classes: 0..24,25..49,50..74,75..99
    match class {
        0 => score -= 40.0,           // tiny dead space, great
        1 => score -= 10.0,           // half-ish free, still usable
        2 => score -= 25.0,           // quarter-ish free
        _ => score -= 0.0,            // nearly empty bin used: wasteful
    }

    // Modulo coupling: if post_residual matches a plausible next-item size class, reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: strong reward scaled by tightness
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 60.0 * tightness;
        } else {
            // next item won't fit: penalize if post_residual is a "dead" leftover
            score += 20.0;
        }
        // modulo harmony: post_residual mod 10 near zero means divisible-friendly residual
        let m = post_residual % 10;
        if m == 0 {
            score -= 15.0;
        } else if m >= 5 {
            score += m as f64;
        } else {
            score += m as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // brand new bin: baseline cost plus penalty unless existing fit is bad
        score += 30.0;
        if post_residual < 20 && post_residual > 0 {
            score -= 70.0; // placing here would leave tiny dead space -> prefer new bin
        }
    }

    // Prefer filling bins when many bins are open (reduce fragmentation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // Nudge toward bins with residuals close to item size (tight fit)
    let tight = (bin_residual as f64 - item_size as f64);
    score += tight * 0.1;

    // Mean residual coupling: prefer bins below mean residual (fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 12.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Penalize leaving a gap just below the next item's size (blocks lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 6.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates below the mean (consolidate emptier space).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate handling: an empty bin is only attractive when nothing
    // fits well elsewhere; make it slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * bin_pressure;
        // But if open bins are all nearly full (small mean residual), opening is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Mild late-stream tightening: as the stream progresses, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits with slack; penalize leftover slack after the chain.
            let chain_slack = post_residual - next_item_size;
            score -= 35.0 - (chain_slack as f64) * 0.35;
        } else {
            // Next item does NOT fit here: penalize proportional to how much
            // dead space is stranded relative to the next item.
            let stranded = nxt - post;
            score += stranded * 0.6;
        }

        // Coupling with mean residual: bins that keep post_residual close to
        // the fleet mean are "average" fills; deviating upward (wasteful) is bad.
        let dev = post - mean_residual;
        if dev > 0.0 {
            score += dev * 0.15;
        } else {
            score += dev * 0.05; // slight reward for tighter-than-average fills
        }
    } else {
        // Last item: simply minimize leftover waste.
        score += (post_residual as f64) * 0.5;
    }

    // Dead-space penalty: residuals too small to host any plausible item
    // (items >= 10 in classic setting, >= 1 in general setting) are waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 100.0;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when open bins would strand a lot of dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin, mildly penalized so that
        // decent fits into existing bins win, but rewarded if existing
        // bins would create bad lookahead outcomes.
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin chains perfectly with the next item too.
            score -= 20.0;
        }
        // As stream matures, prefer consolidation into open bins less rigidly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Mild penalty for hoarding too many open bins early (fragmentation).
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (post_residual that is hard to reuse).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score -= 6.0; // tiny slivers are nearly useless
        } else if post_residual >= 10 && post_residual <= 30 {
            score -= 4.0; // usable small pockets
        }
        let _ = dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_tight = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * pair_tight;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        // Bonus if next item exactly fills post_residual
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; grows with how many bins already fit the item.
        let mut new_bin_score = 45.0 + 8.0 * fitting_bins_count as f64;
        // If many open bins have large residuals, discourage opening another.
        new_bin_score += 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score *= 0.7 + 0.6 * progress;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score + post_residual as f64;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Global balance: prefer bins whose residual is near the mean (keep residuals uniform).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 3.0 * poly * cap * 0.1;

    // Reward tight fits (small post residual), stronger as stream advances.
    score -= 2.0 * (1.0 - prn) * (0.5 + progress);

    // Penalize when this bin is the only fitting bin (last chance) — prefer using it.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 2.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual {
        // dead space relative to lookahead item
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Slight preference for bins with residual below mean residual (compact bins).
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "usable" capacity classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity classes: residual near multiples of common item sizes is valuable
    let class = (post_residual / 10) as f64; // integer division threshold class
    score -= class * 0.8;

    // Modulo arithmetic: residuals divisible by small item sizes (10,20,25,50) are reusable
    let m10 = post_residual % 10 == 0;
    let m20 = post_residual % 20 == 0;
    let m25 = post_residual % 25 == 0;
    let m50 = post_residual % 50 == 0;
    if m10 { score -= 3.0; }
    if m20 { score -= 2.0; }
    if m25 { score -= 2.5; }
    if m50 { score -= 4.0; }

    // Perfect fit: zero residual is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: tiny but nonzero residuals are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward leaving room for the next item with a good class
            score -= (next_post / 10) as f64 * 1.5;
            if next_post % 10 == 0 { score -= 2.0; }
            if next_post > 0 && next_post < 10 { score += 8.0; }
        } else {
            // Next item won't fit here: penalize hoarding space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, discourage opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Prefer filling bins when many are open (consolidation pressure)
    score += (open_bins_count as f64).sqrt() * (pr / cap) * 0.5;

    // Mean residual alignment: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to host typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving a residual just below the next item's size (near-miss dead space).
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -10.0 && gap < 0.0 {
                score += 6.0 * (1.0 + gap / 10.0);
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus scaling with number of open bins.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // A new bin is more attractive early in the stream.
        if total_items > 0 {
            score -= 25.0 * (1.0 - step_index as f64 / total_items as f64);
        }
        // New bin is unattractive if the item would fit well in a tight existing bin.
        if item_size >= 90 {
            score += 20.0;
        }
    } else {
        // Mild preference for bins with larger residuals among fitting bins (waste absorption).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
        // Slight penalty per open bin to encourage consolidation.
        score += 0.5 * open_bins_count as f64;
    }

    // Tightness coupling: reward high fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-tightness * 25.0).exp();

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff >= 0 {
            let match_quality = diff as f64 / bin_capacity as f64;
            score -= 30.0 * (-match_quality * 18.0).exp();
        } else {
            // Post-residual too small for next item: mild penalty proportional to waste.
            score += (-diff) as f64 * 0.15;
        }
        // Perfect chain: item + next item exactly fills bin.
        if post_residual as i64 == next_item_size as i64 {
            score -= 45.0;
        }
    } else {
        // Last item: only tightness matters.
        score -= 20.0 * (-tightness * 30.0).exp();
    }

    // Penalize creating dead space far below mean residual (unusable gap).
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // but not if it strands the next item badly
        }
    }

    // New-bin candidate: default score is full capacity residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        } else {
            // discourage opening new bin if some open bin gives a tight fit
            score += 10.0 * (-tightness * 1.0).exp();
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, so subtract for closeness.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible future item
    // (items can be as small as 1, but very tiny residuals are hard to use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space penalty
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly: mild reward scaled by fill ratio
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // next item would not fit here: if post_residual is large, mild penalty
            let waste_potential = post_residual as f64 / bin_capacity as f64;
            score += 3.0 * waste_potential;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits badly everywhere else (large item relative to residuals) or
    // when existing residuals are already small.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a new bin when item is large and won't fit well elsewhere.
        let spread = (mean_residual - post_residual as f64).abs();
        score -= 0.15 * open_bins_count as f64;
        if item_size > 60 {
            score -= 10.0;
        }
        // If mean residual across open bins is small (poor options), new bin is ok.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 12.0;
        }
        let _ = spread;
    }

    // Time horizon: early in the stream, be more conservative with new bins
    // (many future items to pack); late, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress); // early: extra new-bin cost
    } else {
        score -= 5.0 * progress; // late: prefer reusing bins
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins leaving small residuals (tight fits win).
    let mut score = post;

    // Non-linear penalty on wasted fraction, growing with stream progress
    // (late in the stream, dead space is harder to recover).
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward when the next item could fit into the post-residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 15.0 * snug * snug;
        } else {
            // Penalize residuals too small for the next item (likely dead space).
            score += 8.0 * (1.0 - post / nxt);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        score = cap * (0.85 - 0.35 * progress);
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).sqrt();
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Mild normalization pressure: bins far from the mean residual are
    // slightly deprioritized to keep residuals homogeneous.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "perfect fits"
    // for common item sizes are worth more than raw space.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize large dead space that is unlikely to be reused: dead space
    // below the minimum item size is pure loss; above ~half capacity it is
    // likely reusable, so discount it.
    if post_residual < 10 {
        score += 50.0 * (1.0 - cap_frac);
    } else if post_residual > bin_capacity / 2 {
        score -= 15.0 * cap_frac;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // the item grid and are easier to fill exactly later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (perfect pair completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
            // Integer-division threshold: post_residual / next_item_size >= 2
            // means room for two more items later; mildly favorable.
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to
            // how much dead space would be stranded.
            score += 6.0 * (1.0 - cap_frac);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or all open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = item_size as f64 * 0.5 - 25.0 * crowding - 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0; // large items deserve fresh bins
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score -= 0.5 * (open_bins_count.min(50) as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (size 1) are fine, but residuals in the "awkward" band (1..=10) that
    // cannot host typical future items are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 12.0; // creating a gap the next item can't use
        }
    }

    // Tightness reward: fraction of the bin that was actually filled.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins over opening new ones; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good existing fit exists.
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + 4.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Last-chance bonus: this is the only bin that can fit the item.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Prefer bins with residual below mean residual (denser bins).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Slight late-stream bias toward reusing bins to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to lookahead item: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving large unusable fragments (below min item size 1..100 range, anything < ~10 is waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        // new-bin candidate: mild penalty unless it's genuinely better (handled by score magnitude)
        score += 30.0 * (1.0 - progress);
    }

    // Spread load when many bins are open and residuals are large.
    if open_bins_count > 4 && pr > 50.0 && bin_residual != bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize large dead space that nothing reasonable can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0; // still usable for small items
    } else if post_residual >= 60 {
        score += 10.0; // large leftover wastes a mostly-full bin poorly
    }

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize if we leave exactly a gap the next item *almost* fits into.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 10.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residual below mean residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: as stream progresses, be more conservative —
    // discourage opening new bins late, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly over time and with many open bins.
        score += 30.0 + progress * 40.0 + open_bins_count as f64 * 2.0;
        // But allow opening a new bin early or when open bins are all nearly full.
        let avg_usable = mean_residual;
        if avg_usable < item_size as f64 * 0.5 {
            score -= 35.0;
        }
        if progress < 0.2 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight discount grows with progress to consolidate.
        score -= progress * 5.0;
    }

    // Cap open-bin sprawl: when many bins are open, favor filling rather than opening.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // Smooth non-linear coupling: residual waste weighted by stream progress
    score += 2.0 * (pr / cap) * (pr / cap) * (1.0 + progress) * cap;
    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 0.5 * (1.0 - pr / cap).powi(3) * cap * (0.5 + progress);
    // Penalize bins that can't fit the lookahead item (dead space creation)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 0.3 * (nxt - pr) * (1.0 + progress);
        } else {
            score -= 0.2 * (1.0 - ((pr - nxt) / cap).powi(2)) * 10.0;
        }
    }
    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr / cap);
    }
    // Mild penalty when many bins are open (consolidate)
    score += 0.05 * open_bins_count as f64;
    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }
    // Mean-residual deviation: prefer bins near the mean (balance preservation)
    score += 0.1 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 as a "waste class"
    let residue_class = post_residual % 10;
    // Dead space penalty: residuals that are small but nonzero are the worst
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit
    } else {
        // smooth harmonic penalty on residue class
        score += 0.6 * (residue_class as f64) * (residue_class as f64) / 10.0;
    }

    // Fractional capacity coupling: how full the bin becomes
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill; // reward high fill quadratically

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain-friendly: even better if it's a near-perfect chain fit
            let chain_slack = post_residual - next_item_size;
            score -= 12.0 - 0.15 * chain_slack as f64;
        } else {
            // next item won't chain here; penalize moderately
            score += 4.0;
            // if next item is large relative to capacity, prefer conserving big residuals
            if next_item_size >= 50 && post_residual < next_item_size {
                score += 3.0 * (next_item_size - post_residual) as f64 / 50.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // a bad harmonic class or when many bins are open with small residuals
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0);
        if bad_fit {
            score -= 5.0; // opening fresh avoids sliver creation elsewhere
        } else {
            score += 18.0 + pressure * 0.5; // default: prefer existing bins
        }
        // late in stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score -= 8.0 * (1.0 - tightness / bin_capacity as f64).max(0.0);

    // Mean residual coupling: if open bins are on average roomy, use them
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (min size 1..100 unknown, so treat small gaps
    // relative to capacity) are dead space -> heavy penalty.
    let dead_threshold = (bin_capacity as f64 * 0.15).ceil() as u32; // ~15 units
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bins pressure: penalize using an open bin slightly more when many
    // bins are open, to discourage spreading; but opening new bins is handled
    // via the empty-bin candidate below.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive
    // unless the item fits poorly everywhere else / residual would be large.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Large items are fine to start a fresh bin with.
        score -= 0.5 * item_size as f64;
        // If the next item is large too, a fresh bin with big residual is good.
        if next_item_size >= item_size {
            score -= 20.0;
        }
        // Few open bins -> cheaper to open another.
        score -= 3.0 * (10 - open_bins_count.min(10)) as f64;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item is slightly larger than post_residual, mild penalty for
    // leaving a nearly-useful-but-insufficient gap.
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) <= 10 {
        score += 12.0;
    }

    // Early in stream, be more selective (favor tight packing); later, allow
    // looser packing to avoid bin explosion.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits (low dead space).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if fit_ratio < 0.05 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // Next item does not fit: penalize large dead space relative to next item.
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.5 * waste;
        }
    }

    // Penalize bins whose post_residual deviates upward from mean residual
    // (leaving more slack than average is wasteful).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // big items may be better in a fresh bin
        }
    }

    // Slight preference to fill earlier-opened bins (compactness over time).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits: reward chaining placements.
            score -= 3.0 * next_item_size as f64 / bin_capacity as f64;
        } else if post_residual > 0 {
            // Unusable gap for the next item; penalize proportionally to gap size.
            let gap = post_residual as f64;
            score += 2.0 * gap / bin_capacity as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 5 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 0.05 * (post_residual as f64);
    }

    // Many open bins: prefer consolidating into existing bins (avoid bin sprawl).
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when mean residual is high, tolerate looser fits
    // to drain large gaps; when low, demand tight fits.
    score -= 0.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: neutral-ish baseline, chosen only when fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: new bins are cheap; later: prefer existing bins.
        let base = 25.0 + 20.0 * progress;
        // Penalize new bin if the lookahead item is large (fresh bin serves it well though).
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 {
            score = base - 4.0;
        } else {
            score = base;
        }
        // Don't open a new bin when a decent fit exists.
        if fitting_bins_count > 0 && (post_residual as f64) < 0.25 * bin_capacity as f64 && bin_residual != bin_capacity {
            score += 15.0;
        }
    }

    // Time horizon: late in the stream, waste is costlier (no future items to fill gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by stream progress.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: coupling of item_size with post_residual.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize residuals that are too small to ever fit a future item (below min size 1, keep generic).
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - (nx - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins where the item is a larger fraction of the residual.
        score += 6.0 * (1.0 - item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Mild bonus early, penalty late (prefer consolidating as stream progresses).
        score = 30.0 + 60.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins whose residual is near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 5.0 * dev * dev;
    }

    // Smooth interaction: residual^2 * progress * openness coupling.
    score += 10.0 * norm_pr * norm_pr * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class logic: classify post_residual into capacity-fraction classes.
    // Residuals <= 25 are "dead space" (only items <= 25 can use them); penalize.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 25.0; // dead space penalty
        // But if next item can exactly consume it, reward instead.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    } else if post_residual <= half {
        score += 5.0; // mildly awkward class
    } else {
        // Large residual: usable by most items; slight reward.
        score -= 10.0;
    }

    // Modulo-class coupling: item sizes that are divisors of capacity (harmonic sizes)
    // pair well with complementary residuals.
    if bin_residual % item_size == 0 {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual % next_item_size == 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // already sitting in open bins; penalize proportionally.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        // But if the item is large and would leave huge dead space anywhere,
        // a fresh bin may still win; that is handled by other bins' penalties.
    }

    // Prefer filling bins that are already partially committed (fewer open bins).
    score += (open_bins_count as f64) * 0.8;

    // Early in stream, be a bit more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Lookahead: if next item cannot fit this bin after placement, mild penalty
    // unless this bin is the only fitting one.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1..=3)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0 * (4.0 - post_residual as f64);
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits relative to item size.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Penalize leaving a gap just below the next item's need (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        let miss = (next_item_size as u32 - post_residual) as f64;
        score += 8.0 * miss;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones.
    score += 0.35 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 3.0 * fitting_bins_count as f64 };
        score += pressure;
        // A new bin is fine if the item is large and would leave little waste anywhere.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 {
        let pair_sum = item_size + next_item_size;
        if pair_sum == bin_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit here: reward tight coupling.
            let slack_after_pair = post_residual - next_item_size;
            score -= 40.0 - slack_after_pair as f64;
        } else {
            // Next item cannot follow: penalize dead space creation,
            // stronger when post_residual is small (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0;
            } else {
                score += dead * 0.15;
            }
        }
    }

    // Relative to mean residual: bins with residuals near the item size
    // (tight fits) are preferred over loosely filled bins.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += tightness * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of empty bin = C - item_size).
    if bin_residual == bin_capacity {
        let escape_penalty = 150.0 / (fitting_bins_count as f64 + 1.0);
        score += escape_penalty;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
    }

    // Mild reward for consolidating into fewer bins.
    score -= open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Lookahead: if next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item could have fit here only if we place current item poorly; slight penalty.
        score += 3.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item (<=10) are waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 20.0; // but not if it creates near-total waste
        }
    }

    // New-bin candidate: penalize opening a new bin when many bins are open with
    // slack, but allow it when open bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 40.0 - 35.0 * (1.0 - crowding).min(1.0) - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild preference for balancing residuals across open bins.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * std::f64::consts::PI;
    let wave = 0.5 * (1.0 - t.cos());
    let poly = wave * (1.0 - wave);
    score += poly * (pr * pr) / cap * 0.6;

    // Penalize large post-residual more strongly late in the stream
    score += progress * (pr / cap) * (pr / cap) * 12.0;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 4.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Discourage spreading residual mass across many open bins
    score += (open_bins_count as f64).ln() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useless" only mildly,
    // punish mid-range residuals that waste space but still invite fragmentation.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: post_residual == 0 -> perfect fit, strong reward.
    if pr == 0 {
        score -= 60.0;
    }
    // Class B: post_residual is a small "harmonic" remainder (<= 10) -> near-perfect packing.
    else if pr <= 10 {
        score -= 30.0;
    }
    // Class C: mid-band residuals (11..=30): dead-space risk, penalize quadratically.
    else if pr <= 30 {
        score += (pr as f64 - 10.0) * (pr as f64 - 10.0) * 0.08;
    }
    // Class D: large residuals: fine, room remains for future items.

    // Modular harmonic classes: residuals that are multiples of common item granularities
    // (e.g. multiples of 10) are more likely to be exactly consumed later.
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }
    if pr > 0 && pr % 5 == 0 && pr % 10 != 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size as i64 == pr {
            score -= 50.0;
        } else if (pr as u32) >= next_item_size && (pr as u32) - next_item_size <= 10 {
            score -= 15.0;
        } else if (pr as u32) < next_item_size && (pr as u32) > 0 {
            // residual too small for the next item: it becomes dead weight
            score += pr as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin should only win when this item would
    // otherwise create a poor fit. Penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is huge relative to capacity and mean residual is small,
        // a fresh bin may be better: soften the penalty.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 && mean_residual < 15.0 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer bins whose residual deviates from the mean toward tight fits:
    // selecting below-mean-residual bins consolidates space.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Slight preference for bins that fit among many (keep open-bin count stable).
    if fitting_bins_count > 1 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to be useful later
    // (typical items are >= 10, so anything below ~10 is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 6.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gap: partially penalize
        score += (25.0 - post) * 1.5;
    }

    // Reward tight fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post gap,
    // strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= (post - nxt).min(10.0) * 2.0;
        } else {
            // Next item cannot use this residual: mild penalty for blocking
            score += (nxt - post).min(20.0) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; prefer
    // filling existing bins when the fit is decent.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual alignment: prefer bins whose residual is below average
    // (closer to full), leaving larger residuals in emptier bins.
    score += (mean_residual - post).max(-30.0).min(30.0) * 0.5;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (post residual here is large).
    if bin_residual == bin_capacity {
        // Slightly worse than a perfect fit, better than a bad fit.
        score = cap * 0.45 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly/nearly accommodates the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize leaving residual far below the mean (fragmented dead space),
    // reward residuals near the mean which stay reusable.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists, i.e.
    // when current bin fits would leave large waste relative to item size.
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        // Prefer opening a fresh bin for large items or when open bins are crowded.
        score = waste_if_open * 0.6 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // fresh bin can also chain the next item
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only usable bin
        }
    }

    // Early in the stream, be slightly more willing to open bins (better packing later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: strongly reward tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // chain fit quality
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last chance: strongly prefer the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is expensive; discourage unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual < 20 {
            score += 15.0; // wasteful to open a bin for a small item
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Mild penalty for spreading across too many bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Base: prefer tight fits via non-linear dead-space penalty
    let dead = pr / cap;
    score += 40.0 * dead * dead;

    // Is this the new-bin candidate?
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        // Penalize opening a new bin; relax as stream progresses
        let mut open_penalty = 25.0 + 15.0 * (1.0 - progress);
        // If very few bins fit the item, opening may be necessary
        if fitting_bins_count <= 1 {
            open_penalty -= 30.0;
        }
        // If next item is large, a fresh bin is valuable
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            open_penalty -= 12.0;
        }
        score += open_penalty;
    } else {
        // Reward using existing bins, especially best-fit-like placements
        score -= 8.0 * (1.0 - dead);
        // Last-chance bonus: avoid wasting the only fitting bin
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward residual closeness to mean (keeps bin profile balanced)
        score += 0.05 * (pr - mean_residual).abs();
        // Lookahead: if next item fits exactly in the post residual, strong reward
        if next_item_size > 0 {
            let gap = (pr - next_item_size as f64).abs();
            score -= 10.0 * (1.0 - gap / cap).max(0.0);
        }
        // Late stream: consolidate more aggressively
        score -= 6.0 * progress * (1.0 - dead);
    }

    // Mild open-bin count pressure: discourage bin proliferation
    score += 0.3 * open_bins_count as f64 * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" classes
    // (multiples of small divisors of capacity) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Class A: post_residual exactly 0 -> perfect fit, strong reward.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Class B: post_residual divisible by 4 or 5 -> likely reusable by small items.
        if pr % 4 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 3.0; }

        // Dead-space class: tiny leftovers (1..=3) are nearly unusable -> penalize.
        if pr < 4 {
            score += 12.0;
        }
    }

    // Integer-division threshold classes on post_residual relative to capacity.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac <= 0.1 {
        score += 8.0; // sliver
    } else if frac <= 0.25 {
        score -= 1.0;
    } else if frac <= 0.5 {
        score -= 2.5;
    } else {
        score -= 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.05;
            // harmonic match: next item divides post_residual nicely
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally to dead space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so that
    // it only wins when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 8.0; // next item is large: a fresh bin pairing is fine
        }
    }

    // Stream progression: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    }

    // Slight tie-break toward bins below mean residual (denser bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, this is
    // an excellent chaining opportunity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 15.0;
            } else {
                score += slack * 0.3;
            }
        } else {
            // Next item cannot follow here; slightly penalize.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are already open; discourage it unless the fit into open bins is bad.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let fit_quality = (bin_capacity - item_size) as f64;
        score = 200.0 + pressure * 10.0 - fit_quality * 0.5;
        if fitting_bins_count == 0 {
            score -= 250.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to
    // encourage consolidation into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tighter-than-average fit, slightly favor it.
    let residual_diff = mean_residual - post_residual as f64;
    score += residual_diff * 0.2;

    // Slight time-decay: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Penalize residuals that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight packing relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and the item fits decently.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.4 * waste;
        // If item is large, new bin is more acceptable.
        if item_size >= 50 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Mild reward for filling bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a mild convex penalty.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 25.0;
        } else if nxt <= pr {
            // next item fits: leftover after next placement
            let pr2 = pr - nxt;
            score -= 12.0 * (1.0 - pr2 / bin_capacity as f64);
        } else {
            // next item will not fit here: mildly penalize creating small residuals
            score += 4.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits even more
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: penalize opening new bins when many bins are already open
    // with slack (mean_residual high) — encourage consolidating into open bins.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let consolidation_pressure = (mean_residual / bin_capacity as f64) * (1.0 + 2.0 * (open_bins_count as f64).ln());
        score += 18.0 + 20.0 * consolidation_pressure + 10.0 * (1.0 - progress);
        // If item exactly fits a fresh bin and nothing else helps, allow it.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If no open bin fits at all, new bin is necessary; soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Time horizon: later in the stream, be greedier about tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // Penalize leaving residuals that are awkward (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: reward small post_residual, non-linearly (quartic tightening).
    let mut score = pr * pr * pr * pr / (cap * cap * cap);

    // Smooth polynomial coupling with stream progress: later in the stream,
    // waste matters more, so amplify the residual penalty.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += progress_coupling * (pr / cap).powi(3) * 40.0;

    // Interaction: post_residual vs mean_residual — prefer bins whose leftover
    // stays near the mean (keeps residuals uniform and reusable).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + progress);

    // Perfect-fit bonus (smooth, not piecewise).
    score -= 25.0 * (-pr as f64 / 8.0).exp();

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 10.0).exp();
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate penalty: opening a new bin is costly unless the current
    // item would leave a large awkward residual in every open bin.
    if bin_residual == bin_capacity {
        let new_bin_score = 70.0 + 30.0 * progress;
        // Compare against typical fit quality: if placing elsewhere would waste
        // a lot (post_residual large), new bin becomes attractive.
        score = new_bin_score - (pr as f64 / cap) * 20.0
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    // Mild penalty for proliferating bins early.
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into granularity classes
    let class = (post_residual / 10) as f64; // integer division threshold on post_residual
    score += class * 2.5; // prefer bins whose leftover falls into a LOW class (smaller leftover bucket)

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize leftover that is unusable for typical item sizes (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Modulo-arithmetic harmony: does post_residual pair well with common item sizes?
    // If next item could exactly fill the leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot fit here; slight penalty if this bin would be skipped anyway
            score += 3.0;
        }
        // Harmonic residue: leftover divisible into chunks of next_item_size
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: residual == capacity. Prefer keeping it closed unless
    // existing fits are poor (high mean residual waste) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (mean_residual - item_size as f64).max(0.0);
        score = 55.0 + waste * 0.4 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a bin
        }
    }

    // Mild preference to fill bins that are already well-used (reduce bin count pressure)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Tie-break: favor bins with residual close to mean (balance load)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are "dead space" — penalize them super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely unusable sliver
        } else {
            // Decay usable-ness: smaller usable residual => larger penalty
            score += (10.0 / post_residual as f64) * 25.0;
        }
    } else {
        // Perfect fill is heavily rewarded
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: discourage scattering into many bins
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when it helps the next item
    // or when all existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Lookahead: opening a fresh bin is good if next item is large
        // (it will leave a large residual that suits big items).
        if next_item_size > 0 {
            let next_fits_now = (bin_residual as i64 - item_size as i64 - next_item_size as i64) >= 0;
            if next_fits_now {
                score -= 35.0; // next item fits here too: open bin is fine
            }
            if next_item_size >= 60 {
                score -= 15.0; // big next item likes fresh space
            }
        }
        // If existing bins fit poorly (high mean residual spread vs item),
        // opening a new bin is less bad.
        let wasted_elsewhere = mean_residual - item_size as f64;
        if wasted_elsewhere > 30.0 {
            score -= 20.0;
        }
    } else {
        // Placing into an existing bin that can also host the next item is great
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
        // Avoid blocking: if post_residual is positive but smaller than next item,
        // and next item is large, mildly penalize (we strand the space).
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Late in the stream, consolidate: prefer existing bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 8.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — placing here is efficient consolidation.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 35.0;
    }

    // Dead space penalty: residual too small for any plausible item (min size 1, but small slivers are wasted).
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean_r {
        score -= 0.5 * (mean_r - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_r);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only if current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: slightly above average so tight fits win.
        score += 8.0;
        // But if this bin would be the only fitting one, opening fresh is bad.
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
        // If lookahead matches a fresh bin split nicely (item + next item <= capacity), encourage fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && (bin_residual as u64) < item_size as u64 + next_item_size as u64 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 3 {
        score -= 0.05 * open_bins_count as f64 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit with the next item (k=2 lookahead).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Reward near-perfect lookahead fit.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= (10.0 - slack) * 1.5;
        }
    }

    // Penalize large dead space non-linearly (wasted capacity grows super-linearly).
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64 * 4.0);

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so an open bin with decent fit is preferred.
        score += 30.0;
        // If many bins can fit, strongly discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0 + 5.0 * (fitting_bins_count as f64);
        }
        // If this is the only fitting bin, opening a new bin is acceptable:
        // reward slightly so last-chance bins with bad fit lose out.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Later in the stream, prefer consolidating (fewer open bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Last-chance bin: strong reward to use it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Reward bins whose residual is below mean (tight bins get filled first).
        score -= (mean_residual - bin_residual as f64) * 0.3;

        // Reward small residuals being consumed fully.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for spreading across too many open bins when item is large.
    if item_size > bin_capacity / 2 && open_bins_count > 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: tight fit rewarded quadratically (small post_residual => low score).
    let mut score = 2.0 * x * x - 1.5 * x;

    // Non-linear coupling: tight fits become more valuable as stream progresses.
    let coupling = (1.0 - progress) * (x * x) - progress * (x * x * x);
    score += 3.0 * coupling;

    // Penalize awkward residuals unlikely to be filled later (near-mid dead space).
    let dead = (x - 0.5) * (x - 0.5);
    score += 0.8 * dead * (0.5 + progress);

    // Lookahead: reward if next item fits into post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx <= x {
            score -= 1.2 * (1.0 - (x - nx)) * (1.0 - progress * 0.5);
        } else {
            score += 0.4 * (nx - x);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    let spread = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 0.3 * spread * (x - mean_residual / cap).abs();

    // New-bin candidate: only attractive when no good fit exists (large x on fresh bin means item small; prefer using existing tight fits).
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are worse
    // than the raw number suggests. Treat gaps < 10 as nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness bonus: fraction of residual consumed by this item
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: prefer reusing existing bins over opening new ones.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how bad the mean residual of open bins is (waste already accumulated).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * mean_residual;
        // If the next item could pair with this item's leftover, a new bin is fine.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) super-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 55.0; // perfect 2-chain
        } else if diff > 0 && (diff as u32) <= 10 {
            score -= 30.0 * (1.0 - diff as f64 / 10.0); // next item still fits snugly
        } else if diff < 0 {
            // next item won't fit here; penalize leaving dead space that is too small to be useful
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0 * (10.0 - dead);
            }
        }
        // Coupling with mean residual: prefer bins whose post_residual stays near mean
        score += 0.15 * ((post_residual as f64 - mean_residual).abs());
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
        // If nothing else fits well, opening a new bin is fine: reduce penalty when
        // this bin would otherwise be a bad home (large post_residual).
        if post_residual as f64 > 0.5 * cap {
            score -= 30.0;
        }
    }

    // Slight progression term: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small awkward gaps are still acceptable
    }
    if post_residual > bin_capacity / 2 {
        score += 10.0 * (post_residual as f64 / bin_capacity as f64 - 0.5);
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this gap: penalize proportionally to wasted space
            score += 8.0 * (1.0 - (next_item_size - post_residual).min(bin_capacity) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer filling bins with low mean residual (nearly-full bins) over fresh ones.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (many fitting bins -> keep using them).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 25.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 20.0 * progress;
        // If the item is large and would leave a big gap in an open bin, new bin is fine.
        let gap_if_open_bin = (bin_capacity.saturating_sub(item_size)) as f64;
        new_bin_penalty -= 10.0 * (gap_if_open_bin / bin_capacity as f64);
        score += new_bin_penalty;
    }

    // Mild preference to balance across many open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: residual scaled by capacity, shaped by progress
    let x = pr / cap; // normalized post-residual in [0,1]
    let t = progress;

    // Base polynomial shaping of post-residual: penalize tiny dead space more
    score += 12.0 * (1.0 - x) * (1.0 - x) * x * t;

    // Reward tight fits smoothly (small post-residual), stronger later in stream
    let tight = 1.0 - x;
    score -= 18.0 * tight * tight * (0.5 + 0.5 * t);

    // Penalty for leaving residual that mismatches future item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let mismatch = (x - nx).abs();
        score += 8.0 * mismatch * mismatch * (1.0 - t);
        // Reward when post-residual exactly accommodates next item
        let cover = if x >= nx { 1.0 - (x - nx) } else { 0.0 };
        score -= 10.0 * cover * cover * nx;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer filling existing
    let crowd = open_bins_count as f64;
    score -= 2.0 * (mean_residual / cap) * (crowd / (crowd + 4.0));

    // New-bin candidate: smooth penalty growing with stream progress
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * t * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 bands.
    // Residuals in [0,9] are "dead" (no item fits since min size 1..100 unknown,
    // but small residuals are hard to fill) -> penalize them.
    let dead_band = post_residual % 10;
    if post_residual <= 10 {
        score -= 15.0; // near-perfect fit reward
    } else if dead_band <= 2 {
        score += 12.0; // tiny unusable sliver penalty
    } else if dead_band >= 8 {
        score -= 4.0;  // close to next decade boundary, likely refillable
    }

    // Integer-division thresholds: how many "average" items still fit.
    let avg_item = mean_residual.max(1.0);
    let slots = (post_residual as f64 / avg_item).floor();
    score -= slots * 2.5;

    // Fraction-of-capacity harmonic classes on post_residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score -= 8.0;      // tight packing reward
    } else if frac > 0.7 {
        score += 5.0;      // wasteful large leftover
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        } else {
            // next item cannot use this bin's leftover anyway: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or we are early with few bins (harmonic restart heuristic).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.55;
        let base = 30.0 + 20.0 * progress;
        if bad_fit || open_bins_count == 0 {
            score -= 40.0;
        } else {
            score += base;
        }
    }

    // Mean-residual divergence: prefer bins whose leftover stays near the mean
    // (balanced packing keeps future options open).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins among many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small-ish gap: mildly risky, only useful if next item fits it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 12.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when the lookahead item exactly consumes the resulting gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current item leaves a large
    // awkward gap elsewhere or open-bin pressure is high.
    if bin_residual == bin_capacity {
        score -= 8.0 * (open_bins_count as f64 / 10.0);
        // Penalize opening a new bin if a decent fit exists.
        if post_residual >= 10 && fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early stream: prefer filling existing bins.
        if step_index as f64 / (total_items.max(1) as f64) < 0.5 {
            score += 10.0;
        }
    }

    // Open-bin pressure: mild penalty for spreading across many bins.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for bins below mean residual (keeps balance).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Aggressive 2-step lookahead: if the next item fits the post_residual,
    // this placement is highly desirable — subtract a bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra bonus if next item fills the bin nearly exactly after two placements.
        let two_step_residual = (post_residual - next_item_size) as f64;
        score -= (1.0 - two_step_residual / bin_capacity as f64) * 20.0;
    }

    // Penalize post_residual that is small but nonzero (dead space unusable for
    // typical items): a residual below the minimum item size is pure waste.
    if post_residual < 1 {
        score -= 40.0; // perfect fill, best outcome
    } else {
        score += 10.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(2);
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post_residual is closer to (or below) the mean, keeping balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening new bins as stream progresses and bin count grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64);
        // But if no existing bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for earlier bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement: reward high fill.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize post_residual relative to mean residual: creating dead space
    // larger than the average open residual is wasteful.
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving small unusable gaps.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.25 * gap * (1.0 - step_index as f64 / total_items.max(1) as f64);
            }
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins score worse.
        score += 25.0;
        // More open bins => prefer reusing an existing bin even more.
        score += 2.0 * open_bins_count as f64;
        // Early in the stream, opening fresh bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If item is small relative to capacity, a fresh bin wastes potential.
        score += 10.0 * (1.0 - fill);
    }

    // Mild reward for tightening nearly-full bins (post_residual small).
    if post_residual <= 10 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight preference for bins with larger residual among equals keeps
    // small-residual bins reserved for small items.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on unusable dead space: residuals too small for typical
    // future items are quadratically costly, scaled by stream progress.
    let dead = (pr / cap).powi(2) * (1.0 + progress) * cap;

    // Smooth reward for tight fits: post_residual near zero gets extra subtraction.
    let tight = ((pr / cap) * std::f64::consts::PI).cos() * cap * 0.5;

    // Lookahead coupling: penalize if the next item cannot use the post residual.
    let lookahead_penalty = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        (gap / cap).powi(2) * cap * 0.8
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 { cap * 1.5 } else { 0.0 };

    // Mild penalty for spreading across many open bins vs. consolidating load.
    let spread = (open_bins_count as f64).ln() * (pr / cap) * 4.0;

    // New-bin candidate: an empty bin has no waste yet; make it moderately
    // attractive unless an open bin gives a very tight fit.
    let is_new = bin_residual == bin_capacity;
    let new_bin_bonus = if is_new { cap * 0.35 + progress * cap * 0.15 } else { 0.0 };

    score = pr + dead - tight + lookahead_penalty - last_chance + spread + new_bin_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize waste quadratically, but soften large residuals.
    score = score * score / bin_capacity as f64 + post_residual as f64 * 0.5;

    // Harmonic class of the post residual: residuals divisible into nice
    // chunks (mod 10) are more reusable than ragged ones.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 12.0; // perfectly aligned residual -> very reusable
    } else if mod10 <= 3 {
        score -= 4.0;
    } else if mod10 >= 7 {
        score += 4.0; // ragged sliver -> dead space risk
    }

    // Integer-division thresholds: classify residual into usable slots.
    let slots = post_residual / 10;
    score += (10 - slots.min(10)) as f64 * 0.8;

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = post_residual - next_item_size;
        score -= 15.0 - (next_waste as f64) * 0.6;
        if next_item_size == post_residual {
            score -= 10.0; // perfect pair
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: leftover likely dead
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer tightening existing ones.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mean-residual coupling: if this bin is tighter than average, prefer it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item would leave a large ragged residual elsewhere.
    if bin_residual == bin_capacity {
        score = 18.0 + (item_size as f64) * 0.15;
        if fitting_bins_count <= 2 {
            score -= 10.0; // few alternatives -> opening a bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
