pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;

    // Base: penalize wasted space, super-linear to punish dead space.
    let mut score = post * (1.0 + 0.015 * post / cap);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - post / resid.max(1.0);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item can use the post_residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            // Perfect lookahead fit is very valuable.
            let nx_fit = 1.0 - (post - nx) / cap;
            score -= 10.0 * nx_fit;
        } else {
            // Post-residual too small for next item: mild penalty for stranded space.
            score += 2.0 * (nx - post) / cap;
        }
    } else {
        // Last item: any residual is pure waste; strongly prefer tightest bin.
        score += 5.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, more so when many bins are open
        // (fragmentation) and early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 0.3 * open_bins_count as f64 + 8.0 * (1.0 - progress);
        // But if post_residual would be very small (item nearly fills a fresh bin),
        // opening a new bin is actually great.
        if post <= 5.0 {
            score -= 25.0;
        }
    } else {
        // Slight bonus for using bins that are already below-average residual
        // (consolidate fullness, keep emptier bins flexible).
        if resid < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0 * (resid - mean_residual) / cap;
        }
    }

    // Mild preference late in stream to close out bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer minimal post-residual, with non-linear tightening late in stream.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for awkward residuals (near half-capacity dead space).
    let awkward = (pr - 0.5).abs();
    score += 20.0 * awkward * awkward * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual small relative to item).
    score -= 15.0 * fit * fit * (1.0 - pr);

    // Lookahead coupling: reward if next item can use the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = (post - nx) / cap;
            score -= 12.0 * (1.0 - waste) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr);
    } else if fitting_bins_count > 1 {
        // Mild reward for spreading load when many bins fit.
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize unless open bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            ((cap - mean_residual) / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = cap * (1.1 - 0.35 * pressure) + 10.0 * (1.0 - progress);
        // If only this new bin can take the item, make it attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual matches the fleet mean.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions.
    // Dead space that is a multiple of small "harmonic" units is more reusable.
    let harmonic_units: [u32; 5] = [2, 5, 10, 20, 25];
    let mut harmony_bonus = 0.0;
    for (i, &u) in harmonic_units.iter().enumerate() {
        if post_residual % u == 0 && post_residual > 0 {
            harmony_bonus += (i as f64 + 1.0) * 2.0;
        }
    }
    score -= harmony_bonus;

    // Penalize awkward mid-range residues (odd, prime-adjacent dead space).
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Integer division thresholds: post_residual bucketed by quarter capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 5.0; // tiny dead space, bin nearly wasted
    } else if post_residual <= 2 * quarter {
        score -= 2.0; // sweet spot: room for medium items
    }

    // Lookahead coupling: reward if next item fits exactly or snugly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect fill for next item
        } else if next_item_size <= post_residual {
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + snug / 10.0);
        } else {
            // next item cannot fit here: mild penalty scaled by overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 40.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item justifies a fresh bin
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // good "garbage collector" bin; reward using it.
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=15) are wasted space.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was large relative to mean (tight packing candidates).
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * fit_tightness;

    // Reward filling bins that are already mostly full (small residual before placement).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio.min(1.0);

    // Open-bin pressure: with many open bins, discourage spreading; favor closing bins out.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: leftover likely becomes dead space.
        score += 12.0;
    }

    // New-bin candidate logic: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if no open bin fits well (large post residual or many open bins), allow it.
        if post_residual >= 40 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Slight bonus for reusing an existing bin as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nr).abs();
        if nr <= pr {
            // Next item fits exactly into this bin's leftover: strong reward.
            let tightness = 1.0 - (match_gap / bin_capacity as f64);
            score -= 18.0 * tightness * tightness;
        } else {
            // Next item would not fit here: mild penalty scaled by overshoot.
            score += 0.35 * (nr - pr);
        }
    }

    // Prefer near-full bins (small post_residual relative to capacity).
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Compare against mean residual: avoid bins far above the average leftover
    // unless the fit is tight (item fills most of the residual).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fit_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist and fit well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 20.0 + 3.0 * fitting_bins_count as f64;
        }
        // Early in the stream, new bins are cheaper; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight preference to balance load across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional waste: prefer bins whose residual is nearly consumed.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Tight fits are gold: reward small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus if this bin could still serve the next item too.
            let chain_fit = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_fit as f64 / bin_capacity as f64);
        } else {
            // Dead space: residual too small for next item.
            let dead = post_residual as f64;
            score += 12.0 * (dead / 50.0).min(1.0) * (dead / (next_item_size.max(1) as f64)).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: discourage spreading; prefer compacting into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) / 10.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Mean residual context: if this bin's residual is far below the mean,
    // it is an outlier bin; finishing it off is good.
    let residual_gap = mean_residual - post_residual as f64;
    score -= 8.0 * (residual_gap / 100.0);

    // New-bin candidate penalty: opening a new bin must be clearly worse than
    // any reasonable fit unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin early when few bins are open and fit is poor anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / cap;
    let prog = progress * (1.0 - progress); // peaks mid-stream

    // Dead-space penalty grows non-linearly for small post_residuals, scaled by progress
    score += prog * (prn * prn - 2.0 * prn + 1.0) * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - progress) * (prn * prn) * cap * 0.3;
    score -= progress * (prn * prn * prn) * cap * 0.6;

    // Last-chance bonus: strongly favor the only fitting bin, modulated by progress
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Penalize bins far from mean residual (prefer uniformity), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: reward leaving space close to next item size (smooth Gaussian-like)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (-40.0 * d * d).exp();
    }

    // Mild penalty on opening new bins when many are open and item fits well elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: treat small post_residuals as valuable dead-space classes
    let pr = post_residual;
    if pr <= 10 {
        score -= 60.0; // near-perfect fit: very desirable
    } else {
        // modulo classes on post_residual (harmonic residue classes)
        let class = pr % 10;
        if class == 0 {
            score -= 15.0; // divisible class: leaves room for small items
        } else if class >= 7 {
            score += 8.0; // awkward residue class
        }
    }

    // Penalize large wasted space relative to capacity fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // penalize blocking a large next item
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 30.0;
        // but attractive if current item is large and would fragment an open bin badly
        if item_size >= 50 && post_residual < 20 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score -= 20.0;
        }
    }

    // Stream progression: slightly prefer consolidating into fewer bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (mean_residual - post_residual as f64).max(0.0) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical items are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is "dead space".
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize leaving a large-ish gap that blocks it.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized via
    // its large initial post_residual, but add explicit pressure on new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 5.0 + 0.25 * open_bins_count as f64 + 10.0 * progress;
        score += pressure;
        // New bin is attractive only if the item is large relative to capacity.
        score -= 20.0 * fill;
        // If no open bin fits at all, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins when many are open.
        score -= 0.05 * open_bins_count as f64;
        // Slight preference for bins with residuals below the mean (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residual too small to ever fit any item (min size 1)
    if post_residual == 0 {
        score -= 60.0; // perfect fit is best
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // 2-step lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact chain match strongly favored
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 40.0 - 0.5 * gap;
            if gap == 0.0 {
                score -= 30.0; // perfect 2-chain
            }
        } else {
            // cannot host next item: mild penalty scaled by shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall.min(50.0);
        }
    }

    // Tightness: favor bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Compare residual against mean residual: prefer below-average-residual bins
    // (consolidation) unless it's a new empty bin.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.2 * diff;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and open bins are crowded (residuals mostly small).
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64;
        score += 15.0 - 40.0 * (1.0 - crowdedness) * (item_size as f64 / bin_capacity as f64);
        // late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight bonus for keeping number of open bins low when many are open
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale dead-space penalty by how "unusable" the leftover is.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score += (1.0 - tightness) * (post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Consuming space the next item could have used directly: mild penalty.
            score += 4.0 * (next_item_size as f64 / 100.0);
        }
        // Perfect chaining: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already relatively empty compared to fleet mean.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * tightness;

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        let many_open = open_bins_count > 4;
        if !poor_fit || many_open {
            score += 30.0;
        }
        // If next item is large and this bin would stay nearly full, new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score -= 12.0;
        }
    }

    // Mild penalty proportional to open bins count to encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: waste matters more as stream advances.
    score += 30.0 * progress * norm_pr * norm_pr;

    // Reward filling a bin nearly completely (post_residual near zero).
    score -= 12.0 * (1.0 - norm_pr).powi(4);

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 + 0.5 * (nxt - pr);
        } else {
            // Smooth reward when next item fits well into the remaining space.
            score -= 4.0 * (1.0 - ((pr - nxt) / cap)).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins, less so when existing fits are bad.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 20.0 + 2.0 * open_f.sqrt();
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early in stream, opening bins is cheaper.
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference to balance residuals across open bins.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (1/8 granularity)
    let item_class = (item_size * 8) / bin_capacity;
    let next_class = (next_item_size * 8) / bin_capacity;

    // Reward tight fits: post_residual in low harmonic classes
    let post_class = (post_residual * 8) / bin_capacity;
    score -= (bin_capacity as f64 / (post_residual + 1) as f64) * 0.5;

    // Penalize dead space: post_residual too small to hold a plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic pairing bonus: if next item fits exactly into post_residual (same class residue)
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 / (pair_waste as f64 + 1.0)) * 1.5;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Modulo coupling: reward when item_class and post_class are complementary (sum to 8)
    if item_class + post_class >= 8 {
        score -= 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins whose residual is below mean (fill the emptiest-feeling tight bins)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Integer-division threshold on post_residual: waste classes
    let waste_band = post_residual / 15;
    score += waste_band as f64 * 3.0;

    // New-bin candidate: penalize mildly unless current bins are very tight
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // Early in stream, exploring new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Small tie-break against many open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // (tiny gaps) are heavily penalized with a superlinear term.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) superlinearly.
    let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Lookahead: strongly favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // creates a gap the next item cannot use
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer compacting when many bins are open.
    score += 3.0 * open_bins_count as f64;

    // Mild attraction toward bins with residuals close to item size (best-fit shaping).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // New-bin candidate: penalize so it is chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward when post_residual can host next item exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: post_residual becomes dead space
            score += 15.0 * (1.0 - post_residual as f64 / next);
        }
        // match against mean residual structure
        if mean_residual > 0.0 {
            let rel = post_residual as f64 / mean_residual;
            score += (rel - 1.0) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += open_bins_count as f64 * 0.5;

    // Early stream: mild preference for opening new bins to build flexibility
    score -= (1.0 - progress) * 5.0;

    // Penalize brand-new bin slightly unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        if big > 0.6 { score -= 10.0; } else { score += 12.0 - 15.0 * big; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual: dead space created by this placement
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac; // superlinear penalty on unusable leftovers

    // Reward tight fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible; reward proportionally to how well it fills
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_fill;
        } else if next_item_size <= bin_residual {
            // Next item fits before placement but not after: mild penalty for blocking
            score += 6.0;
        }
        // Dead space too small for next item is wasted space
        if post_residual < next_item_size && post_residual < 10 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual close to item size (minimize fragmentation)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Global state coupling: when many bins are open, favor consolidation into
    // bins below mean residual (pack fuller bins first to close them out)
    if open_bins_count > 0 {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive early in the stream
    // or when this placement would leave a large dead space in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin; decreases with progress (less room to waste later)
        let mut new_bin_cost = 30.0 - 15.0 * progress;
        // If current item nearly fills a bin, opening is great
        if item_size >= bin_capacity * 8 / 10 {
            new_bin_cost -= 20.0;
        }
        // If many open bins exist, prefer spreading less
        new_bin_cost += 0.5 * open_bins_count as f64;
        // If no other bin fits well, new bin is cheap
        if fitting_bins_count == 0 {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - t) + prn * t * t;
    score += 12.0 * poly;

    // Reward tight fits, scaled by progress
    let tight = 1.0 - prn;
    score -= 18.0 * tight * tight * (0.5 + t);

    // Lookahead: reward if next item can use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let waste = pr - nxt;
            score -= 8.0 * (1.0 - waste / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: penalize alternatives when only this bin fits
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize scattering when many bins open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Mild alignment with mean residual
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: prefer opening fresh bins early, discourage late
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but weight it non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Harmonic class: post_residual bucketed by capacity fractions (dead-space classes).
    // Residuals in (0, 10] are nearly unusable (min item 1..100 unknown, but small
    // items are rare-ish); residuals in (10, 25] are "half-dead".
    let dead = if post_residual == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post_residual <= 10 {
        15.0
    } else if post_residual <= 25 {
        8.0
    } else {
        0.0
    };
    score += dead;

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how much of post_residual the next item consumes
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * use_ratio;
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a decent fit (post_residual small).
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight preference when many open bins are fragmented
        score = 35.0 + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item benefits from fresh capacity
        }
    }

    // Stream progression: late in the stream, be greedier about tight fits
    // (less future to plan for), damp lookahead influence.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it's a "filler" bin — filling fragmented bins is good.
    let res_gap = mean_residual - bin_residual as f64;
    if res_gap > 0.0 {
        score -= 0.3 * res_gap.min(50.0);
    }

    // Modulo harmonic classes on post_residual: residuals congruent to small
    // multiples of 10 pair well with common item sizes.
    let class = post_residual % 10;
    if class == 0 && post_residual > 0 {
        score -= 5.0; // round residuals are reusable
    } else if class >= 8 {
        score += 3.0; // awkward leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (< 10, the minimum item size) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 10 {
        // Perfect fit, zero dead space: strong reward.
        score -= 40.0;
    }

    // Non-linear dead-space penalty: small gaps that only fit tiny items are wasteful.
    if post_residual >= 1 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward leaving residual that can host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gaps that cannot fit the next item are likely dead.
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Tightness reward: bins whose residual is close to item_size are good fits.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin fits well, allow opening (soften when item is large).
        if item_size > 50 {
            score -= 20.0;
        }
    }

    // Progress-based mild adjustment: early stream, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mean residual coupling: if mean residual across open bins is low, prefer new bin.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residuals that are too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits into post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra bonus if next item fills bin exactly after this placement.
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // Post-residual too small for next item: mild penalty proportional to waste.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins -> discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if mean residual across open bins is low (bins nearly full),
        // opening a new bin is more reasonable.
        score -= 0.3 * mean_residual;
        // Early in stream, allow new bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer filling bins with larger residuals when many bins are open (balance).
    if !new_bin_candidate && open_bins_count > 1 {
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space)
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fills less aggressively; late, penalize waste more
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Cubic interaction: small post residual is extra valuable as stream advances
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - nxt / cap) * (0.5 + progress);
        } else {
            score += 5.0 * nxt / cap;
        }
    }

    // Slight preference for keeping bin count low: favor fuller bins when many bins open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near/below mean (balance)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish, slightly penalized so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fraction classes
    // class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Integer-division thresholds: which lookahead items could fill the leftover?
        // Reward if the next item exactly fills the post_residual (harmonic pairing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 35.0; // perfect chain fill
            } else if next_item_size <= post_residual {
                // next item fits, but leaves another residual: evaluate chain quality
                let chain_post = post_residual - next_item_size;
                if chain_post < 10 {
                    score -= 18.0; // near-perfect two-item chain
                } else {
                    // modular arithmetic: does chain_post fall in a "useful" small class?
                    let useful = chain_post % 10; // sizes 1..100, multiples of 10 common
                    score -= (10 - useful.min(10 - useful)) as f64 * 0.5;
                }
            } else {
                // next item cannot use this residual: dead space risk
                score += 6.0;
            }
        }

        // Penalize residuals that are "dead zones": too small for the smallest item (1..100 unknown,
        // assume small items ~ size 10 exist but be distribution-agnostic via modulo classes)
        let r = post_residual;
        if r < 10 {
            score += 8.0; // tiny unusable sliver
        }

        // Capacity-fraction harmonic classes: residuals near common fractions of C
        // are more likely to be filled by future items of harmonic sizes.
        let frac = r as f64 / cap;
        if (frac - 0.5).abs() < 0.02 {
            score -= 5.0; // half-full residual is attractive
        } else if (frac - 0.25).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
            score -= 3.0;
        }

        // Modulo class of post_residual relative to capacity: prefer residuals that are
        // multiples of common small divisors (2,4,5,10) -> more splittable.
        let div_bonus = ((r % 2 == 0) as i32 + (r % 5 == 0) as i32 + (r % 10 == 0) as i32) as f64;
        score -= div_bonus * 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        // base penalty to prefer reusing open bins
        score += 30.0 + 3.0 * open_bins_count as f64;
        // if the item is large relative to capacity and few bins fit it, new bin is fine
        if item_size as f64 > 0.7 * cap && fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference to balance residuals: bins far below mean residual are
    // already "used up"; prefer bins with residual close to item need.
    let target = mean_residual - item_size as f64;
    score += 0.15 * (post_residual as f64 - target).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.3 * (post_residual - next_item_size) as f64;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (5.0 + 10.0 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make empty bins less attractive unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.4;
        // Late in the stream, opening new bins is more acceptable.
        score -= 30.0 * progress;
    } else {
        // Mild alignment with mean residual: prefer bins whose residual is close to typical.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the remaining space: mild reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Next item won't fit here: penalize leaving a gap that is nearly-but-not usable.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare against mean residual: bins far below mean residual are "wasted" bins;
    // placing here consumes their slack efficiently.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize opening new bins when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
        // But if next item is large and would leave this new bin well-used, soften.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Small penalty for very large dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // near-perfect packing bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Nonlinear penalty for small-but-nonzero dead space (unusable slivers).
        if post_residual < 10 {
            score += 25.0 - 2.5 * post_residual as f64;
        }
        // Reward leaving residuals that can accommodate typical future items.
        let usable = (post_residual as f64 / 10.0).floor() * 10.0;
        score -= usable * 0.05;
    }

    // Lookahead: strongly prefer bins whose leftover fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.3 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, penalize opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when few bins fit well (fragmentation pressure).
        if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - 1.0 / (fitting_bins_count as f64 + 1.0));
        }
        // Attractive when open bins are already crowded (low mean residual).
        score -= 0.4 * (mean_residual - post_residual as f64).max(0.0);
        // Late in the stream, avoid spreading items across many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Very large items are fine to place in a fresh bin.
        if item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
    } else {
        // Mild reward for filling existing bins rather than opening new ones.
        score -= 5.0;
        // Prefer bins with residual close to item (best-fit bias beyond raw post_residual).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.08 * tightness;
    }

    // Global balance: if many open bins, slightly prefer consolidating into fuller ones.
    if open_bins_count > 4 {
        score -= 0.5 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (ni - pr) / cap * (1.0 + progress);
        } else {
            score -= 4.0 * (1.0 - (ni - pr).abs() / cap) * progress;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += 3.0 * (fit - 1.0);
    }

    // Prefer bins with residuals below the mean residual (consolidate slack)
    let dev = mean_residual - pr;
    score -= 6.0 * dev / cap;

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral base slightly above good fits, cheaper early
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress + 0.1 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: treat post_residual by capacity fractions / integer division.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left as dead space

    // Penalize dead space super-linearly but with harmonic-class buckets.
    // Class boundaries at capacity/8 intervals (12, 25, 37, 50, 62, 75, 87).
    let class = post_residual / (bin_capacity / 8 + 1);
    score += (class as f64) * (class as f64) * 4.0;

    // Small post_residual (< 10, the minimum item size) is dead space: extra penalty
    // unless it's a perfect fit (already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the remainder.
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 80.0 * fill;
        } else {
            // Next item cannot use the remainder: mild penalty scaled by leftover size.
            score += 10.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes (bin_capacity - item_size) of
    // potential packing. Only prefer it when all fits would leave huge dead space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: the space that will remain after placing item.
        score = (bin_capacity - item_size) as f64 * 1.5;
        // Early in the stream, cheap to open bins (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score *= 1.0 - 0.3 * (1.0 - progress);
        // If many open bins already have large residuals, discourage new bin.
        score += (mean_residual / cap) * 40.0;
        // If next item could pair with current item in this fresh bin, bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0;
        }
    } else {
        // Existing bin: slight preference for bins whose residual is close to mean
        // (keeps bin residuals balanced), plus reward for using large residual bins.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
        // Reward filling bins that are already mostly full (consolidation).
        let used_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= 20.0 * used_frac;
    }

    // Modulo harmonic class on item_size: items in "nice" classes (dividing capacity)
    // pack well; prefer bins where post_residual stays in a friendly class.
    let friendly = |r: u32| r % 10 == 0 || r % 25 == 0 || r % 50 == 0;
    if post_residual > 0 && friendly(post_residual) {
        score -= 15.0;
    }
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 20 {
        score += 20.0; // awkward small remainder
    }

    // Late in stream: tighten up, avoid spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit is always excellent
    }

    // Reward tight fits relative to bin size (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 40.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let lookahead_bad = next_item_size > 0 && next_item_size as f64 > mean_residual;
        if open_bins_count == 0 || (fragmentation < 0.25 && (fitting_bins_count == 0 || lookahead_bad)) {
            score -= 20.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 2.0; // prefer filling existing bins
        }
    }

    // Lookahead coupling: if this bin's post residual fits the next item, reward it.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < 10 {
        score += 8.0; // residual too small even for next item => dead space
    }

    // Late-stream consolidation: as stream progresses, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Remaining space still usable by the next item: reward closeness of the fit.
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-gap / 25.0).exp();
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: dead space penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.3 * gap;
    }

    // Compare leftover against mean residual of open bins.
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight bias against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin by the current item
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportionally to how much of the bin gets used
    score -= 12.0 * fill * fill;

    // Penalize large dead space nonlinearly (dead space that cannot host typical items)
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.15 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving a residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 4.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // no open bin fits or the fit in open bins is very poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let baseline_penalty = 45.0 + 10.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No alternative: opening a new bin is fine, remove the penalty
            score -= baseline_penalty;
        } else {
            // Only open a new bin if the best alternative would waste a lot
            let waste_threshold = 0.35 * bin_capacity as f64;
            let poor_fit = mean_residual - item_size as f64 > waste_threshold;
            if poor_fit {
                score -= baseline_penalty * 0.8;
            } else {
                score += baseline_penalty;
            }
        }
    }

    // Mild preference to consolidate into emptier bins when many bins are open
    if !is_new_bin {
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Late-stream: discourage leaving many tiny residuals scattered
    score += progress * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p = progress;
    let poly = norm_post * norm_post * (1.0 + p) + norm_post * (1.0 - p) * (1.0 - p);
    score += 2.5 * poly * bin_capacity as f64 * 0.1;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (1.0 + 2.0 * p) * 8.0;

    // Penalize dead space relative to mean residual of open bins.
    let dead = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dead * (0.5 + p);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 * (1.0 + p);
    }

    // New-bin candidate: penalize mildly unless residual would be very small
    // or existing fits are poor; also penalize opening bins late.
    if is_new_bin {
        score += 6.0 * (1.0 - p) + 10.0 * p;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0; // new bin can also host the next item
        }
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let slack_fit = 1.0 - ((post_residual as f64 - nx) / bin_capacity as f64);
            score -= 4.0 * slack_fit * (0.5 + p);
        } else {
            score += 0.05 * (nx - post_residual as f64);
        }
    }

    // Slight preference to spread load when many bins are open.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * norm_post * bin_capacity as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: subtract for small post_residual (scaled).
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space is post_residual that
    // cannot accommodate the next item (or typical small items).
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 30 };
    if post_residual > 0 && post_residual < min_useful {
        // Dead space penalty grows as stream progresses (less time to recover).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 30.0 * progress;
    }

    // Perfect closure bonus: filling a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when a good fit exists among open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin score ~ residual of fresh bin minus discount for crowding.
        score = post - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Prefer new bin only if mean residual across open bins is low (poor fits).
        score += (mean_residual - 15.0).max(0.0) * 1.5;
        // Late in stream, prefer reusing open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Slight preference for bins with residual close to mean (balance load).
        score += ((bin_residual as f64) - mean_residual).abs() * 0.3;
    }

    // Modulo-class bonus: post_residual in {0} or >= next item is reusable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10, the minimum item size) are pure waste: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for the lookahead item are also weak (soft penalty).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 12.0;
    }
    // Perfect fill is the ideal outcome: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // --- Tightness bonus: reward high fill ratio of the bin ---
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // --- Open-bin pressure ---
    // With many open bins, prefer consolidating into existing bins (penalize new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive on poor fits elsewhere.
        score += 55.0 + 1.5 * pressure;
    } else {
        // Existing bins get a mild discount that grows with bin pressure.
        score -= 0.5 * pressure;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Mean residual coupling: bins deviating far below mean residual are already tight;
    // prefer them slightly to balance residual distribution. ---
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Mild early-stream exploration: be less picky early, stricter later.
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    score -= 0.5 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 30.0;

    // 2-step lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            // reward when next item leaves a still-usable remainder
            let r2 = post_residual - next_item_size;
            score -= 25.0 * (r2 as f64 / bin_capacity as f64);
        } else {
            // penalize dead space that next item cannot use
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is very small.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow opening a new bin late in the stream if current fit is bad
        if post_residual as f64 > 0.25 * bin_capacity as f64 {
            score += 20.0;
        }
    }

    // Late in the stream, prefer filling bins as fully as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residual.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 12.0;

    // Dead-space penalty for residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 6.0;
        } else {
            score += 2.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: default mild penalty; open a fresh bin
    // only when existing bins would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste = mean_residual - item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // fresh bin useful for next item too
        }
        if waste > 30.0 {
            score -= waste * 0.4;
        } else {
            score += 14.0;
        }
        // Early in the stream, prefer consolidating into open bins.
        score += (1.0 - t) * 8.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage filling.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, non-linearly (quadratic + cubic)
    let mut score = pr + 20.0 * norm_pr * norm_pr + 10.0 * norm_pr.powi(3);

    // Smooth coupling of post_residual with stream progress:
    // early on, be greedy with tight fits; later, tolerate spread
    let progress_coupling = (1.0 - progress) * norm_pr * norm_pr * 40.0
        + progress * norm_pr * 15.0;
    score += progress_coupling;

    // Penalize large dead space relative to mean residual (waste indicator)
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Perfect fit reward (smooth, via normalized residual)
    score -= 30.0 * (1.0 - norm_pr).powi(4) * (item_size as f64 / cap);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-gap / 15.0) * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement (harmonic class on capacity fractions)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit reward: post_residual in small harmonic classes {0,1,2}
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Integer division thresholds: dead space unusable for typical small items (1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // dead space zone
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, stronger if it nearly fills again
            let next_post = post_residual - next_item_size;
            score -= 8.0 + 10.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            if next_post <= 2 {
                score -= 10.0; // chain of near-perfect fits
            }
        } else {
            // next item won't fit here: penalize leaving a large but unusable gap
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so open bins are usually preferred
        score += 35.0;
        // if the item would leave a bad residual in any bin, opening fresh is fine
        if post_residual >= 10 && fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size >= bin_capacity / 2 {
            score -= 10.0; // big items pair well in fresh bins
        }
    }

    // Modulo arithmetic on post_residual: harmonic residue classes
    let r = post_residual % 10;
    score += match r {
        0 => -4.0,          // round residue, reusable by decile-sized items
        1 | 2 => -2.0,
        8 | 9 => 2.0,
        _ => 0.0,
    };

    // Stream progression: later in stream, tighten up (less willing to leave medium gaps)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln();
        if bin_residual < bin_capacity {
            score -= 3.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize heavily as post_residual shrinks into dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fits are excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residuals that no future item can plausibly use (below min size 1 is
    // impossible, but tiny gaps under 10 are statistically near-dead for 1..100 items).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += 0.8 * (20.0 - gap);
    }

    // Open-bin pressure: prefer compacting into fewer bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean residual (balanced filling);
    // penalize outliers that would strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly reward using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // If next item cannot fit here after placement, mild penalty (bin becomes idle).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream or when open
        // bins are numerous and fragmented.
        score += 30.0 - 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        }
        // penalize residuals that can't fit the next item at all
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        score -= 5.0; // last item: just fill tightly
    }

    // Reward bins whose residual is below mean (tighter packing)
    score += (mean_residual - post_residual as f64) * 0.6;

    // Penalize large dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // nearly full bin is great
    }
    if post_residual > bin_capacity as f64 * 0.4 {
        score += 6.0; // leaving too much space
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // no tight fit is possible elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.55 + progress * 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // room for a chain
        }
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count > 0 {
            score += 12.0; // prefer fitting existing bins
        }
    }

    // Slight bonus for spreading load when many bins are open
    score -= (open_bins_count as f64).ln() * 0.4 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fit (small post_residual already does this); add non-linear waste penalty
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // penalize leaving post_residual too small for next item
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 30.0 * gap;
        }
    }

    // Perfect-fill reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 70.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        if open_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        return new_bin_score;
    }

    // Prefer bins whose residual deviates from mean (consolidate fragmented space)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins early on
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial waste penalty: dead space punished super-linearly.
    let x = (pr / cap).clamp(0.0, 1.0);
    score += 18.0 * x * x * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 10.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Penalize bins whose post_residual can't hold the lookahead item (wasted pairing),
    // but reward when lookahead fits exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = ((pr - nx) / cap).clamp(0.0, 1.0);
            score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            let gap = ((nx - pr) / cap).clamp(0.0, 1.0);
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - x);
    }

    // Discard near-empty usage: avoid spreading load across many bins.
    let fill = 1.0 - x;
    score -= 4.0 * fill * fill * (open_bins_count as f64).ln();

    // New-bin candidate: penalize mildly unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    // Coupling with mean residual: prefer bins deviating from mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near multiples of
    // common item sizes (10, 20, 25, 50) are "usable" dead space.
    let pr = post_residual;
    let mut usable_bonus = 0.0;
    for m in [10u32, 20, 25, 40, 50] {
        let r = pr % m;
        if r == 0 && pr > 0 {
            usable_bonus += m as f64 * 0.4;
        } else if r <= 2 {
            usable_bonus += m as f64 * 0.1;
        }
    }
    score -= usable_bonus;

    // Exact / near-exact fit reward.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Fractional fill of the bin: reward high fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that just barely fails the next item.
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += gap * 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (pristine empty bin): only attractive when open bins
    // have poor residuals relative to the item, or stream is early.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 45.0;
        if mean_gap < 0.0 {
            new_bin_score -= (-mean_gap) * 0.5;
        } else {
            new_bin_score += mean_gap * 0.3;
        }
        if open_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        new_bin_score -= progress * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Mild penalty for proliferating bins with large mean slack.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item are pure waste. Penalize sharply when the gap is
    // tiny but nonzero (unusable), while rewarding near-perfect fits.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongest reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable micro-gap: heavy penalty scaled by how tiny it is.
        score += (10 - post_residual) as f64 * 8.0;
    } else {
        // Usable gap: mild quadratic penalty to prefer larger, flexible gaps.
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 10.0;
    }

    // Reward bins whose residual tightly matches the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 5.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheap so the new-bin candidate competes.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 0.8 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin gets a baseline score equal to
    // its full residual, plus a fixed opening cost. It should only win when
    // every open bin would create a nasty dead space or the stream is young
    // and future flexibility matters.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // opening a fresh bin leaves a fully usable gap
        }
        // Early in the stream, flexibility is valuable: make new bins cheaper.
        score -= (1.0 - progress) * 15.0;
    } else if post_residual >= 10 && next_item_size > 0 && post_residual >= next_item_size {
        // This bin can also host the lookahead item: reward chaining.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill
    if post > 0.0 && post < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward when next item fits the post residual exactly/well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap);
            if (gap as u32) == 0 {
                score -= 20.0; // perfect 2-chain
            }
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Compare against mean residual of open bins: prefer bins below mean residual (tighter bins)
    score += 0.5 * (post - mean_residual).max(-20.0).min(20.0) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when this bin would leave a bad residual
    // and other bins are congested
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 25.0;
        // but if placing in an existing bin would leave a large awkward residual,
        // opening a fresh bin becomes relatively better
        if next_item_size > 0 && post < next_item_size as f64 {
            score -= 10.0;
        }
        if post > 60.0 {
            score -= 5.0; // fresh bin has plenty of room for future items
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative anyway
        }
    }

    // Mild pressure against bin sprawl late in the stream
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose residual after placement can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space if residual is too small to ever be useful.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Opening a new bin is more acceptable early or when open bins are mostly full.
        score += 30.0 - 10.0 * pressure / 10.0 - 5.0 * progress;
        // If the item nearly fills an empty bin, opening is attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Mild preference for bins below mean residual (keeps balance).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * (1.5 * norm_pr - 0.8) + (progress * progress) * (0.6 - 1.2 * norm_pr));

    let mut score = poly * cap;

    // Reward tight fits, more strongly later in the stream
    score -= (cap - pr) * (0.1 + 0.25 * progress);

    // Penalize leaving dead space that no plausible next item can use
    if next_item_size > 0 && next_item_size as f64 > pr {
        score += (next_item_size as f64 - pr) * (0.3 + 0.4 * progress);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and residual is far below mean (fragmentation)
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // Discard near-full bins slightly to keep them for tiny items
    if norm_pr < 0.05 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by large powers reward tight packing
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // modulo classes: post_residual % 10 dead-space classes
        let class = pr % 10;
        score += (class as f64) * 1.7;
        // harmonic tiers via integer division thresholds
        if pr <= 10 { score -= 25.0; }
        else if pr <= 20 { score -= 12.0; }
        else if pr <= 30 { score -= 4.0; }
        else if pr >= 70 { score += 15.0; } // wasteful large leftover
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0 + 0.15 * (next_item_size as f64);
            // harmonic match: next divides residual nicely
            if pr % next_item_size.max(1) == 0 { score -= 10.0; }
        } else {
            let gap = (next_item_size - pr) as f64;
            score += 0.25 * gap.min(40.0);
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 2.0 * (open_bins_count as f64);
        // still allow new bin if item is huge and would leave tiny residual elsewhere
        if item_size >= bin_capacity * 9 / 10 { score -= 55.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 15.0; }
    }

    // mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small unusable dead space: heavily penalize.
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Dead space is worse late in the stream when less room to recover.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 + 2.0 * progress) * 10.0;

    // If next item fits in the post residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but mildly encourage consolidation when few bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (better packing).
    score += 0.4 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits: low post_residual is good.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        if gap == 0.0 {
            score -= 40.0; // perfect chaining of two items
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow here: penalize dead space relative to next item.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize wasting a large residual on a small item when other bins fit.
    if fitting_bins_count > 1 {
        score += 8.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it competitive only when open bins are tight.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 + 10.0 {
            score -= 20.0; // open bins are nearly full; opening fresh is good
        }
    }

    // Mild preference to balance residuals toward the mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: penalize if next item cannot fit in the post residual
    // (wasting residual capacity), reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // chain fit: both fit snugly
            if post_residual - next_item_size < 10 {
                score -= 4.0;
            }
        } else {
            score += 5.0;
            // residual too small to ever be useful for typical items
            if post_residual < 5 {
                score += 8.0;
            }
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter ones even more
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else {
            // penalize opening new bin when alternatives exist,
            // unless mean residual is very fragmented
            score += 12.0;
            if mean_residual < 15.0 {
                score -= 6.0;
            }
            if open_bins_count > 20 {
                score += 4.0; // too many open bins already
            }
            // early in stream, consolidating is cheaper
            score += 5.0 * (1.0 - progress);
        }
    }

    // Slight preference to fill bins with larger residual (drain big holes)
    // only when item is small relative to residual.
    if (item_size as f64) < 0.4 * bin_residual as f64 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear penalty on residual, amplified as stream progresses
    score += prn * prn * (1.0 + progress) * 30.0;
    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - prn) * (1.0 - prn) * (0.5 + progress) * 20.0;

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins with residual close to item (good fit) via smooth coupling
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= (1.0 - diff / cap) * 12.0 * (1.0 - progress);
        if pr >= nx && pr - nx <= 10.0 {
            score -= 8.0;
        }
    }

    // Discourage opening new bins when many open with usable mean residual
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        score += mean_residual * 0.1 * (1.0 - progress);
    }

    // Mild regularization coupling with mean residual
    score += (prn - mean_residual / cap) * (prn - mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small residue class
    // is nearly useless; residues that could pair with common item sizes are fine.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small post_residual is excellent (tight fit) -> reward.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Dead-space penalty: quadratic growth of wasted residual.
    score += 0.08 * pr * pr / cap;

    // Harmonic classes: post_residual divisible by common size classes (10, 20, 25, 50)
    // leaves room that typical items (multiples of 5/10) can still use.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        // Odd residues are hard to fill -> penalize.
        score += 4.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Bonus if post_residual - next_item_size lands on a tight class.
            let r2 = post_residual - next_item_size;
            if r2 <= 5 { score -= 8.0; }
            if r2 % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here; mildly penalize leaving big unusable gap.
            score += (next_item_size as f64 - pr).min(30.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer reusing open bins when fit is decent,
    // but open a new bin when the only fits are terrible.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; discourage when a good existing fit exists.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        // If mean residual across open bins is large, reuse is better.
        if mean_residual > item_size as f64 + 15.0 {
            score += 20.0;
        }
    }

    // Progressive pressure: as stream advances, keep bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Many open bins with low mean residual -> consolidate (favor this bin more if tight).
    if open_bins_count > 4 {
        let gap = (mean_residual - pr).max(0.0);
        score += 0.1 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // a future item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero relative to bin size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Penalize bins whose residual is already small (aging bins with little
    // usable space get deprioritized in favor of roomier bins).
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Open-bin pressure: discourage opening too many bins.
    score += 3.0 * open_bins_count as f64;

    // Lookahead coupling: if the next item fits in this bin's post_residual,
    // reward; if next item would fit but post_residual barely misses, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it unattractive unless open bins are crowded
    // or this bin would be a near-perfect fit anyway.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for bins whose residual is close to mean residual
    // (keeps bin residuals balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space, more so when it cannot fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * post_residual as f64;
        }
    }

    // Lookahead matching: reward when post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness;

    // Penalize wasting a large residual on a small item.
    let waste_ratio = item_size as f64 / bin_residual as f64;
    score += 40.0 * (1.0 - waste_ratio);

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = mean_residual < item_size as f64 * 1.2;
        score += if big_item > 0.7 || poor_fit { -150.0 } else { 250.0 };
    } else {
        // Prefer bins whose residual deviates favorably from the mean.
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: encourage keeping bins compact for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that next item could use: if post_residual < next_item_size,
    // the leftover is likely wasted.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            score += 12.0 * (nx - post_residual as f64) / cap;
        } else {
            // Bonus when next item fits perfectly into the resulting residual.
            let gap = post_residual as f64 - nx;
            if gap < 8.0 {
                score -= 10.0 * (1.0 - gap / 8.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives: slight penalty for wasting a scarce-fit bin.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in stream, prefer keeping residuals balanced/flexible;
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 - mean_residual).abs() / cap;

    // Bin count pressure: when many bins open, discourage spreading; when few, allow it.
    if open_bins_count > 4 {
        score += 1.5 * (open_bins_count as f64).ln() * (post_residual as f64) / cap;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: make it unattractive unless the item fits terribly everywhere.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * (1.0 - (item_size as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on post_residual (dead space), normalized by capacity
    let x = post / cap;
    let mut score = post * (1.0 + x * x);

    // Smooth stream-progress coupling: later in stream, penalize waste more aggressively
    score *= 1.0 + 0.8 * progress * x;

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= 25.0 * (-post / 12.0).exp();

    // Lookahead: if next item can fit into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (next_item_size as f64 / post) * (1.0 - progress * 0.5);
    }
    // Penalize leaving residual that is too small for the next item (unusable sliver)
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post {
        score += 6.0 * (1.0 - post / (next_item_size as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for bins with residuals below the mean (consolidating waste)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure against proliferating bins early
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * x;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = post * (1.0 + x * x) + 8.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large powers of 2
    // or landing on "nice" fractions of capacity are more reusable.
    let pr = post_residual as u32;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 50 == 0 { class_bonus += 6.0; }
        else if pr % 25 == 0 { class_bonus += 4.0; }
        else if pr % 10 == 0 { class_bonus += 3.0; }
        else if pr % 5 == 0 { class_bonus += 1.5; }
        // power-of-two friendliness
        if pr % 32 == 0 { class_bonus += 2.0; }
        else if pr % 16 == 0 { class_bonus += 1.0; }
        else if pr % 8 == 0 { class_bonus += 0.5; }
        // dead-space band: residuals too small for typical items (<=9) are wasted
        if pr < 10 { class_bonus -= 12.0; }
        else if pr < 20 { class_bonus -= 4.0; }
    } else {
        class_bonus += 15.0; // perfect closure
    }
    score -= class_bonus;

    // Coupling with the lookahead item: reward leaving room for next_item_size,
    // penalize leaving a residual just barely unable to fit it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            let slack = post_residual as f64 - n;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            let miss = n - post_residual as f64;
            if miss <= 10.0 {
                score += 6.0 * (1.0 - miss / 10.0); // near miss: painful dead space
            }
        }
    }

    // Fractional tightness: strong reward for high fill ratio of this placement.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // penalize new bin when existing bins are reasonably empty on average
        score += 10.0 + 20.0 * (1.0 - fragmentation) + 10.0 * progress;
        if fitting_bins_count == 0 { score -= 25.0; } // no alternative: must open
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing big items into fresh bins is fine
        }
    }

    // Mild penalty for accumulating many open bins with mediocre residuals.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64);
    }

    // Small tie-break noise via harmonic phase of step index (deterministic).
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any residual that is too small to hold even
    // the smallest plausible item is pure waste. Penalize it super-linearly.
    if post_residual > 0 {
        // Fraction of the bin wasted by this placement.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        // Sharpen penalty when the gap is tiny (likely unusable dead space).
        if post_residual < 10 {
            score += 25.0 * (1.0 - waste_frac) * (10.0 - post_residual as f64);
        } else {
            score += 2.0 * waste_frac * waste_frac * bin_capacity as f64;
        }
    }

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that still accommodate the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0;
        if slack == 0 {
            score -= 12.0; // chains perfectly into next item
        } else if slack < 10 {
            score += 5.0; // leaves a new tiny dead gap for the future
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // This placement creates a gap the next item cannot use.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, using it avoids
    // opening a new bin — reward strongly unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual < 10 && post_residual > 0 {
            score -= 5.0;
        } else {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Opening a new bin is acceptable early in the stream or when existing
        // bins are nearly full on average (mean_residual small).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if mean_residual > 0.7 * bin_capacity as f64 || progress < 0.05 {
            score -= 40.0; // existing bins too full to be useful -> open new bin
        }
    } else {
        // Existing bin: slight preference for fuller bins (smaller residual).
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Encourage packing into bins that are already heavily loaded.
        score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Mild global pressure: more open bins -> favor any existing-bin placement.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining: bin fully consumed over two steps
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            // penalize by the dead space remaining after the lookahead item
            score += leftover_after_next as f64 * 0.6;
            // small bonus for tight fits
            score -= 5.0;
        } else {
            // next item cannot follow in this bin: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.5 {
            score -= 6.0 * (0.5 - rel); // leaving less slack than average is good
        } else {
            score += 4.0 * (rel - 0.5).min(2.0); // excessive slack vs peers is wasteful
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer the tightest fit
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well (post_residual would be large dead space) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = pr; // an empty bin used now keeps 100 - item_size unused
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // prefer new bin when open bins are crowded (low mean residual) or few options exist
        let open_penalty = 25.0 * pressure + 10.0 * progress;
        score = waste + open_penalty;
        if fitting_bins_count == 0 {
            score -= 50.0; // forced: nothing else fits
        }
    }

    score
}
